local function getBootstrapBaseDir()
    if type(getWorkingDirectory) == "function" then
        local ok, path = pcall(getWorkingDirectory)
        if ok and type(path) == "string" and path ~= "" then
            return tostring(path)
        end
    end
    return "."
end

local function getBootstrapLogDirCandidates()
    local baseDir = getBootstrapBaseDir()
    return {
        string.format("%s\\moonloader\\logs", baseDir),
        string.format("%s\\logs", baseDir),
        "logs",
        "."
    }
end

local function getBootstrapMarkerPath()
    local candidates = getBootstrapLogDirCandidates()
    for _, dirPath in ipairs(candidates) do
        local markerPath = string.format("%s\\tools logs.current", tostring(dirPath))
        local file = io.open(markerPath, "a")
        if file then
            file:close()
            return markerPath
        end
    end
    return "tools logs.current"
end

local function readBootstrapMarker()
    local file = io.open(getBootstrapMarkerPath(), "r")
    if not file then
        return nil, nil
    end
    local path = tostring(file:read("*l") or "")
    local ts = tonumber(file:read("*l") or "")
    file:close()
    if path == "" then
        return nil, ts
    end
    return path, ts
end

local function writeBootstrapMarker(path)
    local file = io.open(getBootstrapMarkerPath(), "w")
    if not file then
        return false
    end
    file:write(tostring(path or "") .. "\n")
    file:write(tostring(os.time() or 0) .. "\n")
    file:close()
    return true
end

local function buildBootstrapLogPath()
    local stamp = os.date("%Y-%m-%d_%H-%M-%S")
    local baseDir = getBootstrapBaseDir()
    local existingPath, existingTs = readBootstrapMarker()
    local nowTs = os.time() or 0
    if existingPath and existingTs and math.abs(nowTs - existingTs) <= 300 then
        local probe = io.open(existingPath, "a")
        if probe then
            probe:close()
            writeBootstrapMarker(existingPath)
            return existingPath
        end
    end

    local candidates = {
        string.format("%s\\moonloader\\logs\\tools logs_%s.txt", baseDir, stamp),
        string.format("%s\\logs\\tools logs_%s.txt", baseDir, stamp),
        string.format("logs\\tools logs_%s.txt", stamp),
        string.format("tools logs_%s.txt", stamp)
    }

    for _, path in ipairs(candidates) do
        local file = io.open(path, "a")
        if file then
            file:close()
            writeBootstrapMarker(path)
            return path
        end
    end

    return candidates[#candidates]
end

BOOT_LOGGER = rawget(_G, "BOOT_LOGGER") or {}
BOOT_LOGGER.path = BOOT_LOGGER.path or buildBootstrapLogPath()
BOOT_LOGGER.buffer = BOOT_LOGGER.buffer or {}

function BOOT_LOGGER.write(message)
    local line = string.format("[%s] [BOOT] %s", os.date("%Y-%m-%d %H:%M:%S"), tostring(message or ""))
    table.insert(BOOT_LOGGER.buffer, line)

    local file = io.open(BOOT_LOGGER.path, "a")
    if file then
        file:write(line .. "\n")
        file:close()
    end

    if type(print) == "function" then
        print("[BOOT] " .. tostring(message or ""))
    end
end

