local function safeRequire(moduleName)
    -- crash fix: preserve boot trace if a required MoonLoader dependency is missing.
    local ok, result = pcall(require, moduleName)
    if ok then
        return result
    end
    BOOT_LOGGER.write(string.format("Require failed: %s -> %s", tostring(moduleName), tostring(result)))
    error(string.format("Failed to require %s: %s", tostring(moduleName), tostring(result)))
end

