local _u8_native = encoding.UTF8

local function _is_valid_utf8_text(value)
    if type(value) ~= "string" then
        return false
    end
    local i = 1
    while i <= #value do
        local b1 = value:byte(i)
        if not b1 then
            return false
        elseif b1 <= 0x7F then
            i = i + 1
        elseif b1 >= 0xC2 and b1 <= 0xDF then
            local b2 = value:byte(i + 1)
            if not b2 or b2 < 0x80 or b2 > 0xBF then
                return false
            end
            i = i + 2
        elseif b1 >= 0xE0 and b1 <= 0xEF then
            local b2 = value:byte(i + 1)
            local b3 = value:byte(i + 2)
            if not b2 or not b3 or b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF then
                return false
            end
            i = i + 3
        elseif b1 >= 0xF0 and b1 <= 0xF4 then
            local b2 = value:byte(i + 1)
            local b3 = value:byte(i + 2)
            local b4 = value:byte(i + 3)
            if not b2 or not b3 or not b4 or b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF or b4 < 0x80 or b4 > 0xBF then
                return false
            end
            i = i + 4
        else
            return false
        end
    end
    return true
end

local function _u8_call(value)
    if type(value) ~= "string" then
        return value
    end
    if value == "" or _is_valid_utf8_text(value) then
        return value
    end

    if type(_u8_native) == "table" then
        local mt = getmetatable(_u8_native)
        if mt and type(mt.__call) == "function" then
            local ok, result = pcall(mt.__call, _u8_native, value)
            if ok and result ~= nil then
                return result
            end
        end
    elseif type(_u8_native) == "function" then
        local ok, result = pcall(_u8_native, value)
        if ok and result ~= nil then
            return result
        end
    end

    return value
end

local _u8_proxy = {}
if type(_u8_native) == "table" then
    for k, v in pairs(_u8_native) do
        _u8_proxy[k] = v
    end
end
setmetatable(_u8_proxy, { __call = function(_, value) return _u8_call(value) end })
u8 = _u8_proxy

