ReconnectManager = {
    active = false,
    reconnectAtMs = 0,
    delaySec = 0
}

local RECONNECT_GAMESTATE_WAIT_CONNECT = 1
local RECONNECT_GAMESTATE_DISCONNECTED = 5

function ReconnectManager.cleanupUiState()
    if type(sampIsDialogActive) == "function" and type(sampCloseCurrentDialogWithButton) == "function" then
        local okDialog, dialogOpen = pcall(sampIsDialogActive)
        if okDialog and dialogOpen then
            pcall(sampCloseCurrentDialogWithButton, 0)
        end
    end

    if type(sampTextdrawIsExists) == "function" and type(sampTextdrawDelete) == "function" then
        for i = 0, 2304 do
            local okExists, exists = pcall(sampTextdrawIsExists, i)
            if okExists and exists then
                pcall(sampTextdrawDelete, i)
            end
        end
    end
end

function ReconnectManager.start(delaySec)
    local delay = math.max(1, math.floor(tonumber(delaySec) or 0))
    if type(sampSetGamestate) ~= "function" or type(sampDisconnectWithReason) ~= "function" then
        local message = "Reconnect unavailable: SA-MP reconnect functions topilmadi."
        if LogManager and LogManager.system then
            LogManager.system("[RECONNECT] " .. message)
        end
        return false, message
    end

    ReconnectManager.delaySec = delay
    ReconnectManager.reconnectAtMs = RuntimeGuard.getNowMs() + (delay * 1000)
    ReconnectManager.active = true

    local okDisconnect, disconnectErr = pcall(function()
        ReconnectManager.cleanupUiState()
        sampSetGamestate(RECONNECT_GAMESTATE_DISCONNECTED)
        sampDisconnectWithReason(0)
    end)

    if not okDisconnect then
        ReconnectManager.active = false
        local message = "Reconnect disconnect phase failed: " .. tostring(disconnectErr or "unknown")
        if LogManager and LogManager.system then
            LogManager.system("[RECONNECT] " .. message)
        end
        return false, message
    end

    local message = string.format("Reconnect scheduled in %ds.", delay)
    if LogManager and LogManager.system then
        LogManager.system("[RECONNECT] " .. message)
    end
    return true, message
end

function ReconnectManager.update()
    if not ReconnectManager.active then
        return
    end

    if RuntimeGuard.getNowMs() < tonumber(ReconnectManager.reconnectAtMs or 0) then
        return
    end

    ReconnectManager.active = false
    local okConnect, connectErr = pcall(sampSetGamestate, RECONNECT_GAMESTATE_WAIT_CONNECT)
    if LogManager and LogManager.system then
        if okConnect then
            LogManager.system("[RECONNECT] Reconnect triggered.")
        else
            LogManager.system("[RECONNECT] Reconnect trigger failed: " .. tostring(connectErr or "unknown"))
        end
    end
end

