Crypto = {}

local _bit = rawget(_G, "bit")
local _bit32 = rawget(_G, "bit32")

local band, bor, bxor, rshift, lshift

if _bit and type(_bit.band) == "function" then
    band = _bit.band
    bor = _bit.bor
    bxor = _bit.bxor
    rshift = _bit.rshift
    lshift = _bit.lshift
elseif _bit32 and type(_bit32.band) == "function" then
    band = _bit32.band
    bor = _bit32.bor
    bxor = _bit32.bxor
    rshift = _bit32.rshift
    lshift = _bit32.lshift
else
    local function mask32(x)
        return x % 4294967296
    end

    band = function(a, b)
        a = mask32(a)
        b = mask32(b)
        local res = 0
        local bitval = 1
        for _ = 0, 31 do
            local aa = a % 2
            local bb = b % 2
            if aa == 1 and bb == 1 then
                res = res + bitval
            end
            a = (a - aa) / 2
            b = (b - bb) / 2
            bitval = bitval * 2
        end
        return res
    end

    bor = function(a, b)
        a = mask32(a)
        b = mask32(b)
        local res = 0
        local bitval = 1
        for _ = 0, 31 do
            local aa = a % 2
            local bb = b % 2
            if aa == 1 or bb == 1 then
                res = res + bitval
            end
            a = (a - aa) / 2
            b = (b - bb) / 2
            bitval = bitval * 2
        end
        return res
    end

    bxor = function(a, b)
        a = mask32(a)
        b = mask32(b)
        local res = 0
        local bitval = 1
        for _ = 0, 31 do
            local aa = a % 2
            local bb = b % 2
            if aa ~= bb then
                res = res + bitval
            end
            a = (a - aa) / 2
            b = (b - bb) / 2
            bitval = bitval * 2
        end
        return res
    end

    rshift = function(a, n)
        return math.floor(mask32(a) / (2 ^ n))
    end

    lshift = function(a, n)
        return mask32(a * (2 ^ n))
    end
end

local function rrotate(x, n)
    return bor(rshift(x, n), lshift(x, 32 - n))
end

local function tohex(num)
    return string.format("%08x", num)
end

local K = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
