local function sha256_raw(msg)
    local h0 = 0x6a09e667
    local h1 = 0xbb67ae85
    local h2 = 0x3c6ef372
    local h3 = 0xa54ff53a
    local h4 = 0x510e527f
    local h5 = 0x9b05688c
    local h6 = 0x1f83d9ab
    local h7 = 0x5be0cd19

    local msgLen = #msg
    local bitLen = msgLen * 8

    msg = msg .. string.char(0x80)
    local padLen = (56 - (#msg % 64)) % 64
    msg = msg .. string.rep("\0", padLen)

    local high = math.floor(bitLen / 2 ^ 32)
    local low = bitLen % 2 ^ 32
    msg = msg .. string.char(
        rshift(high, 24) % 256,
        rshift(high, 16) % 256,
        rshift(high, 8) % 256,
        high % 256,
        rshift(low, 24) % 256,
        rshift(low, 16) % 256,
        rshift(low, 8) % 256,
        low % 256
    )

    local w = {}
    for chunkStart = 1, #msg, 64 do
        for i = 0, 15 do
            local j = chunkStart + (i * 4)
            local a = string.byte(msg, j) or 0
            local b = string.byte(msg, j + 1) or 0
            local c = string.byte(msg, j + 2) or 0
            local d = string.byte(msg, j + 3) or 0
            w[i] = bor(lshift(a, 24), bor(lshift(b, 16), bor(lshift(c, 8), d)))
        end
        for i = 16, 63 do
            local s0 = bxor(rrotate(w[i - 15], 7), rrotate(w[i - 15], 18), rshift(w[i - 15], 3))
            local s1 = bxor(rrotate(w[i - 2], 17), rrotate(w[i - 2], 19), rshift(w[i - 2], 10))
            w[i] = (w[i - 16] + s0 + w[i - 7] + s1) % 4294967296
        end

        local a = h0
        local b = h1
        local c = h2
        local d = h3
        local e = h4
        local f = h5
        local g = h6
        local h = h7

        for i = 0, 63 do
            local s1 = bxor(rrotate(e, 6), bxor(rrotate(e, 11), rrotate(e, 25)))
            local ch = bxor(band(e, f), band(bxor(e, 0xFFFFFFFF), g))
            local temp1 = (h + s1 + ch + K[i + 1] + w[i]) % 4294967296
            local s0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
            local maj = bxor(band(a, b), band(a, c), band(b, c))
            local temp2 = (s0 + maj) % 4294967296

            h = g
            g = f
            f = e
            e = (d + temp1) % 4294967296
            d = c
            c = b
            b = a
            a = (temp1 + temp2) % 4294967296
        end

        h0 = (h0 + a) % 4294967296
        h1 = (h1 + b) % 4294967296
        h2 = (h2 + c) % 4294967296
        h3 = (h3 + d) % 4294967296
        h4 = (h4 + e) % 4294967296
        h5 = (h5 + f) % 4294967296
        h6 = (h6 + g) % 4294967296
        h7 = (h7 + h) % 4294967296
    end

    return string.char(
        rshift(h0, 24) % 256, rshift(h0, 16) % 256, rshift(h0, 8) % 256, h0 % 256,
        rshift(h1, 24) % 256, rshift(h1, 16) % 256, rshift(h1, 8) % 256, h1 % 256,
        rshift(h2, 24) % 256, rshift(h2, 16) % 256, rshift(h2, 8) % 256, h2 % 256,
        rshift(h3, 24) % 256, rshift(h3, 16) % 256, rshift(h3, 8) % 256, h3 % 256,
        rshift(h4, 24) % 256, rshift(h4, 16) % 256, rshift(h4, 8) % 256, h4 % 256,
        rshift(h5, 24) % 256, rshift(h5, 16) % 256, rshift(h5, 8) % 256, h5 % 256,
        rshift(h6, 24) % 256, rshift(h6, 16) % 256, rshift(h6, 8) % 256, h6 % 256,
        rshift(h7, 24) % 256, rshift(h7, 16) % 256, rshift(h7, 8) % 256, h7 % 256
    )
end

local function hexFromRaw(raw)
    return (raw:gsub(".", function(c)
        return string.format("%02x", string.byte(c))
    end))
end

function Crypto.sha256(message)
    return hexFromRaw(sha256_raw(tostring(message or "")))
end

function Crypto.hmac_sha256(key, message)
    local blockSize = 64
    local k = tostring(key or "")
    if #k > blockSize then
        k = sha256_raw(k)
    end
    if #k < blockSize then
        k = k .. string.rep("\0", blockSize - #k)
    end

    local oKey = {}
    local iKey = {}
    for i = 1, blockSize do
        local kb = string.byte(k, i) or 0
        oKey[i] = string.char(bxor(kb, 0x5c))
        iKey[i] = string.char(bxor(kb, 0x36))
    end

    local inner = sha256_raw(table.concat(iKey) .. tostring(message or ""))
    local outer = sha256_raw(table.concat(oKey) .. inner)
    return hexFromRaw(outer)
end

end

BOOT_LOGGER.write("Inlining module: core/runtime_guard.lua")
do
-- ============================================
-- RUNTIME GUARD
-- ============================================
RuntimeGuard = {
    lastErrorAtMs = {},
    cooldownMs = 1200,
    terminateMeta = {
        source = "",
        reason = "",
        context = "",
        requestedAtMs = 0
    }
}

local _getTickCountFn = type(getTickCount) == "function" and getTickCount or nil
function RuntimeGuard.getNowMs()
    if _getTickCountFn then
        local ok, value = pcall(_getTickCountFn)
        if ok and type(value) == "number" then
            return value
        end
    end
    return math.floor(os.clock() * 1000)
end

local function logSystemLine(message)
    local text = tostring(message or "")
    if LogManager and type(LogManager.system) == "function" then
        LogManager.system(text)
        return
    end
    if BOOT_LOGGER and type(BOOT_LOGGER.write) == "function" then
        BOOT_LOGGER.write(text)
        return
    end
    if type(print) == "function" then
        print(text)
    end
end

function RuntimeGuard.report(tag, err)
    local key = tostring(tag or "runtime")
    local nowMs = RuntimeGuard.getNowMs()
    local lastMs = tonumber(RuntimeGuard.lastErrorAtMs[key]) or 0
    if (nowMs - lastMs) < RuntimeGuard.cooldownMs then
        return
    end
    RuntimeGuard.lastErrorAtMs[key] = nowMs

    local message = tostring(err or "unknown error")
    if type(debug) == "table" and type(debug.traceback) == "function" then
        local okTrace, trace = pcall(debug.traceback, message, 2)
        if okTrace and type(trace) == "string" and trace ~= "" then
            message = trace
        end
    end

    if LogManager and type(LogManager.error) == "function" then
        LogManager.error(string.format("[%s] %s", key, message))
    end
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage(string.format("[GMEA] %s xato: %s", key, tostring(err or "unknown")), 0xFF6666)
    end
    print(string.format("[GMEA][%s] %s", key, message))
end

function RuntimeGuard.requestTerminate(source, reason, context)
    local meta = RuntimeGuard.terminateMeta or {}
    meta.source = tostring(source or "unknown")
    meta.reason = tostring(reason or "unspecified")
    meta.context = tostring(context or "")
    meta.requestedAtMs = RuntimeGuard.getNowMs()
    RuntimeGuard.terminateMeta = meta

    local suffix = meta.context ~= "" and (" | context=" .. meta.context) or ""
    logSystemLine(string.format(
        "[RUNTIME] terminate requested | source=%s | reason=%s%s",
        meta.source,
        meta.reason,
        suffix
    ))
    return meta
end

function RuntimeGuard.getTerminateMeta()
    return RuntimeGuard.terminateMeta or {}
end

function RuntimeGuard.clearTerminateMeta()
    RuntimeGuard.terminateMeta = {
        source = "",
        reason = "",
        context = "",
        requestedAtMs = 0
    }
end

local _rg_unpack = table.unpack or unpack
function RuntimeGuard.call(tag, fn, ...)
    if type(fn) ~= "function" then
        RuntimeGuard.report(tag, "call target is not function")
        return false
    end
    local args = { ... }
    return xpcall(function()
        return fn(_rg_unpack(args))
    end, function(err)
        RuntimeGuard.report(tag, err)
        return err
    end)
end

-- Safe wrapper for chat commands to avoid hard crashes
local rawSampSendChat = sampSendChat
local _unpackFn = table.unpack or unpack
function sendChat(...)
    local fn = rawSampSendChat
    if type(fn) ~= "function" then
        fn = sampSendChat
        if type(fn) ~= "function" then
            return false
        end
        rawSampSendChat = fn
    end
    local firstArg = tostring((...) or "")
    if firstArg == "" then
        return false
    end
    if type(sampGetGamestate) == "function" then
        local okState, state = pcall(sampGetGamestate)
        if okState and (state == 1 or state == 5) then
            return false
        end
    end
    if PermissionGuard and PermissionGuard.allowCommand then
        local okPerm, allowed = pcall(PermissionGuard.allowCommand, firstArg)
        if not okPerm then
            RuntimeGuard.report("PermissionGuard.allowCommand", allowed)
            return false
        end
        if not allowed then
            return false
        end
    end
    local ok, err = pcall(fn, _unpackFn({...}))
    if not ok then
        RuntimeGuard.report("sampSendChat", err)
    end
    return ok
end




end

