end

function UtilityManager.getUzWeekdayIndex(timestamp)
    local uzTimestamp = tonumber(timestamp) or UtilityManager.getUzTimestamp()
    local weekday = tonumber(os.date("!%w", uzTimestamp)) or 0
    if weekday == 0 then
