    if configName == "" then
        if LogManager and LogManager.error then
            LogManager.error(tag .. " failed: empty config path")
        elseif BOOT_LOGGER and BOOT_LOGGER.write then
            BOOT_LOGGER.write(tag .. " failed: empty config path")
        end
        return nil
    end
    if type(inicfg) ~= "table" or type(inicfg.load) ~= "function" then
        if LogManager and LogManager.error then
            LogManager.error(tag .. " failed: inicfg.load unavailable")
        elseif BOOT_LOGGER and BOOT_LOGGER.write then
            BOOT_LOGGER.write(tag .. " failed: inicfg.load unavailable")
        end
        return nil
    end
    local ok, data = pcall(inicfg.load, nil, configName)
    if ok then
        return data
    end
    if LogManager and LogManager.error then
        LogManager.error(string.format("%s failed (%s): %s", tag, configName, tostring(data)))
    elseif BOOT_LOGGER and BOOT_LOGGER.write then
        BOOT_LOGGER.write(string.format("%s failed (%s): %s", tag, configName, tostring(data)))
