    end
    if type(path) ~= "string" or path == "" then
        if LogManager and LogManager.error then
            LogManager.error("INI save failed: empty path")
        end
        return false
    end
    if type(inicfg) ~= "table" or type(inicfg.save) ~= "function" then
        if LogManager and LogManager.error then
            LogManager.error(string.format("INI save failed (%s): inicfg.save unavailable", tostring(path)))
        end
        return false
    end
    local ok, err = pcall(inicfg.save, data, path)
    if not ok then
        LogManager.error(string.format("INI save failed (%s): %s", path, tostring(err)))
        return false
    end
    return true
end

