    local okCoords, a, b, c, d = pcall(getCharCoordinates, PLAYER_PED)
    if not okCoords then
        return false, 0, 0, 0
    end

    -- Some MoonLoader builds return: success, x, y, z
    if type(a) == "boolean" then
        if not a then return false, 0, 0, 0 end
