    if type(value) == "number" then
        return value ~= 0
    end
    local normalized = UtilityManager.trim(tostring(value or "")):lower()
    if normalized == "" then
        return defaultValue == true
    end
    if normalized == "true" or normalized == "1" or normalized == "yes" or normalized == "on" then
        return true
    end
    if normalized == "false" or normalized == "0" or normalized == "no" or normalized == "off" then
        return false
    end
    return defaultValue == true
end

function UtilityManager.casefoldUtf8Cyrillic(text)
    local value = tostring(text or "")
    local out = {}
    local i = 1

    while i <= #value do
        local b1 = value:byte(i)
        local b2 = value:byte(i + 1)
        local b3 = value:byte(i + 2)
        local b4 = value:byte(i + 3)

        if b1 >= 65 and b1 <= 90 then
            out[#out + 1] = string.char(b1 + 32)
            i = i + 1
        elseif b1 == 0xD0 and b2 then
            if b2 >= 0x90 and b2 <= 0x9F then
                out[#out + 1] = string.char(0xD0, b2 + 0x20)
            elseif b2 >= 0xA0 and b2 <= 0xAF then
                out[#out + 1] = string.char(0xD1, b2 - 0x20)
            elseif b2 == 0x81 then
                out[#out + 1] = string.char(0xD1, 0x91)
            else
                out[#out + 1] = string.char(b1, b2)
            end
            i = i + 2
        elseif b1 == 0xD1 and b2 then
            out[#out + 1] = string.char(b1, b2)
            i = i + 2
        elseif b1 >= 0xC2 and b1 <= 0xDF and b2 then
            out[#out + 1] = string.char(b1, b2)
            i = i + 2
        elseif b1 >= 0xE0 and b1 <= 0xEF and b2 and b3 then
            out[#out + 1] = string.char(b1, b2, b3)
            i = i + 3
        elseif b1 >= 0xF0 and b1 <= 0xF4 and b2 and b3 and b4 then
            out[#out + 1] = string.char(b1, b2, b3, b4)
            i = i + 4
        else
            out[#out + 1] = string.char(b1)
            i = i + 1
        end
    end

    return table.concat(out)
end

function UtilityManager.casefoldCp1251Cyrillic(text)
    local value = tostring(text or "")
    local out = {}
    for i = 1, #value do
        local b = value:byte(i)
        if b >= 65 and b <= 90 then
            b = b + 32
        elseif b >= 192 and b <= 223 then
            b = b + 32
        elseif b == 168 then
            b = 184
        end
        out[i] = string.char(b)
    end
    return table.concat(out)
end

function UtilityManager.isValidUtf8(text)
    local value = tostring(text or "")
    local i = 1

    while i <= #value do
        local b1 = value:byte(i)
        if b1 <= 0x7F then
            i = i + 1
        elseif b1 >= 0xC2 and b1 <= 0xDF then
            local b2 = value:byte(i + 1)
            if not b2 or b2 < 0x80 or b2 > 0xBF then
                return false
            end
            i = i + 2
        elseif b1 >= 0xE0 and b1 <= 0xEF then
            local b2 = value:byte(i + 1)
            local b3 = value:byte(i + 2)
            if not b2 or not b3 then
                return false
            end
            if b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF then
                return false
            end
            i = i + 3
        elseif b1 >= 0xF0 and b1 <= 0xF4 then
            local b2 = value:byte(i + 1)
            local b3 = value:byte(i + 2)
            local b4 = value:byte(i + 3)
            if not b2 or not b3 or not b4 then
                return false
            end
            if b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF or b4 < 0x80 or b4 > 0xBF then
                return false
            end
            i = i + 4
        else
            return false
        end
    end

    return true
end

function UtilityManager.getMatchVariants(text)
    local source = UtilityManager.trim(tostring(text or ""))
    if source == "" then
        return {}
    end

    local variants = {}
    local seen = {}

    local function addVariant(value)
        local candidate = UtilityManager.trim(tostring(value or ""))
        if candidate ~= "" and not seen[candidate] then
            seen[candidate] = true
            table.insert(variants, candidate)
        end
    end

    local function addWithCasefold(value)
        addVariant(value)
        addVariant(UtilityManager.casefoldUtf8Cyrillic(value))
        addVariant(UtilityManager.casefoldCp1251Cyrillic(value))
    end

    addWithCasefold(source)

    local okUtf8, utf8Value = pcall(function()
        return u8(source)
    end)
    if okUtf8 and type(utf8Value) == "string" then
        addWithCasefold(utf8Value)
    end

    if type(u8) == "table" and type(u8.decode) == "function" then
        local okDecode, decoded = pcall(u8.decode, u8, source)
        if okDecode and type(decoded) == "string" then
            addWithCasefold(decoded)
        end
    end

    if type(u8) == "table" and type(u8.encode) == "function" then
        local okEncode, encoded = pcall(u8.encode, u8, source)
        if okEncode and type(encoded) == "string" then
            addWithCasefold(encoded)
        end
    end

    return variants
end

function UtilityManager.toUtf8(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    if UtilityManager.isValidUtf8(value) then
        return value
    end

    local ok, converted = pcall(u8, value)
    if ok and type(converted) == "string" and converted ~= "" then
        return converted
    end

    return value
end

function UtilityManager.startsWith(str, prefix)
    local value = tostring(str or "")
    local pref = tostring(prefix or "")
    if pref == "" then
        return true
    end
    return value:sub(1, #pref) == pref
end

function UtilityManager.contains(tbl, value)
    if type(tbl) ~= "table" then
        return false
    end
    for _, v in pairs(tbl) do
        if v == value then return true end
    end
    return false
end



