BOOT_LOGGER.write("Inlining module: logs/log_manager.lua")
do
-- ============================================
-- LOG MANAGER
-- ============================================
LogManager = {
    logs = {},
    filePath = nil,
    fileReady = false,
    categories = {
        SYSTEM = "SYSTEM",
        SECURITY = "SECURITY",
        ADMIN = "ADMIN",
        PLAYER = "PLAYER",
        REPORT = "REPORT",
        ERROR = "ERROR"
    }
}

local function stringifyScalar(value)
    local kind = type(value)
    if kind == "nil" then
        return "nil"
    end
    if kind == "number" or kind == "boolean" then
        return tostring(value)
    end
    return tostring(value):gsub("[%c\r\n]+", " ")
end

local function stringifyData(data)
    if type(data) ~= "table" then
        return ""
    end

    local parts = {}
    for key, value in pairs(data) do
        local label = tostring(key)
        if type(value) == "table" then
            local nestedCount = 0
            for nestedKey, nestedValue in pairs(value) do
                nestedCount = nestedCount + 1
                if nestedCount > 6 then
                    break
                end
                parts[#parts + 1] = string.format("%s.%s=%s", label, tostring(nestedKey), stringifyScalar(nestedValue))
            end
        else
            parts[#parts + 1] = string.format("%s=%s", label, stringifyScalar(value))
        end
    end
    table.sort(parts)
    return table.concat(parts, ", ")
end

local function appendLine(path, line)
    -- Log faylga yozish o'chirilgan
    return false
end

local function resolveLogPath()
    if BOOT_LOGGER and type(BOOT_LOGGER.path) == "string" and BOOT_LOGGER.path ~= "" then
        return BOOT_LOGGER.path
    end

    local stamp = os.date("%Y-%m-%d_%H-%M-%S")
    local baseDir = "."
    if type(getWorkingDirectory) == "function" then
        local ok, path = pcall(getWorkingDirectory)
        if ok and type(path) == "string" and path ~= "" then
            baseDir = tostring(path)
        end
    end

    local candidates = {
        string.format("%s\\moonloader\\logs\\tools logs_%s.txt", baseDir, stamp),
        string.format("%s\\logs\\tools logs_%s.txt", baseDir, stamp),
        string.format("logs\\tools logs_%s.txt", stamp),
        string.format("tools logs_%s.txt", stamp)
    }

    for _, path in ipairs(candidates) do
        local file = io.open(path, "a")
        if file then
            file:close()
            return path
        end
    end

    return candidates[#candidates]
end

local function writeBootBuffer()
    if not (BOOT_LOGGER and BOOT_LOGGER.buffer) then
        return
    end
    BOOT_LOGGER.buffer = {}
end

local function writeEntry(entry)
    if not LogManager.fileReady then
        return
    end

    local line = string.format("[%s] [%s] %s",
        os.date("%Y-%m-%d %H:%M:%S"),
        tostring(entry.category or "SYSTEM"),
        tostring(entry.message or ""))

    local dataText = stringifyData(entry.data)
    if dataText ~= "" then
        line = line .. " | " .. dataText
    end

    appendLine(LogManager.filePath, line)
end

function LogManager.initialize()
    LogManager.logs = {}
    LogManager.filePath = resolveLogPath()
    LogManager.fileReady = appendLine(LogManager.filePath, string.format("[%s] [SYSTEM] Log session opened", os.date("%Y-%m-%d %H:%M:%S")))
    writeBootBuffer()
    LogManager.system("Diagnostic log initialized", { file = LogManager.filePath })
end

function LogManager.add(category, message, data)
    local entry = {
        id = UtilityManager.generateId(),
        timestamp = os.time(),
        formattedTime = os.date("%H:%M:%S"),
        category = category,
        message = message,
        data = data or {}
    }

    table.insert(LogManager.logs, entry)

    if #LogManager.logs > CONFIG.MAX_LOG_ENTRIES then
        table.remove(LogManager.logs)
    end

    writeEntry(entry)

    return entry.id
end

function LogManager.system(message, data)
    return LogManager.add(LogManager.categories.SYSTEM, message, data)
end

function LogManager.security(message, data)
    return LogManager.add(LogManager.categories.SECURITY, message, data)
end

function LogManager.admin(message, data)
    return LogManager.add(LogManager.categories.ADMIN, message, data)
end

function LogManager.player(message, data)
    return LogManager.add(LogManager.categories.PLAYER, message, data)
end

function LogManager.report(message, data)
    return LogManager.add(LogManager.categories.REPORT, message, data)
end

function LogManager.error(message, data)
    return LogManager.add(LogManager.categories.ERROR, message, data)
end

function LogManager.getByCategory(category)
    local result = {}
    for _, log in ipairs(LogManager.logs) do
        if log.category == category then
            table.insert(result, log)
        end
    end
    return result
end

function LogManager.getRecent(count)
    count = count or 50
    local result = {}
    for i = 1, math.min(count, #LogManager.logs) do
        table.insert(result, LogManager.logs[i])
    end
    return result
end

function LogManager.clear()
    LogManager.logs = {}
    LogManager.system("Logs cleared")
end

function LogManager.exportToFile(filename)
    local file = io.open(filename, "w")
    if file then
        for _, log in ipairs(LogManager.logs) do
            file:write(string.format("[%s] [%s] %s\n",
                log.formattedTime, log.category, log.message))
        end
        file:close()
        return true
    end
    return false
end


end

