function UtilityManager.bufferToString(buf)
    if type(buf) == "cdata" then
        -- crash fix: ffi.string may throw on invalid/non-char cdata buffers.
        local ok, result = pcall(function()
            local sizeOk, size = pcall(ffi.sizeof, buf)
            if sizeOk and tonumber(size) and tonumber(size) > 0 then
                local maxLen = math.max(0, tonumber(size) - 1)
                local realLen = 0
                while realLen < maxLen do
                    local byte = tonumber(buf[realLen]) or 0
                    if byte == 0 then
                        break
                    end
                    realLen = realLen + 1
                end
                return ffi.string(buf, realLen)
            end
            return ffi.string(buf)
        end)
        if ok and type(result) == "string" then
            return result
        end
        if RuntimeGuard and RuntimeGuard.report then
            RuntimeGuard.report("UtilityManager.bufferToString", result)
        end
        return ""
    end
    return tostring(buf or "")
end

function UtilityManager.toGameEncoding(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    if UtilityManager.isValidUtf8(value) and type(u8) == "table" and type(u8.decode) == "function" then
        local ok, decoded = pcall(u8.decode, u8, value)
        if ok and type(decoded) == "string" and decoded ~= "" then
            return decoded
        end
    end

    return value
end

function UtilityManager.setBufferString(buf, text)
    if type(buf) ~= "cdata" then
        return false
    end

    local value = tostring(text or "")
    local okSize, rawSize = pcall(ffi.sizeof, buf)
    local size = okSize and tonumber(rawSize) or 0
    if size <= 0 then
        return false
    end

    local okFill = pcall(ffi.fill, buf, size, 0)
    if not okFill then
        if RuntimeGuard and RuntimeGuard.report then
            RuntimeGuard.report("UtilityManager.setBufferString", "ffi.fill failed")
        end
        return false
    end
    if value ~= "" and size > 1 then
        local clipped = value:sub(1, size - 1)
        local okCopy, copyErr = pcall(ffi.copy, buf, clipped)
        if not okCopy then
            if RuntimeGuard and RuntimeGuard.report then
                RuntimeGuard.report("UtilityManager.setBufferString", copyErr)
            end
            return false
        end
    end

    return true
end

local function getEnvValue(name)
    if type(getEnv) == "function" then
        local okEnv, value = pcall(getEnv, tostring(name or ""))
        if okEnv and value and tostring(value) ~= "" then
            return tostring(value)
        end
    end
    local okOs, value = pcall(os.getenv, tostring(name or ""))
    if okOs and value and tostring(value) ~= "" then
        return tostring(value)
    end
    return ""
end

local function getScriptFingerprint()
    local parts = {
        getEnvValue("COMPUTERNAME"),
        getEnvValue("USERNAME"),
        getEnvValue("SYSTEMDRIVE"),
        getEnvValue("HOMEDRIVE"),
        getEnvValue("HOMEPATH")
    }

    local okWd, wd = pcall(getWorkingDirectory)
    if okWd and wd and tostring(wd) ~= "" then
        parts[#parts + 1] = tostring(wd)
    end

    if type(thisScript) == "function" then
        local okScript, script = pcall(thisScript)
        if okScript and script and script.path then
            parts[#parts + 1] = tostring(script.path)
        end
    end

    return table.concat(parts, "|")
end

local function xorByte(a, b)
    local result = 0
    local bitValue = 1
    local left = tonumber(a) or 0
    local right = tonumber(b) or 0
    while left > 0 or right > 0 do
        local leftBit = left % 2
        local rightBit = right % 2
        if leftBit ~= rightBit then
            result = result + bitValue
        end
        left = math.floor(left / 2)
        right = math.floor(right / 2)
        bitValue = bitValue * 2
    end
    return result
end

local function hexEncode(text)
    local value = tostring(text or "")
    local out = {}
    for i = 1, #value do
        out[#out + 1] = string.format("%02x", value:byte(i))
    end
    return table.concat(out)
end

local function hexDecode(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end
    if (#value % 2) ~= 0 or value:find("[^0-9a-fA-F]") then
        return nil
    end
    local out = {}
    for i = 1, #value, 2 do
        local byte = tonumber(value:sub(i, i + 1), 16)
        if not byte then
            return nil
        end
        out[#out + 1] = string.char(byte)
    end
    return table.concat(out)
end

local function getAdminKeyBindingSecret()
    if SettingsManager._adminKeyBindingSecret then
        return SettingsManager._adminKeyBindingSecret
    end
    local seed = table.concat({
        "grandadmin",
        "admin_api_key_v1",
        getScriptFingerprint()
    }, "|")
    SettingsManager._adminKeyBindingSecret = Crypto.sha256(seed)
    return SettingsManager._adminKeyBindingSecret
end

local function getStreamBytes(secret, salt, size)
    local out = {}
    local produced = 0
    local counter = 0
    local total = tonumber(size) or 0
    while produced < total do
        counter = counter + 1
        local block = Crypto.hmac_sha256(secret, table.concat({
            "vault_stream",
            tostring(salt or ""),
            tostring(counter),
            tostring(total)
        }, "|"))
        out[#out + 1] = block
        produced = produced + #block
    end
    return table.concat(out):sub(1, total)
end

local function applyStreamCipher(text, secret, salt)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end
    local stream = getStreamBytes(secret, salt, #value)
    local out = {}
    for i = 1, #value do
        out[i] = string.char(xorByte(value:byte(i), stream:byte(i)))
    end
    return table.concat(out)
end

local function createVaultSalt()
    local seed = table.concat({
        tostring(os.time()),
        tostring(os.clock()),
        getEnvValue("COMPUTERNAME"),
        tostring(math.random(100000, 999999))
    }, "|")
    return Crypto.sha256(seed):sub(1, 32)
end

function SettingsManager.encryptAdminApiKey(value)
    local plain = tostring(value or "")
    if plain == "" then
        return ""
    end
    local secret = getAdminKeyBindingSecret()
    local salt = createVaultSalt()
    local cipherBytes = applyStreamCipher(plain, secret, salt)
    local cipherHex = hexEncode(cipherBytes)
    local mac = Crypto.hmac_sha256(secret, table.concat({
        "vault_mac",
        salt,
        cipherHex
    }, "|"))
    return table.concat({ "v1", salt, cipherHex, mac }, ":")
end

function SettingsManager.decryptAdminApiKey(value)
    local text = tostring(value or "")
    if text == "" then
        return ""
    end

    local version, salt, cipherHex, mac = text:match("^([^:]+):([^:]+):([^:]+):([^:]+)$")
    if version ~= "v1" or not salt or not cipherHex or not mac then
        return nil, "invalid_format"
    end

    local secret = getAdminKeyBindingSecret()
    local expectedMac = Crypto.hmac_sha256(secret, table.concat({
        "vault_mac",
        salt,
        cipherHex
    }, "|"))
    if tostring(expectedMac) ~= tostring(mac) then
        return nil, "integrity_mismatch"
    end

    local cipherBytes = hexDecode(cipherHex)
    if not cipherBytes then
        return nil, "cipher_decode_failed"
    end

    return applyStreamCipher(cipherBytes, secret, salt)
end

function SettingsManager.buildPersistedConfig()
    local persisted = UtilityManager.tableCopy(SettingsManager.data)
    local protected = SettingsManager.encryptAdminApiKey(persisted.adminApiKey)
    persisted.adminApiKey = ""
    persisted.adminApiKeyEnc = protected
    return { main = persisted }
end

function SettingsManager.load()
    UtilityManager.ensureConfigDirectory()

    local rawConfig = UtilityManager.safeIniLoad(SettingsManager.configPath, "Settings load")
    local config = nil
    if type(rawConfig) == "table" then
        if type(rawConfig.main) == "table" then
            config = rawConfig.main
        else
            -- Backward compatibility with old flat/no-section format.
            config = rawConfig
        end
    end

    SettingsManager.data = UtilityManager.tableCopy(SettingsManager.defaults)
    if type(config) == "table" then
        for key, value in pairs(config) do
            if type(value) == "table" and type(SettingsManager.data[key]) == "table" then
                for innerKey, innerValue in pairs(value) do
                    SettingsManager.data[key][innerKey] = innerValue
                end
            else
                SettingsManager.data[key] = value
            end
        end
    end

    local rawPlainAdminKey = type(config) == "table" and tostring(config.adminApiKey or "") or ""
    local rawEncryptedAdminKey = type(config) == "table" and tostring(config.adminApiKeyEnc or "") or ""
    local shouldResaveProtected = false

    if rawEncryptedAdminKey ~= "" then
        local decrypted, decryptErr = SettingsManager.decryptAdminApiKey(rawEncryptedAdminKey)
        if decrypted then
            SettingsManager.data.adminApiKey = tostring(decrypted)
            if rawPlainAdminKey ~= "" then
                shouldResaveProtected = true
            end
        else
            SettingsManager.data.adminApiKey = ""
            SettingsManager.data.adminApiKeyEnc = ""
            shouldResaveProtected = false
            if LogManager and LogManager.error then
                LogManager.error("Admin API key vault check failed: " .. tostring(decryptErr))
            end
        end
    elseif rawPlainAdminKey ~= "" then
        SettingsManager.data.adminApiKey = rawPlainAdminKey
        shouldResaveProtected = true
    else
        SettingsManager.data.adminApiKey = ""
    end
    SettingsManager.data.adminApiKeyEnc = ""

    -- Always start with Kerakli and Fura tabs disabled until the user turns them back on manually.
    SettingsManager.data.kerakliMenuDisabled = true
    SettingsManager.data.furaMenuDisabled = true

    -- Normalize color table because some INI parsers store indexes as strings.
    local primary = SettingsManager.data.primaryColor
    if type(primary) == "table" then
        -- safety fix: malformed config should not silently switch to unrelated colors.
        local r = tonumber(primary[1] or primary["1"]) or 189
        local g = tonumber(primary[2] or primary["2"]) or 38
        local b = tonumber(primary[3] or primary["3"]) or 51
        SettingsManager.data.primaryColor = { r, g, b }
    else
        SettingsManager.data.primaryColor = { 189, 38, 51 }
    end

    SettingsManager.data.killListOverlayEnabled =
        UtilityManager.parseIniBool(SettingsManager.data.killListOverlayEnabled, true)
    SettingsManager.data.adminCheckerOverlayEnabled =
        UtilityManager.parseIniBool(SettingsManager.data.adminCheckerOverlayEnabled, true)
    SettingsManager.data.adminCheckerStatsEnabled =
        UtilityManager.parseIniBool(SettingsManager.data.adminCheckerStatsEnabled, false)
    SettingsManager.data.adminCheckerTextScale =
        UtilityManager.clamp(tonumber(SettingsManager.data.adminCheckerTextScale) or 1.0, 0.75, 1.80)

    local function normalizeCheckerRgb(value, fallback)
        local source = type(value) == "table" and value or fallback
        local r = tonumber(source[1] or source["1"]) or fallback[1]
        local g = tonumber(source[2] or source["2"]) or fallback[2]
        local b = tonumber(source[3] or source["3"]) or fallback[3]
        return {
            UtilityManager.clamp(math.floor(r + 0.5), 0, 255),
            UtilityManager.clamp(math.floor(g + 0.5), 0, 255),
            UtilityManager.clamp(math.floor(b + 0.5), 0, 255)
        }
    end
    SettingsManager.data.adminCheckerColorLv12 = normalizeCheckerRgb(SettingsManager.data.adminCheckerColorLv12, {122, 224, 255})
    SettingsManager.data.adminCheckerColorLv3 = normalizeCheckerRgb(SettingsManager.data.adminCheckerColorLv3, {92, 158, 255})
    SettingsManager.data.adminCheckerColorLv4 = normalizeCheckerRgb(SettingsManager.data.adminCheckerColorLv4, {250, 219, 77})
    SettingsManager.data.adminCheckerColorLv5 = normalizeCheckerRgb(SettingsManager.data.adminCheckerColorLv5, {255, 71, 82})
    SettingsManager.data.targetCircleEnabled =
        UtilityManager.parseIniBool(SettingsManager.data.targetCircleEnabled, false)
    SettingsManager.data.targetCircleMinRadius =
        UtilityManager.clamp(math.floor(tonumber(SettingsManager.data.targetCircleMinRadius) or 64), 32, 400)
    SettingsManager.data.targetCircleMaxRadius =
        UtilityManager.clamp(math.floor(tonumber(SettingsManager.data.targetCircleMaxRadius) or 260), 48, 600)
    if SettingsManager.data.targetCircleMaxRadius < SettingsManager.data.targetCircleMinRadius then
        SettingsManager.data.targetCircleMaxRadius = SettingsManager.data.targetCircleMinRadius
    end
    SettingsManager.data.targetCircleRadius =
        UtilityManager.clamp(
            math.floor(tonumber(SettingsManager.data.targetCircleRadius) or 140),
            SettingsManager.data.targetCircleMinRadius,
            SettingsManager.data.targetCircleMaxRadius
        )

    -- Force panel toggle to M for consistent behavior
    SettingsManager.data.hotkey = vkeys.VK_M
    -- Disable autosave to avoid repeated inicfg exceptions on this environment
    SettingsManager.data.autoSave = false
    -- Force legacy GTA V panel off; default UI is the shared dark-red theme.
    SettingsManager.data.gtaUiEnabled = false
    SettingsManager.data.gtaUiScale = UtilityManager.clamp(tonumber(SettingsManager.data.gtaUiScale) or 1.0, 0.80, 1.40)
    SettingsManager.data.gtaUiPerfMode = SettingsManager.data.gtaUiPerfMode ~= false
    SettingsManager.data.gtaUiAnimations = SettingsManager.data.gtaUiAnimations == true
    SettingsManager.data.gtaUiSound = SettingsManager.data.gtaUiSound ~= false
    -- Normalize quick hotkeys
    SettingsManager.data.quickHotkeysEnabled = SettingsManager.data.quickHotkeysEnabled ~= false
    SettingsManager.data.quickHotkeyModifier = tonumber(SettingsManager.data.quickHotkeyModifier) or vkeys.VK_MENU
    SettingsManager.data.quickHotkeySpec = tonumber(SettingsManager.data.quickHotkeySpec) or vkeys.VK_1
    SettingsManager.data.quickHotkeyTeleport = tonumber(SettingsManager.data.quickHotkeyTeleport) or vkeys.VK_2
    SettingsManager.data.quickHotkeyFreeze = tonumber(SettingsManager.data.quickHotkeyFreeze) or vkeys.VK_3
    SettingsManager.data.quickHotkeyJail = tonumber(SettingsManager.data.quickHotkeyJail) or vkeys.VK_4
    SettingsManager.data.kerakliMenuToggleKey =
        UtilityManager.clamp(math.floor(tonumber(SettingsManager.data.kerakliMenuToggleKey) or 0), 0, 255)
    SettingsManager.data.clickWarpEnabled = SettingsManager.data.clickWarpEnabled ~= false

    if shouldResaveProtected then
        local okSave = UtilityManager.safeIniSave(SettingsManager.buildPersistedConfig(), SettingsManager.configPath)
        if okSave and LogManager and LogManager.system then
            LogManager.system("Admin API key migrated to protected local vault")
        end
    end
    if LogManager and LogManager.system then
        LogManager.system("Settings loaded")
    end
end




end

