        ACCENT_HOVER = imgui.ImVec4(0.84, 0.24, 0.28, 1.0),
        WARNING = imgui.ImVec4(1.0, 0.7059, 0.0, 1.0),
        DANGER = imgui.ImVec4(0.92, 0.26, 0.24, 1.0),
        TEXT = imgui.ImVec4(0.97, 0.95, 0.94, 1.0),
        BORDER = imgui.ImVec4(0.40, 0.12, 0.15, 1.0)
    },
    cache = {
        lastUpdateMs = 0,
        players = {},
        reports = {},
        nameToId = {},
        reportCounts = {},
        playerCount = 0,
        reportCount = 0,
        suspiciousCount = 0,
        serverFps = 0,
        ping = 0,
        adminActive = false,
        spectate = {
            active = false,
            id = nil,
            name = "N/A",
            weapon = "N/A",
            health = 0,
            armor = 0,
            speed = 0,
            lastPos = nil,
            lastAtMs = 0
        }
    },
    vitals = {},
    logFilter = "all",
    fps = { frameCount = 0, lastAt = os.clock(), value = 0 },
    lastVitalsPruneMs = 0,
    selectedPlayerId = nil,
    selectedPlayerName = "",
    selectedReportId = nil,
    buffers = {}
}

function GtaVPanel.initialize()
    GtaVPanel.buffers = GtaVPanel.buffers or {}
    GtaVPanel.ensureBuffers()
end

function GtaVPanel.ensureBuffers()
    -- crash fix: render path can be entered after partial init/reload; buffers must exist.
    if not (GtaVPanel.buffers and GtaVPanel.buffers.actionReason) then
        GtaVPanel.buffers.actionReason = imgui.new.char[96]()
        UtilityManager.setBufferString(GtaVPanel.buffers.actionReason, "")
    end
    if not (GtaVPanel.buffers and GtaVPanel.buffers.actionDuration) then
        GtaVPanel.buffers.actionDuration = imgui.ImInt(10)
    end
    if not (GtaVPanel.buffers and GtaVPanel.buffers.targetId) then
        GtaVPanel.buffers.targetId = imgui.ImInt(0)
    end
end

function GtaVPanel.getScale()
    if not SettingsManager or not SettingsManager.get then
        return 1.0
    end
    return UtilityManager.clamp(tonumber(SettingsManager.get("gtaUiScale")) or 1.0, 0.80, 1.40)
end

function GtaVPanel.trackFps()
    local fps = GtaVPanel.fps
    local now = os.clock()
    fps.frameCount = fps.frameCount + 1
    if (now - fps.lastAt) >= 1.0 then
        fps.value = fps.frameCount
        fps.frameCount = 0
        fps.lastAt = now
    end
end

function GtaVPanel.pushStyle(scale)
    local c = GtaVPanel.colors
    imgui.PushStyleColor(imgui.Col.WindowBg, c.BG)
    imgui.PushStyleColor(imgui.Col.ChildBg, c.PANEL)
    imgui.PushStyleColor(imgui.Col.Border, c.BORDER)
    imgui.PushStyleColor(imgui.Col.Text, c.TEXT)
    imgui.PushStyleColor(imgui.Col.Button, c.PANEL)
    imgui.PushStyleColor(imgui.Col.ButtonHovered, c.ACCENT_HOVER)
    imgui.PushStyleColor(imgui.Col.ButtonActive, c.ACCENT)
    imgui.PushStyleColor(imgui.Col.FrameBg, c.PANEL)
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, c.BORDER)
    imgui.PushStyleColor(imgui.Col.FrameBgActive, c.ACCENT)
    imgui.PushStyleColor(imgui.Col.Header, c.PANEL)
    imgui.PushStyleColor(imgui.Col.HeaderHovered, c.ACCENT_HOVER)
    imgui.PushStyleColor(imgui.Col.HeaderActive, c.ACCENT)

    local varCount = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 10 * scale)
        imgui.PushStyleVar(imgui.StyleVar.FrameRounding, 6 * scale)
        imgui.PushStyleVar(imgui.StyleVar.ChildRounding, 8 * scale)
        imgui.PushStyleVar(imgui.StyleVar.FrameBorderSize, 1)
        varCount = 4
    end

    return 13, varCount
end

function GtaVPanel.popStyle(colorCount, varCount)
    if colorCount and colorCount > 0 then
        imgui.PopStyleColor(colorCount)
    end
    if varCount and varCount > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(varCount)
    end
end

function GtaVPanel.resolvePlayerIdByName(name)
    local key = UtilityManager.trim(tostring(name or "")):lower()
    if key == "" then
        return nil
    end
    return GtaVPanel.cache.nameToId[key]
end

function GtaVPanel.getVitals(playerId)
    local id = tonumber(playerId)
    if not id then
        return { health = 0, armor = 0 }
    end

    local nowMs = RuntimeGuard.getNowMs()
    local entry = GtaVPanel.vitals[id]
    if entry and (nowMs - (entry.ts or 0)) < 1000 then
        return entry
    end

    local health, armor = 0, 0
    local ped = MainUI and type(MainUI.getPlayerPedHandleById) == "function" and MainUI.getPlayerPedHandleById(id) or nil
    if ped and type(getCharHealth) == "function" then
        local ok, value = pcall(getCharHealth, ped)
        if ok and value then
            health = math.floor(tonumber(value) or 0)
        end
    end
    if ped and type(getCharArmour) == "function" then
        local ok, value = pcall(getCharArmour, ped)
        if ok and value then
            armor = math.floor(tonumber(value) or 0)
        end
    end

    entry = { health = health, armor = armor, ts = nowMs }
    GtaVPanel.vitals[id] = entry
    return entry
end

function GtaVPanel.updateSpectateCache(nowMs)
    local spec = GtaVPanel.cache.spectate
    if not (SpectateQuickPanel and SpectateQuickPanel.active and SpectateQuickPanel.targetId) then
        spec.active = false
        spec.id = nil
        spec.name = "N/A"
        spec.weapon = "N/A"
        spec.health = 0
        spec.armor = 0
        spec.speed = 0
        spec.lastPos = nil
        spec.lastAtMs = 0
        return
    end

    local id = tonumber(SpectateQuickPanel.targetId)
    spec.active = true
    spec.id = id
    spec.name = tostring(SpectateQuickPanel.targetNick or "")
    if spec.name == "" and id and type(sampGetPlayerNickname) == "function" then
        local okNick, nick = pcall(sampGetPlayerNickname, id)
        spec.name = okNick and tostring(nick or "") or "Unknown"
    end

    spec.weapon = "N/A"
    if id and type(sampGetPlayerWeapon) == "function" then
        local okW, weaponId = pcall(sampGetPlayerWeapon, id)
        if okW and weaponId then
            spec.weapon = tostring(weaponId)
        end
    end

    local ped = MainUI and type(MainUI.getPlayerPedHandleById) == "function" and MainUI.getPlayerPedHandleById(id) or nil
    if ped and type(getCharHealth) == "function" then
        local ok, value = pcall(getCharHealth, ped)
        if ok then
            spec.health = math.floor(tonumber(value) or 0)
        end
    end
    if ped and type(getCharArmour) == "function" then
        local ok, value = pcall(getCharArmour, ped)
        if ok then
            spec.armor = math.floor(tonumber(value) or 0)
        end
    end

    if ped and type(getCharCoordinates) == "function" then
        local okPos, a, b, c, d = pcall(getCharCoordinates, ped)
        if okPos then
            local x, y, z = nil, nil, nil
            if type(a) == "boolean" then
                if a then
                    x, y, z = tonumber(b), tonumber(c), tonumber(d)
                end
            else
                x, y, z = tonumber(a), tonumber(b), tonumber(c)
            end
            if x and y and z then
                if spec.lastPos and spec.lastAtMs and spec.lastAtMs > 0 then
                    local dt = (nowMs - spec.lastAtMs) / 1000.0
                    if dt > 0 then
                        local dx = x - spec.lastPos.x
                        local dy = y - spec.lastPos.y
                        local dz = z - spec.lastPos.z
                        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
                        spec.speed = (dist / dt) * 3.6
                    end
                end
                spec.lastPos = { x = x, y = y, z = z }
                spec.lastAtMs = nowMs
            end
        end
    end
end

function GtaVPanel.updateCache()
    if not MainUI or not MainUI.window or not MainUI.window.open then
        return
    end
    if not SettingsManager or not SettingsManager.get then
        return
    end
    if SettingsManager.get("gtaUiEnabled") == false then
        return
    end

    local nowMs = RuntimeGuard.getNowMs()
    local interval = SettingsManager.get("gtaUiPerfMode") and
        (CONFIG.UI.GTA_REFRESH_PERF_MS or 150) or
        (CONFIG.UI.GTA_REFRESH_MS or 100)
    if (nowMs - GtaVPanel.cache.lastUpdateMs) < interval then
        return
    end
    GtaVPanel.cache.lastUpdateMs = nowMs

    local players = {}
    if PlayerManager and type(PlayerManager.getOnlineList) == "function" then
        local okPlayers, list = pcall(PlayerManager.getOnlineList)
        if okPlayers and type(list) == "table" then
            players = list
        end
    end
    GtaVPanel.cache.players = players
    GtaVPanel.cache.playerCount = #players

    local nameToId = {}
    for _, row in ipairs(players) do
        local nick = tostring(row.name or ""):lower()
        if nick ~= "" then
            nameToId[nick] = row.id
        end
    end
    GtaVPanel.cache.nameToId = nameToId

    if (nowMs - (GtaVPanel.lastVitalsPruneMs or 0)) > 2000 then
        GtaVPanel.lastVitalsPruneMs = nowMs
        local alive = {}
        for _, row in ipairs(players) do
            alive[row.id] = true
        end
        for id in pairs(GtaVPanel.vitals) do
            if not alive[id] then
                GtaVPanel.vitals[id] = nil
            end
        end
        -- safety fix: stale UI selection should not survive after player list refresh.
        if GtaVPanel.selectedPlayerId and not alive[GtaVPanel.selectedPlayerId] then
            GtaVPanel.selectedPlayerId = nil
            GtaVPanel.selectedPlayerName = ""
        end
    end

    local reports = {}
    if ReportManager and type(ReportManager.reports) == "table" then
        reports = ReportManager.reports
    end
    GtaVPanel.cache.reports = reports
    GtaVPanel.cache.reportCount = #reports
    local reportCounts = {}
    local activeReports = {}
    for _, r in ipairs(reports) do
        activeReports[r.id] = true
        local suspect = tostring(r.suspect or ""):lower()
        if suspect ~= "" then
            reportCounts[suspect] = (reportCounts[suspect] or 0) + 1
        end
    end
    GtaVPanel.cache.reportCounts = reportCounts
    if GtaVPanel.selectedReportId and not activeReports[GtaVPanel.selectedReportId] then
        GtaVPanel.selectedReportId = nil
    end

    local suspicious = 0
    if SecurityManager and type(SecurityManager.suspiciousPlayers) == "table" then
        for _ in pairs(SecurityManager.suspiciousPlayers) do
            suspicious = suspicious + 1
        end
    end
    if suspicious == 0 and AutoAlertSystem and type(AutoAlertSystem.alerts) == "table" then
        suspicious = #AutoAlertSystem.alerts
    end
    GtaVPanel.cache.suspiciousCount = suspicious

    if ServerManager and type(ServerManager.getServerFPS) == "function" then
        local okFps, fpsValue = pcall(ServerManager.getServerFPS)
        GtaVPanel.cache.serverFps = okFps and (tonumber(fpsValue) or 0) or 0
    else
        GtaVPanel.cache.serverFps = 0
    end

    local ping = 0
    if MainUI and type(MainUI.getLocalPlayerId) == "function" and type(sampGetPlayerPing) == "function" then
        local id = MainUI.getLocalPlayerId()
        if id then
            local okPing, value = pcall(sampGetPlayerPing, id)
            if okPing and value then
                ping = tonumber(value) or 0
            end
        end
    end
    GtaVPanel.cache.ping = ping

    if AdminSession and type(AdminSession.isAdminActive) == "function" then
        GtaVPanel.cache.adminActive = AdminSession.isAdminActive()
    else
        GtaVPanel.cache.adminActive = false
    end

    if not GtaVPanel.selectedPlayerId and MainUI and MainUI.buffers and MainUI.buffers.playerId then
        local pid = tonumber(MainUI.buffers.playerId[0])
        if pid and pid > 0 then
            GtaVPanel.selectedPlayerId = pid
        end
    end

    GtaVPanel.updateSpectateCache(nowMs)
end

function GtaVPanel.renderTopBar(scale)
    local c = GtaVPanel.colors
    imgui.BeginChild("##gtav_topbar", imgui.ImVec2(0, 44 * scale), false)
    imgui.TextColored(c.ACCENT, "ADMIN CONTROL CENTER")
    imgui.SameLine()
    imgui.TextDisabled(string.format("Players: %d | Reports: %d | Suspicious: %d",
        GtaVPanel.cache.playerCount, GtaVPanel.cache.reportCount, GtaVPanel.cache.suspiciousCount))
    imgui.EndChild()
end

function GtaVPanel.renderStatusBar(scale)
    local c = GtaVPanel.colors
    imgui.BeginChild("##gtav_status", imgui.ImVec2(0, 26 * scale), true)
    local adminText = GtaVPanel.cache.adminActive and "ON" or "OFF"
    local adminColor = GtaVPanel.cache.adminActive and c.ACCENT or c.DANGER
    imgui.Text(string.format("FPS: %d | Ping: %d", GtaVPanel.fps.value or 0, GtaVPanel.cache.ping))
    imgui.SameLine()
    imgui.TextColored(adminColor, string.format("Admin Mode: %s", adminText))
    imgui.SameLine()
    imgui.TextDisabled(string.format("Version: %s", CONFIG.VERSION))
    imgui.EndChild()
end

function GtaVPanel.renderNav(scale)
    local c = GtaVPanel.colors
    local width = 170 * scale
    imgui.BeginChild("##gtav_nav", imgui.ImVec2(width, 0), true)
    for _, tab in ipairs(GtaVPanel.tabs) do
        local selected = (GtaVPanel.selectedTab == tab.id)
        if selected then
            imgui.PushStyleColor(imgui.Col.Button, c.ACCENT)
            imgui.PushStyleColor(imgui.Col.ButtonHovered, c.ACCENT)
            imgui.PushStyleColor(imgui.Col.ButtonActive, c.ACCENT)
        end
        if imgui.Button(tab.label, imgui.ImVec2(-1, 30 * scale)) then
            GtaVPanel.selectedTab = tab.id
        end
        if selected then
            imgui.PopStyleColor(3)
        end
    end
    imgui.EndChild()
end

function GtaVPanel.renderDashboard(scale)
    local c = GtaVPanel.colors
    local avail = imgui.GetContentRegionAvail()
    local gap = 10 * scale
    local cardW = (avail.x - gap) * 0.5

    imgui.BeginChild("##gtav_dash_row1", imgui.ImVec2(0, 70 * scale), false)
    imgui.BeginChild("##gtav_card_players", imgui.ImVec2(cardW, 64 * scale), true)
    imgui.TextDisabled("Players Online")
    imgui.TextColored(c.ACCENT, tostring(GtaVPanel.cache.playerCount))
    imgui.EndChild()
    imgui.SameLine(0, gap)
    imgui.BeginChild("##gtav_card_reports", imgui.ImVec2(cardW, 64 * scale), true)
    imgui.TextDisabled("Active Reports")
    imgui.TextColored(c.WARNING, tostring(GtaVPanel.cache.reportCount))
    imgui.EndChild()
    imgui.EndChild()

    imgui.BeginChild("##gtav_dash_row2", imgui.ImVec2(0, 70 * scale), false)
    imgui.BeginChild("##gtav_card_susp", imgui.ImVec2(cardW, 64 * scale), true)
    imgui.TextDisabled("Suspicious Players")
    imgui.TextColored(c.DANGER, tostring(GtaVPanel.cache.suspiciousCount))
    imgui.EndChild()
    imgui.SameLine(0, gap)
    imgui.BeginChild("##gtav_card_sfps", imgui.ImVec2(cardW, 64 * scale), true)
    imgui.TextDisabled("Server FPS")
    imgui.TextColored(c.ACCENT, tostring(GtaVPanel.cache.serverFps))
    imgui.EndChild()
    imgui.EndChild()

    if AutoAlertSystem and AutoAlertSystem.renderPopup then
        imgui.Spacing()
        AutoAlertSystem.renderPopup()
    end
end

function GtaVPanel.renderPlayers(scale)
    GtaVPanel.ensureBuffers()
    imgui.Columns(2, "##gtav_players_cols", false)
    imgui.SetColumnWidth(0, math.max(260 * scale, imgui.GetWindowWidth() * 0.62))

    imgui.BeginChild("##gtav_players_list", imgui.ImVec2(0, 260 * scale), true)
    local list = GtaVPanel.cache.players or {}
    local spanAll = imgui.SelectableFlags and imgui.SelectableFlags.SpanAllColumns or 0
    if imgui.BeginTable then
        local flags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##gtav_players_table", 5, flags) then
            imgui.TableSetupColumn("ID")
            imgui.TableSetupColumn("Name")
            imgui.TableSetupColumn("Ping")
            imgui.TableSetupColumn("Health")
            imgui.TableSetupColumn("Armor")
            imgui.TableHeadersRow()

            if imgui.ImGuiListClipper then
                local clipper = imgui.ImGuiListClipper()
                clipper:Begin(#list, imgui.GetTextLineHeightWithSpacing())
                while clipper:Step() do
                    for i = clipper.DisplayStart, clipper.DisplayEnd - 1 do
                        local row = list[i + 1]
                        if row then
                            local selected = (GtaVPanel.selectedPlayerId == row.id)
                            imgui.TableNextRow()
                            imgui.TableSetColumnIndex(0)
                            if imgui.Selectable(tostring(row.id), selected, spanAll) then
                                GtaVPanel.selectedPlayerId = row.id
                                GtaVPanel.selectedPlayerName = tostring(row.name or "")
                                if MainUI and MainUI.buffers and MainUI.buffers.playerId then
                                    MainUI.buffers.playerId[0] = row.id
                                end
                            end
                            imgui.TableSetColumnIndex(1); imgui.Text(tostring(row.name))
                            imgui.TableSetColumnIndex(2); imgui.Text(tostring(row.ping))
                            local vitals = GtaVPanel.getVitals(row.id)
                            imgui.TableSetColumnIndex(3); imgui.Text(tostring(vitals.health or 0))
                            imgui.TableSetColumnIndex(4); imgui.Text(tostring(vitals.armor or 0))
                        end
                    end
                end
                clipper:End()
            else
                for _, row in ipairs(list) do
                    local selected = (GtaVPanel.selectedPlayerId == row.id)
                    imgui.TableNextRow()
                    imgui.TableSetColumnIndex(0)
                    if imgui.Selectable(tostring(row.id), selected, spanAll) then
                        GtaVPanel.selectedPlayerId = row.id
                        GtaVPanel.selectedPlayerName = tostring(row.name or "")
                        if MainUI and MainUI.buffers and MainUI.buffers.playerId then
                            MainUI.buffers.playerId[0] = row.id
                        end
                    end
                    imgui.TableSetColumnIndex(1); imgui.Text(tostring(row.name))
                    imgui.TableSetColumnIndex(2); imgui.Text(tostring(row.ping))
                    local vitals = GtaVPanel.getVitals(row.id)
                    imgui.TableSetColumnIndex(3); imgui.Text(tostring(vitals.health or 0))
                    imgui.TableSetColumnIndex(4); imgui.Text(tostring(vitals.armor or 0))
                end
            end
            imgui.EndTable()
        end
    else
        for _, row in ipairs(list) do
            local label = string.format("[%d] %s | Ping: %s | HP: %s | ARM: %s",
                tonumber(row.id) or 0,
                tostring(row.name or ""),
                tostring(row.ping or 0),
                tostring((GtaVPanel.getVitals(row.id) or {}).health or 0),
                tostring((GtaVPanel.getVitals(row.id) or {}).armor or 0))
            if imgui.Selectable(label, GtaVPanel.selectedPlayerId == row.id) then
                GtaVPanel.selectedPlayerId = row.id
                GtaVPanel.selectedPlayerName = tostring(row.name or "")
                if MainUI and MainUI.buffers and MainUI.buffers.playerId then
                    MainUI.buffers.playerId[0] = row.id
                end
            end
        end
    end
    imgui.EndChild()

    imgui.NextColumn()
    imgui.BeginChild("##gtav_player_detail", imgui.ImVec2(0, 0), true)
    local pid = tonumber(GtaVPanel.selectedPlayerId or 0)
    if pid and pid > 0 then
        local nick = GtaVPanel.selectedPlayerName
        if nick == "" and type(sampGetPlayerNickname) == "function" then
            local okNick, name = pcall(sampGetPlayerNickname, pid)
            if okNick and name then
                nick = tostring(name)
            end
        end
        imgui.Text(string.format("Name: %s", nick or "Unknown"))
        imgui.Text(string.format("ID: %d", pid))
        if type(sampGetPlayerPing) == "function" then
            local okPing, value = pcall(sampGetPlayerPing, pid)
            imgui.Text(string.format("Ping: %s", okPing and tostring(value) or "N/A"))
        end

        local data = PlayerLogManager and PlayerLogManager.ensurePlayer and PlayerLogManager.ensurePlayer(pid, nick) or nil
        local playtime = data and tostring(data.profile.playtime or "N/A") or "N/A"
        local reportCount = GtaVPanel.cache.reportCounts[tostring(nick or ""):lower()] or 0
        local punishments = data and PlayerLogManager.countPunishments(data) or 0
        imgui.Text(string.format("Playtime: %s", playtime))
        imgui.Text(string.format("Reports: %d", reportCount))
        imgui.Text(string.format("Punishments: %d", punishments))

        imgui.Separator()
        imgui.InputInt("Duration (min)", GtaVPanel.buffers.actionDuration)
        imgui.InputText("Reason", GtaVPanel.buffers.actionReason, 96)

        if imgui.Button("Spectate", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then PlayerManager.spectate(pid) end
        end
        imgui.SameLine()
        if imgui.Button("Teleport", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then PlayerManager.teleportTo(pid) end
        end
        imgui.SameLine()
        if imgui.Button("Freeze", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then PlayerManager.freeze(pid) end
        end

        if imgui.Button("Jail", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then
                PlayerManager.jail(pid, GtaVPanel.buffers.actionDuration[0], UtilityManager.bufferToString(GtaVPanel.buffers.actionReason))
            end
        end
        imgui.SameLine()
        if imgui.Button("Mute", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then
                PlayerManager.mute(pid, GtaVPanel.buffers.actionDuration[0], UtilityManager.bufferToString(GtaVPanel.buffers.actionReason))
            end
        end
        imgui.SameLine()
        if imgui.Button("Kick", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then
                PlayerManager.kick(pid, UtilityManager.bufferToString(GtaVPanel.buffers.actionReason))
            end
        end

        if imgui.Button("Ban", imgui.ImVec2(90 * scale, 26 * scale)) then
            if PlayerManager then
                PlayerManager.ban(pid, UtilityManager.bufferToString(GtaVPanel.buffers.actionReason))
            end
        end
    else
        imgui.TextDisabled("Select a player to investigate.")
    end
    imgui.EndChild()
    imgui.Columns(1)
end

function GtaVPanel.renderReports(scale)
    imgui.Columns(2, "##gtav_reports_cols", false)
    imgui.SetColumnWidth(0, math.max(260 * scale, imgui.GetWindowWidth() * 0.62))

    imgui.BeginChild("##gtav_reports_list", imgui.ImVec2(0, 260 * scale), true)
    local list = GtaVPanel.cache.reports or {}
    local spanAll = imgui.SelectableFlags and imgui.SelectableFlags.SpanAllColumns or 0
    if imgui.BeginTable then
        local flags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##gtav_reports_table", 5, flags) then
            imgui.TableSetupColumn("ID")
            imgui.TableSetupColumn("Reporter")
            imgui.TableSetupColumn("Accused")
            imgui.TableSetupColumn("Reason")
            imgui.TableSetupColumn("Priority")
            imgui.TableHeadersRow()
            for _, r in ipairs(list) do
                imgui.TableNextRow()
                imgui.TableSetColumnIndex(0)
                if imgui.Selectable(tostring(r.id), GtaVPanel.selectedReportId == r.id, spanAll) then
                    GtaVPanel.selectedReportId = r.id
                end
                imgui.TableSetColumnIndex(1); imgui.Text(tostring(r.reporter))
                imgui.TableSetColumnIndex(2); imgui.Text(tostring(r.suspect))
                imgui.TableSetColumnIndex(3); imgui.Text(tostring(r.reason))
                imgui.TableSetColumnIndex(4); imgui.Text(tostring(r.priority or "normal"))
            end
            imgui.EndTable()
        end
    else
        for _, r in ipairs(list) do
            local label = string.format("#%s | %s -> %s | %s",
                tostring(r.id or ""),
                tostring(r.reporter or ""),
                tostring(r.suspect or ""),
                tostring(r.reason or ""))
            if imgui.Selectable(label, GtaVPanel.selectedReportId == r.id) then
                GtaVPanel.selectedReportId = r.id
            end
        end
    end
    imgui.EndChild()

    imgui.NextColumn()
    imgui.BeginChild("##gtav_reports_detail", imgui.ImVec2(0, 0), true)
    local selectedReport = nil
    for _, r in ipairs(list) do
        if r.id == GtaVPanel.selectedReportId then
            selectedReport = r
            break
        end
    end
    if selectedReport then
        imgui.Text(string.format("Report #%s", tostring(selectedReport.id)))
        imgui.Text(string.format("Reporter: %s", tostring(selectedReport.reporter)))
        imgui.Text(string.format("Accused: %s", tostring(selectedReport.suspect)))
        imgui.Text(string.format("Reason: %s", tostring(selectedReport.reason)))
        imgui.Text(string.format("Priority: %s", tostring(selectedReport.priority or "normal")))

        imgui.Separator()
        if imgui.Button("Accept", imgui.ImVec2(110 * scale, 26 * scale)) then
            ReportManager.acceptReport(selectedReport.id)
        end
        imgui.SameLine()
        if imgui.Button("Reject", imgui.ImVec2(110 * scale, 26 * scale)) then
            ReportManager.closeReport(selectedReport.id, "Rejected")
        end
        imgui.SameLine()
        if imgui.Button("Spectate", imgui.ImVec2(110 * scale, 26 * scale)) then
            local suspectId = GtaVPanel.resolvePlayerIdByName(selectedReport.suspect)
            if suspectId and PlayerManager then
                PlayerManager.spectate(suspectId)
            end
        end

        if imgui.Button("Teleport", imgui.ImVec2(110 * scale, 26 * scale)) then
            ReportManager.teleportToSuspect(selectedReport.id)
        end
    else
        imgui.TextDisabled("Select a report to view details.")
    end
    imgui.EndChild()
    imgui.Columns(1)
end

function GtaVPanel.renderSpectate(scale)
    local spec = GtaVPanel.cache.spectate
    imgui.BeginChild("##gtav_spec", imgui.ImVec2(0, 160 * scale), true)
    if not spec.active then
        imgui.TextDisabled("No active spectate target.")
        imgui.EndChild()
        return
    end
    imgui.Text(string.format("Player: %s [%s]", tostring(spec.name), tostring(spec.id or "N/A")))
    imgui.Text(string.format("Weapon: %s", tostring(spec.weapon)))
    imgui.Text(string.format("Health: %s", tostring(math.floor(spec.health or 0))))
    imgui.Text(string.format("Armor: %s", tostring(math.floor(spec.armor or 0))))
    imgui.Text(string.format("Speed: %.1f km/h", tonumber(spec.speed) or 0))
    local analysis = SpectateAssistant and SpectateAssistant.getAnalysis and SpectateAssistant.getAnalysis(spec.id) or nil
    if analysis then
        imgui.Text(string.format("Headshots: %.0f%%", analysis.headshotRate * 100))
        imgui.Text(string.format("Accuracy: %.0f%%", analysis.accuracy * 100))
        if analysis.hits >= 10 and analysis.headshotRate > 0.75 then
            imgui.TextColored(GtaVPanel.colors.DANGER, "? Possible aim anomaly")
        end
    else
        imgui.Text("Headshots: N/A")
        imgui.Text("Accuracy: N/A")
    end
    imgui.EndChild()

    if imgui.Button("Free Camera", imgui.ImVec2(140 * scale, 26 * scale)) then
        if SpectateQuickPanel then
            SpectateQuickPanel.cursorVisible = false
        end
    end
    imgui.SameLine()
    if imgui.Button("Stop Spectate", imgui.ImVec2(140 * scale, 26 * scale)) then
        SpectateQuickPanel.sendSpOff()
    end
end

function GtaVPanel.getFilteredLogs()
    if not LogManager or not LogManager.logs then
        return {}
    end
    if GtaVPanel.logFilter == "all" then
        return LogManager.logs
    end
    local target = nil
    if GtaVPanel.logFilter == "admin" then
        target = LogManager.categories.ADMIN
    elseif GtaVPanel.logFilter == "security" then
        target = LogManager.categories.SECURITY
    elseif GtaVPanel.logFilter == "player" then
        target = LogManager.categories.PLAYER
    end
    if not target then
        return LogManager.logs
    end
    local result = {}
    for _, entry in ipairs(LogManager.logs) do
        if entry.category == target then
            table.insert(result, entry)
        end
    end
    return result
end

function GtaVPanel.renderLogs(scale)
    if imgui.Button("All", imgui.ImVec2(60 * scale, 24 * scale)) then
        GtaVPanel.logFilter = "all"
    end
    imgui.SameLine()
    if imgui.Button("Admin", imgui.ImVec2(60 * scale, 24 * scale)) then
        GtaVPanel.logFilter = "admin"
    end
    imgui.SameLine()
    if imgui.Button("Security", imgui.ImVec2(70 * scale, 24 * scale)) then
        GtaVPanel.logFilter = "security"
    end
    imgui.SameLine()
    if imgui.Button("Player", imgui.ImVec2(60 * scale, 24 * scale)) then
        GtaVPanel.logFilter = "player"
    end

    imgui.BeginChild("##gtav_logs", imgui.ImVec2(0, 220 * scale), true)
    local logs = GtaVPanel.getFilteredLogs()
    if imgui.BeginTable then
        local flags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##gtav_logs_table", 3, flags) then
            imgui.TableSetupColumn("Time")
            imgui.TableSetupColumn("Category")
            imgui.TableSetupColumn("Action")
            imgui.TableHeadersRow()

            local count = #logs
            if imgui.ImGuiListClipper then
                local clipper = imgui.ImGuiListClipper()
                clipper:Begin(count, imgui.GetTextLineHeightWithSpacing())
                while clipper:Step() do
                    for i = clipper.DisplayStart, clipper.DisplayEnd - 1 do
                        local entry = logs[i + 1]
                        if entry then
                            imgui.TableNextRow()
                            imgui.TableSetColumnIndex(0); imgui.Text(tostring(entry.formattedTime or ""))
                            imgui.TableSetColumnIndex(1); imgui.Text(tostring(entry.category or ""))
                            imgui.TableSetColumnIndex(2); imgui.Text(tostring(entry.message or ""))
                        end
                    end
                end
                clipper:End()
            else
                for _, entry in ipairs(logs) do
                    imgui.TableNextRow()
                    imgui.TableSetColumnIndex(0); imgui.Text(tostring(entry.formattedTime or ""))
                    imgui.TableSetColumnIndex(1); imgui.Text(tostring(entry.category or ""))
                    imgui.TableSetColumnIndex(2); imgui.Text(tostring(entry.message or ""))
                end
            end
            imgui.EndTable()
        end
    else
        for _, entry in ipairs(logs) do
            imgui.Text(string.format("[%s] [%s] %s",
                tostring(entry.formattedTime or ""),
                tostring(entry.category or ""),
                tostring(entry.message or "")))
        end
    end
    imgui.EndChild()

    if imgui.CollapsingHeader("Admin History") then
        if AdminHistoryTracker and AdminHistoryTracker.renderTable then
            AdminHistoryTracker.renderTable()
        end
    end
    if KillListManager and KillListManager.renderLogsSection then
        KillListManager.renderLogsSection(scale)
    end
end

