function GtaVPanel.renderMain(scale)
    if GtaVPanel.selectedTab == "dashboard" then
        GtaVPanel.renderDashboard(scale)
    elseif GtaVPanel.selectedTab == "players" then
        GtaVPanel.renderPlayers(scale)
    elseif GtaVPanel.selectedTab == "reports" then
        GtaVPanel.renderReports(scale)
    elseif GtaVPanel.selectedTab == "spectate" then
        GtaVPanel.renderSpectate(scale)
    elseif GtaVPanel.selectedTab == "logs" then
        GtaVPanel.renderLogs(scale)
