function GtaVPanel.render()
    if not MainUI or not MainUI.window or not MainUI.window.open then
        return
    end
    if not SettingsManager or not SettingsManager.get then
        return
    end
    if SettingsManager.get("gtaUiEnabled") == false then
        return
    end

    GtaVPanel.ensureBuffers()
    GtaVPanel.updateCache()
    GtaVPanel.trackFps()

    local scale = GtaVPanel.getScale()
    local minWidth, minHeight = 900 * scale, 520 * scale
    local defaultPos = imgui.ImVec2(80, 60)
    local condAppearing = (imgui.Cond and imgui.Cond.Appearing) or imgui.Cond.FirstUseEver

    if MainUI.window.pos and MainUI.window.pos.x and MainUI.window.pos.y then
        imgui.SetNextWindowPos(
            imgui.ImVec2(MainUI.window.pos.x, MainUI.window.pos.y),
            condAppearing
        )
    else
        imgui.SetNextWindowPos(defaultPos, imgui.Cond.FirstUseEver)
    end

    local io = imgui.GetIO and imgui.GetIO()
    if io and io.DisplaySize then
        local maxWidth = math.max(minWidth, io.DisplaySize.x - 20)
        local maxHeight = math.max(minHeight, io.DisplaySize.y - 20)
        if imgui.SetNextWindowSizeConstraints then
            imgui.SetNextWindowSizeConstraints(
                imgui.ImVec2(minWidth, minHeight),
                imgui.ImVec2(maxWidth, maxHeight)
            )
        end
        if MainUI.window.size and MainUI.window.size.x and MainUI.window.size.y then
            imgui.SetNextWindowSize(
                imgui.ImVec2(MainUI.window.size.x, MainUI.window.size.y),
                condAppearing
            )
        else
            local autoWidth = math.max(minWidth, math.min(maxWidth, io.DisplaySize.x * 0.88))
            local autoHeight = math.max(minHeight, math.min(maxHeight, io.DisplaySize.y * 0.88))
            imgui.SetNextWindowSize(
                imgui.ImVec2(autoWidth, autoHeight),
                imgui.Cond.FirstUseEver
            )
        end
    end

    local colorCount, varCount = GtaVPanel.pushStyle(scale)
    local flags = imgui.WindowFlags.NoCollapse +
                  imgui.WindowFlags.NoSavedSettings +
                  imgui.WindowFlags.NoTitleBar

    if imgui.Begin("##gtav_admin_panel", nil, flags) then
        RuntimeGuard.call("GtaVPanel.render.body", function()
            if MainUI and MainUI.captureWindowSnapshot then
                MainUI.captureWindowSnapshot(minWidth, minHeight)
            end

            GtaVPanel.renderTopBar(scale)
            if AutoAlertSystem and AutoAlertSystem.renderPopup then
                AutoAlertSystem.renderPopup()
            end
            imgui.Separator()

            local statusHeight = 28 * scale
            imgui.BeginChild("##gtav_body", imgui.ImVec2(0, imgui.GetContentRegionAvail().y - statusHeight), false)
            GtaVPanel.renderNav(scale)
            imgui.SameLine()
            imgui.BeginChild("##gtav_main", imgui.ImVec2(0, 0), true)
            RuntimeGuard.call("GtaVPanel.renderMain", GtaVPanel.renderMain, scale)
            imgui.EndChild()
            imgui.EndChild()

            imgui.Separator()
            GtaVPanel.renderStatusBar(scale)
        end)
    end
    imgui.End()
    if MainUI and MainUI.renderKatatsyaAccessPopup then
        MainUI.renderKatatsyaAccessPopup()
    end
    if MainUI and MainUI.renderKatatsyaPanel then
        MainUI.renderKatatsyaPanel()
    end
    GtaVPanel.popStyle(colorCount, varCount)
end

function SettingsManager.save()
    UtilityManager.ensureConfigDirectory()

    local payload = { main = SettingsManager.data }
    if SettingsManager.buildPersistedConfig then
        payload = SettingsManager.buildPersistedConfig()
    end
    local okSave = UtilityManager.safeIniSave(payload, SettingsManager.configPath)
    if okSave and LogManager and LogManager.system then
        LogManager.system("Settings saved")
    end
    return okSave
end

function SettingsManager.get(key)
    local value = SettingsManager.data[key]
    if value == nil then
        return SettingsManager.defaults[key]
    end
    return value
end

function SettingsManager.set(key, value)
    SettingsManager.data[key] = value
    if SettingsManager.data.autoSave then
        SettingsManager.save()
    end
end

function SettingsManager.reset()
    SettingsManager.data = UtilityManager.tableCopy(SettingsManager.defaults)
    SettingsManager.save()
    if LogManager and LogManager.system then
        LogManager.system("Settings reset to defaults")
    end
end

function SettingsManager.getHotkeyName()
    local key = SettingsManager.data.hotkey or SettingsManager.defaults.hotkey or vkeys.VK_M
    if type(vkeys.id_to_name) == "function" then
        return vkeys.id_to_name(key) or "M"
    end
    return "M"
end

