function AutoPunishmentManager.ensureForm()
    if AutoPunishmentManager.form then
        return
    end

    AutoPunishmentManager.form = {
        label = imgui.new.char[64](),
        command1 = imgui.new.char[160](),
        command2 = imgui.new.char[160]()
    }
