    UtilityManager.setBufferString(AutoPunishmentManager.form.command1, "/jail {id} 60 DM")
    UtilityManager.setBufferString(AutoPunishmentManager.form.command2, "")
end

function AutoPunishmentManager.getDefaultPos()
    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080
    return 18, math.max(10, screenY - 330)
end

function AutoPunishmentManager.normalizeCommandTemplate(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    if value:sub(1, 1) ~= "/" then
        value = "/" .. value
    end
    return value
end

function AutoPunishmentManager.markDirty()
    AutoPunishmentManager.dirty = true
end

function AutoPunishmentManager.buildPayload()
    local payload = {
        main = {
            panelPosX = tonumber(AutoPunishmentManager.ui.pos.x) or 280,
            panelPosY = tonumber(AutoPunishmentManager.ui.pos.y) or 0,
            panelWidth = tonumber(AutoPunishmentManager.ui.size.width) or 360,
            panelHeight = tonumber(AutoPunishmentManager.ui.size.height) or 280
        }
    }

    for index, action in ipairs(AutoPunishmentManager.customActions or {}) do
        payload["action_" .. tostring(index)] = {
            id = tostring(action.id or UtilityManager.generateId()),
            label = tostring(action.label or ""),
            command1 = tostring(action.command1 or ""),
            command2 = tostring(action.command2 or "")
        }
    end

    return payload
end

function AutoPunishmentManager.save(force)
    if not force and not AutoPunishmentManager.dirty then
        return true
    end
    AutoPunishmentManager.dirty = false
    AutoPunishmentManager.lastUiSaveAt = os.clock()
    return UtilityManager.safeIniSave(AutoPunishmentManager.buildPayload(), AutoPunishmentManager.configPath)
end

function AutoPunishmentManager.flushUiSave(force)
    if force == true then
        return AutoPunishmentManager.save(true)
    end
    if not AutoPunishmentManager.dirty then
        return true
    end
    if (os.clock() - tonumber(AutoPunishmentManager.lastUiSaveAt or 0)) < 0.40 then
        return false
    end
    return AutoPunishmentManager.save(true)
end

function AutoPunishmentManager.load()
    AutoPunishmentManager.configPath = UtilityManager.getConfigPath("auto_punishments.ini")
    AutoPunishmentManager.customActions = {}

    local defaultX, defaultY = AutoPunishmentManager.getDefaultPos()
    local saved = UtilityManager.safeIniLoad(AutoPunishmentManager.configPath, "Auto punishments load")
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}

    AutoPunishmentManager.ui.pos.x = tonumber(main.panelPosX) or defaultX
    AutoPunishmentManager.ui.pos.y = tonumber(main.panelPosY) or defaultY
    AutoPunishmentManager.ui.size.width = tonumber(main.panelWidth) or 360
    AutoPunishmentManager.ui.size.height = tonumber(main.panelHeight) or 280

    local indexed = {}
    for sectionName, section in pairs(saved or {}) do
        local index = tonumber(tostring(sectionName or ""):match("^action_(%d+)$"))
        if index and type(section) == "table" then
            indexed[#indexed + 1] = {
                index = index,
                id = tostring(section.id or UtilityManager.generateId()),
                label = UtilityManager.trim(tostring(section.label or "")),
                command1 = AutoPunishmentManager.normalizeCommandTemplate(section.command1 or ""),
                command2 = AutoPunishmentManager.normalizeCommandTemplate(section.command2 or "")
            }
        end
    end

    table.sort(indexed, function(a, b)
        return tonumber(a.index) < tonumber(b.index)
    end)

    for _, entry in ipairs(indexed) do
        if entry.label ~= "" and entry.command1 ~= "" then
            AutoPunishmentManager.customActions[#AutoPunishmentManager.customActions + 1] = {
                id = entry.id,
                label = entry.label,
                command1 = entry.command1,
                command2 = entry.command2
            }
        end
    end

    AutoPunishmentManager.dirty = false
    AutoPunishmentManager.lastUiSaveAt = os.clock()
end

function AutoPunishmentManager.initialize()
    AutoPunishmentManager.ensureForm()
    AutoPunishmentManager.load()
end

function AutoPunishmentManager.getTargetId()
    return tonumber(SpectateQuickPanel and SpectateQuickPanel.targetId)
end

function AutoPunishmentManager.expandCommand(commandTemplate, targetId)
    local value = AutoPunishmentManager.normalizeCommandTemplate(commandTemplate)
    if value == "" then
        return ""
    end

    local idText = tostring(tonumber(targetId) or 0)
    value = value:gsub("{%s*[Ii][Dd]%s*}", idText)
    value = value:gsub("%%[Ii][Dd]%%", idText)
    value = value:gsub("%$[Ii][Dd]", idText)
    value = value:gsub("{TARGET}", idText)
    value = value:gsub("{target}", idText)
    return UtilityManager.toGameEncoding(value)
end

function AutoPunishmentManager.executeCommands(commands, targetId, actionLabel)
    local prepared = {}
    for _, commandTemplate in ipairs(commands or {}) do
        local command = AutoPunishmentManager.expandCommand(commandTemplate, targetId)
        if UtilityManager.trim(command) ~= "" then
            prepared[#prepared + 1] = command
        end
    end

    if #prepared == 0 then
        return false
    end

    local function emit(command)
        local okSend = sendChat(command)
        if okSend and LogManager and LogManager.admin then
            LogManager.admin(string.format("Auto punish [%s]: %s", tostring(actionLabel or "custom"), tostring(command)))
        end
        return okSend
    end

    if #prepared == 1 or not (lua_thread and type(lua_thread.create) == "function") then
        return emit(prepared[1])
    end

    lua_thread.create(function()
        for index, command in ipairs(prepared) do
            emit(command)
            if index < #prepared and type(wait) == "function" then
                wait(120)
            end
        end
    end)
    return true
end

function AutoPunishmentManager.executeAction(action)
    local targetId = AutoPunishmentManager.getTargetId()
    if not targetId or targetId <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[SP] Auto jazo: target ID topilmadi.", 0xFF6666)
        end
        return false
    end

    if type(action) ~= "table" then
        return false
    end

    local commands = action.commands or { action.command1, action.command2 }
    return AutoPunishmentManager.executeCommands(commands, targetId, action.label or action.id)
end

function AutoPunishmentManager.addCustomAction(label, command1, command2)
    local safeLabel = UtilityManager.trim(tostring(label or ""))
    local safeCommand1 = AutoPunishmentManager.normalizeCommandTemplate(command1)
    local safeCommand2 = AutoPunishmentManager.normalizeCommandTemplate(command2)
    if safeLabel == "" or safeCommand1 == "" then
        return false
    end

    AutoPunishmentManager.customActions[#AutoPunishmentManager.customActions + 1] = {
        id = UtilityManager.generateId(),
        label = safeLabel,
        command1 = safeCommand1,
        command2 = safeCommand2
    }
    AutoPunishmentManager.markDirty()
    AutoPunishmentManager.save(true)
    return true
end

function AutoPunishmentManager.removeCustomAction(index)
    local numericIndex = tonumber(index)
    if not numericIndex or not AutoPunishmentManager.customActions[numericIndex] then
        return false
    end
    table.remove(AutoPunishmentManager.customActions, numericIndex)
    AutoPunishmentManager.markDirty()
    AutoPunishmentManager.save(true)
    return true
end

function AutoPunishmentManager.getAllActions()
    local actions = {}
    for _, entry in ipairs(AutoPunishmentManager.getDefaultActions()) do
        actions[#actions + 1] = entry
    end
    for _, entry in ipairs(AutoPunishmentManager.customActions or {}) do
        actions[#actions + 1] = {
            id = tostring(entry.id or UtilityManager.generateId()),
            label = tostring(entry.label or "Custom"),
            commands = { entry.command1, entry.command2 },
            builtIn = false
        }
    end
    return actions
end

function AutoPunishmentManager.renderSpectatePanel()
    if not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        return
    end

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080

    local actions = AutoPunishmentManager.getAllActions()
    local ui = AutoPunishmentManager.ui
    ui.pos = ui.pos or { x = 280, y = 0 }
    ui.size = ui.size or { width = 360, height = 280 }

    local minWidth = 280
    local minHeight = 180
    local maxWidth = math.max(minWidth, screenX - 10)
    local maxHeight = math.max(minHeight, screenY - 10)
    local defaultX, defaultY = AutoPunishmentManager.getDefaultPos()
    local startX = tonumber(ui.pos.x) or defaultX
    local startY = tonumber(ui.pos.y) or defaultY
    local width = UtilityManager.clamp(tonumber(ui.size.width) or 360, minWidth, maxWidth)
    local height = UtilityManager.clamp(tonumber(ui.size.height) or 280, minHeight, maxHeight)

    startX = UtilityManager.clamp(startX, 10, math.max(10, screenX - width - 10))
    startY = UtilityManager.clamp(startY, 10, math.max(10, screenY - height - 10))

    if not ui.initialized then
        imgui.SetNextWindowPos(imgui.ImVec2(startX, startY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
        ui.initialized = true
    end

    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(
            imgui.ImVec2(minWidth, minHeight),
            imgui.ImVec2(maxWidth, maxHeight)
        )
    end

    local flags = imgui.WindowFlags.NoCollapse
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.09, 0.03, 0.04, 0.92))
    imgui.PushStyleColor(imgui.Col.Border, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 0.98))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 10)
        styleVarPushed = 1
    end

    if imgui.Begin("Avto Jazo##SpectateAutoPunishPanel", nil, flags) then
        local currentPos = imgui.GetWindowPos()
        local currentSize = imgui.GetWindowSize()
        if currentPos and currentSize then
            local changed = false
            if math.abs((ui.pos.x or 0) - currentPos.x) > 0.5 or math.abs((ui.pos.y or 0) - currentPos.y) > 0.5 then
                ui.pos.x = currentPos.x
                ui.pos.y = currentPos.y
                changed = true
            end
            if math.abs((ui.size.width or 0) - currentSize.x) > 0.5 or math.abs((ui.size.height or 0) - currentSize.y) > 0.5 then
                ui.size.width = currentSize.x
                ui.size.height = currentSize.y
                changed = true
            end
            if changed then
                AutoPunishmentManager.markDirty()
            end
        end
        AutoPunishmentManager.flushUiSave(false)

        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0),
            string.format("AUTO JAZO: %s", SpectateQuickPanel.getTargetDisplay()))
        imgui.TextDisabled("SP target uchun tezkor jazo tugmalari")
        imgui.Separator()

        local contentWidth = math.max(200, imgui.GetContentRegionAvail().x)
        local gap = 6
        local columns = contentWidth >= 520 and 3 or 2
        columns = math.max(1, columns)
        local buttonWidth = math.max(110, math.floor((contentWidth - ((columns - 1) * gap)) / columns))

        for index, action in ipairs(actions) do
            local label = tostring(action.label or ("Action " .. tostring(index)))
            if imgui.Button(label .. "##sp_auto_punish_" .. tostring(action.id or index), imgui.ImVec2(buttonWidth, 30)) then
                AutoPunishmentManager.executeAction(action)
            end

            local lastInRow = (index % columns == 0) or (index == #actions)
            if not lastInRow then
                imgui.SameLine(0, gap)
            end
        end
    end
    imgui.End()

    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)
end

