            commands = { "/spawn {id}" }
        }
    }
end

function FwPunishmentManager.getDefaultPos()
    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080
    return math.max(18, screenX - 430), math.max(10, screenY - 410)
end

function FwPunishmentManager.normalizeCommandTemplate(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    if value:sub(1, 1) ~= "/" then
        value = "/" .. value
    end
    return value
end

function FwPunishmentManager.copyCommands(commands)
    local result = {}
    for _, command in ipairs(commands or {}) do
        result[#result + 1] = FwPunishmentManager.normalizeCommandTemplate(command)
    end
    return result
end

function FwPunishmentManager.markDirty()
    FwPunishmentManager.dirty = true
end

function FwPunishmentManager.getRuleSectionName(ruleId)
    return "rule_" .. tostring(ruleId or "")
end

function FwPunishmentManager.getRuleById(ruleId)
    for _, rule in ipairs(FwPunishmentManager.rules or {}) do
        if tostring(rule.id or "") == tostring(ruleId or "") then
            return rule
        end
    end
    return nil
end

function FwPunishmentManager.ensureEditors()
    FwPunishmentManager.editors = FwPunishmentManager.editors or {}
    for _, rule in ipairs(FwPunishmentManager.rules or {}) do
        if not FwPunishmentManager.editors[rule.id] then
            FwPunishmentManager.editors[rule.id] = {
                command1 = imgui.new.char[160](),
                command2 = imgui.new.char[160]()
            }
        end
    end
end

function FwPunishmentManager.syncEditorBuffers(ruleId)
    FwPunishmentManager.ensureEditors()
    for _, rule in ipairs(FwPunishmentManager.rules or {}) do
        if not ruleId or tostring(rule.id) == tostring(ruleId) then
            local editor = FwPunishmentManager.editors[rule.id]
            if editor then
                UtilityManager.setBufferString(editor.command1, tostring(rule.commands and rule.commands[1] or ""))
                UtilityManager.setBufferString(editor.command2, tostring(rule.commands and rule.commands[2] or ""))
            end
        end
    end
end

function FwPunishmentManager.buildPayload()
    local payload = {
        main = {
            panelPosX = tonumber(FwPunishmentManager.ui.pos.x) or 660,
            panelPosY = tonumber(FwPunishmentManager.ui.pos.y) or 0,
            panelWidth = tonumber(FwPunishmentManager.ui.size.width) or 400,
            panelHeight = tonumber(FwPunishmentManager.ui.size.height) or 360
        }
    }

    for _, rule in ipairs(FwPunishmentManager.rules or {}) do
        payload[FwPunishmentManager.getRuleSectionName(rule.id)] = {
            showInSpectate = rule.showInSpectate == false and 0 or 1,
            command1 = tostring(rule.commands and rule.commands[1] or ""),
            command2 = tostring(rule.commands and rule.commands[2] or "")
        }
    end

    return payload
end

function FwPunishmentManager.save(force)
    if not force and not FwPunishmentManager.dirty then
        return true
    end
    FwPunishmentManager.dirty = false
    FwPunishmentManager.lastUiSaveAt = os.clock()
    return UtilityManager.safeIniSave(FwPunishmentManager.buildPayload(), FwPunishmentManager.configPath)
end

function FwPunishmentManager.flushUiSave(force)
    if force == true then
        return FwPunishmentManager.save(true)
    end
    if not FwPunishmentManager.dirty then
        return true
    end
    if (os.clock() - tonumber(FwPunishmentManager.lastUiSaveAt or 0)) < 0.40 then
        return false
    end
    return FwPunishmentManager.save(true)
end

function FwPunishmentManager.load()
    FwPunishmentManager.configPath = UtilityManager.getConfigPath("fw_punishments.ini")
    FwPunishmentManager.rules = {}

    local defaultX, defaultY = FwPunishmentManager.getDefaultPos()
    local saved = UtilityManager.safeIniLoad(FwPunishmentManager.configPath, "FW punishments load")
    saved = type(saved) == "table" and saved or {}
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}

    FwPunishmentManager.ui.pos.x = tonumber(main.panelPosX) or defaultX
    FwPunishmentManager.ui.pos.y = tonumber(main.panelPosY) or defaultY
    FwPunishmentManager.ui.size.width = tonumber(main.panelWidth) or 400
    FwPunishmentManager.ui.size.height = tonumber(main.panelHeight) or 360

    for _, defaultRule in ipairs(FwPunishmentManager.getDefaultRules()) do
        local section = saved[FwPunishmentManager.getRuleSectionName(defaultRule.id)] or {}
        local commands = {
            FwPunishmentManager.normalizeCommandTemplate(section.command1 or defaultRule.commands[1] or ""),
            FwPunishmentManager.normalizeCommandTemplate(section.command2 or defaultRule.commands[2] or "")
        }
        FwPunishmentManager.rules[#FwPunishmentManager.rules + 1] = {
            id = defaultRule.id,
            label = defaultRule.label,
            description = defaultRule.description,
            showInSpectate = not (tostring(section.showInSpectate or "1") == "0"),
            defaultCommands = FwPunishmentManager.copyCommands(defaultRule.commands),
            commands = commands
        }
    end

    FwPunishmentManager.ensureEditors()
    FwPunishmentManager.syncEditorBuffers()
    FwPunishmentManager.dirty = false
    FwPunishmentManager.lastUiSaveAt = os.clock()
end

function FwPunishmentManager.initialize()
    FwPunishmentManager.load()
end

function FwPunishmentManager.toggle()
    FwPunishmentManager.enabled = not FwPunishmentManager.enabled
    if not FwPunishmentManager.enabled and MainUI and MainUI.playerManagementView == "fw" then
        MainUI.playerManagementView = "main"
    end
    return FwPunishmentManager.enabled
end

function FwPunishmentManager.getTargetId()
    return tonumber(SpectateQuickPanel and SpectateQuickPanel.targetId)
end

function FwPunishmentManager.expandCommand(commandTemplate, targetId)
    local value = FwPunishmentManager.normalizeCommandTemplate(commandTemplate)
    if value == "" then
        return ""
    end

    local idText = tostring(tonumber(targetId) or 0)
    value = value:gsub("{%s*[Ii][Dd]%s*}", idText)
    value = value:gsub("%%[Ii][Dd]%%", idText)
    value = value:gsub("%$[Ii][Dd]", idText)
    value = value:gsub("{TARGET}", idText)
    value = value:gsub("{target}", idText)
    return UtilityManager.toGameEncoding(value)
end

function FwPunishmentManager.executeCommands(commands, targetId, actionLabel)
    local prepared = {}
    for _, commandTemplate in ipairs(commands or {}) do
        local command = FwPunishmentManager.expandCommand(commandTemplate, targetId)
        if UtilityManager.trim(command) ~= "" then
            prepared[#prepared + 1] = command
        end
    end

    if #prepared == 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[FW] Bu band uchun jazo buyruqi sozlanmagan.", 0xFFCC66)
        end
        return false
    end

    local function emit(command)
        local okSend = sendChat(command)
        if okSend and LogManager and LogManager.admin then
            LogManager.admin(string.format("FW punish [%s]: %s", tostring(actionLabel or "rule"), tostring(command)))
        end
        return okSend
    end

    if #prepared == 1 or not (lua_thread and type(lua_thread.create) == "function") then
        return emit(prepared[1])
    end

    lua_thread.create(function()
        for index, command in ipairs(prepared) do
            emit(command)
            if index < #prepared and type(wait) == "function" then
                wait(120)
            end
        end
    end)
    return true
end

function FwPunishmentManager.executeRule(rule)
    local targetId = FwPunishmentManager.getTargetId()
    if not targetId or targetId <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[FW] SP target ID topilmadi.", 0xFF6666)
        end
        return false
    end
    if type(rule) ~= "table" then
        return false
    end

    -- FamilyTracker: avval /stats yuboriladi, keyin (1200ms keyin) jazo beriladi
    if FamilyTracker and FamilyTracker.triggerStatsRequest then
        local targetNick   = tostring(SpectateQuickPanel and SpectateQuickPanel.targetNick or "")
        local ruleRef      = rule
        local idRef        = targetId
        local punishLabel  = tostring(rule.label or rule.id or "N/A")
        FamilyTracker.triggerStatsRequest(targetId, targetNick, function()
            FwPunishmentManager.executeCommands(ruleRef.commands, idRef, ruleRef.label or ruleRef.id)
        end, punishLabel)
        return true
    end

    -- FamilyTracker yuklanmagan bo'lsa — to'g'ridan-to'g'ri jazo
    return FwPunishmentManager.executeCommands(rule.commands, targetId, rule.label or rule.id)
end

function FwPunishmentManager.applyEditor(ruleId)
    local rule = FwPunishmentManager.getRuleById(ruleId)
    local editor = FwPunishmentManager.editors and FwPunishmentManager.editors[ruleId]
    if not rule or not editor then
        return false
    end

    rule.commands = {
        FwPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command1)),
        FwPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command2))
    }
    FwPunishmentManager.markDirty()
    return FwPunishmentManager.save(true)
end

function FwPunishmentManager.resetRule(ruleId)
    local rule = FwPunishmentManager.getRuleById(ruleId)
    if not rule then
        return false
    end
    rule.commands = FwPunishmentManager.copyCommands(rule.defaultCommands)
    FwPunishmentManager.syncEditorBuffers(ruleId)
    FwPunishmentManager.markDirty()
    return FwPunishmentManager.save(true)
end

function FwPunishmentManager.renderSpectatePanel()
    if not FwPunishmentManager.enabled or not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        return
    end

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080

    local ui = FwPunishmentManager.ui
    ui.pos = ui.pos or { x = 660, y = 0 }
    ui.size = ui.size or { width = 400, height = 360 }

    local minWidth = 320
    local minHeight = 220
    local maxWidth = math.max(minWidth, screenX - 10)
    local maxHeight = math.max(minHeight, screenY - 10)
    local defaultX, defaultY = FwPunishmentManager.getDefaultPos()
    local startX = tonumber(ui.pos.x) or defaultX
    local startY = tonumber(ui.pos.y) or defaultY
    local width = UtilityManager.clamp(tonumber(ui.size.width) or 400, minWidth, maxWidth)
    local height = UtilityManager.clamp(tonumber(ui.size.height) or 360, minHeight, maxHeight)

    startX = UtilityManager.clamp(startX, 10, math.max(10, screenX - width - 10))
    startY = UtilityManager.clamp(startY, 10, math.max(10, screenY - height - 10))

    if not ui.initialized then
        imgui.SetNextWindowPos(imgui.ImVec2(startX, startY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
        ui.initialized = true
    end

    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(
            imgui.ImVec2(minWidth, minHeight),
            imgui.ImVec2(maxWidth, maxHeight)
        )
    end

    local flags = imgui.WindowFlags.NoCollapse
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.09, 0.03, 0.04, 0.92))
    imgui.PushStyleColor(imgui.Col.Border, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 0.98))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 10)
        styleVarPushed = 1
    end

    if imgui.Begin("FW Jazolar##SpectateFwPunishPanel", nil, flags) then
        local currentPos = imgui.GetWindowPos()
        local currentSize = imgui.GetWindowSize()
        if currentPos and currentSize then
            local changed = false
            if math.abs((ui.pos.x or 0) - currentPos.x) > 0.5 or math.abs((ui.pos.y or 0) - currentPos.y) > 0.5 then
                ui.pos.x = currentPos.x
                ui.pos.y = currentPos.y
                changed = true
            end
            if math.abs((ui.size.width or 0) - currentSize.x) > 0.5 or math.abs((ui.size.height or 0) - currentSize.y) > 0.5 then
                ui.size.width = currentSize.x
                ui.size.height = currentSize.y
                changed = true
            end
            if changed then
                FwPunishmentManager.markDirty()
            end
        end
        FwPunishmentManager.flushUiSave(false)

        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0),
            string.format("FW JAZOLAR: %s", SpectateQuickPanel.getTargetDisplay()))
        imgui.TextDisabled("/fw bilan yoqiladi yoki o'chiriladi")
        -- FamilyTracker: joriy target semyasini yangilash va ko'rsatish
        if FamilyTracker then
            pcall(FamilyTracker.refreshCurrentTarget)
            local fam = tostring(FamilyTracker.currentTargetFamily or "")
            if fam ~= "" then
                imgui.TextColored(imgui.ImVec4(0.2, 0.85, 1.0, 1.0),
                    string.format(u8"Semya: %s", fam))
            else
                imgui.TextDisabled(u8"Semya: aniqlanmagan")
            end
        end
        imgui.Separator()

        local contentWidth = math.max(220, imgui.GetContentRegionAvail().x)
        local gap = 6
        local columns = contentWidth >= 560 and 4 or 3
        columns = math.max(2, columns)
        local buttonWidth = math.max(82, math.floor((contentWidth - ((columns - 1) * gap)) / columns))

        local visibleRules = {}
        for _, rule in ipairs(FwPunishmentManager.rules or {}) do
            if rule.showInSpectate ~= false then
                visibleRules[#visibleRules + 1] = rule
            end
        end

        if #visibleRules == 0 then
            imgui.TextDisabled(u8"SP panel uchun hozircha hech qanday FW band ko'rsatilmayapti.")
        end

        for index, rule in ipairs(visibleRules) do
            if imgui.Button(tostring(rule.label or index) .. "##fw_rule_" .. tostring(rule.id or index), imgui.ImVec2(buttonWidth, 30)) then
                FwPunishmentManager.executeRule(rule)
            end

            if imgui.IsItemHovered() then
                imgui.BeginTooltip()
                if imgui.PushTextWrapPos then
                    imgui.PushTextWrapPos(420)
                end
                if imgui.TextUnformatted then
                    imgui.TextUnformatted(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                else
                    imgui.TextWrapped(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                end
                local preview = table.concat(rule.commands or {}, " | ")
                if UtilityManager.trim(preview) ~= "" then
                    imgui.Separator()
                    if imgui.TextUnformatted then
                        imgui.TextUnformatted(preview)
                    else
                        imgui.TextWrapped(preview)
                    end
                end
                if imgui.PopTextWrapPos then
                    imgui.PopTextWrapPos()
                end
                imgui.EndTooltip()
            end

            local lastInRow = (index % columns == 0) or (index == #visibleRules)
            if not lastInRow then
                imgui.SameLine(0, gap)
            end
        end
    end
    imgui.End()

    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)
end

