function FuraPunishmentManager.getDefaultPos()
    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080
    return math.max(18, screenX - 860), math.max(10, screenY - 410)
end

function FuraPunishmentManager.normalizeCommandTemplate(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    if value:sub(1, 1) ~= "/" then
        value = "/" .. value
    end
    return value
end

function FuraPunishmentManager.copyCommands(commands)
    local result = {}
    for _, command in ipairs(commands or {}) do
        result[#result + 1] = FuraPunishmentManager.normalizeCommandTemplate(command)
    end
    return result
end

function FuraPunishmentManager.markDirty()
    FuraPunishmentManager.dirty = true
end

function FuraPunishmentManager.getRuleSectionName(ruleId)
    return "rule_" .. tostring(ruleId or "")
end

function FuraPunishmentManager.getRuleById(ruleId)
    for _, rule in ipairs(FuraPunishmentManager.rules or {}) do
        if tostring(rule.id or "") == tostring(ruleId or "") then
            return rule
        end
    end
    return nil
end

function FuraPunishmentManager.ensureEditors()
    FuraPunishmentManager.editors = FuraPunishmentManager.editors or {}
    for _, rule in ipairs(FuraPunishmentManager.rules or {}) do
        if not FuraPunishmentManager.editors[rule.id] then
            FuraPunishmentManager.editors[rule.id] = {
                command1 = imgui.new.char[160](),
                command2 = imgui.new.char[160]()
            }
        end
    end
end

function FuraPunishmentManager.syncEditorBuffers(ruleId)
    FuraPunishmentManager.ensureEditors()
    for _, rule in ipairs(FuraPunishmentManager.rules or {}) do
        if not ruleId or tostring(rule.id) == tostring(ruleId) then
            local editor = FuraPunishmentManager.editors[rule.id]
            if editor then
                UtilityManager.setBufferString(editor.command1, tostring(rule.commands and rule.commands[1] or ""))
                UtilityManager.setBufferString(editor.command2, tostring(rule.commands and rule.commands[2] or ""))
            end
        end
    end
end

function FuraPunishmentManager.buildPayload()
    local payload = {
        main = {
            panelPosX = tonumber(FuraPunishmentManager.ui.pos.x) or 240,
            panelPosY = tonumber(FuraPunishmentManager.ui.pos.y) or 0,
            panelWidth = tonumber(FuraPunishmentManager.ui.size.width) or 400,
            panelHeight = tonumber(FuraPunishmentManager.ui.size.height) or 360
        }
    }

    for _, rule in ipairs(FuraPunishmentManager.rules or {}) do
        payload[FuraPunishmentManager.getRuleSectionName(rule.id)] = {
            showInSpectate = rule.showInSpectate == false and 0 or 1,
            command1 = tostring(rule.commands and rule.commands[1] or ""),
            command2 = tostring(rule.commands and rule.commands[2] or "")
        }
    end

    return payload
end

function FuraPunishmentManager.save(force)
    if not force and not FuraPunishmentManager.dirty then
        return true
    end
    FuraPunishmentManager.dirty = false
    FuraPunishmentManager.lastUiSaveAt = os.clock()
    return UtilityManager.safeIniSave(FuraPunishmentManager.buildPayload(), FuraPunishmentManager.configPath)
end

function FuraPunishmentManager.flushUiSave(force)
    if force == true then
        return FuraPunishmentManager.save(true)
    end
    if not FuraPunishmentManager.dirty then
        return true
    end
    if (os.clock() - tonumber(FuraPunishmentManager.lastUiSaveAt or 0)) < 0.40 then
        return false
    end
    return FuraPunishmentManager.save(true)
end

function FuraPunishmentManager.load()
    FuraPunishmentManager.configPath = UtilityManager.getConfigPath("fura_punishments.ini")
    FuraPunishmentManager.rules = {}

    local defaultX, defaultY = FuraPunishmentManager.getDefaultPos()
    local saved = UtilityManager.safeIniLoad(FuraPunishmentManager.configPath, "FURA punishments load")
    saved = type(saved) == "table" and saved or {}
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}

    FuraPunishmentManager.ui.pos.x = tonumber(main.panelPosX) or defaultX
    FuraPunishmentManager.ui.pos.y = tonumber(main.panelPosY) or defaultY
    FuraPunishmentManager.ui.size.width = tonumber(main.panelWidth) or 400
    FuraPunishmentManager.ui.size.height = tonumber(main.panelHeight) or 360

    for _, defaultRule in ipairs(FuraPunishmentManager.getDefaultRules()) do
        local section = saved[FuraPunishmentManager.getRuleSectionName(defaultRule.id)] or {}
        local commands = {
            FuraPunishmentManager.normalizeCommandTemplate(section.command1 or defaultRule.commands[1] or ""),
            FuraPunishmentManager.normalizeCommandTemplate(section.command2 or defaultRule.commands[2] or "")
        }
        FuraPunishmentManager.rules[#FuraPunishmentManager.rules + 1] = {
            id = defaultRule.id,
            label = defaultRule.label,
            description = defaultRule.description,
            showInSpectate = not (tostring(section.showInSpectate or "1") == "0"),
            defaultCommands = FuraPunishmentManager.copyCommands(defaultRule.commands),
            commands = commands
        }
    end

    FuraPunishmentManager.ensureEditors()
    FuraPunishmentManager.syncEditorBuffers()
    FuraPunishmentManager.dirty = false
    FuraPunishmentManager.lastUiSaveAt = os.clock()
end

function FuraPunishmentManager.initialize()
    FuraPunishmentManager.load()
end

function FuraPunishmentManager.toggle()
    FuraPunishmentManager.enabled = not FuraPunishmentManager.enabled
    if not FuraPunishmentManager.enabled and MainUI and MainUI.playerManagementView == "fura" then
        MainUI.playerManagementView = "main"
    end
    return FuraPunishmentManager.enabled
end

function FuraPunishmentManager.getTargetId()
    return tonumber(SpectateQuickPanel and SpectateQuickPanel.targetId)
end

function FuraPunishmentManager.expandCommand(commandTemplate, targetId)
    local value = FuraPunishmentManager.normalizeCommandTemplate(commandTemplate)
    if value == "" then
        return ""
    end

    local idText = tostring(tonumber(targetId) or 0)
    value = value:gsub("{%s*[Ii][Dd]%s*}", idText)
    value = value:gsub("%%[Ii][Dd]%%", idText)
    value = value:gsub("%$[Ii][Dd]", idText)
    value = value:gsub("{TARGET}", idText)
    value = value:gsub("{target}", idText)
    return UtilityManager.toGameEncoding(value)
end

function FuraPunishmentManager.executeCommands(commands, targetId, actionLabel)
    local prepared = {}
    for _, commandTemplate in ipairs(commands or {}) do
        local command = FuraPunishmentManager.expandCommand(commandTemplate, targetId)
        if UtilityManager.trim(command) ~= "" then
            prepared[#prepared + 1] = command
        end
    end

    if #prepared == 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[FURA] Bu band uchun jazo buyruqi sozlanmagan.", 0xFFCC66)
        end
        return false
    end

    local function emit(command)
        local okSend = sendChat(command)
        if okSend and LogManager and LogManager.admin then
            LogManager.admin(string.format("FURA punish [%s]: %s", tostring(actionLabel or "rule"), tostring(command)))
        end
        return okSend
    end

    if #prepared == 1 or not (lua_thread and type(lua_thread.create) == "function") then
        return emit(prepared[1])
    end

    lua_thread.create(function()
        for index, command in ipairs(prepared) do
            emit(command)
            if index < #prepared and type(wait) == "function" then
                wait(120)
            end
        end
    end)
    return true
end

function FuraPunishmentManager.executeRule(rule)
    local targetId = FuraPunishmentManager.getTargetId()
    if not targetId or targetId <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[FURA] SP target ID topilmadi.", 0xFF6666)
        end
        return false
    end
    if type(rule) ~= "table" then
        return false
    end

    return FuraPunishmentManager.executeCommands(rule.commands, targetId, rule.label or rule.id)
end

function FuraPunishmentManager.applyEditor(ruleId)
    local rule = FuraPunishmentManager.getRuleById(ruleId)
    local editor = FuraPunishmentManager.editors and FuraPunishmentManager.editors[ruleId]
    if not rule or not editor then
        return false
    end

    rule.commands = {
        FuraPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command1)),
        FuraPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command2))
    }
    FuraPunishmentManager.markDirty()
    return FuraPunishmentManager.save(true)
end

function FuraPunishmentManager.resetRule(ruleId)
    local rule = FuraPunishmentManager.getRuleById(ruleId)
    if not rule then
        return false
    end
    rule.commands = FuraPunishmentManager.copyCommands(rule.defaultCommands)
    FuraPunishmentManager.syncEditorBuffers(ruleId)
    FuraPunishmentManager.markDirty()
    return FuraPunishmentManager.save(true)
end

function FuraPunishmentManager.renderSpectatePanel()
    if not FuraPunishmentManager.enabled or not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        return
    end

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080

    local ui = FuraPunishmentManager.ui
    ui.pos = ui.pos or { x = 240, y = 0 }
    ui.size = ui.size or { width = 400, height = 360 }

    local minWidth = 320
    local minHeight = 220
    local maxWidth = math.max(minWidth, screenX - 10)
    local maxHeight = math.max(minHeight, screenY - 10)
    local defaultX, defaultY = FuraPunishmentManager.getDefaultPos()
    local startX = tonumber(ui.pos.x) or defaultX
    local startY = tonumber(ui.pos.y) or defaultY
    local width = UtilityManager.clamp(tonumber(ui.size.width) or 400, minWidth, maxWidth)
    local height = UtilityManager.clamp(tonumber(ui.size.height) or 360, minHeight, maxHeight)

    startX = UtilityManager.clamp(startX, 10, math.max(10, screenX - width - 10))
    startY = UtilityManager.clamp(startY, 10, math.max(10, screenY - height - 10))

    if not ui.initialized then
        imgui.SetNextWindowPos(imgui.ImVec2(startX, startY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
        ui.initialized = true
    end

    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(
            imgui.ImVec2(minWidth, minHeight),
            imgui.ImVec2(maxWidth, maxHeight)
        )
    end

    local flags = imgui.WindowFlags.NoCollapse
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.03, 0.06, 0.09, 0.92))
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0.10, 0.60, 0.85, 0.98))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 10)
        styleVarPushed = 1
    end

    if imgui.Begin("FURA Jazolar##SpectateFuraPunishPanel", nil, flags) then
        local currentPos = imgui.GetWindowPos()
        local currentSize = imgui.GetWindowSize()
        if currentPos and currentSize then
            local changed = false
            if math.abs((ui.pos.x or 0) - currentPos.x) > 0.5 or math.abs((ui.pos.y or 0) - currentPos.y) > 0.5 then
                ui.pos.x = currentPos.x
                ui.pos.y = currentPos.y
                changed = true
            end
            if math.abs((ui.size.width or 0) - currentSize.x) > 0.5 or math.abs((ui.size.height or 0) - currentSize.y) > 0.5 then
                ui.size.width = currentSize.x
                ui.size.height = currentSize.y
                changed = true
            end
            if changed then
                FuraPunishmentManager.markDirty()
            end
        end
        FuraPunishmentManager.flushUiSave(false)

        imgui.TextColored(imgui.ImVec4(0.10, 0.70, 0.95, 1.0),
            string.format("FURA JAZOLAR: %s", SpectateQuickPanel.getTargetDisplay()))
        imgui.TextDisabled("/fura bilan yoqiladi yoki o'chiriladi")
        imgui.TextColored(imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"FURGON UCHUN JANG | HAR KUNI 21:00")
        imgui.Separator()

        local contentWidth = math.max(220, imgui.GetContentRegionAvail().x)
        local gap = 6
        local columns = contentWidth >= 560 and 4 or 3
        columns = math.max(2, columns)
        local buttonWidth = math.max(82, math.floor((contentWidth - ((columns - 1) * gap)) / columns))

        local visibleRules = {}
        for _, rule in ipairs(FuraPunishmentManager.rules or {}) do
            if rule.showInSpectate ~= false then
                visibleRules[#visibleRules + 1] = rule
            end
        end

        if #visibleRules == 0 then
            imgui.TextDisabled(u8"SP panel uchun hozircha hech qanday FURA band ko'rsatilmayapti.")
        end

        for index, rule in ipairs(visibleRules) do
            if imgui.Button(tostring(rule.label or index) .. "##fura_rule_" .. tostring(rule.id or index), imgui.ImVec2(buttonWidth, 30)) then
                FuraPunishmentManager.executeRule(rule)
            end

            if imgui.IsItemHovered() then
                imgui.BeginTooltip()
                if imgui.PushTextWrapPos then
                    imgui.PushTextWrapPos(420)
                end
                if imgui.TextUnformatted then
                    imgui.TextUnformatted(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                else
                    imgui.TextWrapped(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                end
                local preview = table.concat(rule.commands or {}, " | ")
                if UtilityManager.trim(preview) ~= "" then
                    imgui.Separator()
                    if imgui.TextUnformatted then
                        imgui.TextUnformatted(preview)
                    else
                        imgui.TextWrapped(preview)
                    end
                end
                if imgui.PopTextWrapPos then
                    imgui.PopTextWrapPos()
                end
                imgui.EndTooltip()
            end

            local lastInRow = (index % columns == 0) or (index == #visibleRules)
            if not lastInRow then
                imgui.SameLine(0, gap)
            end
        end
    end
    imgui.End()

    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)
end

