            description = "Fraps so'ralgan o'yinchi yozuvni taqdim etmaguncha keyingi bizvarlarda ishtirok eta olmaydi.",
            commands = {},
            comment = "Og'zaki ogohlantirish beriladi"
        }
    }
end

function BwPunishmentManager.getDefaultPos()
    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080
    return math.max(18, screenX - 880), math.max(10, screenY - 450)
end

function BwPunishmentManager.normalizeCommandTemplate(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    if value:sub(1, 1) ~= "/" then
        value = "/" .. value
    end
    return value
end

function BwPunishmentManager.copyCommands(commands)
    local result = {}
    for _, command in ipairs(commands or {}) do
        result[#result + 1] = BwPunishmentManager.normalizeCommandTemplate(command)
    end
    return result
end

function BwPunishmentManager.markDirty()
    BwPunishmentManager.dirty = true
end

function BwPunishmentManager.getRuleSectionName(ruleId)
    return "rule_" .. tostring(ruleId or "")
end

function BwPunishmentManager.getRuleById(ruleId)
    for _, rule in ipairs(BwPunishmentManager.rules or {}) do
        if tostring(rule.id or "") == tostring(ruleId or "") then
            return rule
        end
    end
    return nil
end

function BwPunishmentManager.ensureEditors()
    BwPunishmentManager.editors = BwPunishmentManager.editors or {}
    for _, rule in ipairs(BwPunishmentManager.rules or {}) do
        if not BwPunishmentManager.editors[rule.id] then
            BwPunishmentManager.editors[rule.id] = {
                command1 = imgui.new.char[160](),
                command2 = imgui.new.char[160]()
            }
        end
    end
end

function BwPunishmentManager.syncEditorBuffers(ruleId)
    BwPunishmentManager.ensureEditors()
    for _, rule in ipairs(BwPunishmentManager.rules or {}) do
        if not ruleId or tostring(rule.id) == tostring(ruleId) then
            local editor = BwPunishmentManager.editors[rule.id]
            if editor then
                UtilityManager.setBufferString(editor.command1, tostring(rule.commands and rule.commands[1] or ""))
                UtilityManager.setBufferString(editor.command2, tostring(rule.commands and rule.commands[2] or ""))
            end
        end
    end
end

function BwPunishmentManager.buildPayload()
    local payload = {
        main = {
            panelPosX = tonumber(BwPunishmentManager.ui.pos.x) or 120,
            panelPosY = tonumber(BwPunishmentManager.ui.pos.y) or 0,
            panelWidth = tonumber(BwPunishmentManager.ui.size.width) or 420,
            panelHeight = tonumber(BwPunishmentManager.ui.size.height) or 400
        }
    }

    for _, rule in ipairs(BwPunishmentManager.rules or {}) do
        payload[BwPunishmentManager.getRuleSectionName(rule.id)] = {
            showInSpectate = rule.showInSpectate == false and 0 or 1,
            command1 = tostring(rule.commands and rule.commands[1] or ""),
            command2 = tostring(rule.commands and rule.commands[2] or "")
        }
    end

    return payload
end

function BwPunishmentManager.save(force)
    if not force and not BwPunishmentManager.dirty then
        return true
    end
    BwPunishmentManager.dirty = false
    BwPunishmentManager.lastUiSaveAt = os.clock()
    return UtilityManager.safeIniSave(BwPunishmentManager.buildPayload(), BwPunishmentManager.configPath)
end

function BwPunishmentManager.flushUiSave(force)
    if force == true then
        return BwPunishmentManager.save(true)
    end
    if not BwPunishmentManager.dirty then
        return true
    end
    if (os.clock() - tonumber(BwPunishmentManager.lastUiSaveAt or 0)) < 0.40 then
        return false
    end
    return BwPunishmentManager.save(true)
end

function BwPunishmentManager.load()
    BwPunishmentManager.configPath = UtilityManager.getConfigPath("bw_punishments.ini")
    BwPunishmentManager.rules = {}

    local defaultX, defaultY = BwPunishmentManager.getDefaultPos()
    local saved = UtilityManager.safeIniLoad(BwPunishmentManager.configPath, "BW punishments load")
    saved = type(saved) == "table" and saved or {}
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}

    BwPunishmentManager.ui.pos.x = tonumber(main.panelPosX) or defaultX
    BwPunishmentManager.ui.pos.y = tonumber(main.panelPosY) or defaultY
    BwPunishmentManager.ui.size.width = tonumber(main.panelWidth) or 420
    BwPunishmentManager.ui.size.height = tonumber(main.panelHeight) or 400

    for _, defaultRule in ipairs(BwPunishmentManager.getDefaultRules()) do
        local section = saved[BwPunishmentManager.getRuleSectionName(defaultRule.id)] or {}
        local commands = {
            BwPunishmentManager.normalizeCommandTemplate(section.command1 or defaultRule.commands[1] or ""),
            BwPunishmentManager.normalizeCommandTemplate(section.command2 or defaultRule.commands[2] or "")
        }
        BwPunishmentManager.rules[#BwPunishmentManager.rules + 1] = {
            id = defaultRule.id,
            label = defaultRule.label,
            description = defaultRule.description,
            comment = defaultRule.comment or nil,
            showInSpectate = not (tostring(section.showInSpectate or "1") == "0"),
            defaultCommands = BwPunishmentManager.copyCommands(defaultRule.commands),
            commands = commands
        }
    end

    BwPunishmentManager.ensureEditors()
    BwPunishmentManager.syncEditorBuffers()
    BwPunishmentManager.dirty = false
    BwPunishmentManager.lastUiSaveAt = os.clock()
end

function BwPunishmentManager.initialize()
    BwPunishmentManager.load()
end

function BwPunishmentManager.toggle()
    BwPunishmentManager.enabled = not BwPunishmentManager.enabled
    if not BwPunishmentManager.enabled and MainUI and MainUI.playerManagementView == "bw" then
        MainUI.playerManagementView = "main"
    end
    return BwPunishmentManager.enabled
end

function BwPunishmentManager.getTargetId()
    return tonumber(SpectateQuickPanel and SpectateQuickPanel.targetId)
end

function BwPunishmentManager.expandCommand(commandTemplate, targetId)
    local value = BwPunishmentManager.normalizeCommandTemplate(commandTemplate)
    if value == "" then
        return ""
    end

    local idText = tostring(tonumber(targetId) or 0)
    value = value:gsub("{%s*[Ii][Dd]%s*}", idText)
    value = value:gsub("%%[Ii][Dd]%%", idText)
    value = value:gsub("%$[Ii][Dd]", idText)
    value = value:gsub("{TARGET}", idText)
    value = value:gsub("{target}", idText)
    return UtilityManager.toGameEncoding(value)
end

function BwPunishmentManager.executeCommands(commands, targetId, actionLabel)
    local prepared = {}
    for _, commandTemplate in ipairs(commands or {}) do
        local command = BwPunishmentManager.expandCommand(commandTemplate, targetId)
        if UtilityManager.trim(command) ~= "" then
            prepared[#prepared + 1] = command
        end
    end

    if #prepared == 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[BW] Bu band uchun jazo buyruqi sozlanmagan.", 0xFFCC66)
        end
        return false
    end

    local function emit(command)
        local okSend = sendChat(command)
        if okSend and LogManager and LogManager.admin then
            LogManager.admin(string.format("BW punish [%s]: %s", tostring(actionLabel or "rule"), tostring(command)))
        end
        return okSend
    end

    if #prepared == 1 or not (lua_thread and type(lua_thread.create) == "function") then
        return emit(prepared[1])
    end

    lua_thread.create(function()
        for index, command in ipairs(prepared) do
            emit(command)
            if index < #prepared and type(wait) == "function" then
                wait(120)
            end
        end
    end)
    return true
end

function BwPunishmentManager.executeRule(rule)
    local targetId = BwPunishmentManager.getTargetId()
    if not targetId or targetId <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[BW] SP target ID topilmadi.", 0xFF6666)
        end
        return false
    end
    if type(rule) ~= "table" then
        return false
    end

    return BwPunishmentManager.executeCommands(rule.commands, targetId, rule.label or rule.id)
end

function BwPunishmentManager.applyEditor(ruleId)
    local rule = BwPunishmentManager.getRuleById(ruleId)
    local editor = BwPunishmentManager.editors and BwPunishmentManager.editors[ruleId]
    if not rule or not editor then
        return false
    end

    rule.commands = {
        BwPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command1)),
        BwPunishmentManager.normalizeCommandTemplate(UtilityManager.bufferToString(editor.command2))
    }
    BwPunishmentManager.markDirty()
    return BwPunishmentManager.save(true)
end

function BwPunishmentManager.resetRule(ruleId)
    local rule = BwPunishmentManager.getRuleById(ruleId)
    if not rule then
        return false
    end
    rule.commands = BwPunishmentManager.copyCommands(rule.defaultCommands)
    BwPunishmentManager.syncEditorBuffers(ruleId)
    BwPunishmentManager.markDirty()
    return BwPunishmentManager.save(true)
end

function BwPunishmentManager.renderSpectatePanel()
    if not BwPunishmentManager.enabled or not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        return
    end

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080

    local ui = BwPunishmentManager.ui
    ui.pos = ui.pos or { x = 120, y = 0 }
    ui.size = ui.size or { width = 420, height = 400 }

    local minWidth = 320
    local minHeight = 220
    local maxWidth = math.max(minWidth, screenX - 10)
    local maxHeight = math.max(minHeight, screenY - 10)
    local defaultX, defaultY = BwPunishmentManager.getDefaultPos()
    local startX = tonumber(ui.pos.x) or defaultX
    local startY = tonumber(ui.pos.y) or defaultY
    local width = UtilityManager.clamp(tonumber(ui.size.width) or 420, minWidth, maxWidth)
    local height = UtilityManager.clamp(tonumber(ui.size.height) or 400, minHeight, maxHeight)

    startX = UtilityManager.clamp(startX, 10, math.max(10, screenX - width - 10))
    startY = UtilityManager.clamp(startY, 10, math.max(10, screenY - height - 10))

    if not ui.initialized then
        imgui.SetNextWindowPos(imgui.ImVec2(startX, startY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
        ui.initialized = true
    end

    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(
            imgui.ImVec2(minWidth, minHeight),
            imgui.ImVec2(maxWidth, maxHeight)
        )
    end

    local flags = imgui.WindowFlags.NoCollapse
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.06, 0.03, 0.09, 0.92))
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0.65, 0.20, 0.80, 0.98))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 10)
        styleVarPushed = 1
    end

    if imgui.Begin("BW Jazolar##SpectateBwPunishPanel", nil, flags) then
        local currentPos = imgui.GetWindowPos()
        local currentSize = imgui.GetWindowSize()
        if currentPos and currentSize then
            local changed = false
            if math.abs((ui.pos.x or 0) - currentPos.x) > 0.5 or math.abs((ui.pos.y or 0) - currentPos.y) > 0.5 then
                ui.pos.x = currentPos.x
                ui.pos.y = currentPos.y
                changed = true
            end
            if math.abs((ui.size.width or 0) - currentSize.x) > 0.5 or math.abs((ui.size.height or 0) - currentSize.y) > 0.5 then
                ui.size.width = currentSize.x
                ui.size.height = currentSize.y
                changed = true
            end
            if changed then
                BwPunishmentManager.markDirty()
            end
        end
        BwPunishmentManager.flushUiSave(false)

        imgui.TextColored(imgui.ImVec4(0.65, 0.20, 0.80, 1.0),
            string.format("BW JAZOLAR: %s", SpectateQuickPanel.getTargetDisplay()))
        imgui.TextDisabled("/bw bilan yoqiladi yoki o'chiriladi")
        imgui.TextColored(imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"BIZNES UCHUN URUSH")
        imgui.Separator()

        local contentWidth = math.max(220, imgui.GetContentRegionAvail().x)
        local gap = 6
        local columns = contentWidth >= 560 and 4 or 3
        columns = math.max(2, columns)
        local buttonWidth = math.max(82, math.floor((contentWidth - ((columns - 1) * gap)) / columns))

        local visibleRules = {}
        for _, rule in ipairs(BwPunishmentManager.rules or {}) do
            if rule.showInSpectate ~= false then
                visibleRules[#visibleRules + 1] = rule
            end
        end

        if #visibleRules == 0 then
            imgui.TextDisabled(u8"SP panel uchun hozircha hech qanday BW band ko'rsatilmayapti.")
        end

        for index, rule in ipairs(visibleRules) do
            if imgui.Button(tostring(rule.label or index) .. "##bw_rule_" .. tostring(rule.id or index), imgui.ImVec2(buttonWidth, 30)) then
                BwPunishmentManager.executeRule(rule)
            end

            if imgui.IsItemHovered() then
                imgui.BeginTooltip()
                if imgui.PushTextWrapPos then
                    imgui.PushTextWrapPos(420)
                end
                if imgui.TextUnformatted then
                    imgui.TextUnformatted(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                else
                    imgui.TextWrapped(UtilityManager.toUtf8(rule.description or "") or tostring(rule.description or ""))
                end
                if rule.comment and rule.comment ~= "" then
                    imgui.TextColored(imgui.ImVec4(1.0, 0.6, 0.2, 1.0),
                        UtilityManager.toUtf8(rule.comment) or tostring(rule.comment))
                end
                local preview = table.concat(rule.commands or {}, " | ")
                if UtilityManager.trim(preview) ~= "" then
                    imgui.Separator()
                    if imgui.TextUnformatted then
                        imgui.TextUnformatted(preview)
                    else
                        imgui.TextWrapped(preview)
                    end
                end
                if imgui.PopTextWrapPos then
                    imgui.PopTextWrapPos()
                end
                imgui.EndTooltip()
            end

            local lastInRow = (index % columns == 0) or (index == #visibleRules)
            if not lastInRow then
                imgui.SameLine(0, gap)
            end
        end
    end
    imgui.End()

    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)
end

-- ============================================
-- FAMILY TRACKER — Semya aniqlovchi modul
-- FW jazo berilganda /stats ID yuborib, Oila: qatorini topadi,
-- INI ga saqlaydi, log yozadi, SP panelda va menyuda qidiruv ishlaydi.
-- ============================================
FamilyTracker = {
    configPath = nil,
    -- nick (lower) -> { nick = original, family = "...", updatedAt = timestamp }
    db = {},
    -- Kutilayotgan /stats javoblar: playerId -> { nick, requestedAt }
    pending = {},
    -- SP panelda ko'rinadigan joriy target semyasi
    currentTargetFamily = "",
    -- Admin menu qidiruv buffer
    searchBuf = nil,
    searchResult = nil
}

function FamilyTracker.initialize()
    FamilyTracker.configPath = UtilityManager.getConfigPath("family_tracker.ini")
    FamilyTracker.load()
    FamilyTracker.searchBuf = imgui.new.char[64]()
    UtilityManager.setBufferString(FamilyTracker.searchBuf, "")
end

function FamilyTracker.load()
    local saved = UtilityManager.safeIniLoad(FamilyTracker.configPath, "FamilyTracker load")
    FamilyTracker.db = {}
    if type(saved) ~= "table" then return end
    for key, section in pairs(saved) do
        if type(section) == "table" then
            local nick = UtilityManager.trim(tostring(section.nick or ""))
            local family = UtilityManager.trim(tostring(section.family or ""))
            local updatedAt = tonumber(section.updatedAt) or 0
            if nick ~= "" and family ~= "" then
                FamilyTracker.db[nick:lower()] = {
                    nick = nick,
                    family = family,
                    updatedAt = updatedAt
                }
            end
        end
    end
    if LogManager and LogManager.system then
        LogManager.system(string.format("[FamilyTracker] %d yozuv yuklandi.", FamilyTracker.countDb()))
    end
end

function FamilyTracker.save()
    local payload = {}
    local i = 1
    for _, entry in pairs(FamilyTracker.db) do
        payload["entry_" .. i] = {
            nick = tostring(entry.nick or ""),
            family = tostring(entry.family or ""),
            updatedAt = tostring(entry.updatedAt or 0)
        }
        i = i + 1
    end
    return UtilityManager.safeIniSave(payload, FamilyTracker.configPath)
end

function FamilyTracker.countDb()
    local n = 0
    for _ in pairs(FamilyTracker.db) do n = n + 1 end
    return n
end

-- ============================================================
-- FamilyLogger: kunlik log fayl (family_log_DD.MM.YYYY.txt)
-- ============================================================
FamilyLogger = {}

function FamilyLogger.getPath()
    local dateStamp = os.date("%d.%m.%Y")  -- masalan: 11.05.2026
    local baseDir = "."
    if type(getWorkingDirectory) == "function" then
        local ok, path = pcall(getWorkingDirectory)
        if ok and type(path) == "string" and path ~= "" then
            baseDir = path
        end
    end
    local candidates = {
        string.format("%s\\moonloader\\logs\\family_log_%s.txt", baseDir, dateStamp),
        string.format("%s\\logs\\family_log_%s.txt", baseDir, dateStamp),
        string.format("family_log_%s.txt", dateStamp)
    }
    for _, p in ipairs(candidates) do
        local f = io.open(p, "a")
        if f then
            f:close()
            return p
        end
    end
    return candidates[#candidates]
end

function FamilyLogger.write(nick, family, punishment)
    local path = FamilyLogger.getPath()
    if not path or path == "" then return end

    local f = io.open(path, "a")
    if not f then return end

    -- Fayl yangi (bo'sh) bo'lsa — sarlavha yoz
    local size = f:seek("end")
    if size == 0 then
        local dateStr = os.date("%d.%m.%Y")
        f:write(string.format("=== Sana: %s ===\n", dateStr))
        f:write(string.format("%-24s | %-20s | %-20s | %s\n",
            "Vaqt", "Nik", "Semya", "Jazo"))
        f:write(string.rep("-", 90) .. "\n")
    end

    local timeStr = os.date("%d.%m.%Y(%H:%M:%S)")
    local line = string.format("%-24s | %-20s | %-20s | %s\n",
        timeStr,
        tostring(nick       or "?"),
        tostring(family     or "?"),
        tostring(punishment or "?"))
    f:write(line)
    f:close()
end

-- FW jazo berilganda chaqiriladi: /stats ID yuboradi, keyin onDone() chaqiriladi
function FamilyTracker.triggerStatsRequest(playerId, nick, onDone, punishment)
    local id = tonumber(playerId)
    if not id or id < 0 then
        if type(onDone) == "function" then onDone() end
        return
    end
    FamilyTracker.pending[id] = {
        nick        = tostring(nick       or ""),
        punishment  = tostring(punishment or "N/A"),
        requestedAt = os.clock()
    }
    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(function()
            -- /stats yuborish
            if type(sendChat) == "function" then
                sendChat(string.format("/stats %d", id))
            end
            -- Dialog kelishi uchun 1200ms kutish
            wait(1200)
            -- Keyin jazo buyrug'ini bajarish
            if type(onDone) == "function" then
                pcall(onDone)
            end
        end)
    else
        -- lua_thread yo'q bo'lsa — to'g'ridan-to'g'ri chaqirish
        if type(sendChat) == "function" then
            sendChat(string.format("/stats %d", id))
        end
        if type(onDone) == "function" then onDone() end
    end
end

-- Dialog kelganda: "Oila:" qatorini qidiradi
function FamilyTracker.processStatsDialog(dialogId, style, title, button1, button2, text)
    if next(FamilyTracker.pending) == nil then return nil end

    local body = tostring(text or "")
    local header = tostring(title or "")

    -- Faqat "O'yin statistikasi" dialog ekanligini tekshirish
    local cleanHeader = header:gsub("{%x%x%x%x%x%x}", "")
    cleanHeader = UtilityManager.trim(cleanHeader):lower()
    local isStatsDialog = cleanHeader:find("statistika", 1, true) ~= nil
                       or cleanHeader:find("statistik", 1, true) ~= nil
                       or cleanHeader:find("o'yin stat", 1, true) ~= nil
                       or cleanHeader:find("stats", 1, true) ~= nil

    if not isStatsDialog then return nil end

    -- Pending'dan birinchi entry olish
    local matchedId = nil
    local matchedEntry = nil
    for pid, entry in pairs(FamilyTracker.pending) do
        matchedId = pid
        matchedEntry = entry
        break
    end

    if not matchedId or not matchedEntry then return nil end

    -- Qatorlarni tozalab massivga yig'amiz
    local lines = {}
    for line in body:gmatch("[^\r\n]+") do
        local clean = line:gsub("{%x%x%x%x%x%x}", "")
        clean = UtilityManager.trim(clean)
        if clean ~= "" then
            lines[#lines + 1] = clean
        end
    end

    -- "Oila:" qatorini qidirish (ikki formatda)
    local familyName = nil
    for i, line in ipairs(lines) do
        -- Format 1: "Oila:   Scorpion Squad" (bir qatorda, bo'sh joy/tab bilan)
        local f = line:match("[Oo]ila%s*:%s+(.+)$")
        if not f then
            -- Format 2: "Oila:" yolg'iz — keyingi qator = semya nomi
            if line:match("^[Oo]ila%s*:%s*$") and lines[i + 1] then
                f = lines[i + 1]
            end
        end
        if f then
            f = f:gsub("{%x%x%x%x%x%x}", "")
            f = UtilityManager.trim(f)
            if f ~= "" and f ~= "-" and f ~= "N/A" and f ~= "Yo'q" and f ~= "Yoq" then
                familyName = f
                break
            end
        end
    end

    -- Pending'dan o'chiramiz
    FamilyTracker.pending[matchedId] = nil

    if not familyName or familyName == "" then
        if LogManager and LogManager.system then
            LogManager.system(string.format(
                "[FamilyTracker] Stats dialog olindi, Oila: topilmadi (nick=%s)",
                tostring(matchedEntry.nick or "")))
        end
        return nil
    end

    -- DB ga saqlash (nik avval ham bo'lsa — faqat semya yangilanadi)
    local nick = UtilityManager.trim(tostring(matchedEntry.nick or ""))
    if nick == "" then return nil end

    FamilyTracker.db[nick:lower()] = {
        nick = nick,
        family = familyName,
        updatedAt = os.time()
    }
    FamilyTracker.save()

    -- SP panelda ko'rsatish uchun
    FamilyTracker.currentTargetFamily = familyName

    -- Kunlik log faylga yozish
    local punishment = tostring(matchedEntry.punishment or "N/A")
    if FamilyLogger and FamilyLogger.write then
        pcall(FamilyLogger.write, nick, familyName, punishment)
    end

    -- Chat xabar
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage(string.format("[FW] %s semyasi: %s", nick, familyName), 0x33DDFF)
    end

    return nil
end

-- SP panelda joriy target'ning semyasini yangilash
function FamilyTracker.refreshCurrentTarget()
    if not SpectateQuickPanel or not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        FamilyTracker.currentTargetFamily = ""
        return
    end
    local nick = tostring(SpectateQuickPanel.targetNick or "")
    if nick == "" then return end
    local entry = FamilyTracker.lookupByNick(nick)
    if entry then
        FamilyTracker.currentTargetFamily = tostring(entry.family or "")
    else
        FamilyTracker.currentTargetFamily = ""
    end
end

-- Admin menyuda semya qidiruv paneli render
function FamilyTracker.renderSearchPanel()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.2, 0.8, 1, 1), u8"SEMYA QIDIRUV")
    imgui.TextDisabled(u8"Nik yoki semya nomi bilan qidiring.")
    imgui.Separator()
    imgui.Spacing()

    -- Qidiruv inputi (KillList uslubida)
    imgui.SetNextItemWidth(-120)
    imgui.InputText(u8"Qidiruv##ft_search_input", FamilyTracker.searchBuf, 64)
    imgui.SameLine()
    if imgui.Button(u8"Tozalash##ft_clear_btn", imgui.ImVec2(110, 24)) then
        UtilityManager.setBufferString(FamilyTracker.searchBuf, "")
    end
    imgui.TextDisabled(u8"Nik yoki semya nomi bo'yicha qidiring.")

    -- Qidiruv so'rovini casefold qilish (UTF-8 / Kirill harflar uchun)
    local rawQuery = UtilityManager.bufferToString(FamilyTracker.searchBuf)
    local foldedQuery = UtilityManager.casefoldUtf8Cyrillic(UtilityManager.trim(rawQuery))

    -- DB dan mos yozuvlarni topish (real-time, har frame)
    local matched = {}
    for _, entry in pairs(FamilyTracker.db) do
        local nickFolded   = UtilityManager.casefoldUtf8Cyrillic(tostring(entry.nick   or ""))
        local familyFolded = UtilityManager.casefoldUtf8Cyrillic(tostring(entry.family or ""))
        if foldedQuery == ""
           or nickFolded:find(foldedQuery, 1, true)
           or familyFolded:find(foldedQuery, 1, true)
        then
            matched[#matched + 1] = entry
        end
    end

    -- Eng yangi oxirida bo'lishi uchun tartiblash
    table.sort(matched, function(a, b)
        return (tonumber(a.updatedAt) or 0) > (tonumber(b.updatedAt) or 0)
    end)

    imgui.Spacing()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.2, 0.8, 1, 1),
        string.format(u8"Topildi: %d ta  (Jami: %d ta)", #matched, FamilyTracker.countDb()))
    imgui.Separator()
    imgui.Spacing()

    -- Ro'yxat (scroll bilan)
    imgui.BeginChild("##ft_results_list", imgui.ImVec2(0, 0), false)

    if #matched == 0 then
        if foldedQuery ~= "" then
            imgui.TextColored(COLORS.DANGER or imgui.ImVec4(1, 0.3, 0.3, 1),
                u8"Hech narsa topilmadi.")
        else
            imgui.TextDisabled(u8"Ma'lumotlar bazasi bo'sh.")
        end
    else
        -- Jadval sarlavhasi
        local availW = math.max(300, imgui.GetContentRegionAvail().x)
        local col1W = math.floor(availW * 0.38)
        local col2W = math.floor(availW * 0.37)
        local col3W = math.floor(availW * 0.25)

        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.15, 0.05, 0.06, 0.6))
        imgui.BeginChild("##ft_table_header", imgui.ImVec2(0, 24), false)
        imgui.SetCursorPosX(6)
        imgui.TextColored(COLORS.TEXT_DIM or imgui.ImVec4(0.7, 0.7, 0.7, 1), u8"NIK")
        imgui.SameLine(col1W)
        imgui.TextColored(COLORS.TEXT_DIM or imgui.ImVec4(0.7, 0.7, 0.7, 1), u8"SEMYA")
        imgui.SameLine(col1W + col2W)
        imgui.TextColored(COLORS.TEXT_DIM or imgui.ImVec4(0.7, 0.7, 0.7, 1), u8"SANA")
        imgui.EndChild()
        imgui.PopStyleColor()

        -- Qatorlar
        for i, e in ipairs(matched) do
            local dateStr = e.updatedAt and tonumber(e.updatedAt) > 0
                and os.date("%d.%m %H:%M", tonumber(e.updatedAt))
                or "N/A"

            local rowBg = (i % 2 == 0)
                and imgui.ImVec4(0.09, 0.03, 0.04, 0.5)
                or  imgui.ImVec4(0.12, 0.04, 0.05, 0.4)

            imgui.PushStyleColor(imgui.Col.ChildBg, rowBg)
            imgui.BeginChild(string.format("##ft_row_%d", i), imgui.ImVec2(0, 22), false)
            imgui.SetCursorPosX(6)
            imgui.TextColored(
                COLORS.PRIMARY or imgui.ImVec4(0.2, 0.9, 0.4, 1),
                tostring(e.nick or ""))
            imgui.SameLine(col1W)
            imgui.TextColored(
                COLORS.WARNING or imgui.ImVec4(1, 0.85, 0.1, 1),
                tostring(e.family or ""))
            imgui.SameLine(col1W + col2W)
            imgui.TextDisabled(dateStr)
            imgui.EndChild()
            imgui.PopStyleColor()
        end
    end

    imgui.EndChild()
end

FwReturnTracker = {
    radius = 600.0,
    windowSec = 15 * 60,
    scanIntervalMs = 1000,
    deathHistoryByPlayerId = {},
    watchListByPlayerId = {},
    lastScanAtMs = 0
}

function FwReturnTracker.initialize()
    FwReturnTracker.clear()
end

function FwReturnTracker.isFwEnabled()
    return FwPunishmentManager and FwPunishmentManager.enabled == true
end

function FwReturnTracker.getNowSec()
    return (tonumber(UtilityManager.getNowMs()) or 0) / 1000.0
end

function FwReturnTracker.clear()
    FwReturnTracker.deathHistoryByPlayerId = {}
    FwReturnTracker.watchListByPlayerId = {}
    FwReturnTracker.lastScanAtMs = 0
end

function FwReturnTracker.getLocalPlayerId()
    if MainUI and type(MainUI.getLocalPlayerId) == "function" then
        return tonumber(MainUI.getLocalPlayerId())
    end
    if TekshiruvManager and type(TekshiruvManager.getLocalPlayerId) == "function" then
        return tonumber(TekshiruvManager.getLocalPlayerId())
    end
    return nil
end

function FwReturnTracker.getLocalCoords()
    if UtilityManager and type(UtilityManager.getPlayerCoords) == "function" then
        local okCoords, x, y, z = UtilityManager.getPlayerCoords()
        if okCoords then
            x = tonumber(x)
            y = tonumber(y)
            z = tonumber(z)
            if x and y and z then
                return x, y, z
            end
        end
    end
    return nil
end

function FwReturnTracker.getPlayerCoordsById(playerId)
    local numericId = tonumber(playerId)
    if not numericId or numericId < 0 then
        return nil
    end

    local ped = nil
    if MainUI and type(MainUI.getPlayerPedHandleById) == "function" then
        ped = MainUI.getPlayerPedHandleById(numericId)
    elseif ReportCatchManager and type(ReportCatchManager.getPlayerPedHandle) == "function" then
        ped = ReportCatchManager.getPlayerPedHandle(numericId)
    end

    ped = tonumber(ped)
    if not ped then
        return nil
    end

    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, ped)
        if okExists and not exists then
            return nil
        end
    end

    if type(getCharCoordinates) ~= "function" then
        return nil
    end

    local okCoords, a, b, c, d = pcall(getCharCoordinates, ped)
    if not okCoords then
        return nil
    end

    local x, y, z = nil, nil, nil
    if TeleportClickManager and type(TeleportClickManager.extractCoords) == "function" then
        x, y, z = TeleportClickManager.extractCoords(a, b, c, d)
    else
        if type(a) == "boolean" then
            if not a then
                return nil
            end
            x, y, z = tonumber(b), tonumber(c), tonumber(d)
        else
            x, y, z = tonumber(a), tonumber(b), tonumber(c)
        end
    end

    if not x or not y or not z then
        return nil
    end

    return x, y, z
end

function FwReturnTracker.getDistance3d(ax, ay, az, bx, by, bz)
    local dx = (tonumber(ax) or 0) - (tonumber(bx) or 0)
    local dy = (tonumber(ay) or 0) - (tonumber(by) or 0)
    local dz = (tonumber(az) or 0) - (tonumber(bz) or 0)
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function FwReturnTracker.pruneDeathHistory(playerId, now)
    local key = tostring(tonumber(playerId) or 0)
    local history = FwReturnTracker.deathHistoryByPlayerId[key]
    if type(history) ~= "table" then
        return {}
    end

    local minTime = (tonumber(now) or 0) - (tonumber(FwReturnTracker.windowSec) or 0)
    local filtered = {}
    for _, record in ipairs(history) do
        local deathTime = tonumber(record and record.deathTime) or 0
        if deathTime >= minTime then
            filtered[#filtered + 1] = record
        end
    end

    while #filtered > 4 do
        table.remove(filtered, 1)
    end

    if #filtered > 0 then
        FwReturnTracker.deathHistoryByPlayerId[key] = filtered
    else
        FwReturnTracker.deathHistoryByPlayerId[key] = nil
    end

    return filtered
end

function FwReturnTracker.armWatch(playerId, nick, now)
    local numericId = tonumber(playerId) or 0
    if numericId <= 0 then
        return nil
    end

    local key = tostring(numericId)
    local watch = FwReturnTracker.watchListByPlayerId[key] or {}
    watch.playerId = numericId
    watch.nickSnapshot = UtilityManager.trim(tostring(nick or watch.nickSnapshot or ""))
    if watch.nickSnapshot == "" then
        watch.nickSnapshot = string.format("ID_%d", numericId)
    end
    watch.armedAt = tonumber(now) or 0
    watch.expiresAt = (tonumber(now) or 0) + (tonumber(FwReturnTracker.windowSec) or 0)
    watch.notified = false
    watch.seenOutside = false
    FwReturnTracker.watchListByPlayerId[key] = watch
    return watch
end

function FwReturnTracker.pruneWatches(now)
    local currentTime = tonumber(now) or 0
    for key, watch in pairs(FwReturnTracker.watchListByPlayerId or {}) do
        local expiresAt = tonumber(watch and watch.expiresAt) or 0
        if expiresAt <= 0 or currentTime > expiresAt then
            FwReturnTracker.watchListByPlayerId[key] = nil
        end
    end
end

function FwReturnTracker.onPlayerDeathNotification(killerId, killedId, reason)
    if not FwReturnTracker.isFwEnabled() then
        return
    end

    local victimId = tonumber(killedId) or -1
    if victimId < 0 then
        return
    end

    local localPlayerId = FwReturnTracker.getLocalPlayerId()
    if localPlayerId and victimId == localPlayerId then
        return
    end

    if not UtilityManager.isPlayerConnected(victimId) then
        return
    end

    local localX, localY, localZ = FwReturnTracker.getLocalCoords()
    if not localX then
        return
    end

    local victimX, victimY, victimZ = FwReturnTracker.getPlayerCoordsById(victimId)
    if not victimX then
        return
    end

    local distance = FwReturnTracker.getDistance3d(localX, localY, localZ, victimX, victimY, victimZ)
    if distance > (tonumber(FwReturnTracker.radius) or 600.0) then
        return
    end

    local now = FwReturnTracker.getNowSec()
    local nick = UtilityManager.getPlayerNicknameSafe(victimId, string.format("ID_%d", victimId))
    local key = tostring(victimId)
    local history = FwReturnTracker.deathHistoryByPlayerId[key]
    if type(history) ~= "table" then
        history = {}
        FwReturnTracker.deathHistoryByPlayerId[key] = history
    end

    history[#history + 1] = {
        playerId = victimId,
        nickSnapshot = tostring(nick or ""),
        deathTime = now,
        distanceAtDeath = distance
    }

    history = FwReturnTracker.pruneDeathHistory(victimId, now)
    if #history >= 2 then
        local previousWatch = FwReturnTracker.watchListByPlayerId[key]
        local shouldLogArm = not previousWatch or tonumber(previousWatch.expiresAt or 0) < now or previousWatch.notified == true
        local watch = FwReturnTracker.armWatch(victimId, nick, now)
        if shouldLogArm and watch and LogManager and type(LogManager.system) == "function" then
            LogManager.system(string.format(
                "FW return tracker armed: %s [%d] | nearby deaths=%d | radius=%.1fm",
                tostring(watch.nickSnapshot or ""),
                victimId,
                #history,
                tonumber(distance) or 0
            ))
        end
    end
end

function FwReturnTracker.update()
    if not FwReturnTracker.isFwEnabled() then
        if next(FwReturnTracker.deathHistoryByPlayerId) or next(FwReturnTracker.watchListByPlayerId) then
            FwReturnTracker.clear()
        end
        return
    end

    local nowMs = tonumber(UtilityManager.getNowMs()) or 0
    if (nowMs - (tonumber(FwReturnTracker.lastScanAtMs) or 0)) < (tonumber(FwReturnTracker.scanIntervalMs) or 1000) then
        return
    end
    FwReturnTracker.lastScanAtMs = nowMs

    local now = nowMs / 1000.0
    for playerKey in pairs(FwReturnTracker.deathHistoryByPlayerId or {}) do
        FwReturnTracker.pruneDeathHistory(playerKey, now)
    end
    FwReturnTracker.pruneWatches(now)

    local localX, localY, localZ = FwReturnTracker.getLocalCoords()
    if not localX then
        return
    end

    for key, watch in pairs(FwReturnTracker.watchListByPlayerId or {}) do
        if type(watch) ~= "table" then
            FwReturnTracker.watchListByPlayerId[key] = nil
        elseif watch.notified ~= true then
            local victimId = tonumber(watch.playerId) or 0
            if victimId <= 0 then
                FwReturnTracker.watchListByPlayerId[key] = nil
            elseif not UtilityManager.isPlayerConnected(victimId) then
                watch.seenOutside = true
            else
                local nick = UtilityManager.getPlayerNicknameSafe(victimId, watch.nickSnapshot or string.format("ID_%d", victimId))
                if UtilityManager.trim(nick) ~= "" then
                    watch.nickSnapshot = nick
                end

                local victimX, victimY, victimZ = FwReturnTracker.getPlayerCoordsById(victimId)
                if not victimX then
                    watch.seenOutside = true
                else
                    local distance = FwReturnTracker.getDistance3d(localX, localY, localZ, victimX, victimY, victimZ)
                    if distance > (tonumber(FwReturnTracker.radius) or 600.0) then
                        watch.seenOutside = true
                    elseif watch.seenOutside == true and now <= (tonumber(watch.expiresAt) or 0) then
                        watch.notified = true
                        if type(sampAddChatMessage) == "function" then
                            sampAddChatMessage(string.format(
                                "[GMEA][FW] Qaytdi: %s [%d] 600m radiusga kirdi.",
                                tostring(watch.nickSnapshot or ("ID_" .. tostring(victimId))),
                                victimId
                            ), 0x33CCFF)
                        end
                        if LogManager and type(LogManager.system) == "function" then
                            LogManager.system(string.format(
                                "FW return detected: %s [%d] returned within %.0fs window.",
                                tostring(watch.nickSnapshot or ""),
                                victimId,
                                tonumber(FwReturnTracker.windowSec) or 0
                            ))
                        end
                    end
                end
            end
        end
    end
end

function SpectateQuickPanel.start(playerId)
    local id = tonumber(playerId)
    if not id then return end

    SpectateQuickPanel.active = true
    SpectateQuickPanel.targetId = id
    SpectateQuickPanel.cursorVisible = true
    SpectateQuickPanel.rightMouseLastState = false
    SpectateQuickPanel.spaceLastState = false
    SpectateQuickPanel.rightMouseToggleRequested = false
    SpectateQuickPanel.reportReviewMode = false
    SpectateQuickPanel.reportAnswerId = nil
    SpectateQuickPanel.showTemplatePicker = false
    SpectateQuickPanel.showTaqiqPicker = false
    SpectateQuickPanel.showTpCarModePicker = false
    SpectateQuickPanel.tpCarBusy = false
    SpectateQuickPanel.getCarBusy = false
    SpectateQuickPanel.setFuelBusy = false
    SpectateQuickPanel.moderationMode = "none"

    if UtilityManager.isPlayerConnected(id) then
        SpectateQuickPanel.targetNick = UtilityManager.getPlayerNicknameSafe(id, "")
    else
        SpectateQuickPanel.targetNick = ""
    end
end

function SpectateQuickPanel.stop()
    AutoPunishmentManager.flushUiSave(true)
    FwPunishmentManager.flushUiSave(true)
    SpectateQuickPanel.active = false
    SpectateQuickPanel.targetId = nil
    SpectateQuickPanel.targetNick = ""
    SpectateQuickPanel.cursorVisible = true
    SpectateQuickPanel.rightMouseLastState = false
    SpectateQuickPanel.spaceLastState = false
    SpectateQuickPanel.rightMouseToggleRequested = false
    SpectateQuickPanel.reportReviewMode = false
    SpectateQuickPanel.reportAnswerId = nil
    SpectateQuickPanel.showTemplatePicker = false
    SpectateQuickPanel.showTaqiqPicker = false
    SpectateQuickPanel.showTpCarModePicker = false
    SpectateQuickPanel.tpCarBusy = false
    SpectateQuickPanel.getCarBusy = false
    SpectateQuickPanel.setFuelBusy = false
    SpectateQuickPanel.moderationMode = "none"
end

function SpectateQuickPanel.enableReportReviewMode(reportAnswerId)
    local id = tonumber(reportAnswerId)
    if not id then return end
    SpectateQuickPanel.reportReviewMode = true
    SpectateQuickPanel.reportAnswerId = id
end

function SpectateQuickPanel.clearReportReviewMode()
    SpectateQuickPanel.reportReviewMode = false
    SpectateQuickPanel.reportAnswerId = nil
end

function SpectateQuickPanel.ensureFormState()
    if SpectateQuickPanel.form then
        return
    end

    SpectateQuickPanel.form = {
        jailMinutes = imgui.ImInt(60),
        banDays = imgui.ImInt(3),
        muteMinutes = imgui.ImInt(60),
        rmuteMinutes = imgui.ImInt(60),
        jailReason = imgui.new.char[128](),
        banReason = imgui.new.char[128](),
        warnReason = imgui.new.char[128](),
        muteReason = imgui.new.char[128](),
        rmuteReason = imgui.new.char[128](),
        runmuteReason = imgui.new.char[128](),
        unmuteReason = imgui.new.char[128](),
        skickReason = imgui.new.char[128]()
    }
end

function SpectateQuickPanel.getReasonFromBuffer(buf, fallback)
    local value = UtilityManager.trim(UtilityManager.bufferToString(buf) or "")
    if value == "" then
        return fallback or "No reason"
    end
    return value
end

function SpectateQuickPanel.getCommandReasonFromBuffer(buf, fallback)
    local reason = SpectateQuickPanel.getReasonFromBuffer(buf, fallback)
    return UtilityManager.toGameEncoding(reason)
end

function SpectateQuickPanel.getSharedReplyTemplates()
    if ReportCatchManager and ReportCatchManager.templates then
        return ReportCatchManager.templates
    end
    return {}
end

function SpectateQuickPanel.resolveAnswerId()
    local fromSpec = tonumber(SpectateQuickPanel.reportAnswerId)
    if fromSpec and fromSpec > 0 then
        return fromSpec
    end

    if ReportCatchManager and ReportCatchManager.currentReport then
        local fromCurrent = tonumber(ReportCatchManager.currentReport.id)
        if fromCurrent and fromCurrent > 0 then
            return fromCurrent
        end
    end

    if ReportCatchManager and ReportCatchManager.waitingReportId then
        local fromWaiting = tonumber(ReportCatchManager.waitingReportId)
        if fromWaiting and fromWaiting > 0 then
            return fromWaiting
        end
    end

    return nil
end

function SpectateQuickPanel.resolveTemplateTargetId()
    return SpectateQuickPanel.resolveAnswerId()
end

function SpectateQuickPanel.toggleTemplatePicker()
    SpectateQuickPanel.showTemplatePicker = not SpectateQuickPanel.showTemplatePicker
end

function SpectateQuickPanel.toggleTaqiqPicker()
    SpectateQuickPanel.showTaqiqPicker = not SpectateQuickPanel.showTaqiqPicker
    if SpectateQuickPanel.showTaqiqPicker then
        SpectateQuickPanel.showTemplatePicker = true
    end
end

function SpectateQuickPanel.sendTaqiqRandomReply()
    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("admin.chat") then
        PermissionGuard.logBlocked("admin.chat", "admin.chat")
        return
    end
    if not ReportCatchManager or not ReportCatchManager.getFixedEvakuatorReplyText then
        return
    end

    local payload = UtilityManager.trim(tostring(ReportCatchManager.getFixedEvakuatorReplyText() or ""))
    if payload == "" then
        sampAddChatMessage("[GMEA] Taqiq javobi bo'sh.", 0xFF6666)
        return
    end

    SpectateQuickPanel.showTaqiqPicker = false
    sendChat(string.format("/n %s", payload))
    LogManager.admin(string.format("Quick panel: /n %s", payload))
end

function SpectateQuickPanel.getTaqiqReplyVariants()
    local fixedReply = ReportCatchManager and ReportCatchManager.getFixedEvakuatorReplyText and
        ReportCatchManager.getFixedEvakuatorReplyText() or
        "Assalomu alaykum, spidometrdagi evakuator tugmasiga bosing"
    fixedReply = UtilityManager.trim(tostring(fixedReply or ""))
    if fixedReply == "" then
        return {}
    end
    return { fixedReply }
end

function SpectateQuickPanel.sendDirectReplyText(replyText, logTag)
    local targetId = SpectateQuickPanel.resolveTemplateTargetId()
    if not targetId then
        sampAddChatMessage("[GMEA] Javob yuborish uchun report ID topilmadi.", 0xFF6666)
        return
    end
    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("report.reply") then
        PermissionGuard.logBlocked("report.reply", "report.reply")
        return
    end

    local payload = UtilityManager.trim(tostring(replyText or ""))
    if payload == "" then
        return
    end

    sendChat(string.format("/ans %d %s", targetId, payload))
    LogManager.report(string.format(
        "Spectate direct reply sent: report #%d (%s)",
        targetId,
        tostring(logTag or "custom")
    ))

    if ReportCatchManager and ReportCatchManager.markAnswered then
        ReportCatchManager.markAnswered(targetId)
    end
    if ReportCatchManager and ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == tonumber(targetId) and
       ReportCatchManager.closePopup then
        ReportCatchManager.closePopup()
    end
end

function SpectateQuickPanel.sendTaqiqReply(index)
    local variants = SpectateQuickPanel.getTaqiqReplyVariants()
    local picked = variants[tonumber(index) or 0]
    if not picked then
        return
    end
    SpectateQuickPanel.sendDirectReplyText(picked, "taqiq_variant_" .. tostring(index))
end

function SpectateQuickPanel.sendSlap()
    local id = tonumber(SpectateQuickPanel.targetId)
    if not id then return end

    sendChat(string.format("/slap %d", id))
    LogManager.admin(string.format("Quick panel: /slap %d", id))
end

function SpectateQuickPanel.sendSharedTemplateReply(templateId)
    local targetId = SpectateQuickPanel.resolveTemplateTargetId()
    if not targetId then
        sampAddChatMessage("[GMEA] Javob yuborish uchun SP target ID topilmadi.", 0xFF6666)
        return
    end
    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("report.reply") then
        PermissionGuard.logBlocked("report.reply", "report.reply")
        return
    end
    if PermissionGuard and PermissionGuard.canUseTemplate and
       not PermissionGuard.canUseTemplate(templateId) then
        PermissionGuard.logBlocked("report.template:" .. tostring(templateId), "report.reply")
        return
    end

    local templates = SpectateQuickPanel.getSharedReplyTemplates()
    local picked = nil
    for _, template in ipairs(templates) do
        if tonumber(template.id) == tonumber(templateId) then
            picked = template
            break
        end
    end

    if not picked then
        return
    end

    sendChat(string.format("/ans %d %s", targetId, picked.text or ""))
    LogManager.report(string.format(
        "Spectate template reply sent: player #%d via template #%d",
        targetId,
        tonumber(picked.id) or 0))

    if ReportCatchManager and ReportCatchManager.markAnswered then
        ReportCatchManager.markAnswered(targetId)
    end
    if ReportCatchManager and ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == tonumber(targetId) and
       ReportCatchManager.closePopup then
        ReportCatchManager.closePopup()
    end
end

function SpectateQuickPanel.openModerationMode(mode)
    SpectateQuickPanel.ensureFormState()
    SpectateQuickPanel.moderationMode = mode or "none"
end

function SpectateQuickPanel.applyJailToTarget()
    local id = tonumber(SpectateQuickPanel.targetId)
    if not id then return end
    SpectateQuickPanel.ensureFormState()

    local minutes = tonumber(SpectateQuickPanel.form.jailMinutes[0]) or 60
    minutes = math.max(1, minutes)
    local reason = SpectateQuickPanel.getCommandReasonFromBuffer(SpectateQuickPanel.form.jailReason, "DM")

    sendChat(string.format("/jail %d %d %s", id, minutes, reason))
    LogManager.admin(string.format("Quick panel: /jail %d %d %s", id, minutes, UtilityManager.toUtf8(reason)))
end

function SpectateQuickPanel.applyBanToTarget()
    local id = tonumber(SpectateQuickPanel.targetId)
    if not id then return end
    SpectateQuickPanel.ensureFormState()

    local days = tonumber(SpectateQuickPanel.form.banDays[0]) or 1
    days = math.max(1, days)
    local reason = SpectateQuickPanel.getCommandReasonFromBuffer(SpectateQuickPanel.form.banReason, "Ban")

    sendChat(string.format("/ban %d %d %s", id, days, reason))
    LogManager.admin(string.format("Quick panel: /ban %d %d %s", id, days, UtilityManager.toUtf8(reason)))
end

function SpectateQuickPanel.applyWarnToTarget()
    local id = tonumber(SpectateQuickPanel.targetId)
    if not id then return end
    SpectateQuickPanel.ensureFormState()

    local reason = SpectateQuickPanel.getCommandReasonFromBuffer(SpectateQuickPanel.form.warnReason, "Warn")

    sendChat(string.format("/warn %d %s", id, reason))
    LogManager.admin(string.format("Quick panel: /warn %d %s", id, UtilityManager.toUtf8(reason)))
end

function SpectateQuickPanel.applyMuteToTarget()
    local id = tonumber(SpectateQuickPanel.targetId)
    if not id then return end
    SpectateQuickPanel.ensureFormState()

    local minutes = tonumber(SpectateQuickPanel.form.muteMinutes[0]) or 60
    minutes = math.max(1, minutes)
    local reason = SpectateQuickPanel.getCommandReasonFromBuffer(SpectateQuickPanel.form.muteReason, "Mute")

    sendChat(string.format("/mute %d %d %s", id, minutes, reason))
    LogManager.admin(string.format("Quick panel: /mute %d %d %s", id, minutes, UtilityManager.toUtf8(reason)))
end

