function PlayerManager.getOnlineList(force)
    local nowMs = UtilityManager.getNowMs()
    if not force and (nowMs - (PlayerManager.lastListUpdateMs or 0)) < (PlayerManager.listRefreshMs or 300) then
        return PlayerManager.onlineList
    end

    local list = {}
    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        return PlayerManager.onlineList or list
    end
    local okMax, maxId = pcall(sampGetMaxPlayerId, false)
    maxId = okMax and tonumber(maxId) or -1
    if maxId < 0 then
        return PlayerManager.onlineList or list
    end
    for i = 0, maxId do
        local okConn, connected = pcall(sampIsPlayerConnected, i)
        if okConn and connected then
            local okNick, nick = pcall(sampGetPlayerNickname, i)
            local score = 0
            if type(sampGetPlayerScore) == "function" then
                local okScore, value = pcall(sampGetPlayerScore, i)
                score = okScore and tonumber(value) or 0
            end
            local ping = 0
            if type(sampGetPlayerPing) == "function" then
                local okPing, value = pcall(sampGetPlayerPing, i)
                ping = okPing and tonumber(value) or 0
            end
            table.insert(list, {
                id = i,
                name = okNick and tostring(nick or "Unknown") or "Unknown",
                score = score,
                ping = ping
            })
        end
    end
    PlayerManager.onlineList = list
    PlayerManager.lastListUpdateMs = nowMs
    return list
end

function PlayerManager.getAdminList()
    if AdminCheckerManager and type(AdminCheckerManager.getFlatList) == "function" then
        return AdminCheckerManager.getFlatList()
    end
    return {}
end



