BOOT_LOGGER.write("Inlining module: admin/admin_security_log.lua")
do
-- ============================================
-- PLAYER LOG MANAGER
-- ============================================
AdminSecurityLog = {
    entries = {},
    maxEntries = CONFIG.LIMITS.ADMIN_SECURITY_LOG or 200
}

function AdminSecurityLog.add(action, targetId, reason, adminName)
    local numericId = tonumber(targetId)
    local label = tostring(targetId or "0")
    if numericId and numericId > 0 and type(sampGetPlayerNickname) == "function" then
        local okNick, nick = pcall(sampGetPlayerNickname, numericId)
        if okNick and nick and tostring(nick) ~= "" then
            label = string.format("%s[%d]", tostring(nick), numericId)
        end
    end
    local entry = {
        ts = os.time(),
        admin = tostring(adminName or "You"),
        action = tostring(action or "Action"),
        target = numericId or 0,
        targetLabel = label,
        reason = tostring(reason or "")
    }
    table.insert(AdminSecurityLog.entries, 1, entry)
    if #AdminSecurityLog.entries > AdminSecurityLog.maxEntries then
        table.remove(AdminSecurityLog.entries)
    end
end


end

