BOOT_LOGGER.write("Inlining module: admin/admin_history_tracker.lua")
do
AdminHistoryTracker = {
    maxEntries = CONFIG.LIMITS.ADMIN_HISTORY or 200
}

function AdminHistoryTracker.add(action, targetId, reason)
    local adminName = AdminSession.getAdminName()
    if AdminSecurityLog then
        AdminSecurityLog.maxEntries = AdminHistoryTracker.maxEntries
        AdminSecurityLog.add(action, targetId, reason or "", adminName)
    end
end

function AdminHistoryTracker.renderTable()
    local entries = AdminSecurityLog and AdminSecurityLog.entries or {}
    local rowHeight = (imgui.GetTextLineHeightWithSpacing and imgui.GetTextLineHeightWithSpacing() or 18)

    if imgui.BeginTable then
        local tableFlags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##admin_history_table", 4, tableFlags) then
            imgui.TableSetupColumn("Time")
            imgui.TableSetupColumn("Admin")
            imgui.TableSetupColumn("Action")
            imgui.TableSetupColumn("Target")
            imgui.TableHeadersRow()

            if imgui.ImGuiListClipper then
                local clipper = imgui.ImGuiListClipper()
                clipper:Begin(#entries, rowHeight)
                while clipper:Step() do
                    for i = clipper.DisplayStart, clipper.DisplayEnd - 1 do
                        local entry = entries[i + 1]
                        if entry then
                            imgui.TableNextRow()
                            imgui.TableSetColumnIndex(0); imgui.Text(os.date("%H:%M", entry.ts or os.time()))
                            imgui.TableSetColumnIndex(1); imgui.Text(tostring(entry.admin))
                            imgui.TableSetColumnIndex(2); imgui.Text(tostring(entry.action))
                            imgui.TableSetColumnIndex(3); imgui.Text(tostring(entry.targetLabel or entry.target))
                        end
                    end
                end
                clipper:End()
            else
                for _, entry in ipairs(entries) do
                    imgui.TableNextRow()
                    imgui.TableSetColumnIndex(0); imgui.Text(os.date("%H:%M", entry.ts or os.time()))
                    imgui.TableSetColumnIndex(1); imgui.Text(tostring(entry.admin))
                    imgui.TableSetColumnIndex(2); imgui.Text(tostring(entry.action))
                    imgui.TableSetColumnIndex(3); imgui.Text(tostring(entry.targetLabel or entry.target))
                end
            end
            imgui.EndTable()
        end
    else
        imgui.Columns(4, "##admin_history_cols", true)
        imgui.Text("Time"); imgui.NextColumn()
        imgui.Text("Admin"); imgui.NextColumn()
        imgui.Text("Action"); imgui.NextColumn()
        imgui.Text("Target"); imgui.NextColumn()
        for _, entry in ipairs(entries) do
            imgui.Text(os.date("%H:%M", entry.ts or os.time())); imgui.NextColumn()
            imgui.Text(tostring(entry.admin)); imgui.NextColumn()
            imgui.Text(tostring(entry.action)); imgui.NextColumn()
            imgui.Text(tostring(entry.targetLabel or entry.target)); imgui.NextColumn()
        end
        imgui.Columns(1)
    end
end


end

BOOT_LOGGER.write("Inlining module: input/quick_action_hotkeys.lua")
do
QuickActionHotkeys = {
    lastState = {}
}

function QuickActionHotkeys.wasKeyPressed(key)
    if type(isKeyJustPressed) == "function" then
        local ok, val = pcall(isKeyJustPressed, key)
        return ok and val == true
    end
    if type(wasKeyPressed) == "function" then
        local ok, val = pcall(wasKeyPressed, key)
        return ok and val == true
    end
    if type(isKeyDown) ~= "function" then
        return false
    end
    local ok, down = pcall(isKeyDown, key)
    down = ok and down == true
    local prev = QuickActionHotkeys.lastState[key] == true
    QuickActionHotkeys.lastState[key] = down
    return down and not prev
end

function QuickActionHotkeys.update(chatActive, dialogActive)
    if not SettingsManager or not SettingsManager.get then
        return
    end
    if SettingsManager.get("quickHotkeysEnabled") == false then
        return
    end
    if chatActive or dialogActive then
        return
    end
    if not AdminSession.isAdminActive() then
        return
    end
    if type(isKeyDown) ~= "function" then
        return
    end

    local modifier = tonumber(SettingsManager.get("quickHotkeyModifier")) or vkeys.VK_MENU
    local okAlt, altDown = pcall(isKeyDown, modifier)
    if not okAlt or not altDown then
        return
    end

    local targetId = AdminSelection.getSelectedPlayerId()
    if not targetId or targetId <= 0 then
        return
    end
    local targetNick = AdminSelection.getSelectedNick(targetId)

    local specKey = tonumber(SettingsManager.get("quickHotkeySpec")) or vkeys.VK_1
    local tpKey = tonumber(SettingsManager.get("quickHotkeyTeleport")) or vkeys.VK_2
    local freezeKey = tonumber(SettingsManager.get("quickHotkeyFreeze")) or vkeys.VK_3
    local jailKey = tonumber(SettingsManager.get("quickHotkeyJail")) or vkeys.VK_4

    if QuickActionHotkeys.wasKeyPressed(specKey) then
        if PlayerManager then
            PlayerManager.spectate(targetId)
        end
        AdminHistoryTracker.add("Spectate", targetId, targetNick)
    elseif QuickActionHotkeys.wasKeyPressed(tpKey) then
        if PlayerManager then
            PlayerManager.teleportTo(targetId)
        end
        AdminHistoryTracker.add("Teleport", targetId, targetNick)
    elseif QuickActionHotkeys.wasKeyPressed(freezeKey) then
        if PlayerManager then
            PlayerManager.freeze(targetId)
        end
        AdminHistoryTracker.add("Freeze", targetId, targetNick)
    elseif QuickActionHotkeys.wasKeyPressed(jailKey) then
        if PlayerManager then
            PlayerManager.jail(targetId, 10, "Quick hotkey")
        end
        AdminHistoryTracker.add("Jail", targetId, targetNick)
    end
end


end

