    hotkeyFlipFix = vkeys and vkeys.VK_8 or 0x38,
    hotkeyVehicleGetCar = vkeys and vkeys.VK_1 or 0x31,
    hotkeyModifier = vkeys and vkeys.VK_MENU or 0x12,
