    lastGetHereDown = false,
    lastSlapDown = false,
    lastSkickDown = false,
    lastFlipFixDown = false,
    lastVehicleGetCarDown = false,
    pendingSpectateTargetId = nil,
    pendingSpectateUntil = 0,
    suppressRenderUntil = 0,
    getCarBusy = false,
    target = nil,
    segments = 72,
    thickness = 1.8
}

function TargetCircleOverlay.initialize()
    TargetCircleOverlay.loadFromSettings()
end

function TargetCircleOverlay.loadFromSettings()
    TargetCircleOverlay.enabled = SettingsManager.get("targetCircleEnabled") == true
    TargetCircleOverlay.minRadius = UtilityManager.clamp(math.floor(tonumber(SettingsManager.get("targetCircleMinRadius")) or 64), 32, 400)
    TargetCircleOverlay.maxRadius = UtilityManager.clamp(math.floor(tonumber(SettingsManager.get("targetCircleMaxRadius")) or 260), 48, 600)
    if TargetCircleOverlay.maxRadius < TargetCircleOverlay.minRadius then
        TargetCircleOverlay.maxRadius = TargetCircleOverlay.minRadius
    end
    TargetCircleOverlay.radius = UtilityManager.clamp(
        math.floor(tonumber(SettingsManager.get("targetCircleRadius")) or 140),
        TargetCircleOverlay.minRadius,
        TargetCircleOverlay.maxRadius
    )
end

function TargetCircleOverlay.saveToSettings()
    SettingsManager.set("targetCircleEnabled", TargetCircleOverlay.enabled)
    SettingsManager.set("targetCircleRadius", TargetCircleOverlay.radius)
    SettingsManager.set("targetCircleMinRadius", TargetCircleOverlay.minRadius)
    SettingsManager.set("targetCircleMaxRadius", TargetCircleOverlay.maxRadius)
    SettingsManager.save()
end

function TargetCircleOverlay.isFeatureAvailable()
    if not isSampAvailable then
        return false
    end
    local ok, available = pcall(isSampAvailable)
    if not ok or available ~= true then
        return false
    end
    return TargetCircleOverlay.isLocalPlayerReady()
end

function TargetCircleOverlay.isOverlayVisible()
    return TargetCircleOverlay.isFeatureAvailable() and TargetCircleOverlay.enabled == true
end

function TargetCircleOverlay.isRenderBlocked()
    if (os.clock() or 0) < tonumber(TargetCircleOverlay.suppressRenderUntil or 0) then
        return true
    end
    if type(sampIsChatInputActive) == "function" then
        local okChat, chatActive = pcall(sampIsChatInputActive)
        if okChat and chatActive == true then
            return true
        end
    end
    if type(sampIsDialogActive) == "function" then
        local okDialog, dialogActive = pcall(sampIsDialogActive)
        if okDialog and dialogActive == true then
            return true
        end
    end
    if type(isPauseMenuActive) == "function" then
        local okPause, pauseActive = pcall(isPauseMenuActive)
        if okPause and pauseActive == true then
            return true
        end
    end
    if MainUI and MainUI.window and MainUI.window.open then
        return true
    end
    if ReportCatchManager and ReportCatchManager.popupOpen then
        return true
    end
    if AdminRelayManager and AdminRelayManager.popupOpen then
        return true
    end
    if SpectateQuickPanel and SpectateQuickPanel.active and SpectateQuickPanel.cursorVisible then
        return true
    end
    if FarmAnswerTool and FarmAnswerTool.open then
        return true
    end
    if AdminCheckerManager and AdminCheckerManager.placementActive == true then
        return true
    end
    return false
end

function TargetCircleOverlay.getDrawList()
    local drawList = nil
    if imgui.GetBackgroundDrawList then
        local okDraw, value = pcall(imgui.GetBackgroundDrawList)
        if okDraw then
            drawList = value
        end
    end
    if (not drawList) and imgui.GetForegroundDrawList then
        local okDraw, value = pcall(imgui.GetForegroundDrawList)
        if okDraw then
            drawList = value
        end
    end
    return drawList
end

function TargetCircleOverlay.getCenter()
    local sx, sy = getScreenResolution()
    sx = tonumber(sx) or 1920
    sy = tonumber(sy) or 1080
    return sx * 0.5, sy * 0.5, sx, sy
end

function TargetCircleOverlay.getIoMouseWheel()
    if not imgui or type(imgui.GetIO) ~= "function" then
        return 0
    end
    local okIo, io = pcall(imgui.GetIO)
    if not okIo or not io then
        return 0
    end
    return tonumber(io.MouseWheel) or 0
end

function TargetCircleOverlay.getTextSize(text)
    local safeText = tostring(text or "")
    if imgui and type(imgui.CalcTextSize) == "function" then
        local okSize, size = pcall(imgui.CalcTextSize, safeText)
        if okSize and size then
            return tonumber(size.x) or 0, tonumber(size.y) or 0
        end
    end
    return #safeText * 7, 14
end

function TargetCircleOverlay.drawShadowedText(drawList, x, y, color, text)
    if not drawList or type(drawList.AddText) ~= "function" then
        return
    end
    local safeText = tostring(text or "")
    local shadow = MainUI and MainUI.colorToU32 and MainUI.colorToU32(imgui.ImVec4(0, 0, 0, 0.86)) or 0xDD000000
    local textColor = MainUI and MainUI.colorToU32 and MainUI.colorToU32(color or COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1)) or 0xFFFFFFFF
    drawList:AddText(imgui.ImVec2(x + 1, y + 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(x - 1, y + 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(x + 1, y - 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(x - 1, y - 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(x, y), textColor, safeText)
end

function TargetCircleOverlay.drawCenteredText(drawList, centerX, y, color, text)
    local width = select(1, TargetCircleOverlay.getTextSize(text))
    TargetCircleOverlay.drawShadowedText(drawList, centerX - width * 0.5, y, color, text)
end

function TargetCircleOverlay.drawCircleOutline(drawList, centerX, centerY, radius, colorU32)
    if not drawList then
        return false
    end
    if type(drawList.AddCircle) == "function" then
        drawList:AddCircle(imgui.ImVec2(centerX, centerY), radius, colorU32, TargetCircleOverlay.segments, TargetCircleOverlay.thickness)
        return true
    end
    if type(drawList.AddLine) ~= "function" then
        return false
    end

    local segments = math.max(24, tonumber(TargetCircleOverlay.segments) or 72)
    local step = (math.pi * 2) / segments
    local previousX = centerX + radius
    local previousY = centerY
    for index = 1, segments do
        local angle = step * index
        local nextX = centerX + math.cos(angle) * radius
        local nextY = centerY + math.sin(angle) * radius
        drawList:AddLine(
            imgui.ImVec2(previousX, previousY),
            imgui.ImVec2(nextX, nextY),
            colorU32,
            TargetCircleOverlay.thickness
        )
        previousX = nextX
        previousY = nextY
    end
    return true
end

function TargetCircleOverlay.notify(message, color)
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage("[GMEA] " .. tostring(message or ""), color or 0x33CCFF)
    end
end

function TargetCircleOverlay.toggle()
    TargetCircleOverlay.enabled = not TargetCircleOverlay.enabled
    if TargetCircleOverlay.enabled then
        TargetCircleOverlay.targetMode = "player"
        TargetCircleOverlay.lastSpawnDown = false
        TargetCircleOverlay.lastRgunDown = false
        TargetCircleOverlay.lastSpecDown = false
        TargetCircleOverlay.lastStatsDown = false
        TargetCircleOverlay.lastGetHereDown = false
        TargetCircleOverlay.lastSlapDown = false
        TargetCircleOverlay.lastSkickDown = false
        TargetCircleOverlay.lastFlipFixDown = false
        TargetCircleOverlay.lastVehicleGetCarDown = false
        TargetCircleOverlay.target = nil
    else
        TargetCircleOverlay.target = nil
    end
    TargetCircleOverlay.saveToSettings()
    TargetCircleOverlay.notify(
        string.format(
            "Target Circle: %s%s",
            TargetCircleOverlay.enabled and "ON" or "OFF",
            TargetCircleOverlay.enabled and " [PLAYER]" or ""
        ),
        TargetCircleOverlay.enabled and 0x33FF66 or 0xFFAA66
    )
end

function TargetCircleOverlay.switchMode()
    if not TargetCircleOverlay.enabled then
        return false
    end
    if tostring(TargetCircleOverlay.targetMode or "player") == "vehicle" then
        TargetCircleOverlay.targetMode = "player"
    else
        TargetCircleOverlay.targetMode = "vehicle"
    end
    TargetCircleOverlay.lastSpawnDown = false
    TargetCircleOverlay.lastRgunDown = false
    TargetCircleOverlay.lastSpecDown = false
    TargetCircleOverlay.lastStatsDown = false
    TargetCircleOverlay.lastGetHereDown = false
    TargetCircleOverlay.lastSlapDown = false
    TargetCircleOverlay.lastSkickDown = false
    TargetCircleOverlay.lastFlipFixDown = false
    TargetCircleOverlay.lastVehicleGetCarDown = false
    TargetCircleOverlay.target = nil
    TargetCircleOverlay.notify(
        string.format("Target Circle mode: %s", tostring(TargetCircleOverlay.targetMode or "player"):upper()),
        0x33CCFF
    )
    return true
end

function TargetCircleOverlay.isUiInputBlocked(chatActive, dialogActive)
    if chatActive or dialogActive then
        return true
    end
    if MainUI and MainUI.window and MainUI.window.open then
        return true
    end
    if ReportCatchManager and ReportCatchManager.popupOpen then
        return true
    end
    if AdminRelayManager and AdminRelayManager.popupOpen then
        return true
    end
    if SpectateQuickPanel and SpectateQuickPanel.active and SpectateQuickPanel.cursorVisible then
        return true
    end
    if TeleportClickManager and TeleportClickManager.enabled then
        return true
    end
    if FarmAnswerTool and FarmAnswerTool.open then
        return true
    end
    if AdminCheckerManager and AdminCheckerManager.placementActive == true then
        return true
    end
    if type(isPauseMenuActive) == "function" then
        local okPause, pauseActive = pcall(isPauseMenuActive)
        if okPause and pauseActive == true then
            return true
        end
    end
    return false
end

function TargetCircleOverlay.isLocalPlayerReady()
    if not PLAYER_PED then
        return false
    end
    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, PLAYER_PED)
        if okExists and not exists then
            return false
        end
    end
    return true
end

function TargetCircleOverlay.getPlayerCenterCoords(playerId)
    local ped = MainUI and type(MainUI.getPlayerPedHandleById) == "function" and MainUI.getPlayerPedHandleById(playerId) or nil
    if not ped or type(getCharCoordinates) ~= "function" then
        return nil
    end
    local okPos, a, b, c, d = pcall(getCharCoordinates, ped)
    if not okPos then
        return nil
    end
    local x, y, z = UtilityManager.extractCoordTriplet(a, b, c, d)
    if not x or not y or not z then
        return nil
    end
    if type(getCharHealth) == "function" then
        local okHealth, health = pcall(getCharHealth, ped)
        if okHealth and tonumber(health) and tonumber(health) <= 0 then
            return nil
        end
    end
    return x, y, z + 0.9, ped
end

function TargetCircleOverlay.getSampVehicleIdByHandle(vehicleHandle)
    local handle = tonumber(vehicleHandle)
    if not handle or handle <= 0 or type(sampGetVehicleIdByCarHandle) ~= "function" then
        return nil
    end

    local okVehId, a, b = pcall(sampGetVehicleIdByCarHandle, handle)
    if not okVehId then
        return nil
    end

    local sampVehId = nil
    if type(a) == "boolean" then
        if a then
            sampVehId = tonumber(b)
        end
    else
        sampVehId = tonumber(a)
    end

    if sampVehId and sampVehId > 0 then
        return sampVehId
    end
    return nil
end

function TargetCircleOverlay.getVehicleHandleBySampId(vehicleId)
    local sampVehicleId = tonumber(vehicleId)
    if not sampVehicleId or sampVehicleId <= 0 or type(sampGetCarHandleBySampVehicleId) ~= "function" then
        return nil
    end

    local okHandle, a, b = pcall(sampGetCarHandleBySampVehicleId, sampVehicleId)
    if not okHandle then
        return nil
    end

    local vehicleHandle = nil
    if type(a) == "boolean" then
        if a then
            vehicleHandle = tonumber(b)
        end
    else
        vehicleHandle = tonumber(a)
    end

    if not vehicleHandle or vehicleHandle <= 0 then
        return nil
    end

    if type(doesVehicleExist) == "function" then
        local okExists, exists = pcall(doesVehicleExist, vehicleHandle)
        if okExists and not exists then
            return nil
        end
    end

    return vehicleHandle
end

function TargetCircleOverlay.getVehicleCenterCoords(vehicleId, vehicleHandle)
    local handle = tonumber(vehicleHandle) or TargetCircleOverlay.getVehicleHandleBySampId(vehicleId)
    if not handle or type(getCarCoordinates) ~= "function" then
        return nil
    end

    local okPos, a, b, c, d = pcall(getCarCoordinates, handle)
    if not okPos then
        return nil
    end

    local x, y, z = UtilityManager.extractCoordTriplet(a, b, c, d)
    if not x or not y or not z then
        return nil
    end

    return x, y, z + 0.6, handle
end

function TargetCircleOverlay.worldToScreen(x, y, z)
    if type(convert3DCoordsToScreen) ~= "function" then
        return nil
    end
    local ok, a, b, c, d = pcall(convert3DCoordsToScreen, x, y, z)
    if not ok then
        return nil
    end
    if type(a) == "boolean" then
        if not a then
            return nil
        end
        return tonumber(b), tonumber(c)
    end
    local sx, sy = tonumber(a), tonumber(b)
    if not sx or not sy then
        return nil
    end
    return sx, sy
end

function TargetCircleOverlay.findTargetInCircle()
    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        return nil
    end

    local targetMode = tostring(TargetCircleOverlay.targetMode or "player")
    local centerX, centerY, screenX, screenY = TargetCircleOverlay.getCenter()
    local radius = tonumber(TargetCircleOverlay.radius) or 140
    local radiusSq = radius * radius
    local localPlayerId = MainUI and type(MainUI.getLocalPlayerId) == "function" and MainUI.getLocalPlayerId() or nil
    local maxPlayerId = UtilityManager.getMaxPlayerIdSafe(1000)

    local best = nil
    if targetMode == "player" then
        for playerId = 0, maxPlayerId do
            if not localPlayerId or playerId ~= localPlayerId then
                local okConnected, connected = pcall(sampIsPlayerConnected, playerId)
                if okConnected and connected then
                    local x, y, z = TargetCircleOverlay.getPlayerCenterCoords(playerId)
                    if x and y and z then
                        local sx, sy = TargetCircleOverlay.worldToScreen(x, y, z)
                        if sx and sy and sx >= 0 and sy >= 0 and sx <= screenX and sy <= screenY then
                            local dx = sx - centerX
                            local dy = sy - centerY
                            local screenDistSq = dx * dx + dy * dy
                            if screenDistSq <= radiusSq then
                                local nick = UtilityManager.getPlayerNicknameSafe(playerId, "Unknown")
                                if (not best) or screenDistSq < best.screenDistSq then
                                    best = {
                                        kind = "player",
                                        id = playerId,
                                        nick = nick,
                                        screenX = sx,
                                        screenY = sy,
                                        screenDistSq = screenDistSq
                                    }
                                end
                            end
                        end
                    end
                end
            end
        end
        return best
    end

    local seenVehicleIds = {}
    local function considerVehicleCandidate(vehicleId, vehicleHandle)
        local sampVehicleId = tonumber(vehicleId)
        if not sampVehicleId or sampVehicleId <= 0 or seenVehicleIds[sampVehicleId] then
            return
        end
        seenVehicleIds[sampVehicleId] = true

        local x, y, z = TargetCircleOverlay.getVehicleCenterCoords(sampVehicleId, vehicleHandle)
        if not x or not y or not z then
            return
        end

        local sx, sy = TargetCircleOverlay.worldToScreen(x, y, z)
        if not sx or not sy or sx < 0 or sy < 0 or sx > screenX or sy > screenY then
            return
        end

        local dx = sx - centerX
        local dy = sy - centerY
        local screenDistSq = dx * dx + dy * dy
        if screenDistSq > radiusSq then
            return
        end

        if (not best) or screenDistSq < best.screenDistSq then
            best = {
                kind = "vehicle",
                id = sampVehicleId,
                nick = "Vehicle",
                screenX = sx,
                screenY = sy,
                screenDistSq = screenDistSq
            }
        end
    end

    local scannedVehicleFromHandles = false
    if type(getAllVehicles) == "function" then
        local okVehicles, vehicleHandles = pcall(getAllVehicles)
        if okVehicles and type(vehicleHandles) == "table" then
            scannedVehicleFromHandles = true
            for _, rawHandle in ipairs(vehicleHandles) do
                local handle = tonumber(rawHandle)
                if handle and handle > 0 then
                    local sampVehicleId = TargetCircleOverlay.getSampVehicleIdByHandle(handle)
                    if sampVehicleId and sampVehicleId > 0 then
                        considerVehicleCandidate(sampVehicleId, handle)
                    end
                end
            end
        end
    end

    if not scannedVehicleFromHandles then
        local maxVehicleId = UtilityManager.getMaxVehicleIdSafe(0)
        if maxVehicleId > 0 then
            for vehicleId = 1, maxVehicleId do
                local handle = TargetCircleOverlay.getVehicleHandleBySampId(vehicleId)
                if handle then
                    considerVehicleCandidate(vehicleId, handle)
                end
            end
        end
    end

    return best
end

function TargetCircleOverlay.getTargetLabel()
    if not TargetCircleOverlay.target then
        return "Target: none"
    end
    if tostring(TargetCircleOverlay.target.kind or "player") == "vehicle" then
        return string.format("Target: Vehicle [%d]", tonumber(TargetCircleOverlay.target.id) or 0)
    end
    return string.format("Target: %s [%d]", tostring(TargetCircleOverlay.target.nick or "Unknown"), tonumber(TargetCircleOverlay.target.id) or 0)
end

function TargetCircleOverlay.executeTargetAction(actionName)
    local now = os.clock()
    if (now - TargetCircleOverlay.lastActionAt) < TargetCircleOverlay.actionCooldown then
        return false
    end
    TargetCircleOverlay.lastActionAt = now

    local target = TargetCircleOverlay.target
    if not target or tonumber(target.id) == nil then
        TargetCircleOverlay.notify("Target Circle: target topilmadi.", 0xFF9933)
        return false
    end

    local targetId = tonumber(target.id)
    local targetKind = tostring(target.kind or "player")
    if targetKind == "vehicle" and actionName ~= "getcar" then
        TargetCircleOverlay.notify("Target Circle: bu action faqat player targetga ishlaydi.", 0xFF9933)
        return false
    end

    if actionName == "spawn" then
        if sendChat(string.format("/spawn %d", targetId)) ~= false then
            TargetCircleOverlay.notify(string.format("Target Circle: /spawn %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /spawn %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /spawn yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "rgun" then
        if sendChat(string.format("/rgun %d", targetId)) ~= false then
            TargetCircleOverlay.notify(string.format("Target Circle: /rgun %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /rgun %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /rgun yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "gethere" then
        if sendChat(string.format("/gethere %d", targetId)) ~= false then
            TargetCircleOverlay.notify(string.format("Target Circle: /gethere %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /gethere %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /gethere yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "getcar" then
        if targetKind == "vehicle" then
            if sendChat(string.format("/getcar %d", targetId)) ~= false then
                TargetCircleOverlay.notify(string.format("Target Circle: /getcar %d yuborildi.", targetId), 0x33FF66)
                LogManager.admin(string.format("Target Circle: /getcar %d (vehicle target)", targetId))
                return true
            end
            TargetCircleOverlay.notify("Target Circle: /getcar yuborib bo'lmadi.", 0xFF6666)
            return false
        end
        if TargetCircleOverlay.getCarBusy then
            TargetCircleOverlay.notify("Target Circle: /getcar jarayoni davom etmoqda.", 0xFF9933)
            return false
        end
        if not SpectateQuickPanel or type(SpectateQuickPanel.resolveTargetVehicleIdForGetcar) ~= "function" then
            TargetCircleOverlay.notify("Target Circle: getcar helper topilmadi.", 0xFF6666)
            return false
        end
        if not lua_thread or type(lua_thread.create) ~= "function" then
            TargetCircleOverlay.notify("Target Circle: thread API topilmadi.", 0xFF6666)
            return false
        end

        TargetCircleOverlay.getCarBusy = true
        lua_thread.create(function()
            local ok, err = pcall(function()
                local vehicleId = SpectateQuickPanel.resolveTargetVehicleIdForGetcar(targetId, 2100)
                if not vehicleId or vehicleId <= 0 then
                    TargetCircleOverlay.notify("Target Circle: mashina ID topilmadi.", 0xFF6666)
                    return
                end
                if sendChat(string.format("/getcar %d", vehicleId)) ~= false then
                    TargetCircleOverlay.notify(string.format("Target Circle: /getcar %d yuborildi.", vehicleId), 0x33FF66)
                    LogManager.admin(string.format("Target Circle: /getcar %d (target #%d)", vehicleId, targetId))
                    return
                end
                TargetCircleOverlay.notify("Target Circle: /getcar yuborib bo'lmadi.", 0xFF6666)
            end)
            TargetCircleOverlay.getCarBusy = false
            if not ok then
                TargetCircleOverlay.notify("Target Circle: /getcar xato bo'ldi.", 0xFF6666)
                LogManager.error("Target Circle getcar failed: " .. tostring(err))
            end
        end)
        return true
    end

    if actionName == "sp" then
        if tonumber(TargetCircleOverlay.pendingSpectateTargetId) == targetId and now < tonumber(TargetCircleOverlay.pendingSpectateUntil or 0) then
            return true
        end
        if SpectateQuickPanel and SpectateQuickPanel.active and tonumber(SpectateQuickPanel.targetId) == targetId then
            return true
        end
        if PlayerManager and type(PlayerManager.spectate) == "function" then
            TargetCircleOverlay.pendingSpectateTargetId = targetId
            TargetCircleOverlay.pendingSpectateUntil = now + 1.8
            TargetCircleOverlay.suppressRenderUntil = now + 1.2
            PlayerManager.spectate(targetId)
            LogManager.admin(string.format("Target Circle: /sp %d", targetId))
            return true
        end
        if sendChat(string.format("/sp %d", targetId)) ~= false then
            TargetCircleOverlay.pendingSpectateTargetId = targetId
            TargetCircleOverlay.pendingSpectateUntil = now + 1.8
            TargetCircleOverlay.suppressRenderUntil = now + 1.2
            LogManager.admin(string.format("Target Circle: /sp %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: SP yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "stats" then
        if sendChat(string.format("/stats %d", targetId)) ~= false then
            TargetCircleOverlay.suppressRenderUntil = (os.clock() or 0) + 2.2
            TargetCircleOverlay.notify(string.format("Target Circle: /stats %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /stats %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /stats yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "slap" then
        if PlayerManager and type(PlayerManager.slap) == "function" then
            if PlayerManager.slap(targetId) then
                TargetCircleOverlay.notify(string.format("Target Circle: /slap %d yuborildi.", targetId), 0x33FF66)
                LogManager.admin(string.format("Target Circle: /slap %d", targetId))
                return true
            end
        elseif sendChat(string.format("/slap %d", targetId)) ~= false then
            TargetCircleOverlay.notify(string.format("Target Circle: /slap %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /slap %d", targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /slap yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "skick" then
        local reason = "SKICK"
        if MainUI and type(MainUI.isProtectedAdminTarget) == "function" then
            local okProtected, isProtected = pcall(MainUI.isProtectedAdminTarget, targetId)
            if okProtected and isProtected == true then
                TargetCircleOverlay.notify("Target Circle: admin targetga /skick ishlamaydi.", 0xFF9933)
                return false
            end
        end
        if sendChat(string.format("/skick %d %s", targetId, reason)) ~= false then
            TargetCircleOverlay.notify(string.format("Target Circle: /skick %d yuborildi.", targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /skick %d %s", targetId, reason))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /skick yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    if actionName == "flipfix" then
        local flipOk = sendChat(string.format("/flip %d", targetId)) ~= false
        local fixOk = sendChat(string.format("/fixcar %d", targetId)) ~= false
        if flipOk and fixOk then
            TargetCircleOverlay.notify(string.format("Target Circle: /flip %d va /fixcar %d yuborildi.", targetId, targetId), 0x33FF66)
            LogManager.admin(string.format("Target Circle: /flip %d | /fixcar %d", targetId, targetId))
            return true
        end
        TargetCircleOverlay.notify("Target Circle: /flip yoki /fixcar yuborib bo'lmadi.", 0xFF6666)
        return false
    end

    return false
end

function TargetCircleOverlay.handleRadiusInput(chatActive, dialogActive)
    if TargetCircleOverlay.isUiInputBlocked(chatActive, dialogActive) then
        return
    end
    if type(isKeyDown) ~= "function" then
        return
    end
    local okAlt, altDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyModifier)
    if not okAlt or not altDown then
        return
    end
    local wheel = TargetCircleOverlay.getIoMouseWheel()
    if wheel == 0 then
        return
    end

    local step = math.max(6, math.floor(TargetCircleOverlay.radius * 0.08))
    if wheel > 0 then
        TargetCircleOverlay.radius = UtilityManager.clamp(TargetCircleOverlay.radius + step, TargetCircleOverlay.minRadius, TargetCircleOverlay.maxRadius)
    else
        TargetCircleOverlay.radius = UtilityManager.clamp(TargetCircleOverlay.radius - step, TargetCircleOverlay.minRadius, TargetCircleOverlay.maxRadius)
    end
    TargetCircleOverlay.saveToSettings()
end

function TargetCircleOverlay.handleActionInput(chatActive, dialogActive)
    if TargetCircleOverlay.isUiInputBlocked(chatActive, dialogActive) then
        TargetCircleOverlay.lastSpawnDown = false
        TargetCircleOverlay.lastRgunDown = false
        TargetCircleOverlay.lastSpecDown = false
        TargetCircleOverlay.lastStatsDown = false
        TargetCircleOverlay.lastGetHereDown = false
        TargetCircleOverlay.lastSlapDown = false
        TargetCircleOverlay.lastSkickDown = false
        TargetCircleOverlay.lastFlipFixDown = false
        TargetCircleOverlay.lastVehicleGetCarDown = false
        return
    end

    local spawnPressed = false
    local rgunPressed = false
    local specPressed = false
    local statsPressed = false
    local getherePressed = false
    local slapPressed = false
    local skickPressed = false
    local flipfixPressed = false
    local vehicleGetcarPressed = false
    if type(isKeyJustPressed) == "function" then
        local okSpawnPressed, valueSpawnPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeySpawn)
        spawnPressed = okSpawnPressed and valueSpawnPressed == true
        local okRgunPressed, valueRgunPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyRgun)
        rgunPressed = okRgunPressed and valueRgunPressed == true
        local okSpecPressed, valueSpecPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeySpec)
        specPressed = okSpecPressed and valueSpecPressed == true
        local okStatsPressed, valueStatsPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyStats)
        statsPressed = okStatsPressed and valueStatsPressed == true
        local okGetHerePressed, valueGetHerePressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyGetHere)
        getherePressed = okGetHerePressed and valueGetHerePressed == true
        local okSlapPressed, valueSlapPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeySlap)
        slapPressed = okSlapPressed and valueSlapPressed == true
        local okSkickPressed, valueSkickPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeySkick)
        skickPressed = okSkickPressed and valueSkickPressed == true
        local okFlipFixPressed, valueFlipFixPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyFlipFix)
        flipfixPressed = okFlipFixPressed and valueFlipFixPressed == true
        local okVehicleGetCarPressed, valueVehicleGetCarPressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyVehicleGetCar)
        vehicleGetcarPressed = okVehicleGetCarPressed and valueVehicleGetCarPressed == true
    end
    if spawnPressed then
        TargetCircleOverlay.lastSpawnDown = true
    end
    if rgunPressed then
        TargetCircleOverlay.lastRgunDown = true
    end
    if specPressed then
        TargetCircleOverlay.lastSpecDown = true
    end
    if statsPressed then
        TargetCircleOverlay.lastStatsDown = true
    end
    if getherePressed then
        TargetCircleOverlay.lastGetHereDown = true
    end
    if slapPressed then
        TargetCircleOverlay.lastSlapDown = true
    end
    if skickPressed then
        TargetCircleOverlay.lastSkickDown = true
    end
    if flipfixPressed then
        TargetCircleOverlay.lastFlipFixDown = true
    end
    if vehicleGetcarPressed then
        TargetCircleOverlay.lastVehicleGetCarDown = true
    end

    if (not spawnPressed) or (not rgunPressed) or (not specPressed) or (not statsPressed) or (not getherePressed) or (not slapPressed) or (not skickPressed) or (not flipfixPressed) or (not vehicleGetcarPressed) then
        if type(isKeyDown) == "function" then
            if not spawnPressed then
                local okSpawnDown, spawnDown = pcall(isKeyDown, TargetCircleOverlay.hotkeySpawn)
                spawnDown = okSpawnDown and spawnDown == true
                if spawnDown and not TargetCircleOverlay.lastSpawnDown then
                    spawnPressed = true
                end
                TargetCircleOverlay.lastSpawnDown = spawnDown
            end

            if not rgunPressed then
                local okRgunDown, rgunDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyRgun)
                rgunDown = okRgunDown and rgunDown == true
                if rgunDown and not TargetCircleOverlay.lastRgunDown then
                    rgunPressed = true
                end
                TargetCircleOverlay.lastRgunDown = rgunDown
            end

            if not specPressed then
                local okSpecDown, specDown = pcall(isKeyDown, TargetCircleOverlay.hotkeySpec)
                specDown = okSpecDown and specDown == true
                if specDown and not TargetCircleOverlay.lastSpecDown then
                    specPressed = true
                end
                TargetCircleOverlay.lastSpecDown = specDown
            end

            if not statsPressed then
                local okStatsDown, statsDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyStats)
                statsDown = okStatsDown and statsDown == true
                if statsDown and not TargetCircleOverlay.lastStatsDown then
                    statsPressed = true
                end
                TargetCircleOverlay.lastStatsDown = statsDown
            end

            if not getherePressed then
                local okGetHereDown, gethereDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyGetHere)
                gethereDown = okGetHereDown and gethereDown == true
                if gethereDown and not TargetCircleOverlay.lastGetHereDown then
                    getherePressed = true
                end
                TargetCircleOverlay.lastGetHereDown = gethereDown
            end

            if not slapPressed then
                local okSlapDown, slapDown = pcall(isKeyDown, TargetCircleOverlay.hotkeySlap)
                slapDown = okSlapDown and slapDown == true
                if slapDown and not TargetCircleOverlay.lastSlapDown then
                    slapPressed = true
                end
                TargetCircleOverlay.lastSlapDown = slapDown
            end

            if not skickPressed then
                local okSkickDown, skickDown = pcall(isKeyDown, TargetCircleOverlay.hotkeySkick)
                skickDown = okSkickDown and skickDown == true
                if skickDown and not TargetCircleOverlay.lastSkickDown then
                    skickPressed = true
                end
                TargetCircleOverlay.lastSkickDown = skickDown
            end

            if not flipfixPressed then
                local okFlipFixDown, flipfixDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyFlipFix)
                flipfixDown = okFlipFixDown and flipfixDown == true
                if flipfixDown and not TargetCircleOverlay.lastFlipFixDown then
                    flipfixPressed = true
                end
                TargetCircleOverlay.lastFlipFixDown = flipfixDown
            end

            if not vehicleGetcarPressed then
                local okVehicleGetCarDown, vehicleGetcarDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyVehicleGetCar)
                vehicleGetcarDown = okVehicleGetCarDown and vehicleGetcarDown == true
                if vehicleGetcarDown and not TargetCircleOverlay.lastVehicleGetCarDown then
                    vehicleGetcarPressed = true
                end
                TargetCircleOverlay.lastVehicleGetCarDown = vehicleGetcarDown
            end
        end
    end

    local targetMode = tostring(TargetCircleOverlay.targetMode or "player")
    if targetMode == "vehicle" then
        if vehicleGetcarPressed then
            TargetCircleOverlay.executeTargetAction("getcar")
        end
        return
    end

    if spawnPressed then
        TargetCircleOverlay.executeTargetAction("spawn")
    elseif statsPressed then
        TargetCircleOverlay.executeTargetAction("stats")
    elseif specPressed then
        TargetCircleOverlay.executeTargetAction("sp")
    elseif rgunPressed then
        TargetCircleOverlay.executeTargetAction("rgun")
    elseif getherePressed then
        TargetCircleOverlay.executeTargetAction("gethere")
    elseif slapPressed then
        TargetCircleOverlay.executeTargetAction("slap")
    elseif skickPressed then
        TargetCircleOverlay.executeTargetAction("skick")
    elseif flipfixPressed then
        TargetCircleOverlay.executeTargetAction("flipfix")
    end
end

function TargetCircleOverlay.handleModeSwitch(chatActive, dialogActive)
    if TargetCircleOverlay.isUiInputBlocked(chatActive, dialogActive) then
        TargetCircleOverlay.lastModeSwitchDown = false
        return
    end
    if not TargetCircleOverlay.enabled then
        TargetCircleOverlay.lastModeSwitchDown = false
        return
    end

    local modePressed = false
    if type(isKeyJustPressed) == "function" then
        local okPressed, valuePressed = pcall(isKeyJustPressed, TargetCircleOverlay.hotkeyModeSwitch)
        modePressed = okPressed and valuePressed == true
    end
    if (not modePressed) and type(isKeyDown) == "function" then
        local okDown, keyDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyModeSwitch)
        keyDown = okDown and keyDown == true
        if keyDown and not TargetCircleOverlay.lastModeSwitchDown then
            modePressed = true
        end
        TargetCircleOverlay.lastModeSwitchDown = keyDown
    elseif modePressed then
        TargetCircleOverlay.lastModeSwitchDown = true
    end

    if modePressed then
        TargetCircleOverlay.switchMode()
    end
end

function TargetCircleOverlay.handleToggle(chatActive, dialogActive)
    if TargetCircleOverlay.isUiInputBlocked(chatActive, dialogActive) then
        TargetCircleOverlay.lastToggleDown = false
        TargetCircleOverlay.lastModeSwitchDown = false
        if QuickActionHotkeys and QuickActionHotkeys.lastState then
            QuickActionHotkeys.lastState[TargetCircleOverlay.hotkeyToggle] = false
        end
        return
    end

    local togglePressed = false
    if QuickActionHotkeys and type(QuickActionHotkeys.wasKeyPressed) == "function" then
        togglePressed = QuickActionHotkeys.wasKeyPressed(TargetCircleOverlay.hotkeyToggle) == true
    elseif type(isKeyDown) == "function" then
        local okDown, keyDown = pcall(isKeyDown, TargetCircleOverlay.hotkeyToggle)
        keyDown = okDown and keyDown == true
        togglePressed = keyDown and not TargetCircleOverlay.lastToggleDown
        TargetCircleOverlay.lastToggleDown = keyDown
    else
        return
    end

    local now = os.clock() or 0
    if togglePressed and
       (now - tonumber(TargetCircleOverlay.lastToggleAt or 0)) >= tonumber(TargetCircleOverlay.toggleCooldown or 0.22) then
        TargetCircleOverlay.lastToggleAt = now
        TargetCircleOverlay.toggle()
    end
end

function TargetCircleOverlay.update(chatActive, dialogActive)
    if not TargetCircleOverlay.isFeatureAvailable() then
        TargetCircleOverlay.pendingSpectateTargetId = nil
        TargetCircleOverlay.pendingSpectateUntil = 0
        TargetCircleOverlay.target = nil
        return
    end

    TargetCircleOverlay.handleToggle(chatActive, dialogActive)
    if not TargetCircleOverlay.enabled then
        TargetCircleOverlay.lastModeSwitchDown = false
        TargetCircleOverlay.pendingSpectateTargetId = nil
        TargetCircleOverlay.pendingSpectateUntil = 0
        TargetCircleOverlay.target = nil
        return
    end

    if not TargetCircleOverlay.isLocalPlayerReady() then
        TargetCircleOverlay.pendingSpectateTargetId = nil
        TargetCircleOverlay.pendingSpectateUntil = 0
        TargetCircleOverlay.target = nil
        return
    end

    TargetCircleOverlay.handleModeSwitch(chatActive, dialogActive)
    local now = os.clock()
    if tonumber(TargetCircleOverlay.pendingSpectateUntil or 0) > 0 and now >= tonumber(TargetCircleOverlay.pendingSpectateUntil or 0) then
        TargetCircleOverlay.pendingSpectateTargetId = nil
        TargetCircleOverlay.pendingSpectateUntil = 0
    end

    TargetCircleOverlay.handleRadiusInput(chatActive, dialogActive)
    TargetCircleOverlay.handleActionInput(chatActive, dialogActive)

    if (now - TargetCircleOverlay.lastScanAt) < TargetCircleOverlay.scanInterval then
        return
    end
    TargetCircleOverlay.lastScanAt = now
    TargetCircleOverlay.target = TargetCircleOverlay.findTargetInCircle()
end

function TargetCircleOverlay.render()
    if not TargetCircleOverlay.isOverlayVisible() then
        return
    end
    if TargetCircleOverlay.isRenderBlocked() then
        return
    end

    local drawList = TargetCircleOverlay.getDrawList()
    if not drawList or type(drawList.AddText) ~= "function" then
        return
    end

    local centerX, centerY = TargetCircleOverlay.getCenter()
    local radius = tonumber(TargetCircleOverlay.radius) or 140
    local activeTarget = TargetCircleOverlay.target ~= nil
    local targetMode = tostring(TargetCircleOverlay.targetMode or "player")
    local outlineColor = activeTarget and (COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0)) or (COLORS.INFO or imgui.ImVec4(0.45, 0.82, 1.0, 1.0))
    local hintColor = COLORS.TEXT_DIM or imgui.ImVec4(0.76, 0.76, 0.76, 1.0)
    local textColor = activeTarget and (COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1)) or hintColor
    local outlineU32 = MainUI and MainUI.colorToU32 and MainUI.colorToU32(outlineColor) or 0xFFFFFFFF

    if not TargetCircleOverlay.drawCircleOutline(drawList, centerX, centerY, radius, outlineU32) then
        return
    end
    if type(drawList.AddCircleFilled) == "function" then
        drawList:AddCircleFilled(imgui.ImVec2(centerX, centerY), 2.6, outlineU32)
        if activeTarget and TargetCircleOverlay.target.screenX and TargetCircleOverlay.target.screenY then
            drawList:AddCircleFilled(imgui.ImVec2(TargetCircleOverlay.target.screenX, TargetCircleOverlay.target.screenY), 3.8, outlineU32)
        end
    end

    TargetCircleOverlay.drawCenteredText(drawList, centerX, centerY - radius - 26, textColor, TargetCircleOverlay.getTargetLabel())
    TargetCircleOverlay.drawCenteredText(drawList, centerX, centerY - radius - 46, hintColor, string.format("Mode: %s | E - Switch", string.upper(targetMode)))
    TargetCircleOverlay.drawCenteredText(drawList, centerX, centerY + radius + 10, hintColor, "ALT + Wheel - Size")
    TargetCircleOverlay.drawShadowedText(drawList, centerX - radius - 88, centerY - 8, hintColor, "R - ON/OFF")
    if targetMode == "vehicle" then
        TargetCircleOverlay.drawShadowedText(drawList, centerX - radius - 104, centerY + 12, hintColor, "1 - GetCar")
    else
        TargetCircleOverlay.drawShadowedText(drawList, centerX - radius - 104, centerY + 12, hintColor, "1 - Spawn")
        TargetCircleOverlay.drawShadowedText(drawList, centerX - radius - 104, centerY + 32, hintColor, "2 - Stats")
        TargetCircleOverlay.drawShadowedText(drawList, centerX - radius - 104, centerY + 52, hintColor, "3 - SP")
        TargetCircleOverlay.drawShadowedText(drawList, centerX + radius + 18, centerY - 28, hintColor, "4 - RGun")
        TargetCircleOverlay.drawShadowedText(drawList, centerX + radius + 18, centerY - 8, hintColor, "5 - GetHere")
        TargetCircleOverlay.drawShadowedText(drawList, centerX + radius + 18, centerY + 12, hintColor, "6 - Slap")
        TargetCircleOverlay.drawShadowedText(drawList, centerX + radius + 18, centerY + 32, hintColor, "7 - Skick")
        TargetCircleOverlay.drawShadowedText(drawList, centerX + radius + 18, centerY + 52, hintColor, "8 - Flip+Fix")
    end

    if activeTarget and TargetCircleOverlay.target.screenX and TargetCircleOverlay.target.screenY then
        local infoX = TargetCircleOverlay.target.screenX + 10
        local infoY = TargetCircleOverlay.target.screenY - 22
        TargetCircleOverlay.drawShadowedText(
            drawList,
            infoX,
            infoY,
            COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1),
            string.format("%s [%d]", tostring(TargetCircleOverlay.target.nick or "Unknown"), tonumber(TargetCircleOverlay.target.id) or 0)
        )
    end
end


end

BOOT_LOGGER.write("Inlining module: navigation/nearby_player_scanner.lua")
do
-- ============================================
-- NEARBY PLAYER SCANNER
-- ============================================
NearbyPlayerScanner = {
    radius = 50.0,
    entries = {},
    lastUpdateMs = 0
}

function NearbyPlayerScanner.update()
    local nowMs = RuntimeGuard.getNowMs()
    if (nowMs - NearbyPlayerScanner.lastUpdateMs) < 1000 then
        return
    end
    NearbyPlayerScanner.lastUpdateMs = nowMs

    local hasLocal, lx, ly, lz = UtilityManager.getPlayerCoords()
    if not hasLocal then
        NearbyPlayerScanner.entries = {}
        return
    end

    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        NearbyPlayerScanner.entries = {}
        return
    end

    local maxId = UtilityManager.getMaxPlayerIdSafe(-1)
    if maxId < 0 then
        NearbyPlayerScanner.entries = {}
        return
    end

    local localId = MainUI and type(MainUI.getLocalPlayerId) == "function" and MainUI.getLocalPlayerId() or nil
    local results = {}

    for id = 0, maxId do
        local okConn, connected = pcall(sampIsPlayerConnected, id)
        if okConn and connected and (not localId or id ~= localId) then
            local x, y, z = UtilityManager.getPlayerWorldCoordsById(id)
            if x and y and z then
                local dx = x - lx
                local dy = y - ly
                local dz = z - lz
                local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
                if dist <= NearbyPlayerScanner.radius then
                    local nick = UtilityManager.getPlayerNicknameSafe(id, "Unknown")
                    table.insert(results, { id = id, name = nick, dist = dist })
                end
            end
        end
    end

    table.sort(results, function(a, b) return (a.dist or 0) < (b.dist or 0) end)
    NearbyPlayerScanner.entries = results
end

function NearbyPlayerScanner.renderTable()
    local list = NearbyPlayerScanner.entries
    imgui.BeginChild("##nearby_players", imgui.ImVec2(0, 140), true)
    imgui.Columns(3, "##nearby_cols", false)
    imgui.Text("ID"); imgui.NextColumn()
    imgui.Text("Name"); imgui.NextColumn()
    imgui.Text("Distance"); imgui.NextColumn()
    imgui.Separator()
    for i = 1, math.min(#list, 12) do
        local row = list[i]
        imgui.Text(tostring(row.id)); imgui.NextColumn()
        imgui.Text(tostring(row.name)); imgui.NextColumn()
        imgui.Text(string.format("%dm", math.floor(row.dist or 0))); imgui.NextColumn()
    end
    imgui.Columns(1)
    imgui.EndChild()
end


end

BOOT_LOGGER.write("Inlining module: systems/combat_stats.lua")
do
-- ============================================
-- COMBAT STATS + SMART SPECTATE ASSISTANT
-- ============================================
CombatStats = {
    players = {},
    lastPruneMs = 0
}

function CombatStats.isTracking(playerId)
    if not SpectateQuickPanel or not SpectateQuickPanel.active or not SpectateQuickPanel.targetId then
        return false
    end
    return tonumber(SpectateQuickPanel.targetId) == tonumber(playerId)
end

function CombatStats.ensure(playerId)
    local id = tonumber(playerId)
    if not id then
        return nil
    end
    if not CombatStats.isTracking(id) then
        return nil
    end
    local entry = CombatStats.players[id]
    if not entry then
        entry = { shots = 0, hits = 0, headshots = 0, kills = 0, updatedAt = RuntimeGuard.getNowMs() }
        CombatStats.players[id] = entry
    end
    entry.updatedAt = RuntimeGuard.getNowMs()
    return entry
end

function CombatStats.recordShot(playerId)
    local entry = CombatStats.ensure(playerId)
    if not entry then
        return
    end
    entry.shots = (entry.shots or 0) + 1
end

function CombatStats.recordHit(attackerId, bodypart)
    local entry = CombatStats.ensure(attackerId)
    if not entry then
        return
    end
    entry.hits = (entry.hits or 0) + 1
    if tonumber(bodypart) == 9 then
        entry.headshots = (entry.headshots or 0) + 1
    end
end

function CombatStats.recordKill(killerId)
    local entry = CombatStats.ensure(killerId)
    if not entry then
        return
    end
    entry.kills = (entry.kills or 0) + 1
end

function CombatStats.getStats(playerId)
    return CombatStats.players[tonumber(playerId or -1)]
end

function CombatStats.prune()
    local nowMs = RuntimeGuard.getNowMs()
    if (nowMs - CombatStats.lastPruneMs) < 5000 then
        return
    end
    CombatStats.lastPruneMs = nowMs
    for id, entry in pairs(CombatStats.players) do
        if not entry or (nowMs - (entry.updatedAt or 0)) > 60000 then
            CombatStats.players[id] = nil
        end
    end
end


end

BOOT_LOGGER.write("Inlining module: spectate/spectate_assistant.lua")
do
SpectateAssistant = {}

function SpectateAssistant.getAnalysis(playerId)
    local stats = CombatStats.getStats(playerId)
    if not stats then
        return nil
    end
    local hits = tonumber(stats.hits) or 0
    local shots = tonumber(stats.shots) or 0
    local headshots = tonumber(stats.headshots) or 0
    local headshotRate = hits > 0 and (headshots / hits) or 0
    local accuracy = shots > 0 and (hits / shots) or 0
    return {
        headshotRate = headshotRate,
        accuracy = accuracy,
        hits = hits
    }
end


end

BOOT_LOGGER.write("Inlining module: monitoring/auto_alert_system.lua")
do
-- ============================================
-- AUTO ALERT SYSTEM
-- ============================================
AutoAlertSystem = {
    alerts = {},
    cooldowns = {},
    killWindow = {},
    reportWindow = {},
    lastCleanupMs = 0,
    killCount = CONFIG.ALERTS.KILL_COUNT,
    killWindowSec = CONFIG.ALERTS.KILL_WINDOW_SEC,
    reportCount = CONFIG.ALERTS.REPORT_COUNT,
    reportWindowSec = CONFIG.ALERTS.REPORT_WINDOW_SEC,
    moneyThreshold = CONFIG.ALERTS.MONEY_THRESHOLD,
    cooldownSec = CONFIG.ALERTS.COOLDOWN_SEC,
    popupTtlSec = CONFIG.ALERTS.POPUP_TTL_SEC,
    cleanupMs = CONFIG.ALERTS.CLEANUP_MS
}

function AutoAlertSystem.shouldThrottle(key)
    local now = os.time()
    local last = tonumber(AutoAlertSystem.cooldowns[key]) or 0
    if now - last < AutoAlertSystem.cooldownSec then
        return true
    end
    AutoAlertSystem.cooldowns[key] = now
    return false
end

function AutoAlertSystem.pushAlert(message, targetId, targetName)
    if not AdminSession.isAdminActive() then
        return
    end
    local msg = tostring(message or "")
    if msg == "" then
        return
    end
    table.insert(AutoAlertSystem.alerts, 1, {
        text = msg,
        ts = os.time(),
        expiresAt = os.time() + (AutoAlertSystem.popupTtlSec or 6)
    })
    local maxAlerts = CONFIG.LIMITS.ALERTS or 5
    if #AutoAlertSystem.alerts > maxAlerts then
        table.remove(AutoAlertSystem.alerts)
    end
    AdminHistoryTracker.add("Alert", targetId or targetName or "Unknown", msg)
end

function AutoAlertSystem.recordKill(killerId, killedId)
    local id = tonumber(killerId)
    if not id or id <= 0 then
        return
    end
    local now = os.time()
    local list = AutoAlertSystem.killWindow[id] or {}
    table.insert(list, now)
    local pruned = {}
    for _, ts in ipairs(list) do
        if now - ts <= AutoAlertSystem.killWindowSec then
            table.insert(pruned, ts)
        end
    end
    AutoAlertSystem.killWindow[id] = pruned
    if #pruned >= AutoAlertSystem.killCount then
        local key = "killspree:" .. tostring(id)
        if not AutoAlertSystem.shouldThrottle(key) then
            local nick = AdminSelection.getSelectedNick(id)
            AutoAlertSystem.pushAlert(string.format("? %s killed %d players in %d seconds",
                nick, #pruned, AutoAlertSystem.killWindowSec), id, nick)
        end
    end
end

function AutoAlertSystem.recordReport(suspectName)
    local name = UtilityManager.trim(tostring(suspectName or ""))
    if name == "" then
        return
    end
    local now = os.time()
    local list = AutoAlertSystem.reportWindow[name] or {}
    table.insert(list, now)
    local pruned = {}
    for _, ts in ipairs(list) do
        if now - ts <= AutoAlertSystem.reportWindowSec then
            table.insert(pruned, ts)
        end
    end
    AutoAlertSystem.reportWindow[name] = pruned
    if #pruned >= AutoAlertSystem.reportCount then
        local key = "reports:" .. name
        if not AutoAlertSystem.shouldThrottle(key) then
            AutoAlertSystem.pushAlert(string.format("? Player %s received %d reports in %d seconds",
                name, #pruned, AutoAlertSystem.reportWindowSec), name, name)
        end
    end
end

function AutoAlertSystem.recordMoneyEntry(playerId, nick, text)
    local line = tostring(text or "")
    if line == "" then
        return
    end
    local folded = PlayerLogManager and PlayerLogManager.foldText and PlayerLogManager.foldText(line) or line:lower()
    if not (folded:find("received", 1, true) or folded:find("oldi", 1, true) or
            folded:find("pul", 1, true) or folded:find("money", 1, true) or
            line:find("%$")) then
        return
    end
    local amount = tonumber(line:match("(%d+)%s*[,$]")) or tonumber(line:match("%$%s*(%d+)")) or
                   tonumber(line:match("(%d+)%s*rubl")) or tonumber(line:match("(%d+)%s*???"))
    if amount and amount >= AutoAlertSystem.moneyThreshold then
        local key = "money:" .. tostring(playerId or nick or "unknown")
        if not AutoAlertSystem.shouldThrottle(key) then
            local name = tostring(nick or playerId or "Unknown")
            AutoAlertSystem.pushAlert(string.format("? Player %s money increase: %d", name, amount), playerId, name)
        end
    end
end

function AutoAlertSystem.update()
    CombatStats.prune()
    local now = os.time()
    local nowMs = RuntimeGuard.getNowMs()
    local cleanupMs = AutoAlertSystem.cleanupMs or 500
    if (nowMs - AutoAlertSystem.lastCleanupMs) < cleanupMs then
        return
    end
    AutoAlertSystem.lastCleanupMs = nowMs
    local alive = {}
    for _, alert in ipairs(AutoAlertSystem.alerts) do
        if (alert.expiresAt or 0) >= now then
            table.insert(alive, alert)
        end
    end
    AutoAlertSystem.alerts = alive

    for id, list in pairs(AutoAlertSystem.killWindow) do
        local kept = {}
        for _, ts in ipairs(list) do
            if now - ts <= AutoAlertSystem.killWindowSec then
                table.insert(kept, ts)
            end
        end
        if #kept > 0 then
            AutoAlertSystem.killWindow[id] = kept
        else
            AutoAlertSystem.killWindow[id] = nil
        end
    end

    for name, list in pairs(AutoAlertSystem.reportWindow) do
        local kept = {}
        for _, ts in ipairs(list) do
            if now - ts <= AutoAlertSystem.reportWindowSec then
                table.insert(kept, ts)
            end
        end
        if #kept > 0 then
            AutoAlertSystem.reportWindow[name] = kept
        else
            AutoAlertSystem.reportWindow[name] = nil
        end
    end

    local cooldownTtl = (AutoAlertSystem.cooldownSec or 20) * 3
    for key, ts in pairs(AutoAlertSystem.cooldowns) do
        if now - (tonumber(ts) or 0) > cooldownTtl then
            AutoAlertSystem.cooldowns[key] = nil
        end
    end
end

function AutoAlertSystem.renderPopup()
    local list = AutoAlertSystem.alerts
    if not list or #list == 0 then
        return
    end
    local alert = list[1]
    if not alert or not alert.text then
        return
    end
    imgui.PushStyleColor(imgui.Col.ChildBg, COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 0.2))
    imgui.BeginChild("##auto_alert_popup", imgui.ImVec2(0, 30), true)
    imgui.TextColored(COLORS.DANGER or imgui.ImVec4(1.0, 0.3, 0.3, 1.0), tostring(alert.text))
    imgui.EndChild()
    imgui.PopStyleColor(1)
end


end

BOOT_LOGGER.write("Inlining module: logs/player_log_manager.lua")
do
PlayerLogManager = {
    cache = {},
    selectedId = nil,
    selectedNick = "",
    selectedKey = "",
    pending = nil,
    currentView = "search",
    uiOpenLogged = false,
    lastLoggedView = "",
    adminLogFilterSelected = false,
    searchState = { query = "", kind = "", results = {}, note = "" },
    maxCacheEntries = CONFIG.LIMITS.PLAYER_LOG_CACHE or 200,
    lastPruneMs = 0
}

function PlayerLogManager.normalizeServerText(text)
    local cleaned = tostring(text or "")
    cleaned = cleaned:gsub("{%x%x%x%x%x%x}", "")
    cleaned = cleaned:gsub("\t", " ")
    cleaned = cleaned:gsub("%s%s+", " ")
    return UtilityManager.trim(cleaned)
end

function PlayerLogManager.foldText(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value:lower()
end

function PlayerLogManager.resolveSearchQuery(query)
    local value = UtilityManager.trim(tostring(query or ""))
    if value == "" then
        return nil
    end
    if value:match("^%d+%.%d+%.%d+%.%d+$") then
        return { kind = "ip", value = value }
    end
    local num = tonumber(value)
    if num then
        return { kind = "id", value = num }
    end
    return { kind = "nick", value = value }
end

function PlayerLogManager.countPunishments(data)
    local count = 0
    for _, entry in ipairs(data.adminActions.entries or {}) do
        local action = PlayerLogManager.foldText(entry.action or "")
        if action:find("ban", 1, true) or action:find("mute", 1, true) or
           action:find("jail", 1, true) or action:find("warn", 1, true) then
            count = count + 1
        end
    end
    return count
end

function PlayerLogManager.addSearchResult(results, data)
    if not data then
        return
    end
    PlayerLogManager.hydrateOnlineProfile(data)
    for _, row in ipairs(results) do
        if row.id == data.profile.playerId then
            row.nick = data.profile.nickname or data.nick
            row.ip = data.profile.ip
            row.ping = data.profile.ping
            row.level = data.profile.level
            row.registerDate = data.profile.registerDate
            row.lastLogin = data.profile.lastLogin
            row.playtime = data.profile.playtime
            return
        end
    end
    table.insert(results, {
        id = data.profile.playerId,
        nick = data.profile.nickname or data.nick,
        ip = data.profile.ip,
        ping = data.profile.ping,
        level = data.profile.level,
        registerDate = data.profile.registerDate,
        lastLogin = data.profile.lastLogin,
        playtime = data.profile.playtime
    })
end

function PlayerLogManager.findPlayersByIp(ip)
    local results = {}
    local target = tostring(ip or "")
    if target == "" then
        return results
    end
    for _, data in pairs(PlayerLogManager.cache) do
        local match = false
        if tostring(data.profile.ip) == target or tostring(data.profile.lastIp) == target then
            match = true
        else
            for _, prev in ipairs(data.network.previousIps or {}) do
                if tostring(prev) == target then
                    match = true
                    break
                end
            end
        end
        if match then
            PlayerLogManager.addSearchResult(results, data)
        end
    end
    return results
end

function PlayerLogManager.findPlayersByNick(nick)
    local results = {}
    local target = PlayerLogManager.foldText(nick)
    if target == "" then
        return results
    end
    local players = PlayerManager.getOnlineList()
    for _, player in ipairs(players) do
        if PlayerLogManager.foldText(player.name):find(target, 1, true) then
            local data = PlayerLogManager.ensurePlayer(player.id, player.name)
            PlayerLogManager.hydrateOnlineProfile(data)
            PlayerLogManager.addSearchResult(results, data)
        end
    end
    for _, data in pairs(PlayerLogManager.cache) do
        local nickFolded = PlayerLogManager.foldText(data.profile.nickname or data.nick)
        if nickFolded ~= "" and nickFolded:find(target, 1, true) then
            PlayerLogManager.addSearchResult(results, data)
        else
            for _, prev in ipairs(data.profile.previousNicknames or {}) do
                if PlayerLogManager.foldText(prev):find(target, 1, true) then
                    PlayerLogManager.addSearchResult(results, data)
                    break
                end
            end
        end
    end
    return results
end

function PlayerLogManager.performSearch(query)
    local resolved = PlayerLogManager.resolveSearchQuery(query)
    PlayerLogManager.searchState = { query = tostring(query or ""), kind = "", results = {}, note = "" }
    if not resolved then
        return
    end
    PlayerLogManager.searchState.kind = resolved.kind
    if resolved.kind == "ip" then
        PlayerLogManager.searchState.results = PlayerLogManager.findPlayersByIp(resolved.value)
        PlayerLogManager.searchState.note = string.format("IP ADDRESS: %s", resolved.value)
        PlayerLogManager.logAdminEvent("Admin searched IP: " .. resolved.value)
    elseif resolved.kind == "id" then
        local pid = tonumber(resolved.value)
        if pid then
            local nick = sampIsPlayerConnected(pid) and sampGetPlayerNickname(pid) or ""
            local data = PlayerLogManager.ensurePlayer(pid, nick)
            PlayerLogManager.hydrateOnlineProfile(data)
            PlayerLogManager.addSearchResult(PlayerLogManager.searchState.results, data)
            PlayerLogManager.selectPlayer(pid, nick)
            PlayerLogManager.requestSnapshot(pid, nick, tostring(resolved.value))
            PlayerLogManager.logAdminEvent(string.format("Admin searched player ID: %d", pid))
        end
    else
        local results = PlayerLogManager.findPlayersByNick(resolved.value)
        PlayerLogManager.searchState.results = results
        if results[1] then
            PlayerLogManager.selectPlayer(results[1].id, results[1].nick)
            PlayerLogManager.requestSnapshot(results[1].id, results[1].nick, tostring(resolved.value))
        end
        PlayerLogManager.logAdminEvent("Admin searched player: " .. resolved.value)
    end
end

function PlayerLogManager.getPlayerKey(playerId)
    if not playerId then
        return ""
    end
    return tostring(playerId)
end

function PlayerLogManager.ensurePlayer(playerId, nick)
    local key = PlayerLogManager.getPlayerKey(playerId)
    if key == "" then
        return nil
    end
    local data = PlayerLogManager.cache[key]
    if not data then
        local safeNick = tostring(nick or "")
        data = {
            id = tonumber(playerId) or 0,
            nick = safeNick,
            profile = {
                nickname = safeNick,
                playerId = tonumber(playerId) or 0,
                accountId = "N/A",
                ip = "N/A",
                country = "N/A",
                ping = "N/A",
                level = "N/A",
                registerDate = "N/A",
                lastLogin = "N/A",
                playtime = "N/A",
                adminLevel = "N/A",
                previousNicknames = {},
                nickChanges = 0,
                lastIp = "N/A"
            },
            history = { entries = {}, seen = {} },
            assets = {
                cash = "N/A",
                bank = "N/A",
                total = "N/A",
                vehicles = {},
                properties = {},
                apartments = {},
                businesses = {}
            },
            network = {
                ip = "N/A",
                previousIps = {},
                country = "N/A",
                region = "N/A",
                connectionType = "N/A",
                pingHistory = {},
                packetLoss = "N/A",
                sameIpAccounts = {},
                sameIpPlayers = {}
            },
            combat = {
                kills = 0,
                deaths = 0,
                headshots = 0,
                headshotRate = 0,
                kd = 0,
                longestKill = "N/A",
                weaponsUsed = {}
            },
            economy = {
                earned = "N/A",
                spent = "N/A",
                transfersSent = 0,
                transfersReceived = 0,
                largestTxn = "N/A"
            },
            reports = {
                sent = 0,
                received = 0,
                resolved = 0,
                history = {}
            },
            adminActions = { entries = {} },
            risk = { score = 0, label = "Low Risk", factors = {} },
            raw = { statsLines = {}, getinfoLines = {}, historyLines = {} },
            lastUpdated = { stats = 0, getinfo = 0, history = 0, risk = 0 },
            loading = { stats = false, getinfo = false, history = false },
            lastRequestAt = 0
        }
        PlayerLogManager.cache[key] = data
    end

    if nick and nick ~= "" then
        data.nick = tostring(nick)
        data.profile.nickname = tostring(nick)
    end
    data.profile.playerId = tonumber(playerId) or data.profile.playerId
    data.lastAccessAt = UtilityManager.getNowMs()
    PlayerLogManager.pruneCache()
    return data
end

function PlayerLogManager.pruneCache()
    local maxEntries = tonumber(PlayerLogManager.maxCacheEntries) or 0
    if maxEntries <= 0 then
        return
    end
    local nowMs = UtilityManager.getNowMs()
    if (nowMs - (PlayerLogManager.lastPruneMs or 0)) < 5000 then
        return
    end
    PlayerLogManager.lastPruneMs = nowMs

    local count = 0
    for _ in pairs(PlayerLogManager.cache) do
        count = count + 1
    end
    if count <= maxEntries then
        return
    end

    local entries = {}
    for key, data in pairs(PlayerLogManager.cache) do
        table.insert(entries, {
            key = key,
            last = tonumber(data.lastAccessAt or data.lastRequestAt or 0)
        })
    end
    table.sort(entries, function(a, b)
        return a.last < b.last
    end)

    local removeCount = count - maxEntries
    for i = 1, removeCount do
        PlayerLogManager.cache[entries[i].key] = nil
    end
end

function PlayerLogManager.addHistoryEntry(data, text, timestamp)
    if not data or not text or text == "" then
        return
    end
    local key = tostring(text)
    if data.history.seen[key] then
        return
    end
    data.history.seen[key] = true
    table.insert(data.history.entries, 1, {
        ts = timestamp or os.time(),
        text = key
    })
    if AutoAlertSystem and AutoAlertSystem.recordMoneyEntry then
        AutoAlertSystem.recordMoneyEntry(data.profile.playerId, data.profile.nickname or data.nick, key)
    end
    local limit = CONFIG.LIMITS.PLAYER_LOG_HISTORY or 120
    if #data.history.entries > limit then
        local removed = table.remove(data.history.entries)
        if removed and removed.text then
            data.history.seen[removed.text] = nil
        end
    end
end

function PlayerLogManager.logAdminEvent(message)
    if not message or message == "" then
        return
    end
    LogManager.admin("[ADMIN_LOG] " .. message)
end

function PlayerLogManager.addAdminAction(playerId, action, details)
    local data = PlayerLogManager.ensurePlayer(playerId)
    if not data then
        return
    end
    local entry = {
        ts = os.time(),
        admin = AdminSession and AdminSession.getAdminName and AdminSession.getAdminName() or "You",
        action = tostring(action or "Action"),
        details = tostring(details or "")
    }
    table.insert(data.adminActions.entries, 1, entry)
    local limit = CONFIG.LIMITS.PLAYER_LOG_ADMIN_ACTIONS or 100
    if #data.adminActions.entries > limit then
        table.remove(data.adminActions.entries)
    end
    PlayerLogManager.addHistoryEntry(data, string.format("%s | %s", entry.action, entry.details))
end

function PlayerLogManager.selectPlayer(playerId, nick)
    local data = PlayerLogManager.ensurePlayer(playerId, nick)
    if not data then
        return nil
    end
    data.lastAccessAt = UtilityManager.getNowMs()
    PlayerLogManager.selectedId = tonumber(playerId) or data.profile.playerId
    PlayerLogManager.selectedNick = tostring(nick or data.nick or "")
    PlayerLogManager.selectedKey = PlayerLogManager.getPlayerKey(PlayerLogManager.selectedId)
    PlayerLogManager.logAdminEvent(string.format("Admin opened player log: %s[%d]",
        tostring(PlayerLogManager.selectedNick or "Unknown"),
        tonumber(PlayerLogManager.selectedId) or 0))
    return data
end

function PlayerLogManager.getSelectedData()
    local key = PlayerLogManager.selectedKey or ""
    if key == "" then
        return nil
    end
    return PlayerLogManager.cache[key]
end

function PlayerLogManager.getPendingPhaseType(pending, nowClock)
    if not pending or not pending.phases then
        return "stats"
    end
    for _, phase in ipairs(pending.phases) do
        if nowClock >= phase.start and nowClock <= phase["end"] then
            return phase.kind
        end
    end
    return pending.phases[#pending.phases].kind
end

function PlayerLogManager.isLineRelated(line, pending)
    if not pending then
        return false
    end
    local folded = PlayerLogManager.foldText(line)
    if folded == "" then
        return false
    end
    local idText = tostring(pending.playerId or "")
    if idText ~= "" and (folded:find("[" .. idText .. "]", 1, true) or folded:find(idText, 1, true)) then
        return true
    end
    local nickFolded = PlayerLogManager.foldText(pending.nick or "")
    if nickFolded ~= "" and folded:find(nickFolded, 1, true) then
        return true
    end
    local keywords = {
        "hisob", "account", "akkaunt", "nickname", "nick", "ip",
        "level", "daraja", "admin", "stat", "statistika", "tarix", "history",
        "register", "registr", "login", "kirish", "playtime", "online", "o'yin vaqti",
        "ban", "mute", "jail", "warn", "demorgan"
    }
    for _, key in ipairs(keywords) do
        if folded:find(key, 1, true) then
            return true
        end
    end
    return false
end

function PlayerLogManager.captureLine(pending, kind, line)
    if not pending or not kind or not line then
        return
    end
    pending.captured = pending.captured or { stats = {}, getinfo = {}, history = {} }
    local bucket = pending.captured[kind]
    if not bucket then
        bucket = {}
        pending.captured[kind] = bucket
    end
    if #bucket >= 160 then
        return
    end
    table.insert(bucket, PlayerLogManager.normalizeServerText(line))
end

function PlayerLogManager.captureServerMessage(text)
    local pending = PlayerLogManager.pending
    if not pending then
        return
    end
    local nowClock = os.clock()
    if nowClock > (pending.expiresAt or 0) then
        return
    end
    if not PlayerLogManager.isLineRelated(text, pending) then
        return
    end
    local phase = PlayerLogManager.getPendingPhaseType(pending, nowClock)
    PlayerLogManager.captureLine(pending, phase, text)
end

function PlayerLogManager.captureDialog(text)
    local pending = PlayerLogManager.pending
    if not pending then
        return
    end
    local nowClock = os.clock()
    if nowClock > (pending.expiresAt or 0) then
        return
    end
    local phase = PlayerLogManager.getPendingPhaseType(pending, nowClock)
    local raw = tostring(text or "")
    if raw == "" then
        return
    end
    for line in raw:gmatch("[^\r\n]+") do
        if PlayerLogManager.isLineRelated(line, pending) then
            PlayerLogManager.captureLine(pending, phase, line)
        end
    end
end

function PlayerLogManager.extractValueAfterSeparator(line)
    local value = PlayerLogManager.normalizeServerText(line)
    local candidate = value:match("[:=]%s*(.+)")
    if not candidate then
        candidate = value:match("%-%s*(.+)")
    end
    candidate = UtilityManager.trim(candidate or "")
    if candidate == "" or candidate == value then
        return ""
    end
    return candidate
end

function PlayerLogManager.extractLastNumber(line)
    local value = PlayerLogManager.extractValueAfterSeparator(line)
    if value ~= "" then
        local lastNumber = nil
        for num in tostring(value):gmatch("(-?%d+)") do
            lastNumber = tonumber(num)
        end
        if lastNumber ~= nil then
            return lastNumber
        end
    end

    local lastNumber = nil
    for num in PlayerLogManager.normalizeServerText(line):gmatch("(-?%d+)") do
        lastNumber = tonumber(num)
    end
    return lastNumber
end

function PlayerLogManager.findNumberByKeywords(lines, keywords)
    for _, line in ipairs(lines or {}) do
        local cleanLine = PlayerLogManager.normalizeServerText(line)
        local folded = PlayerLogManager.foldText(cleanLine)
        for _, key in ipairs(keywords or {}) do
            if folded:find(key, 1, true) then
                local num = PlayerLogManager.extractLastNumber(cleanLine)
                if num then
                    return tonumber(num)
                end
            end
        end
    end
    return nil
end

function PlayerLogManager.findTextByKeywords(lines, keywords)
    for _, line in ipairs(lines or {}) do
        local cleanLine = PlayerLogManager.normalizeServerText(line)
        local folded = PlayerLogManager.foldText(cleanLine)
        for _, key in ipairs(keywords or {}) do
            if folded:find(key, 1, true) then
                local value = PlayerLogManager.extractValueAfterSeparator(cleanLine)
                if value ~= "" then
                    return value
                end
            end
        end
    end
    return nil
end

function PlayerLogManager.findFirstIp(lines)
    for _, line in ipairs(lines or {}) do
        local ip = PlayerLogManager.normalizeServerText(line):match("(%d+%.%d+%.%d+%.%d+)")
        if ip then
            return ip
        end
    end
    return nil
end

function PlayerLogManager.findAccountId(lines)
    local keywords = {
        "account id", "account", "akkaunt", "akk raqam", "hisob qaytnomasi", "hisob qaydnomasi"
    }
    for _, line in ipairs(lines or {}) do
        local cleanLine = PlayerLogManager.normalizeServerText(line)
        local folded = PlayerLogManager.foldText(cleanLine)
        if not folded:find("hisobot", 1, true) then
            for _, key in ipairs(keywords) do
                if folded:find(key, 1, true) then
                    local value = PlayerLogManager.extractValueAfterSeparator(cleanLine)
                    if value ~= "" then
                        return value
                    end
                end
            end
        end
    end
    return nil
end

function PlayerLogManager.findDateTexts(lines)
    local results = {}
    local seen = {}
    for _, line in ipairs(lines or {}) do
        local cleanLine = PlayerLogManager.normalizeServerText(line)
        local value = PlayerLogManager.extractValueAfterSeparator(cleanLine)
        local candidate = value
        if candidate == "" then
            candidate = cleanLine:match("(%d%d%d%d%-%d%d%-%d%d%s+%d%d:%d%d)") or
                cleanLine:match("(%d%d%.%d%d%.%d%d%d%d%s+%d%d:%d%d)") or
                cleanLine:match("(%d%d%d%d%-%d%d%-%d%d)") or
                cleanLine:match("(%d%d%.%d%d%.%d%d%d%d)")
        end
        candidate = UtilityManager.trim(candidate or "")
        if candidate ~= "" and not seen[candidate] then
            seen[candidate] = true
            table.insert(results, candidate)
        end
    end
    return results
end

function PlayerLogManager.findPlaytimeText(lines)
    for _, line in ipairs(lines or {}) do
        local cleanLine = PlayerLogManager.normalizeServerText(line)
        local folded = PlayerLogManager.foldText(cleanLine)
        if folded:find("playtime", 1, true) or folded:find("online", 1, true) or
           folded:find("o'yin vaqti", 1, true) or folded:find("otigran", 1, true) then
            local value = PlayerLogManager.extractValueAfterSeparator(cleanLine)
            if value ~= "" then
                return value
            end
        end
        local hms = cleanLine:match("(%d+:%d+:%d+)")
        if hms then
            return hms
        end
    end
    return nil
end

function PlayerLogManager.hydrateOnlineProfile(data)
    if not data then
        return
    end
    local pid = tonumber(data.profile.playerId) or 0
    if pid <= 0 or type(sampIsPlayerConnected) ~= "function" or not sampIsPlayerConnected(pid) then
        return
    end
    if type(sampGetPlayerNickname) == "function" then
        local okNick, nick = pcall(sampGetPlayerNickname, pid)
        if okNick and nick and nick ~= "" then
            data.profile.nickname = tostring(nick)
        end
    end
    if type(sampGetPlayerPing) == "function" then
        local okPing, ping = pcall(sampGetPlayerPing, pid)
        if okPing and ping ~= nil then
            data.profile.ping = tostring(ping)
        end
    end
    if type(sampGetPlayerScore) == "function" then
        local okScore, score = pcall(sampGetPlayerScore, pid)
        if okScore and tonumber(score) then
            data.profile.level = tostring(math.max(0, tonumber(score) or 0))
        end
    end
end

function PlayerLogManager.refreshLiveProfile(playerId, nick, force)
    local data = PlayerLogManager.ensurePlayer(playerId, nick)
    if not data then
        return nil
    end
    if PlayerManager and type(PlayerManager.getOnlineList) == "function" then
        PlayerManager.getOnlineList(force == true)
    end
    PlayerLogManager.hydrateOnlineProfile(data)

    data.loading.stats = false
    data.loading.getinfo = false
    data.loading.history = false
    data.lastUpdated.stats = os.time()
    data.lastUpdated.getinfo = 0
    data.lastUpdated.history = 0

    return data
end

function PlayerLogManager.resolveOffstatsTarget(playerId, nick, explicitTarget)
    local direct = UtilityManager.trim(tostring(explicitTarget or ""))
    if direct ~= "" then
        return direct
    end

    local safeNick = UtilityManager.trim(tostring(nick or ""))
    if safeNick ~= "" then
        return safeNick
    end

    local pid = tonumber(playerId) or 0
    if pid > 0 and type(sampIsPlayerConnected) == "function" and sampIsPlayerConnected(pid) and
       type(sampGetPlayerNickname) == "function" then
        local okNick, liveNick = pcall(sampGetPlayerNickname, pid)
        liveNick = UtilityManager.trim(tostring(liveNick or ""))
        if okNick and liveNick ~= "" then
            return liveNick
        end
    end

    if pid > 0 then
        return tostring(pid)
    end

    return ""
end

function PlayerLogManager.startSnapshotCommands(pending)
    if not pending then
        return
    end

    local offstatsTarget = UtilityManager.trim(tostring(pending.offstatsTarget or ""))
    local statsTarget = tonumber(pending.playerId) or 0

    local function sendCommands(withDelay)
        if offstatsTarget ~= "" then
            sendChat(string.format("/offstats %s", offstatsTarget))
        end
        if statsTarget > 0 then
            if withDelay then
                wait(1900)
            end
            sendChat(string.format("/stats %d", statsTarget))
        end
    end

    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(function()
            sendCommands(true)
        end)
    else
        sendCommands(false)
    end
end

function PlayerLogManager.extractDate(line)
    local y, m, d, hh, mm = tostring(line):match("(%d%d%d%d)%-(%d%d)%-(%d%d)%s+(%d%d):(%d%d)")
    if y then
        return os.time({ year = tonumber(y), month = tonumber(m), day = tonumber(d), hour = tonumber(hh), min = tonumber(mm), sec = 0 })
    end
    local d2, m2, y2, hh2, mm2 = tostring(line):match("(%d%d)%.(%d%d)%.(%d%d%d%d)%s+(%d%d):(%d%d)")
    if y2 then
        return os.time({ year = tonumber(y2), month = tonumber(m2), day = tonumber(d2), hour = tonumber(hh2), min = tonumber(mm2), sec = 0 })
    end
    return nil
end

function PlayerLogManager.updateProfileFromLines(data)
    local statsLines = data.raw.statsLines or {}
    local infoLines = data.raw.getinfoLines or {}
    local historyLines = data.raw.historyLines or {}

    local ip = PlayerLogManager.findFirstIp(infoLines) or PlayerLogManager.findFirstIp(statsLines)
    if ip then
        data.profile.ip = ip
        data.profile.lastIp = ip
        data.network.ip = ip
        local exists = false
        for _, known in ipairs(data.network.previousIps) do
            if known == ip then
                exists = true
                break
            end
        end
        if not exists then
            table.insert(data.network.previousIps, ip)
        end
    end

    local accountId = PlayerLogManager.findAccountId(infoLines)
    if accountId and accountId ~= "" then
        data.profile.accountId = accountId
    end

    local level = PlayerLogManager.findNumberByKeywords(statsLines, { "level", "daraja", "???????", "lvl" })
    if level then
        data.profile.level = tostring(level)
    end

    local adminLevel = PlayerLogManager.findNumberByKeywords(infoLines, { "admin", "?????", "adm" })
    if adminLevel then
        data.profile.adminLevel = tostring(adminLevel)
    end

    local registerDate = PlayerLogManager.findTextByKeywords(infoLines, { "register", "ro'yxat", "registr", "reg date", "created" })
    if registerDate and registerDate ~= "" then
        data.profile.registerDate = registerDate
    end

    local lastLogin = PlayerLogManager.findTextByKeywords(infoLines, { "last login", "last", "oxirgi", "kirish", "login" })
    if lastLogin and lastLogin ~= "" then
        data.profile.lastLogin = lastLogin
    end

    local playtime = PlayerLogManager.findPlaytimeText(statsLines)
    if playtime and playtime ~= "" then
        data.profile.playtime = playtime
    end

    local cash = PlayerLogManager.findTextByKeywords(infoLines, { "naqd", "cash", "?????" })
    if cash and cash ~= "" then
        data.assets.cash = cash
    end
    local bank = PlayerLogManager.findTextByKeywords(infoLines, { "bank", "hisob", "????" })
    if bank and bank ~= "" then
        data.assets.bank = bank
    end

    local country = PlayerLogManager.findTextByKeywords(infoLines, { "country", "davlat", "??????" })
    if country and country ~= "" then
        data.profile.country = country
        data.network.country = country
    end
    local region = PlayerLogManager.findTextByKeywords(infoLines, { "region", "viloyat", "???????" })
    if region and region ~= "" then
        data.network.region = region
    end
    local conn = PlayerLogManager.findTextByKeywords(infoLines, { "connection", "ulanish", "??????" })
    if conn and conn ~= "" then
        data.network.connectionType = conn
    end

    local dates = PlayerLogManager.findDateTexts(infoLines)
    if data.profile.registerDate == "N/A" and dates[1] then
        data.profile.registerDate = dates[1]
    end
    if data.profile.lastLogin == "N/A" then
        data.profile.lastLogin = dates[2] or dates[1] or data.profile.lastLogin
    end

    for _, line in ipairs(historyLines) do
        local folded = PlayerLogManager.foldText(line)
        if folded:find("nick", 1, true) or folded:find("nickname", 1, true) or folded:find("nik", 1, true) then
            local newNick = line:match("->%s*(%S+)")
            if newNick and newNick ~= "" then
                local exists = false
                for _, prev in ipairs(data.profile.previousNicknames) do
                    if prev == newNick then
                        exists = true
                        break
                    end
                end
                if not exists then
                    table.insert(data.profile.previousNicknames, newNick)
                    data.profile.nickChanges = #data.profile.previousNicknames
                end
            end
        end
    end

    PlayerLogManager.hydrateOnlineProfile(data)
end

function PlayerLogManager.updateHistoryFromLines(data)
    for _, line in ipairs(data.raw.historyLines or {}) do
        local ts = PlayerLogManager.extractDate(line) or os.time()
        PlayerLogManager.addHistoryEntry(data, tostring(line), ts)
    end
end

function PlayerLogManager.computeEconomy(data)
    if not data then
        return
    end
    local events = {}
    local largest = 0
    local sent = 0
    local received = 0

    for _, entry in ipairs(data.history.entries or {}) do
        local line = tostring(entry.text or "")
        local folded = PlayerLogManager.foldText(line)
        if folded:find("transfer", 1, true) or folded:find("sent", 1, true) or
           folded:find("received", 1, true) or folded:find("pul", 1, true) or
           folded:find("money", 1, true) or line:find("%$") then
            table.insert(events, { ts = entry.ts or os.time(), text = line })
            local amount = tonumber(line:match("(%d+)%s*[,$]")) or tonumber(line:match("%$%s*(%d+)")) or
                           tonumber(line:match("(%d+)%s*rubl")) or tonumber(line:match("(%d+)%s*???"))
            if amount then
                if amount > largest then
                    largest = amount
                end
                if folded:find("sent", 1, true) or folded:find("yubor", 1, true) then
                    sent = sent + 1
                elseif folded:find("received", 1, true) or folded:find("oldi", 1, true) then
                    received = received + 1
                end
            end
        end
    end

    data.economy.events = events
    if largest > 0 then
        data.economy.largestTxn = tostring(largest)
    end
    data.economy.transfersSent = sent
    data.economy.transfersReceived = received
end

function PlayerLogManager.extractItemEvents(data)
    local events = {}
    for _, entry in ipairs(data.history.entries or {}) do
        local line = tostring(entry.text or "")
        local folded = PlayerLogManager.foldText(line)
        if folded:find("weapon", 1, true) or folded:find("qurol", 1, true) or
           folded:find("dropped", 1, true) or folded:find("traded", 1, true) or
           folded:find("purchased", 1, true) or folded:find("sotib", 1, true) or
           folded:find("vehicle", 1, true) or folded:find("house", 1, true) or
           folded:find("biz", 1, true) then
            table.insert(events, { ts = entry.ts or os.time(), text = line })
        end
    end
    return events
end

function PlayerLogManager.computeRisk(data)
    local score = 0
    local factors = {}
    local reports = tonumber(data.reports.received) or 0
    if reports > 0 then
        score = score + math.min(25, reports * 5)
        table.insert(factors, string.format("Reports received: %d", reports))
    end
    local punishments = 0
    for _, entry in ipairs(data.adminActions.entries or {}) do
        local action = PlayerLogManager.foldText(entry.action or "")
        if action:find("ban", 1, true) or action:find("mute", 1, true) or action:find("jail", 1, true) or
           action:find("warn", 1, true) then
            punishments = punishments + 1
        end
    end
    if punishments > 0 then
        score = score + math.min(25, punishments * 5)
        table.insert(factors, string.format("Punishments: %d", punishments))
    end
    local kd = tonumber(data.combat.kd) or 0
    if kd >= 5 then
        score = score + 15
        table.insert(factors, string.format("High K/D ratio: %.2f", kd))
    end
    local headshotRate = tonumber(data.combat.headshotRate) or 0
    if headshotRate >= 60 then
        score = score + 15
        table.insert(factors, string.format("High headshot rate: %d%%", headshotRate))
    end
    local multiAccounts = #(data.network.sameIpPlayers or {})
    if multiAccounts > 0 then
        score = score + 20
        table.insert(factors, string.format("Same IP players: %d", multiAccounts))
    end
    local largestTxn = tonumber(data.economy.largestTxn) or 0
    if largestTxn >= 500000 then
        score = score + 10
        table.insert(factors, string.format("Large transaction: %d", largestTxn))
    end
    local totalTransfers = (tonumber(data.economy.transfersSent) or 0) + (tonumber(data.economy.transfersReceived) or 0)
    if totalTransfers >= 5 then
        score = score + 10
        table.insert(factors, string.format("Multiple transfers: %d", totalTransfers))
    end
    score = math.min(100, score)

    local label = "Low Risk"
    if score >= 85 then
        label = "Critical Risk"
    elseif score >= 60 then
        label = "High Risk"
    elseif score >= 30 then
        label = "Medium Risk"
    end
    data.risk.score = score
    data.risk.label = label
    data.risk.factors = factors
end

function PlayerLogManager.applyCapturedData(pending)
    if not pending then
        return
    end
    local data = PlayerLogManager.ensurePlayer(pending.playerId, pending.nick)
    if not data then
        return
    end
    local captured = pending.captured or {}
    if captured.stats and #captured.stats > 0 then
        data.raw.statsLines = captured.stats
        data.lastUpdated.stats = os.time()
    end
    if captured.getinfo and #captured.getinfo > 0 then
        data.raw.getinfoLines = captured.getinfo
        data.lastUpdated.getinfo = os.time()
    end
    if captured.history and #captured.history > 0 then
        data.raw.historyLines = captured.history
        data.lastUpdated.history = os.time()
    end
    data.loading.stats = false
    data.loading.getinfo = false
    data.loading.history = false

    PlayerLogManager.updateProfileFromLines(data)
    PlayerLogManager.updateHistoryFromLines(data)
    PlayerLogManager.computeEconomy(data)
    PlayerLogManager.computeRisk(data)
end

function PlayerLogManager.requestSnapshot(playerId, nick, explicitTarget)
    local data = PlayerLogManager.refreshLiveProfile(playerId, nick, true)
    if not data then
        return
    end
    local snapshotTarget = PlayerLogManager.resolveOffstatsTarget(playerId, nick, explicitTarget)
    if snapshotTarget == "" or type(sendChat) ~= "function" then
        PlayerLogManager.pending = nil
        PlayerLogManager.logAdminEvent(string.format("Admin refreshed live player data: %s[%d]",
            tostring(data.profile.nickname or data.nick or "Unknown"),
            tonumber(data.profile.playerId) or 0))
        return
    end

    local nowClock = os.clock()
    data.loading.stats = true
    data.loading.getinfo = true
    data.loading.history = false
    data.lastRequestAt = UtilityManager.getNowMs()

    PlayerLogManager.pending = {
        playerId = tonumber(data.profile.playerId) or 0,
        nick = tostring(data.profile.nickname or data.nick or ""),
        offstatsTarget = snapshotTarget,
        captured = { stats = {}, getinfo = {}, history = {} },
        phases = {
            { kind = "getinfo", start = nowClock, ["end"] = nowClock + 2.1 },
            { kind = "stats", start = nowClock + 2.15, ["end"] = nowClock + 5.4 }
        },
        expiresAt = nowClock + 5.7
    }

    PlayerLogManager.startSnapshotCommands(PlayerLogManager.pending)
    PlayerLogManager.logAdminEvent(string.format("Admin requested /offstats + /stats for %s[%d]",
        tostring(data.profile.nickname or data.nick or snapshotTarget),
        tonumber(data.profile.playerId) or 0))
end

function PlayerLogManager.update()
    local pending = PlayerLogManager.pending
    if not pending then
        return
    end
    if os.clock() > (pending.expiresAt or 0) then
        PlayerLogManager.pending = nil
        PlayerLogManager.applyCapturedData(pending)
    end
end

function PlayerLogManager.captureReport(report)
    if not report then
        return
    end
    local playerId = tonumber(report.playerId)
    local nick = tostring(report.nick or "")
    if not playerId and nick ~= "" and ReportCatchManager and
       type(ReportCatchManager.getPlayerIdByNick) == "function" then
        playerId = ReportCatchManager.getPlayerIdByNick(nick)
    end
    if not playerId then
        return
    end
    local data = PlayerLogManager.ensurePlayer(playerId, nick)
    if not data then
        return
    end
    data.reports.sent = (data.reports.sent or 0) + 1
    table.insert(data.reports.history, 1, {
        ts = report.time or os.time(),
        text = string.format("Report: %s", tostring(report.text or "")),
        id = report.id
    })
    local limit = CONFIG.LIMITS.PLAYER_LOG_REPORT_HISTORY or 50
    if #data.reports.history > limit then
        table.remove(data.reports.history)
    end
    PlayerLogManager.addHistoryEntry(data, string.format("Report sent: %s", tostring(report.text or "")), report.time)
end

function PlayerLogManager.onPlayerDeathNotification(killerId, killedId, reason)
    if killerId and killerId ~= 0 then
        local killerNick = sampIsPlayerConnected(killerId) and sampGetPlayerNickname(killerId) or ""
        local data = PlayerLogManager.ensurePlayer(killerId, killerNick)
        if data then
            data.combat.kills = (data.combat.kills or 0) + 1
            data.combat.kd = data.combat.deaths > 0 and (data.combat.kills / data.combat.deaths) or data.combat.kills
            PlayerLogManager.addHistoryEntry(data, string.format("Kill: %s", tostring(killedId or 0)))
        end
    end
    if killedId and killedId ~= 0 then
        local victimNick = sampIsPlayerConnected(killedId) and sampGetPlayerNickname(killedId) or ""
        local data = PlayerLogManager.ensurePlayer(killedId, victimNick)
        if data then
            data.combat.deaths = (data.combat.deaths or 0) + 1
            data.combat.kd = data.combat.deaths > 0 and (data.combat.kills / data.combat.deaths) or data.combat.kills
            PlayerLogManager.addHistoryEntry(data, string.format("Death by: %s", tostring(killerId or 0)))
        end
    end
end

-- ============================================
-- CHAT LOG MANAGER
-- ============================================
ChatLogManager = {
    entries = {},
    grouped = {},
    orderedDates = {},
    configPath = "",
    confirmReset = false,
    expandedDates = {},
    dirty = false,
    lastSavedAtMs = 0,
    maxEntries = 3500,
    dataVersion = 0,
    filterCacheQuery = "",
    filterCacheVersion = -1,
    filterCacheBuckets = nil
}

function ChatLogManager.foldText(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value:lower()
end

function ChatLogManager.sanitizeField(value)
    local text = tostring(value or "")
    text = text:gsub("[%c\r\n\t]", " ")
    text = text:gsub("%s%s+", " ")
    return UtilityManager.trim(text)
end

function ChatLogManager.buildDateLabel(timestamp)
    return os.date("%d.%m.%Y", tonumber(timestamp) or os.time())
end

function ChatLogManager.buildTimeLabel(timestamp)
    return os.date("%H.%M.%S", tonumber(timestamp) or os.time())
end

function ChatLogManager.dateSortValue(dateLabel)
    local day, month, year = tostring(dateLabel or ""):match("^(%d%d)%.(%d%d)%.(%d%d%d%d)$")
    if not day or not month or not year then
        return 0
    end
    return (tonumber(year) or 0) * 10000 + (tonumber(month) or 0) * 100 + (tonumber(day) or 0)
end

function ChatLogManager.sortDates()
    table.sort(ChatLogManager.orderedDates, function(left, right)
        local l = ChatLogManager.dateSortValue(left)
        local r = ChatLogManager.dateSortValue(right)
        if l == r then
            return tostring(left or "") > tostring(right or "")
        end
        return l > r
    end)
end

function ChatLogManager.ensureDateBucket(dateLabel)
    local label = tostring(dateLabel or ChatLogManager.buildDateLabel(os.time()))
    if type(ChatLogManager.grouped[label]) ~= "table" then
        ChatLogManager.grouped[label] = {}
        table.insert(ChatLogManager.orderedDates, label)
        ChatLogManager.sortDates()
    end
    return ChatLogManager.grouped[label]
end

function ChatLogManager.invalidateFilterCache()
    ChatLogManager.dataVersion = (tonumber(ChatLogManager.dataVersion) or 0) + 1
    ChatLogManager.filterCacheQuery = ""
    ChatLogManager.filterCacheVersion = -1
    ChatLogManager.filterCacheBuckets = nil
end

function ChatLogManager.removeOrderedDate(dateLabel)
    local label = tostring(dateLabel or "")
    if label == "" then
        return
    end
    for index = #ChatLogManager.orderedDates, 1, -1 do
        if tostring(ChatLogManager.orderedDates[index] or "") == label then
            table.remove(ChatLogManager.orderedDates, index)
            break
        end
    end
end

function ChatLogManager.removeEntryFromBucket(entry)
    local dateLabel = tostring(entry and entry.dateText or "")
    if dateLabel == "" then
        return
    end
    local bucket = ChatLogManager.grouped[dateLabel]
    if type(bucket) ~= "table" then
        return
    end
    for index = #bucket, 1, -1 do
        if bucket[index] == entry then
            table.remove(bucket, index)
            break
        end
    end
    if #bucket <= 0 then
        ChatLogManager.grouped[dateLabel] = nil
        ChatLogManager.removeOrderedDate(dateLabel)
    end
end

function ChatLogManager.attachEntry(entry)
    if type(entry) ~= "table" then
        return
    end
    table.insert(ChatLogManager.entries, 1, entry)
    local bucket = ChatLogManager.ensureDateBucket(entry.dateText)
    table.insert(bucket, 1, entry)
    ChatLogManager.invalidateFilterCache()
end

function ChatLogManager.isIgnoredLine(text)
    local folded = ChatLogManager.foldText(text)
    if folded == "" then
        return true
    end

    -- FIX #2: [mp] va [fw] ni aniq prefix sifatida tekshir, ichida emas
    -- Avval boshqa o'yinchi "[mp]" so'zini ishlatsa ham filterlangan
    -- FIX #5b: [gmea] faqat tizim xabarlari uchun ignore qilinadi
    -- [gmea tools] va [gmea status] esa foydalanuvchiga ko'rsatilishi kerak
    local ignoredSnippets = {
        "tools by hikmat",
        "[boot]",
        "target circle:",
        "[navigator]",
        "[report catch]",
        "[repcatch]",
    }
    for _, snippet in ipairs(ignoredSnippets) do
        if folded:find(snippet, 1, true) then
            return true
        end
    end
    -- [gmea] faqat qator boshida va undan keyin "tools" yoki "status" kelmagan holda ignore
    if folded:sub(1, 6) == "[gmea]" then
        return true
    end
    -- [mp] va [fw] faqat qator boshida bo'lsa ignore qilish
    if folded:sub(1, 4) == "[mp]" or folded:sub(1, 4) == "[fw]" then
        return true
    end
    return false
end

function ChatLogManager.normalizeSpeaker(text)
    local nick, playerId = ChatLogManager.resolveSpeakerIdentity(text)
    if nick == "" or not playerId or playerId < 0 then
        return ""
    end
    return string.format("%s[%d]", nick, playerId)
end

function ChatLogManager.foldNickKey(text)
    local value = tostring(text or "")
    value = value:gsub("{%x%x%x%x%x%x}", "")
    value = value:gsub("[%[%]%(%)]+", "")
    value = UtilityManager.trim(value):lower()
    return value
end

function ChatLogManager.resolveLivePlayerIdByNick(nick)
    local targetNick = UtilityManager.trim(tostring(nick or ""))
    local foldedTarget = ChatLogManager.foldNickKey(targetNick)
    if targetNick == "" or foldedTarget == "" then
        return nil
    end

    if ReportCatchManager and type(ReportCatchManager.getPlayerIdByNick) == "function" then
        local okId, valueId = pcall(ReportCatchManager.getPlayerIdByNick, targetNick)
        valueId = okId and tonumber(valueId) or nil
        if valueId and valueId >= 0 then
            return valueId
        end
    end

    if AdminPoManager and type(AdminPoManager.resolveNickToId) == "function" then
        local okId, valueId = pcall(AdminPoManager.resolveNickToId, targetNick)
        valueId = okId and tonumber(valueId) or nil
        if valueId and valueId >= 0 then
            return valueId
        end
    end

    if NearbyPlayerScanner and type(NearbyPlayerScanner.entries) == "table" then
        for _, entry in ipairs(NearbyPlayerScanner.entries) do
            local entryId = tonumber(entry and entry.id) or -1
            if entryId >= 0 and ChatLogManager.foldNickKey(entry and entry.name or "") == foldedTarget then
                return entryId
            end
        end
    end

    if type(sampIsPlayerConnected) ~= "function" or type(sampGetPlayerNickname) ~= "function" then
        return nil
    end

    local maxId = 1000
    if type(sampGetMaxPlayerId) == "function" then
        local okMax, valueMax = pcall(sampGetMaxPlayerId, false)
        valueMax = okMax and tonumber(valueMax) or nil
        if valueMax and valueMax >= 0 then
            maxId = valueMax
        end
    end

    for i = 0, maxId do
        local okConn, connected = pcall(sampIsPlayerConnected, i)
        if okConn and connected then
            local okNick, liveNick = pcall(sampGetPlayerNickname, i)
            if okNick and ChatLogManager.foldNickKey(liveNick) == foldedTarget then
                return tonumber(i) or nil
            end
        end
    end

    return nil
end

function ChatLogManager.resolveSpeakerIdentity(text)
    local speaker = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
    speaker = ChatLogManager.sanitizeField(speaker)
    speaker = speaker:gsub("^<ADM>%s*", "")
    speaker = speaker:gsub("^%[[^%]]+%]%s*", "")
    speaker = speaker:gsub("^%(+%s*", "")
    speaker = speaker:gsub("^%[+%s*", "")
    speaker = speaker:gsub("^%)+%s*", "")
    speaker = speaker:gsub("^%]+%s*", "")
    speaker = speaker:gsub("%s*%)+%s*$", "")
    speaker = speaker:gsub("%s*%]+%s*$", "")
    speaker = UtilityManager.trim(speaker)
    if speaker == "" then
        return "", nil
    end

    local nick, id = speaker:match("^(.+)%[(%d+)%]$")
    if not nick or not id then
        nick, id = speaker:match("^(.+)%((%d+)%)$")
    end
    if nick and id then
        return UtilityManager.trim(nick), tonumber(id) or -1
    end

    local plainNick = speaker:match("^([%w_%.%-]+)$")
    if not plainNick or plainNick == "" then
        return "", nil
    end

    local resolvedId = ChatLogManager.resolveLivePlayerIdByNick(plainNick)

    if resolvedId and resolvedId >= 0 then
        return plainNick, resolvedId
    end
    return "", nil
end

function ChatLogManager.isPlayerSpeaker(text)
    local speaker = ChatLogManager.normalizeSpeaker(text)
    return speaker ~= ""
end

function ChatLogManager.resolveChannel(tagText, body)
    local tagFolded = ChatLogManager.foldText(tagText)
    local bodyFolded = ChatLogManager.foldText(body)
    if tagFolded == "a" or tagFolded == "adm" or bodyFolded:find("<adm>", 1, true) or bodyFolded:find("ga javob berdi:", 1, true) then
        return "Admin chat"
    end
    if tagFolded == "f" or tagFolded == "fam" or tagFolded == "family" then
        return "Family chat"
    end
    if tagFolded == "v" or tagFolded == "vip" then
        return "VIP chat"
    end
    if tagFolded == "r" then
        return "Radio chat"
    end
    -- FIX #4: OOC aniqlashda sub(1,2) o'rniga find ishlatiladi (UTF-8 xavfsiz)
    if tagFolded == "ooc" or bodyFolded:find("^%(%(") then
        return "OOC chat"
    end
    if tagFolded ~= "" then
        return "[" .. tostring(tagText or "") .. "]"
    end
    if ChatLogManager.isPlayerSpeaker(body) then
        if bodyFolded:find("^%(%(") then
            return "OOC chat"
        end
        return "Player chat"
    end
    return "Server chat"
end

function ChatLogManager.buildSearchText(entry)
    return ChatLogManager.foldText(table.concat({
        tostring(entry.timeText or ""),
        tostring(entry.dateText or ""),
        tostring(entry.channel or ""),
        tostring(entry.speaker or ""),
        tostring(entry.message or ""),
        tostring(entry.display or "")
    }, " | "))
end

function ChatLogManager.formatSpeakerLabel(speaker)
    local value = ChatLogManager.sanitizeField(speaker)
    local nick, id = ChatLogManager.resolveSpeakerIdentity(value)
    if nick ~= "" and id and id >= 0 then
        return string.format("%s(%s)", UtilityManager.trim(nick), tostring(id))
    end
    return value
end

function ChatLogManager.decorateSpeakerChunk(rawSpeaker, formattedLabel)
    local source = tostring(rawSpeaker or "")
    local leading = source:match("^([%(%[]+%s*)") or ""
    local trailing = source:match("(%s*[%)%]]+)%s*$") or ""
    return tostring(leading or "") .. tostring(formattedLabel or "") .. tostring(trailing or "")
end

function ChatLogManager.rewriteServerMessageWithIds(text)
    local source = tostring(text or "")
    if source == "" or ChatLogManager.isIgnoredLine(source) then
        return source
    end

    local normalizedSource = PlayerLogManager and type(PlayerLogManager.normalizeServerText) == "function" and
        PlayerLogManager.normalizeServerText(source) or ChatLogManager.sanitizeField(source)

    local sourceTime, body = normalizedSource:match("^%[(%d%d:%d%d:%d%d)%]%s*(.*)$")
    body = UtilityManager.trim(body or normalizedSource)
    if body == "" then
        return source
    end

    local tagText, rest = body:match("^%[([^%]]+)%]%s*(.*)$")
    local parseBody = UtilityManager.trim(rest or body)
    if parseBody == "" then
        return source
    end

    local genericSpeaker, genericMessage = parseBody:match("^([^:]+):%s*(.+)$")
    if not genericSpeaker or not genericMessage then
        return source
    end

    local nick, playerId = ChatLogManager.resolveSpeakerIdentity(genericSpeaker)
    if nick == "" or not playerId or playerId < 0 then
        return source
    end

    local formattedSpeaker = ChatLogManager.decorateSpeakerChunk(genericSpeaker, string.format("%s(%d)", nick, playerId))
    local rebuiltBody = formattedSpeaker .. ": " .. tostring(genericMessage)
    if tagText and tagText ~= "" then
        rebuiltBody = string.format("[%s] %s", tostring(tagText), rebuiltBody)
    end
    if sourceTime and sourceTime ~= "" then
        return string.format("[%s] %s", tostring(sourceTime), rebuiltBody)
    end
    return rebuiltBody
end

function ChatLogManager.makeDisplay(entry)
    local prefix = string.format("%s | %s", tostring(entry.timeText or ""), tostring(entry.channel or "Server chat"))
    if tostring(entry.speaker or "") ~= "" then
        return string.format("%s | %s: %s", prefix, ChatLogManager.formatSpeakerLabel(entry.speaker), tostring(entry.message or ""))
    end
    return string.format("%s | %s", prefix, tostring(entry.message or ""))
end

function ChatLogManager.rebuildGroups()
    ChatLogManager.grouped = {}
    ChatLogManager.orderedDates = {}
    for _, entry in ipairs(ChatLogManager.entries) do
        local bucket = ChatLogManager.ensureDateBucket(entry.dateText)
        table.insert(bucket, entry)
    end
    ChatLogManager.invalidateFilterCache()
end

function ChatLogManager.serializeField(value)
    return tostring(value or ""):gsub("[\t\r\n]", " ")
end

function ChatLogManager.hexEncodeBlob(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    local out = {}
    for i = 1, #value do
        out[#out + 1] = string.format("%02X", value:byte(i))
    end
    return table.concat(out)
end

function ChatLogManager.hexDecodeBlob(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    local out = {}
    for hex in value:gmatch("%x%x") do
        out[#out + 1] = string.char(tonumber(hex, 16) or 0)
    end
    return table.concat(out)
end

function ChatLogManager.serializeEntries(entries)
    local lines = {}
    for _, entry in ipairs(entries or {}) do
        lines[#lines + 1] = table.concat({
            tostring(math.floor(tonumber(entry.timestamp) or os.time())),
            ChatLogManager.serializeField(entry.timeText),
            ChatLogManager.serializeField(entry.dateText),
            ChatLogManager.serializeField(entry.channel),
            ChatLogManager.serializeField(entry.speaker),
            ChatLogManager.serializeField(entry.message)
        }, "\t")
    end
    return "hex:" .. ChatLogManager.hexEncodeBlob(table.concat(lines, "\n"))
end

function ChatLogManager.deserializeEntries(blob)
    local result = {}
    local source = tostring(blob or "")
    if source:sub(1, 4) == "hex:" then
        source = ChatLogManager.hexDecodeBlob(source:sub(5))
    end

    for line in source:gmatch("[^\r\n]+") do
        local fields = UtilityManager.splitString(line, "\t")
        local timestamp = tonumber(fields[1])
        if timestamp then
            local entry = {
                timestamp = timestamp,
                timeText = ChatLogManager.sanitizeField(fields[2]),
                dateText = ChatLogManager.sanitizeField(fields[3]),
                channel = ChatLogManager.sanitizeField(fields[4]),
                speaker = ChatLogManager.sanitizeField(fields[5]),
                message = ChatLogManager.sanitizeField(fields[6])
            }
            if entry.timeText == "" then
                entry.timeText = ChatLogManager.buildTimeLabel(timestamp)
            end
            if entry.dateText == "" then
                entry.dateText = ChatLogManager.buildDateLabel(timestamp)
            end
            if entry.channel == "" then
                entry.channel = "Server chat"
            end
            if ChatLogManager.isPlayerSpeaker(entry.speaker) then
            entry.display = ChatLogManager.makeDisplay(entry)
            entry.searchText = ChatLogManager.buildSearchText(entry)
            table.insert(result, entry)
            end
        end
    end

    table.sort(result, function(a, b)
        return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0)
    end)
    return result
end

function ChatLogManager.load()
    UtilityManager.ensureConfigDirectory()
    ChatLogManager.configPath = UtilityManager.getConfigPath("chat_logs.ini")
    ChatLogManager.entries = {}
    ChatLogManager.grouped = {}
    ChatLogManager.orderedDates = {}
    ChatLogManager.confirmReset = false
    ChatLogManager.expandedDates = {}
    ChatLogManager.dirty = false
    ChatLogManager.lastSavedAtMs = 0
    ChatLogManager.dataVersion = 0
    ChatLogManager.filterCacheQuery = ""
    ChatLogManager.filterCacheVersion = -1
    ChatLogManager.filterCacheBuckets = nil

    local saved = UtilityManager.safeIniLoad(ChatLogManager.configPath, "Chat Log load")
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}
    ChatLogManager.maxEntries = UtilityManager.clamp(math.floor(tonumber(main.maxEntries) or 3500), 500, 12000)

    local dates = {}
    if type(saved) == "table" then
        for sectionName, section in pairs(saved) do
            local idx = tonumber(tostring(sectionName or ""):match("^day_(%d+)$"))
            if idx and type(section) == "table" then
                dates[#dates + 1] = {
                    index = idx,
                    date = tostring(section.date or ""),
                    entries = ChatLogManager.deserializeEntries(section.entriesBlob or "")
                }
            end
        end
    end

    table.sort(dates, function(left, right)
        local l = ChatLogManager.dateSortValue(left.date)
        local r = ChatLogManager.dateSortValue(right.date)
        if l == r then
            return (left.index or 0) < (right.index or 0)
        end
        return l > r
    end)

    for _, bucket in ipairs(dates) do
        for _, entry in ipairs(bucket.entries or {}) do
            table.insert(ChatLogManager.entries, entry)
        end
    end
    ChatLogManager.rebuildGroups()
end

function ChatLogManager.save()
    UtilityManager.ensureConfigDirectory()
    if ChatLogManager.configPath == "" then
        ChatLogManager.configPath = UtilityManager.getConfigPath("chat_logs.ini")
    end

    local payload = {
        main = {
            maxEntries = tonumber(ChatLogManager.maxEntries) or 3500
        }
    }

    ChatLogManager.sortDates()
    for index, dateLabel in ipairs(ChatLogManager.orderedDates) do
        payload["day_" .. tostring(index)] = {
            date = tostring(dateLabel or ""),
            entriesBlob = ChatLogManager.serializeEntries(ChatLogManager.grouped[dateLabel] or {})
        }
    end

    local okSave = UtilityManager.safeIniSave(payload, ChatLogManager.configPath)
    if okSave then
        ChatLogManager.dirty = false
        ChatLogManager.lastSavedAtMs = UtilityManager.getNowMs()
    end
    return okSave
end

function ChatLogManager.markDirty()
    ChatLogManager.dirty = true
end

function ChatLogManager.clear()
    ChatLogManager.entries = {}
    ChatLogManager.grouped = {}
    ChatLogManager.orderedDates = {}
    ChatLogManager.confirmReset = false
    ChatLogManager.expandedDates = {}
    ChatLogManager.invalidateFilterCache()
    ChatLogManager.markDirty()
    ChatLogManager.save()
    if LogManager and LogManager.system then
        LogManager.system("Chat Log reset")
    end
end

function ChatLogManager.entryMatchesQuery(entry, query, queryIsFolded)
    local foldedQuery = queryIsFolded and tostring(query or "") or ChatLogManager.foldText(query)
    if foldedQuery == "" then
        return true
    end
    local searchText = tostring(entry.searchText or "")
    if searchText == "" then
        entry.searchText = ChatLogManager.buildSearchText(entry)
        searchText = entry.searchText
    end
    return searchText:find(foldedQuery, 1, true) ~= nil
end

function ChatLogManager.getFilteredBuckets(query)
    local foldedQuery = ChatLogManager.foldText(query)
    local cacheVersion = tonumber(ChatLogManager.filterCacheVersion) or -1
    local dataVersion = tonumber(ChatLogManager.dataVersion) or 0
    if ChatLogManager.filterCacheBuckets and
       tostring(ChatLogManager.filterCacheQuery or "") == foldedQuery and
       cacheVersion == dataVersion then
        return ChatLogManager.filterCacheBuckets
    end

    local buckets = {}
    for _, dateLabel in ipairs(ChatLogManager.orderedDates) do
        local visibleEntries = {}
        for _, entry in ipairs(ChatLogManager.grouped[dateLabel] or {}) do
            if ChatLogManager.entryMatchesQuery(entry, foldedQuery, true) then
                visibleEntries[#visibleEntries + 1] = entry
            end
        end
        if #visibleEntries > 0 then
            buckets[#buckets + 1] = {
                date = dateLabel,
                entries = visibleEntries
            }
        end
    end
    ChatLogManager.filterCacheQuery = foldedQuery
    ChatLogManager.filterCacheVersion = dataVersion
    ChatLogManager.filterCacheBuckets = buckets
    return buckets
end

function ChatLogManager.parseServerMessage(text)
    local source = PlayerLogManager and PlayerLogManager.normalizeServerText and
        PlayerLogManager.normalizeServerText(text) or ChatLogManager.sanitizeField(text)
    if source == "" or ChatLogManager.isIgnoredLine(source) then
        return nil
    end

    -- FIX #3: timestamp yo'q bo'lsa source ni body sifatida ishlatish to'g'ri,
    -- lekin body parse ham kerak bo'lsa source ni tekshiramiz
    local sourceTime, body = source:match("^%[(%d%d:%d%d:%d%d)%]%s*(.*)$")
    if not sourceTime then
        -- Timestamp yo'q: butun source ni body deb qabul qil
        body = source
    end
    body = UtilityManager.trim(body or source)
    if body == "" or ChatLogManager.isIgnoredLine(body) then
        return nil
    end

    local tagText, rest = body:match("^%[([^%]]+)%]%s*(.*)$")
    local channel = ChatLogManager.resolveChannel(tagText, body)
    local parseBody = UtilityManager.trim(rest or body)
    local speaker = ""
    local message = parseBody

    local responder, targetLabel, replyText = parseBody:match("^<ADM>%s*([^%[]+%[%d+%])%s*(.-)%s*ga javob berdi:%s*(.+)$")
    if responder and replyText then
        speaker = ChatLogManager.normalizeSpeaker(responder)
        message = ChatLogManager.sanitizeField(string.format("%s ga javob berdi: %s", UtilityManager.trim(targetLabel or ""), replyText))
        channel = "Admin chat"
    else
        local genericSpeaker, genericMessage = parseBody:match("^([^:]+):%s*(.+)$")
        if genericSpeaker and genericMessage then
            local normalizedSpeaker = ChatLogManager.normalizeSpeaker(genericSpeaker)
            if normalizedSpeaker ~= "" then
                speaker = normalizedSpeaker
                message = ChatLogManager.sanitizeField(genericMessage)
            else
                message = ChatLogManager.sanitizeField(parseBody)
            end
        else
            message = ChatLogManager.sanitizeField(parseBody)
        end
    end

    -- FIX #1: speaker bo'sh bo'lsa ham server xabarlarini saqla
    -- Avval faqat player xabarlari saqlanardi, endi barchasi saqlanadi
    if message == "" then
        return nil
    end

    local timestamp = os.time()
    local entry = {
        timestamp = timestamp,
        timeText = sourceTime and tostring(sourceTime):gsub(":", ".") or ChatLogManager.buildTimeLabel(timestamp),
        dateText = ChatLogManager.buildDateLabel(timestamp),
        channel = channel ~= "" and channel or "Server chat",
        speaker = speaker,
        message = message
    }
    entry.display = ChatLogManager.makeDisplay(entry)
    entry.searchText = ChatLogManager.buildSearchText(entry)
    return entry
end

function ChatLogManager.captureServerMessage(text)
    local entry = ChatLogManager.parseServerMessage(text)
    if not entry then
        return
    end

    ChatLogManager.attachEntry(entry)
    while #ChatLogManager.entries > (tonumber(ChatLogManager.maxEntries) or 3500) do
        local removed = table.remove(ChatLogManager.entries)
        if removed then
            ChatLogManager.removeEntryFromBucket(removed)
        end
    end
    ChatLogManager.markDirty()
end

function ChatLogManager.update()
    if not ChatLogManager.dirty then
        return
    end
    local nowMs = UtilityManager.getNowMs()
    if (nowMs - (tonumber(ChatLogManager.lastSavedAtMs) or 0)) < 1200 then
        return
    end
    ChatLogManager.save()
end

function ChatLogManager.renderLogsSection(scale, options)
    local buttonWidth = math.max(110, math.floor(120 * (tonumber(scale) or 1.0)))
    local buttonHeight = math.max(24, math.floor(26 * (tonumber(scale) or 1.0)))
    local embedded = type(options) == "table" and options.embedded == true
    local query = type(options) == "table" and tostring(options.query or "") or ""

    local function renderBody()
        if imgui.Button("Reset Log##ChatLogReset", imgui.ImVec2(buttonWidth, buttonHeight)) then
            ChatLogManager.confirmReset = true
        end
        if ChatLogManager.confirmReset then
            imgui.TextColored(COLORS.DANGER or imgui.ImVec4(1.0, 0.25, 0.25, 1.0),
                UtilityManager.toUtf8("Rostdan ham barcha chat loglarni o'chirmoqchimisiz?"))
            if imgui.Button("Ha##ChatLogResetYes", imgui.ImVec2(buttonWidth, buttonHeight)) then
                ChatLogManager.clear()
            end
            imgui.SameLine()
            if imgui.Button("Bekor qilish##ChatLogResetNo", imgui.ImVec2(buttonWidth, buttonHeight)) then
                ChatLogManager.confirmReset = false
            end
        end

        local buckets = ChatLogManager.getFilteredBuckets(query)
        if #buckets == 0 then
            if UtilityManager.trim(query) ~= "" then
                imgui.TextDisabled("Qidiruv bo'yicha chat log topilmadi.")
            else
                imgui.TextDisabled("Chat loglar hali yo'q.")
            end
            return
        end

        local function isDateExpanded(dateLabel)
            return ChatLogManager.expandedDates[tostring(dateLabel or "")] == true
        end

        local function renderEntry(entry)
            local textColor = COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1)
            local channelFolded = ChatLogManager.foldText(entry.channel)
            if channelFolded:find("admin", 1, true) then
                textColor = COLORS.WARNING or textColor
            elseif channelFolded:find("family", 1, true) then
                textColor = COLORS.INFO or textColor
            elseif channelFolded:find("vip", 1, true) then
                textColor = COLORS.PRIMARY or textColor
            end

            local header = string.format("%s | %s", tostring(entry.timeText or "--.--.--"), tostring(entry.channel or "Server chat"))
            if tostring(entry.speaker or "") ~= "" then
                header = string.format("%s | %s", header, ChatLogManager.formatSpeakerLabel(entry.speaker))
            end

            imgui.TextColored(textColor, header)
            if imgui.TextWrapped then
                imgui.TextWrapped(tostring(entry.message or ""))
            else
                imgui.Text(tostring(entry.message or ""))
            end
            imgui.Separator()
        end

        imgui.BeginChild("##ChatLogsByDate", imgui.ImVec2(0, 0), true)
        for index, bucket in ipairs(buckets) do
            local dateLabel = tostring(bucket.date or "")
            local expanded = isDateExpanded(dateLabel)
            local headerText = string.format("%s %s (%d)", expanded and "[-]" or "[+]", dateLabel, #bucket.entries)
            if imgui.Button(headerText .. "##ChatLogDate_" .. tostring(index), imgui.ImVec2(-1, 28)) then
                ChatLogManager.expandedDates[tostring(dateLabel)] = not expanded or nil
                expanded = isDateExpanded(dateLabel)
            end
            if expanded then
                imgui.Indent(10)
                for entryIndex, entry in ipairs(bucket.entries) do
                    renderEntry(entry)
                    if entryIndex < #bucket.entries then
                        imgui.Spacing()
                    end
                end
                imgui.Unindent(10)
            end
        end
        imgui.EndChild()
    end

    if embedded then
        renderBody()
        return
    end

    if imgui.CollapsingHeader("Server Chat Log") then
        renderBody()
    end
end

function ChatLogManager.initialize()
    ChatLogManager.load()
    if LogManager and LogManager.system then
        LogManager.system("Chat Log initialized")
    end
end

-- ============================================
-- KILL LIST MANAGER
-- ============================================
KillListManager = {
    entries = {},
    grouped = {},
    orderedDates = {},
    configPath = "",
    confirmReset = false,
    expandedDates = {},
    dateAnimations = {},
    lastEventKey = "",
    lastEventAtMs = 0,
    maxOverlayEntries = 60,
    overlay = {
        pos = { x = 20, y = 220 },
        size = { width = 420, height = 220 },
        initialized = false,
        dirty = false,
        lastSavedAtMs = 0
    },
    dataVersion = 0,
    filterCacheQuery = "",
    filterCacheVersion = -1,
    filterCacheBuckets = nil
}

function KillListManager.sanitizeNick(value, fallback)
    local text = UtilityManager.trim(tostring(value or ""))
    text = text:gsub("[%c\r\n\t]", " ")
    if text == "" then
        text = tostring(fallback or "Unknown")
    end
    return text
end

function KillListManager.normalizePlayerId(value, fallback)
    local numeric = tonumber(value)
    if not numeric then
        return tonumber(fallback) or 0
    end
    if numeric == 65535 then
        return 0
    end
    if numeric < 0 then
        return tonumber(fallback) or 0
    end
    return math.floor(numeric)
end

function KillListManager.playerIdToText(value)
    local numeric = tonumber(value)
    if numeric == nil then
        return "?"
    end
    numeric = math.floor(numeric)
    if numeric < 0 then
        return "?"
    end
    return tostring(numeric)
end

function KillListManager.getPlayerNick(playerId, fallback)
    local numericId = tonumber(playerId)
    if numericId == 65535 or numericId == 0 then
        return KillListManager.sanitizeNick(fallback, "World")
    end
    if numericId and numericId >= 0 and type(sampIsPlayerConnected) == "function" and type(sampGetPlayerNickname) == "function" then
        local okConnected, connected = pcall(sampIsPlayerConnected, numericId)
        if okConnected and connected then
            local okNick, nick = pcall(sampGetPlayerNickname, numericId)
            if okNick and tostring(nick or "") ~= "" then
                return KillListManager.sanitizeNick(nick, fallback)
            end
        end
    end
    if PlayerLogManager and type(PlayerLogManager.ensurePlayer) == "function" and numericId and numericId > 0 then
        local okEnsure, data = pcall(PlayerLogManager.ensurePlayer, numericId, "")
        if okEnsure and type(data) == "table" then
            local profile = type(data.profile) == "table" and data.profile or {}
            local nick = tostring(profile.nickname or data.nick or "")
            if nick ~= "" then
                return KillListManager.sanitizeNick(nick, fallback)
            end
        end
    end
    if numericId and numericId > 0 then
        return KillListManager.sanitizeNick(fallback, "Player" .. tostring(numericId))
    end
    return KillListManager.sanitizeNick(fallback, "Unknown")
end

function KillListManager.buildDateLabel(timestamp)
    return os.date("%d.%m.%Y", tonumber(timestamp) or os.time())
end

function KillListManager.buildTimeLabel(timestamp)
    return os.date("%H:%M:%S", tonumber(timestamp) or os.time())
end

function KillListManager.dateSortValue(dateLabel)
    local day, month, year = tostring(dateLabel or ""):match("^(%d%d)%.(%d%d)%.(%d%d%d%d)$")
    if not day or not month or not year then
        return 0
    end
    return (tonumber(year) or 0) * 10000 + (tonumber(month) or 0) * 100 + (tonumber(day) or 0)
end

function KillListManager.makeDisplay(entry)
    return string.format("%s(%s) - %s(%s) - %s",
        KillListManager.sanitizeNick(entry.killerNick, "Unknown"),
        KillListManager.playerIdToText(entry.killerId),
        KillListManager.sanitizeNick(entry.victimNick, "Unknown"),
        KillListManager.playerIdToText(entry.victimId),
        tostring(entry.timeText or KillListManager.buildTimeLabel(entry.timestamp)))
end

function KillListManager.sortDates()
    table.sort(KillListManager.orderedDates, function(left, right)
        local l = KillListManager.dateSortValue(left)
        local r = KillListManager.dateSortValue(right)
        if l == r then
            return tostring(left or "") > tostring(right or "")
        end
        return l > r
    end)
end

function KillListManager.ensureDateBucket(dateLabel)
    local label = tostring(dateLabel or KillListManager.buildDateLabel(os.time()))
    if type(KillListManager.grouped[label]) ~= "table" then
        KillListManager.grouped[label] = {}
        table.insert(KillListManager.orderedDates, label)
        KillListManager.sortDates()
    end
    return KillListManager.grouped[label]
end

function KillListManager.invalidateFilterCache()
    KillListManager.dataVersion = (tonumber(KillListManager.dataVersion) or 0) + 1
    KillListManager.filterCacheQuery = ""
    KillListManager.filterCacheVersion = -1
    KillListManager.filterCacheBuckets = nil
end

function KillListManager.serializeField(value)
    return tostring(value or ""):gsub("[\t\r\n]", " ")
end

function KillListManager.hexEncodeBlob(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    local out = {}
    for i = 1, #value do
        out[#out + 1] = string.format("%02X", value:byte(i))
    end
    return table.concat(out)
end

function KillListManager.hexDecodeBlob(text)
    local value = tostring(text or "")
    if value == "" then
        return ""
    end

    local out = {}
    for hex in value:gmatch("%x%x") do
        out[#out + 1] = string.char(tonumber(hex, 16) or 0)
    end
    return table.concat(out)
end

function KillListManager.hasLegacyBrokenIni(path)
    local configPath = tostring(path or "")
    if configPath == "" then
        return false
    end

    local handle = io.open(configPath, "r")
    if not handle then
        return false
    end

    local raw = handle:read("*a") or ""
    handle:close()
    if raw == "" or not raw:find("entriesBlob%s*=", 1) then
        return false
    end

    local trackingEntries = false
    for line in raw:gmatch("[^\r\n]+") do
        if line:match("^%s*%[") then
            trackingEntries = false
        elseif line:match("^%s*entriesBlob%s*=") then
            trackingEntries = true
        elseif trackingEntries then
            if not line:find("=", 1, true) then
                return true
            end
            trackingEntries = false
        end
    end

    return false
end

function KillListManager.parseLegacyIni(path)
    -- safety fix: migrate old multiline entriesBlob format without letting inicfg touch malformed files.
    local configPath = tostring(path or "")
    if configPath == "" then
        return nil
    end

    local handle = io.open(configPath, "r")
    if not handle then
        return nil
    end

    local raw = handle:read("*a") or ""
    handle:close()
    if raw == "" then
        return nil
    end

    local parsed = {}
    local currentSection = nil
    local currentSectionName = nil
    local collectingBlob = false

    for line in (raw .. "\n"):gmatch("([^\r\n]*)\r?\n") do
        local sectionName = line:match("^%s*%[([^%]]+)%]%s*$")
        if sectionName then
            currentSectionName = tostring(sectionName)
            currentSection = parsed[currentSectionName]
            if type(currentSection) ~= "table" then
                currentSection = {}
                parsed[currentSectionName] = currentSection
            end
            collectingBlob = false
        elseif currentSectionName and currentSection then
            local key, value = line:match("^%s*([^=]+)%s*=%s*(.*)$")
            if key then
                local normalizedKey = UtilityManager.trim(key)
                local normalizedValue = tostring(value or "")
                currentSection[normalizedKey] = normalizedValue
                collectingBlob = normalizedKey == "entriesBlob"
            elseif collectingBlob then
                local continuation = tostring(line or "")
                if continuation ~= "" then
                    local existing = tostring(currentSection.entriesBlob or "")
                    if existing ~= "" then
                        currentSection.entriesBlob = existing .. "\n" .. continuation
                    else
                        currentSection.entriesBlob = continuation
                    end
                end
            end
        end
    end

    return parsed
end

function KillListManager.serializeEntries(entries)
    local lines = {}
    for _, entry in ipairs(entries or {}) do
        lines[#lines + 1] = table.concat({
            tostring(math.floor(tonumber(entry.timestamp) or os.time())),
            KillListManager.serializeField(entry.killerNick),
            KillListManager.playerIdToText(entry.killerId),
            KillListManager.serializeField(entry.victimNick),
            KillListManager.playerIdToText(entry.victimId),
            KillListManager.serializeField(entry.timeText or ""),
            KillListManager.serializeField(entry.dateText or "")
        }, "\t")
    end
    return "hex:" .. KillListManager.hexEncodeBlob(table.concat(lines, "\n"))
end

function KillListManager.buildSearchText(entry)
    return table.concat({
        UtilityManager.casefoldUtf8Cyrillic(tostring(entry.timeText or "")),
        UtilityManager.casefoldUtf8Cyrillic(tostring(entry.dateText or "")),
        UtilityManager.casefoldUtf8Cyrillic(tostring(entry.killerNick or "")),
        tostring(tonumber(entry.killerId) or 0),
        UtilityManager.casefoldUtf8Cyrillic(tostring(entry.victimNick or "")),
        tostring(tonumber(entry.victimId) or 0),
        UtilityManager.casefoldUtf8Cyrillic(tostring(entry.display or ""))
    }, " ")
end

function KillListManager.entryMatchesQuery(entry, query, queryIsFolded)
    local foldedQuery = queryIsFolded and tostring(query or "") or UtilityManager.casefoldUtf8Cyrillic(UtilityManager.trim(tostring(query or "")))
    if foldedQuery == "" then
        return true
    end
    local searchText = tostring(entry.searchText or "")
    if searchText == "" then
        entry.searchText = KillListManager.buildSearchText(entry)
        searchText = entry.searchText
    end
    return searchText:find(foldedQuery, 1, true) ~= nil
end

function KillListManager.getFilteredBuckets(query)
    local foldedQuery = UtilityManager.casefoldUtf8Cyrillic(UtilityManager.trim(tostring(query or "")))
    local cacheVersion = tonumber(KillListManager.filterCacheVersion) or -1
    local dataVersion = tonumber(KillListManager.dataVersion) or 0
    if KillListManager.filterCacheBuckets and
       tostring(KillListManager.filterCacheQuery or "") == foldedQuery and
       cacheVersion == dataVersion then
        return KillListManager.filterCacheBuckets
    end

    local buckets = {}
    for _, dateLabel in ipairs(KillListManager.orderedDates) do
        local matches = {}
        for _, entry in ipairs(KillListManager.grouped[dateLabel] or {}) do
            if KillListManager.entryMatchesQuery(entry, foldedQuery, true) then
                matches[#matches + 1] = entry
            end
        end
        if #matches > 0 then
            buckets[#buckets + 1] = { date = dateLabel, entries = matches }
        end
    end
    KillListManager.filterCacheQuery = foldedQuery
    KillListManager.filterCacheVersion = dataVersion
    KillListManager.filterCacheBuckets = buckets
    return buckets
end

function KillListManager.deserializeEntries(blob, forcedDate)
    local result = {}
    local source = tostring(blob or "")
    if source:sub(1, 4) == "hex:" then
        source = KillListManager.hexDecodeBlob(source:sub(5))
    end

    for line in source:gmatch("[^\r\n]+") do
        local fields = UtilityManager.splitString(line, "\t")
        local timestamp = tonumber(fields[1])
        local killerNick = KillListManager.sanitizeNick(fields[2], "Unknown")
        local killerId = tonumber(fields[3]) or 0
        local victimNick = KillListManager.sanitizeNick(fields[4], "Unknown")
        local victimId = tonumber(fields[5]) or 0
        local timeText = UtilityManager.trim(fields[6] or "")
        local dateText = UtilityManager.trim(fields[7] or forcedDate or "")
        if timestamp then
            local entry = {
                timestamp = timestamp,
                killerNick = killerNick,
                killerId = killerId,
                victimNick = victimNick,
                victimId = victimId,
                timeText = timeText ~= "" and timeText or KillListManager.buildTimeLabel(timestamp),
                dateText = dateText ~= "" and dateText or KillListManager.buildDateLabel(timestamp)
            }
            entry.display = KillListManager.makeDisplay(entry)
            entry.searchText = KillListManager.buildSearchText(entry)
            table.insert(result, entry)
        end
    end
    table.sort(result, function(a, b)
        return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0)
    end)
    return result
end

function KillListManager.applyLoadedState(saved)
    -- safety fix: centralize restored state so both migrated and normal INI loads behave identically.
    local overlay = KillListManager.overlay
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}

    overlay.pos.x = tonumber(main.overlayPosX) or overlay.pos.x or 20
    overlay.pos.y = tonumber(main.overlayPosY) or overlay.pos.y or 220
    overlay.size.width = tonumber(main.overlayWidth) or overlay.size.width or 420
    overlay.size.height = tonumber(main.overlayHeight) or overlay.size.height or 220
    overlay.initialized = false
    overlay.dirty = false
    overlay.lastSavedAtMs = 0

    if type(saved) ~= "table" then
        return false
    end

    local dates = {}
    for sectionName, section in pairs(saved) do
        local idx = tonumber(tostring(sectionName or ""):match("^day_(%d+)$"))
        if idx and type(section) == "table" then
            dates[#dates + 1] = {
                index = idx,
                date = tostring(section.date or ""),
                entries = KillListManager.deserializeEntries(section.entriesBlob or "", section.date or "")
            }
        end
    end

    table.sort(dates, function(left, right)
        local l = KillListManager.dateSortValue(left.date)
        local r = KillListManager.dateSortValue(right.date)
        if l == r then
            return (left.index or 0) < (right.index or 0)
        end
        return l > r
    end)

    for _, bucket in ipairs(dates) do
        local dateLabel = UtilityManager.trim(bucket.date or "")
        if dateLabel ~= "" and #bucket.entries > 0 then
            KillListManager.grouped[dateLabel] = bucket.entries
            KillListManager.orderedDates[#KillListManager.orderedDates + 1] = dateLabel
            for _, entry in ipairs(bucket.entries) do
                table.insert(KillListManager.entries, entry)
            end
        end
    end

    table.sort(KillListManager.entries, function(a, b)
        return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0)
    end)
    KillListManager.sortDates()
    return true
end

function KillListManager.load()
    UtilityManager.ensureConfigDirectory()
    KillListManager.configPath = UtilityManager.getConfigPath("kill_list.ini")
    KillListManager.entries = {}
    KillListManager.grouped = {}
    KillListManager.orderedDates = {}
    KillListManager.confirmReset = false
    KillListManager.expandedDates = {}
    KillListManager.dateAnimations = {}
    KillListManager.dataVersion = 0
    KillListManager.filterCacheQuery = ""
    KillListManager.filterCacheVersion = -1
    KillListManager.filterCacheBuckets = nil

    if KillListManager.hasLegacyBrokenIni(KillListManager.configPath) then
        if LogManager and LogManager.system then
            LogManager.system("Kill List legacy INI format detected, migrating storage")
        end
        local migrated = KillListManager.parseLegacyIni(KillListManager.configPath)
        local migratedOk = KillListManager.applyLoadedState(migrated)
        KillListManager.save()
        return migratedOk
    end

    local saved = UtilityManager.safeIniLoad(KillListManager.configPath, "Kill List load")
    return KillListManager.applyLoadedState(saved)
end

function KillListManager.save()
    UtilityManager.ensureConfigDirectory()
    if KillListManager.configPath == "" then
        KillListManager.configPath = UtilityManager.getConfigPath("kill_list.ini")
    end

    local overlay = KillListManager.overlay or {}
    local payload = {
        main = {
            overlayPosX = tonumber(overlay.pos and overlay.pos.x) or 20,
            overlayPosY = tonumber(overlay.pos and overlay.pos.y) or 220,
            overlayWidth = tonumber(overlay.size and overlay.size.width) or 420,
            overlayHeight = tonumber(overlay.size and overlay.size.height) or 220
        }
    }

    KillListManager.sortDates()
    for index, dateLabel in ipairs(KillListManager.orderedDates) do
        payload["day_" .. tostring(index)] = {
            date = tostring(dateLabel or ""),
            entriesBlob = KillListManager.serializeEntries(KillListManager.grouped[dateLabel] or {})
        }
    end

    local okSave = UtilityManager.safeIniSave(payload, KillListManager.configPath)
    if not okSave and LogManager and LogManager.error then
        LogManager.error("Kill List save failed", { path = KillListManager.configPath })
    end
    return okSave
end

function KillListManager.touchOverlayState()
    KillListManager.overlay.dirty = true
end

function KillListManager.flushOverlayState(force)
    local overlay = KillListManager.overlay
    if not overlay or not overlay.dirty then
        return
    end
    local nowMs = RuntimeGuard and RuntimeGuard.getNowMs and RuntimeGuard.getNowMs() or math.floor(os.clock() * 1000)
    if not force and (nowMs - (tonumber(overlay.lastSavedAtMs) or 0)) < 900 then
        return
    end
    overlay.lastSavedAtMs = nowMs
    overlay.dirty = false
    KillListManager.save()
end

function KillListManager.getSpectateQuickBounds()
    if not (SpectateQuickPanel and SpectateQuickPanel.active and SpectateQuickPanel.cursorVisible and SpectateQuickPanel.ui) then
        return nil
    end

    local ui = SpectateQuickPanel.ui
    local x = tonumber(ui.quickPos and ui.quickPos.x)
    local y = tonumber(ui.quickPos and ui.quickPos.y)
    local width = tonumber(ui.quickSize and ui.quickSize.width)
    local height = tonumber(ui.quickSize and ui.quickSize.height)
    if not x or not y or not width or not height or width <= 0 or height <= 0 then
        return nil
    end

    return {
        x = x,
        y = y,
        width = width,
        height = height
    }
end

function KillListManager.resolvePassiveOverlayRect(posX, posY, width, height, screenX, screenY)
    local renderX = posX
    local renderY = posY
    local spectateBounds = KillListManager.getSpectateQuickBounds()
    if not spectateBounds then
        return renderX, renderY, false
    end

    local overlap = not (
        (renderX + width) < spectateBounds.x or
        renderX > (spectateBounds.x + spectateBounds.width) or
        (renderY + height) < spectateBounds.y or
        renderY > (spectateBounds.y + spectateBounds.height)
    )
    if not overlap then
        return renderX, renderY, true
    end

    local padding = 12
    local aboveY = spectateBounds.y - height - padding
    if aboveY >= 10 then
        renderY = aboveY
    else
        local leftX = spectateBounds.x - width - padding
        local rightX = spectateBounds.x + spectateBounds.width + padding
        if leftX >= 10 then
            renderX = leftX
        elseif rightX <= (screenX - 10) then
            renderX = rightX
        else
            renderY = UtilityManager.clamp(aboveY, 10, math.max(10, screenY - height - 10))
        end
    end

    renderX = UtilityManager.clamp(renderX, 10, math.max(10, screenX - width - 10))
    renderY = UtilityManager.clamp(renderY, 10, math.max(10, screenY - height - 10))
    return renderX, renderY, true
end

function KillListManager.drawOverlayCard(drawList, renderX, renderY, width, height)
    -- style fix: use one shared renderer so Kill List keeps the same look with or without the main menu.
    if not drawList or type(drawList.AddRectFilled) ~= "function" or type(drawList.AddText) ~= "function" then
        return
    end

    local minPos = imgui.ImVec2(renderX, renderY)
    local maxPos = imgui.ImVec2(renderX + width, renderY + height)
    local radius = 18
    local base = imgui.ImVec4(0.09, 0.03, 0.04, 0.92)
    local bodyBg = imgui.ImVec4(0.08, 0.03, 0.04, 0.90)
    local border = COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 0.98)
    local titleColor = COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0)
    local dimColor = COLORS.TEXT_DIM or imgui.ImVec4(0.76, 0.76, 0.76, 0.95)
    local bodyMin = imgui.ImVec2(minPos.x + 8, minPos.y + 36)
    local bodyMax = imgui.ImVec2(maxPos.x - 8, maxPos.y - 8)
    local countText = tostring(#KillListManager.entries)

    drawList:AddRectFilled(minPos, maxPos, MainUI.colorToU32(base), radius)
    drawList:AddRect(minPos, maxPos, MainUI.colorToU32(border), radius, 0, 1.5)
    drawList:AddText(imgui.ImVec2(minPos.x + 12, minPos.y + 10), MainUI.colorToU32(titleColor), "Kill List")
    drawList:AddText(imgui.ImVec2(minPos.x + 72, minPos.y + 10), MainUI.colorToU32(dimColor), "|")
    drawList:AddText(imgui.ImVec2(minPos.x + 82, minPos.y + 10), MainUI.colorToU32(dimColor), "Kunlik kill loglar")
    local countPosX = maxPos.x - 12
    if imgui.CalcTextSize then
        local okSize, size = pcall(imgui.CalcTextSize, countText)
        if okSize and size then
            countPosX = maxPos.x - (tonumber(size.x) or 0) - 12
        end
    end
    drawList:AddText(imgui.ImVec2(countPosX, minPos.y + 10), MainUI.colorToU32(dimColor), countText)
    if type(drawList.AddLine) == "function" then
        drawList:AddLine(
            imgui.ImVec2(minPos.x + 10, minPos.y + 30),
            imgui.ImVec2(maxPos.x - 10, minPos.y + 30),
            MainUI.colorToU32(imgui.ImVec4(border.x, border.y, border.z, 0.72)),
            1.0
        )
    end

    local startY = bodyMin.y + 8
    local rowHeight = 22
    local rowGap = 5
    local maxLines = math.max(1, math.floor((height - 64) / (rowHeight + rowGap)))
    local total = math.min(#KillListManager.entries, maxLines)

    if total <= 0 then
        drawList:AddText(imgui.ImVec2(bodyMin.x + 10, bodyMin.y + 10), MainUI.colorToU32(dimColor), "Kill loglar hali yo'q.")
        return
    end

    for index = 1, total do
        local entry = KillListManager.entries[index]
        if entry then
            local text = UtilityManager.toUtf8(entry.display or "")
            if #text > 62 then
                text = text:sub(1, 59) .. "..."
            end
            local rowY = startY + ((index - 1) * (rowHeight + rowGap))
            local rowMin = imgui.ImVec2(bodyMin.x + 8, rowY)
            local rowMax = imgui.ImVec2(bodyMax.x - 8, rowY + rowHeight)
            local rowFill = index == 1 and imgui.ImVec4(0.16, 0.05, 0.07, 0.96) or imgui.ImVec4(0.12, 0.04, 0.06, 0.93)
            drawList:AddRectFilled(rowMin, rowMax, MainUI.colorToU32(rowFill), 12)
            drawList:AddRect(rowMin, rowMax, MainUI.colorToU32(imgui.ImVec4(border.x, border.y, border.z, 0.52)), 12, 0, 1.0)
            drawList:AddText(imgui.ImVec2(rowMin.x + 8, rowMin.y + 4), MainUI.colorToU32(dimColor), text)
        end
    end
end

function KillListManager.clear()
    KillListManager.entries = {}
    KillListManager.grouped = {}
    KillListManager.orderedDates = {}
    KillListManager.confirmReset = false
    KillListManager.expandedDates = {}
    KillListManager.dateAnimations = {}
    KillListManager.lastEventKey = ""
    KillListManager.lastEventAtMs = 0
    KillListManager.invalidateFilterCache()
    KillListManager.save()
    if LogManager and LogManager.system then
        LogManager.system("Kill List reset")
    end
end

function KillListManager.recordKill(killerId, killedId, reason)
    local killerNumeric = KillListManager.normalizePlayerId(killerId, 0)
    local victimNumeric = KillListManager.normalizePlayerId(killedId, 0)
    local killerNick = KillListManager.getPlayerNick(killerId, killerNumeric == 0 and "World" or nil)
    local victimNick = KillListManager.getPlayerNick(killedId, nil)

    if victimNick == "" then
        victimNick = "Unknown"
    end

    local nowTs = os.time()
    local nowMs = RuntimeGuard and RuntimeGuard.getNowMs and RuntimeGuard.getNowMs() or math.floor(os.clock() * 1000)
    local dedupeKey = table.concat({
        tostring(killerNick or ""),
        tostring(killerNumeric or 0),
        tostring(victimNick or ""),
        tostring(victimNumeric or 0)
    }, "|")
    if KillListManager.lastEventKey == dedupeKey and (nowMs - (tonumber(KillListManager.lastEventAtMs) or 0)) < 1200 then
        return false
    end
    KillListManager.lastEventKey = dedupeKey
    KillListManager.lastEventAtMs = nowMs

    local entry = {
        timestamp = nowTs,
        killerNick = KillListManager.sanitizeNick(killerNick, "Unknown"),
        killerId = killerNumeric,
        victimNick = KillListManager.sanitizeNick(victimNick, "Unknown"),
        victimId = victimNumeric,
        timeText = KillListManager.buildTimeLabel(nowTs),
        dateText = KillListManager.buildDateLabel(nowTs),
        reason = tonumber(reason) or 0
    }
    entry.display = KillListManager.makeDisplay(entry)
    entry.searchText = KillListManager.buildSearchText(entry)

    table.insert(KillListManager.entries, 1, entry)
    local bucket = KillListManager.ensureDateBucket(entry.dateText)
    table.insert(bucket, 1, entry)
    KillListManager.invalidateFilterCache()
    KillListManager.save()
    return true
end

function KillListManager.isOverlayVisible()
    return SettingsManager and SettingsManager.get and SettingsManager.get("killListOverlayEnabled") == true
end

function KillListManager.renderOverlay()
    if not KillListManager.isOverlayVisible() then
        return
    end

    local interactive = MainUI and MainUI.window and MainUI.window.open == true
    local overlay = KillListManager.overlay
    overlay.pos = overlay.pos or { x = 20, y = 220 }
    overlay.size = overlay.size or { width = 420, height = 220 }

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080

    local minWidth = 300
    local minHeight = 150
    local maxWidth = math.max(minWidth, screenX - 10)
    local maxHeight = math.max(minHeight, screenY - 10)

    local width = UtilityManager.clamp(tonumber(overlay.size.width) or 420, minWidth, maxWidth)
    local height = UtilityManager.clamp(tonumber(overlay.size.height) or 220, minHeight, maxHeight)
    local posX = UtilityManager.clamp(tonumber(overlay.pos.x) or 20, 10, math.max(10, screenX - width - 10))
    local posY = UtilityManager.clamp(tonumber(overlay.pos.y) or 220, 10, math.max(10, screenY - height - 10))

    if not interactive then
        -- safety fix: passive kill overlay must never force the game cursor on or create an interactive imgui window.
        imgui.Process = false
        imgui.ShowCursor = false
        overlay.pos.x = posX
        overlay.pos.y = posY
        overlay.size.width = width
        overlay.size.height = height

        local drawList = nil
        local renderX, renderY, spectateActive = KillListManager.resolvePassiveOverlayRect(posX, posY, width, height, screenX, screenY)
        if spectateActive and imgui.GetBackgroundDrawList then
            local okDraw, value = pcall(imgui.GetBackgroundDrawList)
            if okDraw then
                drawList = value
            end
        end
        if (not drawList) and imgui.GetForegroundDrawList then
            local okDraw, value = pcall(imgui.GetForegroundDrawList)
            if okDraw then
                drawList = value
            end
        end
        if (not drawList) and imgui.GetBackgroundDrawList then
            local okDraw, value = pcall(imgui.GetBackgroundDrawList)
            if okDraw then
                drawList = value
            end
        end
        if not drawList or type(drawList.AddRectFilled) ~= "function" or type(drawList.AddText) ~= "function" then
            return
        end

        KillListManager.drawOverlayCard(drawList, renderX, renderY, width, height)
        return
    end

    if not overlay.initialized then
        imgui.SetNextWindowPos(imgui.ImVec2(posX, posY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
        overlay.initialized = true
    end
    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(
            imgui.ImVec2(minWidth, minHeight),
            imgui.ImVec2(maxWidth, maxHeight)
        )
    end

    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoSavedSettings + (imgui.WindowFlags.NoTitleBar or 0)
    if not interactive then
        flags = flags +
            imgui.WindowFlags.NoInputs +
            imgui.WindowFlags.NoMove +
            imgui.WindowFlags.NoResize +
            imgui.WindowFlags.NoNavFocus +
            imgui.WindowFlags.NoBringToFrontOnFocus
    end

    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.00, 0.00, 0.00, 0.01))
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0.00, 0.00, 0.00, 0.00))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        if imgui.StyleVar.WindowRounding then
            imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 12)
            styleVarPushed = styleVarPushed + 1
        end
        if imgui.StyleVar.WindowPadding then
            imgui.PushStyleVar(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
            styleVarPushed = styleVarPushed + 1
        end
        if imgui.StyleVar.WindowBorderSize then
            imgui.PushStyleVar(imgui.StyleVar.WindowBorderSize, 0)
            styleVarPushed = styleVarPushed + 1
        end
    end

    if imgui.Begin("Kill List##KillListOverlay", nil, flags) then
        local drawList = imgui.GetWindowDrawList and imgui.GetWindowDrawList() or nil
        if interactive then
            local windowPos = imgui.GetWindowPos()
            local windowSize = imgui.GetWindowSize()
            local changed = false

            if windowPos then
                local clampedX = UtilityManager.clamp(windowPos.x, 10, math.max(10, screenX - (windowSize and windowSize.x or width) - 10))
                local clampedY = UtilityManager.clamp(windowPos.y, 10, math.max(10, screenY - (windowSize and windowSize.y or height) - 10))
                if math.abs((tonumber(overlay.pos.x) or 0) - clampedX) > 0.5 or math.abs((tonumber(overlay.pos.y) or 0) - clampedY) > 0.5 then
                    overlay.pos.x = clampedX
                    overlay.pos.y = clampedY
                    changed = true
                end
            end
            if windowSize then
                local clampedW = UtilityManager.clamp(windowSize.x, minWidth, maxWidth)
                local clampedH = UtilityManager.clamp(windowSize.y, minHeight, maxHeight)
                if math.abs((tonumber(overlay.size.width) or 0) - clampedW) > 0.5 or math.abs((tonumber(overlay.size.height) or 0) - clampedH) > 0.5 then
                    overlay.size.width = clampedW
                    overlay.size.height = clampedH
                    changed = true
                end
            end
            if changed then
                KillListManager.touchOverlayState()
            end
            if drawList and windowPos and windowSize then
                KillListManager.drawOverlayCard(drawList, windowPos.x, windowPos.y, windowSize.x, windowSize.y)
            end
        end

        local contentSize = imgui.GetWindowSize()
        if contentSize then
            imgui.Dummy(imgui.ImVec2(
                math.max(8, (tonumber(contentSize.x) or width) - 4),
                math.max(8, (tonumber(contentSize.y) or height) - 4)
            ))
        end
    end

    imgui.End()
    if styleVarPushed > 0 then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)

    KillListManager.flushOverlayState(interactive == false)
end

function KillListManager.renderLogsSection(scale, options)
    local buttonWidth = math.max(110, math.floor(120 * (tonumber(scale) or 1.0)))
    local buttonHeight = math.max(24, math.floor(26 * (tonumber(scale) or 1.0)))
    local embedded = type(options) == "table" and options.embedded == true
    local query = type(options) == "table" and UtilityManager.trim(tostring(options.query or "")) or ""

    local function renderBody()
        if imgui.Button("Reset Log##KillListReset", imgui.ImVec2(buttonWidth, buttonHeight)) then
            KillListManager.confirmReset = true
        end
        if KillListManager.confirmReset then
            imgui.TextColored(COLORS.DANGER or imgui.ImVec4(1.0, 0.25, 0.25, 1.0),
                UtilityManager.toUtf8("Rostdan ham barcha kill loglarni o'chirmoqchimisiz?"))
            if imgui.Button("Ha##KillListResetYes", imgui.ImVec2(buttonWidth, buttonHeight)) then
                KillListManager.clear()
            end
            imgui.SameLine()
            if imgui.Button("Bekor qilish##KillListResetNo", imgui.ImVec2(buttonWidth, buttonHeight)) then
                KillListManager.confirmReset = false
            end
        end

        local buckets = query ~= "" and KillListManager.getFilteredBuckets(query) or nil
        if buckets and #buckets == 0 then
            imgui.TextDisabled("Qidiruv bo'yicha kill log topilmadi.")
            return
        end
        if not buckets and #KillListManager.orderedDates == 0 then
            imgui.TextDisabled("Kill loglar hali yo'q.")
            return
        end

        local function isDateExpanded(dateLabel)
            return KillListManager.expandedDates[tostring(dateLabel or "")] == true
        end

        local function syncDateAnim(dateLabel, delta)
            local key = tostring(dateLabel or "")
            local state = KillListManager.dateAnimations[key]
            if not state then
                state = { value = 0, target = 0 }
                KillListManager.dateAnimations[key] = state
            end

            state.target = isDateExpanded(key) and 1 or 0
            local blend = UtilityManager.clamp((tonumber(delta) or (1 / 60)) * 10.0, 0.08, 0.45)
            state.value = UtilityManager.lerp(tonumber(state.value) or 0, tonumber(state.target) or 0, blend)
            if math.abs((tonumber(state.value) or 0) - (tonumber(state.target) or 0)) < 0.015 then
                state.value = state.target
            end

            if state.value <= 0.001 and state.target == 0 then
                return 0
            end

            if MainUI and type(MainUI.easeInOutSine) == "function" then
                return MainUI.easeInOutSine(state.value)
            end

            return UtilityManager.clamp(tonumber(state.value) or 0, 0, 1)
        end

        local function renderDateHeader(dateLabel, entryCount, expanded, index, entryScale)
            local availX = math.max(120, tonumber(imgui.GetContentRegionAvail().x) or 120)
            local rowHeight = math.max(28, math.floor(32 * (tonumber(entryScale) or 1.0)))
            local screenPos = imgui.GetCursorScreenPos()
            local key = string.format("##KillListDateRow_%d", tonumber(index) or 0)
            local clicked = imgui.InvisibleButton(key, imgui.ImVec2(availX, rowHeight))
            local hovered = imgui.IsItemHovered()
            local held = imgui.IsItemActive()
            local drawList = imgui.GetWindowDrawList and imgui.GetWindowDrawList() or nil

            if drawList and type(drawList.AddRectFilled) == "function" and MainUI and type(MainUI.colorToU32) == "function" then
                local idleBg = imgui.ImVec4(0.10, 0.04, 0.05, 0.76)
                local hoverBg = imgui.ImVec4(0.16, 0.05, 0.07, 0.88)
                local openBg = MainUI.mixColor and MainUI.mixColor(idleBg, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 1.0), 0.28) or hoverBg
                local bg = expanded and openBg or (hovered and hoverBg or idleBg)
                local border = COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 1.0)
                if held then
                    bg = MainUI.mixColor and MainUI.mixColor(bg, border, 0.18) or bg
                end

                local minPos = imgui.ImVec2(screenPos.x, screenPos.y)
                local maxPos = imgui.ImVec2(screenPos.x + availX, screenPos.y + rowHeight)
                drawList:AddRectFilled(minPos, maxPos, MainUI.colorToU32(bg), 10)
                drawList:AddRect(minPos, maxPos, MainUI.colorToU32(border), 10, 0, 1.0)

                local marker = expanded and "[-]" or "[+]"
                local label = string.format("%s %s", marker, tostring(dateLabel or "Unknown date"))
                local countText = string.format("%d", tonumber(entryCount) or 0)
                local titleColor = COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1)
                local countColor = COLORS.TEXT_DIM or imgui.ImVec4(0.78, 0.78, 0.78, 1)
                drawList:AddText(imgui.ImVec2(screenPos.x + 12, screenPos.y + 8), MainUI.colorToU32(titleColor), label)

                local countPosX = screenPos.x + availX - 28
                if imgui.CalcTextSize then
                    local okSize, size = pcall(imgui.CalcTextSize, countText)
                    if okSize and size then
                        countPosX = screenPos.x + availX - (tonumber(size.x) or 0) - 12
                    end
                end
                drawList:AddText(imgui.ImVec2(countPosX, screenPos.y + 8), MainUI.colorToU32(countColor), countText)
            else
                if imgui.Selectable(string.format("%s %s (%d)##KillListDateFallback_%d",
                    expanded and "[-]" or "[+]",
                    tostring(dateLabel or "Unknown date"),
                    tonumber(entryCount) or 0,
                    tonumber(index) or 0), false) then
                    clicked = true
                end
            end

            return clicked
        end

        local function renderEntryRow(dateIndex, entryIndex, entry, entryScale)
            local availX = math.max(160, tonumber(imgui.GetContentRegionAvail().x) or 160)
            local rowHeight = math.max(22, math.floor(24 * (tonumber(entryScale) or 1.0)))
            local rowPos = imgui.GetCursorScreenPos()
            local key = string.format("##KillListEntryRow_%d_%d", tonumber(dateIndex) or 0, tonumber(entryIndex) or 0)
            imgui.InvisibleButton(key, imgui.ImVec2(availX, rowHeight))

            local drawList = imgui.GetWindowDrawList and imgui.GetWindowDrawList() or nil
            local label = UtilityManager.toUtf8(entry.display or "")
            if #label > 110 then
                label = label:sub(1, 107) .. "..."
            end

            if drawList and MainUI and type(MainUI.colorToU32) == "function" then
                local minPos = imgui.ImVec2(rowPos.x, rowPos.y)
                local maxPos = imgui.ImVec2(rowPos.x + availX, rowPos.y + rowHeight)
                local fill = imgui.ImVec4(0.11, 0.04, 0.05, 0.82)
                local border = imgui.ImVec4(0.46, 0.09, 0.13, 0.82)
                local textColor = COLORS.TEXT_DIM or imgui.ImVec4(0.82, 0.82, 0.82, 1.0)
                drawList:AddRectFilled(minPos, maxPos, MainUI.colorToU32(fill), 9)
                drawList:AddRect(minPos, maxPos, MainUI.colorToU32(border), 9, 0, 1.0)
                drawList:AddText(imgui.ImVec2(rowPos.x + 10, rowPos.y + 5), MainUI.colorToU32(textColor), label)
            else
                imgui.TextUnformatted(label)
            end
        end

        -- animation fix: keep daily logs inline so expanded entries push the remaining dates down instead of opening inside a framed block.
        local delta = MainUI and type(MainUI.getAnimationDelta) == "function" and MainUI.getAnimationDelta() or (1 / 60)
        local listHeight = 220 * (tonumber(scale) or 1.0)
        local childFlags = 0
        if imgui.WindowFlags.NoBackground then
            childFlags = childFlags + imgui.WindowFlags.NoBackground
        end

        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.07, 0.02, 0.03, 0.74))
        imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0.42, 0.07, 0.11, 0.95))
        local childStyleVarsPushed = 0
        if imgui.PushStyleVar and imgui.StyleVar and imgui.StyleVar.ChildRounding then
            imgui.PushStyleVar(imgui.StyleVar.ChildRounding, 12)
            childStyleVarsPushed = 1
        end
        imgui.BeginChild("##KillListLogsByDate", imgui.ImVec2(0, listHeight), true, childFlags)
        local sourceBuckets = buckets or {}
        if not buckets then
            for _, dateLabel in ipairs(KillListManager.orderedDates) do
                sourceBuckets[#sourceBuckets + 1] = {
                    date = dateLabel,
                    entries = KillListManager.grouped[dateLabel] or {}
                }
            end
        end
        for index, bucketInfo in ipairs(sourceBuckets) do
            local dateLabel = bucketInfo.date
            local entries = bucketInfo.entries or {}
            local expanded = isDateExpanded(dateLabel)
            if renderDateHeader(dateLabel, #entries, expanded, index, scale) then
                KillListManager.expandedDates[tostring(dateLabel)] = not expanded or nil
                expanded = isDateExpanded(dateLabel)
            end

            local progress = syncDateAnim(dateLabel, delta)
            if progress > 0.001 and #entries > 0 then
                local lineHeight = math.max(18, math.floor(18 * (tonumber(scale) or 1.0)))
                local paddingY = math.max(8, math.floor(8 * (tonumber(scale) or 1.0)))
                local maxExpandedHeight = math.max(96, math.floor(220 * (tonumber(scale) or 1.0)))
                local targetHeight = math.min(maxExpandedHeight, (#entries * lineHeight) + (paddingY * 2))
                local visibleHeight = math.max(2, math.floor(targetHeight * progress))
                local innerFlags = 0
                if imgui.WindowFlags.NoBackground then
                    innerFlags = innerFlags + imgui.WindowFlags.NoBackground
                end

                imgui.BeginChild("##KillListDateBody" .. tostring(index), imgui.ImVec2(0, visibleHeight), false, innerFlags)
                imgui.Dummy(imgui.ImVec2(0, paddingY * progress))
                imgui.Indent(10)
                for entryIndex, entry in ipairs(entries) do
                    renderEntryRow(index, entryIndex, entry, scale)
                    if visibleHeight >= targetHeight or entry ~= entries[#entries] then
                        imgui.Spacing()
                    end
                end
                imgui.Unindent(10)
                imgui.EndChild()
            end

            imgui.Dummy(imgui.ImVec2(0, math.max(4, math.floor(6 * (tonumber(scale) or 1.0)))))
        end
        imgui.EndChild()
        if childStyleVarsPushed > 0 and imgui.PopStyleVar then
            imgui.PopStyleVar(childStyleVarsPushed)
        end
        imgui.PopStyleColor(2)
    end

    if embedded then
        renderBody()
        return
    end

    if imgui.CollapsingHeader("Kill List") then
        renderBody()
    end
end

function KillListManager.initialize()
    local hadSavedData = KillListManager.load()
    if not hadSavedData then
        KillListManager.save()
    end
    if LogManager and LogManager.system then
        LogManager.system("Kill List initialized")
    end
end

end

