local function applyWorldByteRpc(rpcId, value)
    -- safety fix: Grand Mobile climate overrides should gracefully degrade on builds without RakNet helpers.
    local numericRpc = tonumber(rpcId)
    local numericValue = tonumber(value)
    if not numericRpc or not numericValue then
        return false
    end
    if type(raknetNewBitStream) ~= "function" or
       type(raknetBitStreamWriteInt8) ~= "function" or
       type(raknetEmulRpcReceiveBitStream) ~= "function" or
       type(raknetDeleteBitStream) ~= "function" then
        return false
    end

    local ok = pcall(function()
        local bs = raknetNewBitStream()
        raknetBitStreamWriteInt8(bs, numericValue)
        raknetEmulRpcReceiveBitStream(numericRpc, bs)
        raknetDeleteBitStream(bs)
    end)
    return ok
end

function ServerManager.updateClimateLocks()
    local savedTimeEnabled = SettingsManager and SettingsManager.get and SettingsManager.get("worldTimeEnabled") == true
    local savedWeatherEnabled = SettingsManager and SettingsManager.get and SettingsManager.get("worldWeatherEnabled") == true

    if savedTimeEnabled then
        ServerManager.setServerTime(SettingsManager.get("worldTimeValue"), true)
    end
    if savedWeatherEnabled then
        ServerManager.setWeather(SettingsManager.get("worldWeatherValue"), true)
    end
end

function ServerManager.setServerTime(hour, lockedApply)
    lockedApply = lockedApply == true
    local numericHour = math.floor(tonumber(hour) or tonumber(ServerManager.serverTime) or 12)
    numericHour = UtilityManager.clamp(numericHour, 0, 23)
    ServerManager.serverTime = numericHour

    local applied = false
    if applyWorldByteRpc(94, numericHour) then
        applied = true
    end
    if not applied and type(setWorldTime) == "function" then
        local ok = pcall(setWorldTime, numericHour, true)
        applied = ok or applied
    end
    if not applied and type(setTimeOfDay) == "function" then
        local ok = pcall(setTimeOfDay, numericHour, 0)
        applied = ok or applied
    end

    if SettingsManager and SettingsManager.set then
        SettingsManager.set("worldTimeValue", numericHour)
    end
    if not lockedApply then
        LogManager.admin(string.format("Server time set to %02d:00", numericHour))
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[GMEA] Vaqt o'zgartirildi: %02d:00", numericHour), applied and 0x33FF66 or 0xFF9933)
        end
    end
    return applied
end

function ServerManager.setWeather(weatherId, lockedApply)
    lockedApply = lockedApply == true
    local numericWeather = math.floor(tonumber(weatherId) or tonumber(ServerManager.weather) or 0)
    numericWeather = UtilityManager.clamp(numericWeather, 0, 45)
    ServerManager.weather = numericWeather

    local applied = false
    if applyWorldByteRpc(152, numericWeather) then
        applied = true
    end
    if not applied and type(setWorldWeather) == "function" then
        local ok = pcall(setWorldWeather, numericWeather, true)
        applied = ok or applied
    end
    if not applied and type(forceWeatherNow) == "function" then
        local ok = pcall(forceWeatherNow, numericWeather)
        applied = ok or applied
    end

    if SettingsManager and SettingsManager.set then
        SettingsManager.set("worldWeatherValue", numericWeather)
    end
    if not lockedApply then
        LogManager.admin(string.format("Weather changed to %d", numericWeather))
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[GMEA] Pogoda o'zgartirildi: %d", numericWeather), applied and 0x33FF66 or 0xFF9933)
        end
    end
    return applied
end

function ServerManager.scheduleRestart(minutes)
    ServerManager.restartScheduled = true
    ServerManager.restartTime = os.time() + (minutes * 60)
    LogManager.admin(string.format("Server restart scheduled in %d minutes", minutes))
end

function ServerManager.globalAnnouncement(message)
    sendChat(string.format("/announce %s", message))
    LogManager.admin(string.format("Global announcement: %s", message))
end

function ServerManager.privateAnnouncement(playerId, message)
    sendChat(string.format("/pm %d [ADMIN] %s", playerId, message))
end

function ServerManager.clearChat()
    for i = 1, 20 do
        print(" ")
    end
    LogManager.admin("Chat cleared")
end

function ServerManager.getServerFPS()
    return 60
end

function ServerManager.getPlayerPingList()
    local list = {}
    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        return list
    end
    local okMax, maxPlayerId = pcall(sampGetMaxPlayerId, false)
    maxPlayerId = okMax and tonumber(maxPlayerId) or -1
    if maxPlayerId < 0 then
        return list
    end
    for i = 0, maxPlayerId do
        local okConnected, connected = pcall(sampIsPlayerConnected, i)
        if okConnected and connected then
            local ping = 0
            if type(sampGetPlayerPing) == "function" then
                local okPing, valuePing = pcall(sampGetPlayerPing, i)
                if okPing then
                    ping = tonumber(valuePing) or 0
                end
            end
            table.insert(list, {
                id = i,
                name = UtilityManager.getPlayerNicknameSafe(i, ""),
                ping = ping
            })
        end
    end
    return list
end

function ServerManager.getMemoryUsage()
    return collectgarbage("count")
end

