do
-- ============================================
-- TEKSHIRUV MANAGER
-- ============================================
TekshiruvManager = {
    settings = {
        enabled = true,
        speedEnabled = true,
        wordEnabled = true,
        onFootLimitKmh = 95,
        vehicleLimitKmh = 260,
        wordsRaw = ""
    },
    keywordList = {},
    incidents = {},
    maxIncidents = 220,
    playerStates = {},
    lastScanAtMs = 0,
    scanIntervalMs = 500,
    speedAlertCooldownMs = 2500,
    wordAlertCooldownMs = 1500,
    wordAlertLastByKey = {}
}

function TekshiruvManager.getNowMs()
    return UtilityManager.getNowMs()
end

function TekshiruvManager.foldText(text)
    local value = tostring(text or "")
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value
end

function TekshiruvManager.normalizeLine(text)
    local clean = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
    clean = clean:gsub("[\r\n]+", " "):gsub("%s%s+", " ")
    return UtilityManager.trim(clean)
end

function TekshiruvManager.stripTimestampPrefix(text)
    local value = tostring(text or "")
    value = value:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
    return UtilityManager.trim(value)
end

function TekshiruvManager.reloadKeywordList()
    TekshiruvManager.keywordList = {}
    local seen = {}
    local source = tostring(TekshiruvManager.settings.wordsRaw or "")
    source = source:gsub("[\r\n;|]+", ",")

    for token in source:gmatch("([^,]+)") do
        local raw = UtilityManager.trim(token)
        if raw ~= "" then
            local folded = TekshiruvManager.foldText(raw)
            if folded ~= "" and not seen[folded] then
                seen[folded] = true
                table.insert(TekshiruvManager.keywordList, {
                    raw = raw,
                    folded = folded
                })
            end
        end
    end
end

function TekshiruvManager.loadSettings()
    TekshiruvManager.settings.enabled = SettingsManager.get("tekshiruvEnabled") ~= false
    TekshiruvManager.settings.speedEnabled = SettingsManager.get("tekshiruvSpeedEnabled") ~= false
    TekshiruvManager.settings.wordEnabled = SettingsManager.get("tekshiruvWordEnabled") ~= false
    TekshiruvManager.settings.onFootLimitKmh = math.max(20, math.min(600,
        math.floor(tonumber(SettingsManager.get("tekshiruvOnFootLimitKmh")) or 95)))
    TekshiruvManager.settings.vehicleLimitKmh = math.max(40, math.min(900,
        math.floor(tonumber(SettingsManager.get("tekshiruvVehicleLimitKmh")) or 260)))
    TekshiruvManager.settings.wordsRaw = tostring(SettingsManager.get("tekshiruvWords") or "")
    TekshiruvManager.reloadKeywordList()
end

function TekshiruvManager.saveSettings()
    SettingsManager.set("tekshiruvEnabled", TekshiruvManager.settings.enabled == true)
    SettingsManager.set("tekshiruvSpeedEnabled", TekshiruvManager.settings.speedEnabled == true)
    SettingsManager.set("tekshiruvWordEnabled", TekshiruvManager.settings.wordEnabled == true)
    SettingsManager.set("tekshiruvOnFootLimitKmh", math.floor(tonumber(TekshiruvManager.settings.onFootLimitKmh) or 95))
    SettingsManager.set("tekshiruvVehicleLimitKmh", math.floor(tonumber(TekshiruvManager.settings.vehicleLimitKmh) or 260))
    SettingsManager.set("tekshiruvWords", tostring(TekshiruvManager.settings.wordsRaw or ""))
    SettingsManager.save()
end

function TekshiruvManager.initialize()
    TekshiruvManager.loadSettings()
    TekshiruvManager.incidents = {}
    TekshiruvManager.playerStates = {}
    TekshiruvManager.wordAlertLastByKey = {}
    TekshiruvManager.lastScanAtMs = 0
    LogManager.system("Tekshiruv manager initialized")
end

function TekshiruvManager.isAccessUnlocked()
    return true
end

function TekshiruvManager.isSpeedMonitoringActive()
    return TekshiruvManager.isAccessUnlocked() and
           TekshiruvManager.settings.enabled == true and
           TekshiruvManager.settings.speedEnabled == true
end

function TekshiruvManager.isWordMonitoringActive()
    return TekshiruvManager.isAccessUnlocked() and
           TekshiruvManager.settings.enabled == true and
           TekshiruvManager.settings.wordEnabled == true and
           #TekshiruvManager.keywordList > 0
end

function TekshiruvManager.addIncident(kind, playerId, nick, detail)
    local entry = {
        timestamp = os.time(),
        time = os.date("%H:%M:%S"),
        kind = tostring(kind or "INFO"),
        id = tonumber(playerId) or -1,
        nick = UtilityManager.trim(tostring(nick or "Unknown")),
        detail = UtilityManager.trim(tostring(detail or ""))
    }
    if entry.nick == "" then
        entry.nick = "Unknown"
    end

    table.insert(TekshiruvManager.incidents, 1, entry)
    if #TekshiruvManager.incidents > TekshiruvManager.maxIncidents then
        table.remove(TekshiruvManager.incidents)
    end

    LogManager.security(string.format("Tekshiruv [%s] #%d %s: %s",
        entry.kind, entry.id, entry.nick, entry.detail))
end

function TekshiruvManager.resolveNickById(playerId, fallback)
    local nick = UtilityManager.trim(tostring(fallback or ""))
    if type(sampIsPlayerConnected) == "function" and type(sampGetPlayerNickname) == "function" then
        local okConnected, connected = pcall(sampIsPlayerConnected, playerId)
        if okConnected and connected then
            local okNick, onlineNick = pcall(sampGetPlayerNickname, playerId)
            if okNick and onlineNick and tostring(onlineNick) ~= "" then
                nick = tostring(onlineNick)
            end
        end
    end
    if nick == "" then
        nick = string.format("ID_%d", tonumber(playerId) or -1)
    end
    return nick
end

function TekshiruvManager.getLocalPlayerId()
    if not PLAYER_PED or type(sampGetPlayerIdByCharHandle) ~= "function" then
        return nil
    end
    local ok, a, b = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not ok then
        return nil
    end
    if type(a) == "boolean" then
        if a then
            return tonumber(b)
        end
        return nil
    end
    return tonumber(a)
end

function TekshiruvManager.getPlayerCoords(playerId)
    local ped = nil
    if MainUI and type(MainUI.getPlayerPedHandleById) == "function" then
        ped = MainUI.getPlayerPedHandleById(playerId)
    elseif ReportCatchManager and type(ReportCatchManager.getPlayerPedHandle) == "function" then
        ped = ReportCatchManager.getPlayerPedHandle(playerId)
    end

    ped = tonumber(ped)
    if not ped then
        return nil
    end

    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, ped)
        if okExists and not exists then
            return nil
        end
    end

    if type(getCharCoordinates) ~= "function" then
        return nil
    end

    local okCoords, x, y, z = pcall(getCharCoordinates, ped)
    if not okCoords then
        return nil
    end

    x = tonumber(x)
    y = tonumber(y)
    z = tonumber(z)
    if not x or not y or not z then
        return nil
    end

    local inVehicle = false
    if type(isCharInAnyCar) == "function" then
        local okVehicle, value = pcall(isCharInAnyCar, ped)
        if okVehicle and value then
            inVehicle = true
        end
    end

    return x, y, z, inVehicle
end

function TekshiruvManager.resetRuntimeForDisabled()
    TekshiruvManager.playerStates = {}
end

function TekshiruvManager.update()
    if not TekshiruvManager.isSpeedMonitoringActive() then
        TekshiruvManager.resetRuntimeForDisabled()
        return
    end

    local nowMs = TekshiruvManager.getNowMs()
    if (nowMs - TekshiruvManager.lastScanAtMs) < TekshiruvManager.scanIntervalMs then
        return
    end
    TekshiruvManager.lastScanAtMs = nowMs

    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        return
    end

    local localId = TekshiruvManager.getLocalPlayerId()
    local okMax, maxId = pcall(sampGetMaxPlayerId, false)
    maxId = okMax and tonumber(maxId) or -1
    if maxId < 0 then
        return
    end

    local nowSec = nowMs / 1000.0

    for playerId = 0, maxId do
        local okConnected, connected = pcall(sampIsPlayerConnected, playerId)
        if not okConnected or not connected or (localId and playerId == localId) then
            TekshiruvManager.playerStates[playerId] = nil
        else
            local x, y, z, inVehicle = TekshiruvManager.getPlayerCoords(playerId)
            if not x then
                TekshiruvManager.playerStates[playerId] = nil
            else
                local state = TekshiruvManager.playerStates[playerId] or {}
                local prevX, prevY, prevZ = tonumber(state.x), tonumber(state.y), tonumber(state.z)
                local prevT = tonumber(state.t)
                local lastIncidentAt = tonumber(state.lastIncidentAt) or 0

                if prevX and prevY and prevZ and prevT then
                    local dt = nowSec - prevT
                    if dt >= 0.20 and dt <= 3.0 then
                        local dx = x - prevX
                        local dy = y - prevY
                        local dz = z - prevZ
                        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
                        local speedKmh = (dist / dt) * 3.6
                        local limit = inVehicle and TekshiruvManager.settings.vehicleLimitKmh or
                                     TekshiruvManager.settings.onFootLimitKmh
                        local minDist = inVehicle and 9.0 or 3.0

                        if speedKmh >= limit and dist >= minDist and (nowMs - lastIncidentAt) >= TekshiruvManager.speedAlertCooldownMs then
                            local nick = TekshiruvManager.resolveNickById(playerId, "")
                            local violation = inVehicle and "juda tez harakat (mashina)" or "juda tez harakat (piyoda)"
                            TekshiruvManager.addIncident(
                                "SPEED",
                                playerId,
                                nick,
                                string.format("%s: %.1f km/h (limit %d)", violation, speedKmh, limit)
                            )
                            lastIncidentAt = nowMs
                        end
                    end
                end

                state.x = x
                state.y = y
                state.z = z
                state.t = nowSec
                state.lastIncidentAt = lastIncidentAt
                TekshiruvManager.playerStates[playerId] = state
            end
        end
    end
end

function TekshiruvManager.isNoiseServerLine(line)
    local folded = TekshiruvManager.foldText(line)
    if folded == "" then
        return true
    end
    if folded:find("<adm>", 1, true) or folded:find("[a]", 1, true) then
        return true
    end
    if folded:find("ga javob berdi", 1, true) or folded:find("???????", 1, true) then
        return true
    end
    if folded:find("uchun administrator", 1, true) then
        return true
    end
    if folded:find("report #", 1, true) or folded:find("new report", 1, true) then
        return true
    end
    return false
end

function TekshiruvManager.extractPlayerMessage(text)
    local clean = TekshiruvManager.stripTimestampPrefix(TekshiruvManager.normalizeLine(text))
    if clean == "" or TekshiruvManager.isNoiseServerLine(clean) then
        return nil
    end

    local nick, idText, msg = clean:match("^.-([%w_%.%-]+)%[(%d+)%]%s*:%s*(.+)$")
    if not nick then
        local idText2, nick2, msg2 = clean:match("^.-%[(%d+)%]%s*([%w_%.%-]+)%s*:%s*(.+)$")
        if idText2 and nick2 and msg2 then
            nick, idText, msg = nick2, idText2, msg2
        end
    end

    local playerId = tonumber(idText)
    msg = UtilityManager.trim(tostring(msg or ""))
    if not playerId or msg == "" then
        return nil
    end

    return playerId, tostring(nick or ""), msg
end

function TekshiruvManager.processServerMessage(text)
    if not TekshiruvManager.isWordMonitoringActive() then
        return
    end

    local playerId, nick, msg = TekshiruvManager.extractPlayerMessage(text)
    if not playerId then
        return
    end

    if type(sampIsPlayerConnected) == "function" then
        local okConnected, connected = pcall(sampIsPlayerConnected, playerId)
        if okConnected and not connected then
            return
        end
    end

    local foldedMsg = TekshiruvManager.foldText(msg)
    if foldedMsg == "" then
        return
    end

    local nowMs = TekshiruvManager.getNowMs()

    for _, entry in ipairs(TekshiruvManager.keywordList) do
        local token = tostring(entry.folded or "")
        if token ~= "" and foldedMsg:find(token, 1, true) then
            local cooldownKey = string.format("%d|%s", playerId, token)
            local lastAt = tonumber(TekshiruvManager.wordAlertLastByKey[cooldownKey]) or 0
            if (nowMs - lastAt) >= TekshiruvManager.wordAlertCooldownMs then
                TekshiruvManager.wordAlertLastByKey[cooldownKey] = nowMs
                local resolvedNick = TekshiruvManager.resolveNickById(playerId, nick)
                TekshiruvManager.addIncident(
                    "WORD",
                    playerId,
                    resolvedNick,
                    string.format("so'z: \"%s\" | xabar: %s", tostring(entry.raw or ""), msg)
                )
            end
            break
        end
    end
end



end

