local LEGACY_SERVER_TEMPLATE_KEYS = {
    template_warn = true,
    template_not_guilty = true,
    template_guilty = true,
    template_checking = true,
    template_done = true
}

local function cloneReportTemplate(template)
    if type(template) ~= "table" then
        return nil
    end
    return {
        id = tonumber(template.id) or 0,
        key = template.key and tostring(template.key) or nil,
        text = tostring(template.text or ""),
        shortcut = tostring(template.shortcut or ""),
        autoSpReporter = template.autoSpReporter == true
    }
end

local function cloneReportTemplateList(list)
    local out = {}
    for _, template in ipairs(list or {}) do
        local cloned = cloneReportTemplate(template)
        if cloned and cloned.id > 0 and cloned.text ~= "" then
            out[#out + 1] = cloned
        end
    end
    return out
end

local function findDefaultReportTemplate(id, key)
    local wantedId = tonumber(id) or 0
    local wantedKey = key and tostring(key) or nil
    for _, template in ipairs(DEFAULT_REPORT_CATCH_TEMPLATES) do
        if wantedId > 0 and tonumber(template.id) == wantedId then
            return template
        end
        if wantedKey and template.key == wantedKey then
            return template
        end
    end
    return nil
end

local function normalizeIncomingReportTemplate(template, fallbackIndex)
    if type(template) ~= "table" then
        return nil
    end

    local templateId = tonumber(template.id) or tonumber(template.template_id) or tonumber(fallbackIndex) or 0
    local templateKey = template.key and tostring(template.key) or nil
    local fallback = findDefaultReportTemplate(templateId, templateKey)
    local text = tostring(template.text or template.message or template.reply or (fallback and fallback.text) or "")
    if text == "" then
        return nil
    end

    local shortcut = tostring(template.shortcut or template.name or (fallback and fallback.shortcut) or ("T" .. tostring(templateId > 0 and templateId or fallbackIndex or 1)))
    local autoSpReporter = template.autoSpReporter
    if autoSpReporter == nil then
        autoSpReporter = template.auto_sp_reporter
    end
    if autoSpReporter == nil then
        autoSpReporter = template.auto_sp
    end
    if autoSpReporter == nil and fallback then
        autoSpReporter = fallback.autoSpReporter
    end

    return {
        id = templateId > 0 and templateId or tonumber(fallbackIndex) or 1,
        key = templateKey or (fallback and fallback.key) or nil,
        text = text,
        shortcut = shortcut,
        autoSpReporter = autoSpReporter == true or tostring(autoSpReporter or "") == "true"
    }
end

local function isLegacyServerTemplateList(list)
    if type(list) ~= "table" or #list == 0 then
        return false
    end

    local legacyCount = 0
    for _, template in ipairs(list) do
        if type(template) == "table" then
            local templateKey = tostring(template.key or ""):lower()
            local templateName = tostring(template.name or template.shortcut or ""):lower()
            if LEGACY_SERVER_TEMPLATE_KEYS[templateKey] or LEGACY_SERVER_TEMPLATE_KEYS[templateName] then
                legacyCount = legacyCount + 1
            end
        end
    end

    return legacyCount == #list and legacyCount > 0
end

