function ReportCatchManager.applyServerTemplates(list)
    if type(list) ~= "table" then
        ReportCatchManager.templates = {}
        ReportCatchManager.templateSource = "cleared"
        return
    end

    if #list == 0 then
        ReportCatchManager.templates = {}
        ReportCatchManager.templateSource = "cleared"
        return
    end

    if isLegacyServerTemplateList(list) then
        ReportCatchManager.templates = cloneReportTemplateList(
            ReportCatchManager.defaultTemplates or DEFAULT_REPORT_CATCH_TEMPLATES
        )
        ReportCatchManager.templateSource = "legacy-defaults"
        if LogManager and LogManager.system then
            LogManager.system("[REPORT] Legacy backend templates detected; source reply templates restored")
        end
        return
    end

    local normalized = {}
    for index, template in ipairs(list) do
        local nextTemplate = normalizeIncomingReportTemplate(template, index)
        if nextTemplate then
            normalized[#normalized + 1] = nextTemplate
        end
    end
    ReportCatchManager.templates = normalized
    ReportCatchManager.templateSource = "server"
end

function ReportCatchManager.getEffectiveTemplateCatalogForPermissions(list)
    if type(list) == "table" and isLegacyServerTemplateList(list) then
        return cloneReportTemplateList(ReportCatchManager.defaultTemplates or DEFAULT_REPORT_CATCH_TEMPLATES)
    end
    return list
end

