function RepQuickReplyManager.isEnabled()
    return ReportCatchManager and
           ReportCatchManager.settings and
           ReportCatchManager.settings.repQuickAutoEnabled == true
end

function RepQuickReplyManager.isBlockedByTime()
    -- 22:45 dan 23:00 gacha (inclusive) hech qanday auto /ans yuborilmaydi.
    local now = os.date("*t")
    if not now then
        return false
    end
    local hour = tonumber(now.hour) or 0
    local minute = tonumber(now.min) or 0
    local total = hour * 60 + minute
    return total >= (22 * 60 + 45) and total <= (23 * 60 + 0)
end

function RepQuickReplyManager.hasPlusMarker(report)
    local source = tostring((report and report.rawText) or (report and report.text) or "")
    return source:find("+", 1, true) ~= nil
end

function RepQuickReplyManager.containsFuraMarker(report)
    local source = tostring((report and report.rawText) or (report and report.text) or "")
    if source == "" then
        return false
    end

    local normalized = source
    normalized = normalized:gsub("[FfФф]", "f")
    normalized = normalized:gsub("[UuУу]", "u")
    normalized = normalized:gsub("[RrРр]", "r")
    normalized = normalized:gsub("[AaАа]", "a")
    normalized = normalized:lower()

    return normalized:find("fura", 1, true) ~= nil
end

function RepQuickReplyManager.shouldSkip(report)
    if RepQuickReplyManager.hasPlusMarker(report) then
        return true, "plus_marker"
    end
    if RepQuickReplyManager.isBlockedByTime() then
        return true, "blocked_time"
    end
    return false, nil
end

function RepQuickReplyManager.tryAutoAnswer(report)
    if not RepQuickReplyManager.isEnabled() then
        return false
    end
    if type(report) ~= "table" then
        return false
    end

    local reportId = tonumber(report.id)
    if not reportId or reportId <= 0 then
        return false
    end

    local shouldSkip, reason = RepQuickReplyManager.shouldSkip(report)
    if shouldSkip then
        if LogManager and LogManager.report then
            LogManager.report(string.format("REP auto skipped for report #%d (%s)", reportId, tostring(reason or "skip")))
        end
        return false
    end

    local cmd = string.format("/ans %d %s", reportId, RepQuickReplyManager.answerText)
    if sendChat(cmd) == false then
        if LogManager and LogManager.report then
            LogManager.report(string.format("REP auto failed for report #%d", reportId))
        end
        return false
    end

    if ReportCatchManager and ReportCatchManager.markAnswered then
        ReportCatchManager.markAnswered(reportId)
    end
    if ReportCatchManager and ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == reportId and
       ReportCatchManager.closePopup then
        ReportCatchManager.closePopup()
    end

    if LogManager and LogManager.report then
        LogManager.report(string.format("REP auto answered report #%d: %s", reportId, RepQuickReplyManager.answerText))
    end
    return true
end

function RepQuickReplyManager.renderWindow()
    if not RepQuickReplyManager.open then
        return
    end

    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.AlwaysAutoResize
    local open = imgui.ImBool(RepQuickReplyManager.open)

    if imgui.Begin(u8"REP yordamchi##RepQuickReplyManager", open, flags) then
        local enabled = imgui.ImBool(RepQuickReplyManager.isEnabled())
        if imgui.Checkbox(u8"Hamma repga javob##rep_quick_auto", enabled) then
            if ReportCatchManager and ReportCatchManager.settings then
                ReportCatchManager.settings.repQuickAutoEnabled = enabled[0]
            end
            if enabled[0] and SettingsManager and SettingsManager.set then
                SettingsManager.set("kerakliMenuDisabled", true)
            end
            if ReportCatchManager and ReportCatchManager.saveSettings then
                ReportCatchManager.saveSettings()
            end
        end
        imgui.TextDisabled(u8"Har yangi reportga /ans ID Assalom alekum, kuzatyapman yuboradi.")
        imgui.TextDisabled(u8"Report ichida '+' bo'lsa yoki 22:45-23:00 oralig'ida bo'lsa, o'tkazib yuboradi.")
        imgui.Separator()
        imgui.TextDisabled(string.format("Holat: %s", enabled[0] and "yoqilgan" or "o'chirilgan"))
        imgui.TextDisabled(string.format("Matn: %s", RepQuickReplyManager.answerText))
    end

    RepQuickReplyManager.open = open[0]
    imgui.End()
end


