    if ReportCatchManager.settings.afkReportAdminHelpText == "" then
        ReportCatchManager.settings.afkReportAdminHelpText = "help {id}"
    end

    ReportCatchManager.settings.afkReportCooldown =
        math.max(0, math.min(300, tonumber(ReportCatchManager.settings.afkReportCooldown) or 8))
    ReportCatchManager.settings.reportKeywordReplyEnabled =
        ReportCatchManager.settings.reportKeywordReplyEnabled == true
    ReportCatchManager.settings.reportKeywordReplyKeywords =
        UtilityManager.trim(tostring(ReportCatchManager.settings.reportKeywordReplyKeywords or ""))
    if ReportCatchManager.settings.reportKeywordReplyKeywords == "" then
        ReportCatchManager.settings.reportKeywordReplyKeywords = "evakuator, эвакуатор"
    end

    ReportCatchManager.settings.reportKeywordReplyText1 =
        ReportCatchManager.sanitizeChatFriendlyText(ReportCatchManager.settings.reportKeywordReplyText1 or "")
    if ReportCatchManager.settings.reportKeywordReplyText1 == "" then
        ReportCatchManager.settings.reportKeywordReplyText1 =
            ReportCatchManager.sanitizeChatFriendlyText(DEFAULT_EVAKUATOR_REPLY_TEXT)
    end
    ReportCatchManager.settings.reportKeywordReplyText2 = ""
    ReportCatchManager.settings.reportKeywordReplyText3 = ""
    ReportCatchManager.settings.reportKeywordReplyCooldown =
        math.max(0, math.min(300, tonumber(ReportCatchManager.settings.reportKeywordReplyCooldown) or 8))

    ReportCatchManager.settings.aiAutoReportEnabled =
        UtilityManager.parseIniBool(ReportCatchManager.settings.aiAutoReportEnabled, false)
    ReportCatchManager.settings.aiAutoReportSkipPopup =
        UtilityManager.parseIniBool(ReportCatchManager.settings.aiAutoReportSkipPopup, true)
    ReportCatchManager.settings.aiAutoReportCooldownSec =
        math.max(1, math.min(30, tonumber(ReportCatchManager.settings.aiAutoReportCooldownSec) or 3))
    ReportCatchManager.settings.aiAutoReportRequireUnique =
        UtilityManager.parseIniBool(ReportCatchManager.settings.aiAutoReportRequireUnique, true)
    ReportCatchManager.settings.templateRoutingEnabled =
        UtilityManager.parseIniBool(ReportCatchManager.settings.templateRoutingEnabled, true)

    local routeMap = ReportCatchManager.settings.templateRouteMap
    if type(routeMap) ~= "table" then
        routeMap = {}
    end

    local function resolveRouteValue(routeKey, legacyValue, fallback)
        local value = routeMap[routeKey]
        if value == nil then
            value = legacyValue
        end
        if value == nil then
            value = fallback
        end
        return UtilityManager.trim(tostring(value or ""))
    end

    routeMap["1"] = resolveRouteValue("1", ReportCatchManager.settings.templateRouteKeywords1, "dm, db, sk, bug, bag, yordam")
    routeMap["3"] = resolveRouteValue("3", ReportCatchManager.settings.templateRouteKeywords3, "qachon, almashtiring")
    routeMap["8"] = resolveRouteValue("8", ReportCatchManager.settings.templateRouteKeywords8, "oldirdi, o'dirdi, odirdi, haqorat")

    for rawKey, rawValue in pairs(routeMap) do
        local key = tostring(rawKey or "")
        if key ~= "" then
            routeMap[key] = UtilityManager.trim(tostring(rawValue or ""))
        end
    end

    ReportCatchManager.settings.templateRouteMap = routeMap
    -- Keep legacy fields for backwards compatibility with existing config.
    ReportCatchManager.settings.templateRouteKeywords1 = routeMap["1"] or ""
    ReportCatchManager.settings.templateRouteKeywords3 = routeMap["3"] or ""
    ReportCatchManager.settings.templateRouteKeywords8 = routeMap["8"] or ""
end

