function ReportCatchManager.toggle()
    ReportCatchManager.enabled = not ReportCatchManager.enabled
    if ReportCatchManager.enabled then
        local uiOpen = MainUI and MainUI.window and MainUI.window.open or false
        imgui.Process = uiOpen or ReportCatchManager.popupOpen
        imgui.ShowCursor = uiOpen or ReportCatchManager.popupOpen
        ReportCatchManager.tryShowNextQueuedReport()
    else
        -- N OFF bo'lsa, popup/queue to'liq drop qilinadi.
        ReportCatchManager.clearWaitingReport()
        ReportCatchManager.reportQueue = {}
        ReportCatchManager.popupOpen = false
        ReportCatchManager.currentReport = nil
        ReportCatchManager.animationProgress = 0
        local uiOpen = MainUI and MainUI.window and MainUI.window.open or false
        imgui.Process = uiOpen
        imgui.ShowCursor = uiOpen
    end
    LogManager.system(string.format("Report Catch %s", ReportCatchManager.enabled and "enabled" or "disabled"))
    return ReportCatchManager.enabled
end

function ReportCatchManager.isDuplicate(reportId, nick)
    local key = tostring(reportId) .. "_" .. nick
    local now = os.time()

    for k, time in pairs(ReportCatchManager.recentReports) do
        if now - time > ReportCatchManager.settings.dedupeInterval then
            ReportCatchManager.recentReports[k] = nil
        end
    end

    if ReportCatchManager.recentReports[key] then
        return true
    end

    ReportCatchManager.recentReports[key] = now
    return false
end

function ReportCatchManager.setWaitingReport(report)
    ReportCatchManager.waitingForReply = true
    ReportCatchManager.waitingReportId = report and tonumber(report.id) or nil
    ReportCatchManager.waitingReportNick = report and (report.nick or "") or ""
end

function ReportCatchManager.clearWaitingReport()
    ReportCatchManager.waitingForReply = false
    ReportCatchManager.waitingReportId = nil
    ReportCatchManager.waitingReportNick = ""
end

function ReportCatchManager.markAnswered(reportId)
    local answeredId = tonumber(reportId)
    local pending = ReportCatchManager.pendingPunishmentCheck
    if pending and answeredId then
        local pendingReportId = tonumber(pending.reportId)
        local pendingAnswerTarget = tonumber(pending.answerTargetId)
        local pendingPlayerId = tonumber(pending.playerId)
        if answeredId == pendingReportId or answeredId == pendingAnswerTarget or answeredId == pendingPlayerId then
            ReportCatchManager.pendingPunishmentCheck = nil
            LogManager.report(string.format("Punishment check canceled: report answered (%d)", answeredId))
        end
    end

    if not ReportCatchManager.waitingForReply then
        return false
    end

    local expectedId = tonumber(ReportCatchManager.waitingReportId)
    answeredId = tonumber(reportId)

    if expectedId and answeredId and expectedId ~= answeredId then
        return false
    end

    local resolvedId = expectedId or answeredId or 0
    ReportCatchManager.clearWaitingReport()
    LogManager.report(string.format("Report #%d marked as answered", resolvedId))
    return true
end

function ReportCatchManager.shouldIgnoreIncoming(report)
    if not ReportCatchManager.waitingForReply or not ReportCatchManager.popupOpen then
        return false
    end

    -- Popup ochiq paytda kelgan reportlar navbatga qo'yiladi.
    local queueLimit = math.max(1, tonumber(ReportCatchManager.settings.queueLimit) or 20)
    if #ReportCatchManager.reportQueue >= queueLimit then
        table.remove(ReportCatchManager.reportQueue, 1)
    end
    table.insert(ReportCatchManager.reportQueue, report)

    local incomingId = tonumber(report and report.id or 0) or 0
    local incomingNick = (report and report.nick) or "Unknown"
    local waitingId = tonumber(ReportCatchManager.waitingReportId or 0) or 0
    LogManager.report(string.format(
        "Incoming report #%d from %s queued (waiting answer for #%d, queue=%d/%d)",
        incomingId, incomingNick, waitingId, #ReportCatchManager.reportQueue, queueLimit))
    return true
end

function ReportCatchManager.getKeywordTpTrigger()
    local trigger = UtilityManager.trim(tostring(ReportCatchManager.settings.keywordTpText or ""))
    if trigger == "" then
        return ""
    end
    return trigger:lower()
end

function ReportCatchManager.matchesKeywordTpTrigger(reportText)
    local trigger = ReportCatchManager.getKeywordTpTrigger()
    if trigger == "" then
        return false
    end

    local source = tostring(reportText or ""):gsub("{%x%x%x%x%x%x}", "")
    source = UtilityManager.trim(source):lower()
    if source == "" then
        return false
    end

    return source:find(trigger, 1, true) ~= nil
end

function ReportCatchManager.markKeywordTp(playerId)
    local id = tonumber(playerId)
    if not id then
        return
    end
    ReportCatchManager.keywordTpLastByPlayer[id] = os.time()
end

function ReportCatchManager.foldAdminKey(text)
    local value = tostring(text or "")
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value:lower()
end

function ReportCatchManager.markAdminIdentity(playerId, nick)
    local id = tonumber(playerId)
    if id then
        ReportCatchManager.adminCache.byId[id] = true
    end
    local name = UtilityManager.trim(tostring(nick or ""))
    if name ~= "" then
        ReportCatchManager.adminCache.byNick[ReportCatchManager.foldAdminKey(name)] = true
    end
end

function ReportCatchManager.isAdminKnown(playerId, nick)
    local id = tonumber(playerId)
    if id and ReportCatchManager.adminCache.byId[id] then
        return true
    end
    local name = UtilityManager.trim(tostring(nick or ""))
    if name ~= "" then
        if ReportCatchManager.adminCache.byNick[ReportCatchManager.foldAdminKey(name)] then
            return true
        end
    end
    return false
end

function ReportCatchManager.captureAdminFromServerMessage(text)
    local clean = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
    if clean == "" then
        return
    end
    local folded = ReportCatchManager.foldAdminKey(clean)
    local hasAdminPrefix = clean:find("<ADM>", 1, true) or
        clean:find("<adm>", 1, true) or
        clean:find("%[A%]")

    -- Admin reply lines like:
    -- <ADM> Admin_Nick[12] Player_Nick[44] ga javob berdi: ...
    -- must only mark the admin sender, never the replied player.
    if hasAdminPrefix then
        local senderNick, senderId =
            clean:match("^%s*<[^>]+>%s*([%w_%.%-]+)%[(%d+)%]") or
            clean:match("^%s*%[A%]%s*([%w_%.%-]+)%[(%d+)%]")
        if senderNick and senderId then
            ReportCatchManager.markAdminIdentity(senderId, senderNick)
        end
    end

    local isAdminsListMessage =
        folded:find("tarmoqdagi adminlar", 1, true) or
        folded:find("tarmoqdagi administratorlar", 1, true) or
        folded:find("administratorlar:", 1, true) or
        folded:find("adminlar:", 1, true)

    if not isAdminsListMessage then
        return
    end

    for nick, id in clean:gmatch("([%w_%.%-]+)%s*[%(%[]%s*(%d+)%s*[%]%)]") do
        ReportCatchManager.markAdminIdentity(id, nick)
    end

    local tail = clean:match("[:%-]%s*(.+)$")
    if not tail then
        return
    end

    for token in tail:gmatch("[^,;]+") do
        local name = UtilityManager.trim(token)
        name = name:gsub("%s*%(%d+%)%s*$", "")
        name = name:gsub("%s*%[%d+%]%s*$", "")
        name = name:match("^([%w_%.%-]+)") or ""
        if name ~= "" then
            ReportCatchManager.markAdminIdentity(nil, name)
        end
    end
end

function ReportCatchManager.requestAdminsListOnce()
    -- safety fix: admin-block for MP is fully disabled, so /admins probing is no longer needed here.
    return
end

function ReportCatchManager.normalizeMpNick(playerId, nick)
    local name = UtilityManager.trim(tostring(nick or ""))
    if name ~= "" then
        return name
    end
    if type(sampGetPlayerNickname) == "function" and playerId then
        local okNick, liveNick = pcall(sampGetPlayerNickname, tonumber(playerId))
        if okNick and liveNick and liveNick ~= "" then
            return tostring(liveNick)
        end
    end
    return "Unknown"
end

function ReportCatchManager.addMpPlayer(playerId, nick, reportId)
    local id = tonumber(playerId)
    if not id then
        return
    end
    local name = ReportCatchManager.normalizeMpNick(id, nick)
    local entry = ReportCatchManager.mpPlayers[id]
    if not entry then
        entry = {
            id = id,
            nick = name,
            reportId = tonumber(reportId) or 0,
            addedAt = os.time(),
            addedTime = os.date("%H:%M:%S")
        }
        ReportCatchManager.mpPlayers[id] = entry
        table.insert(ReportCatchManager.mpPlayerOrder, id)
    else
        entry.nick = name
        if tonumber(reportId) then
            entry.reportId = tonumber(reportId) or entry.reportId
        end
    end
end

function ReportCatchManager.removeMpPlayer(playerId, reason)
    local id = tonumber(playerId)
    if not id or not ReportCatchManager.mpPlayers[id] then
        return false
    end
    local entry = ReportCatchManager.mpPlayers[id]
    ReportCatchManager.mpPlayers[id] = nil
    for i = #ReportCatchManager.mpPlayerOrder, 1, -1 do
        if ReportCatchManager.mpPlayerOrder[i] == id then
            table.remove(ReportCatchManager.mpPlayerOrder, i)
            break
        end
    end
    if reason == "death" then
        ReportCatchManager.mpLastDead = {
            id = id,
            nick = entry.nick,
            time = os.time()
        }
        -- O'lgan o'yinchini keyingi MP ochilguncha bloklash
        ReportCatchManager.mpDeathBlocked[id] = {
            nick = entry.nick,
            time = os.time()
        }
    end
    if #ReportCatchManager.mpPlayerOrder == 0 and ReportCatchManager.mpLastDead then
        local last = ReportCatchManager.mpLastDead
        local elapsed = os.time() - (tonumber(last.time) or 0)
        if elapsed <= 120 then
            if (not sampIsPlayerConnected) or sampIsPlayerConnected(last.id) then
                PlayerManager.bring(last.id)
            end
        end
    end
    return true
end

function ReportCatchManager.getMpPlayerEntries(searchText)
    local query = UtilityManager.trim(tostring(searchText or ""))
    local foldedQuery = ReportCatchManager.foldAdminKey(query)
    local result = {}
    for _, id in ipairs(ReportCatchManager.mpPlayerOrder) do
        local entry = ReportCatchManager.mpPlayers[id]
        if entry then
            local match = true
            if query ~= "" then
                local idText = tostring(entry.id)
                local nickFolded = ReportCatchManager.foldAdminKey(entry.nick or "")
                match = idText:find(query, 1, true) ~= nil or
                        nickFolded:find(foldedQuery, 1, true) ~= nil
            end
            if match then
                table.insert(result, entry)
            end
        end
    end
    return result
end

function ReportCatchManager.onMpPlayerDeath(killedId)
    local id = tonumber(killedId)
    if not id then
        return
    end
    if ReportCatchManager.mpPlayers[id] then
        ReportCatchManager.removeMpPlayer(id, "death")
    end
end

function ReportCatchManager.sendMpCommand(commandText)
    local cmd = UtilityManager.trim(tostring(commandText or ""))
    if cmd == "" then
        return false
    end
    if type(sampSendChat) ~= "function" then
        return false
    end
    return sendChat(cmd) ~= false
end

function ReportCatchManager.sendKeywordTpCommand(commandText)
    local cmd = UtilityManager.trim(tostring(commandText or ""))
    if cmd == "" then
        return false
    end
    -- safety fix: use the regular safe chat wrapper first, then fall back to raw sampSendChat.
    if type(sendChat) == "function" then
        local okWrapped, wrappedResult = pcall(sendChat, cmd)
        if okWrapped and wrappedResult ~= false then
            return true
        end
    end
    if type(sampSendChat) ~= "function" then
        return false
    end

    local ok, err = pcall(sampSendChat, cmd)
    if not ok then
        RuntimeGuard.report("ReportCatchManager.sendKeywordTpCommand", err)
    end
    return ok
end

function ReportCatchManager.dispatchKeywordTpBring(playerId)
    local id = tonumber(playerId)
    if not id or id <= 0 then
        return false
    end
    -- safety fix: MP keyword TP should bypass generic player-target validation if the local player cache is stale.
    if ReportCatchManager.sendKeywordTpCommand(string.format("/gethere %d", id)) then
        return true
    end
    if PlayerManager and type(PlayerManager.bring) == "function" then
        return PlayerManager.bring(id) ~= false
    end
    return false
end

function ReportCatchManager.resolveMpWinnerNick(playerId)
    local id = tonumber(playerId)
    if not id or id <= 0 then
        return nil
    end

    local entry = ReportCatchManager.mpPlayers[id]
    if entry then
        local savedNick = UtilityManager.trim(tostring(entry.nick or ""))
        if savedNick ~= "" and savedNick ~= "Unknown" then
            return savedNick
        end
    end

    if type(sampIsPlayerConnected) == "function" and type(sampGetPlayerNickname) == "function" then
        local okConnected, isConnected = pcall(sampIsPlayerConnected, id)
        if okConnected and isConnected then
            local okNick, liveNick = pcall(sampGetPlayerNickname, id)
            local nick = okNick and UtilityManager.trim(tostring(liveNick or "")) or ""
            if nick ~= "" and nick ~= "Unknown" then
                return nick
            end
        end
    end

    return nil
end

function ReportCatchManager.announceMpWinnerById(playerId)
    local id = tonumber(playerId)
    if not id or id <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] G'olib ID sini to'g'ri kiriting.", 0xFF9933)
        end
        return false
    end

    local winnerName = ReportCatchManager.resolveMpWinnerNick(id)
    if not winnerName then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] Bu ID bo'yicha o'yinchi topilmadi.", 0xFF9933)
        end
        return false
    end

    local command = string.format("/msg Tadbirda %s g'olib boldi. Tabriklaymiz", winnerName)

    local dispatch = function()
        local ok = sendChat(command) ~= false
        if ok then
            if LogManager and LogManager.admin then
                LogManager.admin(string.format("MP winner announced manually: %s (%d)", winnerName, id))
            end
            if type(sampAddChatMessage) == "function" then
                sampAddChatMessage(string.format("[GMEA] /msg yuborildi: %s (%d)", winnerName, id), 0x33FF66)
            end
        elseif type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] /msg yuborib bo'lmadi.", 0xFF6666)
        end
    end

    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(function()
            if type(wait) == "function" then
                wait(0)
            end
            dispatch()
        end)
        return true
    end

    dispatch()
    return true
end

