function ReportCatchManager.applyKeywordTpPostActions(playerId)
    local id = tonumber(playerId)
    if not id or id <= 0 then
        return
    end
    if type(sampSendChat) ~= "function" then
        return
    end

    local actions = {}

    if ReportCatchManager.settings.keywordTpAutoHpEnabled ~= false then
        ReportCatchManager.sendKeywordTpCommand(string.format("/hp %d 100", id))
        table.insert(actions, "/hp 100")
    end

    if ReportCatchManager.settings.keywordTpAutoRgunEnabled == true then
        ReportCatchManager.sendKeywordTpCommand(string.format("/rgun %d", id))
        table.insert(actions, "/rgun")
    end

    if ReportCatchManager.settings.keywordTpAutoSetSkinEnabled == true then
        local skinId = math.max(0, math.min(311, tonumber(ReportCatchManager.settings.keywordTpAutoSetSkinId) or 1))
        ReportCatchManager.sendKeywordTpCommand(string.format("/setskin %d %d", id, skinId))
        table.insert(actions, string.format("/setskin %d", skinId))
    end

    if ReportCatchManager.settings.keywordTpAutoGunEnabled == true then
        local gunId   = math.max(0, math.min(46, tonumber(ReportCatchManager.settings.keywordTpAutoGunId) or 24))
        local gunAmmo = math.max(0, math.min(9999, tonumber(ReportCatchManager.settings.keywordTpAutoGunAmmo) or 150))
        ReportCatchManager.sendKeywordTpCommand(string.format("/gun %d %d %d", id, gunId, gunAmmo))
        table.insert(actions, string.format("/gun %d %d", gunId, gunAmmo))
    end

    if #actions > 0 then
        LogManager.report(string.format(
            "Keyword TP post-actions: player #%d -> %s",
            id,
            table.concat(actions, ", ")))
    end
end

function ReportCatchManager.resolveAutoActionPlayerId(report)
    if not report then
        return nil
    end

    -- safety fix: use the more tolerant reporter resolver so keyword TP survives stale playerId cache.
    return ReportCatchManager.resolveReporterPlayerId(report)
end

function ReportCatchManager.isKerakliUnlocked()
    return ReportCatchManager.kerakliUnlocked == true and
           MainUI and MainUI.kerakliAccess and MainUI.kerakliAccess.unlocked == true and
           (not MainUI.isKerakliMenuDisabled or MainUI.isKerakliMenuDisabled() ~= true)
end

function ReportCatchManager.isMpUnlocked()
    return true
end

function ReportCatchManager.shouldRunAutoActions()
    local kerakliUnlocked = ReportCatchManager.isKerakliUnlocked()
    local afkReportActive = (ReportCatchManager.settings.afkReportEnabled or false) and kerakliUnlocked
    local keywordReplyActive = (ReportCatchManager.settings.reportKeywordReplyEnabled or false) and kerakliUnlocked
    local aiAutoActive = (ReportCatchManager.settings.aiAutoReportEnabled or false) and kerakliUnlocked
    local keywordTpActive = (ReportCatchManager.settings.keywordTpEnabled or false) and ReportCatchManager.isMpUnlocked()
    local repQuickActive = ReportCatchManager.settings.repQuickAutoEnabled == true
    return afkReportActive or
           keywordReplyActive or
           aiAutoActive or
           keywordTpActive or
           repQuickActive or
           (ReportCatchManager.settings.autoTP or false) or
           (ReportCatchManager.settings.autoSP or false)
end

function SpectateQuickPanel.resolveTemplateTargetId()
    local targetId = tonumber(SpectateQuickPanel.targetId)
    if targetId and targetId > 0 then
        return targetId
    end
    return nil
end

function ReportCatchManager.getTemplateById(templateId)
    local wantedId = tonumber(templateId)
    if not wantedId then
        return nil
    end
    if PermissionGuard and PermissionGuard.canUseTemplate and
       not PermissionGuard.canUseTemplate(wantedId) then
        return nil
    end
    for _, template in ipairs(ReportCatchManager.templates or {}) do
        if tonumber(template.id) == wantedId then
            return template
        end
    end
    return nil
end

function ReportCatchManager.normalizeRoutingText(text)
    local value = tostring(text or "")
    value = value:gsub("[`?????]", "'")
    value = value:gsub("[\r\n]+", " ")
    return UtilityManager.trim(value)
end

function ReportCatchManager.sanitizeChatFriendlyText(text)
    local value = tostring(text or "")
    value = value:gsub("[\r\n]+", " ")
    value = value:gsub("\226\128\148", ", ")
    value = value:gsub("\226\128\147", "-")
    value = value:gsub("\226\128\152", "'")
    value = value:gsub("\226\128\153", "'")
    value = value:gsub("\202\187", "'")
    value = value:gsub("\202\188", "'")
    value = value:gsub("%s%s+", " ")
    return UtilityManager.trim(value)
end

function ReportCatchManager.getKeywordListFromRaw(raw)
    local source = tostring(raw or "")
    local keywords = {}
    local seen = {}

    for token in source:gmatch("[^,;\r\n]+") do
        local trimmed = UtilityManager.trim(token or "")
        if trimmed ~= "" then
            trimmed = ReportCatchManager.normalizeRoutingText(trimmed)
            local key = UtilityManager.casefoldUtf8Cyrillic(trimmed)
            if key ~= "" and not seen[key] then
                table.insert(keywords, trimmed)
                seen[key] = true
            end
        end
    end
    return keywords
end

function ReportCatchManager.getAfkReportKeywordList()
    local raw = tostring(ReportCatchManager.settings.afkReportKeywords or "")
    local keywords = ReportCatchManager.getKeywordListFromRaw(raw)
    return keywords
end

function ReportCatchManager.getReportKeywordReplyList()
    local raw = tostring(ReportCatchManager.settings.reportKeywordReplyKeywords or "")
    return ReportCatchManager.getKeywordListFromRaw(raw)
end

function ReportCatchManager.matchKeywordInReport(reportText, keywords)
    local source = tostring(reportText or ""):gsub("{%x%x%x%x%x%x}", "")
    source = UtilityManager.trim(source)
    if source == "" then
        return nil
    end

    local sourceVariants = UtilityManager.getMatchVariants(source)
    if #sourceVariants == 0 then
        return nil
    end

    for _, keyword in ipairs(keywords or {}) do
        local keywordVariants = UtilityManager.getMatchVariants(keyword)
        for _, srcVariant in ipairs(sourceVariants) do
            local srcCompact = srcVariant:gsub("%s+", "")
            for _, keywordVariant in ipairs(keywordVariants) do
                if srcVariant:find(keywordVariant, 1, true) then
                    return keyword
                end

                local kwCompact = keywordVariant:gsub("%s+", "")
                if kwCompact ~= "" and srcCompact:find(kwCompact, 1, true) then
                    return keyword
                end
            end
        end
    end

    return nil
end

function ReportCatchManager.getTemplateRouteRaw(templateId)
    local key = tostring(tonumber(templateId) or "")
    if key == "" then
        return ""
    end
    local routeMap = ReportCatchManager.settings.templateRouteMap
    if type(routeMap) ~= "table" then
        routeMap = {}
        ReportCatchManager.settings.templateRouteMap = routeMap
    end
    return tostring(routeMap[key] or "")
end

function ReportCatchManager.setTemplateRouteRaw(templateId, value)
    local key = tostring(tonumber(templateId) or "")
    if key == "" then
        return
    end
    local routeMap = ReportCatchManager.settings.templateRouteMap
    if type(routeMap) ~= "table" then
        routeMap = {}
        ReportCatchManager.settings.templateRouteMap = routeMap
    end
    routeMap[key] = UtilityManager.trim(tostring(value or ""))
end

function ReportCatchManager.getTemplateRoutingKeywordList(templateId)
    return ReportCatchManager.getKeywordListFromRaw(
        ReportCatchManager.getTemplateRouteRaw(templateId)
    )
end

function ReportCatchManager.matchKeywordInText(sourceText, keywords)
    local source = ReportCatchManager.normalizeRoutingText(sourceText)
    if source == "" then
        return nil
    end
    local sourceVariants = UtilityManager.getMatchVariants(source)
    if #sourceVariants == 0 then
        return nil
    end

    for _, keyword in ipairs(keywords or {}) do
        local normalizedKeyword = ReportCatchManager.normalizeRoutingText(keyword)
        if normalizedKeyword ~= "" then
            local keywordVariants = UtilityManager.getMatchVariants(normalizedKeyword)
            for _, srcVariant in ipairs(sourceVariants) do
                local srcCompact = srcVariant:gsub("%s+", "")
                for _, keywordVariant in ipairs(keywordVariants) do
                    if srcVariant:find(keywordVariant, 1, true) then
                        return keyword
                    end
                    local kwCompact = keywordVariant:gsub("%s+", "")
                    if kwCompact ~= "" and srcCompact:find(kwCompact, 1, true) then
                        return keyword
                    end
                end
            end
        end
    end

    return nil
end

function ReportCatchManager.getSuggestedTemplateForReport(reportOrText)
    if ReportCatchManager.settings.templateRoutingEnabled == false then
        return nil, nil
    end

    local reportText = reportOrText
    if type(reportOrText) == "table" then
        reportText = reportOrText.text
    end

    local source = ReportCatchManager.normalizeRoutingText(reportText or "")
    if source == "" then
        return nil, nil
    end

    for _, template in ipairs(ReportCatchManager.templates or {}) do
        local templateId = tonumber(template.id)
        if templateId then
            local keywords = ReportCatchManager.getTemplateRoutingKeywordList(templateId)
            if #keywords > 0 then
                local matchedKeyword = ReportCatchManager.matchKeywordInText(source, keywords)
                if matchedKeyword then
                    return templateId, matchedKeyword
                end
            end
        end
    end

    return nil, nil
end

function ReportCatchManager.ensureSuggestedTemplateForReport(report)
    if not report then
        return nil, nil
    end

    local signature = ReportCatchManager.normalizeRoutingText(report.text or "")
    if report._suggestedTemplateComputed and report._suggestedTemplateSignature == signature then
        return report._suggestedTemplateId, report._suggestedTemplateKeyword
    end

    local templateId, keyword = ReportCatchManager.getSuggestedTemplateForReport(report)
    report._suggestedTemplateComputed = true
    report._suggestedTemplateSignature = signature
    report._suggestedTemplateId = templateId
    report._suggestedTemplateKeyword = keyword
    return templateId, keyword
end

function ReportCatchManager.sendSuggestedReplyForCurrentReport(defaultTemplateId)
    local report = ReportCatchManager.currentReport
    if not report then
        return false
    end

    local templateId = select(1, ReportCatchManager.ensureSuggestedTemplateForReport(report))
    if not templateId then
        templateId = tonumber(defaultTemplateId) or 1
    end
    if not ReportCatchManager.getTemplateById(templateId) then
        local fallbackTemplate = ReportCatchManager.templates and ReportCatchManager.templates[1]
        templateId = fallbackTemplate and tonumber(fallbackTemplate.id) or nil
    end
    if not templateId then
        return false
    end

    ReportCatchManager.sendReply(templateId)
    return true
end

function ReportCatchManager.collectMatchedKeywords(sourceText, keywords)
    local source = ReportCatchManager.normalizeRoutingText(sourceText)
    if source == "" then
        return {}
    end

    local sourceVariants = UtilityManager.getMatchVariants(source)
    if #sourceVariants == 0 then
        sourceVariants = { source }
    end

    local matched = {}
    local seen = {}

    for _, keyword in ipairs(keywords or {}) do
        local normalizedKeyword = ReportCatchManager.normalizeRoutingText(keyword)
        if normalizedKeyword ~= "" then
            local keywordVariants = UtilityManager.getMatchVariants(normalizedKeyword)
            local found = false

            for _, srcVariant in ipairs(sourceVariants) do
                local srcCompact = srcVariant:gsub("%s+", "")
                for _, keywordVariant in ipairs(keywordVariants) do
                    if srcVariant:find(keywordVariant, 1, true) then
                        found = true
                        break
                    end
                    local kwCompact = keywordVariant:gsub("%s+", "")
                    if kwCompact ~= "" and srcCompact:find(kwCompact, 1, true) then
                        found = true
                        break
                    end
                end
                if found then
                    break
                end
            end

            if found then
                local uniqueKey = UtilityManager.casefoldUtf8Cyrillic(normalizedKeyword)
                if uniqueKey ~= "" and not seen[uniqueKey] then
                    seen[uniqueKey] = true
                    table.insert(matched, normalizedKeyword)
                end
            end
        end
    end

    return matched
end

function ReportCatchManager.evaluateAiTemplateForReport(reportText)
    local requireUnique = ReportCatchManager.settings.aiAutoReportRequireUnique ~= false
    local bestTemplateId = nil
    local bestCount = 0
    local bestMatched = {}
    local tie = false

    for _, template in ipairs(ReportCatchManager.templates or {}) do
        local templateId = tonumber(template.id)
        if templateId then
            local keywords = ReportCatchManager.getTemplateRoutingKeywordList(templateId)
            if #keywords > 0 then
                local matchedKeywords = ReportCatchManager.collectMatchedKeywords(reportText, keywords)
                local score = #matchedKeywords
                if score > bestCount then
                    bestTemplateId = templateId
                    bestCount = score
                    bestMatched = matchedKeywords
                    tie = false
                elseif score > 0 and score == bestCount and templateId ~= bestTemplateId then
                    tie = true
                end
            end
        end
    end

    if bestCount <= 0 then
        return nil, 0, {}, "no_match"
    end
    if requireUnique and tie then
        return nil, bestCount, bestMatched, "ambiguous"
    end
    return bestTemplateId, bestCount, bestMatched, "ok"
end

function ReportCatchManager.tryAiAutoReply(report)
    if not report then
        return false
    end
    if ReportCatchManager.settings.aiAutoReportEnabled ~= true then
        return false
    end

    local reportId = tonumber(report.id)
    if not reportId or reportId <= 0 then
        return false
    end

    local runtime = ReportCatchManager.aiAutoRuntime or {}
    ReportCatchManager.aiAutoRuntime = runtime
    runtime.handledByReportId = runtime.handledByReportId or {}

    local nowMs = ReportCatchManager.getNowMs()

    local afkPriorityEnabled =
        (ReportCatchManager.settings.afkReportEnabled == true) and
        ReportCatchManager.isKerakliUnlocked()
    if afkPriorityEnabled then
        local matchedAfkKeyword = ReportCatchManager.matchAfkReportKeyword(report.text or "")
        if matchedAfkKeyword then
            runtime.lastDecisionAt = nowMs
            runtime.lastDecision = string.format(
                "AI: report #%d skip (AFK priority, keyword=%s)",
                reportId,
                tostring(matchedAfkKeyword)
            )
            return false
        end
    end

    local cooldownMs = math.max(1000, math.min(30000,
        (tonumber(ReportCatchManager.settings.aiAutoReportCooldownSec) or 3) * 1000))
    local lastHandledAt = tonumber(runtime.handledByReportId[reportId]) or 0
    if (nowMs - lastHandledAt) < cooldownMs then
        return false
    end

    local templateId, score, matched, status = ReportCatchManager.evaluateAiTemplateForReport(report.text or "")
    if not templateId then
        runtime.lastDecisionAt = nowMs
        if status == "ambiguous" then
            runtime.lastDecision = string.format("AI: report #%d skip (ambiguous, score=%d)", reportId, tonumber(score) or 0)
        else
            runtime.lastDecision = string.format("AI: report #%d skip (no match)", reportId)
        end
        return false
    end

    local template = ReportCatchManager.getTemplateById(templateId)
    if not template then
        return false
    end

    local payload = tostring(template.text or "")
    if payload == "" then
        return false
    end

    sendChat(string.format("/ans %d %s", reportId, payload))
    ReportCatchManager.markAnswered(reportId)
    runtime.handledByReportId[reportId] = nowMs

    local matchedPreview = table.concat(matched or {}, ", ")
    runtime.lastDecisionAt = nowMs
    runtime.lastDecision = string.format(
        "AI: report #%d -> template [%d] score=%d (%s)",
        reportId,
        templateId,
        tonumber(score) or 0,
        matchedPreview ~= "" and matchedPreview or "-"
    )

    if template.id == 1 or template.autoSpReporter then
        local reporterId = ReportCatchManager.resolveReporterPlayerId(report)
        if reporterId then
            PlayerManager.spectate(reporterId)
        end
    end

    if ReportCatchManager.settings.aiAutoReportSkipPopup ~= false and
       ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == reportId then
        ReportCatchManager.closePopup()
    end

    LogManager.report(runtime.lastDecision)
    return true
end

function ReportCatchManager.matchAfkReportKeyword(reportText)
    local keywords = ReportCatchManager.getAfkReportKeywordList()
    return ReportCatchManager.matchKeywordInReport(reportText, keywords)
end

function ReportCatchManager.getAfkReportCooldown()
    return math.max(0, math.min(300, tonumber(ReportCatchManager.settings.afkReportCooldown) or 8))
end

function ReportCatchManager.getReportKeywordReplyCooldown()
    return math.max(0, math.min(300, tonumber(ReportCatchManager.settings.reportKeywordReplyCooldown) or 8))
end

function ReportCatchManager.getFixedEvakuatorReplyText()
    local replyText = ReportCatchManager.sanitizeChatFriendlyText(
        ReportCatchManager.settings and ReportCatchManager.settings.reportKeywordReplyText1 or ""
    )
    if replyText == "" then
        replyText = ReportCatchManager.sanitizeChatFriendlyText(DEFAULT_EVAKUATOR_REPLY_TEXT)
    end
    return replyText
end

function ReportCatchManager.pickReportKeywordReplyText()
    local replyText = ReportCatchManager.getFixedEvakuatorReplyText()
    if replyText == "" then
        return nil, 0
    end
    ReportCatchManager.reportKeywordReplyLastVariantIndex = 1
    return replyText, 1
end

function ReportCatchManager.sendRandomKeywordReplyForReport(reportId, sourceTag)
    local answerId = tonumber(reportId)
    if not answerId then
        return false
    end
    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("report.reply") then
        PermissionGuard.logBlocked("report.reply", "report.reply")
        return false
    end

    local replyText, variantIndex = ReportCatchManager.pickReportKeywordReplyText()
    if not replyText or replyText == "" then
        return false
    end
    replyText = ReportCatchManager.sanitizeChatFriendlyText(replyText)
    if replyText == "" then
        return false
    end

    sendChat(string.format("/ans %d %s", answerId, replyText))
    ReportCatchManager.markAnswered(answerId)

    if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == answerId then
        ReportCatchManager.closePopup()
    end

    LogManager.report(string.format(
        "Evakuator reply sent: report #%d -> variant #%d (source=%s)",
        answerId,
        tonumber(variantIndex) or 1,
        tostring(sourceTag or "unknown")
    ))
    return true, tonumber(variantIndex) or 1
end

function ReportCatchManager.shouldForceAfkRecovery(reportText)
    local source = tostring(reportText or ""):gsub("{%x%x%x%x%x%x}", "")
    source = UtilityManager.trim(source):lower()
    if source == "" then
        return false
    end

    local hints = {
        "tuzat",
        "tuzating",
        "fix",
        "fixcar",
        "repair",
        "agdar",
        "ag'dar",
        "agdarilib",
        "ag'darilib",
        "flip",
        "buzilgan",
        "buzildi"
    }

    for _, hint in ipairs(hints) do
        if source:find(hint, 1, true) then
            return true
        end
    end

    return false
end

function ReportCatchManager.buildAfkAdminHelpCommand(playerId)
    local template = UtilityManager.trim(tostring(ReportCatchManager.settings.afkReportAdminHelpText or ""))
    if template == "" then
        template = "help {id}"
    end

    local idText = tostring(playerId)
    local payload
    if template:find("{id}", 1, true) then
        payload = template:gsub("{id}", idText)
    else
        payload = string.format("%s %s", template, idText)
    end

    payload = UtilityManager.trim(payload:gsub("%s%s+", " "))
    return "/a " .. payload
end

function ReportCatchManager.getWaterHeightAtCoordsSafe(x, y, z)
    if type(getWaterHeightAtCoords) ~= "function" then
        return nil
    end

    local px = tonumber(x)
    local py = tonumber(y)
    local pz = tonumber(z) or 0.0
    if not px or not py then
        return nil
    end

    local ok, a, b, c = pcall(getWaterHeightAtCoords, px, py, pz)
    if not ok then
        ok, a, b, c = pcall(getWaterHeightAtCoords, px, py)
        if not ok then
            return nil
        end
    end

    local wx, wy, wz = TeleportClickManager.extractCoords(a, b, c)
    if wx and wy and wz then
        return tonumber(wz)
    end

    if type(a) == "boolean" then
        if a then
            return tonumber(b) or tonumber(c)
        end
        return nil
    end

    return tonumber(a) or tonumber(b) or tonumber(c)
end

function ReportCatchManager.isCoordsLikelyInWater(x, y, z, margin)
    local px = tonumber(x)
    local py = tonumber(y)
    local pz = tonumber(z)
    if not px or not py or not pz then
        return false
    end

    local waterZ = ReportCatchManager.getWaterHeightAtCoordsSafe(px, py, pz + 0.5)
    if not waterZ then
        return false
    end

    local threshold = tonumber(margin) or 2.2
    return pz <= (waterZ + threshold)
end

function ReportCatchManager.isTargetLikelyInWaterByCoords(playerId)
    local id = tonumber(playerId)
    if not id then
        return false, false
    end

    if not SpectateQuickPanel or type(SpectateQuickPanel.getTargetCenterCoords) ~= "function" then
        return false, false
    end

    local x, y, z, inVehicle = SpectateQuickPanel.getTargetCenterCoords(id)
    if not x or not y or not z then
        return false, inVehicle == true
    end

    return ReportCatchManager.isCoordsLikelyInWater(x, y, z, 2.4), inVehicle == true
end

function ReportCatchManager.getPlayerPedHandle(playerId)
    if type(sampGetCharHandleBySampPlayerId) ~= "function" then
        return nil
    end

    local ok, a, b = pcall(sampGetCharHandleBySampPlayerId, playerId)
    if not ok then
        return nil
    end

    local handle = nil
    if type(a) == "boolean" then
        if not a then
            return nil
        end
        handle = tonumber(b)
    else
        handle = tonumber(a)
    end

    if not handle or handle <= 0 then
        return nil
    end

    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, handle)
        if not okExists or not exists then
            return nil
        end
    end

    return handle
end

function ReportCatchManager.getPlayerVehicleState(playerId)
    local state = {
        known = false,
        inCar = false,
        inWater = false,
        waterByCoords = false,
        isFlipped = false,
        isBroken = false,
        coordKnown = false,
        x = nil,
        y = nil,
        z = nil
    }

    local ped = ReportCatchManager.getPlayerPedHandle(playerId)
    if not ped then
        return state
    end

    state.known = true

    if type(isCharInAnyCar) == "function" then
        local okInCar, inCar = pcall(isCharInAnyCar, ped)
        state.inCar = okInCar and inCar or false
    end

    if not state.inCar then
        return state
    end

    local vehicle = nil
    if type(storeCarCharIsInNoSave) == "function" then
        local okCar, car = pcall(storeCarCharIsInNoSave, ped)
        if okCar then
            vehicle = tonumber(car)
        end
    elseif type(storeCarCharIsIn) == "function" then
        local okCar, car = pcall(storeCarCharIsIn, ped)
        if okCar then
            vehicle = tonumber(car)
        end
    end

    if not vehicle then
        return state
    end

    if type(doesVehicleExist) == "function" then
        local okVehicle, exists = pcall(doesVehicleExist, vehicle)
        if okVehicle and not exists then
            return state
        end
    end

    if type(isCarInWater) == "function" then
        local okWater, inWater = pcall(isCarInWater, vehicle)
        state.inWater = okWater and inWater or false
    end

    if type(getCarCoordinates) == "function" then
        local okVeh, a, b, c = pcall(getCarCoordinates, vehicle)
        if okVeh then
            local vx, vy, vz = TeleportClickManager.extractCoords(a, b, c)
            if vx and vy and vz then
                state.coordKnown = true
                state.x, state.y, state.z = vx, vy, vz
                local byCoords = ReportCatchManager.isCoordsLikelyInWater(vx, vy, vz, 2.4)
                state.waterByCoords = byCoords
                if byCoords then
                    state.inWater = true
                end
            end
        end
    end

    if not state.coordKnown and type(getCharCoordinates) == "function" then
        local okPedPos, a, b, c = pcall(getCharCoordinates, ped)
        if okPedPos then
            local px, py, pz = TeleportClickManager.extractCoords(a, b, c)
            if px and py and pz then
                state.coordKnown = true
                state.x, state.y, state.z = px, py, pz
                local byCoords = ReportCatchManager.isCoordsLikelyInWater(px, py, pz, 2.2)
                state.waterByCoords = byCoords
                if byCoords then
                    state.inWater = true
                end
            end
        end
    end

    if type(isCarUpsideDown) == "function" then
        local okUpside, upside = pcall(isCarUpsideDown, vehicle)
        state.isFlipped = okUpside and upside or false
    end

    if type(getCarHealth) == "function" then
        local okHealth, health = pcall(getCarHealth, vehicle)
        local hp = okHealth and tonumber(health) or nil
        if hp and hp > 0 and hp < 650 then
            state.isBroken = true
        end
    end

    return state
end

function ReportCatchManager.sendAfkRecoveryCommands(playerId, attempts, delayMs)
    if not ReportCatchManager.isKerakliUnlocked() then
        return false
    end

    local id = tonumber(playerId)
    if not id then
        return false
    end

    local total = math.max(1, math.min(3, tonumber(attempts) or 1))
    local gap = math.max(250, math.min(1200, tonumber(delayMs) or 550))

    for index = 1, total do
        if not ReportCatchManager.isKerakliUnlocked() then
            return false
        end
        sendChat(string.format("/flip %d", id))
        wait(gap)
        if not ReportCatchManager.isKerakliUnlocked() then
            return false
        end
        sendChat(string.format("/fixcar %d", id))
        if index < total then
            wait(gap)
        end
    end

    return true
end

function ReportCatchManager.runAfkVehicleAutoActions(playerId, reportText)
    if not ReportCatchManager.isKerakliUnlocked() then
        return
    end

    local id = tonumber(playerId)
    if not id then
        return
    end

    local forceRecoveryByText = ReportCatchManager.shouldForceAfkRecovery(reportText)
    local localAfk = AFKManager and AFKManager.isAFK == true
    local recoveryAlreadySent = false
    local preState = ReportCatchManager.getPlayerVehicleState(id)
    local preWaterInCar = preState and preState.inCar and preState.inWater or false
    local preInCar = preState and preState.inCar or false

    if localAfk and not preWaterInCar then
        -- AFK paytida stream holati kechikishi mumkin, bir marta darhol yuboramiz.
        sendChat(string.format("/flip %d", id))
        sendChat(string.format("/fixcar %d", id))
        recoveryAlreadySent = true
        LogManager.report(string.format(
            "AFK report: immediate recovery fallback sent for #%d (localAfk=%s)",
            id,
            tostring(localAfk)))
    elseif localAfk and preWaterInCar then
        LogManager.report(string.format(
            "AFK report: immediate flip/fix skipped for #%d (water detected pre-check)",
            id))
    end

    lua_thread.create(function()
        if not ReportCatchManager.isKerakliUnlocked() then
            return
        end

        local state = nil
        local seenKnown = false
        local seenInCar = false

        wait(350)
        for _ = 1, 24 do
            state = ReportCatchManager.getPlayerVehicleState(id)
            if state and state.known then
                seenKnown = true
            end
            if state and state.inCar then
                seenInCar = true
                if state.inWater or state.isFlipped or state.isBroken then
                    break
                end
            end
            wait(250)
        end

        local detectedWaterInCar = (state and state.inCar and state.inWater) or preWaterInCar
        local usedTpCarForWater = false

        if not detectedWaterInCar then
            local coordWater, coordInVehicle = ReportCatchManager.isTargetLikelyInWaterByCoords(id)
            if coordWater and (coordInVehicle or preInCar or seenInCar) then
                detectedWaterInCar = true
                LogManager.report(string.format(
                    "AFK report: water detected by coord fallback for #%d (coordInVehicle=%s preInCar=%s seenInCar=%s)",
                    id,
                    tostring(coordInVehicle),
                    tostring(preInCar),
                    tostring(seenInCar)))
            end
        end

        if detectedWaterInCar and ReportCatchManager.isKerakliUnlocked() then
            local helpCmd = ReportCatchManager.buildAfkAdminHelpCommand(id)
            sendChat(helpCmd)
            LogManager.report(string.format("AFK report: water detected for #%d -> %s", id, helpCmd))
            -- AFK report oqimida teleport butunlay o'chirilgan (no /gethere, no /getcar).
            LogManager.report(string.format(
                "AFK report: teleport disabled for #%d, only recovery commands are allowed",
                id))
            wait(500)
        end

        local detectedFlip = state and state.inCar and state.isFlipped or false
        local detectedBroken = state and state.inCar and state.isBroken or false
        local needRecovery = detectedFlip or detectedBroken or (detectedWaterInCar and (not usedTpCarForWater))

        -- Oddiy holatda (AFK emas) text trigger recovery'ni kuchaytiradi.
        if not needRecovery and forceRecoveryByText and not localAfk then
            needRecovery = true
        end

        if not needRecovery and (not seenKnown or (localAfk and not seenInCar)) then
            needRecovery = true
            LogManager.report(string.format(
                "AFK report: vehicle state unavailable for #%d (known=%s inCar=%s localAfk=%s), recovery fallback enabled",
                id,
                tostring(seenKnown),
                tostring(seenInCar),
                tostring(localAfk)))
        end

        if needRecovery then
            if recoveryAlreadySent then
                LogManager.report(string.format(
                    "AFK report: recovery already sent for #%d, duplicate prevented",
                    id))
            else
                local attempts = 1
                ReportCatchManager.sendAfkRecoveryCommands(id, attempts, 550)
                recoveryAlreadySent = true
                LogManager.report(string.format(
                    "AFK report: recovery commands sent for #%d (flip=%s broken=%s forceByText=%s localAfk=%s)",
                    id,
                    tostring(detectedFlip),
                    tostring(detectedBroken),
                    tostring(forceRecoveryByText),
                    tostring(localAfk)))
            end
        else
            LogManager.report(string.format(
                "AFK report: no recovery needed for #%d (known=%s inCar=%s)",
                id,
                tostring(seenKnown),
                tostring(seenInCar)))
        end
    end)
end

function ReportCatchManager.handleAfkReportAuto(report, playerId)
    if not ReportCatchManager.isKerakliUnlocked() then
        return false
    end
    if not ReportCatchManager.settings.afkReportEnabled then
        return false
    end
    if not report or not playerId then
        return false
    end

    local matchedKeyword = ReportCatchManager.matchAfkReportKeyword(report.text or "")
    if not matchedKeyword then
        return false
    end

    local now = os.time()
    local cooldown = ReportCatchManager.getAfkReportCooldown()
    local last = tonumber(ReportCatchManager.afkReportLastByPlayer[playerId]) or 0
    if now - last < cooldown then
        LogManager.report(string.format(
            "AFK report skipped by cooldown for #%d (remaining %ds)",
            playerId,
            math.max(0, cooldown - (now - last))))
        return true
    end
    ReportCatchManager.afkReportLastByPlayer[playerId] = now

    local answerId = tonumber(report.id)
    local replyText = UtilityManager.trim(tostring(ReportCatchManager.settings.afkReportReplyText or ""))
    if replyText == "" then
        replyText = "Assalom alekum, kuzatyapman"
    end

    if answerId then
        sendChat(string.format("/ans %d %s", answerId, replyText))
        ReportCatchManager.markAnswered(answerId)
    end

    PlayerManager.spectate(playerId)

    if answerId and ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == answerId then
        ReportCatchManager.closePopup()
    end

    LogManager.report(string.format(
        "AFK report auto handled: report #%s keyword '%s' -> player #%d (reply + spectate only)",
        tostring(report.id),
        matchedKeyword,
        playerId))
    return true
end

function ReportCatchManager.handleReportKeywordReplyAuto(report, playerId)
    if not ReportCatchManager.isKerakliUnlocked() then
        return false
    end
    if ReportCatchManager.settings.reportKeywordReplyEnabled ~= true then
        return false
    end
    if not report then
        return false
    end

    local matchedKeyword = ReportCatchManager.matchKeywordInReport(
        report.text or "",
        ReportCatchManager.getReportKeywordReplyList()
    )
    if not matchedKeyword then
        return false
    end

    local answerId = tonumber(report.id)
    if not answerId then
        return false
    end

    local now = os.time()
    local key = tostring(tonumber(playerId) or answerId)
    local cooldown = ReportCatchManager.getReportKeywordReplyCooldown()
    local last = tonumber(ReportCatchManager.reportKeywordReplyLastByPlayer[key]) or 0
    if now - last < cooldown then
        LogManager.report(string.format(
            "Keyword auto reply skipped by cooldown for report #%s keyword '%s' (remaining %ds)",
            tostring(report.id),
            tostring(matchedKeyword),
            math.max(0, cooldown - (now - last))
        ))
        return true
    end

    ReportCatchManager.reportKeywordReplyLastByPlayer[key] = now
    local sent, variantIndex = ReportCatchManager.sendRandomKeywordReplyForReport(answerId, "keyword_auto")
    if not sent then
        return false
    end

    LogManager.report(string.format(
        "Keyword auto reply handled: report #%s keyword '%s' -> variant #%d",
        tostring(report.id),
        tostring(matchedKeyword),
        tonumber(variantIndex) or 1
    ))
    return true
end

function UtilityManager.hashSecret(text)
    local input = tostring(text or "")
    local h = 0x45D9F3B
    for i = 1, #input do
        local byte = string.byte(input, i) or 0
        h = (h * 131 + byte + i * 17) % 4294967296
    end
    h = (h + #input * 97) % 4294967296
    return string.format("%08x", h)
end

