        ["tools by nico.luac"] = "43d0a06a94e995ab0861bf2496475f53d8f33228a6665d5dd50075bc2c5c81d8",
        ["tools by bober.luac"] = "5413adc9b1a49efecee2aebaf853bd7519ff6f785571a444fa22a3801226f5d3",
        ["tools by bizarych.luac"] = "c52e9afd0b51cf643ca15856465c6d85d37c222c6f0bcbce783db908e888caa0"
    }
}

function AccessControl.buildSecret()
    local parts = {
        "hikmat",
        "::offline_",
        "access::",
        "2026::",
        "b91f67d2"
    }
    return table.concat(parts)
end

function AccessControl.computeNickProof(index, nick)
    return Crypto.sha256(string.format(
        "nick|%d|%s|%s",
        tonumber(index) or 0,
        AccessControl.buildSecret(),
        tostring(nick or "")
    ))
end

function AccessControl.computePolicyProof()
    return Crypto.sha256(string.format(
        "policy|%s|%s",
        AccessControl.buildSecret(),
        table.concat(AccessControl.authorizedNicks or {}, "|")
    ))
end

function AccessControl.getScriptPath()
    if type(thisScript) ~= "function" then
        return ""
    end

    local okScript, scriptObj = pcall(thisScript)
    if not okScript or not scriptObj or not scriptObj.path then
        return ""
    end

    return tostring(scriptObj.path or "")
end

function AccessControl.readSelfBytes(path)
    local scriptPath = tostring(path or "")
    if scriptPath == "" then
        return nil
    end

    local file = io.open(scriptPath, "rb")
    if not file then
        return nil
    end

    local bytes = file:read("*a")
    file:close()
    return bytes
end

function AccessControl.normalizeSelfBytes(bytes)
    local normalized = tostring(bytes or "")
    normalized = normalized:gsub("selfProofs%s*=%s*%b{}", "selfProofs={__SELF_PROOFS_BLOCK__}")
    return normalized
end

function AccessControl.computeSelfProof(fileName, bytes)
    local normalizedName = tostring(fileName or ""):lower()
    local normalizedBytes = AccessControl.normalizeSelfBytes(bytes)
    return Crypto.sha256(string.format(
        "self|%s|%s|%s",
        normalizedName,
        AccessControl.buildSecret(),
        normalizedBytes
    ))
end

function AccessControl.isSelfIntact()
    local scriptPath = AccessControl.getScriptPath()
    if scriptPath == "" then
        return false, "script_path_unavailable"
    end

    local fileName = tostring(scriptPath:match("[^\\/]+$") or ""):lower()
    local expected = tostring((AccessControl.selfProofs or {})[fileName] or "")
    if expected == "" then
        return false, "unexpected_script_file:" .. tostring(fileName or "unknown")
    end

    local bytes = AccessControl.readSelfBytes(scriptPath)
    if not bytes or bytes == "" then
        return false, "self_read_failed:" .. tostring(fileName)
    end

    local actual = tostring(AccessControl.computeSelfProof(fileName, bytes))
    if actual ~= expected then
        return false, "self_tampered:" .. tostring(fileName)
    end

    return true, "ok"
end

function AccessControl.isPolicyIntact()
    if #(AccessControl.authorizedNicks or {}) ~= 13 then
        return false, "policy_nick_count"
    end

    if #(AccessControl.nickProofs or {}) ~= #(AccessControl.authorizedNicks or {}) then
        return false, "policy_proof_count"
    end

    if tostring(AccessControl.computePolicyProof()) ~= tostring(AccessControl.policyProof or "") then
        return false, "policy_hash_mismatch"
    end

    for index, nick in ipairs(AccessControl.authorizedNicks or {}) do
        local expected = tostring(AccessControl.nickProofs[index] or "")
        if expected == "" or AccessControl.computeNickProof(index, nick) ~= expected then
            return false, "nick_proof_mismatch:" .. tostring(index)
        end
    end

    return true, "ok"
end

function AccessControl.getLocalNick()
    if not PLAYER_PED or type(sampGetPlayerIdByCharHandle) ~= "function" or type(sampGetPlayerNickname) ~= "function" then
        return ""
    end

    local okId, a, b = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not okId then
        return ""
    end

    local playerId = nil
    if type(a) == "boolean" then
        if a then
            playerId = tonumber(b)
        end
    else
        playerId = tonumber(a)
    end

    if not playerId then
        return ""
    end

    local okNick, nick = pcall(sampGetPlayerNickname, playerId)
    if not okNick then
        return ""
    end

    return tostring(nick or "")
end

function AccessControl.isAuthorizedNick(nick)
    local candidate = tostring(nick or "")
    for _, allowedNick in ipairs(AccessControl.authorizedNicks or {}) do
        if candidate == tostring(allowedNick) then
            return true
        end
    end
    return false
end

function AccessControl.crash(reason)
    error("AccessControl: " .. tostring(reason or "unauthorized"), 0)
end

function AccessControl.enforce(options)
    local opts = options or {}
    local crashOnMissingNick = opts.crashOnMissingNick ~= false

    local policyOk, policyReason = AccessControl.isPolicyIntact()
    if not policyOk then
        AccessControl.crash(policyReason or "policy_tampered")
        return false
    end

    local nick = AccessControl.getLocalNick()
    if nick == "" then
        if crashOnMissingNick then
            AccessControl.crash("nick_unavailable")
        end
        return false
    end

    if not AccessControl.isAuthorizedNick(nick) then
        AccessControl.crash("unauthorized_nick:" .. nick)
        return false
    end

    if not AccessControl.welcomed then
        local welcomeText = string.format("[GMEA] Assalomu Alaykum %s", nick)
        if type(print) == "function" then
            print(welcomeText)
        end
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(welcomeText, 0x33FF66)
        end
        AccessControl.welcomed = true
    end

    return true
end

function AccessControl.waitAndEnforce(timeoutMs)
    local deadline = (os.clock() * 1000) + math.max(1000, tonumber(timeoutMs) or 10000)
    while (os.clock() * 1000) < deadline do
        local nick = AccessControl.getLocalNick()
        if nick ~= "" then
            break
        end
        wait(100)
    end

    AccessControl.enforce({ crashOnMissingNick = true })
end

function ReportCatchManager.queueKeywordTp(report)
    if not ReportCatchManager.isMpUnlocked() then
        return
    end
    if not ReportCatchManager.settings.keywordTpEnabled then
        return
    end

    if not report then
        return
    end

    local trigger = ReportCatchManager.getKeywordTpTrigger()
    if trigger == "" then
        return
    end

    local reportText = tostring(report.text or ""):gsub("{%x%x%x%x%x%x}", "")
    reportText = UtilityManager.trim(reportText):lower()
    local rawReportText = tostring(report.rawText or ""):gsub("{%x%x%x%x%x%x}", "")
    local rawReportBody =
        rawReportText:match(":%s*(.-)%s*%[[Hh]isobotlar%s+soni%s*:") or
        rawReportText:match(":%s*(.*)$") or
        rawReportText
    rawReportBody = UtilityManager.trim(tostring(rawReportBody or "")):lower()

    if reportText == "" and rawReportBody == "" then
        return
    end

    if (reportText == "" or not reportText:find(trigger, 1, true)) and
       (rawReportBody == "" or not rawReportBody:find(trigger, 1, true)) then
        return
    end

    local targetId = tonumber(ReportCatchManager.resolveReporterPlayerId(report) or
        ReportCatchManager.resolveAutoActionPlayerId(report))
    if not targetId then
        return
    end

    -- Agar bu o'yinchi MP da o'lib, blokda bo'lsa — TP qilmaslik, faqat /ans xabar yuborish
    local deathBlock = ReportCatchManager.mpDeathBlocked[targetId]
    if deathBlock then
        local reportId = tonumber(report.id) or 0
        if reportId > 0 then
            local blockedMsg = "Assalomu alaykum, siz uchun teleport muddati tugagan"
            sendChat(string.format("/ans %d %s", reportId, blockedMsg))
            if LogManager and LogManager.report then
                LogManager.report(string.format(
                    "Keyword TP BLOCKED (death-blocked): report #%d from %s -> player #%d. Auto /ans sent.",
                    reportId, tostring(report.nick or "Unknown"), targetId))
            end
        end
        return
    end

    local now = os.time()
    local cooldown = 10
    local lastTp = tonumber(ReportCatchManager.keywordTpLastByPlayer[targetId]) or 0
    if now - lastTp < cooldown then
        return
    end

    if ReportCatchManager.keywordTpQueuedPlayers[targetId] then
        return
    end

    table.insert(ReportCatchManager.keywordTpQueue, {
        playerId = targetId,
        reportId = tonumber(report.id) or 0,
        nick = tostring(report.nick or "Unknown")
    })
    ReportCatchManager.keywordTpQueuedPlayers[targetId] = true
    LogManager.report(string.format(
        "Keyword TP queued: report #%d from %s -> player #%d",
        tonumber(report.id) or 0,
        tostring(report.nick or "Unknown"),
        targetId))

    -- Run immediately to avoid delayed gethere after keyword match.
    ReportCatchManager.processKeywordTpQueue(true)
end

function ReportCatchManager.processKeywordTpQueue(forceImmediate)
    if (not ReportCatchManager.settings.keywordTpEnabled) or (not ReportCatchManager.isMpUnlocked()) then
        if #ReportCatchManager.keywordTpQueue > 0 or next(ReportCatchManager.keywordTpQueuedPlayers) ~= nil then
            ReportCatchManager.keywordTpQueue = {}
            ReportCatchManager.keywordTpQueuedPlayers = {}
        end
        return
    end

    if #ReportCatchManager.keywordTpQueue == 0 then
        return
    end

    local nowClock = os.clock()
    if not forceImmediate and nowClock - ReportCatchManager.keywordTpLastProcessAt < 0.6 then
        return
    end

    local nextTp = table.remove(ReportCatchManager.keywordTpQueue, 1)
    if not nextTp then
        return
    end
    ReportCatchManager.keywordTpQueuedPlayers[nextTp.playerId] = nil

    local now = os.time()
    local cooldown = 10
    local lastTp = tonumber(ReportCatchManager.keywordTpLastByPlayer[nextTp.playerId]) or 0
    if now - lastTp < cooldown then
        return
    end

    local resolvedPlayerId = tonumber(nextTp.playerId)
    if type(sampIsPlayerConnected) == "function" and resolvedPlayerId then
        local okConnected, connected = pcall(sampIsPlayerConnected, resolvedPlayerId)
        if okConnected and not connected then
            local fallbackByNick = ReportCatchManager.getPlayerIdByNick(nextTp.nick)
            if fallbackByNick then
                resolvedPlayerId = tonumber(fallbackByNick)
            else
                LogManager.report(string.format(
                    "Keyword TP local cache miss for player #%d (%s), forcing /gethere with original id",
                    tonumber(nextTp.playerId) or -1,
                    tostring(nextTp.nick or "Unknown")))
            end
        end
    end

    nextTp.playerId = tonumber(resolvedPlayerId or nextTp.playerId)
    if not nextTp.playerId or nextTp.playerId <= 0 then
        LogManager.report("Keyword TP skipped: player id could not be resolved")
        return
    end

    ReportCatchManager.keywordTpLastProcessAt = nowClock

    local answerId = tonumber(nextTp.reportId) or 0
    local sentAns = false
    if answerId > 0 and ReportCatchManager.settings.keywordTpAutoAnsEnabled ~= false then
        local ansText = UtilityManager.trim(tostring(
            ReportCatchManager.settings.keywordTpAutoAnsText or
            "Assalamu alaykum, hozir teleport bo'lasiz"
        ))
        if ansText == "" then
            ansText = "Assalamu alaykum, hozir teleport bo'lasiz"
        end
        sentAns = ReportCatchManager.sendKeywordTpCommand(string.format("/ans %d %s", answerId, ansText))
        if sentAns then
            ReportCatchManager.markAnswered(answerId)
        end
    end

    -- safety fix: bypass stale local player cache blockers and dispatch /gethere directly for MP keyword TP.
    local gethereSent = ReportCatchManager.dispatchKeywordTpBring(nextTp.playerId)
    if not gethereSent then
        LogManager.report(string.format(
            "Keyword TP failed to dispatch bring/gethere for player #%d",
            tonumber(nextTp.playerId) or -1))
        return
    end

    ReportCatchManager.applyKeywordTpPostActions(nextTp.playerId)
    ReportCatchManager.addMpPlayer(nextTp.playerId, nextTp.nick, answerId)
    ReportCatchManager.markKeywordTp(nextTp.playerId)
    LogManager.report(string.format(
        "Keyword gethere executed: report #%d (%s) -> player #%d (preAns=%s)",
        answerId,
        tostring(nextTp.nick or "Unknown"),
        nextTp.playerId,
        sentAns and "yes" or "no"))
end

function ReportCatchManager.tryImmediateAutoActions(report, resolvedTargetId)
    if not report then
        return false, nil
    end

    local targetId = tonumber(resolvedTargetId)
    if targetId and ReportCatchManager.handleAfkReportAuto(report, targetId) then
        return true, targetId
    end
    if ReportCatchManager.handleReportKeywordReplyAuto(report, targetId) then
        return true, targetId
    end

    return false, targetId
end

function ReportCatchManager.applyAutoActions(report, resolvedTargetId)
    if not report then
        return
    end

    local targetId = tonumber(resolvedTargetId or ReportCatchManager.resolveAutoActionPlayerId(report))
    local immediateHandled = select(1, ReportCatchManager.tryImmediateAutoActions(report, targetId))
    if immediateHandled then
        return
    end

    ReportCatchManager.queueKeywordTp(report)

    if not targetId then
        return
    end

    if ReportCatchManager.settings.autoTP then
        PlayerManager.teleportTo(targetId)
        ReportCatchManager.markKeywordTp(targetId)
    end
    if ReportCatchManager.settings.autoSP then
        PlayerManager.spectate(targetId)
    end
end

function ReportCatchManager.handleParsedReport(report, popupEnabled, autoEnabled, logMessage)
    if not report then
        return false
    end

    if PlayerLogManager and type(PlayerLogManager.captureReport) == "function" then
        PlayerLogManager.captureReport(report)
    end

    if logMessage and LogManager and LogManager.report then
        LogManager.report(logMessage)
    end

    local resolvedTargetId = nil
    if autoEnabled then
        resolvedTargetId = tonumber(ReportCatchManager.resolveAutoActionPlayerId(report))

        local repQuickHandled = RepQuickReplyManager and RepQuickReplyManager.tryAutoAnswer and
                                RepQuickReplyManager.tryAutoAnswer(report)
        if repQuickHandled then
            return true
        end

        local aiHandled = ReportCatchManager.tryAiAutoReply(report)
        if aiHandled then
            ReportCatchManager.queueKeywordTp(report)
            return true
        end

        local immediateHandled = select(1, ReportCatchManager.tryImmediateAutoActions(report, resolvedTargetId))
        if immediateHandled then
            return true
        end
    end

    if popupEnabled and ReportCatchManager.shouldIgnoreIncoming(report) then
        return true
    end

    if popupEnabled then
        ReportCatchManager.showReport(report)
    end
    if autoEnabled then
        ReportCatchManager.applyAutoActions(report, resolvedTargetId)
    end

    return true
end

function ReportCatchManager.processReport(text)
    local popupEnabled = ReportCatchManager.enabled
    local autoEnabled = ReportCatchManager.shouldRunAutoActions()

    -- Popup OFF bo'lsa ham auto-actions yoqilgan bo'lsa report qayta ishlanadi.
    if (not popupEnabled) and (not autoEnabled) then
        return false
    end

    local cleanText = text:gsub("{%x%x%x%x%x%x}", ""):gsub("^%s+", "")

    -- Grand Mobile report format:
    -- Nick[ID]: message [Hisobotlar soni: N]
    local gmNick, gmPlayerId, gmText, gmCount =
        cleanText:match("^.-([%w_%.%-]+)%s*%[(%d+)%]%s*:%s*(.-)%s*%[[Hh]isobotlar%s+soni%s*:%s*(%d+)%]%s*$")
    if gmNick and gmPlayerId then
        local reportId = tonumber(gmPlayerId) or tonumber(os.time() % 100000)
        if ReportCatchManager.isDuplicate(reportId, gmNick) then
            LogManager.security(string.format("Duplicate report ignored: #%d from %s", reportId, gmNick))
            return true
        end

        local resolvedPlayerId = tonumber(gmPlayerId)
        if resolvedPlayerId and type(sampIsPlayerConnected) == "function" then
            local okConnected, connected = pcall(sampIsPlayerConnected, resolvedPlayerId)
            if not (okConnected and connected) then
                resolvedPlayerId = ReportCatchManager.getPlayerIdByNick(gmNick) or resolvedPlayerId
            end
        elseif not resolvedPlayerId then
            resolvedPlayerId = ReportCatchManager.getPlayerIdByNick(gmNick)
        end

        local report = {
            id = reportId,
            nick = gmNick,
            text = gmText or "",
            rawText = cleanText,
            time = os.time(),
            formattedTime = os.date("%H:%M:%S"),
            playerId = resolvedPlayerId,
            reportCount = tonumber(gmCount) or 0
        }
        return ReportCatchManager.handleParsedReport(
            report,
            popupEnabled,
            autoEnabled,
            string.format("Caught GM report from %s[%d]: %s", gmNick, reportId, report.text:sub(1, 40))
        )
    end

    for _, pattern in ipairs(ReportCatchManager.reportPatterns) do
        local c1, c2, c3 = cleanText:match(pattern)
        if c1 then
            local id, nick, reportText
            if c3 then
                id = tonumber(c1)
                nick = c2
                reportText = c3
            else
                nick = c1
                reportText = c2 or ""
            end
            if not id then
                id = tonumber(os.time() % 100000)
            end

            if ReportCatchManager.isDuplicate(id, nick) then
                LogManager.security(string.format("Duplicate report ignored: #%d from %s", id, nick))
                return true
            end

            local report = {
                id = id,
                nick = nick,
                text = reportText or "",
                rawText = cleanText,
                time = os.time(),
                formattedTime = os.date("%H:%M:%S"),
                playerId = ReportCatchManager.getPlayerIdByNick(nick)
            }
            return ReportCatchManager.handleParsedReport(
                report,
                popupEnabled,
                autoEnabled,
                string.format("Caught report #%d from %s: %s", id, nick, report.text:sub(1, 30))
            )
        end
    end

    -- Generic fallback for many server formats: "#123 Nick: message"
    local id, nick, reportText = cleanText:match("#(%d+)%s+(%S+)%s*:%s*(.+)")
    if id and nick then
        local report = {
            id = tonumber(id) or tonumber(os.time() % 100000),
            nick = nick,
            text = reportText or "",
            rawText = cleanText,
            time = os.time(),
            formattedTime = os.date("%H:%M:%S"),
            playerId = ReportCatchManager.getPlayerIdByNick(nick)
        }
        return ReportCatchManager.handleParsedReport(
            report,
            popupEnabled,
            autoEnabled,
            string.format("Caught report #%d from %s: %s", tonumber(report.id) or 0, nick, report.text:sub(1, 30))
        )
    end

    return false
end

function ReportCatchManager.getPlayerIdByNick(nick)
    local targetNick = tostring(nick or "")
    if targetNick == "" then
        return nil
    end
    if type(sampGetMaxPlayerId) ~= "function" or
       type(sampIsPlayerConnected) ~= "function" or
       type(sampGetPlayerNickname) ~= "function" then
        return nil
    end

    local okMax, maxPlayerId = pcall(sampGetMaxPlayerId, false)
    maxPlayerId = okMax and tonumber(maxPlayerId) or nil
    if not maxPlayerId then
        return nil
    end

    local foldedTarget = ReportCatchManager.foldAdminKey(targetNick)

    for i = 0, maxPlayerId do
        local okConnected, connected = pcall(sampIsPlayerConnected, i)
        if okConnected and connected then
            local okNick, currentNick = pcall(sampGetPlayerNickname, i)
            if okNick then
                local current = tostring(currentNick or "")
                if current == targetNick then
                    return i
                end
                -- safety fix: fallback to normalized nick comparison so report nick formatting differences do not break TP resolution.
                if current ~= "" and ReportCatchManager.foldAdminKey(current) == foldedTarget then
                    return i
                end
            end
        end
    end
    return nil
end

function ReportCatchManager.resolveReporterPlayerId(report)
    if not report then return nil end

    local playerId = tonumber(report.playerId)
    if playerId and sampIsPlayerConnected(playerId) then
        return playerId
    end

    local nick = report.nick or ""
    if nick ~= "" then
        local byNick = ReportCatchManager.getPlayerIdByNick(nick)
        if byNick then
            return byNick
        end
    end

    if playerId then
        return playerId
    end

    local fallbackId = tonumber(report.id)
    if fallbackId then
        return fallbackId
    end

    return nil
end

function ReportCatchManager.extractMentionedPlayerIdFromText(report)
    if not report then
        return nil
    end

    local text = (report.text or ""):gsub("{%x%x%x%x%x%x}", "")
    text = UtilityManager.trim(text)
    if text == "" then
        return nil
    end

    local reporterId = tonumber(ReportCatchManager.resolveReporterPlayerId(report))
    local maxPlayerId = 1000
    if sampGetMaxPlayerId then
        local ok, value = pcall(sampGetMaxPlayerId, false)
        if ok and tonumber(value) then
            maxPlayerId = tonumber(value)
        end
    end

    local seen = {}
    local function pickIfValid(rawId)
        local id = tonumber(rawId)
        if not id then
            return nil
        end
        if id < 0 or id > maxPlayerId then
            return nil
        end
        if reporterId and id == reporterId then
            return nil
        end
        if seen[id] then
            return nil
        end
        seen[id] = true

        if sampIsPlayerConnected and sampIsPlayerConnected(id) then
            return id
        end
        return nil
    end

    for raw in text:gmatch("[Ii][Dd]%s*[:=#%-]?%s*(%d+)") do
        local id = pickIfValid(raw)
        if id then return id end
    end

    for raw in text:gmatch("%[(%d+)%]") do
        local id = pickIfValid(raw)
        if id then return id end
    end

    for raw in text:gmatch("#(%d+)") do
        local id = pickIfValid(raw)
        if id then return id end
    end

    for raw in text:gmatch("%d+") do
        local id = pickIfValid(raw)
        if id then return id end
    end

    return nil
end

function ReportCatchManager.resolveMentionedPlayer(report)
    if not report then
        return nil
    end

    local cachedId = tonumber(report.mentionedPlayerId)
    if cachedId and sampIsPlayerConnected and sampIsPlayerConnected(cachedId) then
        report.mentionedPlayerNick = sampGetPlayerNickname(cachedId) or ""
        return cachedId
    end

    local extractedId = ReportCatchManager.extractMentionedPlayerIdFromText(report)
    if extractedId then
        report.mentionedPlayerId = extractedId
        report.mentionedPlayerNick = sampGetPlayerNickname(extractedId) or ""
        return extractedId
    end

    report.mentionedPlayerId = nil
    report.mentionedPlayerNick = ""
    return nil
end

function ReportCatchManager.spectateMentionedPlayerFromReport()
    local report = ReportCatchManager.currentReport
    if not report then return end

    local mentionedId = ReportCatchManager.resolveMentionedPlayer(report)
    if not mentionedId then
        sampAddChatMessage("[Report Catch] Reportdagi ID topilmadi yoki player online emas.", 0xFF6666)
        return
    end

    local answerId = tonumber(report.id)
    if answerId then
        sendChat(string.format("/ans %d Assalomu alaykum, o'yinchini kuzatyapman", answerId))
        ReportCatchManager.markAnswered(answerId)
    else
        sampAddChatMessage("[Report Catch] /ans uchun report ID topilmadi.", 0xFF6666)
    end

    PlayerManager.spectate(mentionedId)
    if answerId then
        SpectateQuickPanel.enableReportReviewMode(answerId)
    end

    LogManager.report(string.format("Report mention spectate started: report #%s -> player #%d", tostring(report.id), mentionedId))
    ReportCatchManager.closePopup()
end

function ReportCatchManager.showReport(report)
    if LogManager and LogManager.report then
        LogManager.report(string.format("[REPORT] popup callback entered | id=%s", tostring(report and report.id or "?")))
    end
    local screenX = select(1, getScreenResolution()) or 1920
    local defaultX = math.max(10, screenX - (ReportCatchManager.settings.popupSize.width + 30))
    ReportCatchManager.settings.popupPos.x = defaultX
    ReportCatchManager.settings.popupPos.y = 120

    report.mentionedPlayerId = ReportCatchManager.extractMentionedPlayerIdFromText(report)
    if report.mentionedPlayerId then
        report.mentionedPlayerNick = sampGetPlayerNickname(report.mentionedPlayerId) or ""
    else
        report.mentionedPlayerNick = ""
    end
    ReportCatchManager.ensureSuggestedTemplateForReport(report)

    ReportCatchManager.currentReport = report
    ReportCatchManager.resetPopupReplyBuffer()
    ReportCatchManager.popupOpen = true
    ReportCatchManager.setWaitingReport(report)
    ReportCatchManager.animationProgress = 0
    imgui.Process = true
    imgui.ShowCursor = true

    if SettingsManager.get("soundEnabled") and ReportCatchManager.settings.soundEnabled then
        print("\a[Report Catch] NEW REPORT!")
    end

    LogManager.report(string.format("Popup shown for report #%d", report.id))
    if LogManager and LogManager.report then
        LogManager.report(string.format("[REPORT] popup callback exited | id=%s", tostring(report and report.id or "?")))
    end
end

function ReportCatchManager.ensurePopupReplyBuffer()
    if not ReportCatchManager.popupReplyBuffer then
        ReportCatchManager.popupReplyBuffer = imgui.new.char[384]()
        UtilityManager.setBufferString(ReportCatchManager.popupReplyBuffer, "")
    end
    return ReportCatchManager.popupReplyBuffer
end

function ReportCatchManager.resetPopupReplyBuffer()
    local buffer = ReportCatchManager.ensurePopupReplyBuffer()
    UtilityManager.setBufferString(buffer, "")
    return buffer
end

function ReportCatchManager.buildPopupReplyPayload(rawText)
    local text = ReportCatchManager.sanitizeChatFriendlyText(rawText)
    text = UtilityManager.trim(text)
    if text == "" then
        return ""
    end

    local lowered = text:lower()
    if lowered:find("^assalomu%s+alaykum,%s*", 1) == 1 or
       lowered:find("^assalom%s+alekum,%s*", 1) == 1 then
        return text
    end

    return "Assalomu Alaykum, " .. text
end

function ReportCatchManager.sendPopupReply()
    local report = ReportCatchManager.currentReport
    if not report then
        return false
    end

    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("report.reply") then
        PermissionGuard.logBlocked("report.reply", "report.reply")
        return false
    end

    local answerId = tonumber(report.id)
    if not answerId then
        sampAddChatMessage("[Report Catch] Reply uchun report ID topilmadi.", 0xFF6666)
        return false
    end

    local replyBuffer = ReportCatchManager.ensurePopupReplyBuffer()
    local rawText = UtilityManager.bufferToString(replyBuffer) or ""
    local payload = ReportCatchManager.buildPopupReplyPayload(rawText)
    if payload == "" then
        sampAddChatMessage("[Report Catch] Javob matnini yozing.", 0xFF6666)
        return false
    end

    if sendChat(string.format("/ans %d %s", answerId, payload)) == false then
        sampAddChatMessage("[Report Catch] /ans yuborilmadi.", 0xFF6666)
        return false
    end

    LogManager.report(string.format("Popup custom reply sent to report #%d: %s", answerId, payload))
    ReportCatchManager.markAnswered(answerId)
    if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == tonumber(answerId) then
        ReportCatchManager.closePopup()
    end
    return true
end

function ReportCatchManager.closePopup()
    ReportCatchManager.clearWaitingReport()
    ReportCatchManager.popupOpen = false
    ReportCatchManager.currentReport = nil
    ReportCatchManager.resetPopupReplyBuffer()
    ReportCatchManager.animationProgress = 0
    local uiOpen = MainUI and MainUI.window and MainUI.window.open or false
    imgui.Process = uiOpen
    imgui.ShowCursor = uiOpen
    -- Popup yopilishi bilan navbatdagi report darhol chiqadi.
    ReportCatchManager.tryShowNextQueuedReport()
end

function ReportCatchManager.clearQueue()
    ReportCatchManager.reportQueue = {}
    LogManager.system("Report queue cleared")
end

function ReportCatchManager.getQueueCount()
    return #ReportCatchManager.reportQueue
end

function ReportCatchManager.tryShowNextQueuedReport()
    if not ReportCatchManager.enabled then
        return false
    end
    if ReportCatchManager.popupOpen then
        return false
    end
    if #ReportCatchManager.reportQueue == 0 then
        return false
    end

    local nextReport = table.remove(ReportCatchManager.reportQueue, 1)
    if not nextReport then
        return false
    end

    ReportCatchManager.showReport(nextReport)
    return true
end

function ReportCatchManager.resetQuickHotkeyStates()
    local state = ReportCatchManager.quickHotkeyLastState or {}
    for k, _ in pairs(state) do
        state[k] = false
    end
    ReportCatchManager.quickHotkeyLastState = state
end

function ReportCatchManager.isQuickHotkeyPressed(vk, token)
    if not vk then
        return false
    end

    if type(isKeyJustPressed) == "function" then
        local okPressed, pressed = pcall(isKeyJustPressed, vk)
        if okPressed and pressed then
            return true
        end
    end

    local down = false
    if type(isKeyDown) == "function" then
        local okDown, keyDown = pcall(isKeyDown, vk)
        if okDown and keyDown then
            down = true
        end
    end

    local state = ReportCatchManager.quickHotkeyLastState
    local prev = state[token] == true
    state[token] = down
    return down and not prev
end

function ReportCatchManager.canUseQuickHotkeys()
    if not ReportCatchManager.enabled then
        return false
    end
    if sampIsChatInputActive() or sampIsDialogActive() then
        return false
    end
    if MainUI and MainUI.window and MainUI.window.open then
        return false
    end
    if AdminRelayManager and AdminRelayManager.popupOpen then
        return false
    end
    return true
end

function ReportCatchManager.handleQuickHotkeys()
    if not ReportCatchManager.canUseQuickHotkeys() then
        ReportCatchManager.resetQuickHotkeyStates()
        return
    end

    local hk = ReportCatchManager.quickHotkeys or {}

    if ReportCatchManager.isQuickHotkeyPressed(hk.nextOrSkip, "nextOrSkip") then
        if ReportCatchManager.popupOpen then
            ReportCatchManager.closePopup()
        else
            ReportCatchManager.tryShowNextQueuedReport()
        end
    end

    if not ReportCatchManager.popupOpen then
        return
    end

    if ReportCatchManager.isQuickHotkeyPressed(hk.replyTemplate1, "replyTemplate1") then
        local firstTemplate = ReportCatchManager.templates and ReportCatchManager.templates[1]
        if firstTemplate and firstTemplate.id then
            ReportCatchManager.sendReply(firstTemplate.id)
        end
    end

    if ReportCatchManager.isQuickHotkeyPressed(hk.punishments, "punishments") then
        ReportCatchManager.requestPunishmentsReporter()
    end

    if ReportCatchManager.isQuickHotkeyPressed(hk.help, "help") then
        ReportCatchManager.sendHelpRequest()
    end

    if ReportCatchManager.isQuickHotkeyPressed(hk.spectate, "spectate") then
        ReportCatchManager.spectateReporter()
    end

    if ReportCatchManager.isQuickHotkeyPressed(hk.teleport, "teleport") then
        ReportCatchManager.teleportToReporter()
    end
end

function ReportCatchManager.sendReply(templateId)
    local report = ReportCatchManager.currentReport
    if not report then return end

    if PermissionGuard and PermissionGuard.has and not PermissionGuard.has("report.reply") then
        PermissionGuard.logBlocked("report.reply", "report.reply")
        return
    end
    if PermissionGuard and PermissionGuard.canUseTemplate and
       not PermissionGuard.canUseTemplate(templateId) then
        PermissionGuard.logBlocked("report.template:" .. tostring(templateId), "report.reply")
        return
    end

    local template = nil
    for _, t in ipairs(ReportCatchManager.templates) do
        if t.id == templateId then
            template = t
            break
        end
    end

    if template then
        local answeredReportId = report.id
        local cmd = string.format("/ans %d %s", answeredReportId, template.text)
        sendChat(cmd)
        LogManager.report(string.format("Reply sent to report #%d: %s", answeredReportId, template.text))

        if template.id == 1 or template.autoSpReporter then
            local targetId = ReportCatchManager.resolveReporterPlayerId(report)
            if targetId then
                PlayerManager.spectate(targetId)
                LogManager.report(string.format("Auto spectate (/sp) for reporter #%d via template #%d", targetId, template.id))
            else
                sampAddChatMessage("[Report Catch] /sp uchun reporter ID topilmadi.", 0xFF6666)
            end
        end

        -- Close popup right after handling a template reply.
        ReportCatchManager.markAnswered(answeredReportId)
        if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
           tonumber(ReportCatchManager.currentReport.id) == tonumber(answeredReportId) then
            ReportCatchManager.closePopup()
        end
    end
end

function ReportCatchManager.teleportToReporter()
    if not ReportCatchManager.currentReport then return end
    local playerId = ReportCatchManager.currentReport.playerId
    if playerId then
        PlayerManager.teleportTo(playerId)
        LogManager.report(string.format("Teleported to reporter #%d", playerId))
    end
end

function ReportCatchManager.spectateReporter()
    if not ReportCatchManager.currentReport then return end
    local playerId = ReportCatchManager.currentReport.playerId
    if playerId then
        PlayerManager.spectate(playerId)
        LogManager.report(string.format("Spectating reporter #%d", playerId))
    end
end

function ReportCatchManager.getInfoReporter()
    if not ReportCatchManager.currentReport then return end
    local playerId = ReportCatchManager.resolveReporterPlayerId(ReportCatchManager.currentReport)
    if playerId then
        sendChat(string.format("/getinfo %d", playerId))
        LogManager.report(string.format("Requested getinfo for player #%d", playerId))
    end
end

function ReportCatchManager.requestPunishmentsFor(reportId, playerId, nick, sourceTag)
    local resolvedPlayerId = tonumber(playerId)
    local resolvedReportId = tonumber(reportId)
    local resolvedNick = tostring(nick or "")
    local startedAtMs = ReportCatchManager.getNowMs()
    local source = tostring(sourceTag or "unknown")

    if not resolvedPlayerId then
        sampAddChatMessage("[Report Catch] Jazolar: o'yinchi ID topilmadi.", 0xFF6666)
        return false
    end

    ReportCatchManager.pendingPunishmentCheck = {
        reportId = resolvedReportId,
        playerId = resolvedPlayerId,
        answerTargetId = resolvedReportId or resolvedPlayerId,
        nick = resolvedNick,
        startedAtMs = startedAtMs,
        lastRelatedAtMs = 0,
        relatedSeen = false,
        hasPunishment = false,
        details = {},
        contextExpireAtMs = startedAtMs + 3000
    }

    sendChat(string.format("/getinfo %d", resolvedPlayerId))
    sampAddChatMessage(string.format("[Report Catch] Jazolar tekshiruvi boshlandi: player #%d, report #%s",
        resolvedPlayerId, tostring(resolvedReportId or 0)), 0x33CCFF)
    LogManager.report(string.format(
        "Punishment check started (%s) for player #%d (report #%s)",
        source, resolvedPlayerId, tostring(resolvedReportId or 0)))
    return true
end

function ReportCatchManager.requestPunishmentsReporter()
    if not ReportCatchManager.currentReport then return end

    local report = ReportCatchManager.currentReport
    local reportId = report.id
    local playerId = ReportCatchManager.resolveReporterPlayerId(report)
    local nick = report.nick or ""
    ReportCatchManager.requestPunishmentsFor(reportId, playerId, nick, "report_popup")
end

function ReportCatchManager.getNowMs()
    return UtilityManager.getNowMs()
end

function ReportCatchManager.sendHelpRequest()
    local report = ReportCatchManager.currentReport
    if not report then return end

    local playerId = ReportCatchManager.resolveReporterPlayerId(report)
    local answerId = tonumber(report.id)
    if not playerId then
        sampAddChatMessage("[Report Catch] HELP: o'yinchi ID topilmadi.", 0xFF6666)
        return
    end
    if not answerId then
        sampAddChatMessage("[Report Catch] HELP: report ID topilmadi.", 0xFF6666)
        return
    end

    local reportText = (report.text or ""):gsub("{%x%x%x%x%x%x}", "")
    reportText = reportText:gsub("[\r\n]+", " "):gsub("%s%s+", " ")
    reportText = UtilityManager.trim(reportText)
    if reportText == "" then
        reportText = "(report matni yo'q)"
    end

    local helpPayload = string.format("help(%d) %s", playerId, reportText)

    if type(setClipboardText) == "function" then
        pcall(setClipboardText, helpPayload)
    end

    sendChat("/a " .. helpPayload)
    sendChat(string.format("/ans %d Assalom alekum, kuting", answerId))
    LogManager.report(string.format("Help request sent to admin chat for player #%d", playerId))
end

function ReportCatchManager.sendNavigatorPoint()
    local report = ReportCatchManager.currentReport
    if not report then
        sampAddChatMessage("[Report Catch] NAVIGATOR: report topilmadi.", 0xFF6666)
        return
    end

    local answerId = tonumber(report.id)
    if not answerId then
        sampAddChatMessage("[Report Catch] NAVIGATOR: report ID topilmadi.", 0xFF6666)
        return
    end

    if NavigatorManager.startForTarget(answerId, "report_popup") then
        LogManager.report(string.format("Navigator requested from report popup for answer #%d", answerId))
    end
end

function ReportCatchManager.normalizeServerText(text)
    local cleaned = (text or ""):gsub("{%x%x%x%x%x%x}", "")
    return UtilityManager.trim(cleaned)
end

function ReportCatchManager.normalizeGnewsText(text)
    local value = ReportCatchManager.normalizeServerText(text)
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = value:gsub("[`?????]", "'")
    value = value:gsub("%s+", " ")
    return UtilityManager.trim(value)
end

function ReportCatchManager.processGnewsAutoAccept(text)
    local state = ReportCatchManager.gnewsAutoAccept
    if not state or state.enabled == false then
        return false
    end

    local source = ReportCatchManager.normalizeServerText(text)
    if source == "" then
        return false
    end

    local variants = UtilityManager.getMatchVariants(source)
    if #variants == 0 then
        variants = { source }
    end

    local hasStart = false
    local hasInfo = false

    for _, rawVariant in ipairs(variants) do
        local variant = ReportCatchManager.normalizeGnewsText(rawVariant)
        local compact = variant:gsub("['`]", "")

        if variant:find("yangiliklari uchun ariza paydo bo'ldi", 1, true) or
           compact:find("yangiliklari uchun ariza paydo boldi", 1, true) then
            hasStart = true
        end

        if variant:find("qo'shimcha ma'lumot uchun", 1, true) or
           compact:find("qoshimcha malumot uchun", 1, true) then
            hasInfo = true
        end

        if hasStart and hasInfo then
            break
        end
    end

    if not (hasStart and hasInfo) then
        return false
    end

    local nowMs = ReportCatchManager.getNowMs()
    local signature = ReportCatchManager.normalizeGnewsText(source)
    local lastMs = tonumber(state.lastTriggerMs) or 0
    local cooldownMs = math.max(500, tonumber(state.cooldownMs) or 3000)

    if signature == tostring(state.lastSignature or "") and (nowMs - lastMs) < cooldownMs then
        return false
    end

    state.lastTriggerMs = nowMs
    state.lastSignature = signature

    sendChat("/acceptgnews")
    LogManager.admin("Auto GNEWS: /acceptgnews sent")
    return true
end

function ReportCatchManager.isGnewsConfirmDialog(title, text)
    local state = ReportCatchManager.gnewsAutoAccept
    if not state or state.enabled == false then
        return false
    end

    local titleText = ReportCatchManager.normalizeGnewsText(title or "")
    local bodyText = ReportCatchManager.normalizeServerText(text or "")
    if bodyText == "" then
        return false
    end

    local variants = UtilityManager.getMatchVariants(bodyText)
    if #variants == 0 then
        variants = { bodyText }
    end

    local hasPrompt = false
    for _, rawVariant in ipairs(variants) do
        local variant = ReportCatchManager.normalizeGnewsText(rawVariant)
        local compact = variant:gsub("['`]", "")
        if variant:find("tasdiqlash yoki rad etish uchun kalitni kiriting", 1, true) or
           compact:find("tasdiqlash yoki rad etish uchun kalitni kiriting", 1, true) or
           variant:find("tasdiqlash yoki rad etish uchun kalitni kiriting", 1, true) or
           compact:find("tasdiqlash yoki rad etish uchun kalitni kiriting", 1, true) then
            hasPrompt = true
            break
        end
    end

    if not hasPrompt then
        return false
    end

    if titleText == "" then
        return true
    end

    return titleText:find("arizani tasdiqlash", 1, true) ~= nil or
           titleText:find("tasdiqlash", 1, true) ~= nil
end

function ReportCatchManager.extractGnewsDialogCode(text)
    local bodyText = ReportCatchManager.normalizeServerText(text or "")
    if bodyText == "" then
        return nil
    end

    local variants = UtilityManager.getMatchVariants(bodyText)
    if #variants == 0 then
        variants = { bodyText }
    end

    for _, rawVariant in ipairs(variants) do
        local variant = ReportCatchManager.normalizeGnewsText(rawVariant)
        local code = variant:match("kalitni%s+kirit[iy]ng:?%s*(%d+)")
        if code and code ~= "" then
            return code
        end
    end

    return nil
end

function ReportCatchManager.processGnewsAutoAcceptDialog(dialogId, style, title, button1, button2, text)
    if not ReportCatchManager.isGnewsConfirmDialog(title, text) then
        return nil
    end

    local code = ReportCatchManager.extractGnewsDialogCode(text)
    if not code or code == "" then
        LogManager.security("Auto GNEWS confirm: dialog found but code not extracted")
        return nil
    end

    local dlgId = tonumber(dialogId)
    if not dlgId then
        return nil
    end

    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(function()
            if type(wait) == "function" then
                wait(0)
            end
            pcall(sampSendDialogResponse, dlgId, 1, 0, tostring(code))
        end)
    else
        pcall(sampSendDialogResponse, dlgId, 1, 0, tostring(code))
    end

    LogManager.admin(string.format("Auto GNEWS confirm: dialog=%d code=%s", dlgId, tostring(code)))
    return false
end

function ReportCatchManager.stripTimestampPrefix(text)
    local value = tostring(text or "")
    value = value:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
    return UtilityManager.trim(value)
end

function ReportCatchManager.getPunishmentLineVariants(text)
    local variants = UtilityManager.getMatchVariants(text or "")
    if #variants == 0 then
        table.insert(variants, tostring(text or ""))
    end
    return variants
end

function ReportCatchManager.isAdminNoisePunishmentLine(cleanText)
    local line = ReportCatchManager.stripTimestampPrefix(cleanText)
    if line == "" then
        return false
    end

    local textVariants = ReportCatchManager.getPunishmentLineVariants(line)
    local noiseKeywords = {
        "<adm>", "ga javob berdi", "ga javob berdi:", "???????", "????????", "???????:",
        "administrator", "?????????????", "administratori"
    }
    if ReportCatchManager.containsKeywordInVariants(textVariants, noiseKeywords) then
        return true
    end

    for _, value in ipairs(textVariants) do
        local source = tostring(value or "")
        if source:match("^%s*%[a%]") or source:match("^%s*%<adm%>") then
            return true
        end
        if source:match("^[%w_]+%[%d+%]%s*:") then
            return true
        end
    end

    return false
end

function ReportCatchManager.isGetinfoContextLine(cleanText, pending)
    local line = ReportCatchManager.stripTimestampPrefix(cleanText)
    if line == "" then
        return false
    end

    local variants = ReportCatchManager.getPunishmentLineVariants(line)
    local contextKeywords = {
        "hisob qaytnomasi", "hisob qaydnomasi", "tahallus",
        "faol o'yinchi penaltilari", "faol oyinchi penaltilari",
        "penalti", "account", "akkaunt", "id:"
    }

    if ReportCatchManager.containsKeywordInVariants(variants, contextKeywords) then
        return true
    end

    if pending then
        local playerId = tostring(pending.playerId or "")
        if playerId ~= "" then
            for _, value in ipairs(variants) do
                local source = tostring(value or "")
                if source:find("[" .. playerId .. "]", 1, true) then
                    return true
                end
                if source:match("[Ii][Dd]%s*[:=]?%s*" .. playerId) then
                    return true
                end
            end
        end

        local nick = UtilityManager.trim(tostring(pending.nick or ""))
        if nick ~= "" then
            local nickVariants = ReportCatchManager.getPunishmentLineVariants(nick)
            for _, value in ipairs(variants) do
                local source = tostring(value or "")
                for _, nickValue in ipairs(nickVariants) do
                    local nickSource = tostring(nickValue or "")
                    if nickSource ~= "" and source:find(nickSource, 1, true) then
                        return true
                    end
                end
            end
        end
    end

    return false
end

function ReportCatchManager.expandKeywordVariants(keywords)
    local expanded = {}
    local seen = {}

    for _, rawKeyword in ipairs(keywords or {}) do
        local keyword = UtilityManager.trim(tostring(rawKeyword or ""))
        if keyword ~= "" then
            local keywordVariants = ReportCatchManager.getPunishmentLineVariants(keyword)
            for _, value in ipairs(keywordVariants) do
                local source = UtilityManager.trim(tostring(value or ""))
                if source ~= "" then
                    local candidates = {
                        source,
                        source:lower(),
                        UtilityManager.casefoldUtf8Cyrillic(source),
                        UtilityManager.casefoldCp1251Cyrillic(source)
                    }
                    for _, candidate in ipairs(candidates) do
                        local prepared = UtilityManager.trim(tostring(candidate or ""))
                        if prepared ~= "" and not seen[prepared] then
                            seen[prepared] = true
                            table.insert(expanded, prepared)
                        end
                    end
                end
            end
        end
    end

    return expanded
end

function ReportCatchManager.containsKeywordInVariants(variants, keywords)
    local preparedKeywords = ReportCatchManager.expandKeywordVariants(keywords)
    if #preparedKeywords == 0 then
        return false
    end

    for _, value in ipairs(variants or {}) do
        local source = tostring(value or "")
        local candidates = {
            source:lower(),
            UtilityManager.casefoldUtf8Cyrillic(source),
            UtilityManager.casefoldCp1251Cyrillic(source)
        }
        for _, candidate in ipairs(candidates) do
            for _, keyword in ipairs(preparedKeywords) do
                if candidate:find(keyword, 1, true) then
                    return true
                end
            end
        end
    end
    return false
end

function ReportCatchManager.extractNumberNearKeyword(line, keyword)
    local source = tostring(line or "")
    local key = tostring(keyword or "")
    if source == "" or key == "" then
        return nil
    end

    local keyVariants = ReportCatchManager.expandKeywordVariants({ key })
    if #keyVariants == 0 then
        keyVariants = { key }
    end

    for _, keyVariant in ipairs(keyVariants) do
        local escapedKey = tostring(keyVariant):gsub("([%%%^%$%(%)%.%[%]%*%+%-%?])", "%%%1")
        local patterns = {
            escapedKey .. "%s*[:=|%-]*%s*(-?%d+)",
            escapedKey .. "[^%d%-]+(-?%d+)",
            "(-?%d+)%s*[/|,%-]%s*" .. escapedKey,
            "(-?%d+)%s+" .. escapedKey
        }

        for _, pattern in ipairs(patterns) do
            for raw in source:gmatch(pattern) do
                local value = tonumber(raw)
                if value ~= nil then
                    return value
                end
            end
        end
    end

    return nil
end

function ReportCatchManager.isRelatedPunishmentLine(cleanText, pending)
    local line = ReportCatchManager.stripTimestampPrefix(cleanText)
    if line == "" then
        return false
    end

    if ReportCatchManager.isAdminNoisePunishmentLine(line) then
        return false
    end

    local textVariants = ReportCatchManager.getPunishmentLineVariants(line)
    local relatedKeywords = {
        "hisob qaytnomasi", "hisob qaydnomasi", "akk raqam", "akkaunt", "account", "getinfo",
        "jazo", "jazo", "naqaz", "nakaz", "?????", "???????",
        "demorgan", "ban", "tempban", "???",
        "warn", "varn", "????", "ogohl", "??????????",
        "jail", "qamoq", "qamok", "???", "prison",
        "mute", "???", "rmute", "runmute", "chatban", "voiceban",
        "yo'q", "yoq", "mavjud emas", "none", "???", "????", "????????", "?? ???????"
    }

    return ReportCatchManager.containsKeywordInVariants(textVariants, relatedKeywords)
end

function ReportCatchManager.sanitizePunishmentDetail(detail, pending)
    local text = detail or ""
    text = text:gsub("{%x%x%x%x%x%x}", "")

    if pending.nick and pending.nick ~= "" then
        text = text:gsub(pending.nick, "")
    end

    local playerId = tostring(pending.playerId or "")
    if playerId ~= "" then
        text = text:gsub("%[" .. playerId .. "%]", "")
        text = text:gsub("[Ii][Dd]%s*[:=]?%s*" .. playerId, "")
    end

    text = text:gsub("[Hh][Ii][Ss][Oo][Bb]%s+[Qq][Aa][Yy][Tt][Nn][Oo][Mm][Aa][Ss][Ii]", "")
    text = text:gsub("[Hh][Ii][Ss][Oo][Bb]%s+[Qq][Aa][Yy][Dd][Nn][Oo][Mm][Aa][Ss][Ii]", "")
    text = text:gsub("[Aa][Kk][Kk][Aa]?[Uu]?[Nn]?[Tt]?%s*[Rr]?[Aa]?[Qq]?[Aa]?[Mm]?[Ii]?%s*[:=]?%s*[%w_%-]+", "")
    text = text:gsub("[Aa][Cc][Cc][Oo][Uu][Nn][Tt]%s*[:=]?%s*[%w_%-]+", "")
    text = text:gsub("^%s*[-,:;|]+", "")
    text = text:gsub("[-,:;|]+%s*$", "")
    text = text:gsub("%s%s+", " ")

    return UtilityManager.trim(text)
end

function ReportCatchManager.extractPunishmentFromLine(cleanText, pending)
    local line = ReportCatchManager.stripTimestampPrefix(cleanText)
    local variants = ReportCatchManager.getPunishmentLineVariants(line)
    local directLineKeywords = {
        "jail", "warn", "mute", "rmute", "runmute",
        "qamoq", "qamok", "ogohl",
        "???", "????", "???", "??????????"
    }
    local punishmentKeywords = {
        "jazo", "naqaz", "nakaz", "?????", "???????",
        "ban", "tempban", "???", "demorgan",
        "warn", "varn", "????", "ogohl", "??????????",
        "jail", "qamoq", "qamok", "???", "prison",
        "mute", "mut", "???", "rmute", "runmute", "chatban", "voiceban"
    }
    local noPunishmentKeywords = {
        "yo'q", "yoq", "mavjud emas", "none", "???", "????", "????????", "?? ???????"
    }

    -- User requirement: if /getinfo line contains jail/warn/mute anywhere, send that full line.
    if ReportCatchManager.containsKeywordInVariants(variants, directLineKeywords) then
        local fullLine = UtilityManager.trim(line)
        if fullLine ~= "" then
            return fullLine, true
        end
    end

    local hasKeyword = ReportCatchManager.containsKeywordInVariants(variants, punishmentKeywords)
    if not hasKeyword then
        return nil, false
    end

    local numericKeywordTokens = {
        "jazo", "nakaz", "?????", "???????",
        "ban", "tempban", "???", "demorgan",
        "warn", "varn", "????", "ogohl", "??????????",
        "jail", "qamoq", "qamok", "???", "prison",
        "mute", "???", "rmute", "runmute", "chatban", "voiceban"
    }

    local foundNumber = false
    local hasNonZero = false
    for _, source in ipairs(variants) do
        local sourceText = tostring(source or "")
        local scanCandidates = {
            sourceText,
            UtilityManager.casefoldUtf8Cyrillic(sourceText),
            UtilityManager.casefoldCp1251Cyrillic(sourceText)
        }

        for _, line in ipairs(scanCandidates) do
            for _, token in ipairs(numericKeywordTokens) do
                local value = ReportCatchManager.extractNumberNearKeyword(line, token)
                if value ~= nil then
                    foundNumber = true
                    if value > 0 then
                        hasNonZero = true
                        break
                    end
                end
            end
            if hasNonZero then
                break
            end
        end
        if hasNonZero then
            break
        end
    end

    if not hasNonZero then
        local hasNoPunishmentText = ReportCatchManager.containsKeywordInVariants(variants, noPunishmentKeywords)
        if foundNumber or hasNoPunishmentText then
            return nil, false
        end
    end

    -- User requirement: if warn/jail exists, send that line text (cleaned from nick/id/account).
    local detailText = ReportCatchManager.sanitizePunishmentDetail(line, pending)
    if detailText == "" then
        detailText = UtilityManager.trim(line)
    end

    if detailText == "" then
        return nil, false
    end

    return detailText, true
end

function ReportCatchManager.addPunishmentDetail(pending, detailText)
    local text = UtilityManager.trim(detailText or "")
    if text == "" then return end

    for _, existing in ipairs(pending.details) do
        if existing == text then
            return
        end
    end

    table.insert(pending.details, text)
end

function ReportCatchManager.processPunishmentInfoMessage(text)
    local pending = ReportCatchManager.pendingPunishmentCheck
    if not pending then
        return false
    end

    local cleanText = ReportCatchManager.normalizeServerText(text)
    if cleanText == "" then
        return false
    end

    if ReportCatchManager.isAdminNoisePunishmentLine(cleanText) then
        return false
    end

    local nowMs = ReportCatchManager.getNowMs()
    if ReportCatchManager.isGetinfoContextLine(cleanText, pending) then
        pending.relatedSeen = true
        pending.lastRelatedAtMs = nowMs
        pending.contextExpireAtMs = math.max(tonumber(pending.contextExpireAtMs) or 0, nowMs + 3500)
    end

    local contextExpireAtMs = tonumber(pending.contextExpireAtMs) or 0
    if nowMs > contextExpireAtMs then
        return false
    end

    if not ReportCatchManager.isRelatedPunishmentLine(cleanText, pending) then
        return false
    end

    pending.relatedSeen = true
    pending.lastRelatedAtMs = nowMs

    local detailText, isNonZero = ReportCatchManager.extractPunishmentFromLine(cleanText, pending)
    if detailText and isNonZero then
        ReportCatchManager.addPunishmentDetail(pending, detailText)
    end
    if isNonZero then
        pending.hasPunishment = true
    end

    return true
end

function ReportCatchManager.processPunishmentDialogTextBlock(rawText)
    local pending = ReportCatchManager.pendingPunishmentCheck
    if not pending then
        return false
    end

    local text = tostring(rawText or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    if UtilityManager.trim(text) == "" then
        return false
    end

    local nowMs = ReportCatchManager.getNowMs()
    local lines = UtilityManager.splitString(text, "\n")
    local processedAny = false

    for _, rawLine in ipairs(lines) do
        local cleanLine = ReportCatchManager.normalizeServerText(rawLine)
        if cleanLine ~= "" then
            if not ReportCatchManager.isAdminNoisePunishmentLine(cleanLine) then
                if ReportCatchManager.isGetinfoContextLine(cleanLine, pending) then
                    pending.relatedSeen = true
                    pending.lastRelatedAtMs = nowMs
                    pending.contextExpireAtMs = math.max(tonumber(pending.contextExpireAtMs) or 0, nowMs + 3500)
                    processedAny = true
                end

                if ReportCatchManager.isRelatedPunishmentLine(cleanLine, pending) then
                    pending.relatedSeen = true
                    pending.lastRelatedAtMs = nowMs
                    processedAny = true

                    local detailText, isNonZero = ReportCatchManager.extractPunishmentFromLine(cleanLine, pending)
                    if detailText and isNonZero then
                        ReportCatchManager.addPunishmentDetail(pending, detailText)
                    end
                    if isNonZero then
                        pending.hasPunishment = true
                    end
                end
            end
        end
    end

    return processedAny
end

function ReportCatchManager.processPunishmentInfoDialog(dialogId, style, title, button1, button2, text)
    local pending = ReportCatchManager.pendingPunishmentCheck
    if not pending then
        return false
    end

    local titleText = ReportCatchManager.normalizeServerText(title or "")
    local bodyText = tostring(text or "")
    if titleText == "" and UtilityManager.trim(bodyText) == "" then
        return false
    end

    local processedFromTitle = ReportCatchManager.processPunishmentDialogTextBlock(titleText)
    local processedFromBody = ReportCatchManager.processPunishmentDialogTextBlock(bodyText)

    if processedFromTitle or processedFromBody then
        -- Dialog carries full /getinfo snapshot; finalize immediately to avoid fallback "no punishments".
        ReportCatchManager.finalizePunishmentCheck(true)
        return true
    end

    return false
end

function ReportCatchManager.finalizePunishmentCheck(force)
    local pending = ReportCatchManager.pendingPunishmentCheck
    if not pending then
        return
    end

    local nowMs = ReportCatchManager.getNowMs()

    if not force then
        if not pending.relatedSeen then
            return
        end
        local startedAtMs = tonumber(pending.startedAtMs) or nowMs
        local lastRelatedAtMs = tonumber(pending.lastRelatedAtMs) or 0
        if (nowMs - lastRelatedAtMs) < 1200 and (nowMs - startedAtMs) < 8000 then
            return
        end
    end

    if force and not pending.relatedSeen then
        LogManager.report("Punishment check timeout: no getinfo lines detected, sending no-punishment fallback")
    end

    local replyText
    if #pending.details > 0 then
        replyText = "Assalomu alaykum, " .. table.concat(pending.details, "; ")
    else
        replyText = "Assalomu alaykum, sizda jazolar yo'q"
    end

    local answerCommandTargetId = tonumber(pending.answerTargetId) or tonumber(pending.reportId) or tonumber(pending.playerId)
    local resolvedReportId = tonumber(pending.reportId) or answerCommandTargetId
    if not answerCommandTargetId then
        LogManager.security("Punishment reply aborted: invalid report/player ID")
        ReportCatchManager.pendingPunishmentCheck = nil
        return
    end
    sendChat(string.format("/ans %d %s", answerCommandTargetId, replyText))
    LogManager.report(string.format(
        "Punishment reply sent: /ans %d (report #%s): %s",
        answerCommandTargetId,
        tostring(resolvedReportId or 0),
        replyText))
    ReportCatchManager.pendingPunishmentCheck = nil
    ReportCatchManager.markAnswered(resolvedReportId)
    if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
       tonumber(ReportCatchManager.currentReport.id) == tonumber(resolvedReportId) then
        ReportCatchManager.closePopup()
    end
end

function ReportCatchManager.updatePendingPunishmentCheck()
    local pending = ReportCatchManager.pendingPunishmentCheck
    if not pending then
        return
    end

    local nowMs = ReportCatchManager.getNowMs()
    local startedAtMs = tonumber(pending.startedAtMs) or nowMs
    if (nowMs - startedAtMs) >= 8000 then
        ReportCatchManager.finalizePunishmentCheck(true)
        return
    end

    ReportCatchManager.finalizePunishmentCheck(false)
end

function ReportCatchManager.addTemplate(text, shortcut)
    table.insert(ReportCatchManager.templates, {
        id = #ReportCatchManager.templates + 1,
        text = text,
        shortcut = shortcut or ""
    })
    return true
end

function ReportCatchManager.removeTemplate(id)
    for i, template in ipairs(ReportCatchManager.templates) do
        if template.id == id then
            table.remove(ReportCatchManager.templates, i)
            for j = i, #ReportCatchManager.templates do
                ReportCatchManager.templates[j].id = j
            end
            return true
        end
    end
    return false
end

function ReportCatchManager.renderPopup()
    if not ReportCatchManager.popupOpen or not ReportCatchManager.currentReport then
        return
    end

    local report = ReportCatchManager.currentReport
    local settings = ReportCatchManager.settings

    -- Keep enough height so Quick Actions (including JAZOLAR/HELP) remain visible on scaled UI.
    local templateRows = math.max(1, math.ceil(#ReportCatchManager.templates / 4))
    local minPopupHeight = 400 + math.max(0, templateRows - 2) * 34
    if (settings.popupSize.height or 0) < minPopupHeight then
        settings.popupSize.height = minPopupHeight
    end

    if settings.animationEnabled then
        ReportCatchManager.animationProgress = math.min(1, ReportCatchManager.animationProgress + 0.1)
    else
        ReportCatchManager.animationProgress = 1
    end

    local screenX, screenY = getScreenResolution()
    screenX = screenX or 1920
    screenY = screenY or 1080
    local maxX = math.max(0, screenX - settings.popupSize.width - 10)
    local maxY = math.max(0, screenY - settings.popupSize.height - 10)
    settings.popupPos.x = UtilityManager.clamp(settings.popupPos.x or 100, 10, maxX)
    settings.popupPos.y = UtilityManager.clamp(settings.popupPos.y or 100, 10, maxY)

    local startX = screenX
    local targetX = settings.popupPos.x
    local currentX = targetX + (startX - targetX) * (1 - ReportCatchManager.animationProgress)

    imgui.SetNextWindowPos(imgui.ImVec2(currentX, settings.popupPos.y), imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(settings.popupSize.width, settings.popupSize.height), imgui.Cond.Always)

    local flags = imgui.WindowFlags.NoCollapse +
                  imgui.WindowFlags.NoResize +
                  imgui.WindowFlags.NoScrollbar +
                  imgui.WindowFlags.AlwaysAutoResize

    if ReportCatchManager.isDragging then
        flags = flags + imgui.WindowFlags.NoMove
    end

    local windowTitle = string.format("##ReportCatch_%d", report.id)

    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.09, 0.03, 0.04, 0.98))
    imgui.PushStyleColor(imgui.Col.Border, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 1.0))
    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 12)
        imgui.PushStyleVar(imgui.StyleVar.WindowBorderSize, 2)
        styleVarPushed = 2
    end

    local opened = imgui.Begin(windowTitle, nil, flags)
    if opened then
        local headerText = string.format("REPORT #%d", report.id)
        imgui.TextColored(COLORS.DANGER or imgui.ImVec4(0.90, 0.30, 0.30, 1.0), headerText)

        imgui.SameLine(imgui.GetWindowWidth() - 40)
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0, 0, 0, 0))
        if imgui.Button("X##close", imgui.ImVec2(25, 25)) then
            ReportCatchManager.closePopup()
        end
        imgui.PopStyleColor()

        imgui.Separator()

        local reportNickUtf8 = UtilityManager.toUtf8(report.nick)
        local reportTextUtf8 = UtilityManager.toUtf8(report.text)
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), string.format("Player: %s", reportNickUtf8))
        imgui.TextDisabled(string.format("Time: %s", report.formattedTime))
        imgui.TextDisabled(string.format("Queue: %d pending", ReportCatchManager.getQueueCount()))

        imgui.Spacing()
        imgui.TextDisabled(u8"Report matni:")
        local reportScaleApplied = false
        if imgui.SetWindowFontScale then
            imgui.SetWindowFontScale(1.06)
            reportScaleApplied = true
        end
        if imgui.PushTextWrapPos and imgui.PopTextWrapPos then
            imgui.PushTextWrapPos(0)
            imgui.TextWrapped(reportTextUtf8)
            imgui.PopTextWrapPos()
        else
            imgui.TextWrapped(reportTextUtf8)
        end
        if reportScaleApplied and imgui.SetWindowFontScale then
            imgui.SetWindowFontScale(1.0)
        end

        imgui.Spacing()
        local replyBuffer = ReportCatchManager.ensurePopupReplyBuffer()
        if imgui.InputTextMultiline then
            imgui.InputTextMultiline(u8"##report_popup_reply_input", replyBuffer, 384, imgui.ImVec2(-1, 36))
        else
            imgui.InputText(u8"##report_popup_reply_input", replyBuffer, 384)
        end

        local replyPreview = ReportCatchManager.buildPopupReplyPayload(UtilityManager.bufferToString(replyBuffer) or "")
        if replyPreview ~= "" then
            imgui.TextDisabled(u8("Yuboriladi: " .. replyPreview))
        else
            imgui.TextDisabled(u8"Masalan: rp nik")
        end

        if imgui.Button(u8"Yuborish##report_popup_custom_reply_send", imgui.ImVec2(140, 28)) then
            ReportCatchManager.sendPopupReply()
        end

        local mentionedId = ReportCatchManager.resolveMentionedPlayer(report)
        if mentionedId then
            local mentionedNick = UtilityManager.toUtf8(report.mentionedPlayerNick or "")
            local mentionLabel = mentionedNick ~= "" and
                string.format("ID: [%d] %s", mentionedId, mentionedNick) or
                string.format("ID: [%d]", mentionedId)

            imgui.Spacing()
            imgui.PushStyleColor(imgui.Col.Button, COLORS.SECONDARY or imgui.ImVec4(0.56, 0.10, 0.14, 1.0))
            if imgui.Button(mentionLabel .. "##reportMentionedSpec", imgui.ImVec2(0, 30)) then
                ReportCatchManager.spectateMentionedPlayerFromReport()
            end
            imgui.PopStyleColor()

            if imgui.IsItemHovered() then
                imgui.BeginTooltip()
                imgui.Text(u8"Bosilsa: /ans + /sp va tekshiruv tugmalari ochiladi")
                imgui.EndTooltip()
            end
        end

        imgui.Spacing()

        local suggestedTemplateId, suggestedKeyword = ReportCatchManager.ensureSuggestedTemplateForReport(report)
        if ReportCatchManager.settings.templateRoutingEnabled ~= false then
            if imgui.Button("Avto##report_suggested_reply", imgui.ImVec2(120, 26)) then
                ReportCatchManager.sendSuggestedReplyForCurrentReport(1)
            end
            if suggestedTemplateId then
                imgui.SameLine()
                imgui.TextDisabled(string.format("ID: %d", tonumber(suggestedTemplateId) or 1))
                if imgui.IsItemHovered() then
                    imgui.BeginTooltip()
                    imgui.Text(string.format("Kalit: %s", UtilityManager.toUtf8(tostring(suggestedKeyword or ""))))
                    imgui.EndTooltip()
                end
            end
        else
            imgui.TextDisabled("Auto o'chirilgan")
        end

        imgui.Spacing()

        imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Reply Templates:")

        for _, template in ipairs(ReportCatchManager.templates) do
            local btnLabel = string.format("[%d] %s##tpl%d", template.id, template.shortcut, template.id)
            local isSuggested = tonumber(template.id) == tonumber(suggestedTemplateId)

            if isSuggested then
                imgui.PushStyleColor(imgui.Col.Button, COLORS.INFO or imgui.ImVec4(0.86, 0.43, 0.33, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive, COLORS.SECONDARY or imgui.ImVec4(0.56, 0.10, 0.14, 1.0))
            end

            if imgui.Button(btnLabel, imgui.ImVec2(100, 28)) then
                ReportCatchManager.sendReply(template.id)
            end

            if isSuggested then
                imgui.PopStyleColor(3)
            end

            if imgui.IsItemHovered() then
                imgui.BeginTooltip()
                imgui.Text(template.text)
                imgui.EndTooltip()
            end

            if template.id % 4 ~= 0 then
                imgui.SameLine()
            end
        end

        imgui.Spacing()
        imgui.Separator()

        imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Quick Actions:")
        imgui.TextDisabled("F5-next | F6-reply1 | F7-jazo | F8-help | F9-spec | F10-goto")

        local btnSize = imgui.ImVec2(50, 35)

        imgui.PushStyleColor(imgui.Col.Button, COLORS.PRIMARY or imgui.ImVec4(0.74, 0.15, 0.20, 1.0))
        if imgui.Button(u8"GOTO\n\xf0\x9f\x91\xa4##goto", btnSize) then
            ReportCatchManager.teleportToReporter()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"Teleport to reporter (/goto)")
            imgui.EndTooltip()
        end

        imgui.SameLine()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.SECONDARY or imgui.ImVec4(0.56, 0.10, 0.14, 1.0))
        if imgui.Button(u8"SPEC\n\xf0\x9f\x91\x81##spec", btnSize) then
            ReportCatchManager.spectateReporter()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"Spectate reporter (/sp)")
            imgui.EndTooltip()
        end

        imgui.SameLine()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.WARNING or imgui.ImVec4(0.96, 0.73, 0.18, 1.0))
        if imgui.Button(u8"INFO\n\xf0\x9f\x93\x92##info", btnSize) then
            ReportCatchManager.getInfoReporter()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"Get player info (/getinfo)")
            imgui.EndTooltip()
        end

        imgui.Spacing()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.DANGER or imgui.ImVec4(0.92, 0.26, 0.24, 1.0))
        if imgui.Button("JAZOLAR##jazo", imgui.ImVec2(95, 32)) then
            ReportCatchManager.requestPunishmentsReporter()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"Getinfo -> warn/jail ni topib /ans yuborish")
            imgui.EndTooltip()
        end

        imgui.SameLine()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.INFO or imgui.ImVec4(0.86, 0.43, 0.33, 1.0))
        if imgui.Button("HELP##help", imgui.ImVec2(85, 32)) then
            ReportCatchManager.sendHelpRequest()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"/a help(id) + report matnini yuboradi")
            imgui.EndTooltip()
        end

        imgui.SameLine()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.WARNING or imgui.ImVec4(0.96, 0.73, 0.18, 1.0))
        if imgui.Button(u8"EVAKUATOR##report_evacuator", imgui.ImVec2(120, 32)) then
            ReportCatchManager.sendRandomKeywordReplyForReport(report.id, "popup_evakuator")
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"Evakuator javobi yuboriladi")
            imgui.EndTooltip()
        end

        imgui.SameLine()

        imgui.PushStyleColor(imgui.Col.Button, COLORS.SECONDARY or imgui.ImVec4(0.56, 0.10, 0.14, 1.0))
        if imgui.Button("NAVIGATOR##report_nav", imgui.ImVec2(120, 32)) then
            ReportCatchManager.sendNavigatorPoint()
        end
        imgui.PopStyleColor()

        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(u8"/gps ochiladi, tanlangan metka /ans orqali yuboriladi")
            imgui.EndTooltip()
        end

        local queueCount = ReportCatchManager.getQueueCount()
        if queueCount > 0 then
            imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), string.format("Queue: %d", queueCount))
        else
            imgui.TextDisabled("No queue")
        end

        local windowPos = imgui.GetWindowPos()
        if not ReportCatchManager.isDragging then
            settings.popupPos.x = windowPos.x
            settings.popupPos.y = windowPos.y
        end
    end
    imgui.End()

    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    imgui.PopStyleColor(2)
end



end

