            aliases = { "kavkaz", "??????", "??????????", "?????????? ???", "?????????? ??????????" }
        },
        {
            label = "Orexovskaya uyushgan jinoiy guruh",
            aliases = {
                "orexovskaya", "orekhovskaya", "orexov", "orekhov",
                "??????", "??????????", "?????????? ???", "?????????? ??????????"
            }
        }
    }
}

function FuraKillManager.applyLoadProfile()
    if FuraKillManager.enabled then
        FuraKillManager.statsCommandCooldown = FuraKillManager.smoothStatsCommandCooldown
        FuraKillManager.phaseTimeout = FuraKillManager.smoothPhaseTimeout
        FuraKillManager.phaseIdleTimeout = FuraKillManager.smoothPhaseIdleTimeout
        FuraKillManager.maxQueue = FuraKillManager.smoothMaxQueue
        FuraKillManager.profileName = "smooth"
        return
    end

    FuraKillManager.statsCommandCooldown = FuraKillManager.defaultStatsCommandCooldown
    FuraKillManager.phaseTimeout = FuraKillManager.defaultPhaseTimeout
    FuraKillManager.phaseIdleTimeout = FuraKillManager.defaultPhaseIdleTimeout
    FuraKillManager.maxQueue = FuraKillManager.defaultMaxQueue
    FuraKillManager.profileName = "normal"
end

function FuraKillManager.hasPendingWork()
    if FuraKillManager.activeCheck then
        return true
    end

    return type(FuraKillManager.pendingChecks) == "table" and #FuraKillManager.pendingChecks > 0
end

function FuraKillManager.isAfkPauseActive()
    return AFKManager and AFKManager.isAFK == true
end

function FuraKillManager.isMenuDisabled()
    return SettingsManager and SettingsManager.get and SettingsManager.get("furaMenuDisabled") == true
end

function FuraKillManager.logDebug(message)
    if LogManager and LogManager.system then
        LogManager.system("[FURA] " .. tostring(message or ""))
    end
end

function FuraKillManager.isPriorityModeActive()
    if FuraKillManager.isMenuDisabled() or not FuraKillManager.enabled then
        return false
    end

    -- Only switch the global loop into Fura priority mode while an actual
    -- kill verification is queued or running. Keeping the whole system in
    -- priority mode just because the feature is toggled on makes the script
    -- much busier for no real benefit.
    return FuraKillManager.hasPendingWork()
end

function FuraKillManager.initialize()
    FuraKillManager.enabled = SettingsManager.get("furaKillEnabled") == true
    FuraKillManager.applyLoadProfile()
    LogManager.system(string.format("Fura Kill manager initialized (%s)",
        FuraKillManager.enabled and ("enabled/" .. FuraKillManager.profileName) or "disabled"))
end

function FuraKillManager.setEnabled(state)
    if FuraKillManager.isMenuDisabled() then
        return
    end
    FuraKillManager.enabled = state == true
    FuraKillManager.applyLoadProfile()
    SettingsManager.set("furaKillEnabled", FuraKillManager.enabled)
    if LogManager and LogManager.system then
        LogManager.system(string.format("Fura Kill manager mode -> enabled=%s profile=%s",
            tostring(FuraKillManager.enabled), tostring(FuraKillManager.profileName)))
    end

    if not FuraKillManager.enabled then
        FuraKillManager.pendingChecks = {}
        FuraKillManager.activeCheck = nil
        FuraKillManager.playerCache = {}
        FuraKillManager.afkPauseLogged = false
        FuraKillManager.lastStatsCommandAt = 0
        FuraKillManager.lastDeathSignature = ""
        FuraKillManager.lastDeathAt = 0
    end
end

function FuraKillManager.isDialogBusy()
    if type(sampIsDialogActive) ~= "function" then
        return false
    end
    local okDialog, active = pcall(sampIsDialogActive)
    return okDialog and active == true
end

function FuraKillManager.clearData()
    FuraKillManager.kills = {}
    FuraKillManager.killFeed = {}
    FuraKillManager.killerStats = {}
    FuraKillManager.groupKillStats = {}
    FuraKillManager.teamKillStats = {}
    FuraKillManager.playerCache = {}
    FuraKillManager.firstKill = nil
    FuraKillManager.lastKill = nil
    FuraKillManager.pendingChecks = {}
    FuraKillManager.activeCheck = nil
    FuraKillManager.afkPauseLogged = false
    FuraKillManager.lastStatsCommandAt = 0
    FuraKillManager.lastDeathSignature = ""
    FuraKillManager.lastDeathAt = 0
    FuraKillManager.lastExportPath = ""
    FuraKillManager.nextFeedId = 1
end

function FuraKillManager.normalizeLine(text)
    local clean = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
    clean = clean:gsub("[\r\n]+", " "):gsub("%s%s+", " ")
    return UtilityManager.trim(clean)
end

function FuraKillManager.playerLabel(id, nick)
    local pid = tonumber(id) or -1
    local name = UtilityManager.trim(tostring(nick or "Unknown"))
    if name == "" then
        name = "Unknown"
    end
    return string.format("[%d] %s", pid, name)
end

function FuraKillManager.resolveNickById(id)
    local pid = tonumber(id)
    if not pid then
        return "Unknown"
    end

    local okConnected, connected = pcall(sampIsPlayerConnected, pid)
    if okConnected and connected then
        local okNick, nick = pcall(sampGetPlayerNickname, pid)
        if okNick and nick and nick ~= "" then
            return nick
        end
    end

    return string.format("ID_%d", pid)
end

function FuraKillManager.isPlayerCacheFresh(playerId)
    local cache = FuraKillManager.playerCache[tonumber(playerId) or 0]
    if type(cache) ~= "table" then
        return false
    end
    local updatedAt = tonumber(cache.updatedAt or 0) or 0
    return updatedAt > 0 and (os.time() - updatedAt) < math.max(30, tonumber(FuraKillManager.cacheTtl) or 180)
end

function FuraKillManager.applyCachedSideState(side)
    if type(side) ~= "table" then
        return false
    end

    local playerId = tonumber(side.id) or 0
    if playerId <= 0 or not FuraKillManager.isPlayerCacheFresh(playerId) then
        return false
    end

    local cache = FuraKillManager.playerCache[playerId]
    side.nick = UtilityManager.trim(tostring(cache.nick or side.nick or "Unknown"))
    side.isCriminal = cache.isCriminal == true
    side.groupName = UtilityManager.trim(tostring(cache.groupName or ""))
    side.resolved = true
    side.cached = true
    return true
end

function FuraKillManager.storeSideCache(side)
    if type(side) ~= "table" or side.resolved ~= true then
        return
    end

    local playerId = tonumber(side.id) or 0
    if playerId <= 0 then
        return
    end

    FuraKillManager.playerCache[playerId] = {
        id = playerId,
        nick = UtilityManager.trim(tostring(side.nick or "")),
        isCriminal = side.isCriminal == true,
        groupName = UtilityManager.trim(tostring(side.groupName or "")),
        updatedAt = os.time()
    }
end

function FuraKillManager.sideNeedsLookup(side)
    return type(side) == "table" and side.resolved ~= true
end

function FuraKillManager.appendKillFeedRecord(killer, victim)
    local record = {
        entryId = FuraKillManager.nextFeedId,
        killerId = tonumber((killer or {}).id) or -1,
        killerNick = tostring((killer or {}).nick or "Unknown"),
        killerGroup = UtilityManager.trim(tostring((killer or {}).groupName or "")),
        victimId = tonumber((victim or {}).id) or -1,
        victimNick = tostring((victim or {}).nick or "Unknown"),
        victimGroup = UtilityManager.trim(tostring((victim or {}).groupName or "")),
        isTeamKill = false,
        time = os.time(),
        formattedTime = os.date("%Y-%m-%d %H:%M:%S"),
        verificationState = "pending"
    }

    FuraKillManager.nextFeedId = FuraKillManager.nextFeedId + 1
    table.insert(FuraKillManager.killFeed, record)
    if #FuraKillManager.killFeed > FuraKillManager.maxKillLog then
        table.remove(FuraKillManager.killFeed, 1)
    end

    return record
end

function FuraKillManager.findKillFeedRecord(entryId)
    local targetId = tonumber(entryId)
    if not targetId then
        return nil
    end

    for i = #FuraKillManager.killFeed, 1, -1 do
        local record = FuraKillManager.killFeed[i]
        if tonumber(record.entryId) == targetId then
            return record
        end
    end

    return nil
end

function FuraKillManager.updateFeedRecordFromCheck(check, verificationState)
    if not check then
        return
    end

    local record = FuraKillManager.findKillFeedRecord(check.logEntryId)
    if not record then
        return
    end

    record.killerNick = tostring((check.killer or {}).nick or record.killerNick or "Unknown")
    record.victimNick = tostring((check.victim or {}).nick or record.victimNick or "Unknown")
    record.killerGroup = FuraKillManager.normalizeGroupLabel((check.killer or {}).groupName or "")
    record.victimGroup = FuraKillManager.normalizeGroupLabel((check.victim or {}).groupName or "")
    record.isTeamKill = FuraKillManager.areSameGroup(record.killerGroup, record.victimGroup) and
                        FuraKillManager.isSpecificCriminalGroup(record.killerGroup) and
                        FuraKillManager.isSpecificCriminalGroup(record.victimGroup)
    record.verificationState = tostring(verificationState or record.verificationState or "pending")
end

function FuraKillManager.queueKillCheck(killerId, victimId)
    if FuraKillManager.isMenuDisabled() or not FuraKillManager.enabled then
        return
    end

    local kid = tonumber(killerId)
    local vid = tonumber(victimId)
    if not kid or not vid then
        return
    end
    if kid == 65535 or vid == 65535 or kid == vid then
        return
    end

    local now = os.clock()
    local signature = string.format("%d>%d", kid, vid)
    if FuraKillManager.lastDeathSignature == signature and (now - FuraKillManager.lastDeathAt) < 0.4 then
        return
    end
    FuraKillManager.lastDeathSignature = signature
    FuraKillManager.lastDeathAt = now

    local check = {
        killer = {
            id = kid,
            nick = FuraKillManager.resolveNickById(kid),
            isCriminal = false,
            groupName = "",
            resolved = false,
            cached = false,
            lookupAttempts = 0
        },
        victim = {
            id = vid,
            nick = FuraKillManager.resolveNickById(vid),
            isCriminal = false,
            groupName = "",
            resolved = false,
            cached = false,
            lookupAttempts = 0
        },
        createdAt = now,
        phase = nil,
        pendingPhase = nil,
        phaseStartedAt = 0,
        phaseLastRelatedAt = 0,
        phaseCaptureStarted = false,
        phaseCaptureLastAt = 0,
        phaseRelatedSeen = false,
        phaseDetectedCriminal = false,
        phaseDetectedGroup = "",
        phaseGroupHits = {},
        phaseCapturedLines = {}
    }

    FuraKillManager.applyCachedSideState(check.killer)
    FuraKillManager.applyCachedSideState(check.victim)

    local feedRecord = FuraKillManager.appendKillFeedRecord(check.killer, check.victim)
    check.logEntryId = feedRecord.entryId

    table.insert(FuraKillManager.pendingChecks, check)
    if #FuraKillManager.pendingChecks > FuraKillManager.maxQueue then
        table.remove(FuraKillManager.pendingChecks, 1)
    end

    FuraKillManager.logDebug(string.format(
        "queued kill check killer=%s victim=%s pending=%d",
        FuraKillManager.playerLabel(check.killer.id, check.killer.nick),
        FuraKillManager.playerLabel(check.victim.id, check.victim.nick),
        #FuraKillManager.pendingChecks
    ))
end

function FuraKillManager.onPlayerDeathNotification(killerId, killedId, reason)
    if FuraKillManager.isMenuDisabled() then
        return
    end
    FuraKillManager.queueKillCheck(killerId, killedId)
end

function FuraKillManager.beginPhase(phaseName)
    local active = FuraKillManager.activeCheck
    if not active then
        return
    end

    local side = active[phaseName]
    if not side or not side.id then
        return
    end

    if FuraKillManager.isDialogBusy() then
        active.pendingPhase = tostring(phaseName or "")
        return
    end

    active.phase = phaseName
    active.pendingPhase = nil
    active.phaseStartedAt = os.clock()
    active.phaseLastRelatedAt = active.phaseStartedAt
    active.phaseCaptureStarted = false
    active.phaseCaptureLastAt = active.phaseStartedAt
    active.phaseRelatedSeen = false
    active.phaseDetectedCriminal = false
    active.phaseDetectedGroup = ""
    active.phaseGroupHits = {}
    active.phaseCapturedLines = {}

    FuraKillManager.logDebug(string.format(
        "begin phase=%s target=%s",
        tostring(phaseName),
        FuraKillManager.playerLabel(side.id, side.nick)
    ))
    sendChat(string.format("/stats %d", side.id))
    FuraKillManager.lastStatsCommandAt = os.clock()
end

function FuraKillManager.looksLikeStatsLine(line)
    local clean = FuraKillManager.stripTimestampPrefix(FuraKillManager.normalizeLine(line))
    if clean == "" then
        return false
    end

    local folded = FuraKillManager.foldText(clean)
    if folded == "" then
        return false
    end

    local keywords = {
        "hisob qaydnomasi",
        "hisob qaytnomasi",
        "statistika",
        "statistics",
        "player stats",
        "account",
        "akkaunt",
        "tahallus",
        -- bug fix: "id:" alone suppressed /id command chat output.
        -- only treat as stats line if id: appears with other stats context keywords.
        -- handled separately below via pattern check instead of flat keyword.
        "organization",
        "organizatsiya",
        "fraksiya",
        "playtime",
        "played",
        "hours",
        "online:",
        "level:",
        "daraja:"
    }

    for _, keyword in ipairs(keywords) do
        if folded:find(FuraKillManager.foldText(keyword), 1, true) then
            return true
        end
    end

    -- bug fix: "id:" check — only suppress when combined with real stats context.
    if folded:find("id:", 1, true) and (
        folded:find("nick", 1, true) or folded:find("level", 1, true) or
        folded:find("daraja", 1, true) or folded:find("playtime", 1, true) or
        folded:find("statistika", 1, true) or folded:find("akkaunt", 1, true)
    ) then
        return true
    end

    return FuraKillManager.isCriminalGroupLine(clean)
end

function FuraKillManager.foldText(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value:lower()
end

function FuraKillManager.stripTimestampPrefix(text)
    local value = tostring(text or "")
    value = value:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
    return UtilityManager.trim(value)
end

function FuraKillManager.isNoiseLine(line, foldedLine)
    local source = tostring(line or "")
    local lowered = foldedLine or FuraKillManager.foldText(source)
    if lowered == "" then
        return true
    end

    if lowered:find("<adm>", 1, true) or lowered:find("[a]", 1, true) then
        return true
    end
    if lowered:find("ga javob berdi", 1, true) or lowered:find("???????", 1, true) then
        return true
    end
    if lowered:find("uchun administrator", 1, true) or lowered:find("administrator", 1, true) then
        return true
    end
    if lowered:find("?????????? ??????????", 1, true) or lowered:find("?????????? ?????????", 1, true) then
        return true
    end
    if source:match("^%s*%[A%]") or source:match("^%s*<ADM>") then
        return true
    end
    if source:match("^[%w_]+%[%d+%]%s*:") then
        return true
    end

    return false
end

function FuraKillManager.detectCriminalMarker(foldedLine)
    local text = FuraKillManager.foldText(foldedLine)
    if text == "" then
        return false
    end
    if text:find("uyushgan jinoiy guruh", 1, true) then
        return true
    end
    if text:find("jinoiy guruh", 1, true) then
        return true
    end
    if text:find("jinoiy", 1, true) and text:find("guruh", 1, true) then
        return true
    end
    if text:find("???", 1, true) then
        return true
    end
    if text:find("???????????", 1, true) and (text:find("???????", 1, true) or text:find("?????", 1, true)) then
        return true
    end
    if text:find("???????", 1, true) and text:find("?????", 1, true) then
        return true
    end
    return false
end

function FuraKillManager.detectKnownGroupLabel(foldedLine)
    local text = FuraKillManager.foldText(foldedLine)
    if text == "" then
        return nil
    end

    for _, group in ipairs(FuraKillManager.criminalGroups or {}) do
        local tokens = { group.label }
        for _, alias in ipairs(group.aliases or {}) do
            table.insert(tokens, alias)
        end

        for _, token in ipairs(tokens) do
            local foldedToken = FuraKillManager.foldText(token)
            if foldedToken ~= "" and text:find(foldedToken, 1, true) then
                return group.label
            end
        end
    end

    return nil
end

function FuraKillManager.pickTopGroupFromHits(groupHits)
    local picked = nil
    local pickedCount = -1
    for groupName, count in pairs(groupHits or {}) do
        local total = tonumber(count) or 0
        if total > pickedCount then
            picked = tostring(groupName)
            pickedCount = total
        end
    end
    return picked
end

function FuraKillManager.normalizeGroupLabel(groupName)
    local source = UtilityManager.trim(tostring(groupName or ""))
    if source == "" then
        return ""
    end

    local folded = FuraKillManager.foldText(source)
    local detected = FuraKillManager.detectKnownGroupLabel(folded)
    if detected and detected ~= "" then
        return detected
    end

    return source
end

function FuraKillManager.detectCriminalGroupName(line)
    local folded = FuraKillManager.foldText(line or "")
    if folded == "" then
        return nil
    end

    local known = FuraKillManager.detectKnownGroupLabel(folded)
    local marker = FuraKillManager.detectCriminalMarker(folded)
    if known then
        return known
    end
    if marker then
        return "Uyushgan jinoiy guruh"
    end
    return nil
end

function FuraKillManager.isCriminalGroupLine(line)
    return FuraKillManager.detectCriminalGroupName(line) ~= nil
end

function FuraKillManager.isPhaseLineRelated(active, line, foldedLine)
    local phase = active and active.phase
    local side = phase and active[phase] or nil
    if not side then
        return false
    end

    local idText = tostring(side.id)
    if line:find("[" .. idText .. "]", 1, true) then
        return true
    end

    if foldedLine:match("id%s*[:=]?%s*" .. idText) then
        return true
    end

    local nickFolded = FuraKillManager.foldText(side.nick or "")
    if nickFolded ~= "" and foldedLine:find(nickFolded, 1, true) then
        return true
    end

    if foldedLine:find("hisob qaydnomasi", 1, true) and
       (foldedLine:find(idText, 1, true) or (nickFolded ~= "" and foldedLine:find(nickFolded, 1, true))) then
        return true
    end

    return false
end

function FuraKillManager.capturePhaseLine(active, line)
    local source = UtilityManager.trim(tostring(line or ""))
    if source == "" then
        return
    end

    active.phaseCapturedLines = active.phaseCapturedLines or {}
    for _, existing in ipairs(active.phaseCapturedLines) do
        if existing == source then
            return
        end
    end

    table.insert(active.phaseCapturedLines, source)
    if #active.phaseCapturedLines > 50 then
        table.remove(active.phaseCapturedLines, 1)
    end
end

function FuraKillManager.updatePhaseFromLine(active, line, forceContext)
    if not active then
        return false
    end

    local cleanLine = FuraKillManager.stripTimestampPrefix(FuraKillManager.normalizeLine(line))
    if cleanLine == "" then
        return false
    end

    local folded = FuraKillManager.foldText(cleanLine)
    if FuraKillManager.isNoiseLine(cleanLine, folded) then
        return false
    end

    local related = FuraKillManager.isPhaseLineRelated(active, cleanLine, folded)
    local contextAllowed = related or forceContext == true or active.phaseRelatedSeen == true
    local hasMarker = FuraKillManager.detectCriminalMarker(folded)
    local knownGroup = FuraKillManager.detectKnownGroupLabel(folded)

    if related or (contextAllowed and (hasMarker or knownGroup)) then
        active.phaseRelatedSeen = true
        active.phaseLastRelatedAt = os.clock()
        FuraKillManager.capturePhaseLine(active, cleanLine)
        active.phaseCaptureStarted = true
        active.phaseCaptureLastAt = os.clock()
    elseif contextAllowed then
        active.phaseLastRelatedAt = os.clock()
        FuraKillManager.capturePhaseLine(active, cleanLine)
        active.phaseCaptureStarted = true
        active.phaseCaptureLastAt = os.clock()
    end

    if contextAllowed and hasMarker then
        active.phaseDetectedCriminal = true
    end

    if contextAllowed and knownGroup then
        active.phaseDetectedCriminal = true
        active.phaseDetectedGroup = knownGroup
        active.phaseGroupHits = active.phaseGroupHits or {}
        active.phaseGroupHits[knownGroup] = (active.phaseGroupHits[knownGroup] or 0) + 1
    end

    return related or (contextAllowed and (hasMarker or knownGroup))
end

function FuraKillManager.processStatsTextBlock(rawText, forceBlockContext)
    if FuraKillManager.isMenuDisabled() or not FuraKillManager.enabled then
        return false
    end

    local active = FuraKillManager.activeCheck
    if not active then
        return false
    end

    local text = tostring(rawText or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    if UtilityManager.trim(text) == "" then
        return false
    end

    local processedAny = false
    local lines = UtilityManager.splitString(text, "\n")
    local blockRelated = forceBlockContext == true
    local blockStatsLike = forceBlockContext == true
    -- bug fix: 1.15s was too short on laggy servers — stats lines arrive late and get skipped.
    local continueWindow = active.phaseCaptureStarted == true and
        ((os.clock() - tonumber(active.phaseCaptureLastAt or active.phaseStartedAt or 0)) <= 2.0)

    for _, rawLine in ipairs(lines) do
        local cleanLine = FuraKillManager.stripTimestampPrefix(FuraKillManager.normalizeLine(rawLine))
        if cleanLine ~= "" then
            local folded = FuraKillManager.foldText(cleanLine)
            if not FuraKillManager.isNoiseLine(cleanLine, folded) and
               FuraKillManager.isPhaseLineRelated(active, cleanLine, folded) then
                blockRelated = true
            end
            if FuraKillManager.looksLikeStatsLine(cleanLine) then
                blockStatsLike = true
            end
        end
    end

    local useContext = blockRelated or blockStatsLike or continueWindow

    for _, rawLine in ipairs(lines) do
        if FuraKillManager.updatePhaseFromLine(active, rawLine, useContext) then
            processedAny = true
        end
    end

    return processedAny or useContext
end

function FuraKillManager.processStatsMessage(text)
    return FuraKillManager.processStatsTextBlock(text, false)
end

function FuraKillManager.isStatsDialog(title, text)
    local variants = UtilityManager.getMatchVariants(title or "")
    local textVariants = UtilityManager.getMatchVariants(text or "")

    for _, value in ipairs(textVariants) do
        variants[#variants + 1] = value
    end

    if #variants == 0 then
        variants[1] = tostring(title or "")
        variants[2] = tostring(text or "")
    end

    local keywords = {
        "hisob qaytnomasi",
        "hisob qaydnomasi",
        "statistika",
        "statistics",
        "player stats",
        "account",
        "akkaunt",
        "tahallus",
        "id:"
    }

    for _, value in ipairs(variants) do
        local folded = FuraKillManager.foldText(value)
        if folded ~= "" then
            for _, keyword in ipairs(keywords) do
                if folded:find(FuraKillManager.foldText(keyword), 1, true) then
                    return true
                end
            end
        end
    end

    return false
end

function FuraKillManager.processStatsDialog(dialogId, style, title, button1, button2, text)
    if FuraKillManager.isMenuDisabled() or not FuraKillManager.enabled or not FuraKillManager.activeCheck then
        return false
    end

    if not FuraKillManager.isStatsDialog(title, text) then
        return false
    end

    local processed = false
    if title and UtilityManager.trim(tostring(title)) ~= "" then
        processed = FuraKillManager.processStatsTextBlock(tostring(title), true) or processed
    end
    processed = FuraKillManager.processStatsTextBlock(tostring(text or ""), true) or processed

    if processed and FuraKillManager.activeCheck then
        -- /stats dialog usually contains the full text block for current phase.
        FuraKillManager.finalizeActiveCheck()
    end

    return processed
end

function FuraKillManager.getTopKiller()
    local top = nil
    for _, entry in pairs(FuraKillManager.killerStats) do
        if entry.kills and entry.kills > 0 then
            if not top or entry.kills > top.kills then
                top = entry
            end
        end
    end
    return top
end

function FuraKillManager.getWinningCriminalGroup()
    -- Winner must always be based on the latest tracked kill record, not top-kill stats.
    local last = FuraKillManager.kills[#FuraKillManager.kills]
    if not last then
        last = FuraKillManager.lastKill
    end
    if not last then
        return "N/A"
    end

    local winner = FuraKillManager.normalizeGroupLabel(last.killerGroup or "")
    if winner == "" then
        winner = "Uyushgan jinoiy guruh"
    end
    return winner
end

function FuraKillManager.getSortedKillerStats()
    local result = {}
    for _, entry in pairs(FuraKillManager.killerStats) do
        if entry.kills and entry.kills > 0 then
            table.insert(result, entry)
        end
    end

    table.sort(result, function(a, b)
        if a.kills == b.kills then
            return tostring(a.nick) < tostring(b.nick)
        end
        return a.kills > b.kills
    end)

    return result
end

function FuraKillManager.areSameGroup(groupA, groupB)
    local a = FuraKillManager.foldText(FuraKillManager.normalizeGroupLabel(groupA))
    local b = FuraKillManager.foldText(FuraKillManager.normalizeGroupLabel(groupB))
    return a ~= "" and b ~= "" and a == b
end

function FuraKillManager.isSpecificCriminalGroup(groupName)
    local normalized = FuraKillManager.normalizeGroupLabel(groupName)
    local folded = FuraKillManager.foldText(normalized)
    if folded == "" then
        return false
    end
    if folded == FuraKillManager.foldText("Uyushgan jinoiy guruh") then
        return false
    end
    return FuraKillManager.detectKnownGroupLabel(folded) ~= nil
end

function FuraKillManager.getSortedGroupStats(sourceStats)
    local result = {}
    for groupName, count in pairs(sourceStats or {}) do
        local total = tonumber(count) or 0
        if total > 0 then
            table.insert(result, {
                group = tostring(groupName),
                count = total
            })
        end
    end

    table.sort(result, function(a, b)
        if a.count == b.count then
            return tostring(a.group) < tostring(b.group)
        end
        return a.count > b.count
    end)

    return result
end

function FuraKillManager.getTeamKillCount()
    local count = 0
    for _, record in ipairs(FuraKillManager.kills) do
        if record.isTeamKill then
            count = count + 1
        end
    end
    return count
end

function FuraKillManager.addKillRecord(killer, victim)
    local killerGroup = UtilityManager.trim(tostring((killer and killer.groupName) or ""))
    local victimGroup = UtilityManager.trim(tostring((victim and victim.groupName) or ""))
    killerGroup = FuraKillManager.normalizeGroupLabel(killerGroup)
    victimGroup = FuraKillManager.normalizeGroupLabel(victimGroup)
    if killerGroup == "" and killer and killer.isCriminal then
        killerGroup = "Uyushgan jinoiy guruh"
    end
    if victimGroup == "" and victim and victim.isCriminal then
        victimGroup = "Uyushgan jinoiy guruh"
    end

    local record = {
        killerId = killer.id,
        killerNick = killer.nick,
        killerGroup = killerGroup,
        victimId = victim.id,
        victimNick = victim.nick,
        victimGroup = victimGroup,
        isTeamKill = FuraKillManager.areSameGroup(killerGroup, victimGroup) and
                     FuraKillManager.isSpecificCriminalGroup(killerGroup) and
                     FuraKillManager.isSpecificCriminalGroup(victimGroup),
        time = os.time(),
        formattedTime = os.date("%Y-%m-%d %H:%M:%S")
    }

    table.insert(FuraKillManager.kills, record)
    if #FuraKillManager.kills > FuraKillManager.maxKillLog then
        table.remove(FuraKillManager.kills, 1)
    end

    local key = tostring(record.killerId)
    if not FuraKillManager.killerStats[key] then
        FuraKillManager.killerStats[key] = {
            id = record.killerId,
            nick = record.killerNick,
            kills = 0
        }
    end

    local entry = FuraKillManager.killerStats[key]
    entry.nick = record.killerNick
    entry.kills = (entry.kills or 0) + 1

    if record.killerGroup ~= "" then
        FuraKillManager.groupKillStats[record.killerGroup] = (FuraKillManager.groupKillStats[record.killerGroup] or 0) + 1
    end
    if record.isTeamKill and record.killerGroup ~= "" then
        FuraKillManager.teamKillStats[record.killerGroup] = (FuraKillManager.teamKillStats[record.killerGroup] or 0) + 1
    end

    if not FuraKillManager.firstKill then
        FuraKillManager.firstKill = record
    end
    FuraKillManager.lastKill = record
end

function FuraKillManager.hasPhaseEvidence(active)
    if not active then
        return false
    end

    if active.phaseRelatedSeen == true or active.phaseDetectedCriminal == true then
        return true
    end
    if UtilityManager.trim(tostring(active.phaseDetectedGroup or "")) ~= "" then
        return true
    end
    if next(active.phaseGroupHits or {}) ~= nil then
        return true
    end
    return #(active.phaseCapturedLines or {}) > 0
end

function FuraKillManager.schedulePhaseRetry(active, phase)
    if not active then
        return
    end

    active.phase = nil
    active.pendingPhase = tostring(phase or "")
    active.phaseStartedAt = 0
    active.phaseLastRelatedAt = os.clock()
    active.phaseCaptureStarted = false
    active.phaseCaptureLastAt = 0
    active.phaseRelatedSeen = false
    active.phaseDetectedCriminal = false
    active.phaseDetectedGroup = ""
    active.phaseGroupHits = {}
    active.phaseCapturedLines = {}
end

function FuraKillManager.completeActiveCheck()
    local active = FuraKillManager.activeCheck
    if not active then
        return
    end

    if active.killer.resolved == true and active.victim.resolved == true and
       active.killer.isCriminal and active.victim.isCriminal then
        FuraKillManager.addKillRecord(active.killer, active.victim)
        FuraKillManager.updateFeedRecordFromCheck(active, "confirmed")
        FuraKillManager.logDebug(string.format(
            "confirmed kill killer=%s victim=%s killerGroup=%s victimGroup=%s",
            FuraKillManager.playerLabel(active.killer.id, active.killer.nick),
            FuraKillManager.playerLabel(active.victim.id, active.victim.nick),
            tostring(active.killer.groupName or ""),
            tostring(active.victim.groupName or "")
        ))
    elseif active.killer.resolved ~= true or active.victim.resolved ~= true then
        FuraKillManager.updateFeedRecordFromCheck(active, "unverified")
        FuraKillManager.logDebug(string.format(
            "unverified kill killerResolved=%s victimResolved=%s",
            tostring(active.killer.resolved == true),
            tostring(active.victim.resolved == true)
        ))
    else
        FuraKillManager.updateFeedRecordFromCheck(active, "ignored")
        FuraKillManager.logDebug(string.format(
            "ignored kill killerCriminal=%s victimCriminal=%s",
            tostring(active.killer.isCriminal),
            tostring(active.victim.isCriminal)
        ))
    end

    FuraKillManager.activeCheck = nil
end

function FuraKillManager.beginNextPhaseForActiveCheck()
    local active = FuraKillManager.activeCheck
    if not active then
        return
    end

    if FuraKillManager.sideNeedsLookup(active.killer) then
        active.pendingPhase = "killer"
    elseif FuraKillManager.sideNeedsLookup(active.victim) then
        active.pendingPhase = "victim"
    else
        active.phase = nil
        active.pendingPhase = nil
        FuraKillManager.completeActiveCheck()
        return
    end

    if not FuraKillManager.isDialogBusy() and
       (os.clock() - FuraKillManager.lastStatsCommandAt) >= FuraKillManager.statsCommandCooldown then
        FuraKillManager.beginPhase(active.pendingPhase)
    end
end

function FuraKillManager.finalizeActiveCheck()
    local active = FuraKillManager.activeCheck
    if not active then
        return
    end

    local phase = active.phase
    if not phase or not active[phase] then
        FuraKillManager.activeCheck = nil
        return
    end

    local topGroup = FuraKillManager.pickTopGroupFromHits(active.phaseGroupHits)
    if (not topGroup or topGroup == "") and active.phaseDetectedGroup and active.phaseDetectedGroup ~= "" then
        topGroup = FuraKillManager.normalizeGroupLabel(active.phaseDetectedGroup)
    end

    local side = active[phase]
    local hadEvidence = FuraKillManager.hasPhaseEvidence(active)
    if not hadEvidence then
        side.lookupAttempts = (tonumber(side.lookupAttempts or 0) or 0) + 1
        if tonumber(side.lookupAttempts or 0) <= 2 then
            FuraKillManager.updateFeedRecordFromCheck(active, "retry_" .. tostring(phase))
            FuraKillManager.logDebug(string.format(
                "retry phase=%s target=%s attempt=%d",
                tostring(phase),
                FuraKillManager.playerLabel(side.id, side.nick),
                tonumber(side.lookupAttempts or 0) or 0
            ))
            FuraKillManager.schedulePhaseRetry(active, phase)
            return
        end
    end

    side.resolved = hadEvidence
    side.cached = false
    side.isCriminal = active.phaseDetectedCriminal == true or (topGroup ~= nil and topGroup ~= "")
    if side.isCriminal then
        side.groupName = UtilityManager.trim(tostring(topGroup or ""))
        if side.groupName == "" then
            side.groupName = "Uyushgan jinoiy guruh"
        end
    else
        side.groupName = ""
    end

    if side.resolved == true then
        FuraKillManager.storeSideCache(side)
    end

    if phase == "killer" then
        active.phase = nil
        active.phaseStartedAt = 0
        active.phaseLastRelatedAt = os.clock()
        active.phaseCaptureStarted = false
        active.phaseCaptureLastAt = 0
        active.phaseRelatedSeen = false
        FuraKillManager.updateFeedRecordFromCheck(active, "checking_victim")
        FuraKillManager.logDebug(string.format(
            "killer phase done killerCriminal=%s group=%s",
            tostring(active.killer.isCriminal),
            tostring(active.killer.groupName or "")
        ))
        FuraKillManager.beginNextPhaseForActiveCheck()
        return
    end

    FuraKillManager.completeActiveCheck()
end

function FuraKillManager.update()
    if FuraKillManager.isMenuDisabled() or not FuraKillManager.enabled then
        return
    end

    local now = os.clock()

    if FuraKillManager.isAfkPauseActive() then
        if not FuraKillManager.afkPauseLogged then
            FuraKillManager.logDebug(string.format(
                "paused for AFK pending=%d active=%s",
                #FuraKillManager.pendingChecks,
                tostring(FuraKillManager.activeCheck ~= nil)
            ))
            FuraKillManager.afkPauseLogged = true
        end
        return
    elseif FuraKillManager.afkPauseLogged then
        FuraKillManager.afkPauseLogged = false
        FuraKillManager.logDebug(string.format(
            "resumed after AFK pending=%d active=%s",
            #FuraKillManager.pendingChecks,
            tostring(FuraKillManager.activeCheck ~= nil)
        ))
    end

    if FuraKillManager.activeCheck then
        local active = FuraKillManager.activeCheck
        if active.pendingPhase and active.pendingPhase ~= "" then
            if FuraKillManager.isDialogBusy() then
                return
            end
            if (now - FuraKillManager.lastStatsCommandAt) < FuraKillManager.statsCommandCooldown then
                return
            end
            FuraKillManager.beginPhase(active.pendingPhase)
            return
        end

        local phaseElapsed = now - (active.phaseStartedAt or now)
        local idleElapsed = now - (active.phaseLastRelatedAt or now)
        local shouldFinalize = phaseElapsed >= FuraKillManager.phaseTimeout or
                              (active.phaseRelatedSeen and idleElapsed >= FuraKillManager.phaseIdleTimeout)
        if shouldFinalize then
            FuraKillManager.finalizeActiveCheck()
        end
        return
    end

    if #FuraKillManager.pendingChecks == 0 then
        return
    end

    if (now - FuraKillManager.lastStatsCommandAt) < FuraKillManager.statsCommandCooldown then
        return
    end

    if FuraKillManager.isDialogBusy() then
        return
    end

    FuraKillManager.activeCheck = table.remove(FuraKillManager.pendingChecks, 1)
    FuraKillManager.logDebug(string.format(
        "activating queued check killer=%s victim=%s remaining=%d",
        FuraKillManager.playerLabel(FuraKillManager.activeCheck.killer.id, FuraKillManager.activeCheck.killer.nick),
        FuraKillManager.playerLabel(FuraKillManager.activeCheck.victim.id, FuraKillManager.activeCheck.victim.nick),
        #FuraKillManager.pendingChecks
    ))
    FuraKillManager.beginNextPhaseForActiveCheck()
end

function FuraKillManager.exportToTxt(filename)
    local file = io.open(filename, "w")
    if not file then
        return false
    end

    local function writeLine(s)
        file:write((s or "") .. "\n")
    end

    writeLine("=== FURA KILL MONITOR ===")
    writeLine("Generated: " .. os.date("%Y-%m-%d %H:%M:%S"))
    writeLine("Confirmed kills: " .. tostring(#FuraKillManager.kills))
    writeLine("Live feed entries: " .. tostring(#FuraKillManager.killFeed))
    writeLine("TK (bir xil guruh): " .. tostring(FuraKillManager.getTeamKillCount()))
    writeLine("")
    writeLine("G'alaba qozongan jinoiy guruh (oxirgi kill bo'yicha): " .. tostring(FuraKillManager.getWinningCriminalGroup()))
    writeLine("")

    local top = FuraKillManager.getTopKiller()
    if top then
        writeLine(string.format("Eng kop kill qilgan: %s - %d",
            FuraKillManager.playerLabel(top.id, top.nick), top.kills))
    else
        writeLine("Eng kop kill qilgan: N/A")
    end

    if FuraKillManager.firstKill then
        writeLine(string.format("Eng birinchi kill qilgan: %s (%s)",
            FuraKillManager.playerLabel(FuraKillManager.firstKill.killerId, FuraKillManager.firstKill.killerNick),
            FuraKillManager.firstKill.formattedTime or ""))
    else
        writeLine("Eng birinchi kill qilgan: N/A")
    end

    if FuraKillManager.lastKill then
        writeLine(string.format("Eng oxirgi kill qilgan: %s (%s)",
            FuraKillManager.playerLabel(FuraKillManager.lastKill.killerId, FuraKillManager.lastKill.killerNick),
            FuraKillManager.lastKill.formattedTime or ""))
    else
        writeLine("Eng oxirgi kill qilgan: N/A")
    end

    writeLine("")
    writeLine("=== KILLERLAR RO'YXATI ===")
    local killers = FuraKillManager.getSortedKillerStats()
    if #killers == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(killers) do
            writeLine(string.format("%s - %d",
                FuraKillManager.playerLabel(entry.id, entry.nick), entry.kills))
        end
    end

    writeLine("")
    writeLine("=== GURUH BO'YICHA KILL ===")
    local groupKills = FuraKillManager.getSortedGroupStats(FuraKillManager.groupKillStats)
    if #groupKills == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(groupKills) do
            writeLine(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
        end
    end

    writeLine("")
    writeLine("=== TK (BIR XIL GURUH) ===")
    local tkGroups = FuraKillManager.getSortedGroupStats(FuraKillManager.teamKillStats)
    if #tkGroups == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(tkGroups) do
            writeLine(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
        end
    end

    writeLine("")
    writeLine("=== KILL LOG ===")
    if #FuraKillManager.killFeed == 0 then
        writeLine("No tracked kills")
    else
        for i, record in ipairs(FuraKillManager.killFeed) do
            local killerGroup = UtilityManager.trim(tostring(record.killerGroup or ""))
            local victimGroup = UtilityManager.trim(tostring(record.victimGroup or ""))
            if killerGroup == "" then
                killerGroup = "Noma'lum guruh"
            end
            if victimGroup == "" then
                victimGroup = "Noma'lum guruh"
            end
            local verificationState = tostring(record.verificationState or "pending")
            local statusText = "PENDING"
            if verificationState == "confirmed" then
                statusText = "OK"
            elseif verificationState == "checking_victim" then
                statusText = "VICTIM"
            elseif verificationState == "ignored" then
                statusText = "SKIP"
            end
            local tkText = record.isTeamKill and " | TK" or ""
            writeLine(string.format("%d. [%s] %s -> %s",
                i,
                statusText,
                killerGroup,
                victimGroup))
            writeLine(string.format("   %s oldirdi %s%s | %s",
                FuraKillManager.playerLabel(record.killerId, record.killerNick),
                FuraKillManager.playerLabel(record.victimId, record.victimNick),
                tkText,
                record.formattedTime or ""))
        end
    end

    file:close()
    FuraKillManager.lastExportPath = filename
    return true
end



end

