function GossOpgMonitorManager.initialize()
    GossOpgMonitorManager.enabled = SettingsManager.get("gossOpgMonitorEnabled") == true
    LogManager.system(string.format("Goss OPG monitor initialized (%s)",
        GossOpgMonitorManager.enabled and "enabled" or "disabled"))
end

function GossOpgMonitorManager.setEnabled(state)
    GossOpgMonitorManager.enabled = state == true
    SettingsManager.set("gossOpgMonitorEnabled", GossOpgMonitorManager.enabled)
    if not GossOpgMonitorManager.enabled then
        GossOpgMonitorManager.pendingChecks = {}
        GossOpgMonitorManager.activeCheck = nil
    end
end

function GossOpgMonitorManager.clearData()
    GossOpgMonitorManager.kills = {}
    GossOpgMonitorManager.killerStats = {}
    GossOpgMonitorManager.organizationKillStats = {}
    GossOpgMonitorManager.teamKillStats = {}
    GossOpgMonitorManager.pendingChecks = {}
    GossOpgMonitorManager.activeCheck = nil
    GossOpgMonitorManager.firstKill = nil
    GossOpgMonitorManager.lastKill = nil
end

function GossOpgMonitorManager.normalizeLine(text)
    local clean = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
    clean = clean:gsub("[\r\n]+", " "):gsub("%s%s+", " ")
    return UtilityManager.trim(clean)
end

function GossOpgMonitorManager.playerLabel(id, nick)
    local pid = tonumber(id) or -1
    local name = UtilityManager.trim(tostring(nick or "Unknown"))
    if name == "" then
        name = "Unknown"
    end
    return string.format("[%d] %s", pid, name)
end

function GossOpgMonitorManager.resolveNickById(id)
    local pid = tonumber(id)
    if not pid then
        return "Unknown"
    end

    local okConnected, connected = pcall(sampIsPlayerConnected, pid)
    if okConnected and connected then
        local okNick, nick = pcall(sampGetPlayerNickname, pid)
        if okNick and nick and nick ~= "" then
            return nick
        end
    end

    return string.format("ID_%d", pid)
end

function GossOpgMonitorManager.foldText(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end
    value = UtilityManager.casefoldUtf8Cyrillic(value)
    value = UtilityManager.casefoldCp1251Cyrillic(value)
    return value:lower()
end

function GossOpgMonitorManager.stripTimestampPrefix(text)
    local value = tostring(text or "")
    value = value:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
    return UtilityManager.trim(value)
end

function GossOpgMonitorManager.isNoiseLine(line, foldedLine)
    local source = tostring(line or "")
    local lowered = foldedLine or GossOpgMonitorManager.foldText(source)
    if lowered == "" then
        return true
    end
    if lowered:find("<adm>", 1, true) or lowered:find("[a]", 1, true) then
        return true
    end
    if lowered:find("ga javob berdi", 1, true) or lowered:find("???????", 1, true) then
        return true
    end
    if lowered:find("uchun administrator", 1, true) or lowered:find("administrator", 1, true) then
        return true
    end
    if source:match("^%s*%[A%]") or source:match("^%s*<ADM>") then
        return true
    end
    if source:match("^[%w_]+%[%d+%]%s*:") then
        return true
    end
    return false
end

function GossOpgMonitorManager.detectKnownOrganization(foldedLine)
    local text = GossOpgMonitorManager.foldText(foldedLine)
    if text == "" then
        return nil
    end

    for _, org in ipairs(GossOpgMonitorManager.organizations or {}) do
        local tokens = { org.label }
        for _, alias in ipairs(org.aliases or {}) do
            table.insert(tokens, alias)
        end
        for _, token in ipairs(tokens) do
            local foldedToken = GossOpgMonitorManager.foldText(token)
            if foldedToken ~= "" and text:find(foldedToken, 1, true) then
                return org
            end
        end
    end

    return nil
end

function GossOpgMonitorManager.detectCriminalMarker(foldedLine)
    local text = GossOpgMonitorManager.foldText(foldedLine)
    if text == "" then
        return false
    end
    if text:find("uyushgan jinoiy guruh", 1, true) or
       text:find("jinoiy guruh", 1, true) or
       text:find("opg", 1, true) or
       text:find("???", 1, true) or
       (text:find("jinoiy", 1, true) and text:find("guruh", 1, true)) or
       (text:find("???????????", 1, true) and text:find("???????", 1, true)) then
        return true
    end
    return false
end

function GossOpgMonitorManager.detectStateMarker(foldedLine)
    local text = GossOpgMonitorManager.foldText(foldedLine)
    if text == "" then
        return false
    end

    local stateTokens = {
        "fsb", "???",
        "hukumat", "government", "?????????????",
        "harbiy", "army", "military", "?????", "???????",
        "sog'liqni saqlash", "sogliqni saqlash", "vazirligi", "??", "???????", "med",
        "polits", "police", "pd", "?????",
        "yangilik", "news", "smi", "???????", "???"
    }
    for _, token in ipairs(stateTokens) do
        local foldedToken = GossOpgMonitorManager.foldText(token)
        if foldedToken ~= "" and text:find(foldedToken, 1, true) then
            return true
        end
    end
    return false
end

function GossOpgMonitorManager.detectSideMarker(foldedLine)
    local org = GossOpgMonitorManager.detectKnownOrganization(foldedLine)
    if org and org.side then
        return tostring(org.side)
    end
    if GossOpgMonitorManager.detectCriminalMarker(foldedLine) then
        return "criminal"
    end
    if GossOpgMonitorManager.detectStateMarker(foldedLine) then
        return "state"
    end
    return ""
end

function GossOpgMonitorManager.getOrganizationByLabel(label)
    local wanted = GossOpgMonitorManager.foldText(label or "")
    if wanted == "" then
        return nil
    end
    for _, org in ipairs(GossOpgMonitorManager.organizations or {}) do
        if GossOpgMonitorManager.foldText(org.label) == wanted then
            return org
        end
    end
    return nil
end

function GossOpgMonitorManager.normalizeOrganizationLabel(label)
    local source = UtilityManager.trim(tostring(label or ""))
    if source == "" then
        return ""
    end
    local found = GossOpgMonitorManager.detectKnownOrganization(source)
    if found and found.label then
        return found.label
    end
    return source
end

function GossOpgMonitorManager.queueKillCheck(killerId, victimId)
    if not GossOpgMonitorManager.enabled then
        return
    end

    local kid = tonumber(killerId)
    local vid = tonumber(victimId)
    if not kid or not vid or kid == vid or kid == 65535 or vid == 65535 then
        return
    end

    local now = os.clock()
    local signature = string.format("%d>%d", kid, vid)
    if GossOpgMonitorManager.lastDeathSignature == signature and
       (now - GossOpgMonitorManager.lastDeathAt) < 0.4 then
        return
    end
    GossOpgMonitorManager.lastDeathSignature = signature
    GossOpgMonitorManager.lastDeathAt = now

    local check = {
        killer = { id = kid, nick = GossOpgMonitorManager.resolveNickById(kid), isTracked = false, orgLabel = "", orgSide = "" },
        victim = { id = vid, nick = GossOpgMonitorManager.resolveNickById(vid), isTracked = false, orgLabel = "", orgSide = "" },
        createdAt = now,
        phase = nil,
        phaseStartedAt = 0,
        phaseLastRelatedAt = 0,
        phaseRelatedSeen = false,
        phaseDetectedOrg = "",
        phaseDetectedSide = "",
        phaseOrgHits = {},
        phaseCapturedLines = {}
    }

    table.insert(GossOpgMonitorManager.pendingChecks, check)
    if #GossOpgMonitorManager.pendingChecks > GossOpgMonitorManager.maxQueue then
        table.remove(GossOpgMonitorManager.pendingChecks, 1)
    end
end

function GossOpgMonitorManager.onPlayerDeathNotification(killerId, killedId, reason)
    GossOpgMonitorManager.queueKillCheck(killerId, killedId)
end

function GossOpgMonitorManager.beginPhase(phaseName)
    local active = GossOpgMonitorManager.activeCheck
    if not active then
        return
    end

    local side = active[phaseName]
    if not side or not side.id then
        return
    end

    active.phase = phaseName
    active.phaseStartedAt = os.clock()
    active.phaseLastRelatedAt = active.phaseStartedAt
    active.phaseRelatedSeen = false
    active.phaseDetectedOrg = ""
    active.phaseDetectedSide = ""
    active.phaseOrgHits = {}
    active.phaseCapturedLines = {}

    sendChat(string.format("/stats %d", side.id))
    GossOpgMonitorManager.lastStatsCommandAt = os.clock()
end

function GossOpgMonitorManager.isPhaseLineRelated(active, line, foldedLine)
    local phase = active and active.phase
    local side = phase and active[phase] or nil
    if not side then
        return false
    end

    local idText = tostring(side.id)
    if line:find("[" .. idText .. "]", 1, true) then
        return true
    end
    if foldedLine:match("id%s*[:=]?%s*" .. idText) then
        return true
    end

    local nickFolded = GossOpgMonitorManager.foldText(side.nick or "")
    if nickFolded ~= "" and foldedLine:find(nickFolded, 1, true) then
        return true
    end

    return false
end

function GossOpgMonitorManager.capturePhaseLine(active, line)
    local source = UtilityManager.trim(tostring(line or ""))
    if source == "" then
        return
    end

    active.phaseCapturedLines = active.phaseCapturedLines or {}
    for _, existing in ipairs(active.phaseCapturedLines) do
        if existing == source then
            return
        end
    end

    table.insert(active.phaseCapturedLines, source)
    if #active.phaseCapturedLines > 50 then
        table.remove(active.phaseCapturedLines, 1)
    end
end

function GossOpgMonitorManager.updatePhaseFromLine(active, line, forceContext)
    if not active then
        return false
    end

    local cleanLine = GossOpgMonitorManager.stripTimestampPrefix(GossOpgMonitorManager.normalizeLine(line))
    if cleanLine == "" then
        return false
    end

    local folded = GossOpgMonitorManager.foldText(cleanLine)
    if GossOpgMonitorManager.isNoiseLine(cleanLine, folded) then
        return false
    end

    local related = GossOpgMonitorManager.isPhaseLineRelated(active, cleanLine, folded)
    local contextAllowed = related or forceContext == true or active.phaseRelatedSeen == true
    local orgDef = GossOpgMonitorManager.detectKnownOrganization(folded)
    local sideMarker = GossOpgMonitorManager.detectSideMarker(folded)

    if related or (contextAllowed and (orgDef or sideMarker ~= "")) then
        active.phaseRelatedSeen = true
        active.phaseLastRelatedAt = os.clock()
        GossOpgMonitorManager.capturePhaseLine(active, cleanLine)
    end

    if contextAllowed then
        if orgDef then
            active.phaseDetectedOrg = tostring(orgDef.label or "")
            active.phaseDetectedSide = tostring(orgDef.side or "")
            active.phaseOrgHits = active.phaseOrgHits or {}
            active.phaseOrgHits[active.phaseDetectedOrg] = (active.phaseOrgHits[active.phaseDetectedOrg] or 0) + 1
        elseif sideMarker ~= "" and UtilityManager.trim(tostring(active.phaseDetectedSide or "")) == "" then
            active.phaseDetectedSide = sideMarker
        end
    end

    return related or (contextAllowed and (orgDef ~= nil or sideMarker ~= ""))
end

function GossOpgMonitorManager.pickTopOrganization(groupHits)
    local picked = nil
    local pickedCount = -1
    for name, count in pairs(groupHits or {}) do
        local total = tonumber(count) or 0
        if total > pickedCount then
            picked = tostring(name)
            pickedCount = total
        end
    end
    return picked
end

function GossOpgMonitorManager.processStatsTextBlock(rawText)
    if not GossOpgMonitorManager.enabled then
        return false
    end

    local active = GossOpgMonitorManager.activeCheck
    if not active then
        return false
    end

    local text = tostring(rawText or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    if UtilityManager.trim(text) == "" then
        return false
    end

    local processedAny = false
    local lines = UtilityManager.splitString(text, "\n")
    local blockRelated = false

    for _, rawLine in ipairs(lines) do
        local cleanLine = GossOpgMonitorManager.stripTimestampPrefix(GossOpgMonitorManager.normalizeLine(rawLine))
        if cleanLine ~= "" then
            local folded = GossOpgMonitorManager.foldText(cleanLine)
            if not GossOpgMonitorManager.isNoiseLine(cleanLine, folded) and
               GossOpgMonitorManager.isPhaseLineRelated(active, cleanLine, folded) then
                blockRelated = true
                break
            end
        end
    end

    for _, rawLine in ipairs(lines) do
        if GossOpgMonitorManager.updatePhaseFromLine(active, rawLine, blockRelated) then
            processedAny = true
        end
    end

    return processedAny
end

function GossOpgMonitorManager.processStatsMessage(text)
    return GossOpgMonitorManager.processStatsTextBlock(text)
end

function GossOpgMonitorManager.processStatsDialog(dialogId, style, title, button1, button2, text)
    if not GossOpgMonitorManager.enabled or not GossOpgMonitorManager.activeCheck then
        return false
    end

    local processed = false
    if title and UtilityManager.trim(tostring(title)) ~= "" then
        processed = GossOpgMonitorManager.processStatsTextBlock(tostring(title)) or processed
    end
    processed = GossOpgMonitorManager.processStatsTextBlock(tostring(text or "")) or processed

    if processed and GossOpgMonitorManager.activeCheck then
        GossOpgMonitorManager.finalizeActiveCheck()
    end

    return processed
end

function GossOpgMonitorManager.areSameSide(sideA, sideB)
    local a = UtilityManager.trim(tostring(sideA or ""))
    local b = UtilityManager.trim(tostring(sideB or ""))
    if a == "" or b == "" then
        return false
    end
    if a ~= b then
        return false
    end
    return a == "state" or a == "criminal"
end

function GossOpgMonitorManager.normalizeSide(side, orgLabel)
    local value = UtilityManager.trim(tostring(side or ""))
    if value == "state" or value == "criminal" then
        return value
    end

    local orgDef = GossOpgMonitorManager.getOrganizationByLabel(orgLabel or "")
    if orgDef and orgDef.side then
        return tostring(orgDef.side)
    end

    local foldedOrg = GossOpgMonitorManager.foldText(orgLabel or "")
    if foldedOrg ~= "" then
        if GossOpgMonitorManager.detectCriminalMarker(foldedOrg) then
            return "criminal"
        end
        return "state"
    end

    return ""
end

function GossOpgMonitorManager.getSideLabel(side)
    local value = UtilityManager.trim(tostring(side or ""))
    if value == "criminal" then
        return "Jinoiy guruhlar"
    end
    if value == "state" then
        return "Davlat tashkilotlari"
    end
    return "N/A"
end

function GossOpgMonitorManager.getSideTag(side)
    local value = UtilityManager.trim(tostring(side or ""))
    if value == "criminal" then
        return "[OPG]"
    end
    if value == "state" then
        return "[GOSS]"
    end
    return "[N/A]"
end

function GossOpgMonitorManager.addKillRecord(killer, victim)
    local killerOrg = GossOpgMonitorManager.normalizeOrganizationLabel((killer and killer.orgLabel) or "")
    local victimOrg = GossOpgMonitorManager.normalizeOrganizationLabel((victim and victim.orgLabel) or "")
    local killerSide = UtilityManager.trim(tostring((killer and killer.orgSide) or ""))
    local victimSide = UtilityManager.trim(tostring((victim and victim.orgSide) or ""))

    local killerDef = GossOpgMonitorManager.getOrganizationByLabel(killerOrg)
    if killerDef and killerDef.side then
        killerSide = tostring(killerDef.side)
    end
    local victimDef = GossOpgMonitorManager.getOrganizationByLabel(victimOrg)
    if victimDef and victimDef.side then
        victimSide = tostring(victimDef.side)
    end

    killerSide = GossOpgMonitorManager.normalizeSide(killerSide, killerOrg)
    victimSide = GossOpgMonitorManager.normalizeSide(victimSide, victimOrg)

    if killerOrg == "" and killerSide == "criminal" then
        killerOrg = "Barcha jinoiy guruhlar"
    elseif killerOrg == "" and killerSide == "state" then
        killerOrg = "Davlat tashkilotlari"
    end
    if victimOrg == "" and victimSide == "criminal" then
        victimOrg = "Barcha jinoiy guruhlar"
    elseif victimOrg == "" and victimSide == "state" then
        victimOrg = "Davlat tashkilotlari"
    end

    local record = {
        killerId = killer.id,
        killerNick = killer.nick,
        killerOrg = killerOrg,
        killerSide = killerSide,
        victimId = victim.id,
        victimNick = victim.nick,
        victimOrg = victimOrg,
        victimSide = victimSide,
        isTeamKill = GossOpgMonitorManager.areSameSide(killerSide, victimSide),
        time = os.time(),
        formattedTime = os.date("%Y-%m-%d %H:%M:%S")
    }

    table.insert(GossOpgMonitorManager.kills, record)
    if #GossOpgMonitorManager.kills > GossOpgMonitorManager.maxKillLog then
        table.remove(GossOpgMonitorManager.kills, 1)
    end

    local key = tostring(record.killerId)
    if not GossOpgMonitorManager.killerStats[key] then
        GossOpgMonitorManager.killerStats[key] = { id = record.killerId, nick = record.killerNick, kills = 0 }
    end
    local entry = GossOpgMonitorManager.killerStats[key]
    entry.nick = record.killerNick
    entry.kills = (entry.kills or 0) + 1

    if record.killerOrg ~= "" then
        GossOpgMonitorManager.organizationKillStats[record.killerOrg] =
            (GossOpgMonitorManager.organizationKillStats[record.killerOrg] or 0) + 1
    end
    if record.isTeamKill and record.killerOrg ~= "" then
        GossOpgMonitorManager.teamKillStats[record.killerOrg] =
            (GossOpgMonitorManager.teamKillStats[record.killerOrg] or 0) + 1
    end

    if not GossOpgMonitorManager.firstKill then
        GossOpgMonitorManager.firstKill = record
    end
    GossOpgMonitorManager.lastKill = record
end

function GossOpgMonitorManager.finalizeActiveCheck()
    local active = GossOpgMonitorManager.activeCheck
    if not active then
        return
    end

    local phase = active.phase
    if not phase or not active[phase] then
        GossOpgMonitorManager.activeCheck = nil
        return
    end

    local topOrg = GossOpgMonitorManager.pickTopOrganization(active.phaseOrgHits)
    if (not topOrg or topOrg == "") and active.phaseDetectedOrg ~= "" then
        topOrg = active.phaseDetectedOrg
    end
    local detectedSide = UtilityManager.trim(tostring(active.phaseDetectedSide or ""))
    if (not topOrg or topOrg == "") and detectedSide == "criminal" then
        topOrg = "Barcha jinoiy guruhlar"
    elseif (not topOrg or topOrg == "") and detectedSide == "state" then
        topOrg = "Davlat tashkilotlari"
    end

    if topOrg and topOrg ~= "" then
        active[phase].isTracked = true
        active[phase].orgLabel = UtilityManager.trim(tostring(topOrg))
        local orgDef = GossOpgMonitorManager.getOrganizationByLabel(topOrg)
        if orgDef and orgDef.side then
            active[phase].orgSide = tostring(orgDef.side)
        else
            active[phase].orgSide = UtilityManager.trim(tostring(active.phaseDetectedSide or ""))
        end
    else
        active[phase].isTracked = false
        active[phase].orgLabel = ""
        active[phase].orgSide = ""
    end

    if phase == "killer" then
        GossOpgMonitorManager.beginPhase("victim")
        return
    end

    if active.killer.isTracked and active.victim.isTracked then
        GossOpgMonitorManager.addKillRecord(active.killer, active.victim)
    end

    GossOpgMonitorManager.activeCheck = nil
end

function GossOpgMonitorManager.update()
    if not GossOpgMonitorManager.enabled then
        return
    end

    local now = os.clock()
    if GossOpgMonitorManager.activeCheck then
        local active = GossOpgMonitorManager.activeCheck
        local phaseElapsed = now - (active.phaseStartedAt or now)
        local idleElapsed = now - (active.phaseLastRelatedAt or now)
        local shouldFinalize = phaseElapsed >= GossOpgMonitorManager.phaseTimeout or
                              (active.phaseRelatedSeen and idleElapsed >= GossOpgMonitorManager.phaseIdleTimeout)
        if shouldFinalize then
            GossOpgMonitorManager.finalizeActiveCheck()
        end
        return
    end

    if #GossOpgMonitorManager.pendingChecks == 0 then
        return
    end

    if (now - GossOpgMonitorManager.lastStatsCommandAt) < GossOpgMonitorManager.statsCommandCooldown then
        return
    end

    GossOpgMonitorManager.activeCheck = table.remove(GossOpgMonitorManager.pendingChecks, 1)
    GossOpgMonitorManager.beginPhase("killer")
end

function GossOpgMonitorManager.getTopKiller()
    local top = nil
    for _, entry in pairs(GossOpgMonitorManager.killerStats) do
        if entry.kills and entry.kills > 0 then
            if not top or entry.kills > top.kills then
                top = entry
            end
        end
    end
    return top
end

function GossOpgMonitorManager.getLeadingOrganization()
    local latest = GossOpgMonitorManager.kills[#GossOpgMonitorManager.kills]
    if not latest then
        latest = GossOpgMonitorManager.lastKill
    end
    if not latest then
        return "N/A"
    end
    local winner = UtilityManager.trim(tostring(latest.killerOrg or ""))
    if winner == "" then
        winner = "N/A"
    end
    return winner
end

function GossOpgMonitorManager.getWinningSide()
    local last = GossOpgMonitorManager.kills[#GossOpgMonitorManager.kills]
    if not last then
        last = GossOpgMonitorManager.lastKill
    end
    if not last then
        return "N/A"
    end
    return GossOpgMonitorManager.getSideLabel(last.killerSide)
end

function GossOpgMonitorManager.getTopOrganizationByKills()
    local topName = nil
    local topCount = -1
    for orgName, count in pairs(GossOpgMonitorManager.organizationKillStats or {}) do
        local total = tonumber(count) or 0
        if total > topCount then
            topName = tostring(orgName)
            topCount = total
        end
    end
    if not topName or topName == "" or topCount <= 0 then
        return nil, 0
    end
    return topName, topCount
end

function GossOpgMonitorManager.getSortedKillerStats()
    local result = {}
    for _, entry in pairs(GossOpgMonitorManager.killerStats) do
        if entry.kills and entry.kills > 0 then
            table.insert(result, entry)
        end
    end
    table.sort(result, function(a, b)
        if a.kills == b.kills then
            return tostring(a.nick) < tostring(b.nick)
        end
        return a.kills > b.kills
    end)
    return result
end

function GossOpgMonitorManager.getSortedGroupStats(sourceStats)
    local result = {}
    for groupName, count in pairs(sourceStats or {}) do
        local total = tonumber(count) or 0
        if total > 0 then
            table.insert(result, { group = tostring(groupName), count = total })
        end
    end
    table.sort(result, function(a, b)
        if a.count == b.count then
            return tostring(a.group) < tostring(b.group)
        end
        return a.count > b.count
    end)
    return result
end

function GossOpgMonitorManager.getTeamKillCount()
    local count = 0
    for _, record in ipairs(GossOpgMonitorManager.kills) do
        if record.isTeamKill then
            count = count + 1
        end
    end
    return count
end

function GossOpgMonitorManager.exportToTxt(filename)
    local file = io.open(filename, "w")
    if not file then
        return false
    end

    local function writeLine(s)
        file:write((s or "") .. "\n")
    end

    writeLine("=== GOSS OPG MONITOR ===")
    writeLine("Generated: " .. os.date("%Y-%m-%d %H:%M:%S"))
    writeLine("Total tracked kills: " .. tostring(#GossOpgMonitorManager.kills))
    writeLine("TK (bir tomon ichida): " .. tostring(GossOpgMonitorManager.getTeamKillCount()))
    writeLine("")
    writeLine("G'olib tomon (oxirgi kill bo'yicha): " .. tostring(GossOpgMonitorManager.getWinningSide()))
    writeLine("Oxirgi kill qilgan tashkilot: " .. tostring(GossOpgMonitorManager.getLeadingOrganization()))
    writeLine("")

    local top = GossOpgMonitorManager.getTopKiller()
    if top then
        writeLine(string.format("Eng kop kill qilgan: %s - %d",
            GossOpgMonitorManager.playerLabel(top.id, top.nick), top.kills))
    else
        writeLine("Eng kop kill qilgan: N/A")
    end

    local first = GossOpgMonitorManager.firstKill
    if first then
        writeLine(string.format("Eng birinchi kill qilgan: %s %s (%s)",
            GossOpgMonitorManager.getSideTag(first.killerSide),
            GossOpgMonitorManager.playerLabel(first.killerId, first.killerNick),
            first.formattedTime or ""))
    else
        writeLine("Eng birinchi kill qilgan: N/A")
    end

    local last = GossOpgMonitorManager.kills[#GossOpgMonitorManager.kills]
    if not last then
        last = GossOpgMonitorManager.lastKill
    end
    if last then
        writeLine(string.format("Eng oxirgi kill qilgan: %s %s (%s)",
            GossOpgMonitorManager.getSideTag(last.killerSide),
            GossOpgMonitorManager.playerLabel(last.killerId, last.killerNick),
            last.formattedTime or ""))
    else
        writeLine("Eng oxirgi kill qilgan: N/A")
    end

    local topOrgName, topOrgKills = GossOpgMonitorManager.getTopOrganizationByKills()
    if topOrgName then
        writeLine(string.format("Eng kop kill qilgan tashkilot: %s - %d", topOrgName, topOrgKills))
    else
        writeLine("Eng kop kill qilgan tashkilot: N/A")
    end

    writeLine("")
    writeLine("=== KILLERLAR RO'YXATI ===")
    local killers = GossOpgMonitorManager.getSortedKillerStats()
    if #killers == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(killers) do
            writeLine(string.format("%s - %d", GossOpgMonitorManager.playerLabel(entry.id, entry.nick), entry.kills))
        end
    end

    writeLine("")
    writeLine("=== TASHKILOT BO'YICHA KILL ===")
    local groupKills = GossOpgMonitorManager.getSortedGroupStats(GossOpgMonitorManager.organizationKillStats)
    if #groupKills == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(groupKills) do
            writeLine(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
        end
    end

    writeLine("")
    writeLine("=== TK (BIR TOMON ICHIDA) ===")
    local tkGroups = GossOpgMonitorManager.getSortedGroupStats(GossOpgMonitorManager.teamKillStats)
    if #tkGroups == 0 then
        writeLine("No data")
    else
        for _, entry in ipairs(tkGroups) do
            writeLine(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
        end
    end

    writeLine("")
    writeLine("=== KILL LOG ===")
    if #GossOpgMonitorManager.kills == 0 then
        writeLine("No tracked kills")
    else
        for i, record in ipairs(GossOpgMonitorManager.kills) do
            local killerOrg = UtilityManager.trim(tostring(record.killerOrg or ""))
            local victimOrg = UtilityManager.trim(tostring(record.victimOrg or ""))
            if killerOrg == "" then killerOrg = "Noma'lum tashkilot" end
            if victimOrg == "" then victimOrg = "Noma'lum tashkilot" end
            local tkText = record.isTeamKill and " | TK" or ""
            local killerTag = GossOpgMonitorManager.getSideTag(record.killerSide)
            local victimTag = GossOpgMonitorManager.getSideTag(record.victimSide)
            writeLine(string.format("%d. %s -> %s", i, killerOrg, victimOrg))
            writeLine(string.format("   %s %s oldirdi %s %s%s | %s",
                killerTag,
                GossOpgMonitorManager.playerLabel(record.killerId, record.killerNick),
                victimTag,
                GossOpgMonitorManager.playerLabel(record.victimId, record.victimNick),
                tkText,
                record.formattedTime or ""))
        end
    end

    file:close()
    GossOpgMonitorManager.lastExportPath = filename
    return true
end



end

