local function adminCheckerLower(value)
    return tostring(value or ""):lower()
end

local function adminCheckerStripColors(value)
    return tostring(value or ""):gsub("{%x%x%x%x%x%x}", "")
end

local function adminCheckerShadowColor(alpha)
    return imgui.ImVec4(0.01, 0.01, 0.01, tonumber(alpha) or 0.92)
end

local function adminCheckerParseDurationText(value)
    local raw = UtilityManager.trim(tostring(value or ""))
    if raw == "" then
        return "", 0
    end

    local mm, ss = raw:match("^(%d+):(%d+)$")
    if mm and ss then
        local total = (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0)
        return string.format("%02d:%02d", tonumber(mm) or 0, tonumber(ss) or 0), total
    end

    local hh, mm2, ss2 = raw:match("^(%d+):(%d+):(%d+)$")
    if hh and mm2 and ss2 then
        local total = ((tonumber(hh) or 0) * 3600) + ((tonumber(mm2) or 0) * 60) + (tonumber(ss2) or 0)
        return string.format("%02d:%02d:%02d", tonumber(hh) or 0, tonumber(mm2) or 0, tonumber(ss2) or 0), total
    end

    local numeric = tonumber(raw)
    if numeric and numeric > 0 then
        return tostring(math.floor(numeric)), math.floor(numeric)
    end

    return raw, 0
end

local function adminCheckerExtractPlaytime(clean)
    local candidates = {
        clean:match("|%s*(%d+%s*[Ss]oat)"),
        clean:match("|%s*(%d+%s*[Cc]has[a-z]*)"),
        clean:match("|%s*(%d+%s*[Hh])"),
        clean:match("O['`’]?ynagan:%s*([^|]+)"),
        clean:match("Играл:%s*([^|]+)"),
        clean:match("Playtime:%s*([^|]+)"),
        clean:match("Online:%s*([^|]+)")
    }
    for _, candidate in ipairs(candidates) do
        local value = UtilityManager.trim(candidate or "")
        if value ~= "" then
            return value
        end
    end
    return ""
end

local function adminCheckerFormatPlaytimeText(value)
    local raw = UtilityManager.trim(tostring(value or ""))
    if raw == "" then
        return "--"
    end
    if raw:find("soat", 1, true) or raw:find("час", 1, true) or raw:find(":", 1, true) then
        return raw
    end
    local numeric = tonumber(raw)
    if numeric then
        return tostring(math.floor(numeric)) .. " soat"
    end
    return raw
end

local function adminCheckerNormalizeServerText(value)
    local text = tostring(value or "")
    if PlayerLogManager and type(PlayerLogManager.normalizeServerText) == "function" then
        local ok, normalized = pcall(PlayerLogManager.normalizeServerText, text)
        if ok and tostring(normalized or "") ~= "" then
            text = tostring(normalized)
        end
    else
        text = adminCheckerStripColors(text)
    end
    text = text:gsub("^%s*%[%d%d:%d%d:%d%d%]%s*", "")
    text = text:gsub("^%s*%[%d%d:%d%d%]%s*", "")
    return UtilityManager.trim(text)
end

local function adminCheckerFindPlaytimeFromLines(lines)
    if PlayerLogManager and type(PlayerLogManager.findPlaytimeText) == "function" then
        local ok, value = pcall(PlayerLogManager.findPlaytimeText, lines or {})
        value = UtilityManager.trim(tostring(value or ""))
        if ok and value ~= "" then
            return value
        end
    end

    for _, rawLine in ipairs(lines or {}) do
        local cleanLine = adminCheckerNormalizeServerText(rawLine)
        local candidate = cleanLine:match("(%d+:%d+:%d+)") or
            cleanLine:match("(%d+:%d+)") or
            cleanLine:match("(%d+%s*[Ss]oat)") or
            cleanLine:match("(%d+%s*[Cc]has[a-z]*)") or
            cleanLine:match("(%d+%s*[Hh])")
        candidate = UtilityManager.trim(tostring(candidate or ""))
        if candidate ~= "" then
            return candidate
        end
    end

    return ""
end

local function adminCheckerLooksLikeStatsLine(clean)
    local folded = adminCheckerLower(clean)
    if folded == "" then
        return false
    end
    if folded:find("playtime", 1, true) or
       folded:find("o'yin vaqti", 1, true) or
       folded:find("oynagan vaqti", 1, true) or
       folded:find("o'ynagan vaqti", 1, true) or
       folded:find("online:", 1, true) or
       folded:find("level:", 1, true) or
       folded:find("daraja:", 1, true) or
       folded:find("admin daraja", 1, true) or
       folded:find("last login", 1, true) or
       folded:find("register", 1, true) or
       folded:find("login:", 1, true) or
       folded:find("statistika", 1, true) or
       folded:find("stats", 1, true) or
       folded:find("statistics", 1, true) or
       folded:find("player stats", 1, true) or
       folded:find("account", 1, true) or
       folded:find("akkaunt", 1, true) or
       folded:find("tahallus", 1, true) or
       -- bug fix: "id:" alone was too broad and suppressed /id command results.
       -- only suppress when "id:" appears inside a real stats block (alongside other stats keywords).
       (folded:find("id:", 1, true) and (
           folded:find("nick", 1, true) or folded:find("level", 1, true) or
           folded:find("daraja", 1, true) or folded:find("playtime", 1, true) or
           folded:find("statistika", 1, true) or folded:find("akkaunt", 1, true)
       )) or
       folded:find("fraksiya", 1, true) or
       folded:find("organizatsiya", 1, true) or
       folded:find("organization", 1, true) or
       folded:find("hours", 1, true) or
       folded:find("played", 1, true) or
       folded:find("boshqaruv vaqti", 1, true) or
       folded:find("bugungi boshqaruv vaqti", 1, true) or
       folded:find("jami boshqaruv vaqti", 1, true) or
       folded:find("today administration time", 1, true) or
       folded:find("total administration time", 1, true) or
        folded:find("hisob qaydnomasi", 1, true) or
        folded:find("hisob qaytnomasi", 1, true) then
        return true
    end
    local trimmed = UtilityManager.trim(tostring(clean or ""))
    if trimmed:match("^%d+:%d+:%d+$") or
       trimmed:match("^%d+:%d+$") or
       trimmed:match("^%d+%s*[Ss]oat$") or
       trimmed:match("^%d+%s*[Cc]has[a-z]*$") then
        return true
    end
    return false
end

-- safety fix: Admin Checker render code outside this block still calls these helpers by global name.
_G.adminCheckerLower = adminCheckerLower
_G.adminCheckerStripColors = adminCheckerStripColors
