_G.adminCheckerFormatPlaytimeText = adminCheckerFormatPlaytimeText
_G.adminCheckerFindPlaytimeFromLines = adminCheckerFindPlaytimeFromLines

local function adminCheckerCloneBuckets(source)
    local buckets = {}
    for i = 1, 8 do
        buckets[i] = {}
        for _, entry in ipairs((source and source[i]) or {}) do
            buckets[i][#buckets[i] + 1] = entry
        end
    end
    return buckets
end

function AdminCheckerManager.getFlatList()
    return UtilityManager.tableCopy(AdminCheckerManager.flatList or {})
end

function AdminCheckerManager.makeBuckets()
    local buckets = {}
    for i = 1, 8 do
        buckets[i] = {}
    end
    return buckets
end

function AdminCheckerManager.countMapEntries(map)
    local count = 0
    for _ in pairs(map or {}) do
        count = count + 1
    end
    return count
end

function AdminCheckerManager.serializeMap(map)
    local out = {}
    for key, value in pairs(map or {}) do
        local safeKey = UtilityManager.trim(tostring(key or ""))
        if safeKey ~= "" then
            local safeValue = tostring(value or ""):gsub("[\r\n]", " ")
            out[#out + 1] = safeKey .. "=" .. safeValue
        end
    end
    table.sort(out)
    return table.concat(out, "\n")
end

function AdminCheckerManager.deserializeMap(blob, valueTransform)
    local out = {}
    local source = tostring(blob or "")
    for line in source:gmatch("[^\r\n]+") do
        local key, value = line:match("^([^=]+)=(.*)$")
        key = UtilityManager.trim(tostring(key or ""))
        if key ~= "" then
            if type(valueTransform) == "function" then
                out[key] = valueTransform(value)
            else
                out[key] = tostring(value or "")
            end
        end
    end
    return out
end

function AdminCheckerManager.load()
    AdminCheckerManager.configPath = UtilityManager.getConfigPath("admin_checker.ini")
    local saved = UtilityManager.safeIniLoad(AdminCheckerManager.configPath, "Admin checker load")
    local main = type(saved) == "table" and type(saved.main) == "table" and saved.main or {}
    AdminCheckerManager.notes = AdminCheckerManager.deserializeMap(main.notesBlob or "")
    AdminCheckerManager.ignored = AdminCheckerManager.deserializeMap(main.ignoredBlob or "", function(value)
        return tonumber(value) == 1 and 1 or 0
    end)
    AdminCheckerManager.overlay.pos.x = tonumber(main.overlayPosX) or tonumber(AdminCheckerManager.overlay.pos.x) or 24
    AdminCheckerManager.overlay.pos.y = tonumber(main.overlayPosY) or tonumber(AdminCheckerManager.overlay.pos.y) or 210
end

function AdminCheckerManager.save()
    local payload = {
        main = {
            notesBlob = AdminCheckerManager.serializeMap(AdminCheckerManager.notes),
            ignoredBlob = AdminCheckerManager.serializeMap(AdminCheckerManager.ignored),
            overlayPosX = tonumber(AdminCheckerManager.overlay and AdminCheckerManager.overlay.pos and AdminCheckerManager.overlay.pos.x) or 24,
            overlayPosY = tonumber(AdminCheckerManager.overlay and AdminCheckerManager.overlay.pos and AdminCheckerManager.overlay.pos.y) or 210
        }
    }
    return UtilityManager.safeIniSave(payload, AdminCheckerManager.configPath)
end

function AdminCheckerManager.initialize()
    AdminCheckerManager.listByLevel = AdminCheckerManager.makeBuckets()
    AdminCheckerManager.flatList = {}
    AdminCheckerManager.counts = { all = 0, afk = 0 }
    AdminCheckerManager.queue = nil
    AdminCheckerManager.capturePending = false
    AdminCheckerManager.capturePendingAt = 0
    AdminCheckerManager.captureSource = nil
    AdminCheckerManager.manualAdminsUntil = 0
    AdminCheckerManager.manualStatsUntil = 0
    AdminCheckerManager.statsSweepAt = 0
    AdminCheckerManager.lastRequestAt = 0
    AdminCheckerManager.selectedId = nil
    AdminCheckerManager.selectedNick = ""
    AdminCheckerManager.placementActive = false
    AdminCheckerManager.placementLeftLastState = false
    AdminCheckerManager.resetStatsState(false)
    AdminCheckerManager.load()
    if SettingsManager and SettingsManager.set then
        -- safety fix: checker auto refresh must stay manual by default to avoid background /admins spam.
        SettingsManager.set("adminCheckerAutoRefresh", false)
        if SettingsManager.save then
            SettingsManager.save()
        end
    end
    LogManager.system("Admin checker initialized")
end

function AdminCheckerManager.isStatsEnabled()
    return SettingsManager and SettingsManager.get and SettingsManager.get("adminCheckerStatsEnabled") == true
end

function AdminCheckerManager.getTextScale()
    return UtilityManager.clamp(tonumber(SettingsManager and SettingsManager.get and SettingsManager.get("adminCheckerTextScale")) or 1.0, 0.75, 1.80)
end

function AdminCheckerManager.getConfiguredColor(key, fallback)
    local source = SettingsManager and SettingsManager.get and SettingsManager.get(key) or fallback
    local rgb = type(source) == "table" and source or fallback
    return UtilityManager.rgbToFloat(
        tonumber(rgb[1] or rgb["1"]) or fallback[1],
        tonumber(rgb[2] or rgb["2"]) or fallback[2],
        tonumber(rgb[3] or rgb["3"]) or fallback[3]
    )
end

function AdminCheckerManager.resetStatsState(preserveCache)
    if not preserveCache then
        AdminCheckerManager.statsCache = {}
    end
    AdminCheckerManager.statsQueue = {}
    AdminCheckerManager.statsQueueMap = {}
    AdminCheckerManager.statsPending = nil
    AdminCheckerManager.statsSuppress = nil
    AdminCheckerManager.statsLastRequestAt = 0
    AdminCheckerManager.outgoingAutoStatsId = 0
    AdminCheckerManager.outgoingAutoStatsAt = 0
end

function AdminCheckerManager.armOutgoingAutoStats(playerId)
    AdminCheckerManager.outgoingAutoStatsId = tonumber(playerId) or 0
    AdminCheckerManager.outgoingAutoStatsAt = os.clock()
end

function AdminCheckerManager.consumeOutgoingAutoStats(playerId)
    local armedId = tonumber(AdminCheckerManager.outgoingAutoStatsId or 0) or 0
    local armedAt = tonumber(AdminCheckerManager.outgoingAutoStatsAt or 0) or 0
    AdminCheckerManager.outgoingAutoStatsId = 0
    AdminCheckerManager.outgoingAutoStatsAt = 0
    if armedId <= 0 then
        return false
    end
    if (os.clock() - armedAt) > 1.0 then
        return false
    end
    local targetId = tonumber(playerId) or 0
    if targetId > 0 and targetId ~= armedId then
        return false
    end
    return true
end

function AdminCheckerManager.deferManualStats(seconds)
    AdminCheckerManager.resetStatsState(true)
    AdminCheckerManager.manualStatsUntil = os.clock() + math.max(2.5, tonumber(seconds) or 3.5)
end

function AdminCheckerManager.makeStatsIdentityState(id, nick, seconds)
    return {
        id = tonumber(id) or 0,
        nick = tostring(nick or ""),
        untilAt = os.clock() + math.max(0.8, tonumber(seconds) or 1.2)
    }
end

function AdminCheckerManager.matchStatsIdentity(clean, state)
    if type(state) ~= "table" then
        return false
    end
    local folded = adminCheckerLower(clean)
    local nickFolded = adminCheckerLower(state.nick)
    local idText = tostring(tonumber(state.id) or 0)
    return (nickFolded ~= "" and folded:find(nickFolded, 1, true) ~= nil) or
        (idText ~= "0" and (
            folded:find("[" .. idText .. "]", 1, true) ~= nil or
            folded:find("(" .. idText .. ")", 1, true) ~= nil or
            folded:find(" " .. idText .. " ", 1, true) ~= nil or
            folded:find("id:" .. idText, 1, true) ~= nil
        ))
end

function AdminCheckerManager.shouldSuppressStatsOutput(clean)
    local pending = AdminCheckerManager.statsPending
    if pending then
        if adminCheckerLooksLikeStatsLine(clean) then
            return true
        end
    end

    local suppress = AdminCheckerManager.statsSuppress
    if type(suppress) == "table" and os.clock() <= tonumber(suppress.untilAt or 0) then
        if adminCheckerLooksLikeStatsLine(clean) then
            return true
        end
    end

    return false
end

function AdminCheckerManager.isStatsCacheFresh(playerId)
    local cached = AdminCheckerManager.statsCache[tonumber(playerId) or 0]
    if type(cached) ~= "table" then
        return false
    end
    local value = UtilityManager.trim(tostring(cached.playtimeText or ""))
    if value == "" then
        return false
    end
    local updatedAt = tonumber(cached.updatedAt or 0) or 0
    return updatedAt > 0 and (os.time() - updatedAt) < 60
end

function AdminCheckerManager.enqueueStatsForAll(force)
    if not AdminCheckerManager.isStatsEnabled() then
        return 0
    end
    local added = 0
    for _, entry in ipairs(AdminCheckerManager.flatList or {}) do
        local playerId = tonumber(entry and entry.id)
        if playerId and playerId > 0 then
            if force then
                AdminCheckerManager.statsCache[playerId] = nil
            end
            if AdminCheckerManager.enqueueStatsRequest(entry) then
                added = added + 1
            end
        end
    end
    if added > 0 then
        AdminCheckerManager.statsLastRequestAt = 0
    end
    return added
end

function AdminCheckerManager.deferManualAdmins(seconds)
    local holdSeconds = tonumber(seconds) or 3.5
    AdminCheckerManager.capturePending = false
    AdminCheckerManager.capturePendingAt = 0
    AdminCheckerManager.captureSource = nil
    AdminCheckerManager.queue = nil
    AdminCheckerManager.manualAdminsUntil = os.clock() + math.max(1.5, holdSeconds)
end

function AdminCheckerManager.getCachedPlaytimeText(entry)
    local id = tonumber(type(entry) == "table" and entry.id or entry)
    if not id or id <= 0 then
        return ""
    end
    local cached = AdminCheckerManager.statsCache[id]
    if type(cached) ~= "table" then
        return ""
    end
    return UtilityManager.trim(tostring(cached.playtimeText or ""))
end

function AdminCheckerManager.getDisplayPlaytimeText(entry)
    local cached = AdminCheckerManager.getCachedPlaytimeText(entry)
    if cached ~= "" then
        return cached
    end
    return UtilityManager.trim(tostring(type(entry) == "table" and entry.playtimeText or ""))
end

function AdminCheckerManager.finishStatsCapture(playtimeText)
    local pending = AdminCheckerManager.statsPending
    if not pending then
        return false
    end

    local value = UtilityManager.trim(tostring(playtimeText or pending.resolvedPlaytimeText or ""))
    if value ~= "" then
        AdminCheckerManager.statsCache[tonumber(pending.id) or 0] = {
            nick = tostring(pending.nick or ""),
            playtimeText = value,
            updatedAt = os.time()
        }
        local liveEntry = AdminCheckerManager.findEntry(pending.id)
        if liveEntry then
            liveEntry.playtimeText = value
        end
    end

    AdminCheckerManager.statsSuppress = AdminCheckerManager.makeStatsIdentityState(pending.id, pending.nick, 1.35)
    AdminCheckerManager.statsPending = nil
    return value ~= ""
end

function AdminCheckerManager.markStatsResolved(playtimeText)
    local pending = AdminCheckerManager.statsPending
    if not pending then
        return false
    end

    local value = UtilityManager.trim(tostring(playtimeText or ""))
    if value == "" then
        return false
    end

    local now = os.clock()
    pending.resolvedPlaytimeText = value
    pending.captureStarted = true
    pending.lastLineAt = now
    pending.finishAfter = math.max(tonumber(pending.finishAfter or 0) or 0, now + 0.95)
    return true
end

function AdminCheckerManager.enqueueStatsRequest(entry)
    if not AdminCheckerManager.isStatsEnabled() then
        return false
    end
    if type(entry) ~= "table" then
        return false
    end

    local playerId = tonumber(entry.id)
    local nick = UtilityManager.trim(tostring(entry.nick or ""))
    if not playerId or playerId <= 0 or nick == "" then
        return false
    end

    if AdminCheckerManager.isStatsCacheFresh(playerId) then
        return false
    end
    if AdminCheckerManager.statsPending and tonumber(AdminCheckerManager.statsPending.id) == playerId then
        return false
    end
    if AdminCheckerManager.statsQueueMap[playerId] then
        return false
    end

    AdminCheckerManager.statsQueueMap[playerId] = true
    AdminCheckerManager.statsQueue[#AdminCheckerManager.statsQueue + 1] = {
        id = playerId,
        nick = nick
    }
    return true
end

function AdminCheckerManager.processStatsQueue()
    if not AdminCheckerManager.isStatsEnabled() then
        AdminCheckerManager.resetStatsState(true)
        return
    end

    if PlayerLogManager and PlayerLogManager.pending then
        return
    end

    local now = os.clock()
    if tonumber(AdminCheckerManager.manualStatsUntil or 0) > now then
        return
    end
    if AdminCheckerManager.capturePending or type(AdminCheckerManager.queue) == "table" then
        return
    end

    if AdminCheckerManager.statsPending then
        local pending = AdminCheckerManager.statsPending
        local resolvedValue = UtilityManager.trim(tostring(pending.resolvedPlaytimeText or ""))
        local finishAfter = tonumber(pending.finishAfter or 0) or 0
        if resolvedValue ~= "" and finishAfter > 0 and now >= finishAfter then
            AdminCheckerManager.finishStatsCapture(resolvedValue)
        elseif (now - tonumber(pending.startedAt or now)) > 2.5 then
            AdminCheckerManager.finishStatsCapture(resolvedValue)
        end
        return
    end

    if (now - tonumber(AdminCheckerManager.statsLastRequestAt or 0)) < 0.35 then
        return
    end

    local nextRequest = nil
    while #AdminCheckerManager.statsQueue > 0 do
        local candidate = table.remove(AdminCheckerManager.statsQueue, 1)
        local candidateId = tonumber(candidate and candidate.id)
        if candidateId then
            AdminCheckerManager.statsQueueMap[candidateId] = nil
            if not AdminCheckerManager.isStatsCacheFresh(candidateId) then
                nextRequest = candidate
                break
            end
        end
    end

    if not nextRequest then
        return
    end

    AdminCheckerManager.statsPending = {
        id = tonumber(nextRequest.id) or 0,
        nick = tostring(nextRequest.nick or ""),
        lines = {},
        startedAt = now,
        captureStarted = false,
        lastLineAt = now
    }
    AdminCheckerManager.statsLastRequestAt = now
    AdminCheckerManager.armOutgoingAutoStats(nextRequest.id)
    local sent = sendChat(string.format("/stats %d", tonumber(nextRequest.id) or 0))
    if sent == false then
        AdminCheckerManager.outgoingAutoStatsId = 0
        AdminCheckerManager.outgoingAutoStatsAt = 0
    end
end

function AdminCheckerManager.captureStatsMessage(text)
    local pending = AdminCheckerManager.statsPending
    if not pending then
        return nil
    end

    local clean = adminCheckerNormalizeServerText(text)
    if clean == "" then
        return nil
    end

    local folded = adminCheckerLower(clean)
    local nickFolded = adminCheckerLower(pending.nick)
    local idText = tostring(tonumber(pending.id) or 0)
    local hasIdentity = (nickFolded ~= "" and folded:find(nickFolded, 1, true) ~= nil) or
        (idText ~= "0" and (
            folded:find("[" .. idText .. "]", 1, true) ~= nil or
            folded:find("(" .. idText .. ")", 1, true) ~= nil or
            folded:find(" " .. idText .. " ", 1, true) ~= nil
        ))
    local looksLikeStats = adminCheckerLooksLikeStatsLine(clean)

    if not pending.captureStarted then
        if not looksLikeStats then
            return nil
        end
        pending.captureStarted = true
    elseif not hasIdentity and not looksLikeStats then
        return nil
    end

    pending.lastLineAt = os.clock()
    pending.lines[#pending.lines + 1] = clean
    local playtimeText = adminCheckerFindPlaytimeFromLines(pending.lines)
    if playtimeText ~= "" then
        AdminCheckerManager.markStatsResolved(playtimeText)
    end
    return false
end

function AdminCheckerManager.processStatsDialog(dialogId, style, title, button1, button2, text)
    local pending = AdminCheckerManager.statsPending
    if not pending then
        return nil
    end

    local header = adminCheckerNormalizeServerText(title)
    local body = tostring(text or "")
    local foldedHeader = adminCheckerLower(header)
    local nickFolded = adminCheckerLower(pending.nick)
    local idText = tostring(tonumber(pending.id) or 0)
    local bodyFolded = adminCheckerLower(body)
    local looksRelevant = (nickFolded ~= "" and foldedHeader:find(nickFolded, 1, true) ~= nil) or
        (idText ~= "0" and foldedHeader:find(idText, 1, true) ~= nil) or
        (nickFolded ~= "" and bodyFolded:find(nickFolded, 1, true) ~= nil) or
        (idText ~= "0" and bodyFolded:find(idText, 1, true) ~= nil) or
        adminCheckerLooksLikeStatsLine(header) or
        adminCheckerLooksLikeStatsLine(body)

    if not looksRelevant and body == "" then
        return nil
    end

    for line in body:gmatch("[^\r\n]+") do
        local clean = adminCheckerNormalizeServerText(line)
        if clean ~= "" then
            pending.captureStarted = true
            pending.lastLineAt = os.clock()
            pending.lines[#pending.lines + 1] = clean
        end
    end

    local playtimeText = adminCheckerFindPlaytimeFromLines(pending.lines)
    if playtimeText ~= "" then
        AdminCheckerManager.markStatsResolved(playtimeText)
    end
    return false
end

function AdminCheckerManager.getLevelName(level)
    return AdminCheckerManager.levels[tonumber(level) or 0] or tostring(level or "?")
end

function AdminCheckerManager.isOverlayVisible()
    return SettingsManager and SettingsManager.get and
        SettingsManager.get("adminCheckerEnabled") == true and
        SettingsManager.get("adminCheckerOverlayEnabled") ~= false
end

function AdminCheckerManager.getCursorScreenPos()
    if TeleportClickManager and type(TeleportClickManager.getCursorScreenPos) == "function" then
        local okCursor, x, y = pcall(TeleportClickManager.getCursorScreenPos)
        if okCursor and tonumber(x) and tonumber(y) then
            return tonumber(x), tonumber(y)
        end
    end

    if type(getCursorPos) == "function" then
        local ok, a, b, c = pcall(getCursorPos)
        if ok then
            if type(a) == "boolean" then
                if a then
                    return tonumber(b), tonumber(c)
                end
            else
                return tonumber(a), tonumber(b)
            end
        end
    end

    local sx, sy = getScreenResolution()
    return (tonumber(sx) or 1920) * 0.5, (tonumber(sy) or 1080) * 0.5
end

function AdminCheckerManager.isLeftClicked()
    local down = false
    if type(isKeyDown) == "function" then
        local okDown, value = pcall(isKeyDown, vkeys.VK_LBUTTON or 0x01)
        down = okDown and value == true
    end
    local clicked = down and not AdminCheckerManager.placementLeftLastState
    AdminCheckerManager.placementLeftLastState = down
    return clicked
end

function AdminCheckerManager.beginOverlayPlacement()
    AdminCheckerManager.placementActive = true
    AdminCheckerManager.placementLeftLastState = false
    if MainUI then
        MainUI.window.open = false
    end
    imgui.Process = true
    imgui.ShowCursor = true
end

function AdminCheckerManager.finishOverlayPlacement(x, y)
    local screenX, screenY = getScreenResolution()
    local posX = UtilityManager.clamp(tonumber(x) or 24, 8, math.max(8, (tonumber(screenX) or 1920) - 380))
    local posY = UtilityManager.clamp(tonumber(y) or 210, 8, math.max(8, (tonumber(screenY) or 1080) - 180))
    AdminCheckerManager.overlay.pos.x = posX
    AdminCheckerManager.overlay.pos.y = posY
    AdminCheckerManager.placementActive = false
    AdminCheckerManager.placementLeftLastState = false
    AdminCheckerManager.save()
end

function AdminCheckerManager.updateOverlayPlacement()
    if not AdminCheckerManager.placementActive then
        return
    end
    local cursorX, cursorY = AdminCheckerManager.getCursorScreenPos()
    if cursorX and cursorY then
        AdminCheckerManager.overlay.pos.x = cursorX
        AdminCheckerManager.overlay.pos.y = cursorY
    end
    if AdminCheckerManager.isLeftClicked() then
        AdminCheckerManager.finishOverlayPlacement(cursorX, cursorY)
    end
end

function AdminCheckerManager.getLevelColor(level)
    local lvl = tonumber(level) or 0
    if lvl >= 5 then
        return AdminCheckerManager.getConfiguredColor("adminCheckerColorLv5", {255, 71, 82})
    elseif lvl == 4 then
        return AdminCheckerManager.getConfiguredColor("adminCheckerColorLv4", {250, 219, 77})
    elseif lvl == 3 then
        return AdminCheckerManager.getConfiguredColor("adminCheckerColorLv3", {92, 158, 255})
    end
    return AdminCheckerManager.getConfiguredColor("adminCheckerColorLv12", {122, 224, 255})
end

function AdminCheckerManager.buildOverlayLine(entry)
    local target = type(entry) == "table" and entry or {}
    local nick = tostring(target.nick or "Unknown")
    local playerId = tonumber(target.id) or 0
    local levelText = tostring(AdminCheckerManager.getLevelName(target.lvl))
    local playtimeText = adminCheckerFormatPlaytimeText(AdminCheckerManager.getDisplayPlaytimeText(target))
    local line = string.format("%s(%d) %s | %s", nick, playerId, levelText, playtimeText)
    local afkText = UtilityManager.trim(tostring(target.afkText or ""))
    if afkText ~= "" and afkText ~= "0" then
        line = line .. " | AFK " .. afkText
    end
    return line
end

function AdminCheckerManager.drawShadowedText(drawList, x, y, color, text)
    if not drawList or type(drawList.AddText) ~= "function" or not MainUI or type(MainUI.colorToU32) ~= "function" then
        return
    end
    local safeText = tostring(text or "")
    local pos = imgui.ImVec2(tonumber(x) or 0, tonumber(y) or 0)
    local shadow = MainUI.colorToU32(adminCheckerShadowColor(0.94))
    drawList:AddText(imgui.ImVec2(pos.x + 1, pos.y + 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(pos.x - 1, pos.y + 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(pos.x + 1, pos.y - 1), shadow, safeText)
    drawList:AddText(imgui.ImVec2(pos.x - 1, pos.y - 1), shadow, safeText)
    drawList:AddText(pos, MainUI.colorToU32(color or COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1)), safeText)
end

function AdminCheckerManager.drawScaledShadowedText(drawList, x, y, color, text, fontSize)
    local size = tonumber(fontSize) or 0
    local safeText = tostring(text or "")
    if size <= 0 or not imgui.GetFont then
        return AdminCheckerManager.drawShadowedText(drawList, x, y, color, safeText)
    end

    local okFont, font = pcall(imgui.GetFont)
    if not okFont or not font then
        return AdminCheckerManager.drawShadowedText(drawList, x, y, color, safeText)
    end

    local pos = imgui.ImVec2(tonumber(x) or 0, tonumber(y) or 0)
    local shadow = MainUI.colorToU32(adminCheckerShadowColor(0.94))
    local textColor = MainUI.colorToU32(color or COLORS.TEXT or imgui.ImVec4(1, 1, 1, 1))
    local okScaled = pcall(function()
        drawList:AddText(font, size, imgui.ImVec2(pos.x + 1, pos.y + 1), shadow, safeText)
        drawList:AddText(font, size, imgui.ImVec2(pos.x - 1, pos.y + 1), shadow, safeText)
        drawList:AddText(font, size, imgui.ImVec2(pos.x + 1, pos.y - 1), shadow, safeText)
        drawList:AddText(font, size, imgui.ImVec2(pos.x - 1, pos.y - 1), shadow, safeText)
        drawList:AddText(font, size, pos, textColor, safeText)
    end)
    if not okScaled then
        AdminCheckerManager.drawShadowedText(drawList, x, y, color, safeText)
    end
end

function AdminCheckerManager.renderOverlay()
    if not AdminCheckerManager.isOverlayVisible() then
        return
    end

    local drawList = nil
    if imgui.GetBackgroundDrawList then
        local okDraw, value = pcall(imgui.GetBackgroundDrawList)
        if okDraw then
            drawList = value
        end
    end
    if (not drawList) and imgui.GetForegroundDrawList then
        local okDraw, value = pcall(imgui.GetForegroundDrawList)
        if okDraw then
            drawList = value
        end
    end
    if not drawList then
        return
    end

    local screenX, screenY = getScreenResolution()
    screenX = tonumber(screenX) or 1920
    screenY = tonumber(screenY) or 1080
    local posX = UtilityManager.clamp(tonumber(AdminCheckerManager.overlay.pos.x) or 24, 8, math.max(8, screenX - 380))
    local posY = UtilityManager.clamp(tonumber(AdminCheckerManager.overlay.pos.y) or 210, 8, math.max(8, screenY - 180))
    local headerColor = COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0)
    local dimColor = COLORS.TEXT_DIM or imgui.ImVec4(0.76, 0.76, 0.76, 1.0)
    local scale = AdminCheckerManager.getTextScale()
    local baseSize = 13 * scale
    local rowHeight = math.max(15, math.floor(18 * scale))
    local maxRows = math.max(4, math.floor((screenY - posY - (82 * scale)) / rowHeight))
    local visibleEntries = {}
    for _, entry in ipairs(AdminCheckerManager.flatList or {}) do
        if not entry.hidden then
            visibleEntries[#visibleEntries + 1] = entry
            if #visibleEntries >= maxRows then
                break
            end
        end
    end

    AdminCheckerManager.drawScaledShadowedText(drawList, posX, posY, headerColor, "Admin Checker [/admins]", baseSize + 1)
    AdminCheckerManager.drawScaledShadowedText(
        drawList,
        posX,
        posY + math.floor(20 * scale),
        dimColor,
        string.format("Online: %d | AFK: %d | Refresh: %ss", tonumber(AdminCheckerManager.counts.all) or 0, tonumber(AdminCheckerManager.counts.afk) or 0, math.max(1, tonumber(SettingsManager.get("adminCheckerRefreshSeconds")) or 8)),
        baseSize
    )

    local rowY = posY + math.floor(46 * scale)
    if #visibleEntries == 0 then
        AdminCheckerManager.drawScaledShadowedText(drawList, posX, rowY, dimColor, "Adminlar ro'yxati hali olinmagan.", baseSize)
        return
    end

    for _, entry in ipairs(visibleEntries) do
        AdminCheckerManager.drawScaledShadowedText(
            drawList,
            posX,
            rowY,
            AdminCheckerManager.getLevelColor(entry.lvl),
            AdminCheckerManager.buildOverlayLine(entry),
            baseSize
        )
        rowY = rowY + rowHeight
    end
end

function AdminCheckerManager.findEntry(playerId)
    local id = tonumber(playerId)
    if not id then
        return nil
    end
    for _, entry in ipairs(AdminCheckerManager.flatList or {}) do
        if tonumber(entry.id) == id then
            return entry
        end
    end
    return nil
end

function AdminCheckerManager.getNote(nick)
    local key = adminCheckerLower(UtilityManager.trim(tostring(nick or "")))
    return tostring(AdminCheckerManager.notes[key] or "")
end

function AdminCheckerManager.setNote(nick, note)
    local key = adminCheckerLower(UtilityManager.trim(tostring(nick or "")))
    if key == "" then
        return false
    end
    local value = UtilityManager.trim(tostring(note or ""))
    if value == "" then
        AdminCheckerManager.notes[key] = nil
    else
        AdminCheckerManager.notes[key] = value
    end
    AdminCheckerManager.save()
    return true
end

function AdminCheckerManager.isIgnored(nick)
    local key = adminCheckerLower(UtilityManager.trim(tostring(nick or "")))
    return AdminCheckerManager.ignored[key] == 1
end

function AdminCheckerManager.setIgnored(nick, state)
    local key = adminCheckerLower(UtilityManager.trim(tostring(nick or "")))
    if key == "" then
        return false
    end
    if state then
        AdminCheckerManager.ignored[key] = 1
    else
        AdminCheckerManager.ignored[key] = nil
    end
    AdminCheckerManager.save()
    return true
end

function AdminCheckerManager.prepareCapture()
    AdminCheckerManager.capturePending = true
    AdminCheckerManager.capturePendingAt = os.clock()
    AdminCheckerManager.captureSource = "checker"
end

function AdminCheckerManager.beginCapture()
    AdminCheckerManager.queue = {
        buckets = AdminCheckerManager.makeBuckets(),
        dedupe = {},
        source = AdminCheckerManager.captureSource or "checker"
    }
    AdminCheckerManager.queueTouchedAt = os.clock()
    AdminCheckerManager.capturePending = false
end

function AdminCheckerManager.requestRefresh(force)
    local now = os.clock()
    local delay = math.max(1, tonumber(SettingsManager.get("adminCheckerRefreshSeconds")) or 8)
    local captureInFlight = AdminCheckerManager.capturePending or type(AdminCheckerManager.queue) == "table"
    if captureInFlight then
        return false
    end
    if not force and AdminCheckerManager.lastRequestAt > 0 and (now - AdminCheckerManager.lastRequestAt) < delay then
        return false
    end
    AdminCheckerManager.lastRequestAt = now
    AdminCheckerManager.prepareCapture()
    local sent = sendChat("/admins") ~= false
    if not sent then
        AdminCheckerManager.capturePending = false
        AdminCheckerManager.captureSource = nil
    end
    return sent
end

function AdminCheckerManager.isHeaderLine(clean)
    local text = adminCheckerLower(clean)
    return text:find("администрация онлайн", 1, true) ~= nil or
           text:find("администрация в сети", 1, true) ~= nil or
           text:find("administration online", 1, true) ~= nil or
           text:find("tarmoqdagi administratorlar", 1, true) ~= nil or
           text:find("tarmoqdagi adminlar", 1, true) ~= nil
end

function AdminCheckerManager.isMetaLine(clean)
    local text = adminCheckerLower(clean)
    return text:find("bugungi boshqaruv vaqti", 1, true) ~= nil or
           text:find("jami boshqaruv vaqti", 1, true) ~= nil or
           text:find("administration time", 1, true) ~= nil or
           text:find("РІСЂРµРјСЏ Р°РґРјРёРЅРёСЃС‚СЂРёСЂРѕРІР°РЅРёСЏ", 1, true) ~= nil
end

function AdminCheckerManager.parseAdminLine(clean)
    local nick, id = clean:match("^%s*([%w_%.%-]+)%s*%[%s*(%d+)%s*%]")
    if not nick or not id then
        return nil
    end

    local level = clean:match("%[(%d+)%s*[Ll][Vv][Ll]%]") or
                  clean:match("(%d+)%s*[Ll][Vv][Ll]") or
                  clean:match("(%d+)%s*[Dd]arajasi") or
                  clean:match("%[(%d+)%s*[Ll][Ee][Vv][Ee][Ll]%]") or
                  (clean:find("Начальник", 1, true) and "8" or nil)
    level = tonumber(level)
    if not level or level < 1 or level > 8 then
        return nil
    end

    local afkText = UtilityManager.trim(clean:match("AFK%s*%[([^%]]+)%]") or clean:match("AFK:%s*([%d:]+)") or clean:match("AFK%s+([%d:]+)") or "")
    local _, afk = adminCheckerParseDurationText(afkText)
    local playtimeText = adminCheckerExtractPlaytime(clean)
    local rep = tonumber(clean:match("Репутация:%s*([%-%d]+)")) or tonumber(clean:match("Rep:%s*([%-%d]+)")) or 0
    local spec = tonumber(clean:match("/sp%s*(%d+)")) or tonumber(clean:match("SP:%s*(%d+)"))
    local playerId = tonumber(id)

    return {
        nick = tostring(nick),
        id = playerId,
        lvl = level,
        afk = afk,
        afkText = afkText,
        playtimeText = playtimeText,
        rep = rep,
        spec = spec,
        note = AdminCheckerManager.getNote(nick),
        hidden = AdminCheckerManager.isIgnored(nick),
        idle = 0
    }
end

function AdminCheckerManager.addParsedEntry(entry)
    if type(entry) ~= "table" or type(AdminCheckerManager.queue) ~= "table" then
        return false
    end
    local key = tostring(entry.nick or "") .. "#" .. tostring(entry.id or "")
    if AdminCheckerManager.queue.dedupe[key] then
        return false
    end
    AdminCheckerManager.queue.dedupe[key] = true
    local level = UtilityManager.clamp(tonumber(entry.lvl) or 1, 1, 8)
    table.insert(AdminCheckerManager.queue.buckets[level], entry)
    AdminCheckerManager.queueTouchedAt = os.clock()
    return true
end

function AdminCheckerManager.rebuildFlatList()
    local flat = {}
    local counts = { all = 0, afk = 0 }
    for level = 8, 1, -1 do
        table.sort(AdminCheckerManager.listByLevel[level], function(a, b)
            local repA = tonumber(a.rep) or 0
            local repB = tonumber(b.rep) or 0
            if repA == repB then
                return tostring(a.nick or "") < tostring(b.nick or "")
            end
            return repA > repB
        end)
        for _, entry in ipairs(AdminCheckerManager.listByLevel[level]) do
            counts.all = counts.all + 1
            if (tonumber(entry.afk) or 0) > 0 then
                counts.afk = counts.afk + 1
            end
            flat[#flat + 1] = entry
        end
    end
    AdminCheckerManager.flatList = flat
    AdminCheckerManager.counts = counts
end

function AdminCheckerManager.finalizeCapture()
    if type(AdminCheckerManager.queue) ~= "table" then
        return false
    end
    AdminCheckerManager.listByLevel = adminCheckerCloneBuckets(AdminCheckerManager.queue.buckets)
    AdminCheckerManager.queue = nil
    AdminCheckerManager.captureSource = nil
    AdminCheckerManager.rebuildFlatList()
    if AdminCheckerManager.isStatsEnabled() then
        AdminCheckerManager.enqueueStatsForAll(false)
    end
    return true
end

function AdminCheckerManager.update()
    local now = os.clock()
    AdminCheckerManager.updateOverlayPlacement()
    AdminCheckerManager.processStatsQueue()
    if AdminCheckerManager.capturePending and (now - tonumber(AdminCheckerManager.capturePendingAt or 0)) > 4 then
        AdminCheckerManager.capturePending = false
        AdminCheckerManager.captureSource = nil
    end
    if tonumber(AdminCheckerManager.manualAdminsUntil or 0) > 0 and now >= tonumber(AdminCheckerManager.manualAdminsUntil or 0) then
        AdminCheckerManager.manualAdminsUntil = 0
    end
    if tonumber(AdminCheckerManager.manualStatsUntil or 0) > 0 and now >= tonumber(AdminCheckerManager.manualStatsUntil or 0) then
        AdminCheckerManager.manualStatsUntil = 0
    end
    if tonumber(AdminCheckerManager.outgoingAutoStatsAt or 0) > 0 and (now - tonumber(AdminCheckerManager.outgoingAutoStatsAt or 0)) > 1.2 then
        AdminCheckerManager.outgoingAutoStatsId = 0
        AdminCheckerManager.outgoingAutoStatsAt = 0
    end
    if type(AdminCheckerManager.queue) == "table" and (now - tonumber(AdminCheckerManager.queueTouchedAt or 0)) > 0.60 then
        AdminCheckerManager.finalizeCapture()
    end
    if AdminCheckerManager.isStatsEnabled() and #((AdminCheckerManager.flatList) or {}) > 0 then
        if (now - tonumber(AdminCheckerManager.statsSweepAt or 0)) >= 60 then
            AdminCheckerManager.enqueueStatsForAll(false)
            AdminCheckerManager.statsSweepAt = now
        end
    end
    local checkerTabVisible = MainUI and MainUI.window and MainUI.window.open == true and
        (MainUI.currentTab == 4 or MainUI.currentTab == 9)
    local overlayVisible = AdminCheckerManager.isOverlayVisible()
    local shouldAutoRefresh = SettingsManager.get("adminCheckerEnabled") == true and
        ((SettingsManager.get("adminCheckerAutoRefresh") == true and checkerTabVisible) or overlayVisible)
    if shouldAutoRefresh then
        local interval = math.max(1, tonumber(SettingsManager.get("adminCheckerRefreshSeconds")) or 8)
        if tonumber(AdminCheckerManager.manualAdminsUntil or 0) > now then
            return
        elseif tonumber(AdminCheckerManager.lastRequestAt or 0) <= 0 then
            AdminCheckerManager.requestRefresh(true)
        elseif (now - tonumber(AdminCheckerManager.lastRequestAt or 0)) >= interval then
            AdminCheckerManager.requestRefresh(true)
        end
    end
end

function AdminCheckerManager.processServerMessage(text)
    local clean = UtilityManager.trim(adminCheckerStripColors(text))
    if clean == "" then
        return
    end

    local consumedByStats = AdminCheckerManager.captureStatsMessage(clean)
    if consumedByStats == false then
        return false
    end
    if AdminCheckerManager.shouldSuppressStatsOutput(clean) then
        return false
    end

    if tonumber(AdminCheckerManager.manualAdminsUntil or 0) > os.clock() then
        return
    end

    local capturePending = AdminCheckerManager.capturePending == true and AdminCheckerManager.captureSource == "checker"
    local queueActive = type(AdminCheckerManager.queue) == "table" and tostring(AdminCheckerManager.queue.source or "") == "checker"
    local captureActive = capturePending or queueActive

    if captureActive and AdminCheckerManager.isMetaLine(clean) then
        return false
    end

    if AdminCheckerManager.isHeaderLine(clean) then
        if capturePending then
            AdminCheckerManager.beginCapture()
        end
        return false
    end

    local entry = AdminCheckerManager.parseAdminLine(clean)
    if not entry then
        return
    end

    if not capturePending and not queueActive then
        return
    end

    if capturePending and type(AdminCheckerManager.queue) ~= "table" then
        AdminCheckerManager.beginCapture()
    end
    AdminCheckerManager.addParsedEntry(entry)
    if captureActive or type(AdminCheckerManager.queue) == "table" then
        return false
    end
end

function AdminCheckerManager.getLevelCount(level)
    local bucket = AdminCheckerManager.listByLevel[UtilityManager.clamp(tonumber(level) or 1, 1, 8)] or {}
    return #bucket
end

function AdminCheckerManager.printSummaryToChat()
    if type(sampAddChatMessage) ~= "function" then
        return
    end
    sampAddChatMessage(string.format("[GMEA] Admin checker: %d online | AFK: %d", AdminCheckerManager.counts.all, AdminCheckerManager.counts.afk), 0x33FF66)
    for level = 8, 1, -1 do
        local count = AdminCheckerManager.getLevelCount(level)
        if count > 0 then
            sampAddChatMessage(string.format("[GMEA] %s: %d", AdminCheckerManager.getLevelName(level), count), 0xAAAAAA)
        end
    end
end
end


BOOT_LOGGER.write("Inlining module: systems/admin_po_manager.lua")
do
-- ============================================
-- ADMIN PO / CHECKER MANAGER
-- ============================================
AdminPoManager = {
    configPath = "",
    groups = {},
    selectedIndex = 1,
    page = 0,
    multi = nil,
    nickCheck = nil,
    itemSearch = nil,
    itemLevelRanges = {
        { min = 1, max = 14 },
        { min = 15, max = 29 },
        { min = 30, max = 49 },
        { min = 50, max = 99 },
        { min = 100 },
        {}
    }
}

local function adminPoNormalizeNick(nick)
    return UtilityManager.trim(tostring(nick or ""))
end

local function adminPoNormalizeNote(note)
    return tostring(note or ""):gsub("[\r\n]", " ")
end

local function adminPoStripColorTags(text)
    return tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
end

local function adminPoFold(text)
    local value = adminPoNormalizeNick(adminPoStripColorTags(text))
    if value == "" then
        return ""
    end
    return UtilityManager.casefoldUtf8Cyrillic(value)
end

local function adminPoFormatRangeLabel(range)
    if type(range) ~= "table" then
        return "Все LVL"
    end
    if range.min and range.max then
        return string.format("%d - %d LVL", tonumber(range.min) or 0, tonumber(range.max) or 0)
    end
    if range.min and not range.max then
        return string.format("%d+ LVL", tonumber(range.min) or 0)
    end
    return "Все LVL"
end

local function adminPoGetLocalPlayerId()
    if MainUI and type(MainUI.getLocalPlayerId) == "function" then
        local ok, value = pcall(MainUI.getLocalPlayerId)
        if ok then
            return tonumber(value)
        end
    end
    return nil
end

function AdminPoManager.makeDefaultGroup(name)
    local title = adminPoNormalizeNick(name)
    if title == "" then
        title = "Слежка"
    end
    return {
        name = title,
        onlineOnly = true,
        showTitle = true,
        entries = {}
    }
end

function AdminPoManager.serializeEntries(entries)
    local out = {}
    for _, entry in ipairs(entries or {}) do
        local nick = adminPoNormalizeNick(entry.nick)
        if nick ~= "" then
            out[#out + 1] = nick .. "	" .. adminPoNormalizeNote(entry.note)
        end
    end
    return table.concat(out, "\n")
end

function AdminPoManager.deserializeEntries(blob)
    local out = {}
    local source = tostring(blob or "")
    for line in source:gmatch("[^\r\n]+") do
        local nick, note = line:match("^([^	]+)	?(.*)$")
        nick = adminPoNormalizeNick(nick)
        if nick ~= "" then
            out[#out + 1] = {
                nick = nick,
                note = adminPoNormalizeNote(note)
            }
        end
    end
    return out
end

function AdminPoManager.resetTransient()
    AdminPoManager.page = 0
    AdminPoManager.multi = {
        active = false,
        progress = 0,
        results = {},
        current = {
            ip = "-",
            nicks = {}
        },
        startedAtMs = 0,
        thread = nil
    }
    AdminPoManager.nickCheck = {
        num = imgui.ImBool(true),
        sep = imgui.ImBool(true),
        ll = imgui.ImBool(true),
        os = imgui.ImBool(true),
        bl = imgui.ImBool(true),
        bp = imgui.ImBool(true),
        m2 = imgui.ImBool(true),
        results = {},
        lastRunAtMs = 0
    }
    AdminPoManager.itemSearch = {
        active = false,
        levelRangeIndex = 1,
        selectedItem = "",
        progress = { 0, 0 },
        results = {},
        pool = {},
        pendingIndex = nil,
        pendingStartedAt = 0,
        startedAtMs = 0,
        lastStatus = "Предмет не выбран"
    }
end

function AdminPoManager.ensureState()
    if not AdminPoManager.multi or not AdminPoManager.nickCheck or not AdminPoManager.itemSearch then
        AdminPoManager.resetTransient()
    end
end

function AdminPoManager.load()
    AdminPoManager.configPath = UtilityManager.getConfigPath("admin_po.ini")
    local saved = UtilityManager.safeIniLoad(AdminPoManager.configPath, "Admin PO load")
    AdminPoManager.groups = {}
    AdminPoManager.selectedIndex = 1

    if type(saved) == "table" then
        local main = type(saved.main) == "table" and saved.main or {}
        AdminPoManager.selectedIndex = math.max(1, tonumber(main.selectedIndex) or 1)

        local orderedKeys = {}
        for sectionName in pairs(saved) do
            local idx = tonumber(tostring(sectionName):match("^group_(%d+)$"))
            if idx then
                orderedKeys[#orderedKeys + 1] = idx
            end
        end
        table.sort(orderedKeys)

        for _, idx in ipairs(orderedKeys) do
            local section = saved["group_" .. tostring(idx)] or {}
            local group = AdminPoManager.makeDefaultGroup(section.name or ("Checker #" .. tostring(idx)))
            group.onlineOnly = section.onlineOnly ~= false
            group.showTitle = section.showTitle ~= false
            group.entries = AdminPoManager.deserializeEntries(section.entries)
            AdminPoManager.groups[#AdminPoManager.groups + 1] = group
        end
    end

    if #AdminPoManager.groups == 0 then
        AdminPoManager.groups[1] = AdminPoManager.makeDefaultGroup("Слежка")
    end

    AdminPoManager.selectedIndex = UtilityManager.clamp(AdminPoManager.selectedIndex, 1, #AdminPoManager.groups)
end

function AdminPoManager.save()
    local payload = {
        main = {
            selectedIndex = AdminPoManager.selectedIndex
        }
    }
    for index, group in ipairs(AdminPoManager.groups) do
        payload["group_" .. tostring(index)] = {
            name = tostring(group.name or ("Checker #" .. tostring(index))),
            onlineOnly = group.onlineOnly ~= false,
            showTitle = group.showTitle ~= false,
            entries = AdminPoManager.serializeEntries(group.entries)
        }
    end
    return UtilityManager.safeIniSave(payload, AdminPoManager.configPath)
end

function AdminPoManager.initialize()
    AdminPoManager.load()
    AdminPoManager.resetTransient()
    LogManager.system("Admin PO manager initialized")
end

function AdminPoManager.getSelectedGroup()
    return AdminPoManager.groups[UtilityManager.clamp(AdminPoManager.selectedIndex, 1, #AdminPoManager.groups)]
end

function AdminPoManager.createGroup(name)
    local groupName = adminPoNormalizeNick(name)
    if groupName == "" then
        groupName = "Checker #" .. tostring(#AdminPoManager.groups + 1)
    end
    table.insert(AdminPoManager.groups, 1, AdminPoManager.makeDefaultGroup(groupName))
    AdminPoManager.selectedIndex = 1
    AdminPoManager.save()
    return true
end

function AdminPoManager.removeSelectedGroup()
    if #AdminPoManager.groups <= 1 then
        AdminPoManager.groups[1] = AdminPoManager.makeDefaultGroup("Слежка")
        AdminPoManager.selectedIndex = 1
        AdminPoManager.save()
        return false
    end
    table.remove(AdminPoManager.groups, UtilityManager.clamp(AdminPoManager.selectedIndex, 1, #AdminPoManager.groups))
    AdminPoManager.selectedIndex = UtilityManager.clamp(AdminPoManager.selectedIndex, 1, #AdminPoManager.groups)
    AdminPoManager.save()
    return true
end

function AdminPoManager.addEntry(groupIndex, nick, note)
    local group = AdminPoManager.groups[tonumber(groupIndex) or 0]
    local safeNick = adminPoNormalizeNick(nick)
    if not group or safeNick == "" then
        return false, "Nick topilmadi"
    end
    for _, entry in ipairs(group.entries) do
        if adminCheckerLower(entry.nick) == adminCheckerLower(safeNick) then
            return false, "Bu nick allaqachon checker ichida"
        end
    end
    group.entries[#group.entries + 1] = {
        nick = safeNick,
        note = adminPoNormalizeNote(note)
    }
    AdminPoManager.save()
    return true
end

function AdminPoManager.removeEntry(groupIndex, entryIndex)
    local group = AdminPoManager.groups[tonumber(groupIndex) or 0]
    local idx = tonumber(entryIndex)
    if not group or not idx or not group.entries[idx] then
        return false
    end
    table.remove(group.entries, idx)
    AdminPoManager.save()
    return true
end

function AdminPoManager.resolveNickToId(nick)
    local targetNick = adminCheckerLower(adminPoNormalizeNick(nick))
    if targetNick == "" or type(sampIsPlayerConnected) ~= "function" or type(sampGetPlayerNickname) ~= "function" then
        return nil
    end
    for playerId = 0, 1000 do
        local okConnected, connected = pcall(sampIsPlayerConnected, playerId)
        if okConnected and connected then
            local okNick, liveNick = pcall(sampGetPlayerNickname, playerId)
            if okNick and adminCheckerLower(liveNick) == targetNick then
                return playerId
            end
        end
    end
    return nil
end

function AdminPoManager.addPlayerById(groupIndex, playerId, note)
    local id = tonumber(playerId)
    if not id or id < 0 or not UtilityManager.isPlayerConnected(id) then
        return false, "ID noto'g'ri yoki offline"
    end
    local nick = UtilityManager.getPlayerNicknameSafe(id, "")
    if nick == "" then
        return false, "Nick topilmadi"
    end
    return AdminPoManager.addEntry(groupIndex, nick, note)
end

function AdminPoManager.getOnlineIds(group)
    local ids = {}
    for _, entry in ipairs((group and group.entries) or {}) do
        local id = AdminPoManager.resolveNickToId(entry.nick)
        if id then
            ids[#ids + 1] = id
        end
    end
    return ids
end

function AdminPoManager.setPage(page)
    AdminPoManager.ensureState()
    AdminPoManager.page = tonumber(page) or 0
end

function AdminPoManager.stopMultiSearch()
    AdminPoManager.ensureState()
    AdminPoManager.multi.active = false
end

function AdminPoManager.startMultiSearch()
    AdminPoManager.ensureState()
    if AdminPoManager.multi.active then
        return false, "Qidiruv allaqachon ishlayapti"
    end
    if type(lua_thread) ~= "table" or type(lua_thread.create) ~= "function" then
        return false, "lua_thread mavjud emas"
    end

    AdminPoManager.multi.active = true
    AdminPoManager.multi.progress = 0
    AdminPoManager.multi.results = {}
    AdminPoManager.multi.current = { ip = "-", nicks = {} }
    AdminPoManager.multi.startedAtMs = RuntimeGuard.getNowMs()

    AdminPoManager.multi.thread = lua_thread.create(function()
        for playerId = 0, 999 do
            if not AdminPoManager.multi.active then
                break
            end
            AdminPoManager.multi.progress = math.floor(((playerId + 1) / 1000) * 100)
            if UtilityManager.isPlayerConnected(playerId) then
                AdminPoManager.multi.current = { ip = "-", nicks = {} }
                sendChat("/pgetip " .. tostring(playerId))
                wait(1100)
                if #(AdminPoManager.multi.current.nicks or {}) > 1 then
                    AdminPoManager.multi.results[#AdminPoManager.multi.results + 1] = UtilityManager.tableCopy(AdminPoManager.multi.current)
                end
            end
        end
        table.sort(AdminPoManager.multi.results, function(left, right)
            return #((left and left.nicks) or {}) > #((right and right.nicks) or {})
        end)
        AdminPoManager.multi.progress = 100
        AdminPoManager.multi.active = false
    end)

    return true
end

function AdminPoManager.analyzeNonRPNicks()
    AdminPoManager.ensureState()
    local state = AdminPoManager.nickCheck
    local allowUpperParts = {
        La = true,
        Del = true,
        Zu = true,
        Mc = true,
        Di = true,
        De = true,
        Auf = true,
        Du = true,
        Da = true,
        Fon = true,
        Mac = true,
        Aus = true,
        Le = true,
        Al = true,
        Van = true,
        Af = true,
        Sky = true,
        Von = true
    }

    local function hasTripleSame(textValue)
        local source = tostring(textValue or "")
        for index = 3, #source do
            local char = source:sub(index, index)
            if char == source:sub(index - 1, index - 1) and char == source:sub(index - 2, index - 2) then
                return true
            end
        end
        return false
    end

    state.results = {}
    local selfId = adminPoGetLocalPlayerId()

    for playerId = 0, 999 do
        if UtilityManager.isPlayerConnected(playerId) and playerId ~= selfId then
            local nick = UtilityManager.getPlayerNicknameSafe(playerId, "")
            if nick ~= "" then
                local level = 0
                if type(sampGetPlayerScore) == "function" then
                    local okScore, value = pcall(sampGetPlayerScore, playerId)
                    if okScore and value then
                        level = tonumber(value) or 0
                    end
                end

                local function addResult(reason)
                    state.results[#state.results + 1] = {
                        reas = tostring(reason or ""),
                        n = nick,
                        lvl = level,
                        id = playerId
                    }
                end

                if nick:find("%d+") and state.num[0] then
                    addResult("Имеются цифры")
                else
                    local first, last = nick:match("^([%a%d%p]+)_([%a%d%p]+)$")
                    if first and last then
                        if (first .. last):find("%p+") and state.os[0] then
                            addResult("Посторонние символы")
                        elseif state.bp[0] and (first:find("^l") or last:find("^l") or first:find("I", 2, true) or last:find("I", 2, true)) then
                            addResult("Обходной ник")
                        elseif state.ll[0] and (first:find("^[a-z]") or last:find("^[a-z]")) then
                            addResult("С маленькой буквы")
                        elseif state.m2[0] and hasTripleSame(nick) then
                            addResult("Более двух одинаковых букв")
                        elseif first:find("[A-Z]+", 2) or last:find("[A-Z]+", 2) then
                            local headFirst = first:match("^(..*)[A-Z]+")
                            local headLast = last:match("^(.*)[A-Z]+")
                            if state.bl[0] and (not headFirst or not allowUpperParts[headFirst]) and (not headLast or not allowUpperParts[headLast]) then
                                addResult("Большие буквы")
                            end
                        end
                    elseif state.sep[0] then
                        addResult("Нет нижнего подчёркивания")
                    end
                end
            end
        end
    end

    state.lastRunAtMs = RuntimeGuard.getNowMs()
    return true
end

function AdminPoManager.sendNickWarning(playerId)
    local id = tonumber(playerId)
    if not id then
        return false
    end
    if type(lua_thread) ~= "table" or type(lua_thread.create) ~= "function" then
        sendChat("/pm " .. tostring(id) .. " 0 Здравствуйте, Вам необходимо сменить свой никнейм.")
        return true
    end
    lua_thread.create(function()
        sendChat("/pm " .. tostring(id) .. " 0 Здравствуйте, Вам необходимо сменить свой никнейм.")
        wait(1100)
        sendChat("/pm " .. tostring(id) .. " 0 Так как он не соответствует Role-Play режиму.")
        wait(1100)
        sendChat("/pm " .. tostring(id) .. " 0 Используйте: /settings » Сменить Non-RP ник")
    end)
    return true
end

function AdminPoManager.stopItemSearch()
    AdminPoManager.ensureState()
    AdminPoManager.itemSearch.active = false
    AdminPoManager.itemSearch.pendingIndex = nil
end

function AdminPoManager.startItemSearch(itemName)
    AdminPoManager.ensureState()
    local state = AdminPoManager.itemSearch
    local targetItem = adminPoNormalizeNick(itemName)
    if state.active then
        return false, "Qidiruv allaqachon ishlayapti"
    end
    if targetItem == "" then
        return false, "Predmet nomi kiritilmagan"
    end
    if type(lua_thread) ~= "table" or type(lua_thread.create) ~= "function" then
        return false, "lua_thread mavjud emas"
    end

    state.active = true
    state.selectedItem = targetItem
    state.results = {}
    state.pool = {}
    state.progress = { 0, 0 }
    state.pendingIndex = nil
    state.pendingStartedAt = 0
    state.startedAtMs = RuntimeGuard.getNowMs()
    state.lastStatus = "Qidiruv boshlandi"

    state.thread = lua_thread.create(function()
        local range = AdminPoManager.itemLevelRanges[state.levelRangeIndex] or {}
        for playerId = 0, 999 do
            if UtilityManager.isPlayerConnected(playerId) then
                local score = 0
                if type(sampGetPlayerScore) == "function" then
                    local okScore, value = pcall(sampGetPlayerScore, playerId)
                    if okScore and value then
                        score = tonumber(value) or 0
                    end
                end
                if (range.min == nil or score >= range.min) and (range.max == nil or score <= range.max) then
                    state.pool[#state.pool + 1] = {
                        nick = UtilityManager.getPlayerNicknameSafe(playerId, "Unknown"),
                        level = score,
                        count = 0,
                        status = 0,
                        foundAtMs = 0
                    }
                end
            end
        end

        state.progress = { 0, #state.pool }
        if #state.pool == 0 then
            state.lastStatus = "Подходящих игроков в сети нет"
            state.active = false
            return
        end

        for index, entry in ipairs(state.pool) do
            if not state.active then
                break
            end
            state.progress[1] = index
            local playerId = AdminPoManager.resolveNickToId(entry.nick)
            if playerId then
                state.pendingIndex = index
                state.pendingStartedAt = os.clock()
                sendChat(string.format("/checkinv %d 0", playerId))
                while state.active and state.pendingIndex == index do
                    wait(0)
                    if os.clock() - (state.pendingStartedAt or os.clock()) >= 2.2 then
                        state.pendingIndex = nil
                        break
                    end
                end
                if entry.count > 0 then
                    entry.status = 1
                    entry.foundAtMs = RuntimeGuard.getNowMs()
                    state.results[#state.results + 1] = {
                        nick = entry.nick,
                        level = entry.level,
                        count = entry.count,
                        foundAtMs = entry.foundAtMs
                    }
                    table.sort(state.results, function(left, right)
                        return (tonumber(left.count) or 0) > (tonumber(right.count) or 0)
                    end)
                end
                wait(650)
            end
        end

        if state.active then
            state.lastStatus = (#state.results > 0) and "Qidiruv yakunlandi" or "Hech narsa topilmadi"
        else
            state.lastStatus = "Qidiruv to'xtatildi"
        end
        state.pendingIndex = nil
        state.active = false
    end)

    return true
end

function AdminPoManager.processServerMessage(source)
    AdminPoManager.ensureState()
    local text = tostring(source or "")

    if AdminPoManager.multi.active then
        local headerIp = text:match("^%- %- %- %- Совпадение с: ([0-9%.]+)%. %- %- %- %-")
        if headerIp then
            AdminPoManager.multi.current = {
                ip = headerIp,
                nicks = {}
            }
            return false
        end

        local matchedNick = text:match("%- (.*)%[%d+%]")
        if matchedNick then
            local exists = false
            for _, savedNick in ipairs(AdminPoManager.multi.current.nicks or {}) do
                if adminPoFold(savedNick) == adminPoFold(matchedNick) then
                    exists = true
                    break
                end
            end
            if not exists then
                AdminPoManager.multi.current.nicks[#AdminPoManager.multi.current.nicks + 1] = adminPoStripColorTags(matchedNick)
            end
            return false
        end
    end

    if AdminPoManager.itemSearch and AdminPoManager.itemSearch.pendingIndex then
        if text == "Игрок не в сети!" or text == "{FFFFFF}Игрок не в сети!" then
            AdminPoManager.itemSearch.pendingIndex = nil
            return false
        end
    end

    return true
end

function AdminPoManager.findDialogListIndex(text, needle)
    local target = adminPoFold(needle)
    local index = 0
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        if adminPoFold(line):find(target, 1, true) then
            return index
        end
        index = index + 1
    end
    return nil
end

function AdminPoManager.processDialog(dialogId, style, title, button1, button2, text)
    AdminPoManager.ensureState()
    local state = AdminPoManager.itemSearch
    if not state.pendingIndex then
        return true
    end

    local cleanTitle = adminPoStripColorTags(title)
    if tostring(text or "") == "{FFFFFF}Игрок не в сети!" or tostring(text or "") == "Игрок не в сети!" then
        pcall(sampSendDialogResponse, dialogId, 0, 0, "")
        state.pendingIndex = nil
        return false
    end

    if tonumber(style) == 5 and cleanTitle:match("%[ID:%d+%]$") then
        local entry = state.pool[tonumber(state.pendingIndex) or 0]
        if entry then
            for line in tostring(text or ""):gmatch("[^\r\n]+") do
                local itemName, count = line:match("{%x+}%[%d+%] (.-)	%s*{%x+}%[(%d+) шт%]")
                itemName = adminPoStripColorTags(itemName)
                if itemName and count and adminPoFold(itemName) == adminPoFold(state.selectedItem) then
                    entry.count = (tonumber(entry.count) or 0) + (tonumber(count) or 0)
                end
            end
        end

        local nextIndex = AdminPoManager.findDialogListIndex(text, ">> Следующая страница")
        if nextIndex ~= nil then
            pcall(sampSendDialogResponse, dialogId, 1, nextIndex, "")
        else
            pcall(sampSendDialogResponse, dialogId, 0, 0, "")
            state.pendingIndex = nil
        end
        return false
    end

    return true
end

end


