FarmAnswerTool = {
    open = false,
    targetId = nil,
    statusText = "",
    statusError = false
}

function FarmAnswerTool.ensureBuffers()
    -- safety fix: lazy-init imgui buffers so /farm can work even if called in edge startup timing.
    if not FarmAnswerTool.targetId then
        FarmAnswerTool.targetId = imgui.ImInt(0)
    end
end

function FarmAnswerTool.setStatus(message, isError)
    FarmAnswerTool.statusText = tostring(message or "")
    FarmAnswerTool.statusError = isError == true
end

function FarmAnswerTool.openWindow(prefillId)
    FarmAnswerTool.ensureBuffers()
    local resolvedId = math.floor(tonumber(prefillId) or tonumber(FarmAnswerTool.targetId[0]) or 0)
    FarmAnswerTool.targetId[0] = math.max(0, resolvedId)
    FarmAnswerTool.setStatus("", false)
    FarmAnswerTool.open = true
    imgui.Process = true
    imgui.ShowCursor = true
    if LogManager and LogManager.system then
        LogManager.system("FarmAnswerTool opened")
    end
end

function FarmAnswerTool.sendAnswer()
    FarmAnswerTool.ensureBuffers()
    local targetId = math.floor(tonumber(FarmAnswerTool.targetId[0]) or -1)
    if targetId < 0 then
        FarmAnswerTool.setStatus("ID noto'g'ri.", true)
        return false
    end

    local ok = sendChat(string.format("/ans %d Assalom alekum, kuzatyapman", targetId))
    if ok == false then
        FarmAnswerTool.setStatus("/ans yuborilmadi.", true)
        return false
    end

    FarmAnswerTool.setStatus(string.format("/ans %d yuborildi.", targetId), false)
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage(string.format("[GMEA] /ans %d yuborildi.", targetId), 0x33FF66)
    end
    return true
end

function FarmAnswerTool.render()
    if not FarmAnswerTool.open then
        return
    end

    FarmAnswerTool.ensureBuffers()
    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.AlwaysAutoResize
    local open = imgui.ImBool(FarmAnswerTool.open)

    if imgui.Begin(u8"Farm helper##FarmAnswerTool", open, flags) then
        imgui.Text(u8"Bu oynadan faqat bitta /ans yuboriladi.")
        imgui.Spacing()
        imgui.InputInt(u8"ID##farm_target_id", FarmAnswerTool.targetId)
        FarmAnswerTool.targetId[0] = math.max(0, math.floor(tonumber(FarmAnswerTool.targetId[0]) or 0))

        if imgui.Button(u8"Yuborish##farm_send", imgui.ImVec2(140, 30)) then
            RuntimeGuard.call("FarmAnswerTool.sendAnswer", FarmAnswerTool.sendAnswer)
        end
        imgui.SameLine()
        if imgui.Button(u8"Yopish##farm_close", imgui.ImVec2(140, 30)) then
            open[0] = false
        end

        if FarmAnswerTool.statusText ~= "" then
            imgui.Spacing()
            imgui.TextColored(
                FarmAnswerTool.statusError and (COLORS.DANGER or imgui.ImVec4(1.0, 0.25, 0.25, 1.0)) or
                    (COLORS.NEON_SOFT or imgui.ImVec4(0.20, 0.90, 0.45, 1.0)),
                u8(FarmAnswerTool.statusText)
            )
        end
    end

    FarmAnswerTool.open = open[0]
    imgui.End()
end

TimeQuitTool = {
    open = false,
    minutesInput = nil,
    statusText = "",
    statusError = false,
    active = false,
    startedAt = 0,
    dueAt = 0
}

MpTeleportCloseTimer = {
    active = false,
    startedAt = 0,
    endsAt = 0,
    lastUpdateSec = 0,
    sent2m = false,
    sent1m = false,
    sent10s = false,
    sentDone = false
}

function TimeQuitTool.ensureBuffers()
    if not TimeQuitTool.minutesInput then
        TimeQuitTool.minutesInput = imgui.ImInt(5)
    end
end

function TimeQuitTool.initialize()
    TimeQuitTool.ensureBuffers()
    TimeQuitTool.statusText = ""
    TimeQuitTool.statusError = false
    TimeQuitTool.active = false
    TimeQuitTool.startedAt = 0
    TimeQuitTool.dueAt = 0
    return true
end

function MpTeleportCloseTimer.resetRuntime()
    MpTeleportCloseTimer.active = false
    MpTeleportCloseTimer.startedAt = 0
    MpTeleportCloseTimer.endsAt = 0
    MpTeleportCloseTimer.lastUpdateSec = 0
    MpTeleportCloseTimer.sent2m = false
    MpTeleportCloseTimer.sent1m = false
    MpTeleportCloseTimer.sent10s = false
    MpTeleportCloseTimer.sentDone = false
end

function MpTeleportCloseTimer.initialize()
    MpTeleportCloseTimer.resetRuntime()
    return true
end

function MpTeleportCloseTimer.getRemainingSeconds(now)
    if MpTeleportCloseTimer.active ~= true then
        return 0
    end
    local current = tonumber(now) or os.time()
    local endsAt = tonumber(MpTeleportCloseTimer.endsAt) or 0
    return math.max(0, endsAt - current)
end

function MpTeleportCloseTimer.sendMessage(text)
    local payload = UtilityManager.trim(tostring(text or ""))
    if payload == "" then
        return false
    end
    return sendChat("/msg " .. payload) ~= false
end

function MpTeleportCloseTimer.dispatchStage(stageKey, text)
    local sentFieldByStage = {
        two = "sent2m",
        one = "sent1m",
        ten = "sent10s",
        done = "sentDone"
    }
    local sentField = sentFieldByStage[tostring(stageKey or "")]
    if sentField == nil then
        return false
    end
    if MpTeleportCloseTimer[sentField] == true then
        return true
    end
    if MpTeleportCloseTimer.sendMessage(text) ~= false then
        MpTeleportCloseTimer[sentField] = true
        if LogManager and LogManager.system then
            LogManager.system(string.format("MpTeleportCloseTimer sent: %s", tostring(text or "")))
        end
        return true
    end
    return false
end

function MpTeleportCloseTimer.start()
    MpTeleportCloseTimer.resetRuntime()
    local now = tonumber(os.time()) or 0
    if now <= 0 then
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] TP yopilish taymeri ishga tushmadi.", 0xFF6666)
        end
        return false
    end
    MpTeleportCloseTimer.active = true
    MpTeleportCloseTimer.startedAt = now
    MpTeleportCloseTimer.endsAt = now + 120
    MpTeleportCloseTimer.dispatchStage("two", "Teleport yopilishiga 2 minut qoldi")
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage("[GMEA] TP yopilish taymeri ishga tushdi: 2 minut.", 0x33FF66)
    end
    return true
end

function MpTeleportCloseTimer.update()
    if MpTeleportCloseTimer.active ~= true then
        return
    end
    local now = tonumber(os.time()) or 0
    if now <= 0 then
        return
    end
    if now == (tonumber(MpTeleportCloseTimer.lastUpdateSec) or 0) then
        return
    end
    MpTeleportCloseTimer.lastUpdateSec = now

    local remaining = MpTeleportCloseTimer.getRemainingSeconds(now)
    if MpTeleportCloseTimer.sent2m ~= true then
        MpTeleportCloseTimer.dispatchStage("two", "Teleport yopilishiga 2 minut qoldi")
    end
    if remaining <= 60 and MpTeleportCloseTimer.sent1m ~= true then
        MpTeleportCloseTimer.dispatchStage("one", "Teleport yopilishiga 1 minut qoldi")
    end
    if remaining <= 10 and MpTeleportCloseTimer.sent10s ~= true then
        MpTeleportCloseTimer.dispatchStage("ten", "Teleport yopilishiga 10 sekund qoldi")
    end
    if remaining <= 0 then
        if MpTeleportCloseTimer.dispatchStage("done", "Teleport yopildi") ~= false then
            MpTeleportCloseTimer.active = false
        end
    end
end

function TimeQuitTool.setStatus(message, isError)
    TimeQuitTool.statusText = tostring(message or "")
    TimeQuitTool.statusError = isError == true
end

function TimeQuitTool.getRemainingSeconds()
    if TimeQuitTool.active ~= true then
        return 0
    end
    local remaining = math.max(0, math.floor((tonumber(TimeQuitTool.dueAt) or 0) - os.time()))
    return remaining
end

function TimeQuitTool.applyUiState()
    if TimeQuitTool.open == true then
        imgui.Process = true
        imgui.ShowCursor = true
    end
end

function TimeQuitTool.releaseUiState()
    TimeQuitTool.open = false
end

function TimeQuitTool.closeWindow()
    TimeQuitTool.releaseUiState()
    return true
end

function TimeQuitTool.toggleWindow()
    TimeQuitTool.ensureBuffers()
    TimeQuitTool.open = not TimeQuitTool.open
    if TimeQuitTool.open then
        imgui.Process = true
        imgui.ShowCursor = true
    end
    if LogManager and LogManager.system then
        LogManager.system(string.format("TimeQuitTool %s", TimeQuitTool.open and "opened" or "closed"))
    end
    return TimeQuitTool.open
end

function TimeQuitTool.start()
    TimeQuitTool.ensureBuffers()
    local minutes = math.max(1, math.floor(tonumber(TimeQuitTool.minutesInput[0]) or 0))
    TimeQuitTool.minutesInput[0] = minutes
    local now = os.time()
    TimeQuitTool.startedAt = now
    TimeQuitTool.dueAt = now + (minutes * 60)
    TimeQuitTool.active = true
    TimeQuitTool.setStatus(string.format("%d minutlik timer ishga tushdi.", minutes), false)
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage(string.format("[GMEA] /q timer ishga tushdi: %d minut.", minutes), 0x33FF66)
    end
    return true
end

function TimeQuitTool.stop()
    local wasActive = TimeQuitTool.active == true
    TimeQuitTool.active = false
    TimeQuitTool.startedAt = 0
    TimeQuitTool.dueAt = 0
    TimeQuitTool.setStatus("Timer to'xtatildi.", false)
    if wasActive and type(sampAddChatMessage) == "function" then
        sampAddChatMessage("[GMEA] /q timer to'xtatildi.", 0xFF9933)
    end
    return true
end

function TimeQuitTool.executeQuitCommand()
    if type(sampSetGamestate) == "function" and type(sampDisconnectWithReason) == "function" then
        local okDisconnect = pcall(function()
            if ReconnectManager and type(ReconnectManager.cleanupUiState) == "function" then
                ReconnectManager.cleanupUiState()
            end
            sampSetGamestate(RECONNECT_GAMESTATE_DISCONNECTED)
            sampDisconnectWithReason(0)
        end)
        if okDisconnect then
            return true
        end
    end

    if type(rawSampSendChat) == "function" then
        local okRaw = pcall(rawSampSendChat, "/q")
        if okRaw then
            return true
        end
    end

    return sendChat("/q") ~= false
end

function TimeQuitTool.triggerQuit()
    TimeQuitTool.active = false
    TimeQuitTool.startedAt = 0
    TimeQuitTool.dueAt = 0
    local okSend = TimeQuitTool.executeQuitCommand()
    if okSend == false then
        TimeQuitTool.setStatus("/q yuborilmadi.", true)
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] /q yuborilmadi.", 0xFF6666)
        end
        return false
    end
    TimeQuitTool.setStatus("Vaqt tugadi. /q yuborildi.", false)
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage("[GMEA] Vaqt tugadi. /q yuborildi.", 0x33FF66)
    end
    return true
end

function TimeQuitTool.update()
    if TimeQuitTool.active ~= true then
        return
    end
    local dueAt = tonumber(TimeQuitTool.dueAt) or 0
    if dueAt <= 0 then
        TimeQuitTool.stop()
        return
    end
    if os.time() >= dueAt then
        TimeQuitTool.triggerQuit()
    end
end

function TimeQuitTool.render()
    if TimeQuitTool.open ~= true then
        return
    end

    TimeQuitTool.ensureBuffers()
    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.AlwaysAutoResize
    local open = imgui.ImBool(TimeQuitTool.open)

    if imgui.Begin(u8"Time Quit##TimeQuitTool", open, flags) then
        imgui.Text(u8"Minut kiriting. Vaqt tugaganda /q ishlaydi.")
        imgui.Spacing()
        imgui.InputInt(u8"Minut##time_quit_minutes", TimeQuitTool.minutesInput)
        TimeQuitTool.minutesInput[0] = math.max(1, math.floor(tonumber(TimeQuitTool.minutesInput[0]) or 1))

        if TimeQuitTool.active then
            local remaining = TimeQuitTool.getRemainingSeconds()
            local mins = math.floor(remaining / 60)
            local secs = remaining % 60
            imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8(string.format("Qolgan vaqt: %02d:%02d", mins, secs)))
        else
            imgui.TextDisabled(u8"Timer hozir o'chiq.")
        end

        if imgui.Button(u8"Yuborish##time_quit_start", imgui.ImVec2(140, 30)) then
            RuntimeGuard.call("TimeQuitTool.start", TimeQuitTool.start)
        end
        imgui.SameLine()
        if imgui.Button(u8"To'xtatish##time_quit_stop", imgui.ImVec2(140, 30)) then
            RuntimeGuard.call("TimeQuitTool.stop", TimeQuitTool.stop)
        end
        imgui.SameLine()
        if imgui.Button(u8"Yopish##time_quit_close", imgui.ImVec2(140, 30)) then
            open[0] = false
        end

        if TimeQuitTool.statusText ~= "" then
            imgui.Spacing()
            imgui.TextColored(
                TimeQuitTool.statusError and (COLORS.DANGER or imgui.ImVec4(1.0, 0.25, 0.25, 1.0)) or
                    (COLORS.NEON_SOFT or imgui.ImVec4(0.20, 0.90, 0.45, 1.0)),
                u8(TimeQuitTool.statusText)
            )
        end
    end

    TimeQuitTool.open = open[0]
    imgui.End()
end

function MainUI.getAnimationDelta()
    local io = imgui.GetIO and imgui.GetIO()
    local dt = io and tonumber(io.DeltaTime) or nil
    if dt and dt > 0 then
        return UtilityManager.clamp(dt, 1 / 240, 1 / 20)
    end

    local nowMs = RuntimeGuard.getNowMs()
    local lastMs = tonumber(MainUI.buttonFx.lastFrameAtMs) or 0
    if lastMs <= 0 then
        MainUI.buttonFx.lastFrameAtMs = nowMs
        return 1 / 60
    end

    MainUI.buttonFx.lastFrameAtMs = nowMs
    return UtilityManager.clamp((nowMs - lastMs) / 1000, 1 / 240, 1 / 20)
end

function MainUI.mixColor(a, b, t)
    local mix = UtilityManager.clamp(tonumber(t) or 0, 0, 1)
    return imgui.ImVec4(
        UtilityManager.lerp(a.x, b.x, mix),
        UtilityManager.lerp(a.y, b.y, mix),
        UtilityManager.lerp(a.z, b.z, mix),
        UtilityManager.lerp(a.w, b.w, mix)
    )
end

function MainUI.colorToU32(color)
    local c = color or imgui.ImVec4(1, 1, 1, 1)
    if imgui.ColorConvertFloat4ToU32 then
        local ok, value = pcall(imgui.ColorConvertFloat4ToU32, c)
        if ok and value then
            return value
        end
    end
    local r = UtilityManager.clamp(math.floor(((tonumber(c.x) or 1) * 255) + 0.5), 0, 255)
    local g = UtilityManager.clamp(math.floor(((tonumber(c.y) or 1) * 255) + 0.5), 0, 255)
    local b = UtilityManager.clamp(math.floor(((tonumber(c.z) or 1) * 255) + 0.5), 0, 255)
    local a = UtilityManager.clamp(math.floor(((tonumber(c.w) or 1) * 255) + 0.5), 0, 255)
    return r + (g * 256) + (b * 65536) + (a * 16777216)
end

function MainUI.easeOutCubic(t)
    local x = UtilityManager.clamp(tonumber(t) or 0, 0, 1)
    local inv = 1.0 - x
    return 1.0 - (inv * inv * inv)
end

function MainUI.easeInOutSine(t)
    local x = UtilityManager.clamp(tonumber(t) or 0, 0, 1)
    return -(math.cos(math.pi * x) - 1.0) * 0.5
end

function MainUI.getButtonFxState(key)
    local buttonKey = tostring(key or "")
    local state = MainUI.buttonFx.states[buttonKey]
    if not state then
        state = {
            glow = 0,
            target = 0,
            lastSeenAtMs = 0
        }
        MainUI.buttonFx.states[buttonKey] = state
    end
    return state
end

function MainUI.cleanupButtonFx(nowMs)
    if nowMs < (tonumber(MainUI.buttonFx.nextCleanupAtMs) or 0) then
        return
    end

    local expireBefore = nowMs - 12000
    for key, state in pairs(MainUI.buttonFx.states) do
        if (tonumber(state.lastSeenAtMs) or 0) < expireBefore and (tonumber(state.target) or 0) <= 0 then
            MainUI.buttonFx.states[key] = nil
        end
    end

    MainUI.buttonFx.nextCleanupAtMs = nowMs + 5000
end

function MainUI.installNeonButtonHook()
    if MainUI.buttonFx.installed then
        return
    end
    if type(imgui.Button) ~= "function" then
        return
    end

    local rawButton = imgui.Button
    MainUI.buttonFx.installed = true

    imgui.Button = function(label, size)
        local key = tostring(label or "")
        local nowMs = RuntimeGuard.getNowMs()
        local dt = MainUI.getAnimationDelta()
        local state = MainUI.getButtonFxState(key)
        local speed = UtilityManager.clamp(dt * 10.0, 0, 1)
        state.glow = UtilityManager.lerp(state.glow or 0, state.target or 0, speed)
        state.lastSeenAtMs = nowMs

        local glow = UtilityManager.clamp(state.glow or 0, 0, 1)
        local ambient = (tonumber(MainUI.theme.neonPulse) or 0.5) * 0.05
        local baseColor = MainUI.mixColor(COLORS.SURFACE_ALT, COLORS.PRIMARY, 0.22 + ambient + glow * 0.36)
        local hoverColor = MainUI.mixColor(baseColor, COLORS.HOVER, 0.22 + glow * 0.48)
        local activeColor = MainUI.mixColor(baseColor, COLORS.DANGER, 0.30 + glow * 0.52)
        local borderColor = MainUI.mixColor(COLORS.BORDER, COLORS.NEON_SOFT or COLORS.HOVER, 0.18 + ambient + glow * 0.54)
        local textColor = MainUI.mixColor(COLORS.TEXT, COLORS.LIGHT, ambient * 0.8 + glow * 0.30)

        imgui.PushStyleColor(imgui.Col.Button, baseColor)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, hoverColor)
        imgui.PushStyleColor(imgui.Col.ButtonActive, activeColor)
        imgui.PushStyleColor(imgui.Col.Border, borderColor)
        imgui.PushStyleColor(imgui.Col.Text, textColor)

        local pressed = rawButton(label, size)

        imgui.PopStyleColor(5)

        local hovered = false
        local active = false
        if imgui.IsItemHovered then
            local okHovered, hoveredValue = pcall(imgui.IsItemHovered)
            hovered = okHovered and hoveredValue == true
        end
        if imgui.IsItemActive then
            local okActive, activeValue = pcall(imgui.IsItemActive)
            active = okActive and activeValue == true
        end

        state.target = active and 1.0 or (hovered and 0.88 or 0.0)
        MainUI.cleanupButtonFx(nowMs)
        return pressed
    end
end

function MainUI.requestTabSwitch(tabIndex)
    local nextTab = tonumber(tabIndex)
    if nextTab == nil then
        return false
    end
    if nextTab < 0 or nextTab >= #MainUI.tabNames then
        return false
    end
    if not MainUI.canShowTab(nextTab + 1) then
        return false
    end

    local currentTab = tonumber(MainUI.currentTab) or 0
    if nextTab == currentTab then
        return false
    end

    MainUI.animations.lastTab = currentTab
    MainUI.animations.targetTab = nextTab
    MainUI.animations.tabDirection = nextTab > currentTab and 1 or -1
    MainUI.animations.tabTransition = 0
    MainUI.currentTab = nextTab
    return true
end

function MainUI.updateMotionState()
    local dt = MainUI.getAnimationDelta()
    local windowTarget = MainUI.window.open and 1 or 0
    local fadeSpeed = UtilityManager.clamp(dt * 10.0, 0, 1)
    MainUI.animations.fade = UtilityManager.lerp(MainUI.animations.fade or 0, windowTarget, fadeSpeed)

    local duration = tonumber(MainUI.animations.tabDuration) or 0.18
    local tabProgress = tonumber(MainUI.animations.tabTransition) or 1
    if tabProgress < 1 then
        tabProgress = math.min(1, tabProgress + (dt / math.max(0.001, duration)))
    else
        tabProgress = 1
    end
    MainUI.animations.tabTransition = tabProgress

    local timeSeconds = RuntimeGuard.getNowMs() / 1000
    MainUI.theme.neonPulse = 0.5 + 0.5 * math.sin(timeSeconds * 1.15)
    MainUI.theme.neonBreath = 0.5 + 0.5 * math.sin(timeSeconds * 0.55 + 1.2)
end

function MainUI.getAnimatedTabStyle()
    local phase = UtilityManager.clamp(MainUI.animations.tabTransition or 1, 0, 1)
    local reveal = MainUI.easeInOutSine(phase)
    local intro = 1.0 - reveal
    return {
        phase = phase,
        reveal = reveal,
        alpha = UtilityManager.lerp(0.82, 1.0, reveal),
        shiftY = 0,
        accent = intro * 0.55,
        transitioning = phase < 0.999
    }
end

function MainUI.applyDynamicTheme()
    local style = imgui.GetStyle and imgui.GetStyle()
    if not style or not style.Colors then
        return
    end

    local colors = style.Colors
    local pulse = tonumber(MainUI.theme.neonPulse) or 0.5
    local breath = tonumber(MainUI.theme.neonBreath) or 0.5

    colors[imgui.Col.Border] = MainUI.mixColor(COLORS.BORDER, COLORS.NEON_SOFT, 0.08 + pulse * 0.10)
    colors[imgui.Col.Separator] = MainUI.mixColor(imgui.ImVec4(0.60, 0.07, 0.17, 0.85), COLORS.NEON_SOFT, 0.08 + breath * 0.14)
    colors[imgui.Col.MenuBarBg] = MainUI.mixColor(imgui.ImVec4(0.10, 0.02, 0.04, 0.98), COLORS.HOVER, 0.03 + breath * 0.04)
    colors[imgui.Col.Header] = MainUI.mixColor(imgui.ImVec4(0.32, 0.04, 0.09, 0.88), COLORS.NEON_SOFT, 0.03 + pulse * 0.05)
    colors[imgui.Col.HeaderHovered] = MainUI.mixColor(imgui.ImVec4(0.42, 0.05, 0.12, 0.94), COLORS.NEON_HARD, 0.03 + pulse * 0.06)
    colors[imgui.Col.HeaderActive] = MainUI.mixColor(imgui.ImVec4(0.52, 0.06, 0.15, 0.98), COLORS.LIGHT, 0.02 + breath * 0.03)
    colors[imgui.Col.TitleBgActive] = MainUI.mixColor(imgui.ImVec4(0.25, 0.03, 0.08, 1.0), COLORS.HOVER, 0.04 + breath * 0.08)
    colors[imgui.Col.TabActive] = MainUI.mixColor(imgui.ImVec4(0.58, 0.07, 0.17, 1.0), COLORS.NEON_HARD, 0.05 + pulse * 0.08)
    colors[imgui.Col.TabHovered] = MainUI.mixColor(imgui.ImVec4(0.42, 0.05, 0.12, 1.0), COLORS.NEON_SOFT, 0.04 + breath * 0.06)
    colors[imgui.Col.ScrollbarGrabHovered] = MainUI.mixColor(COLORS.PRIMARY, COLORS.NEON_SOFT, 0.06 + pulse * 0.10)
    colors[imgui.Col.ScrollbarGrabActive] = MainUI.mixColor(COLORS.NEON_HARD, COLORS.LIGHT, 0.02 + breath * 0.04)
end

function MainUI.getThemePresets()
    return {
        { name = "Crimson", rgb = { 189, 38, 51 } },
        { name = "Burgundy", rgb = { 146, 28, 46 } },
        { name = "Inferno", rgb = { 214, 66, 36 } },
        { name = "Ruby Ice", rgb = { 132, 62, 178 } }
    }
end

function MainUI.findThemePresetIndex(name)
    local current = tostring(name or "")
    local presets = MainUI.getThemePresets()
    for index, preset in ipairs(presets) do
        if tostring(preset.name) == current then
            return index
        end
    end
    return 1
end

function MainUI.markMenuParticlesDirty()
    if MainUI.menuParticles then
        MainUI.menuParticles.dirty = true
    end
end

function MainUI.applyConfiguredAccent()
    local primary = SettingsManager and SettingsManager.get and SettingsManager.get("primaryColor") or { 189, 38, 51 }
    local r = UtilityManager.clamp(tonumber(primary[1]) or 189, 0, 255)
    local g = UtilityManager.clamp(tonumber(primary[2]) or 38, 0, 255)
    local b = UtilityManager.clamp(tonumber(primary[3]) or 51, 0, 255)

    COLORS.PRIMARY = UtilityManager.rgbToFloat(r, g, b)
    COLORS.SECONDARY = UtilityManager.rgbToFloat(
        UtilityManager.clamp(math.floor(r * 0.68), 0, 255),
        UtilityManager.clamp(math.floor(g * 0.60), 0, 255),
        UtilityManager.clamp(math.floor(b * 0.60), 0, 255)
    )
    COLORS.DANGER = MainUI.mixColor(UtilityManager.rgbToFloat(r, g, b), imgui.ImVec4(1.00, 0.16, 0.28, 1.0), 0.35)
    COLORS.INFO = MainUI.mixColor(UtilityManager.rgbToFloat(r, g, b), imgui.ImVec4(0.98, 0.36, 0.42, 1.0), 0.25)
    COLORS.BORDER = MainUI.mixColor(imgui.ImVec4(0.62, 0.06, 0.17, 1.0), COLORS.PRIMARY, 0.52)
    COLORS.HOVER = MainUI.mixColor(COLORS.PRIMARY, imgui.ImVec4(1.00, 0.36, 0.46, 1.0), 0.28)
    COLORS.ACTIVE = MainUI.mixColor(COLORS.PRIMARY, imgui.ImVec4(0.32, 0.02, 0.06, 1.0), 0.38)
    COLORS.NEON_SOFT = MainUI.mixColor(COLORS.PRIMARY, imgui.ImVec4(1.00, 0.52, 0.60, 1.0), 0.30)
    COLORS.NEON_HARD = MainUI.mixColor(COLORS.PRIMARY, imgui.ImVec4(1.00, 0.88, 0.92, 1.0), 0.22)
    MainUI.theme.accentColor = COLORS.PRIMARY
    MainUI.markMenuParticlesDirty()
end

function MainUI.ensureMenuParticles()
    local targetCount = UtilityManager.clamp(tonumber(SettingsManager.get("menuParticlesCount")) or 16, 4, 40)
    local pool = MainUI.menuParticles.items or {}
    if MainUI.menuParticles.dirty or #pool ~= targetCount then
        MainUI.menuParticles.items = {}
        local symbols = { "*", "+", "o", "~" }
        for i = 1, targetCount do
            MainUI.menuParticles.items[i] = {
                sx = math.random(),
                sy = math.random(),
                phase = math.random() * math.pi * 2,
                symbol = symbols[((i - 1) % #symbols) + 1]
            }
        end
        MainUI.menuParticles.dirty = false
    end
end

function MainUI.renderMenuParticles()
    if SettingsManager.get("menuParticlesEnabled") ~= true then
        return
    end
    local drawList = imgui.GetWindowDrawList and imgui.GetWindowDrawList()
    local winPos = imgui.GetWindowPos and imgui.GetWindowPos()
    local winSize = imgui.GetWindowSize and imgui.GetWindowSize()
    if not drawList or not winPos or not winSize or type(drawList.AddText) ~= "function" then
        return
    end

    MainUI.ensureMenuParticles()

    local speed = UtilityManager.clamp(tonumber(SettingsManager.get("menuParticlesSpeed")) or 0.85, 0.10, 4.0)
    local alpha = UtilityManager.clamp(tonumber(SettingsManager.get("menuParticlesAlpha")) or 0.34, 0.05, 1.0)
    local now = (RuntimeGuard and RuntimeGuard.getNowMs and RuntimeGuard.getNowMs() or math.floor(os.clock() * 1000)) / 1000

    for _, particle in ipairs(MainUI.menuParticles.items or {}) do
        local wave = now * speed + particle.phase
        local x = winPos.x + ((particle.sx + (wave * 0.035)) % 1.0) * winSize.x
        local y = winPos.y + ((particle.sy + math.sin(wave * 0.55) * 0.04 + 1.0) % 1.0) * winSize.y
        local pulse = 0.5 + 0.5 * math.sin(wave * 1.4)
        local color = MainUI.mixColor(COLORS.NEON_SOFT, COLORS.LIGHT, pulse * 0.35)
        color.w = alpha * (0.25 + pulse * 0.40)
        pcall(function()
            drawList:AddText(imgui.ImVec2(x, y), MainUI.colorToU32(color), particle.symbol)
        end)
    end
end

