    MainUI.frameSubscription = nil
    local runtimeCall = RuntimeGuard.call
    MainUI.frameSubscription = imgui.OnFrame(function()
        local ok, visible = runtimeCall("imgui.OnFrame.visible", function()
            local mainWindowOpen = MainUI.window.open == true
            local reportPopupOpen = ReportCatchManager and ReportCatchManager.popupOpen == true or false
            local adminRelayPopupOpen = AdminRelayManager and AdminRelayManager.popupOpen == true or false
            local spectatePanelVisible = SpectateQuickPanel and SpectateQuickPanel.active == true and SpectateQuickPanel.cursorVisible == true or false
            local clickTpVisible = TeleportClickManager and TeleportClickManager.enabled == true or false
            local farmWindowVisible = FarmAnswerTool and FarmAnswerTool.open == true or false
            local killOverlayVisible = KillListManager and KillListManager.isOverlayVisible and KillListManager.isOverlayVisible() or false
            local adminCheckerOverlayVisible = AdminCheckerManager and AdminCheckerManager.isOverlayVisible and AdminCheckerManager.isOverlayVisible() or false
            local targetCircleVisible = TargetCircleOverlay and TargetCircleOverlay.isOverlayVisible and TargetCircleOverlay.isOverlayVisible() or false
            local adminCheckerPlacing = AdminCheckerManager and AdminCheckerManager.placementActive == true or false
            local repQuickVisible = RepQuickReplyManager and RepQuickReplyManager.isWindowOpen and RepQuickReplyManager.isWindowOpen() or false
            local interactiveVisible = mainWindowOpen or reportPopupOpen or adminRelayPopupOpen or
                                     spectatePanelVisible or clickTpVisible or farmWindowVisible or adminCheckerPlacing or repQuickVisible
            if MainUI.frameSubscription then
                MainUI.frameSubscription.HideCursor = not interactiveVisible
            end
            return interactiveVisible or killOverlayVisible or adminCheckerOverlayVisible or targetCircleVisible or repQuickVisible
        end)
        if not ok then
            return false
        end
        return visible == true
    end, function()
        runtimeCall("imgui.OnFrame.render", function()
            local mainWindowOpen = MainUI.window.open == true
            local reportPopupOpen = ReportCatchManager and ReportCatchManager.popupOpen == true or false
            local adminRelayPopupOpen = AdminRelayManager and AdminRelayManager.popupOpen == true or false
            local spectatePanelVisible = SpectateQuickPanel and SpectateQuickPanel.active == true and SpectateQuickPanel.cursorVisible == true or false
            local farmWindowVisible = FarmAnswerTool and FarmAnswerTool.open == true or false
            local timeQuitWindowVisible = TimeQuitTool and TimeQuitTool.open == true or false
            -- crash fix: each render call wrapped in pcall so one failing panel
            -- does not corrupt imgui state for the rest of the frame.
            if mainWindowOpen then
                local ok, err = pcall(MainUI.render)
                if not ok and LogManager and LogManager.system then
                    LogManager.system("[UI] MainUI.render crash: " .. tostring(err or "unknown"))
                end
            end
            if reportPopupOpen then
                pcall(ReportCatchManager.renderPopup)
            end
            if adminRelayPopupOpen then
                pcall(AdminRelayManager.renderPopup)
            end
            if spectatePanelVisible then
                pcall(SpectateQuickPanel.render)
            end
            if TeleportClickManager and TeleportClickManager.renderCursorOverlay then
                pcall(TeleportClickManager.renderCursorOverlay)
            end
            if farmWindowVisible then
                pcall(FarmAnswerTool.render)
            end
            if timeQuitWindowVisible then
                pcall(TimeQuitTool.render)
            end
            if KillListManager and KillListManager.renderOverlay then
                pcall(KillListManager.renderOverlay)
            end
            if AdminCheckerManager and AdminCheckerManager.renderOverlay then
                pcall(AdminCheckerManager.renderOverlay)
            end
            if TargetCircleOverlay and TargetCircleOverlay.render then
                pcall(TargetCircleOverlay.render)
            end
            if RepQuickReplyManager and RepQuickReplyManager.renderWindow then
                pcall(RepQuickReplyManager.renderWindow)
            end
        end)
    end)

    MainUI.initialized = true
    LogManager.system("MainUI initialized")
end

function MainUI.persistWindowState(force)
    if not SettingsManager or not SettingsManager.set or not SettingsManager.save then
        return false
    end

    local pos = MainUI.window.lastGoodPos or MainUI.window.pos
    local size = MainUI.window.lastGoodSize or MainUI.window.size
    if type(pos) ~= "table" or type(size) ~= "table" then
        return false
    end

    local posX = tonumber(pos.x)
    local posY = tonumber(pos.y)
    local width = tonumber(size.x)
    local height = tonumber(size.y)
    if not posX or not posY or not width or not height or width <= 0 or height <= 0 then
        return false
    end

    local now = os.clock()
    if not force and (now - tonumber(MainUI.window.lastPersistAt or 0)) < 0.85 then
        return false
    end

    local changed = math.abs((tonumber(SettingsManager.get("adminMenuPosX")) or 0) - posX) > 0.5 or
                    math.abs((tonumber(SettingsManager.get("adminMenuPosY")) or 0) - posY) > 0.5 or
                    math.abs((tonumber(SettingsManager.get("adminMenuWidth")) or 0) - width) > 0.5 or
                    math.abs((tonumber(SettingsManager.get("adminMenuHeight")) or 0) - height) > 0.5

    if not force and not changed then
        return false
    end

    SettingsManager.set("adminMenuPosX", math.floor(posX + 0.5))
    SettingsManager.set("adminMenuPosY", math.floor(posY + 0.5))
    SettingsManager.set("adminMenuWidth", math.floor(width + 0.5))
    SettingsManager.set("adminMenuHeight", math.floor(height + 0.5))
    MainUI.window.lastPersistAt = now
    return SettingsManager.save()
end

function MainUI.captureWindowSnapshot(minWidth, minHeight)
    if not imgui.GetWindowPos or not imgui.GetWindowSize then
        return
    end

    local pos = imgui.GetWindowPos()
    local size = imgui.GetWindowSize()
    if not pos or not size then
        return
    end

    local io = imgui.GetIO and imgui.GetIO()
    local screenW = io and io.DisplaySize and tonumber(io.DisplaySize.x) or 1920
    local screenH = io and io.DisplaySize and tonumber(io.DisplaySize.y) or 1080
    local safeMinW = tonumber(minWidth) or 620
    local safeMinH = tonumber(minHeight) or 420

    local clampedW = UtilityManager.clamp(tonumber(size.x) or safeMinW, safeMinW, math.max(safeMinW, screenW - 20))
    local clampedH = UtilityManager.clamp(tonumber(size.y) or safeMinH, safeMinH, math.max(safeMinH, screenH - 20))
    local clampedX = UtilityManager.clamp(tonumber(pos.x) or 100, 0, math.max(0, screenW - clampedW))
    local clampedY = UtilityManager.clamp(tonumber(pos.y) or 100, 0, math.max(0, screenH - clampedH))

    local lastGood = MainUI.window.lastGoodSize or MainUI.window.size
    local suspiciousMinShrink = false
    if type(lastGood) == "table" then
        local lastW = tonumber(lastGood.x) or 0
        local lastH = tonumber(lastGood.y) or 0
        suspiciousMinShrink =
            screenW > (safeMinW + 200) and
            screenH > (safeMinH + 180) and
            clampedW <= (safeMinW + 4) and
            clampedH <= (safeMinH + 4) and
            lastW > (safeMinW + 120) and
            lastH > (safeMinH + 80)
    end

    if suspiciousMinShrink then
        local restore = MainUI.window.lastGoodSize or MainUI.window.size
        if restore and imgui.SetWindowSize then
            pcall(imgui.SetWindowSize, imgui.ImVec2(tonumber(restore.x) or safeMinW, tonumber(restore.y) or safeMinH))
        end
        if MainUI.window.lastGoodPos and imgui.SetWindowPos then
            pcall(imgui.SetWindowPos, imgui.ImVec2(
                tonumber(MainUI.window.lastGoodPos.x) or clampedX,
                tonumber(MainUI.window.lastGoodPos.y) or clampedY
            ))
        end
        return
    end

    MainUI.window.pos = { x = clampedX, y = clampedY }
    MainUI.window.size = { x = clampedW, y = clampedH }
    MainUI.window.lastGoodPos = { x = clampedX, y = clampedY }
    MainUI.window.lastGoodSize = { x = clampedW, y = clampedH }
    MainUI.persistWindowState(false)
end

function MainUI.toggle()
    if LogManager and LogManager.system then
        LogManager.system("[UI] panel callback entered")
    end
    MainUI.window.open = not MainUI.window.open
    MainUI.animations.fade = MainUI.window.open and 0 or 1

    -- CRITICAL: Handle cursor and process properly
    if MainUI.window.open then
        imgui.ShowCursor = true
        imgui.Process = true
    else
        imgui.ShowCursor = false
        imgui.Process = false
        MainUI.persistWindowState(true)
        if RulesAiManager and RulesAiManager.stop then
            RulesAiManager.stop()
        end
    end

    LogManager.system(string.format("Panel %s", MainUI.window.open and "opened" or "closed"))
    if LogManager and LogManager.system then
        LogManager.system("[UI] panel callback exited")
    end
end

function MainUI.render()
    if not MainUI.window.open then return end
    if not MainUI.buffers then return end
    if ApprovalGuard and ApprovalGuard.canExecute then
        local canExecute = ApprovalGuard.canExecute()
        if not canExecute then
            MainUI.renderApprovalWaiting()
            return
        end
    end

    MainUI.updateMotionState()
    MainUI.applyDynamicTheme()

    local minWidth, minHeight = 620, 420
    local defaultPos = imgui.ImVec2(100, 100)
    local condAppearing = (imgui.Cond and imgui.Cond.Appearing) or imgui.Cond.FirstUseEver

    if MainUI.window.pos and MainUI.window.pos.x and MainUI.window.pos.y then
        imgui.SetNextWindowPos(
            imgui.ImVec2(MainUI.window.pos.x, MainUI.window.pos.y),
            condAppearing
        )
    else
        imgui.SetNextWindowPos(defaultPos, imgui.Cond.FirstUseEver)
    end

    local io = imgui.GetIO and imgui.GetIO()
    if io and io.DisplaySize then
        local maxWidth = math.max(minWidth, io.DisplaySize.x - 20)
        local maxHeight = math.max(minHeight, io.DisplaySize.y - 20)

        if imgui.SetNextWindowSizeConstraints then
            imgui.SetNextWindowSizeConstraints(
                imgui.ImVec2(minWidth, minHeight),
                imgui.ImVec2(maxWidth, maxHeight)
            )
        end

        if MainUI.window.size and MainUI.window.size.x and MainUI.window.size.y then
            imgui.SetNextWindowSize(
                imgui.ImVec2(MainUI.window.size.x, MainUI.window.size.y),
                condAppearing
            )
        else
            local autoWidth = math.max(minWidth, math.min(maxWidth, io.DisplaySize.x * 0.88))
            local autoHeight = math.max(minHeight, math.min(maxHeight, io.DisplaySize.y * 0.88))
            imgui.SetNextWindowSize(
                imgui.ImVec2(autoWidth, autoHeight),
                imgui.Cond.FirstUseEver
            )
        end
    else
        if MainUI.window.size and MainUI.window.size.x and MainUI.window.size.y then
            imgui.SetNextWindowSize(
                imgui.ImVec2(MainUI.window.size.x, MainUI.window.size.y),
                condAppearing
            )
        else
            imgui.SetNextWindowSize(imgui.ImVec2(minWidth, minHeight), imgui.Cond.FirstUseEver)
        end
    end

    local flags = imgui.WindowFlags.NoCollapse +
                  imgui.WindowFlags.MenuBar

    local styleVarPushed = 0
    if imgui.PushStyleVar and imgui.StyleVar then
        local okAlpha, alphaVar = pcall(function()
            return imgui.StyleVar.Alpha
        end)
        if okAlpha and alphaVar ~= nil then
            imgui.PushStyleVar(alphaVar, UtilityManager.lerp(0.78, 1.0, MainUI.animations.fade or 1))
            styleVarPushed = styleVarPushed + 1
        end
    end

    local shouldDraw = imgui.Begin(u8"Grand Mobile Enterprise Admin System v" .. CONFIG.VERSION,
                   nil, flags)

    if shouldDraw then
        RuntimeGuard.call("MainUI.render.body", function()
            MainUI.captureWindowSnapshot(minWidth, minHeight)
            if AutoAlertSystem and AutoAlertSystem.renderPopup then
                AutoAlertSystem.renderPopup()
                imgui.Spacing()
            end
            MainUI.renderMenuParticles()
            MainUI.renderMenuBar()
            MainUI.renderRoleSummary()
            imgui.Separator()
            MainUI.renderTabs()
        end)
    end

    imgui.End()
    if styleVarPushed > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarPushed)
    end
    if MainUI.renderKatatsyaAccessPopup then
        MainUI.renderKatatsyaAccessPopup()
    end
    if MainUI.renderKatatsyaPanel then
        MainUI.renderKatatsyaPanel()
    end
end

function MainUI.canShowTab(index)
    local key = MainUI.tabPermissions and MainUI.tabPermissions[index]
    if key == "menu.chief_admin" then
        if not RoleManager or not RoleManager.isChiefAdmin or not RoleManager.isChiefAdmin() then
            return false
        end
    end
    if key and PermissionGuard and PermissionGuard.has and not PermissionGuard.has(key) then
        return false
    end
    return true
end

function MainUI.getRoleBadgeColor(level)
    local palette = {
        [1] = imgui.ImVec4(0.58, 0.60, 0.66, 1.0),
        [2] = imgui.ImVec4(0.24, 0.53, 0.93, 1.0),
        [3] = imgui.ImVec4(0.18, 0.73, 0.39, 1.0),
        [4] = imgui.ImVec4(0.95, 0.60, 0.16, 1.0),
        [5] = imgui.ImVec4(0.86, 0.21, 0.21, 1.0),
        [6] = imgui.ImVec4(0.90, 0.74, 0.19, 1.0)
    }
    return palette[tonumber(level) or 0] or (COLORS.INFO or imgui.ImVec4(0.40, 0.70, 1.0, 1.0))
end

function MainUI.renderRoleSummary()
    local primary = RoleManager and RoleManager.getPrimaryRole and RoleManager.getPrimaryRole() or nil
    local secondary = RoleManager and RoleManager.getSecondaryRole and RoleManager.getSecondaryRole() or nil
    local primaryRemaining = RoleManager and RoleManager.getPrimaryRemainingText and RoleManager.getPrimaryRemainingText() or "Rol berilmagan"
    local secondaryRemaining = RoleManager and RoleManager.getSecondaryRemainingText and RoleManager.getSecondaryRemainingText() or "Rol berilmagan"
    local online = SessionState and SessionState.isOnlineNow and SessionState.isOnlineNow() or false
    local lastSeen = SessionState and SessionState.getLastSeenText and SessionState.getLastSeenText() or "noma'lum"
    local totalPlaytime = SessionState and SessionState.getTotalPlaytimeText and SessionState.getTotalPlaytimeText() or "0m"

    imgui.TextDisabled(u8"Role:")
    imgui.SameLine()

    if not primary and not secondary then
        imgui.TextDisabled(u8"Rol berilmagan")
    else
        if primary then
            local primaryLabel = tostring(primary.name_uz or primary.key or "Admin")
            imgui.TextColored(MainUI.getRoleBadgeColor(primary.level), u8("[" .. primaryLabel .. "]"))
            imgui.SameLine()
            imgui.TextDisabled(u8(primaryRemaining))
        end

        if secondary then
            if primary then
                imgui.SameLine()
            end
            local secondaryLabel = tostring(secondary.name_uz or secondary.key or "Secondary")
            imgui.TextColored(COLORS.SECONDARY or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8("[+ " .. secondaryLabel .. "]"))
            imgui.SameLine()
            imgui.TextDisabled(u8(secondaryRemaining))
        end
    end

    imgui.SameLine()
    imgui.TextDisabled("|")
    imgui.SameLine()
    if online then
        imgui.TextColored(COLORS.PRIMARY or imgui.ImVec4(0.20, 0.80, 0.30, 1.0), u8"ONLINE")
    else
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"OFFLINE")
    end
    imgui.SameLine()
    imgui.TextDisabled(u8(lastSeen))
    imgui.SameLine()
    imgui.TextDisabled(u8("Jami: " .. tostring(totalPlaytime)))
end

