        ReportCatchManager.settings.reportKeywordReplyKeywords = keywords
        ReportCatchManager.settings.reportKeywordReplyText1 = text1
        ReportCatchManager.settings.reportKeywordReplyText2 = ""
        ReportCatchManager.settings.reportKeywordReplyText3 = ""
