        UtilityManager.setBufferString(MainUI.buffers.reportKeywordReplyKeywords, keywords)
        UtilityManager.setBufferString(MainUI.buffers.reportKeywordReplyText1, text1)
        UtilityManager.setBufferString(MainUI.buffers.reportKeywordReplyText2, "")
        UtilityManager.setBufferString(MainUI.buffers.reportKeywordReplyText3, "")
