    end

    imgui.TextDisabled(string.format(
        "Kalit so'zlar: %s",
        tostring(ReportCatchManager.settings.reportKeywordReplyKeywords or "")))
    imgui.TextDisabled(string.format(
        "Cooldown: %ds | Hozir bitta javob ishlaydi",
        tonumber(ReportCatchManager.settings.reportKeywordReplyCooldown) or 8))
    imgui.TextDisabled(u8"Report ichida shu kalitlar uchrasa /ans yuboriladi. /sp qo'shilmaydi.")

    imgui.Separator()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Report -> Template Auto Mos")
    local routingEnabled = imgui.ImBool(ReportCatchManager.settings.templateRoutingEnabled ~= false)
    if imgui.Checkbox(u8"Kalit so'z bo'yicha template tanlash##tpl_route_en_" .. scopeSuffix, routingEnabled) then
        ReportCatchManager.settings.templateRoutingEnabled = routingEnabled[0]
        ReportCatchManager.saveSettings()
    end

    MainUI.buffers.replyKeywordsByTemplate = MainUI.buffers.replyKeywordsByTemplate or {}
    imgui.BeginChild("##tpl_route_all_" .. scopeSuffix, imgui.ImVec2(0, 300), true)
    for _, template in ipairs(ReportCatchManager.templates or {}) do
        local templateId = tonumber(template.id)
        if templateId then
            local key = tostring(templateId)
            local routeBuf = MainUI.buffers.replyKeywordsByTemplate[key]
            if not routeBuf then
                routeBuf = imgui.new.char[384]()
                UtilityManager.setBufferString(routeBuf, ReportCatchManager.getTemplateRouteRaw(templateId))
                MainUI.buffers.replyKeywordsByTemplate[key] = routeBuf
            end

            local shortcut = UtilityManager.toUtf8(tostring(template.shortcut or ""))
            if shortcut == "" then
                shortcut = "Template"
            end
            imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), string.format("[%d] %s", templateId, shortcut))
            imgui.TextWrapped("Javob: " .. UtilityManager.toUtf8(tostring(template.text or "")))
            imgui.InputText(
                string.format("Kalit so'zlar (, bilan)##tpl_route_%d_%s", templateId, scopeSuffix),
                routeBuf,
                384
            )
            imgui.Separator()
        end
    end
    imgui.EndChild()

    if imgui.Button(u8"Template auto-mos sozlamani saqlash##tpl_route_save_" .. scopeSuffix, imgui.ImVec2(250, 25)) then
        for _, template in ipairs(ReportCatchManager.templates or {}) do
            local templateId = tonumber(template.id)
            if templateId then
                local key = tostring(templateId)
                local routeBuf = MainUI.buffers.replyKeywordsByTemplate[key]
                local raw = routeBuf and UtilityManager.bufferToString(routeBuf) or ""
                local list = UtilityManager.trim(raw or "")
                ReportCatchManager.setTemplateRouteRaw(templateId, list)
                if routeBuf then
                    UtilityManager.setBufferString(routeBuf, list)
                end
            end
        end
        -- Legacy mirrored fields for old config compatibility.
        ReportCatchManager.settings.templateRouteKeywords1 = ReportCatchManager.getTemplateRouteRaw(1)
        ReportCatchManager.settings.templateRouteKeywords3 = ReportCatchManager.getTemplateRouteRaw(3)
        ReportCatchManager.settings.templateRouteKeywords8 = ReportCatchManager.getTemplateRouteRaw(8)
        ReportCatchManager.saveSettings()
    end

    imgui.TextDisabled(u8"Qoidasi: report matnida kalit so'z bo'lsa popupda AVTO tugmasi mos ID'ni yuboradi.")
    imgui.TextDisabled(u8"Har bir ID uchun: yuqorida template javobi ko'rinadi, pastida o'sha ID trigger kalitlarini kiritasiz.")
end

