function MainUI.isKerakliMenuDisabled()
    return SettingsManager.get("kerakliMenuDisabled") == true
end

local KERAKLI_MENU_SPECIAL_KEY_NAMES = {
    [0xA0] = "LShift",
    [0xA1] = "RShift",
    [0xA2] = "LCtrl",
    [0xA3] = "RCtrl",
    [0xA4] = "LAlt",
    [0xA5] = "RAlt",
    [0x5B] = "LWin",
    [0x5C] = "RWin"
}

local KERAKLI_MENU_CAPTURE_SCAN_KEYS = nil

local function getKerakliMenuCaptureScanKeys()
    if KERAKLI_MENU_CAPTURE_SCAN_KEYS then
        return KERAKLI_MENU_CAPTURE_SCAN_KEYS
    end

    local skipCodes = {
        [0x01] = true, -- LMB
        [0x02] = true, -- RMB
        [0x04] = true, -- MMB
        [0x05] = true, -- XBUTTON1
        [0x06] = true  -- XBUTTON2
    }

    local ordered = {
        0xA3, 0xA2, -- R/L Ctrl
        0xA1, 0xA0, -- R/L Shift
        0xA5, 0xA4, -- R/L Alt
        0x5C, 0x5B  -- R/L Win
    }

    local used = {}
    local list = {}
    for _, code in ipairs(ordered) do
        if not used[code] then
            list[#list + 1] = code
            used[code] = true
        end
    end

    for code = 1, 255 do
        if not skipCodes[code] and not used[code] then
            list[#list + 1] = code
            used[code] = true
        end
    end

    KERAKLI_MENU_CAPTURE_SCAN_KEYS = list
    return KERAKLI_MENU_CAPTURE_SCAN_KEYS
end

function MainUI.getVirtualKeyDisplayName(keyCode)
    local code = math.floor(tonumber(keyCode) or 0)
    if code <= 0 then
        return "OFF"
    end

    local specialName = KERAKLI_MENU_SPECIAL_KEY_NAMES[code]
    if specialName then
        return specialName
    end

    if type(vkeys.id_to_name) == "function" then
        local resolved = tostring(vkeys.id_to_name(code) or "")
        if resolved ~= "" then
            return resolved:gsub("^VK_", "")
        end
    end

    return tostring(code)
end

function MainUI.getKerakliMenuKeyCaptureState()
    if type(MainUI.kerakliMenuKeyCapture) ~= "table" then
        MainUI.kerakliMenuKeyCapture = {
            active = false,
            startedAtMs = 0
        }
    end
    return MainUI.kerakliMenuKeyCapture
end

function MainUI.beginKerakliMenuKeyCapture()
    local state = MainUI.getKerakliMenuKeyCaptureState()
    state.active = true
    state.startedAtMs = UtilityManager.getNowMs()
end

function MainUI.cancelKerakliMenuKeyCapture()
    local state = MainUI.getKerakliMenuKeyCaptureState()
    state.active = false
    state.startedAtMs = 0
end

function MainUI.applyKerakliMenuToggleKey(keyCode)
    local normalized = UtilityManager.clamp(math.floor(tonumber(keyCode) or 0), 0, 255)
    SettingsManager.set("kerakliMenuToggleKey", normalized)
    if MainUI.buffers and MainUI.buffers.kerakliMenuToggleKey then
        MainUI.buffers.kerakliMenuToggleKey[0] = normalized
    end
    if SettingsManager and SettingsManager.save then
        SettingsManager.save()
    end
    MainUI.kerakliMenuHotkeySuppress = normalized > 0
    MainUI.cancelKerakliMenuKeyCapture()
end

function MainUI.updateKerakliMenuKeyCapture(isKeyDownFn, chatActive, dialogActive)
    local state = MainUI.getKerakliMenuKeyCaptureState()
    if not state.active then
        return
    end
    if type(isKeyDownFn) ~= "function" then
        return
    end
    if chatActive or dialogActive then
        return
    end

    local escapeCode = (vkeys and vkeys.VK_ESCAPE) or 0x1B
    local okEscape, escapeDown = pcall(isKeyDownFn, escapeCode)
    if okEscape and escapeDown == true then
        MainUI.cancelKerakliMenuKeyCapture()
        return
    end

    local scanKeys = getKerakliMenuCaptureScanKeys()
    for i = 1, #scanKeys do
        local code = scanKeys[i]
        local okKey, keyDown = pcall(isKeyDownFn, code)
        if okKey and keyDown == true then
            MainUI.applyKerakliMenuToggleKey(code)
            return
        end
    end
end

function MainUI.toggleKerakliMenuDisabled(sourceTag)
    local newState = not MainUI.isKerakliMenuDisabled()
    SettingsManager.set("kerakliMenuDisabled", newState)
    if MainUI.buffers and MainUI.buffers.kerakliMenuToggleKey then
        MainUI.buffers.kerakliMenuToggleKey[0] =
            UtilityManager.clamp(math.floor(tonumber(SettingsManager.get("kerakliMenuToggleKey")) or 0), 0, 255)
    end

    local color = newState and 0xFF9933 or 0x33CC66
    local source = tostring(sourceTag or "toggle")
    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage(
            string.format("[GMEA] Kerakli menyusi: %s (%s)", newState and "OFF" or "ON", source),
            color
        )
    end
end

function MainUI.isFuraMenuDisabled()
    return SettingsManager.get("furaMenuDisabled") == true
end

function MainUI.openKatatsyaPanel()
    MainUI.katatsyaAccess.unlocked = true
    MainUI.katatsyaAccess.popupOpen = false
    MainUI.katatsyaAccess.lastError = ""
    MainUI.katatsyaPanel.open = true
end

function MainUI.katatsyaGetLocalId()
    local id = MainUI.getLocalPlayerId()
    if not id or id < 0 then
        sampAddChatMessage("[GMEA] Katatsya: local player ID topilmadi.", 0xFF6666)
        return nil
    end
    return id
end

local function katatsyaGetLocalActorHandle()
    local actor = rawget(_G, "PLAYER_ACTOR")
    if actor ~= nil and actor ~= false then
        return actor
    end
    actor = rawget(_G, "PLAYER_PED")
    if actor ~= nil and actor ~= false then
        return actor
    end
    return nil
end

local function katatsyaTryGlobalCall(candidates, ...)
    for _, name in ipairs(candidates or {}) do
        local fn = _G[name]
        if type(fn) == "function" then
            local ok, a, b, c, d = pcall(fn, ...)
            if ok then
                return true, tostring(name), a, b, c, d
            end
        end
    end
    return false, nil
end

local function katatsyaExtractCoords(...)
    if TeleportClickManager and type(TeleportClickManager.extractCoords) == "function" then
        return TeleportClickManager.extractCoords(...)
    end

    local a, b, c, d = ...
    if type(a) == "boolean" then
        if not a then
            return nil
        end
        a, b, c = b, c, d
    end

    local x = tonumber(a)
    local y = tonumber(b)
    local z = tonumber(c)
    if x and y and z then
        return x, y, z
    end

    return nil
end

local function katatsyaExtractHandle(...)
    local values = { ... }
    for i = 1, #values do
        local raw = values[i]
        local kind = type(raw)
        if kind == "userdata" or kind == "cdata" then
            return raw
        end
        local value = tonumber(raw)
        if value and value > 0 then
            return math.floor(value)
        end
        if kind == "table" then
            local nested = tonumber(raw.handle or raw.id or raw.car or raw.vehicle)
            if nested and nested > 0 then
                return math.floor(nested)
            end
        end
    end
    return nil
end

local function katatsyaGetPedCoords(ped)
    if type(getCharCoordinates) == "function" then
        local okPos, a, b, c = pcall(getCharCoordinates, ped)
        local x, y, z = katatsyaExtractCoords(okPos, a, b, c)
        if x and y and z then
            return x, y, z
        end
    end

    if type(callOpcode) == "function" then
        local okPos, x, y, z = callOpcode(0x00A0, { ped, 0.0, 0.0, 0.0 })
        local cx, cy, cz = katatsyaExtractCoords(okPos, x, y, z)
        if cx and cy and cz then
            return cx, cy, cz
        end
    end

    return nil
end

function MainUI.katatsyaGiveHp()
    local id = MainUI.katatsyaGetLocalId()
    if not id then
        return
    end
    sendChat(string.format("/hp %d", id))
end

function MainUI.katatsyaGiveArmor()
    local armorValue = math.floor(tonumber(MainUI.buffers.katatsyaArmorValue[0]) or -1)
    if armorValue < 1 or armorValue > 100 then
        sampAddChatMessage("[GMEA] Katatsya: bronya qiymati noto'g'ri (1-100).", 0xFF6666)
        return
    end

    local actor = katatsyaGetLocalActorHandle()
    if not actor then
        sampAddChatMessage("[GMEA] Katatsya: PLAYER_ACTOR topilmadi.", 0xFF6666)
        return
    end

    if type(callOpcode) == "function" then
        RuntimeGuard.call("katatsya.giveArmor", function()
            callOpcode(0x035F, { actor, armorValue })
        end)
        return
    end

    local nativeOk = false
    RuntimeGuard.call("katatsya.giveArmor.native", function()
        local okNative = katatsyaTryGlobalCall({
            "setCharArmour",
            "setCharArmor",
            "setActorArmour",
            "setActorArmor"
        }, actor, armorValue)
        nativeOk = okNative == true
    end)
    if nativeOk then
        return
    end

    local id = MainUI.katatsyaGetLocalId()
    if id then
        sendChat(string.format("/arm %d %d", id, armorValue))
        sampAddChatMessage("[GMEA] Katatsya: opcode yo'q, /arm fallback ishlatildi.", 0x33CC66)
        return
    end

    sampAddChatMessage("[GMEA] Katatsya: opcode/native armor API topilmadi.", 0xFF6666)
end

function MainUI.katatsyaSetSkin()
    local id = MainUI.katatsyaGetLocalId()
    if not id then
        return
    end
    local skinId = math.floor(tonumber(MainUI.buffers.katatsyaSkinId[0]) or -1)
    if skinId < 0 or skinId > 311 then
        sampAddChatMessage("[GMEA] Katatsya: skin ID noto'g'ri (0-311).", 0xFF6666)
        return
    end
    sendChat(string.format("/setskin %d %d", id, skinId))
end

function MainUI.katatsyaGiveWeapon()
    local weaponId = math.floor(tonumber(MainUI.buffers.katatsyaWeaponId[0]) or -1)
    if weaponId < 1 or weaponId > 46 then
        sampAddChatMessage("[GMEA] Katatsya: weapon ID noto'g'ri (1-46).", 0xFF6666)
        return
    end
    if not PLAYER_PED then
        sampAddChatMessage("[GMEA] Katatsya: PLAYER_PED topilmadi.", 0xFF6666)
        return
    end

    if type(callOpcode) == "function" then
        RuntimeGuard.call("katatsya.giveWeapon", function()
            callOpcode(0x01B2, { PLAYER_PED, weaponId, 1000 })
        end)
        return
    end

    local nativeOk = false
    RuntimeGuard.call("katatsya.giveWeapon.native", function()
        local okNative = katatsyaTryGlobalCall({
            "giveWeaponToChar",
            "giveWeaponToActor",
            "giveWeaponToPlayerChar"
        }, PLAYER_PED, weaponId, 1000)
        nativeOk = okNative == true
        if nativeOk then
            katatsyaTryGlobalCall({
                "setCurrentCharWeapon",
                "setCurrentWeaponToChar",
                "setCurrentCharWeaponByType"
            }, PLAYER_PED, weaponId)
        end
    end)
    if nativeOk then
        return
    end

    local id = MainUI.katatsyaGetLocalId()
    if id then
        sendChat(string.format("/gun %d %d %d", id, weaponId, 1000))
        sampAddChatMessage("[GMEA] Katatsya: opcode yo'q, /gun fallback ishlatildi.", 0x33CC66)
        return
    end

    sampAddChatMessage("[GMEA] Katatsya: opcode/native weapon API topilmadi.", 0xFF6666)
end

function MainUI.katatsyaSpawnVehicle()
    local vehicleId = math.floor(tonumber(MainUI.buffers.katatsyaVehicleId[0]) or -1)
    if vehicleId < 400 or vehicleId > 611 then
        sampAddChatMessage("[GMEA] Katatsya: vehicle ID noto'g'ri (400-611).", 0xFF6666)
        return
    end
    if not PLAYER_PED then
        sampAddChatMessage("[GMEA] Katatsya: PLAYER_PED topilmadi.", 0xFF6666)
        return
    end

    local x, y, z = katatsyaGetPedCoords(PLAYER_PED)
    if x == nil or y == nil or z == nil then
        sampAddChatMessage("[GMEA] Katatsya: koordinata olinmadi.", 0xFF6666)
        return
    end

    local spawnX = x
    local spawnY = y
    local spawnZ = z + 1.0

    local car = nil
    RuntimeGuard.call("katatsya.spawnVehicle", function()
        if type(callOpcode) == "function" then
            local okCar, created = callOpcode(0x00A5, { vehicleId, spawnX, spawnY, spawnZ })
            if okCar ~= false then
                car = katatsyaExtractHandle(created)
            end
            if car then
                callOpcode(0x036A, { PLAYER_PED, car })
            end
            return
        end

        local okCreate, _, a, b, c, d = katatsyaTryGlobalCall({
            "createCar",
            "createVehicle"
        }, vehicleId, spawnX, spawnY, spawnZ)
        if okCreate then
            car = katatsyaExtractHandle(a, b, c, d)
            if car then
                katatsyaTryGlobalCall({
                    "warpCharIntoCar",
                    "putCharInCar",
                    "warpCharIntoCarAsDriver"
                }, PLAYER_PED, car)
            end
        end
    end)

    if not car then
        sampAddChatMessage("[GMEA] Katatsya: mashina yaratilmedi.", 0xFF6666)
        return
    end
end

function MainUI.katatsyaFuel100()
    if MainUI.katatsyaPanel.fuelBusy then
        sampAddChatMessage("[GMEA] Katatsya: Fuel jarayoni davom etmoqda...", 0xFF9933)
        return
    end
    if not PLAYER_PED or type(isCharInAnyCar) ~= "function" then
        sampAddChatMessage("[GMEA] Katatsya: mashina topilmadi.", 0xFF6666)
        return
    end
    local okInCar, inCar = pcall(isCharInAnyCar, PLAYER_PED)
    if not okInCar or not inCar then
        sampAddChatMessage("[GMEA] Katatsya: Siz mashinada emassiz.", 0xFF6666)
        return
    end
    if not (lua_thread and type(lua_thread.create) == "function") then
        sampAddChatMessage("[GMEA] Katatsya: thread API topilmadi.", 0xFF6666)
        return
    end
    if TeleportClickManager and TeleportClickManager.dlRequest then
        sampAddChatMessage("[GMEA] Katatsya: /dl band (boshqa jarayon).", 0xFF6666)
        return
    end

    MainUI.katatsyaPanel.fuelBusy = true
    lua_thread.create(function()
        local nowMs = UtilityManager.getNowMs()
        if TeleportClickManager then
            TeleportClickManager.dlObservedVehicleId = nil
            TeleportClickManager.dlObservedAtMs = nowMs
        end
        sendChat("/dl")
        local deadline = nowMs + 2000
        while UtilityManager.getNowMs() <= deadline do
            wait(90)
            local observedId = TeleportClickManager and tonumber(TeleportClickManager.dlObservedVehicleId) or nil
            local observedAt = TeleportClickManager and tonumber(TeleportClickManager.dlObservedAtMs) or 0
            if observedId and observedId > 0 and observedAt >= nowMs then
                sendChat(string.format("/setfuel %d 100", observedId))
                MainUI.katatsyaPanel.fuelBusy = false
                return
            end
        end
        sampAddChatMessage("[GMEA] Katatsya: /dl dan mashina ID topilmadi.", 0xFF6666)
        MainUI.katatsyaPanel.fuelBusy = false
    end)
end

function MainUI.katatsyaGiveJetpack()
    local actor = katatsyaGetLocalActorHandle()
    if not actor then
        sampAddChatMessage("[GMEA] Katatsya: PLAYER_ACTOR topilmadi.", 0xFF6666)
        return
    end

    if type(callOpcode) == "function" then
        RuntimeGuard.call("katatsya.jetpack", function()
            callOpcode(0x07A7, { actor })
        end)
        return
    end

    local nativeOk = false
    RuntimeGuard.call("katatsya.jetpack.native", function()
        local okNative = katatsyaTryGlobalCall({
            "putJetpackOnChar",
            "putJetpackOnActor",
            "giveJetpackToChar",
            "giveJetpackToActor"
        }, actor)
        nativeOk = okNative == true
    end)
    if nativeOk then
        return
    end

    sampAddChatMessage("[GMEA] Katatsya: jetpack opcode/native API topilmadi.", 0xFF6666)
end

