function MainUI.renderKatatsyaPanel()
    if not MainUI.katatsyaPanel.open then
        return
    end

    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.AlwaysAutoResize
    local open = imgui.ImBool(MainUI.katatsyaPanel.open)
    if imgui.Begin("Katatsya Panel", open, flags) then
        local myId = MainUI.getLocalPlayerId()
        imgui.Text(string.format("My ID: %s", tostring(myId or "N/A")))
        imgui.Separator()

        if imgui.Button("HP", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaGiveHp()
        end
        imgui.SameLine()
        imgui.PushItemWidth(120)
        imgui.InputInt("Armor %", MainUI.buffers.katatsyaArmorValue)
        imgui.PopItemWidth()
        MainUI.buffers.katatsyaArmorValue[0] =
            math.max(1, math.min(100, MainUI.buffers.katatsyaArmorValue[0]))
        imgui.SameLine()
        if imgui.Button("Give Armor", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaGiveArmor()
        end

        imgui.Spacing()
        imgui.InputInt("Weapon ID", MainUI.buffers.katatsyaWeaponId)
        MainUI.buffers.katatsyaWeaponId[0] = math.max(0, math.min(46, MainUI.buffers.katatsyaWeaponId[0]))
        if imgui.Button("Give Weapon", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaGiveWeapon()
        end

        imgui.Spacing()
        imgui.InputInt("Vehicle ID", MainUI.buffers.katatsyaVehicleId)
        MainUI.buffers.katatsyaVehicleId[0] = math.max(400, math.min(611, MainUI.buffers.katatsyaVehicleId[0]))
        if imgui.Button("Spawn Vehicle", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaSpawnVehicle()
        end

        imgui.Spacing()
        imgui.InputInt("Skin ID", MainUI.buffers.katatsyaSkinId)
        MainUI.buffers.katatsyaSkinId[0] = math.max(0, math.min(311, MainUI.buffers.katatsyaSkinId[0]))
        if imgui.Button("Set Skin", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaSetSkin()
        end

        imgui.Spacing()
        if imgui.Button("Fuel 100", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaFuel100()
        end
        imgui.SameLine()
        if imgui.Button("Jetpack", imgui.ImVec2(140, 26)) then
            MainUI.katatsyaGiveJetpack()
        end
    end
    MainUI.katatsyaPanel.open = open[0]
    imgui.End()
end
function MainUI.renderKerakliProtected(scopeSuffix)
    if not MainUI.renderKerakliAccessGuard(scopeSuffix) then
        return
    end

    local suffix = tostring(scopeSuffix or "main")
    local disabled = imgui.ImBool(MainUI.isKerakliMenuDisabled())
    if imgui.Checkbox(u8"Kerakli menyusini to'liq o'chirish##kerakli_disable_" .. suffix, disabled) then
        SettingsManager.set("kerakliMenuDisabled", disabled[0])
    end
    local keyBuffer = MainUI.buffers and MainUI.buffers.kerakliMenuToggleKey
    if not keyBuffer and MainUI.buffers then
        MainUI.buffers.kerakliMenuToggleKey = imgui.ImInt(tonumber(SettingsManager.get("kerakliMenuToggleKey")) or 0)
        keyBuffer = MainUI.buffers.kerakliMenuToggleKey
    end
    if keyBuffer then
        local captureState = MainUI.getKerakliMenuKeyCaptureState()
        local keyCode = UtilityManager.clamp(math.floor(tonumber(keyBuffer[0]) or 0), 0, 255)
        local keyName = MainUI.getVirtualKeyDisplayName(keyCode)

        if captureState.active then
            if imgui.Button(u8"Tugmani bosing...##kerakli_disable_key_capture_" .. suffix, imgui.ImVec2(170, 0)) then
            end
            imgui.SameLine()
            if imgui.Button(u8"Bekor qilish##kerakli_disable_key_cancel_" .. suffix, imgui.ImVec2(110, 0)) then
                MainUI.cancelKerakliMenuKeyCapture()
            end
            imgui.TextDisabled(u8"ESC bosilsa bekor qilinadi. Chap/o'ng Ctrl/Shift/Alt alohida saqlanadi.")
        else
            if imgui.Button(u8"Tugmani tanlash##kerakli_disable_key_capture_" .. suffix, imgui.ImVec2(170, 0)) then
                MainUI.beginKerakliMenuKeyCapture()
            end
            imgui.SameLine()
            if imgui.Button(u8"Tozalash##kerakli_disable_key_clear_" .. suffix, imgui.ImVec2(110, 0)) then
                MainUI.applyKerakliMenuToggleKey(0)
            end
        end
        imgui.TextDisabled("Hotkey: " .. keyName)
    end
    if MainUI.isKerakliMenuDisabled() then
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"Kerakli menyusi o'chirilgan. Funksiyalar vaqtincha ishlamaydi.")
        return
    end

    imgui.Separator()
    MainUI.renderKerakliControls({ scopeSuffix = tostring(scopeSuffix or "kerakli") })
end

function MainUI.renderKerakli()
    imgui.TextColored(COLORS.WARNING, u8"KERAKLI")
    imgui.TextDisabled(u8"Bu bo'lim admin menyuda alohida tab sifatida chiqarildi.")
    imgui.Separator()
    MainUI.renderKerakliProtected("tab")
end

function MainUI.renderAiHelperControls(scopeSuffix)
    local suffix = tostring(scopeSuffix or "ai")

    local aiEnabled = imgui.ImBool(ReportCatchManager.settings.aiAutoReportEnabled == true)
    if imgui.Checkbox(u8"AI avtomatik javobni yoqish##ai_enable_" .. suffix, aiEnabled) then
        ReportCatchManager.settings.aiAutoReportEnabled = aiEnabled[0]
        ReportCatchManager.saveSettings()
    end

    local uniqueOnly = imgui.ImBool(ReportCatchManager.settings.aiAutoReportRequireUnique ~= false)
    if imgui.Checkbox(u8"Faqat yagona eng mos natija##ai_unique_" .. suffix, uniqueOnly) then
        ReportCatchManager.settings.aiAutoReportRequireUnique = uniqueOnly[0]
        ReportCatchManager.saveSettings()
    end

    local skipPopup = imgui.ImBool(ReportCatchManager.settings.aiAutoReportSkipPopup ~= false)
    if imgui.Checkbox(u8"AI javob bersa popupni yopish##ai_skip_popup_" .. suffix, skipPopup) then
        ReportCatchManager.settings.aiAutoReportSkipPopup = skipPopup[0]
        ReportCatchManager.saveSettings()
    end

    local cooldown = imgui.ImInt(tonumber(ReportCatchManager.settings.aiAutoReportCooldownSec) or 3)
    if imgui.InputInt(u8"AI kutish vaqti (sekund)##ai_cooldown_" .. suffix, cooldown) then
        ReportCatchManager.settings.aiAutoReportCooldownSec =
            math.max(1, math.min(30, tonumber(cooldown[0]) or 3))
        ReportCatchManager.saveSettings()
    end

    local runtime = ReportCatchManager.aiAutoRuntime or {}
    local lastDecision = tostring(runtime.lastDecision or "")
    if lastDecision ~= "" then
        imgui.TextWrapped("So'nggi qaror: " .. UtilityManager.toUtf8(lastDecision))
    else
        imgui.TextDisabled(u8"So'nggi qaror: hali ishlamagan")
    end
    imgui.TextDisabled(u8"AI kalit so'zlar manbasi: Kerakli -> Report -> Template Auto Mos")
end

function MainUI.renderAiHelper()
    if RulesAiManager and RulesAiManager.setActive then
        RulesAiManager.setActive(true)
    end

    imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"AI YORDAMCHI")
    imgui.TextDisabled(u8"Local AI report matniga qarab eng mos template javobini yuboradi.")
    imgui.Separator()
    MainUI.renderAiHelperControls("tab")

    imgui.Separator()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"RULES AI")
    imgui.TextDisabled(u8"Band yoki vaziyat yozing: 5.2, cheat ishlatgan, o'yinchi sokindi, reklama tashladi")
    imgui.InputText(u8"So'rov##rules_ai_query", MainUI.buffers.aiRulesQuery, 512)

    local disabledScope = false
    if RulesAiManager and RulesAiManager.pending and imgui.BeginDisabled then
        imgui.BeginDisabled()
        disabledScope = true
    end
    if imgui.Button(u8"Tekshirish##rules_ai_ask", imgui.ImVec2(160, 30)) then
        local query = UtilityManager.bufferToString(MainUI.buffers.aiRulesQuery) or ""
        if RulesAiManager and RulesAiManager.ask then
            local okAsk, errAsk = RulesAiManager.ask(query)
            if not okAsk and errAsk and type(sampAddChatMessage) == "function" then
                sampAddChatMessage("[GMEA] Rules AI: " .. tostring(errAsk), 0xFF6666)
            end
        end
    end
    if disabledScope and imgui.EndDisabled then
        imgui.EndDisabled()
    end

    if RulesAiManager and RulesAiManager.pending then
        imgui.SameLine()
        imgui.TextDisabled(u8"Tekshirilmoqda...")
    end

    if RulesAiManager and RulesAiManager.lastError and RulesAiManager.lastError ~= "" then
        imgui.TextColored(COLORS.DANGER or imgui.ImVec4(0.90, 0.30, 0.30, 1.0), u8(RulesAiManager.lastError))
    end

    local rulesResult = RulesAiManager and RulesAiManager.result or nil
    if rulesResult then
        imgui.Separator()
        if rulesResult.band then
            imgui.TextColored(COLORS.PRIMARY or imgui.ImVec4(0.15, 0.68, 0.38, 1.0),
                u8("Band: " .. tostring(rulesResult.band)))
        else
            imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"Band: topilmadi")
        end
        if rulesResult.section and rulesResult.section ~= "" then
            imgui.TextWrapped(u8("Bo'lim: " .. tostring(rulesResult.section)))
        end
        if rulesResult.title and rulesResult.title ~= "" then
            imgui.TextWrapped(u8("Sarlavha: " .. tostring(rulesResult.title)))
        end
        if rulesResult.punishment and rulesResult.punishment ~= "" then
            imgui.TextWrapped(u8("Jazo: " .. tostring(rulesResult.punishment)))
        end
        if rulesResult.explanation and rulesResult.explanation ~= "" then
            imgui.TextWrapped(u8("Izoh: " .. tostring(rulesResult.explanation)))
        end
        if rulesResult.confidence and rulesResult.confidence ~= "" then
            imgui.TextDisabled(u8("Ishonchlilik: " .. tostring(rulesResult.confidence)))
        end

        local nearestMatches = rulesResult.nearest_matches or {}
        if #nearestMatches > 0 then
            imgui.Separator()
            imgui.TextColored(COLORS.SECONDARY or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Yaqin variantlar")
            for _, match in ipairs(nearestMatches) do
                local band = tostring(match.band or "?")
                local title = tostring(match.title or "")
                imgui.BulletText(u8(string.format("%s - %s", band, title)))
            end
        end
    end
end

function MainUI.normalizeMpMessageLine(text)
    local value = UtilityManager.trim(tostring(text or ""))
    if value == "" then
        return ""
    end

    value = value:gsub("^/[Mm][Ss][Gg]%s*", "")
    return UtilityManager.trim(value)
end

function MainUI.getMpEventName()
    local eventName = UtilityManager.trim(UtilityManager.bufferToString(MainUI.buffers.mpEventName) or "")
    if eventName == "" then
        eventName = "Go'sht maydalagich"
        UtilityManager.setBufferString(MainUI.buffers.mpEventName, eventName)
    end
    return eventName
end

function MainUI.buildMpReklamaLines()
    local eventName = MainUI.getMpEventName()
    return {
        "Assalomu alaykum, aziz o'yinchilar!",
        string.format("\"%s\" tadbiri boshlanish arafasida.", eventName),
        "Ishtirok etish uchun hisobotingizga \"+\" belgisini yozing.",
        "Teleportatsiyadan so'ng siz stroy turishingiz kerak!",
        "Sovrin jamg'armasi: 50 000 rubl."
    }
end

function MainUI.getMpRouteValue(buffer, fallback)
    local value = UtilityManager.trim(UtilityManager.bufferToString(buffer) or "")
    if value == "" then
        value = tostring(fallback or "")
        UtilityManager.setBufferString(buffer, value)
    end
    return value
end

function MainUI.buildMpRouteMessage()
    local fromValue = MainUI.getMpRouteValue(MainUI.buffers.mpRouteFrom, SettingsManager.get("mpRouteFrom") or "Edovo")
    local toValue = MainUI.getMpRouteValue(MainUI.buffers.mpRouteTo, SettingsManager.get("mpRouteTo") or "Arzamas")
    return string.format("Biz %s dan %s ga yo'lga chiqyapmiz", fromValue, toValue)
end

function MainUI.saveMpRouteSettings()
    local fromValue = MainUI.getMpRouteValue(MainUI.buffers.mpRouteFrom, "Edovo")
    local toValue = MainUI.getMpRouteValue(MainUI.buffers.mpRouteTo, "Arzamas")
    SettingsManager.set("mpRouteFrom", fromValue)
    SettingsManager.set("mpRouteTo", toValue)
    SettingsManager.save()
    sampAddChatMessage("[GMEA] MP yo'l matni saqlandi.", 0x33FF66)
end

function MainUI.getLocalPlayerId()
    if not PLAYER_PED or type(sampGetPlayerIdByCharHandle) ~= "function" then
        return nil
    end

    local ok, a, b = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not ok then
        return nil
    end

    if type(a) == "boolean" then
        if a then
            return tonumber(b)
        end
        return nil
    end

    return tonumber(a)
end

function MainUI.getPlayerPedHandleById(playerId)
    local id = tonumber(playerId)
    if not id then
        return nil
    end

    if ReportCatchManager and type(ReportCatchManager.getPlayerPedHandle) == "function" then
        local ped = ReportCatchManager.getPlayerPedHandle(id)
        if ped and type(ped) == "number" and ped > 0 then
            return ped
        end
        return nil
    end

    if type(sampGetCharHandleBySampPlayerId) ~= "function" then
        return nil
    end

    local ok, a, b = pcall(sampGetCharHandleBySampPlayerId, id)
    if not ok then
        return nil
    end

    local handle = nil
    if type(a) == "boolean" then
        if a then
            handle = tonumber(b)
        end
    else
        handle = tonumber(a)
    end

    if not handle or handle <= 0 then
        return nil
    end

    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, handle)
        if not okExists or not exists then
            return nil
        end
    end

    return handle
end

function MainUI.collectPlayersInRadius(radiusValue, options)
    options = type(options) == "table" and options or {}
    local radius = math.max(1, math.floor(tonumber(radiusValue) or 0))
    -- safety fix: preserve legacy 3000 clamp for existing actions, allow explicit unlimited radius where needed.
    if options.unlimited ~= true then
        radius = math.min(3000, radius)
    end
    local hasLocalCoords, localX, localY, localZ = UtilityManager.getPlayerCoords()
    if not hasLocalCoords then
        return {}, radius
    end

    if type(sampGetMaxPlayerId) ~= "function" or type(sampIsPlayerConnected) ~= "function" then
        return {}, radius
    end

    local maxPlayerId = UtilityManager.getMaxPlayerIdSafe(1000)

    local localPlayerId = MainUI.getLocalPlayerId()
    local targets = {}

    for i = 0, maxPlayerId do
        local okConn, isConn = pcall(sampIsPlayerConnected, i)
        if okConn and isConn and (not localPlayerId or i ~= localPlayerId) then
            local px, py, pz = UtilityManager.getPlayerWorldCoordsById(i)
            if px and py and pz then
                local dx = px - localX
                local dy = py - localY
                local dz = pz - localZ
                local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
                if distance <= radius then
                    table.insert(targets, i)
                end
            end
        end
    end

    return targets, radius
end

function MainUI.isProtectedAdminTarget(playerId)
    local id = tonumber(playerId)
    if not id or id < 0 then
        return false
    end

    if AdminRelayManager and type(AdminRelayManager.isAdminTarget) == "function" then
        local okAdmin, isAdmin = pcall(AdminRelayManager.isAdminTarget, id)
        if okAdmin and isAdmin == true then
            return true
        end
    end

    local nick = UtilityManager.getPlayerNicknameSafe(id, "")
    if ReportCatchManager and type(ReportCatchManager.isAdminKnown) == "function" then
        local okKnown, isKnown = pcall(ReportCatchManager.isAdminKnown, id, nick)
        if okKnown and isKnown == true then
            return true
        end
    end

    if AdminCheckerManager and type(AdminCheckerManager.findEntry) == "function" then
        local okEntry, entry = pcall(AdminCheckerManager.findEntry, id)
        if okEntry and type(entry) == "table" then
            return true
        end
    end

    return false
end

function MainUI.executeRadiusCommand(title, radiusValue, commandBuilder, options)
    options = type(options) == "table" and options or {}
    if type(sampSendChat) ~= "function" then
        sampAddChatMessage("[MP] Chat API topilmadi.", 0xFF6666)
        return
    end

    if type(commandBuilder) ~= "function" then
        return
    end

    local targets, radius = MainUI.collectPlayersInRadius(radiusValue, options)
    local skippedAdmins = 0
    local filteredTargets = {}
    local filterTarget = type(options.filterTarget) == "function" and options.filterTarget or nil

    for _, playerId in ipairs(targets) do
        local include = true
        local skipReason = nil
        if filterTarget then
            local okFilter, valueInclude, valueReason = pcall(filterTarget, playerId)
            if okFilter and valueInclude == false then
                include = false
                skipReason = tostring(valueReason or "")
            end
        end

        if include then
            table.insert(filteredTargets, playerId)
        elseif skipReason == "admin" then
            skippedAdmins = skippedAdmins + 1
        end
    end

    targets = filteredTargets
    if #targets == 0 then
        local message = string.format("[MP] Radius %d ichida o'yinchi topilmadi.", radius)
        if skippedAdmins > 0 then
            message = string.format("[MP] Radius %d ichida faqat adminlar topildi. Skip qilindi: %d", radius, skippedAdmins)
        end
        sampAddChatMessage(message, 0xFF9933)
        return
    end

    local sendAll = function()
        for _, playerId in ipairs(targets) do
            local okBuild, command = pcall(function()
                return UtilityManager.trim(tostring(commandBuilder(playerId) or ""))
            end)
            if okBuild and type(command) == "string" and command ~= "" then
                local okSend = pcall(sendChat, command)
                if not okSend and LogManager and LogManager.system then
                    LogManager.system(string.format("[MP] sendChat xato: %s", tostring(command)))
                end
                if type(wait) == "function" then
                    wait(0)
                end
            end
        end
    end

    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(sendAll)
    else
        sendAll()
    end

    local summary = string.format("[MP] %s bajarildi: radius %d, nishonlar %d", tostring(title or "Amal"), radius, #targets)
    if skippedAdmins > 0 then
        summary = summary .. string.format(" | admin skip: %d", skippedAdmins)
    end
    sampAddChatMessage(summary, 0x33FF66)
    LogManager.admin(string.format("MP radius action: %s (radius=%d, targets=%d, adminSkipped=%d)", tostring(title or "action"), radius, #targets, skippedAdmins))
end

function MainUI.sendRadiusGun()
    local radius = math.max(1, tonumber(MainUI.buffers.mpGunRadius[0]) or 0)
    local weaponId = math.max(0, tonumber(MainUI.buffers.mpGunId[0]) or 0)
    local ammo = math.max(1, tonumber(MainUI.buffers.mpGunAmmo[0]) or 1)
    MainUI.executeRadiusCommand("Aruja berish (/gun)", radius, function(playerId)
        return string.format("/gun %d %d %d", playerId, weaponId, ammo)
    end)
end

function MainUI.sendRadiusRemoveGun()
    local radius = math.max(1, tonumber(MainUI.buffers.mpRgunRadius[0]) or 0)
    MainUI.executeRadiusCommand("Arujani olish (/rgun)", radius, function(playerId)
        return string.format("/rgun %d", playerId)
    end)
end

function MainUI.sendRadiusSilentKick()
    local radius = math.max(1, tonumber(MainUI.buffers.mpSkickRadius[0]) or 0)
    local reason = UtilityManager.trim(UtilityManager.bufferToString(MainUI.buffers.mpSkickReason) or "")
    if reason == "" then
        reason = "MP"
        UtilityManager.setBufferString(MainUI.buffers.mpSkickReason, reason)
    end
    MainUI.executeRadiusCommand("Silent kick (/skick)", radius, function(playerId)
        return string.format("/skick %d %s", playerId, reason)
    end, {
        filterTarget = function(playerId)
            if MainUI.isProtectedAdminTarget(playerId) then
                return false, "admin"
            end
            return true
        end
    })
end

function MainUI.sendRadiusSpawn()
    local radius = math.max(1, tonumber(MainUI.buffers.mpSpawnRadius[0]) or 0)
    MainUI.executeRadiusCommand("Spawn berish (/spawn)", radius, function(playerId)
