function MainUI.sendMpBroadcast(lines, title)
    if type(lines) ~= "table" or #lines == 0 then
        return
    end

    if type(sampSendChat) ~= "function" then
        sampAddChatMessage("[GMEA] /msg API topilmadi.", 0xFF6666)
        return
    end

    local sendAll = function()
        for _, rawLine in ipairs(lines) do
            local line = MainUI.normalizeMpMessageLine(rawLine)
            if line ~= "" then
                sendChat("/msg " .. line)
                if type(wait) == "function" then
                    wait(0)
                end
            end
        end
    end

    if lua_thread and type(lua_thread.create) == "function" then
        lua_thread.create(sendAll)
    else
        sendAll()
    end

    sampAddChatMessage(string.format("[GMEA] %s yuborildi (%d ta /msg)", tostring(title or "Reklama"), #lines), 0x33FF66)
end

function MainUI.renderMpBroadcastBlock(title, lines, suffix)
    local blockTitle = tostring(title or "Reklama")
    local blockSuffix = tostring(suffix or "default")
    local list = type(lines) == "table" and lines or {}

    if imgui.CollapsingHeader(blockTitle .. "##mp_block_" .. blockSuffix) then
        imgui.BeginChild("##mp_lines_" .. blockSuffix, imgui.ImVec2(0, 120), true)
        for i, rawLine in ipairs(list) do
            local line = MainUI.normalizeMpMessageLine(rawLine)
            if line ~= "" then
                imgui.BulletText(string.format("%d) %s", i, line))
            end
        end
        imgui.EndChild()

        if imgui.Button("Yuborish##mp_send_" .. blockSuffix, imgui.ImVec2(140, 30)) then
            MainUI.sendMpBroadcast(list, blockTitle)
        end
        imgui.SameLine()
        imgui.TextDisabled(string.format("%d ta xabar", #list))
    end
end

function MainUI.renderMpRouteBroadcastBlock()
    imgui.Text(u8"Yo'nalish xabari")
    imgui.InputText(u8"Qayerdan##mp_route_from", MainUI.buffers.mpRouteFrom, 64)
    imgui.InputText(u8"Qayerga##mp_route_to", MainUI.buffers.mpRouteTo, 64)

    local preview = MainUI.buildMpRouteMessage()
    imgui.BeginChild("##mp_route_preview", imgui.ImVec2(0, 58), true)
    imgui.TextWrapped(u8(preview))
    imgui.EndChild()

    if imgui.Button(u8"Saqlash##mp_route_save", imgui.ImVec2(120, 30)) then
        MainUI.saveMpRouteSettings()
    end
    imgui.SameLine()
    if imgui.Button(u8"Yuborish##mp_route_send", imgui.ImVec2(140, 30)) then
        MainUI.sendMpBroadcast({ preview }, "Yo'nalish xabari")
    end
end

