function MainUI.renderPlayerManagement()
    MainUI.playerManagementView = MainUI.playerManagementView or "main"
    if MainUI.playerManagementView == "fw" and not (FwPunishmentManager and FwPunishmentManager.enabled) then
        MainUI.playerManagementView = "main"
    end
    if MainUI.playerManagementView == "fura" and not (FuraPunishmentManager and FuraPunishmentManager.enabled) then
        MainUI.playerManagementView = "main"
    end
    if MainUI.playerManagementView == "bw" and not (BwPunishmentManager and BwPunishmentManager.enabled) then
        MainUI.playerManagementView = "main"
    end

    imgui.Columns(2, "##player_management_layout", false)

    imgui.BeginChild("##player_management_nav", imgui.ImVec2(220, 0), true)
    imgui.TextColored(COLORS.INFO, "PLAYER MGMT")
    imgui.Separator()

    local views = {
        { id = "main", label = "Player Actions" },
        { id = "checker", label = "Admin Checker" },
        { id = "auto_punish", label = "Auto Jazolar" },
        { id = "semya", label = u8"Semya Qidiruv" }
    }
    if FwPunishmentManager and FwPunishmentManager.enabled then
        views[#views + 1] = { id = "fw", label = "FW" }
    end
    if FuraPunishmentManager and FuraPunishmentManager.enabled then
        views[#views + 1] = { id = "fura", label = "FURA" }
    end
    if BwPunishmentManager and BwPunishmentManager.enabled then
        views[#views + 1] = { id = "bw", label = "BW" }
    end

    for _, view in ipairs(views) do
        local selected = MainUI.playerManagementView == view.id
        if imgui.Selectable(view.label, selected) then
            MainUI.playerManagementView = view.id
        end
    end
    imgui.EndChild()

    imgui.NextColumn()

    imgui.BeginChild("##player_management_panel", imgui.ImVec2(0, 0), true)
    if MainUI.playerManagementView == "checker" then
        MainUI.renderAdminCheckerSection(true)
    elseif MainUI.playerManagementView == "fw" then
        MainUI.renderFwPunishmentSection()
    elseif MainUI.playerManagementView == "fura" then
        MainUI.renderFuraPunishmentSection()
    elseif MainUI.playerManagementView == "bw" then
        MainUI.renderBwPunishmentSection()
    elseif MainUI.playerManagementView == "auto_punish" then
        MainUI.renderAutoPunishmentSection()
    elseif MainUI.playerManagementView == "semya" then
        if FamilyTracker and FamilyTracker.renderSearchPanel then
            FamilyTracker.renderSearchPanel()
        end
    else
        MainUI.renderPlayerManagementMainView()
    end
    imgui.EndChild()

    imgui.Columns(1)
end

function MainUI.renderPlayerLog()
    PlayerLogManager.update()
    if not PlayerLogManager.uiOpenLogged then
        PlayerLogManager.uiOpenLogged = true
        PlayerLogManager.logAdminEvent("Admin opened Player Log")
    end

    imgui.Columns(2, "##playerlog_layout", false)

    imgui.BeginChild("##playerlog_nav", imgui.ImVec2(220, 0), true)
    imgui.TextColored(COLORS.INFO, "PLAYER LOG")
    imgui.Separator()

    local views = {
        { id = "search", label = "Player Search", log = "Admin opened Player Search" },
        { id = "alt", label = "ALT Accounts", log = "Admin viewed ALT accounts" },
        { id = "economy", label = "Economy Analysis", log = "Admin inspected economy" },
        { id = "items", label = "Item & Asset History", log = "Admin viewed item/asset history" },
        { id = "admin", label = "Admin Security Log", log = "Admin opened Admin Security Log" },
        { id = "chat", label = "Server Chat Log", log = "Admin opened Server Chat Log" },
        { id = "kill", label = "Kill List", log = "Admin opened Kill List" }
    }
    for _, view in ipairs(views) do
        local selected = PlayerLogManager.currentView == view.id
        if imgui.Selectable(view.label, selected) then
            PlayerLogManager.currentView = view.id
            if PlayerLogManager.lastLoggedView ~= view.id then
                PlayerLogManager.lastLoggedView = view.id
                PlayerLogManager.logAdminEvent(view.log)
            end
        end
    end
    imgui.EndChild()

    imgui.NextColumn()

    imgui.BeginChild("##playerlog_panel", imgui.ImVec2(0, 0), true)
    if PlayerLogManager.currentView == "search" then
        MainUI.renderPlayerLogSearchView()
    elseif PlayerLogManager.currentView == "alt" then
        MainUI.renderPlayerLogAltView()
    elseif PlayerLogManager.currentView == "economy" then
        MainUI.renderPlayerLogEconomyView()
    elseif PlayerLogManager.currentView == "items" then
        MainUI.renderPlayerLogItemsView()
    elseif PlayerLogManager.currentView == "admin" then
        MainUI.renderPlayerLogAdminLogView()
    elseif PlayerLogManager.currentView == "chat" then
        MainUI.renderServerChatLogView()
    elseif PlayerLogManager.currentView == "kill" then
        MainUI.renderKillListLogView()
    end
    imgui.EndChild()

    imgui.Columns(1)
end

function MainUI.renderKillListLogView()
    local styleColorCount = 0
    local styleVarCount = 0
    if imgui.PushStyleColor then
        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.09, 0.03, 0.04, 0.82))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0.56, 0.10, 0.14, 0.96))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0.12, 0.04, 0.06, 0.92))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.FrameBgHovered, imgui.ImVec4(0.16, 0.05, 0.07, 0.95))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.FrameBgActive, imgui.ImVec4(0.19, 0.06, 0.08, 0.98))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.14, 0.04, 0.06, 0.94))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.20, 0.06, 0.08, 0.98))
        styleColorCount = styleColorCount + 1
        imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.24, 0.07, 0.10, 1.00))
        styleColorCount = styleColorCount + 1
    end
    if imgui.PushStyleVar and imgui.StyleVar then
        if imgui.StyleVar.ChildRounding then
            imgui.PushStyleVar(imgui.StyleVar.ChildRounding, 10)
            styleVarCount = styleVarCount + 1
        end
        if imgui.StyleVar.FrameRounding then
            imgui.PushStyleVar(imgui.StyleVar.FrameRounding, 10)
            styleVarCount = styleVarCount + 1
        end
        if imgui.StyleVar.FrameBorderSize then
            imgui.PushStyleVar(imgui.StyleVar.FrameBorderSize, 1)
            styleVarCount = styleVarCount + 1
        end
    end

    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.95, 0.40, 0.44, 1.0), "Kill List")
    imgui.TextDisabled("Kunlik kill loglar shu yerda saqlanadi.")
    imgui.BeginChild("##playerlog_kill_settings", imgui.ImVec2(0, 92), true)
    local overlayEnabled = imgui.ImBool(SettingsManager.get("killListOverlayEnabled") == true)
    if imgui.Checkbox(u8"Kill List overlay##playerlog_kill_overlay", overlayEnabled) then
        SettingsManager.set("killListOverlayEnabled", overlayEnabled[0])
        if KillListManager and KillListManager.flushOverlayState then
            KillListManager.flushOverlayState(true)
        end
        SettingsManager.save()
    end
    imgui.TextDisabled("Overlay yoqilsa ekranda ko'rinadi, o'chsa faqat log yozilishi davom etadi.")
    imgui.TextDisabled("Kill loglar restartdan keyin ham kunlar bo'yicha saqlanadi.")
    imgui.EndChild()

    imgui.Spacing()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.95, 0.40, 0.44, 1.0), "KUNLIK LOG LENTASI")
    imgui.InputText(u8"Qidiruv##kill_list_log_search", MainUI.buffers.killListSearch, 96)
    imgui.SameLine()
    if imgui.Button(u8"Tozalash##kill_list_log_search_clear", imgui.ImVec2(110, 28)) then
        UtilityManager.setBufferString(MainUI.buffers.killListSearch, "")
    end
    imgui.TextDisabled("Nik, ID, sana yoki vaqt bo'yicha qidiring.")
    imgui.BeginChild("##playerlog_kill_logs_panel", imgui.ImVec2(0, 0), true)
    if KillListManager and KillListManager.renderLogsSection then
        KillListManager.renderLogsSection(1.0, {
            embedded = true,
            query = UtilityManager.bufferToString(MainUI.buffers.killListSearch)
        })
    end
    imgui.EndChild()

    if styleVarCount > 0 and imgui.PopStyleVar then
        imgui.PopStyleVar(styleVarCount)
    end
    if styleColorCount > 0 and imgui.PopStyleColor then
        imgui.PopStyleColor(styleColorCount)
    end
end

