function MainUI.renderPlayerLogQuickActions(data)
    if not data then
        return
    end
    local pid = tonumber(data.profile.playerId) or 0
    if pid <= 0 then
        return
    end
    imgui.TextColored(COLORS.WARNING, "ADMIN QUICK ACTIONS")
    if imgui.Button("SPEC", imgui.ImVec2(80, 25)) then
        PlayerManager.spectate(pid)
    end
    imgui.SameLine()
    if imgui.Button("TELEPORT", imgui.ImVec2(90, 25)) then
        PlayerManager.teleportTo(pid)
    end
    imgui.SameLine()
    if imgui.Button("FREEZE", imgui.ImVec2(80, 25)) then
        PlayerManager.freeze(pid)
    end
    imgui.SameLine()
    if imgui.Button("JAIL", imgui.ImVec2(80, 25)) then
        PlayerManager.jail(pid, MainUI.buffers.duration[0], UtilityManager.bufferToString(MainUI.buffers.reason))
    end
    imgui.SameLine()
    if imgui.Button("MUTE", imgui.ImVec2(80, 25)) then
        PlayerManager.mute(pid, MainUI.buffers.duration[0], UtilityManager.bufferToString(MainUI.buffers.reason))
    end
    imgui.SameLine()
    if imgui.Button("BAN", imgui.ImVec2(80, 25)) then
        PlayerManager.ban(pid, UtilityManager.bufferToString(MainUI.buffers.reason))
    end
    imgui.Separator()
end

function MainUI.renderPlayerLogProfileSummary(data)
    if not data then
        imgui.TextDisabled("No player selected.")
        return
    end
    if PlayerLogManager and PlayerLogManager.hydrateOnlineProfile then
        PlayerLogManager.hydrateOnlineProfile(data)
    else
        local pid = tonumber(data.profile.playerId) or 0
        if sampIsPlayerConnected(pid) then
            data.profile.ping = tostring(sampGetPlayerPing(pid))
            local currentNick = sampGetPlayerNickname(pid)
            if currentNick and currentNick ~= "" then
                data.profile.nickname = currentNick
            end
        end
    end
    imgui.TextColored(COLORS.INFO, "PLAYER PROFILE")
    imgui.Text(string.format("Nickname: %s", tostring(data.profile.nickname)))
    imgui.Text(string.format("Player ID: %s", tostring(data.profile.playerId)))
    imgui.Text(string.format("Ping: %s", tostring(data.profile.ping)))
    imgui.Text(string.format("Level: %s", tostring(data.profile.level)))
    local hasExtendedData = tostring(data.profile.accountId or "N/A") ~= "N/A"
        or tostring(data.profile.ip or "N/A") ~= "N/A"
        or tostring(data.profile.registerDate or "N/A") ~= "N/A"
        or tostring(data.profile.lastLogin or "N/A") ~= "N/A"
        or tostring(data.profile.playtime or "N/A") ~= "N/A"
        or tostring(data.profile.adminLevel or "N/A") ~= "N/A"
    if hasExtendedData then
        imgui.Text(string.format("Account ID: %s", tostring(data.profile.accountId)))
        imgui.Text(string.format("IP Address: %s", tostring(data.profile.ip)))
        imgui.Text(string.format("Register Date: %s", tostring(data.profile.registerDate)))
        imgui.Text(string.format("Last Login: %s", tostring(data.profile.lastLogin)))
        imgui.Text(string.format("Playtime: %s", tostring(data.profile.playtime)))
        imgui.Text(string.format("Admin Level: %s", tostring(data.profile.adminLevel)))
    else
        imgui.TextDisabled("Qo'shimcha ma'lumot /offstats va /stats javobidan to'ldiriladi.")
    end
end

function MainUI.renderPlayerLogSearchView()
    imgui.TextColored(COLORS.INFO, "PLAYER SEARCH SYSTEM")
    imgui.InputText("Search##playerlog_search_input", MainUI.buffers.playerLogSearch, 64)
    imgui.SameLine()
    if imgui.Button("Search##playerlog_search_button", imgui.ImVec2(90, 25)) then
        local query = UtilityManager.trim(UtilityManager.bufferToString(MainUI.buffers.playerLogSearch) or "")
        if query ~= "" then
            PlayerLogManager.performSearch(query)
        end
    end
    imgui.SameLine()
    if imgui.Button("Refresh##playerlog_search_refresh", imgui.ImVec2(90, 25)) then
        local data = PlayerLogManager.getSelectedData()
        if data then
            PlayerLogManager.requestSnapshot(data.profile.playerId, data.profile.nickname)
        end
    end
    imgui.TextDisabled("Examples: Hikmatillo | 24 | 185.121.44.23")

    imgui.Separator()
    imgui.TextColored(COLORS.INFO, "SEARCH RESULTS")
    imgui.BeginChild("##playerlog_search_results", imgui.ImVec2(0, 170), true)
    local results = PlayerLogManager.searchState.results or {}
    if imgui.BeginTable then
        local tableFlags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##pl_search_table", 8, tableFlags) then
            imgui.TableSetupColumn("Nickname")
            imgui.TableSetupColumn("Player ID")
            imgui.TableSetupColumn("IP Address")
            imgui.TableSetupColumn("Ping")
            imgui.TableSetupColumn("Level")
            imgui.TableSetupColumn("Register")
            imgui.TableSetupColumn("Last Login")
            imgui.TableSetupColumn("Playtime")
            imgui.TableHeadersRow()
            if #results == 0 then
                imgui.TableNextRow()
                imgui.TableSetColumnIndex(0)
                imgui.TextDisabled("No results yet.")
            end
            for _, row in ipairs(results) do
                local liveData = PlayerLogManager.ensurePlayer(row.id, row.nick)
                if liveData and PlayerLogManager.hydrateOnlineProfile then
                    PlayerLogManager.hydrateOnlineProfile(liveData)
                end
                local rowIp = liveData and liveData.profile.ip or row.ip
                local rowPing = liveData and liveData.profile.ping or row.ping
                local rowLevel = liveData and liveData.profile.level or row.level
                local rowRegisterDate = liveData and liveData.profile.registerDate or row.registerDate
                local rowLastLogin = liveData and liveData.profile.lastLogin or row.lastLogin
                local rowPlaytime = liveData and liveData.profile.playtime or row.playtime
                imgui.TableNextRow()
                imgui.TableSetColumnIndex(0)
                local selected = (PlayerLogManager.selectedId == row.id)
                if imgui.Selectable(tostring(row.nick or "Unknown"), selected,
                    imgui.SelectableFlags and imgui.SelectableFlags.SpanAllColumns or 0) then
                    PlayerLogManager.selectPlayer(row.id, row.nick)
                    PlayerLogManager.requestSnapshot(row.id, row.nick)
                end
                imgui.TableSetColumnIndex(1)
                imgui.Text(tostring(row.id))
                imgui.TableSetColumnIndex(2)
                imgui.Text(tostring(rowIp))
                imgui.TableSetColumnIndex(3)
                imgui.Text(tostring(rowPing))
                imgui.TableSetColumnIndex(4)
                imgui.Text(tostring(rowLevel))
                imgui.TableSetColumnIndex(5)
                imgui.Text(tostring(rowRegisterDate))
                imgui.TableSetColumnIndex(6)
                imgui.Text(tostring(rowLastLogin))
                imgui.TableSetColumnIndex(7)
                imgui.Text(tostring(rowPlaytime))
            end
            imgui.EndTable()
        end
    else
        imgui.Columns(8, "##pl_search_cols", true)
        imgui.Text("Nickname"); imgui.NextColumn()
        imgui.Text("Player ID"); imgui.NextColumn()
        imgui.Text("IP Address"); imgui.NextColumn()
        imgui.Text("Ping"); imgui.NextColumn()
        imgui.Text("Level"); imgui.NextColumn()
        imgui.Text("Register"); imgui.NextColumn()
        imgui.Text("Last Login"); imgui.NextColumn()
        imgui.Text("Playtime"); imgui.NextColumn()
        if #results == 0 then
            imgui.TextDisabled("No results yet.")
        else
            for _, row in ipairs(results) do
                local liveData = PlayerLogManager.ensurePlayer(row.id, row.nick)
                if liveData and PlayerLogManager.hydrateOnlineProfile then
                    PlayerLogManager.hydrateOnlineProfile(liveData)
                end
                local rowIp = liveData and liveData.profile.ip or row.ip
                local rowPing = liveData and liveData.profile.ping or row.ping
                local rowLevel = liveData and liveData.profile.level or row.level
                local rowRegisterDate = liveData and liveData.profile.registerDate or row.registerDate
                local rowLastLogin = liveData and liveData.profile.lastLogin or row.lastLogin
                local rowPlaytime = liveData and liveData.profile.playtime or row.playtime
                if imgui.Selectable(tostring(row.nick or "Unknown"), PlayerLogManager.selectedId == row.id) then
                    PlayerLogManager.selectPlayer(row.id, row.nick)
                    PlayerLogManager.requestSnapshot(row.id, row.nick)
                end
                imgui.NextColumn()
                imgui.Text(tostring(row.id)); imgui.NextColumn()
                imgui.Text(tostring(rowIp)); imgui.NextColumn()
                imgui.Text(tostring(rowPing)); imgui.NextColumn()
                imgui.Text(tostring(rowLevel)); imgui.NextColumn()
                imgui.Text(tostring(rowRegisterDate)); imgui.NextColumn()
                imgui.Text(tostring(rowLastLogin)); imgui.NextColumn()
                imgui.Text(tostring(rowPlaytime)); imgui.NextColumn()
            end
        end
        imgui.Columns(1)
    end
    imgui.EndChild()

    imgui.Separator()
    local data = PlayerLogManager.getSelectedData()
    MainUI.renderPlayerLogQuickActions(data)
    MainUI.renderPlayerLogProfileSummary(data)
end

function MainUI.renderPlayerLogAltView()
    local data = PlayerLogManager.getSelectedData()
    local ip = ""
    if PlayerLogManager.searchState.kind == "ip" then
        ip = PlayerLogManager.searchState.query
    elseif data then
        ip = tostring(data.profile.ip or "")
    end
    imgui.TextColored(COLORS.INFO, "ALT ACCOUNTS")
    imgui.Text(string.format("IP ADDRESS: %s", ip ~= "" and ip or "N/A"))
    if ip == "" then
        imgui.TextDisabled("IP ma'lumoti /offstats javobi kelgandan keyin ko'rinadi.")
        return
    end

    local results = PlayerLogManager.findPlayersByIp(ip)
    imgui.Text(string.format("Accounts found: %d", #results))
    if #results > 1 then
        imgui.TextColored(COLORS.WARNING, "Possible ALT accounts detected")
    end

    imgui.BeginChild("##playerlog_alt_table", imgui.ImVec2(0, 220), true)
    if imgui.BeginTable then
        local tableFlags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##alt_accounts_table", 4, tableFlags) then
            imgui.TableSetupColumn("Nickname")
            imgui.TableSetupColumn("Last Login")
            imgui.TableSetupColumn("Playtime")
            imgui.TableSetupColumn("Punishments")
            imgui.TableHeadersRow()
            if #results == 0 then
                imgui.TableNextRow()
                imgui.TableSetColumnIndex(0)
                imgui.TextDisabled("No cached accounts for this IP.")
            end
            for _, row in ipairs(results) do
                local pdata = PlayerLogManager.ensurePlayer(row.id, row.nick)
                imgui.TableNextRow()
                imgui.TableSetColumnIndex(0)
                if imgui.Selectable(tostring(row.nick or "Unknown"),
                    PlayerLogManager.selectedId == row.id,
                    imgui.SelectableFlags and imgui.SelectableFlags.SpanAllColumns or 0) then
                    PlayerLogManager.selectPlayer(row.id, row.nick)
                    PlayerLogManager.requestSnapshot(row.id, row.nick)
                end
                imgui.TableSetColumnIndex(1)
                imgui.Text(tostring(pdata.profile.lastLogin))
                imgui.TableSetColumnIndex(2)
                imgui.Text(tostring(pdata.profile.playtime))
                imgui.TableSetColumnIndex(3)
                imgui.Text(tostring(PlayerLogManager.countPunishments(pdata)))
            end
            imgui.EndTable()
        end
    else
        imgui.Columns(4, "##alt_accounts_cols", true)
        imgui.Text("Nickname"); imgui.NextColumn()
        imgui.Text("Last Login"); imgui.NextColumn()
        imgui.Text("Playtime"); imgui.NextColumn()
        imgui.Text("Punishments"); imgui.NextColumn()
        if #results == 0 then
            imgui.TextDisabled("No cached accounts for this IP.")
        else
            for _, row in ipairs(results) do
                local pdata = PlayerLogManager.ensurePlayer(row.id, row.nick)
                if imgui.Selectable(tostring(row.nick or "Unknown"), PlayerLogManager.selectedId == row.id) then
                    PlayerLogManager.selectPlayer(row.id, row.nick)
                    PlayerLogManager.requestSnapshot(row.id, row.nick)
                end
                imgui.NextColumn()
                imgui.Text(tostring(pdata.profile.lastLogin)); imgui.NextColumn()
                imgui.Text(tostring(pdata.profile.playtime)); imgui.NextColumn()
                imgui.Text(tostring(PlayerLogManager.countPunishments(pdata))); imgui.NextColumn()
            end
        end
        imgui.Columns(1)
    end
    imgui.EndChild()
end

function MainUI.renderPlayerLogEconomyView()
    local data = PlayerLogManager.getSelectedData()
    if not data then
        imgui.TextDisabled("Select player first.")
        return
    end
    PlayerLogManager.computeEconomy(data)
    MainUI.renderPlayerLogQuickActions(data)

    imgui.TextColored(COLORS.INFO, "ECONOMY ANALYSIS")
    imgui.Text(string.format("Cash balance: %s", tostring(data.assets.cash)))
    imgui.Text(string.format("Bank balance: %s", tostring(data.assets.bank)))
    imgui.Text(string.format("Total earned: %s", tostring(data.economy.earned)))
    imgui.Text(string.format("Total spent: %s", tostring(data.economy.spent)))
    imgui.Text(string.format("Largest transaction: %s", tostring(data.economy.largestTxn)))
    imgui.Text(string.format("Transfers sent: %d", tonumber(data.economy.transfersSent) or 0))
    imgui.Text(string.format("Transfers received: %d", tonumber(data.economy.transfersReceived) or 0))

    local suspicious = false
    if tonumber(data.economy.largestTxn) and tonumber(data.economy.largestTxn) >= 500000 then
        suspicious = true
    end
    if (tonumber(data.economy.transfersSent) or 0) + (tonumber(data.economy.transfersReceived) or 0) >= 5 then
        suspicious = true
    end
    if suspicious then
        imgui.TextColored(COLORS.WARNING, "Suspicious money activity detected")
    end

    imgui.Separator()
    imgui.TextColored(COLORS.INFO, "TRANSACTION HISTORY")
    imgui.BeginChild("##playerlog_economy_events", imgui.ImVec2(0, 200), true)
    local events = data.economy.events or {}
    if #events == 0 then
        imgui.TextDisabled("No economy events captured.")
    else
        for _, entry in ipairs(events) do
            local stamp = os.date("%Y-%m-%d %H:%M", entry.ts or os.time())
            imgui.Text(string.format("%s | %s", stamp, entry.text))
        end
    end
    imgui.EndChild()
end

function MainUI.renderPlayerLogItemsView()
    local data = PlayerLogManager.getSelectedData()
    if not data then
        imgui.TextDisabled("Select player first.")
        return
    end
    MainUI.renderPlayerLogQuickActions(data)

    imgui.TextColored(COLORS.INFO, "ITEM & ASSET HISTORY")
    imgui.BeginChild("##playerlog_item_events", imgui.ImVec2(0, 180), true)
    local events = PlayerLogManager.extractItemEvents(data)
    if #events == 0 then
        imgui.TextDisabled("No item/asset events captured.")
    else
        for _, entry in ipairs(events) do
            local stamp = os.date("%Y-%m-%d %H:%M", entry.ts or os.time())
            imgui.Text(string.format("%s | %s", stamp, entry.text))
        end
    end
    imgui.EndChild()

    imgui.Separator()
    imgui.TextColored(COLORS.INFO, "ASSETS")
    imgui.Text(string.format("Vehicles owned: %d", #(data.assets.vehicles or {})))
    imgui.Text(string.format("Houses owned: %d", #(data.assets.properties or {})))
    imgui.Text(string.format("Apartments owned: %d", #(data.assets.apartments or {})))
    imgui.Text(string.format("Businesses owned: %d", #(data.assets.businesses or {})))
end

function MainUI.renderPlayerLogAdminLogView()
    local data = PlayerLogManager.getSelectedData()
    imgui.TextColored(COLORS.INFO, "ADMIN SECURITY LOG")
    local filterSelected = imgui.ImBool(PlayerLogManager.adminLogFilterSelected)
    if imgui.Checkbox("Filter by selected player", filterSelected) then
        PlayerLogManager.adminLogFilterSelected = filterSelected[0]
    end
    imgui.BeginChild("##playerlog_admin_log", imgui.ImVec2(0, 280), true)
    if imgui.BeginTable then
        local tableFlags = (imgui.TableFlags and (imgui.TableFlags.Borders + imgui.TableFlags.RowBg)) or 0
        if imgui.BeginTable("##admin_security_table", 5, tableFlags) then
            imgui.TableSetupColumn("Admin")
            imgui.TableSetupColumn("Action")
            imgui.TableSetupColumn("Target")
            imgui.TableSetupColumn("Reason")
            imgui.TableSetupColumn("Time")
            imgui.TableHeadersRow()
            for _, entry in ipairs(AdminSecurityLog.entries or {}) do
                local allow = true
                if PlayerLogManager.adminLogFilterSelected and data then
                    allow = tonumber(entry.target) == tonumber(data.profile.playerId)
                end
                if allow then
                    imgui.TableNextRow()
                    imgui.TableSetColumnIndex(0); imgui.Text(tostring(entry.admin))
                    imgui.TableSetColumnIndex(1); imgui.Text(tostring(entry.action))
                    imgui.TableSetColumnIndex(2); imgui.Text(tostring(entry.targetLabel or entry.target))
                    imgui.TableSetColumnIndex(3); imgui.Text(tostring(entry.reason))
                    imgui.TableSetColumnIndex(4); imgui.Text(os.date("%Y-%m-%d %H:%M", entry.ts or os.time()))
                end
            end
            imgui.EndTable()
        end
    else
        imgui.Columns(5, "##admin_security_cols", true)
        imgui.Text("Admin"); imgui.NextColumn()
        imgui.Text("Action"); imgui.NextColumn()
        imgui.Text("Target"); imgui.NextColumn()
        imgui.Text("Reason"); imgui.NextColumn()
        imgui.Text("Time"); imgui.NextColumn()
        for _, entry in ipairs(AdminSecurityLog.entries or {}) do
            local allow = true
            if PlayerLogManager.adminLogFilterSelected and data then
                allow = tonumber(entry.target) == tonumber(data.profile.playerId)
            end
            if allow then
                imgui.Text(tostring(entry.admin)); imgui.NextColumn()
                imgui.Text(tostring(entry.action)); imgui.NextColumn()
                imgui.Text(tostring(entry.targetLabel or entry.target)); imgui.NextColumn()
                imgui.Text(tostring(entry.reason)); imgui.NextColumn()
                imgui.Text(os.date("%Y-%m-%d %H:%M", entry.ts or os.time())); imgui.NextColumn()
            end
        end
        imgui.Columns(1)
    end
    imgui.EndChild()
end

function MainUI.renderTeleportSystem()
    imgui.Text(u8"Tadbir teleportlari:")

    if imgui.CollapsingHeader(u8"Click Warp boshqaruvi") then
        local clickWarpEnabled = imgui.ImBool(SettingsManager.get("clickWarpEnabled") ~= false)
