        SecurityManager.ipCheck(playerId)
    end
    imgui.SameLine()
    if imgui.Button(u8"Serial Check", imgui.ImVec2(100, 25)) then
        SecurityManager.serialCheck(playerId)
    end
    imgui.SameLine()
    if imgui.Button(u8"Multi-Account", imgui.ImVec2(100, 25)) then
        SecurityManager.detectMultiAccount(playerId)
    end
    imgui.SameLine()
    if imgui.Button(u8"Speed Hack", imgui.ImVec2(100, 25)) then
        SecurityManager.detectSpeedHack(playerId)
    end

    if imgui.CollapsingHeader(u8"Hack Detection") then
        if imgui.Button(u8"Health Hack Check", imgui.ImVec2(130, 25)) then
            SecurityManager.detectHealthHack(playerId)
        end
        imgui.SameLine()
        if imgui.Button(u8"Teleport Hack Check", imgui.ImVec2(140, 25)) then
            SecurityManager.detectTeleportHack(playerId)
        end
        imgui.SameLine()
        if imgui.Button(u8"Movement Check", imgui.ImVec2(130, 25)) then
            SecurityManager.detectSuspiciousMovement(playerId)
        end
    end

    if imgui.CollapsingHeader(u8"Blacklist") then
        imgui.InputText(u8"ID/Name", MainUI.buffers.reason, 256)
        imgui.InputInt(u8"Type (1=ID, 2=Serial, 3=IP)", MainUI.buffers.amount)

        if imgui.Button(u8"Add to Blacklist", imgui.ImVec2(130, 25)) then
            local types = {"id", "serial", "ip"}
            SecurityManager.addToBlacklist(UtilityManager.bufferToString(MainUI.buffers.reason),
                types[MainUI.buffers.amount[0]] or "id", "Manual add")
        end
        imgui.SameLine()
        if imgui.Button(u8"Remove from Blacklist", imgui.ImVec2(160, 25)) then
            SecurityManager.removeFromBlacklist(UtilityManager.bufferToString(MainUI.buffers.reason))
        end

        imgui.TextDisabled(string.format("Blacklisted: %d entries", #SecurityManager.blacklist))
    end

    if imgui.CollapsingHeader(u8"Whitelist") then
        imgui.InputText(u8"ID/Name", MainUI.buffers.reason, 256)
        if imgui.Button(u8"Add to Whitelist", imgui.ImVec2(140, 25)) then
            SecurityManager.addToWhitelist(UtilityManager.bufferToString(MainUI.buffers.reason))
        end
        imgui.SameLine()
        if imgui.Button(u8"Remove from Whitelist", imgui.ImVec2(170, 25)) then
            SecurityManager.removeFromWhitelist(UtilityManager.bufferToString(MainUI.buffers.reason))
        end
    end

    if imgui.CollapsingHeader(u8"Chat Filter") then
        local filterEnabled = imgui.ImBool(true)
        imgui.Checkbox(u8"Enable Filter", filterEnabled)

        imgui.Text(u8"Filtered Words:")
        for _, word in ipairs(SecurityManager.chatFilter) do
            imgui.BulletText(word)
        end
    end

    if imgui.Button(u8"Export Security Log", imgui.ImVec2(150, 30)) then
        SecurityManager.exportSecurityLog(UtilityManager.getWorkingDirectorySafe() .. "/security_" .. os.time() .. ".txt")
    end
end

function MainUI.renderAnalytics()
    imgui.Columns(2, "##AnalyticsCols", false)

    imgui.TextColored(COLORS.PRIMARY, u8"REPORT STATISTIKASI")
    imgui.Text(string.format("Hozir: %d", StatsManager.data.session.answers))
    for i = 1, 7 do
        local day = StatsManager.getWeekdayData(i)
        imgui.Text(string.format("%s: %d", StatsManager.getWeekdayLabel(i), day.answers or 0))
    end
    imgui.Text(string.format("Shu oy: %d", StatsManager.data.monthly.answers))

    imgui.NextColumn()

    imgui.TextColored(COLORS.SECONDARY, u8"VAQT STATISTIKASI")
    imgui.Text(string.format("Hozir: %s", UtilityManager.formatTime(StatsManager.data.session.playtime or 0)))
    for i = 1, 7 do
        local day = StatsManager.getWeekdayData(i)
        imgui.Text(string.format("%s: %s", StatsManager.getWeekdayLabel(i),
            UtilityManager.formatTime(day.playtime or 0)))
    end
    imgui.Text(string.format("Shu oy: %s", UtilityManager.formatTime(StatsManager.data.monthly.playtime)))

    imgui.Columns(1)
    imgui.Separator()

    if imgui.CollapsingHeader(u8"Performance Metrics") then
        imgui.Text(string.format("Efficiency: %.1f%%", StatsManager.data.efficiency))
        imgui.Text(string.format("Performance Score: %d", StatsManager.getPerformanceScore()))
        imgui.Text(string.format("Weekly Trend: %d%%", StatsManager.getWeeklyTrend()))

        local trend = StatsManager.getWeeklyTrend()
        local trendColor = trend >= 0 and COLORS.PRIMARY or COLORS.DANGER
        local trendIcon = trend >= 0 and "+" or ""
        imgui.TextColored(trendColor, string.format("Trend: %s%d%%", trendIcon, trend))
    end

    if imgui.CollapsingHeader(u8"Activity Charts") then
        local values = {0.3, 0.5, 0.8, 0.6, 0.9, 0.7, 0.85}
        if imgui.PlotHistogram then
            imgui.PlotHistogram("##Activity", values, #values, 0, "Activity", 0, 1, imgui.ImVec2(0, 80))
        else
            imgui.TextDisabled("Activity chart not supported by your mimgui build")
        end
    end

    imgui.Separator()
    imgui.Text(u8"Export Data:")
    if imgui.Button(u8"Export to TXT", imgui.ImVec2(120, 30)) then
        AnalyticsManager.exportToTxt(UtilityManager.getWorkingDirectorySafe() .. "/analytics_" .. os.time() .. ".txt")
    end
    imgui.SameLine()
    if imgui.Button(u8"Export to JSON", imgui.ImVec2(120, 30)) then
        AnalyticsManager.exportToJson(UtilityManager.getWorkingDirectorySafe() .. "/analytics_" .. os.time() .. ".json")
    end
    imgui.SameLine()
    if imgui.Button(u8"Compare Week", imgui.ImVec2(120, 30)) then
        local comp = AnalyticsManager.comparePreviousWeek()
        print(string.format("Comparison: %d%%", comp.percentage))
    end
end

function MainUI.renderAdminCheckerSection(embedded)
    if not embedded then
        if not imgui.CollapsingHeader(u8"Admin Checker") then
            return
        end
    else
        imgui.TextColored(COLORS.PRIMARY, u8"Admin Checker")
        imgui.TextDisabled(u8"Online adminlar ro'yxati va tezkor kuzatuv.")
        imgui.Separator()
    end

    local checkerLower = rawget(_G, "adminCheckerLower")
    if type(checkerLower) ~= "function" then
        checkerLower = function(value)
            return tostring(value or ""):lower()
        end
    end

    local checkerFormatPlaytimeText = rawget(_G, "adminCheckerFormatPlaytimeText")
    if type(checkerFormatPlaytimeText) ~= "function" then
        checkerFormatPlaytimeText = function(value)
            local raw = UtilityManager.trim(tostring(value or ""))
            if raw == "" then
                return "--"
            end
            return raw
        end
    end

    local function syncAdminCheckerStyleBuffers()
        if not MainUI.buffers.adminCheckerTextScale then
            MainUI.buffers.adminCheckerTextScale = imgui.ImFloat(tonumber(SettingsManager.get("adminCheckerTextScale")) or 1.0)
        end
        local function ensureColorBuffer(key, fieldName, fallback)
            if not MainUI.buffers[fieldName] then
                MainUI.buffers[fieldName] = imgui.new.float[3]()
            end
            local rgb = SettingsManager.get(key) or fallback
            MainUI.buffers[fieldName][0] = (tonumber(rgb[1] or rgb["1"]) or fallback[1]) / 255
            MainUI.buffers[fieldName][1] = (tonumber(rgb[2] or rgb["2"]) or fallback[2]) / 255
            MainUI.buffers[fieldName][2] = (tonumber(rgb[3] or rgb["3"]) or fallback[3]) / 255
        end
        MainUI.buffers.adminCheckerTextScale[0] = tonumber(SettingsManager.get("adminCheckerTextScale")) or 1.0
        ensureColorBuffer("adminCheckerColorLv12", "adminCheckerColorLv12", {122, 224, 255})
        ensureColorBuffer("adminCheckerColorLv3", "adminCheckerColorLv3", {92, 158, 255})
        ensureColorBuffer("adminCheckerColorLv4", "adminCheckerColorLv4", {250, 219, 77})
        ensureColorBuffer("adminCheckerColorLv5", "adminCheckerColorLv5", {255, 71, 82})
    end

    local function saveAdminCheckerColor(key, buffer)
        local rgb = {
            math.floor(UtilityManager.clamp(buffer[0], 0, 1) * 255),
            math.floor(UtilityManager.clamp(buffer[1], 0, 1) * 255),
            math.floor(UtilityManager.clamp(buffer[2], 0, 1) * 255)
        }
        SettingsManager.set(key, rgb)
        SettingsManager.save()
    end

    syncAdminCheckerStyleBuffers()

    local enabled = imgui.ImBool(SettingsManager.get("adminCheckerEnabled") == true)
    if imgui.Checkbox(u8"Yoqilgan##admin_checker_enabled", enabled) then
        SettingsManager.set("adminCheckerEnabled", enabled[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local compact = imgui.ImBool(SettingsManager.get("adminCheckerCompact") == true)
    if imgui.Checkbox(u8"Compact##admin_checker_compact", compact) then
        SettingsManager.set("adminCheckerCompact", compact[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local overlayEnabled = imgui.ImBool(SettingsManager.get("adminCheckerOverlayEnabled") ~= false)
    if imgui.Checkbox(u8"Overlay##admin_checker_overlay", overlayEnabled) then
        SettingsManager.set("adminCheckerOverlayEnabled", overlayEnabled[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local autoRefresh = imgui.ImBool(SettingsManager.get("adminCheckerAutoRefresh") == true)
    if imgui.Checkbox(u8"Auto refresh##admin_checker_auto", autoRefresh) then
        SettingsManager.set("adminCheckerAutoRefresh", autoRefresh[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local statsEnabled = imgui.ImBool(SettingsManager.get("adminCheckerStatsEnabled") == true)
    if imgui.Checkbox(u8"/stats bilan vaqt##admin_checker_stats_enabled", statsEnabled) then
        SettingsManager.set("adminCheckerStatsEnabled", statsEnabled[0])
        SettingsManager.save()
        if statsEnabled[0] and AdminCheckerManager.enqueueStatsForAll then
            AdminCheckerManager.enqueueStatsForAll(false)
        elseif not statsEnabled[0] and AdminCheckerManager.resetStatsState then
            AdminCheckerManager.resetStatsState(true)
        end
    end

    local showAfkToggle = imgui.ImBool(SettingsManager.get("adminCheckerShowAfk") ~= false)
    if imgui.Checkbox(u8"AFK ko'rsatish##admin_checker_show_afk", showAfkToggle) then
        SettingsManager.set("adminCheckerShowAfk", showAfkToggle[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local showRepToggle = imgui.ImBool(SettingsManager.get("adminCheckerShowRep") ~= false)
    if imgui.Checkbox(u8"Rep ko'rsatish##admin_checker_show_rep", showRepToggle) then
        SettingsManager.set("adminCheckerShowRep", showRepToggle[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    local showSpecToggle = imgui.ImBool(SettingsManager.get("adminCheckerShowSpec") ~= false)
    if imgui.Checkbox(u8"/sp ko'rsatish##admin_checker_show_spec", showSpecToggle) then
        SettingsManager.set("adminCheckerShowSpec", showSpecToggle[0])
        SettingsManager.save()
    end

    if imgui.Button(u8"Yangilash (/admins)##admin_checker_refresh", imgui.ImVec2(180, 28)) then
        AdminCheckerManager.requestRefresh(true)
    end
    imgui.SameLine()
    if imgui.Button(u8"Joylashuvni o'zgartirish##admin_checker_place", imgui.ImVec2(210, 28)) then
        AdminCheckerManager.beginOverlayPlacement()
    end
    imgui.SameLine()
    if imgui.Button(u8"Chatga chiqarish##admin_checker_print", imgui.ImVec2(150, 28)) then
        AdminCheckerManager.printSummaryToChat()
    end

    if imgui.InputInt(u8"Refresh sec##admin_checker_sec", MainUI.buffers.adminCheckerRefresh) then
        MainUI.buffers.adminCheckerRefresh[0] = math.max(1, math.min(60, tonumber(MainUI.buffers.adminCheckerRefresh[0]) or 8))
        SettingsManager.set("adminCheckerRefreshSeconds", MainUI.buffers.adminCheckerRefresh[0])
        SettingsManager.save()
    end
    imgui.SameLine()
    if imgui.SliderFloat then
        if imgui.SliderFloat(u8"Yozuv hajmi##admin_checker_text_scale", MainUI.buffers.adminCheckerTextScale, 0.75, 1.80, "%.2f") then
            SettingsManager.set("adminCheckerTextScale", UtilityManager.clamp(tonumber(MainUI.buffers.adminCheckerTextScale[0]) or 1.0, 0.75, 1.80))
            SettingsManager.save()
        end
    elseif imgui.InputFloat then
        if imgui.InputFloat(u8"Yozuv hajmi##admin_checker_text_scale", MainUI.buffers.adminCheckerTextScale) then
            MainUI.buffers.adminCheckerTextScale[0] = UtilityManager.clamp(tonumber(MainUI.buffers.adminCheckerTextScale[0]) or 1.0, 0.75, 1.80)
            SettingsManager.set("adminCheckerTextScale", MainUI.buffers.adminCheckerTextScale[0])
            SettingsManager.save()
        end
    end

    if imgui.ColorEdit3 then
        imgui.TextDisabled(u8"Lvl ranglari")
        if imgui.ColorEdit3("1-2 LVL##admin_checker_color_lv12", MainUI.buffers.adminCheckerColorLv12) then
            saveAdminCheckerColor("adminCheckerColorLv12", MainUI.buffers.adminCheckerColorLv12)
        end
        if imgui.ColorEdit3("3 LVL##admin_checker_color_lv3", MainUI.buffers.adminCheckerColorLv3) then
            saveAdminCheckerColor("adminCheckerColorLv3", MainUI.buffers.adminCheckerColorLv3)
        end
        if imgui.ColorEdit3("4 LVL##admin_checker_color_lv4", MainUI.buffers.adminCheckerColorLv4) then
            saveAdminCheckerColor("adminCheckerColorLv4", MainUI.buffers.adminCheckerColorLv4)
        end
        if imgui.ColorEdit3("5+ LVL##admin_checker_color_lv5", MainUI.buffers.adminCheckerColorLv5) then
            saveAdminCheckerColor("adminCheckerColorLv5", MainUI.buffers.adminCheckerColorLv5)
        end
    end

    imgui.InputText(u8"Qidiruv##admin_checker_search", MainUI.buffers.adminCheckerSearch, 64)
    local rawSearch = UtilityManager.trim(UtilityManager.bufferToString(MainUI.buffers.adminCheckerSearch) or "")
    local search = checkerLower(rawSearch)
    if search == "qidiruv" then
        search = ""
    end

    imgui.TextDisabled(string.format("Online: %d | AFK: %d", AdminCheckerManager.counts.all, AdminCheckerManager.counts.afk))
    if statsEnabled[0] then
        local queueCount = #((AdminCheckerManager.statsQueue) or {})
        local pendingStats = AdminCheckerManager.statsPending
        local pendingText = pendingStats and string.format(" | Tekshirilmoqda: %s[%d]", tostring(pendingStats.nick or ""), tonumber(pendingStats.id) or 0) or ""
        imgui.TextDisabled(u8(string.format("/stats cache yoqilgan (60s) | Cache: %d | Navbat: %d%s", AdminCheckerManager.countMapEntries(AdminCheckerManager.statsCache), queueCount, pendingText)))
    else
        imgui.TextDisabled(u8("/stats orqali vaqtni olish o'chirilgan"))
    end
    if AdminCheckerManager.placementActive then
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(1.0, 0.75, 0.2, 1.0), u8("Joylashuv rejimi yoqilgan: ekranda joy tanlab, chap tugma bosing."))
    end

    local showAfk = SettingsManager.get("adminCheckerShowAfk") ~= false
    local showRep = SettingsManager.get("adminCheckerShowRep") ~= false
    local showSpec = SettingsManager.get("adminCheckerShowSpec") ~= false
    local checkerTextScaleValue = AdminCheckerManager.getTextScale()
    local fontScaleApplied = false
    if imgui.SetWindowFontScale then
        imgui.SetWindowFontScale(checkerTextScaleValue)
        fontScaleApplied = true
    end

    MainUI._adminCheckerBucketStates = MainUI._adminCheckerBucketStates or {}
    for level = 8, 1, -1 do
        local bucket = AdminCheckerManager.listByLevel[level] or {}
        if #bucket > 0 then
            local bucketOpen = MainUI._adminCheckerBucketStates[level] == true
            local bucketLabel = string.format("%s %s (%d)##admin_level_%d", bucketOpen and "[-]" or "[+]", AdminCheckerManager.getLevelName(level), #bucket, level)
            if imgui.Button(u8(bucketLabel), imgui.ImVec2(-1, 26)) then
                bucketOpen = not bucketOpen
                MainUI._adminCheckerBucketStates[level] = bucketOpen
            end
            if bucketOpen then
                local visibleCount = 0
                imgui.Indent()
            for _, entry in ipairs(bucket) do
                if statsEnabled[0] and AdminCheckerManager.enqueueStatsRequest then
                    AdminCheckerManager.enqueueStatsRequest(entry)
                end
                local line = string.format("%s[%d]", tostring(entry.nick or "Unknown"), tonumber(entry.id) or 0)
                if SettingsManager.get("adminCheckerCompact") ~= true then
                    line = line .. string.format(" | %s", tostring(AdminCheckerManager.getLevelName(entry.lvl)))
                    line = line .. string.format(" | %s", checkerFormatPlaytimeText(AdminCheckerManager.getDisplayPlaytimeText(entry)))
                    if showAfk then
                        if UtilityManager.trim(tostring(entry.afkText or "")) ~= "" then
                            line = line .. string.format(" | AFK: %s", tostring(entry.afkText))
                        elseif (tonumber(entry.afk) or 0) > 0 then
                            line = line .. string.format(" | AFK: %d", tonumber(entry.afk) or 0)
                        end
                    end
                    if showRep then
                        line = line .. string.format(" | Rep: %d", tonumber(entry.rep) or 0)
                    end
                    if showSpec and entry.spec then
                        line = line .. string.format(" | /sp %d", tonumber(entry.spec) or 0)
                    end
                    if entry.hidden then
                        line = line .. " | IGN"
                    end
                    if UtilityManager.trim(entry.note or "") ~= "" then
                        line = line .. " | " .. tostring(entry.note)
                    end
                end

                local folded = checkerLower(line)
                if search == "" or folded:find(search, 1, true) then
                    visibleCount = visibleCount + 1
                    local selected = AdminCheckerManager.selectedId == tonumber(entry.id)
                    if imgui.Selectable(u8(line .. "##admin_checker_entry_" .. tostring(entry.id)), selected) then
                        AdminCheckerManager.selectedId = tonumber(entry.id)
                        AdminCheckerManager.selectedNick = tostring(entry.nick or "")
                        UtilityManager.setBufferString(MainUI.buffers.adminCheckerNote, AdminCheckerManager.getNote(entry.nick))
                    end
                    imgui.SameLine()
                    if imgui.SmallButton(u8("SP##admin_checker_sp_" .. tostring(entry.id))) then
                        PlayerManager.spectate(entry.id)
                    end
                    imgui.SameLine()
                    if imgui.SmallButton(u8("Goto##admin_checker_goto_" .. tostring(entry.id))) then
                        PlayerManager.teleportTo(entry.id)
                    end
                    imgui.SameLine()
                    if imgui.SmallButton(u8("GetHere##admin_checker_gethere_" .. tostring(entry.id))) then
                        PlayerManager.bring(entry.id)
                    end
                end
            end
                if visibleCount == 0 and search ~= "" then
                    imgui.TextDisabled(u8("Bu levelda qidiruvga mos admin topilmadi."))
                end
                imgui.Unindent()
            end
        end
    end

    local selectedEntry = AdminCheckerManager.findEntry(AdminCheckerManager.selectedId)
    if selectedEntry then
        if statsEnabled[0] and AdminCheckerManager.enqueueStatsRequest then
            AdminCheckerManager.enqueueStatsRequest(selectedEntry)
        end

        if MainUI._adminCheckerBoundNick ~= tostring(selectedEntry.nick or "") then
            MainUI._adminCheckerBoundNick = tostring(selectedEntry.nick or "")
            UtilityManager.setBufferString(MainUI.buffers.adminCheckerNote, AdminCheckerManager.getNote(selectedEntry.nick))
        end

        imgui.Separator()
        imgui.TextColored(COLORS.PRIMARY, u8("Tanlangan admin: " .. tostring(selectedEntry.nick) .. " [" .. tostring(selectedEntry.id) .. "]"))
        imgui.TextDisabled(string.format("LVL: %s | Playtime: %s | AFK: %s | Rep: %d",
            AdminCheckerManager.getLevelName(selectedEntry.lvl),
            checkerFormatPlaytimeText(AdminCheckerManager.getDisplayPlaytimeText(selectedEntry)),
            UtilityManager.trim(tostring(selectedEntry.afkText or "")) ~= "" and tostring(selectedEntry.afkText) or tostring(tonumber(selectedEntry.afk) or 0),
            tonumber(selectedEntry.rep) or 0))
        imgui.InputText(u8"Note##admin_checker_note", MainUI.buffers.adminCheckerNote, 256)
        if imgui.Button(u8"Noteni saqlash##admin_checker_note_save", imgui.ImVec2(170, 28)) then
            AdminCheckerManager.setNote(selectedEntry.nick, UtilityManager.bufferToString(MainUI.buffers.adminCheckerNote))
        end
        imgui.SameLine()
        local ignored = imgui.ImBool(AdminCheckerManager.isIgnored(selectedEntry.nick))
        if imgui.Checkbox(u8"Ignore##admin_checker_ignore", ignored) then
            AdminCheckerManager.setIgnored(selectedEntry.nick, ignored[0])
        end
    end

    if fontScaleApplied and imgui.SetWindowFontScale then
        imgui.SetWindowFontScale(1.0)
    end
end

function MainUI.renderAdminPoTrackerWorkspace()
    AdminPoManager.ensureState()

    imgui.BeginChild("##AdminPoGroups", imgui.ImVec2(190, 260), true)
    for index, group in ipairs(AdminPoManager.groups or {}) do
        local selected = AdminPoManager.selectedIndex == index
        if imgui.Selectable(u8(string.format("%s (%d)##admin_po_group_%d", tostring(group.name), #(group.entries or {}), index)), selected) then
            AdminPoManager.selectedIndex = index
            UtilityManager.setBufferString(MainUI.buffers.adminPoGroupName, tostring(group.name or ""))
        end
    end
    imgui.EndChild()

    imgui.SameLine()
    imgui.BeginGroup()

    local group = AdminPoManager.getSelectedGroup()
    if not group then
        if imgui.Button(u8"Checker yaratish##admin_po_create_only", imgui.ImVec2(180, 28)) then
            AdminPoManager.createGroup("Checker #1")
        end
        imgui.EndGroup()
        return
    end

    if MainUI._adminPoBoundIndex ~= AdminPoManager.selectedIndex then
        MainUI._adminPoBoundIndex = AdminPoManager.selectedIndex
        UtilityManager.setBufferString(MainUI.buffers.adminPoGroupName, tostring(group.name or ""))
    end

    imgui.InputText(u8"Nomi##admin_po_name", MainUI.buffers.adminPoGroupName, 96)
    if imgui.Button(u8"Nomni saqlash##admin_po_name_save", imgui.ImVec2(150, 28)) then
        group.name = UtilityManager.trim(UtilityManager.bufferToString(MainUI.buffers.adminPoGroupName) or "")
        if group.name == "" then
            group.name = "Checker #" .. tostring(AdminPoManager.selectedIndex)
        end
        AdminPoManager.save()
    end
    imgui.SameLine()
    if imgui.Button(u8"Yangi checker##admin_po_new", imgui.ImVec2(130, 28)) then
        AdminPoManager.createGroup(UtilityManager.bufferToString(MainUI.buffers.adminPoGroupName))
    end
    imgui.SameLine()
    if imgui.Button(u8"O'chirish##admin_po_remove_group", imgui.ImVec2(110, 28)) then
        AdminPoManager.removeSelectedGroup()
    end

    local onlineOnly = imgui.ImBool(group.onlineOnly ~= false)
    if imgui.Checkbox(u8"Faqat online ko'rsatish##admin_po_online_only", onlineOnly) then
        group.onlineOnly = onlineOnly[0]
        AdminPoManager.save()
    end
    imgui.SameLine()
    local showTitle = imgui.ImBool(group.showTitle ~= false)
    if imgui.Checkbox(u8"Sarlavha ko'rsatish##admin_po_show_title", showTitle) then
        group.showTitle = showTitle[0]
        AdminPoManager.save()
    end

    imgui.BeginChild("##AdminPoEntries", imgui.ImVec2(0, 170), true)
    if group.showTitle ~= false then
        imgui.TextColored(COLORS.PRIMARY, u8(string.format("%s | Online: %d", tostring(group.name or "Checker"), #AdminPoManager.getOnlineIds(group))))
        imgui.Separator()
    end
    if #(group.entries or {}) == 0 then
        imgui.TextDisabled(u8"Checker bo'sh")
    else
        for entryIndex, entry in ipairs(group.entries) do
            local onlineId = AdminPoManager.resolveNickToId(entry.nick)
            if onlineId or group.onlineOnly ~= true then
                local label = string.format("%s[%s]", tostring(entry.nick), onlineId and tostring(onlineId) or "OFF")
                if UtilityManager.trim(entry.note or "") ~= "" then
                    label = label .. " // " .. tostring(entry.note)
                end
                imgui.Text(u8(label))
                if onlineId then
                    imgui.SameLine()
                    if imgui.SmallButton(u8("SP##admin_po_sp_" .. tostring(entryIndex))) then
                        PlayerManager.spectate(onlineId)
                    end
                    imgui.SameLine()
                    if imgui.SmallButton(u8("Goto##admin_po_goto_" .. tostring(entryIndex))) then
                        PlayerManager.teleportTo(onlineId)
                    end
                    imgui.SameLine()
                    if imgui.SmallButton(u8("GetHere##admin_po_gethere_" .. tostring(entryIndex))) then
                        PlayerManager.bring(onlineId)
                    end
                end
                imgui.SameLine()
                if imgui.SmallButton(u8("X##admin_po_del_" .. tostring(entryIndex))) then
                    AdminPoManager.removeEntry(AdminPoManager.selectedIndex, entryIndex)
                    break
                end
            end
        end
    end
    imgui.EndChild()

    imgui.InputInt(u8"ID##admin_po_player_id", MainUI.buffers.adminPoPlayerId)
    imgui.InputText(u8"Izoh##admin_po_note", MainUI.buffers.adminPoNote, 192)
    if imgui.Button(u8"ID bo'yicha qo'shish##admin_po_add_id", imgui.ImVec2(180, 28)) then
        local okAdd, message = AdminPoManager.addPlayerById(
            AdminPoManager.selectedIndex,
            MainUI.buffers.adminPoPlayerId[0],
            UtilityManager.bufferToString(MainUI.buffers.adminPoNote)
        )
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage("[GMEA] " .. tostring(message or (okAdd and "Checkerga qo'shildi" or "Qo'shib bo'lmadi")), okAdd and 0x33FF66 or 0xFF6666)
        end
    end
    imgui.SameLine()
    if imgui.Button(u8"Online'ni /sp qilish##admin_po_spec_all", imgui.ImVec2(180, 28)) then
        local ids = AdminPoManager.getOnlineIds(group)
        if #ids == 0 then
            if type(sampAddChatMessage) == "function" then
                sampAddChatMessage("[GMEA] Checker ichida online o'yinchi topilmadi.", 0xFF6666)
            end
        else
            for _, playerId in ipairs(ids) do
                PlayerManager.spectate(playerId)
            end
        end
    end

    imgui.EndGroup()
end

function MainUI.renderAdminPoSection()
    if not imgui.CollapsingHeader(u8"Admin PO") then
        return
    end
    MainUI.renderAdminPoTrackerWorkspace()
end

function MainUI.renderAdminPoHeader(title, subtitle)
    local accent = COLORS and COLORS.PRIMARY or imgui.ImVec4(0.85, 0.18, 0.24, 1.0)
    imgui.TextColored(accent, u8(title))
    if subtitle and subtitle ~= "" then
        imgui.TextDisabled(u8(subtitle))
    end
    imgui.Separator()
end

function MainUI.renderAdminPoCard(cardKey, iconLabel, title, subtitle, pageId, size)
    AdminPoManager.ensureState()
    local buttonSize = size or imgui.ImVec2(280, 108)
    local state = MainUI.getButtonFxState("admin_po_card:" .. tostring(cardKey))
    local active = tonumber(AdminPoManager.page) == tonumber(pageId)

    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0, 0, 0, 0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0, 0, 0, 0))
    imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0, 0, 0, 0))
    local pressed = imgui.Button("##admin_po_card_" .. tostring(cardKey), buttonSize)
    local hovered = imgui.IsItemHovered()
    imgui.PopStyleColor(3)

    local nowMs = RuntimeGuard.getNowMs()
    state.lastSeenAtMs = nowMs
    state.target = (hovered or active) and 1 or 0
    local dt = MainUI.getAnimationDelta()
    local lerpSpeed = math.min(1, dt * 9)
    state.glow = UtilityManager.lerp(state.glow or 0, state.target or 0, lerpSpeed)

    local minPos = imgui.GetItemRectMin()
    local maxPos = imgui.GetItemRectMax()
    local drawList = imgui.GetWindowDrawList()
    local base = MainUI.mixColor(COLORS.SURFACE_ALT, COLORS.PRIMARY, 0.10 + (state.glow or 0) * 0.22)
    local border = MainUI.mixColor(COLORS.BORDER, COLORS.NEON_SOFT or COLORS.HOVER, 0.08 + (state.glow or 0) * 0.42)
    local topBar = MainUI.mixColor(COLORS.PRIMARY, COLORS.NEON_HARD or COLORS.LIGHT, 0.12 + (state.glow or 0) * 0.36)
    local iconColor = MainUI.mixColor(COLORS.TEXT, COLORS.LIGHT, 0.20 + (state.glow or 0) * 0.58)
    local subtitleColor = MainUI.mixColor(COLORS.TEXT_DIM or COLORS.TEXT, COLORS.TEXT, 0.25)
    local timeValue = os.clock() * 2.4 + tonumber(pageId or 0)
    local orbX = minPos.x + 36 + math.cos(timeValue) * 11
    local orbY = minPos.y + 28 + math.sin(timeValue * 1.2) * 6

    drawList:AddRectFilled(minPos, maxPos, MainUI.colorToU32(base), 12)
    drawList:AddRect(minPos, maxPos, MainUI.colorToU32(border), 12, 0, 1.6)
    drawList:AddRectFilled(minPos, imgui.ImVec2(maxPos.x, minPos.y + 4), MainUI.colorToU32(topBar), 12, 1)
    drawList:AddCircleFilled(imgui.ImVec2(minPos.x + 34, minPos.y + 28), 18, MainUI.colorToU32(MainUI.mixColor(COLORS.SURFACE, COLORS.PRIMARY, 0.18 + (state.glow or 0) * 0.20)))
    drawList:AddCircleFilled(imgui.ImVec2(orbX, orbY), 3.2, MainUI.colorToU32(MainUI.mixColor(COLORS.NEON_SOFT or COLORS.PRIMARY, COLORS.LIGHT, 0.25 + (state.glow or 0) * 0.44)))
    drawList:AddText(imgui.ImVec2(minPos.x + 23, minPos.y + 17 + math.sin(timeValue) * 1.8), MainUI.colorToU32(iconColor), tostring(iconLabel or "*"))
    drawList:AddText(imgui.ImVec2(minPos.x + 64, minPos.y + 20), MainUI.colorToU32(COLORS.TEXT), tostring(title or ""))
    drawList:AddText(imgui.ImVec2(minPos.x + 64, minPos.y + 48), MainUI.colorToU32(subtitleColor), tostring(subtitle or ""))

    if pressed then
        AdminPoManager.setPage(pageId)
    end
end

function MainUI.renderAdminPoOverview()
    AdminPoManager.ensureState()
    MainUI.renderAdminPoHeader("Админ ПО", "Плиточное меню в стиле AA: подпункты, анимация и быстрые действия")

    local spacing = 10
    local avail = imgui.GetContentRegionAvail()
    local cardWidth = math.max(240, (avail.x - spacing) / 2)

    MainUI.renderAdminPoCard("multi", "IP", "Мультиаккаунты", "Поиск игроков с одинаковыми IP", 1, imgui.ImVec2(cardWidth, 106))
    imgui.SameLine(0, spacing)
    MainUI.renderAdminPoCard("nick", "Aa", "Проверка ников", "Поиск NonRP и обходных ников", 2, imgui.ImVec2(cardWidth, 106))
    MainUI.renderAdminPoCard("item", "[]", "Поиск предметов", "Проверка инвентарей по предмету", 3, imgui.ImVec2(cardWidth, 106))
    imgui.SameLine(0, spacing)
    MainUI.renderAdminPoCard("checker", "CK", "Чекер игроков", "Списки слежки и быстрый реккон", 4, imgui.ImVec2(cardWidth, 106))
    MainUI.renderAdminPoCard("legacy", "FX", "Чит-функции", "Старый набор функций из вашего таба", 5, imgui.ImVec2(cardWidth, 106))

    imgui.Spacing()
    imgui.BeginChild("##admin_po_info", imgui.ImVec2(-1, 110), true)
    imgui.TextColored(COLORS.PRIMARY, u8"Что перенесено")
    imgui.BulletText(u8"Главная плиточная навигация по образцу донорского меню")
    imgui.BulletText(u8"Подразделы: мультиаккаунты, NonRP ники, поиск предметов, чекер")
    imgui.BulletText(u8"Пульсирующие карточки и анимированный индикатор на иконках")
    imgui.TextDisabled(u8"Там, где донор опирался на внешние модули/ассеты, сделан встроенный single-file вариант.")
    imgui.EndChild()
end

function MainUI.renderAdminPoPageHeader(title, subtitle)
    if imgui.Button(u8"< Назад##admin_po_back", imgui.ImVec2(86, 28)) then
        AdminPoManager.setPage(0)
    end
