    imgui.TextColored(COLORS.PRIMARY, u8(title))
    imgui.TextDisabled(u8(subtitle or ""))
    imgui.EndGroup()
    imgui.Separator()
end

function MainUI.renderAdminPoMultiPage()
    AdminPoManager.ensureState()
    local state = AdminPoManager.multi
    MainUI.renderAdminPoPageHeader("Админ ПО | Поиск мультиаккаунтов", "Поиск игроков, играющих с одного IP адреса")
    imgui.TextDisabled(u8"Не забывайте, что часть совпадений может быть нормальной при нескольких устройствах.")

    if state.active then
        imgui.TextColored(COLORS.WARNING, u8(string.format("[ %d%% ] Проверка IP: %s", tonumber(state.progress) or 0, tostring(state.current.ip or "-"))))
        imgui.SameLine()
        imgui.TextDisabled(u8"●")
    else
        imgui.TextDisabled(u8"[ Проверка не запущена ]")
    end

    if state.active then
        if imgui.Button(u8"Остановить поиск##admin_po_stop_multi", imgui.ImVec2(170, 26)) then
            AdminPoManager.stopMultiSearch()
        end
    else
        if imgui.Button(u8"Начать поиск##admin_po_start_multi", imgui.ImVec2(170, 26)) then
            local okStart, message = AdminPoManager.startMultiSearch()
            if type(sampAddChatMessage) == "function" and not okStart then
                sampAddChatMessage("[GMEA] " .. tostring(message or "Qidiruvni boshlab bo'lmadi"), 0xFF6666)
            end
        end
    end

    imgui.BeginChild("##admin_po_multi_results", imgui.ImVec2(-1, -1), true)
    imgui.TextColored(COLORS.PRIMARY, u8"IP адрес")
    imgui.SameLine(210)
    imgui.TextColored(COLORS.PRIMARY, u8"Аккаунты")
    imgui.Separator()

    if #state.results == 0 then
        local placeholder = state.active and "Идёт поиск совпадений..." or "Список пуст. Нажмите «Начать поиск»."
        imgui.SetCursorPosY(math.max(32, imgui.GetWindowHeight() * 0.45))
        imgui.TextDisabled(u8(placeholder))
    else
        for index, entry in ipairs(state.results) do
            imgui.Text(u8(tostring(entry.ip or "-")))
            imgui.SameLine(210)
            imgui.PushTextWrapPos(imgui.GetCursorPosX() + imgui.GetContentRegionAvail().x)
            imgui.Text(u8(table.concat(entry.nicks or {}, ", ")))
            imgui.PopTextWrapPos()
            if index < #state.results then
                imgui.Separator()
            end
        end
    end
    imgui.EndChild()
end

function MainUI.renderAdminPoNickPage()
    AdminPoManager.ensureState()
    local state = AdminPoManager.nickCheck
    MainUI.renderAdminPoPageHeader("Админ ПО | Проверка NonRP ников", "Поиск игроков с никами, которые похожи на NonRP или обходные")

    imgui.BeginGroup()
    imgui.Checkbox(u8"Цифры в нике##admin_po_num", state.num)
    imgui.Checkbox(u8"Нет нижнего подчёркивания##admin_po_sep", state.sep)
    imgui.Checkbox(u8"Посторонние символы##admin_po_os", state.os)
    imgui.Checkbox(u8"Более 2-х одинаковых букв##admin_po_m2", state.m2)
    imgui.EndGroup()
    imgui.SameLine(260)
    imgui.BeginGroup()
    imgui.Checkbox(u8"Маленькие буквы в начале##admin_po_ll", state.ll)
    imgui.Checkbox(u8"Большие буквы внутри ника##admin_po_bl", state.bl)
    imgui.Checkbox(u8"Обходные ники##admin_po_bp", state.bp)
    imgui.EndGroup()

    if imgui.Button(u8"Проанализировать##admin_po_analyze_nicks", imgui.ImVec2(170, 28)) then
        AdminPoManager.analyzeNonRPNicks()
    end
    imgui.SameLine()
    imgui.TextDisabled(u8(string.format("Найдено: %d", #(state.results or {}))))

    imgui.BeginChild("##admin_po_nick_results", imgui.ImVec2(-1, -1), true)
    if #(state.results or {}) == 0 then
        imgui.SetCursorPosY(math.max(32, imgui.GetWindowHeight() * 0.45))
        imgui.TextDisabled(u8"Список пуст. Нажмите «Проанализировать». ")
    else
        for index, entry in ipairs(state.results) do
            imgui.Text(u8(tostring(entry.lvl or 0)))
            imgui.SameLine(50)
            imgui.TextColored(COLORS.TEXT, u8(string.format("%s[%d]", tostring(entry.n or "Unknown"), tonumber(entry.id) or 0)))
            imgui.SameLine(285)
            imgui.Text(u8(tostring(entry.reas or "")))
            imgui.SameLine(math.max(380, imgui.GetWindowWidth() - 150))
            if imgui.SmallButton(u8("/sp##admin_po_nick_sp_" .. tostring(index))) then
                PlayerManager.spectate(tonumber(entry.id) or 0)
            end
            imgui.SameLine()
            if imgui.SmallButton(u8("/az##admin_po_nick_az_" .. tostring(index))) then
                sendChat("/az " .. tostring(entry.id))
            end
            imgui.SameLine()
            if imgui.SmallButton(u8("/pm##admin_po_nick_pm_" .. tostring(index))) then
                AdminPoManager.sendNickWarning(entry.id)
            end
            if index < #state.results then
                imgui.Separator()
            end
        end
    end
    imgui.EndChild()
end

function MainUI.renderAdminPoItemPage()
    AdminPoManager.ensureState()
    local state = AdminPoManager.itemSearch
    MainUI.renderAdminPoPageHeader("Админ ПО | Поиск предметов", "Проверка наличия выбранного предмета в инвентарях игроков")

    for index, range in ipairs(AdminPoManager.itemLevelRanges or {}) do
        local selected = state.levelRangeIndex == index
        if selected then
            imgui.PushStyleColor(imgui.Col.Button, COLORS.PRIMARY)
            imgui.PushStyleColor(imgui.Col.ButtonHovered, COLORS.HOVER)
            imgui.PushStyleColor(imgui.Col.ButtonActive, COLORS.ACTIVE)
        end
        if imgui.Button(u8(adminPoFormatRangeLabel(range) .. "##admin_po_range_" .. tostring(index)), imgui.ImVec2(98, 26)) and not state.active then
            state.levelRangeIndex = index
        end
        if selected then
            imgui.PopStyleColor(3)
        end
        if index < #(AdminPoManager.itemLevelRanges or {}) then
            imgui.SameLine()
        end
    end

    imgui.InputText(u8"Предмет##admin_po_item_name", MainUI.buffers.adminPoItemName, 96)
    local currentItem = UtilityManager.bufferToString(MainUI.buffers.adminPoItemName)
    if state.active then
        if imgui.Button(u8(string.format("Остановить [ %d / %d ]##admin_po_stop_item", tonumber(state.progress[1]) or 0, tonumber(state.progress[2]) or 0)), imgui.ImVec2(220, 28)) then
            AdminPoManager.stopItemSearch()
        end
        imgui.SameLine()
        imgui.TextDisabled(u8(string.format("Ищем: %s", tostring(state.selectedItem or "-"))))
    else
        if imgui.Button(u8"Начать поиск##admin_po_start_item", imgui.ImVec2(180, 28)) then
            local okStart, message = AdminPoManager.startItemSearch(currentItem)
            if type(sampAddChatMessage) == "function" and not okStart then
                sampAddChatMessage("[GMEA] " .. tostring(message or "Qidiruvni boshlab bo'lmadi"), 0xFF6666)
            end
        end
        imgui.SameLine()
        imgui.TextDisabled(u8(string.format("Текущий предмет: %s", currentItem ~= "" and currentItem or "Не выбран")))
    end

    imgui.BeginChild("##admin_po_item_results", imgui.ImVec2(-1, -1), true)
    imgui.TextColored(COLORS.PRIMARY, u8"Игрок")
    imgui.SameLine(255)
    imgui.TextColored(COLORS.PRIMARY, u8"Уровень")
    imgui.SameLine(365)
    imgui.TextColored(COLORS.PRIMARY, u8"Количество")
    imgui.Separator()

    if #(state.results or {}) == 0 then
        local placeholder = state.active and "Идёт поиск предмета..." or "Выберите диапазон уровней, предмет и запустите поиск."
        imgui.SetCursorPosY(math.max(32, imgui.GetWindowHeight() * 0.45))
        imgui.TextDisabled(u8(placeholder))
    else
        for index, entry in ipairs(state.results) do
            local liveId = AdminPoManager.resolveNickToId(entry.nick)
            imgui.Text(u8(string.format("%s(%s)", tostring(entry.nick or "Unknown"), liveId and tostring(liveId) or "OFF")))
            imgui.SameLine(255)
            imgui.Text(u8(tostring(entry.level or 0)))
            imgui.SameLine(365)
            imgui.Text(u8(string.format("%s шт.", tostring(entry.count or 0))))
            if liveId then
                imgui.SameLine(math.max(420, imgui.GetWindowWidth() - 76))
                if imgui.SmallButton(u8("SP##admin_po_item_sp_" .. tostring(index))) then
                    PlayerManager.spectate(liveId)
                end
            end
            if index < #state.results then
                imgui.Separator()
            end
        end
    end
    imgui.EndChild()
end

