function MainUI.renderFuraMonitor()
    if not MainUI.renderFuraAccessGuard("tab") then
        return
    end

    local disabled = imgui.ImBool(MainUI.isFuraMenuDisabled())
    if imgui.Checkbox(u8"Fura menyusini to'liq o'chirish##fura_disable_tab", disabled) then
        SettingsManager.set("furaMenuDisabled", disabled[0])
    end
    if MainUI.isFuraMenuDisabled() then
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"Fura menyusi o'chirilgan. Bu bo'limdagi funksiyalar ishlamaydi.")
        return
    end

    imgui.Separator()

    local enabled = imgui.ImBool(FuraKillManager.enabled)
    if imgui.Checkbox(u8"Enable Fura Kill Monitor", enabled) then
        FuraKillManager.setEnabled(enabled[0])
    end
    imgui.SameLine()
    if FuraKillManager.enabled then
        imgui.TextColored(COLORS.PRIMARY or imgui.ImVec4(0.15, 0.68, 0.38, 1.0), "[ON]")
    else
        imgui.TextColored(COLORS.DANGER or imgui.ImVec4(0.90, 0.30, 0.30, 1.0), "[OFF]")
    end

    local activeState = "Idle"
    if FuraKillManager.activeCheck then
        local phase = FuraKillManager.activeCheck.phase or "pending"
        local side = FuraKillManager.activeCheck[phase]
        if side then
            activeState = string.format("Checking %s: %s", phase, FuraKillManager.playerLabel(side.id, side.nick))
        else
            activeState = "Checking"
        end
    end

    imgui.TextDisabled(string.format("Queue: %d | Confirmed: %d | Live feed: %d | State: %s",
        #FuraKillManager.pendingChecks, #FuraKillManager.kills, #FuraKillManager.killFeed, activeState))
    imgui.TextDisabled("Rule: killer/victim /stats ichida jinoiy guruh matni qayerda kelsa ham hisoblanadi")
    imgui.TextDisabled(string.format("Priority mode: %s | Background updates deferred while Fura is ON",
        FuraKillManager.profileName == "smooth" and "ON" or "OFF"))

    if imgui.Button(u8"Export TXT", imgui.ImVec2(120, 30)) then
        local path = UtilityManager.getWorkingDirectorySafe() .. "/fura_kills_" .. os.time() .. ".txt"
        local ok = FuraKillManager.exportToTxt(path)
        if ok then
            sampAddChatMessage("[GMEA] Fura kill export saved: " .. path, 0x33FF66)
        else
            sampAddChatMessage("[GMEA] Fura kill export failed", 0xFF6666)
        end
    end
    imgui.SameLine()
    if imgui.Button(u8"Clear List", imgui.ImVec2(120, 30)) then
        FuraKillManager.clearData()
    end

    if FuraKillManager.lastExportPath ~= "" then
        imgui.TextDisabled("Last export: " .. FuraKillManager.lastExportPath)
    end

    imgui.Separator()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Summary")
    imgui.Text(string.format("G'alaba qozongan jinoiy guruh (oxirgi kill): %s", FuraKillManager.getWinningCriminalGroup()))

    local top = FuraKillManager.getTopKiller()
    if top then
        imgui.Text(string.format("Eng kop kill qilgan: %s - %d",
            FuraKillManager.playerLabel(top.id, top.nick), top.kills))
    else
        imgui.Text("Eng kop kill qilgan: N/A")
    end

    if FuraKillManager.firstKill then
        local firstCount = (FuraKillManager.killerStats[tostring(FuraKillManager.firstKill.killerId)] or {}).kills or 1
        imgui.Text(string.format("Eng birinchi kill qilgan: %s - %d",
            FuraKillManager.playerLabel(FuraKillManager.firstKill.killerId, FuraKillManager.firstKill.killerNick),
            firstCount))
    else
        imgui.Text("Eng birinchi kill qilgan: N/A")
    end

    if FuraKillManager.lastKill then
        local lastCount = (FuraKillManager.killerStats[tostring(FuraKillManager.lastKill.killerId)] or {}).kills or 1
        imgui.Text(string.format("Eng oxirgi kill qilgan: %s - %d",
            FuraKillManager.playerLabel(FuraKillManager.lastKill.killerId, FuraKillManager.lastKill.killerNick),
            lastCount))
    else
        imgui.Text("Eng oxirgi kill qilgan: N/A")
    end
    imgui.Text(string.format("TK (bir xil guruh): %d", FuraKillManager.getTeamKillCount()))

    imgui.Separator()

    if imgui.CollapsingHeader(u8"Killerlar ro'yxati") then
        local killers = FuraKillManager.getSortedKillerStats()
        if #killers == 0 then
            imgui.TextDisabled("No killers tracked yet")
        else
            for _, entry in ipairs(killers) do
                imgui.BulletText(string.format("%s - %d",
                    FuraKillManager.playerLabel(entry.id, entry.nick), entry.kills))
            end
        end
    end

    if imgui.CollapsingHeader(u8"Guruh bo'yicha kill") then
        local groupStats = FuraKillManager.getSortedGroupStats(FuraKillManager.groupKillStats)
        if #groupStats == 0 then
            imgui.TextDisabled("No groups tracked yet")
        else
            for _, entry in ipairs(groupStats) do
                imgui.BulletText(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
            end
        end
    end

    if imgui.CollapsingHeader(u8"TK (bir xil guruh)") then
        local tkStats = FuraKillManager.getSortedGroupStats(FuraKillManager.teamKillStats)
        if #tkStats == 0 then
            imgui.TextDisabled("No TK tracked yet")
        else
            for _, entry in ipairs(tkStats) do
                imgui.BulletText(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
            end
        end
    end

    if imgui.CollapsingHeader(u8"Kill log (o'ldirgan | o'lgan)") then
        imgui.BeginChild("##FuraKillLog", imgui.ImVec2(0, 220), true)
        if #FuraKillManager.killFeed == 0 then
            imgui.TextDisabled("No tracked kills")
        else
            for i = #FuraKillManager.killFeed, 1, -1 do
                local record = FuraKillManager.killFeed[i]
                local killerGroup = UtilityManager.trim(tostring(record.killerGroup or ""))
                local victimGroup = UtilityManager.trim(tostring(record.victimGroup or ""))
                if killerGroup == "" then killerGroup = "Noma'lum guruh" end
                if victimGroup == "" then victimGroup = "Noma'lum guruh" end
                local verificationState = tostring(record.verificationState or "pending")
                local statusText = "[PENDING]"
                if verificationState == "confirmed" then
                    statusText = "[OK]"
                elseif verificationState == "checking_victim" then
                    statusText = "[VICTIM]"
                elseif verificationState == "ignored" then
                    statusText = "[SKIP]"
                end
                local tkText = record.isTeamKill and " [TK]" or ""
                imgui.Text(string.format("%s %s: %s oldirdi %s%s",
                    statusText,
                    string.format("%s -> %s", killerGroup, victimGroup),
                    FuraKillManager.playerLabel(record.killerId, record.killerNick),
                    FuraKillManager.playerLabel(record.victimId, record.victimNick),
                    tkText))
                imgui.SameLine()
                imgui.TextDisabled(record.formattedTime or "")
            end
        end
        imgui.EndChild()
    end
end

function MainUI.renderGossOpgMonitor()
    if not MainUI.renderFuraAccessGuard("gossopg") then
        return
    end

    if MainUI.isFuraMenuDisabled() then
        imgui.TextColored(COLORS.WARNING or imgui.ImVec4(0.95, 0.77, 0.06, 1.0), u8"Fura menyusi o'chirilgan. Bu bo'limdagi funksiyalar ishlamaydi.")
        return
    end

    imgui.Separator()

    local enabled = imgui.ImBool(GossOpgMonitorManager.enabled)
    if imgui.Checkbox(u8"Goss OPG monitorni yoqish", enabled) then
        GossOpgMonitorManager.setEnabled(enabled[0])
    end
    imgui.SameLine()
    if GossOpgMonitorManager.enabled then
        imgui.TextColored(COLORS.PRIMARY or imgui.ImVec4(0.15, 0.68, 0.38, 1.0), "[ON]")
    else
        imgui.TextColored(COLORS.DANGER or imgui.ImVec4(0.90, 0.30, 0.30, 1.0), "[OFF]")
    end

    local activeState = "Idle"
    if GossOpgMonitorManager.activeCheck then
        local phase = GossOpgMonitorManager.activeCheck.phase or "pending"
        local side = GossOpgMonitorManager.activeCheck[phase]
        if side then
            activeState = string.format("Tekshirilmoqda (%s): %s", phase, GossOpgMonitorManager.playerLabel(side.id, side.nick))
        else
            activeState = "Tekshirilmoqda"
        end
    end

    imgui.TextDisabled(string.format("Navbat: %d | Yozilgan killlar: %d | Holat: %s",
        #GossOpgMonitorManager.pendingChecks, #GossOpgMonitorManager.kills, activeState))
    imgui.TextDisabled(u8"Rule: kill list faqat o'ldirish eventidan yoziladi, /stats ichidan tashkilot aniqlanadi")
    imgui.TextDisabled(u8"Tashkilotlar: FSB, Hukumat, Harbiy, Arzamas/Janubiy med-police, Yangiliklar, va barcha OPG")

    if imgui.Button(u8"TXT eksport##gossopg_export", imgui.ImVec2(140, 30)) then
        local path = UtilityManager.getWorkingDirectorySafe() .. "/goss_opg_kills_" .. os.time() .. ".txt"
        local ok = GossOpgMonitorManager.exportToTxt(path)
        if ok then
            sampAddChatMessage("[GMEA] Goss OPG export saved: " .. path, 0x33FF66)
        else
            sampAddChatMessage("[GMEA] Goss OPG export failed", 0xFF6666)
        end
    end
    imgui.SameLine()
    if imgui.Button(u8"Ro'yxatni tozalash##gossopg_clear", imgui.ImVec2(120, 30)) then
        GossOpgMonitorManager.clearData()
    end

    if GossOpgMonitorManager.lastExportPath ~= "" then
        imgui.TextDisabled("Oxirgi eksport: " .. GossOpgMonitorManager.lastExportPath)
    end

    imgui.Separator()
    imgui.TextColored(COLORS.INFO or imgui.ImVec4(0.20, 0.60, 0.86, 1.0), u8"Qisqa hisobot")
    imgui.Text(string.format("G'olib tomon (oxirgi kill): %s", GossOpgMonitorManager.getWinningSide()))
    imgui.Text(string.format("Oxirgi kill qilgan tashkilot: %s", GossOpgMonitorManager.getLeadingOrganization()))
    imgui.Text(string.format("TK (bir tomon ichida): %d", GossOpgMonitorManager.getTeamKillCount()))

    local top = GossOpgMonitorManager.getTopKiller()
    if top then
        imgui.Text(string.format("Eng kop kill qilgan: %s - %d",
            GossOpgMonitorManager.playerLabel(top.id, top.nick), top.kills))
    else
        imgui.Text("Eng kop kill qilgan: N/A")
    end

    local topOrgName, topOrgKills = GossOpgMonitorManager.getTopOrganizationByKills()
    if topOrgName then
        imgui.Text(string.format("Eng kop kill qilgan tashkilot: %s - %d", topOrgName, topOrgKills))
    else
        imgui.Text("Eng kop kill qilgan tashkilot: N/A")
    end

    local first = GossOpgMonitorManager.firstKill
    if first then
        imgui.Text(string.format("Eng birinchi kill qilgan: %s %s (%s)",
            GossOpgMonitorManager.getSideTag(first.killerSide),
            GossOpgMonitorManager.playerLabel(first.killerId, first.killerNick),
            first.formattedTime or ""))
    else
        imgui.Text("Eng birinchi kill qilgan: N/A")
    end

    local last = GossOpgMonitorManager.kills[#GossOpgMonitorManager.kills]
    if not last then
        last = GossOpgMonitorManager.lastKill
    end
    if last then
        imgui.Text(string.format("Eng oxirgi kill qilgan: %s %s (%s)",
            GossOpgMonitorManager.getSideTag(last.killerSide),
            GossOpgMonitorManager.playerLabel(last.killerId, last.killerNick),
            last.formattedTime or ""))
    else
        imgui.Text("Eng oxirgi kill qilgan: N/A")
    end

    if imgui.CollapsingHeader(u8"Killerlar ro'yxati##gossopg_killers") then
        local killers = GossOpgMonitorManager.getSortedKillerStats()
        if #killers == 0 then
            imgui.TextDisabled("Hali kill yozilmagan")
        else
            for _, entry in ipairs(killers) do
                imgui.BulletText(string.format("%s - %d",
                    GossOpgMonitorManager.playerLabel(entry.id, entry.nick), entry.kills))
            end
        end
    end

    if imgui.CollapsingHeader(u8"Tashkilot bo'yicha kill##gossopg_orgkills") then
        local orgStats = GossOpgMonitorManager.getSortedGroupStats(GossOpgMonitorManager.organizationKillStats)
        if #orgStats == 0 then
            imgui.TextDisabled("Tashkilotlar bo'yicha ma'lumot yo'q")
        else
            for _, entry in ipairs(orgStats) do
                imgui.BulletText(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
            end
        end
    end

    if imgui.CollapsingHeader(u8"TK (bir tomon ichida)##gossopg_tk") then
        local tkStats = GossOpgMonitorManager.getSortedGroupStats(GossOpgMonitorManager.teamKillStats)
        if #tkStats == 0 then
            imgui.TextDisabled("TK holatlari yozilmagan")
        else
            for _, entry in ipairs(tkStats) do
                imgui.BulletText(string.format("%s - %d", tostring(entry.group), tonumber(entry.count) or 0))
            end
        end
    end

    if imgui.CollapsingHeader(u8"Kill log (o'ldirgan | o'lgan)##gossopg_log") then
        imgui.BeginChild("##GossOpgKillLog", imgui.ImVec2(0, 220), true)
        if #GossOpgMonitorManager.kills == 0 then
            imgui.TextDisabled("Kill log bo'sh")
        else
            for i = #GossOpgMonitorManager.kills, 1, -1 do
                local record = GossOpgMonitorManager.kills[i]
                local killerOrg = UtilityManager.trim(tostring(record.killerOrg or ""))
                local victimOrg = UtilityManager.trim(tostring(record.victimOrg or ""))
                if killerOrg == "" then killerOrg = "Noma'lum tashkilot" end
                if victimOrg == "" then victimOrg = "Noma'lum tashkilot" end
                local tkText = record.isTeamKill and " [TK]" or ""
                local killerTag = GossOpgMonitorManager.getSideTag(record.killerSide)
                local victimTag = GossOpgMonitorManager.getSideTag(record.victimSide)
                imgui.Text(string.format("%s: %s %s oldirdi %s %s%s",
                    string.format("%s -> %s", killerOrg, victimOrg),
                    killerTag,
                    GossOpgMonitorManager.playerLabel(record.killerId, record.killerNick),
                    victimTag,
                    GossOpgMonitorManager.playerLabel(record.victimId, record.victimNick),
                    tkText))
                imgui.SameLine()
                imgui.TextDisabled(record.formattedTime or "")
            end
        end
        imgui.EndChild()
    end
end

function MainUI.renderSettings()
    if imgui.CollapsingHeader(u8"Appearance") then
        local presets = MainUI.getThemePresets()
        local currentPresetIndex = MainUI.findThemePresetIndex(SettingsManager.get("themePreset"))
        local previewName = presets[currentPresetIndex] and presets[currentPresetIndex].name or presets[1].name
        if imgui.BeginCombo(u8"Design preset", previewName) then
            for i, preset in ipairs(presets) do
                if imgui.Selectable(preset.name, currentPresetIndex == i) then
                    SettingsManager.set("themePreset", preset.name)
                    SettingsManager.set("primaryColor", { preset.rgb[1], preset.rgb[2], preset.rgb[3] })
                    SettingsManager.save()
                    MainUI.applyConfiguredAccent()
                    if not MainUI.buffers.primaryColor then
                        MainUI.buffers.primaryColor = imgui.new.float[3]()
                    end
                    MainUI.buffers.primaryColor[0] = preset.rgb[1] / 255
                    MainUI.buffers.primaryColor[1] = preset.rgb[2] / 255
                    MainUI.buffers.primaryColor[2] = preset.rgb[3] / 255
                end
            end
            imgui.EndCombo()
        end

        imgui.Text(u8"Primary Color:")
        if not MainUI.buffers.primaryColor then
            MainUI.buffers.primaryColor = imgui.new.float[3]()
        end
        local storedPrimary = SettingsManager.get("primaryColor") or { 189, 38, 51 }
        if not MainUI._primaryColorSynced then
            MainUI.buffers.primaryColor[0] = (tonumber(storedPrimary[1]) or 189) / 255
            MainUI.buffers.primaryColor[1] = (tonumber(storedPrimary[2]) or 38) / 255
            MainUI.buffers.primaryColor[2] = (tonumber(storedPrimary[3]) or 51) / 255
            MainUI._primaryColorSynced = true
        end
        if imgui.ColorEdit3("##PrimaryColor", MainUI.buffers.primaryColor) then
            local rgb = {
                math.floor(UtilityManager.clamp(MainUI.buffers.primaryColor[0], 0, 1) * 255),
                math.floor(UtilityManager.clamp(MainUI.buffers.primaryColor[1], 0, 1) * 255),
                math.floor(UtilityManager.clamp(MainUI.buffers.primaryColor[2], 0, 1) * 255)
            }
            SettingsManager.set("primaryColor", rgb)
            SettingsManager.save()
            MainUI.applyConfiguredAccent()
        end

        local particlesEnabled = imgui.ImBool(SettingsManager.get("menuParticlesEnabled") == true)
        if imgui.Checkbox(u8"Qimirlovchi ikonka zarralari##menu_particles_enabled", particlesEnabled) then
            SettingsManager.set("menuParticlesEnabled", particlesEnabled[0])
            SettingsManager.save()
            MainUI.markMenuParticlesDirty()
        end

        local particleCount = imgui.ImInt(tonumber(SettingsManager.get("menuParticlesCount")) or 16)
        if imgui.SliderInt(u8"Ikonka soni##menu_particles_count", particleCount, 4, 40) then
            SettingsManager.set("menuParticlesCount", particleCount[0])
            SettingsManager.save()
            MainUI.markMenuParticlesDirty()
        end

        local particleSpeed = imgui.ImFloat(tonumber(SettingsManager.get("menuParticlesSpeed")) or 0.85)
        if imgui.SliderFloat(u8"Ikonka tezligi##menu_particles_speed", particleSpeed, 0.10, 4.0, "%.2f") then
            SettingsManager.set("menuParticlesSpeed", particleSpeed[0])
            SettingsManager.save()
        end

        local particleAlpha = imgui.ImFloat(tonumber(SettingsManager.get("menuParticlesAlpha")) or 0.34)
        if imgui.SliderFloat(u8"Ikonka alpha##menu_particles_alpha", particleAlpha, 0.05, 1.0, "%.2f") then
            SettingsManager.set("menuParticlesAlpha", particleAlpha[0])
            SettingsManager.save()
        end
    end

    if imgui.CollapsingHeader(u8"Interface") then
        imgui.TextColored(COLORS.PRIMARY, u8"Animated neon design")
        imgui.TextDisabled(u8"Buttonlar glow bilan ishlaydi, fon bo'ylab ikonka-zarralar yuradi.")
        imgui.TextDisabled(u8"Rang o'zgarsa border, hover va accent ham birga yangilanadi.")

        local killListOverlay = imgui.ImBool(SettingsManager.get("killListOverlayEnabled") == true)
        if imgui.Checkbox(u8"Kill List overlay", killListOverlay) then
            SettingsManager.set("killListOverlayEnabled", killListOverlay[0])
            if KillListManager and KillListManager.flushOverlayState then
                KillListManager.flushOverlayState(true)
            end
            SettingsManager.save()
        end
        imgui.TextDisabled(u8"Overlay o'chsa ham kill loglar yozilishda davom etadi.")
    end

    if imgui.CollapsingHeader(u8"Hotkeys") then
        imgui.Text(string.format("Current Toggle Key: %s", SettingsManager.getHotkeyName()))
        imgui.TextDisabled(u8"Press M to toggle panel")
    end

    if imgui.CollapsingHeader(u8"Approval") then
        imgui.TextDisabled(u8"Local rejimda approval/parol talabi o'chirilgan.")
    end

    if imgui.CollapsingHeader(u8"Quick Action Hotkeys") then
        local enabled = imgui.ImBool(SettingsManager.get("quickHotkeysEnabled") ~= false)
        if imgui.Checkbox(u8"Enable quick hotkeys", enabled) then
            SettingsManager.set("quickHotkeysEnabled", enabled[0])
        end

        if not MainUI.buffers.quickSpecKey then
            MainUI.buffers.quickModifierKey = imgui.ImInt(tonumber(SettingsManager.get("quickHotkeyModifier")) or vkeys.VK_MENU)
            MainUI.buffers.quickSpecKey = imgui.ImInt(tonumber(SettingsManager.get("quickHotkeySpec")) or vkeys.VK_1)
            MainUI.buffers.quickTpKey = imgui.ImInt(tonumber(SettingsManager.get("quickHotkeyTeleport")) or vkeys.VK_2)
            MainUI.buffers.quickFreezeKey = imgui.ImInt(tonumber(SettingsManager.get("quickHotkeyFreeze")) or vkeys.VK_3)
            MainUI.buffers.quickJailKey = imgui.ImInt(tonumber(SettingsManager.get("quickHotkeyJail")) or vkeys.VK_4)
        end

        if imgui.InputInt(u8"Modifier key code", MainUI.buffers.quickModifierKey) then
            SettingsManager.set("quickHotkeyModifier", MainUI.buffers.quickModifierKey[0])
        end
        if imgui.InputInt(u8"Spec key code", MainUI.buffers.quickSpecKey) then
            SettingsManager.set("quickHotkeySpec", MainUI.buffers.quickSpecKey[0])
        end
        if imgui.InputInt(u8"TP key code", MainUI.buffers.quickTpKey) then
            SettingsManager.set("quickHotkeyTeleport", MainUI.buffers.quickTpKey[0])
        end
        if imgui.InputInt(u8"Freeze key code", MainUI.buffers.quickFreezeKey) then
            SettingsManager.set("quickHotkeyFreeze", MainUI.buffers.quickFreezeKey[0])
        end
        if imgui.InputInt(u8"Jail key code", MainUI.buffers.quickJailKey) then
            SettingsManager.set("quickHotkeyJail", MainUI.buffers.quickJailKey[0])
        end
        imgui.TextDisabled("Default: ALT + 1/2/3/4")
    end

    if imgui.CollapsingHeader(u8"AFK Settings") then
        local afkEnabled = imgui.ImBool(SettingsManager.get("afkEnabled"))
        if imgui.Checkbox(u8"Enable AFK Detection", afkEnabled) then
            SettingsManager.set("afkEnabled", afkEnabled[0])
        end

        imgui.TextDisabled(string.format("AFK Timeout: %d seconds", CONFIG.AFK_TIMEOUT))
    end

    if imgui.CollapsingHeader(u8"Auto Save") then
        local autoSave = imgui.ImBool(SettingsManager.get("autoSave"))
        if imgui.Checkbox(u8"Enable Auto Save", autoSave) then
            SettingsManager.set("autoSave", autoSave[0])
        end

        imgui.TextDisabled(string.format("Save Interval: %d seconds", CONFIG.AUTO_SAVE_INTERVAL))
    end

    if imgui.CollapsingHeader(u8"Language") then
        local langItems = {"Uzbek", "English", "Russian"}
        local currentLang = 1
        if imgui.BeginCombo(u8"Language", langItems[currentLang]) then
            for i, lang in ipairs(langItems) do
                if imgui.Selectable(lang, currentLang == i) then
                    SettingsManager.set("language", lang:lower():sub(1, 2))
                end
            end
            imgui.EndCombo()
        end
    end

    imgui.Separator()
    if imgui.Button(u8"Save Settings", imgui.ImVec2(120, 30)) then
        SettingsManager.save()
    end
    imgui.SameLine()
    if imgui.Button(u8"Factory Reset", imgui.ImVec2(120, 30)) then
        SettingsManager.reset()
    end

    imgui.Separator()
    imgui.TextDisabled(string.format("Grand Mobile Enterprise Admin v%s", CONFIG.VERSION))
    imgui.TextDisabled("Built for MoonLoader SAMP")
end

function MainUI.renderApprovalWaiting()
    local statusLabel = "Unknown"
    local statusRaw = nil
    if ApprovalGuard and ApprovalGuard.getStatus then
        statusRaw = ApprovalGuard.getStatus()
    end
    if ApprovalGuard and ApprovalGuard.statusLabel then
        statusLabel = ApprovalGuard.statusLabel()
    end

    if statusRaw == "blocked" or statusRaw == "banned" then
        imgui.TextColored(COLORS.DANGER, u8"Access blocked")
    elseif statusRaw == "pending" then
        imgui.TextColored(COLORS.WARNING, u8"Waiting for admin approval")
    else
        imgui.TextColored(COLORS.WARNING, u8"Verifying access status...")
    end

    imgui.TextDisabled(u8("Status: " .. statusLabel))
    imgui.Spacing()
    if statusRaw == "pending" then
        imgui.TextWrapped(u8"Your access request has been registered automatically. Please wait until an admin approves it.")
        imgui.Spacing()
    end
    imgui.TextDisabled(u8"Tool functions are disabled until approval.")
end

function MainUI.renderApproval()
    if ApprovalManager and ApprovalManager.render then
        ApprovalManager.render()
        return
    end
    imgui.TextDisabled(u8"Approval manager not available.")
end

function MainUI.renderChiefAdministrator()
    if ChiefAdminManager and ChiefAdminManager.render then
        ChiefAdminManager.render()
        return
    end
    imgui.TextDisabled("Chief Administrator manager not available.")
end

function MainUI.renderAdminPo()
    if not PermissionGuard.has("menu.admin_po") then
        imgui.TextColored(imgui.ImVec4(1, 0.3, 0.3, 1), u8"Kirish taqiqlangan")
        return
    end

    AdminPoManager.ensureState()
    local page = tonumber(AdminPoManager.page) or 0

    if page == 0 then
        MainUI.renderAdminPoOverview()
    elseif page == 1 then
        MainUI.renderAdminPoMultiPage()
    elseif page == 2 then
        MainUI.renderAdminPoNickPage()
    elseif page == 3 then
        MainUI.renderAdminPoItemPage()
    elseif page == 4 then
        MainUI.renderAdminPoPageHeader("Админ ПО | Чекер игроков", "Списки слежки, заметки и быстрые действия по онлайну")
        MainUI.renderAdminPoTrackerWorkspace()
    elseif page == 5 then
        MainUI.renderAdminPoPageHeader("Админ ПО | Чит-функции", "Старый функционал вашего таба сохранён отдельной страницей")
        MainUI.renderAdminPoLegacyCheats()
    else
        AdminPoManager.setPage(0)
        MainUI.renderAdminPoOverview()
    end
end


end

BOOT_LOGGER.write("Inlining module: admin/admin_modes_manager.lua")
do
-- ============================================
-- ADMIN MODES MANAGER
-- ============================================
AdminModesManager = {
    lastTickMs = 0,
    lastGodState = false,
    lastInvisibleState = false,
    warnedGodUnsupported = false,
    warnedInvisibleUnsupported = false
}

function AdminModesManager.getNowMs()
    return UtilityManager.getNowMs()
end

function AdminModesManager.getLocalPed()
    if not PLAYER_PED then
        return nil
    end

    if type(doesCharExist) == "function" then
        local okExists, exists = pcall(doesCharExist, PLAYER_PED)
        if okExists and not exists then
            return nil
        end
    end

    return PLAYER_PED
end

function AdminModesManager.tryGlobalCall(fnName, ...)
    local fn = _G[fnName]
    if type(fn) ~= "function" then
        return false
    end
    local ok = pcall(fn, ...)
    return ok
end

function AdminModesManager.getPedVehicle(ped)
    if not ped then
        return nil
    end

    local vehicle = nil
    if type(storeCarCharIsInNoSave) == "function" then
        local okCar, car = pcall(storeCarCharIsInNoSave, ped)
        if okCar then
            vehicle = tonumber(car)
        end
    elseif type(storeCarCharIsIn) == "function" then
        local okCar, car = pcall(storeCarCharIsIn, ped)
        if okCar then
            vehicle = tonumber(car)
        end
    end

    if not vehicle then
        return nil
    end

    if type(doesVehicleExist) == "function" then
        local okExists, exists = pcall(doesVehicleExist, vehicle)
        if okExists and not exists then
            return nil
        end
    end

    return vehicle
end

function AdminModesManager.applyGodMode(enabled)
    local ped = AdminModesManager.getLocalPed()
    if not ped then
        return false
    end

    local applied = false

    if enabled then
        if AdminModesManager.tryGlobalCall("setCharHealth", ped, 999.0) then
            applied = true
        elseif AdminModesManager.tryGlobalCall("setCharHealth", ped, 100.0) then
            applied = true
        end

        if AdminModesManager.tryGlobalCall("setCharProofs", ped, true, true, true, true, true) then
            applied = true
        end

        local vehicle = AdminModesManager.getPedVehicle(ped)
        if vehicle then
            if AdminModesManager.tryGlobalCall("setCarHealth", vehicle, 1000.0) then
                applied = true
            end
            if AdminModesManager.tryGlobalCall("setCarProofs", vehicle, true, true, true, true, true) then
                applied = true
            end
        end
    else
        AdminModesManager.tryGlobalCall("setCharProofs", ped, false, false, false, false, false)
        local vehicle = AdminModesManager.getPedVehicle(ped)
        if vehicle then
            AdminModesManager.tryGlobalCall("setCarProofs", vehicle, false, false, false, false, false)
        end
        applied = true
    end

    return applied
end

function AdminModesManager.applyInvisibleMode(enabled)
    local ped = AdminModesManager.getLocalPed()
    if not ped then
        return false
    end

    local applied = false

    if enabled then
        if AdminModesManager.tryGlobalCall("setCharVisible", ped, false) then
            applied = true
        end
        if AdminModesManager.tryGlobalCall("setCharAlpha", ped, 0) then
            applied = true
        end
    else
        if AdminModesManager.tryGlobalCall("setCharVisible", ped, true) then
            applied = true
        end
        if AdminModesManager.tryGlobalCall("setCharAlpha", ped, 255) then
            applied = true
        end
    end

    return applied
end

function AdminModesManager.update()
    local nowMs = AdminModesManager.getNowMs()
    if (nowMs - AdminModesManager.lastTickMs) < 120 then
        return
    end
    AdminModesManager.lastTickMs = nowMs

    local godEnabled = SettingsManager.get("godMode") == true
    local invisibleEnabled = SettingsManager.get("invisible") == true

    if godEnabled then
        local okGod = AdminModesManager.applyGodMode(true)
        if not okGod and not AdminModesManager.warnedGodUnsupported then
            AdminModesManager.warnedGodUnsupported = true
            sampAddChatMessage("[GMEA] God Mode API topilmadi (build mos emas).", 0xFF6666)
        end
    elseif AdminModesManager.lastGodState then
        AdminModesManager.applyGodMode(false)
    end

    if invisibleEnabled then
        local okInvisible = AdminModesManager.applyInvisibleMode(true)
        if not okInvisible and not AdminModesManager.warnedInvisibleUnsupported then
            AdminModesManager.warnedInvisibleUnsupported = true
            sampAddChatMessage("[GMEA] Invisible Mode API topilmadi (build mos emas).", 0xFF6666)
        end
    elseif AdminModesManager.lastInvisibleState then
        AdminModesManager.applyInvisibleMode(false)
    end

    AdminModesManager.lastGodState = godEnabled
    AdminModesManager.lastInvisibleState = invisibleEnabled
end

function AdminModesManager.restore()
    AdminModesManager.applyInvisibleMode(false)
    AdminModesManager.applyGodMode(false)
end


end

