function CheatFunctions.enableWallhackPed(enabled)
    if type(sampGetServerSettingsPtr) ~= "function" then
        return
    end

    local ok, ptr = pcall(sampGetServerSettingsPtr)
    if not ok or not ptr then
        return
    end

    local mem = memory
    if not mem or not mem.setfloat or not mem.setint8 then
        return
    end

    if enabled then
        local dist = CheatFunctions.whPed and CheatFunctions.whDistance or 25
        local ok1 = pcall(mem.setfloat, ptr + 39, dist)
        local ok2 = pcall(mem.setint8, ptr + 47, 0)
    else
        local ok1 = pcall(mem.setfloat, ptr + 39, 25)
        local ok2 = pcall(mem.setint8, ptr + 47, 1)
    end
end

function CheatFunctions.enableWallhackVeh(enabled)
    CheatFunctions.whVeh = enabled
    if enabled and CheatFunctions.whVehSync then
        CheatFunctions.whVehSync = false
    end
