function CheatFunctions.applyGodMode(enabled)
    local ped = PLAYER_PED
    if not ped or type(doesCharExist) ~= "function" then
        return false
    end

    local ok, exists = pcall(doesCharExist, ped)
    if not ok or not exists then
        return false
    end

    if enabled then
        if type(setCharProofs) == "function" then
            pcall(setCharProofs, ped, true, true, true, true, true)
        end
        if type(setCharHealth) == "function" then
            pcall(setCharHealth, ped, 999.0)
        end

        if type(isInCar) == "function" then
            local okInCar, inCar = pcall(isInCar)
            if okInCar and inCar then
                if type(storeCarCharIsInNoSave) == "function" then
                    local okVeh, vehicle = pcall(storeCarCharIsInNoSave, ped)
                    if okVeh and vehicle then
                        if type(setCarProofs) == "function" then
                            pcall(setCarProofs, vehicle, true, true, true, true, true)
                        end
                        if type(setCarCanBeDamaged) == "function" then
                            pcall(setCarCanBeDamaged, vehicle, false)
                        end
                        if type(setCarHealth) == "function" then
                            pcall(setCarHealth, vehicle, 1000.0)
                        end
                    end
                end
            end
        end
    else
        if type(setCharProofs) == "function" then
            pcall(setCharProofs, ped, false, false, false, false, false)
        end

        if type(isInCar) == "function" then
            local okInCar, inCar = pcall(isInCar)
            if okInCar and inCar then
                if type(storeCarCharIsInNoSave) == "function" then
                    local okVeh, vehicle = pcall(storeCarCharIsInNoSave, ped)
                    if okVeh and vehicle then
                        if type(setCarProofs) == "function" then
                            pcall(setCarProofs, vehicle, false, false, false, false, false)
                        end
                        if type(setCarCanBeDamaged) == "function" then
                            pcall(setCarCanBeDamaged, vehicle, true)
                        end
                    end
                end
            end
        end
    end

    return true
end

function CheatFunctions.applyFOV(enabled)
    local mem = memory
    if not mem or not mem.setfloat then
        return
    end

    local addr = 9265400
    if enabled then
        pcall(mem.setfloat, addr + 16, CheatFunctions.fovValue)
    else
        pcall(mem.setfloat, addr + 16, 70.0)
