        pcall(mem.setfloat, 9252668, 0.6)
        pcall(mem.setfloat, 9252672, 0.3)
        pcall(mem.setfloat, 9252676, 0.5)
    else
        pcall(mem.setfloat, 9252664, 0.8)
        pcall(mem.setfloat, 9252668, 0.0)
        pcall(mem.setfloat, 9252672, 0.0)
        pcall(mem.setfloat, 9252676, 0.0)
    end
end

