do

ToolsStatusManager = {}

function ToolsStatusManager.getModules()
    local function chk(name, obj, extraCheck)
        local ok = type(obj) == "table"
        if ok and type(extraCheck) == "function" then
            local s, r = pcall(extraCheck, obj)
            ok = s and r == true
        end
        return { name = name, ok = ok }
    end
    return {
        chk("RuntimeGuard",          RuntimeGuard,          function(o) return type(o.call) == "function" end),
        chk("UtilityManager",        UtilityManager,        function(o) return type(o.getNowMs) == "function" end),
        chk("LogManager",            LogManager,            function(o) return type(o.add) == "function" and o.fileReady == true end),
        chk("SettingsManager",       SettingsManager,       function(o) return type(o.get) == "function" end),
        chk("PermissionGuard",       PermissionGuard,       function(o) return type(o.allowCommand) == "function" end),
        chk("ApprovalGuard",         ApprovalGuard,         function(o) return type(o.canExecute) == "function" end),
        chk("RoleManager",           RoleManager,           function(o) return type(o.getPrimaryRole) == "function" end),
        chk("ReconnectManager",      ReconnectManager,      function(o) return type(o.start) == "function" end),
        chk("StatsManager",          StatsManager,          function(o) return type(o.data) == "table" end),
        chk("AFKManager",            AFKManager,            function(o) return type(o.update) == "function" end),
        chk("ReportManager",         ReportManager,         function(o) return type(o.reports) == "table" end),
        chk("ReportCatchManager",    ReportCatchManager,    function(o) return type(o.templates) == "table" end),
        chk("PlayerManager",         PlayerManager,         function(o) return type(o.cache) == "table" end),
        chk("SpectateQuickPanel",    SpectateQuickPanel,    function(o) return type(o.render) == "function" end),
        chk("AdminSession",          AdminSession,          function(o) return type(o.data) == "table" end),
        chk("AdminSelection",        AdminSelection,        nil),
        chk("NearbyPlayerScanner",   NearbyPlayerScanner,   function(o) return type(o.update) == "function" end),
        chk("CombatStats",           CombatStats,           function(o) return type(o.data) == "table" end),
        chk("AutoAlertSystem",       AutoAlertSystem,       function(o) return type(o.alerts) == "table" end),
        chk("ChatLogManager",        ChatLogManager,        function(o) return type(o.logs) == "table" end),
        chk("KillListManager",       KillListManager,       function(o) return type(o.kills) == "table" end),
        chk("TeleportManager",       TeleportManager,       function(o) return type(o.locations) == "table" end),
        chk("ServerManager",         ServerManager,         function(o) return o.serverTime ~= nil end),
        chk("SecurityManager",       SecurityManager,       function(o) return type(o.blacklist) == "table" end),
        chk("TekshiruvManager",      TekshiruvManager,      function(o) return type(o.update) == "function" end),
        chk("AdminRelayManager",     AdminRelayManager,     function(o) return type(o.queue) == "table" end),
        chk("FuraKillManager",       FuraKillManager,       function(o) return type(o.kills) == "table" end),
        chk("GossOpgMonitorManager", GossOpgMonitorManager, function(o) return type(o.kills) == "table" end),
        chk("AnalyticsManager",      AnalyticsManager,      nil),
        chk("AdminCheckerManager",   AdminCheckerManager,   function(o) return type(o.update) == "function" end),
        chk("AdminPoManager",        AdminPoManager,        function(o) return type(o.update) == "function" end),
        chk("MainUI",                MainUI,                function(o) return type(o.window) == "table" end),
        chk("GtaVPanel",             GtaVPanel,             function(o) return type(o.render) == "function" end),
        chk("TargetCircleOverlay",   TargetCircleOverlay,   nil),
        chk("TeleportClickManager",  TeleportClickManager,  function(o) return type(o.update) == "function" end),
        chk("AdminSecurityLog",      AdminSecurityLog,      nil),
    }
end

function ToolsStatusManager.printToChat()
    local modules = ToolsStatusManager.getModules()
    local total, okCount, failList = #modules, 0, {}
    for _, m in ipairs(modules) do
        if m.ok then okCount = okCount + 1
        else table.insert(failList, m.name) end
    end

    -- Helper: chat ga chiqar + ChatLogManager ga yoz
    local function emit(text, color)
        sampAddChatMessage(text, color or -1)
        if ChatLogManager and type(ChatLogManager.captureServerMessage) == "function" then
            local clean = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
            if clean ~= "" then pcall(ChatLogManager.captureServerMessage, clean) end
        end
    end

    -- Sarlavha
    emit(string.format(
        "{88CCFF}╔══ [GMEA Status] ══ Tools v%s ══╗",
        tostring(CONFIG and CONFIG.VERSION or "?")
    ), -1)

    -- Modullar soni
    local allOk = #failList == 0
    emit(string.format(
        "{88CCFF}║{FFFFFF} Modullar: {%s}%d/%d OK",
        allOk and "33FF66" or "FF5555", okCount, total
    ), -1)

    -- Muvaffaqiyatsiz modullar
    if #failList > 0 then
        emit(string.format(
            "{88CCFF}║{FF5555} Xato: %s",
            table.concat(failList, ", ")
        ), -1)
    else
        emit("{88CCFF}║{33FF66} Barcha modullar yashil ✓", -1)
    end

    -- Log fayli
    if LogManager and LogManager.filePath then
        emit(string.format(
            "{88CCFF}║{AAAAAA} Log: %s", tostring(LogManager.filePath)
        ), -1)
    end

    -- Rol va Approval holati
    local role     = (RoleManager and RoleManager.getPrimaryRole and RoleManager.getPrimaryRole()) or "?"
    local approval = (ApprovalGuard and ApprovalGuard.statusLabel and ApprovalGuard.statusLabel()) or "?"
    emit(string.format(
        "{88CCFF}║{FFFFFF} Rol: {FFCC44}%s{FFFFFF}  |  Approval: {FFCC44}%s",
        tostring(role), tostring(approval)
    ), -1)

    -- Report va log soni
    local rCount = (ReportManager and type(ReportManager.reports) == "table" and #ReportManager.reports) or 0
    local lCount = (LogManager and type(LogManager.logs) == "table" and #LogManager.logs) or 0
    emit(string.format(
        "{88CCFF}║{FFFFFF} Reportlar: {FFCC44}%d{FFFFFF}  |  Log yozuvlar: {FFCC44}%d",
        rCount, lCount
    ), -1)

    -- Monitor holatlari
    local furaOn = FuraKillManager and FuraKillManager.enabled
    local gossOn = GossOpgMonitorManager and GossOpgMonitorManager.enabled
    emit(string.format(
        "{88CCFF}║{FFFFFF} Fura: {%s}%s{FFFFFF}  |  Goss OPG: {%s}%s",
        furaOn and "33FF66" or "AAAAAA", furaOn and "ON" or "OFF",
        gossOn and "33FF66" or "AAAAAA", gossOn and "ON" or "OFF"
    ), -1)

    emit("{88CCFF}╚═══════════════════════════╝", -1)

    if LogManager and LogManager.system then
        LogManager.system("/tools status called")
    end
end

BOOT_LOGGER.write("ToolsStatusManager loaded")
end

BOOT_LOGGER.write("Inlining module: core/event_bus.lua")
do
-- ============================================
-- COMMAND HANDLERS
-- ============================================
function processCommand(cmd)
    cmd = tostring(cmd or "")
    if cmd == "" then
        return true
    end

    local function canUseTool()
        if ApprovalGuard and ApprovalGuard.canExecute then
            if not ApprovalGuard.canExecute() then
                if ApprovalGuard.notifyIfPending then
                    ApprovalGuard.notifyIfPending()
                end
                return false
            end
        end
        return true
    end

    local args = {}
    for arg in cmd:gmatch("%S+") do
        table.insert(args, arg)
    end

    if not args[1] then return true end
    local command = args[1]:gsub("^/", ""):lower()

    if command == "amenu" then
        sampAddChatMessage("[GMEA] /amenu disabled. Press M to open admin panel.", -1)
        return false
    end

    -- /tools status  — barcha modullar holati
    -- /tools help    — buyruqlar ro'yxati
    if command == "tools" then
        local sub = tostring(args[2] or ""):lower()
        if sub == "status" or sub == "stat" or sub == "s" then
            if ToolsStatusManager and ToolsStatusManager.printToChat then
                ToolsStatusManager.printToChat()
            else
                sampAddChatMessage("[GMEA] ToolsStatusManager yuklanmagan.", 0xFF5555)
            end
            return false
        end
        local helpLines = {
            "[GMEA Tools] Buyruqlar:",
            "  /tools status  — barcha modullar holati",
            "  /rld           — scriptni qayta yuklash",
            "  /rec [soniya]  — reconnect",
        }
        for _, line in ipairs(helpLines) do
            sampAddChatMessage(line, -1)
            if ChatLogManager and type(ChatLogManager.captureServerMessage) == "function" then
                pcall(ChatLogManager.captureServerMessage, line)
            end
        end
        return false
    end

    if command == "rld" or command == "rdl" then
        if not canUseTool() then
            return false
        end
        SpectateQuickPanel.saveUiToDisk()
        if AutoPunishmentManager and AutoPunishmentManager.flushUiSave then
            AutoPunishmentManager.flushUiSave(true)
        end
        if FwPunishmentManager and FwPunishmentManager.flushUiSave then
            FwPunishmentManager.flushUiSave(true)
        end
        if StatsManager and StatsManager.save then
            StatsManager.save()
        end
        if RuntimeGuard and RuntimeGuard.requestTerminate then
            RuntimeGuard.requestTerminate("processCommand", "reload_requested", command)
        end
        SCRIPT_RELOAD_REQUESTED = true
        sampAddChatMessage("[GMEA] Reload requested: script qayta yuklanmoqda...", 0x33FF66)
        return false
    end

    if command == "rec" then
        if not canUseTool() then
            return false
        end
        local delay = tonumber(args[2]) or 5
        local okRec, message = ReconnectManager.start(delay)
        sampAddChatMessage("[GMEA] " .. tostring(message or ""), okRec and 0x33FF66 or 0xFF6666)
        return false
    end

    if command == "farm" then
        if not canUseTool() then
            return false
        end
        if FarmAnswerTool and FarmAnswerTool.openWindow then
            FarmAnswerTool.openWindow(args[2])
        end
        return false
    end

    if command == "time" then
        if not canUseTool() then
            return false
        end
        local opened = TimeQuitTool and TimeQuitTool.toggleWindow and TimeQuitTool.toggleWindow()
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(
                string.format("[GMEA] Time Quit %s", opened and "ochildi" or "yopildi"),
                opened and 0x33FF66 or 0xFF9933
            )
        end
        return false
    end

    if command == "admins" then
        if not canUseTool() then
            return false
        end
        return true
    end

    if command == "rep" then
        if not canUseTool() then
            return false
        end
        local opened = RepQuickReplyManager and RepQuickReplyManager.toggleWindow and
                       RepQuickReplyManager.toggleWindow()
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[GMEA] REP auto paneli: %s", opened and "ochildi" or "yopildi"), 0x33CCFF)
        end
        return false
    end

    if command == "fw" then
        if not canUseTool() then
            return false
        end
        local enabled = FwPunishmentManager.toggle()
        if FwReturnTracker and type(FwReturnTracker.clear) == "function" then
            FwReturnTracker.clear()
        end
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[FW] %s", enabled and "FW jazolar yoqildi." or "FW jazolar o'chirildi."), enabled and 0x33FF66 or 0xFFAA66)
        end
        return false
    end

    if command == "fura" then
        if not canUseTool() then
            return false
        end
        local enabled = FuraPunishmentManager.toggle()
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[FURA] %s", enabled and "FURA jazolar yoqildi." or "FURA jazolar o'chirildi."), enabled and 0x33FF66 or 0xFFAA66)
        end
        return false
    end

    if command == "bw" then
        if not canUseTool() then
            return false
        end
        local enabled = BwPunishmentManager.toggle()
        if type(sampAddChatMessage) == "function" then
            sampAddChatMessage(string.format("[BW] %s", enabled and "BW jazolar yoqildi." or "BW jazolar o'chirildi."), enabled and 0x33FF66 or 0xFFAA66)
        end
        return false
    end

    -- /testfam ID  — FamilyTracker ni jazo bermay test qilish
    -- Misol: /testfam 42
    if command == "testfam" then
        local targetId = tonumber(args[2])
        if not targetId then
            sampAddChatMessage("[FamilyTracker] Ishlatish: /testfam <ID>  (masalan: /testfam 42)", 0xFFAA00)
            return false
        end
        -- SP paneldagi nick yoki bo'sh string
        local nick = ""
        if SpectateQuickPanel and SpectateQuickPanel.active and SpectateQuickPanel.targetId then
            nick = tostring(SpectateQuickPanel.targetNick or "")
        end
        if nick == "" then
            -- Agar SP da bo'lmasa — SAMP'dan nickname olishga urinish
            if type(sampGetPlayerNickname) == "function" then
                local okN, n = pcall(sampGetPlayerNickname, targetId)
                if okN and type(n) == "string" and n ~= "" then
                    nick = n
                end
            end
        end
        if nick == "" then
            nick = "TestPlayer_" .. targetId
        end
        sampAddChatMessage(string.format("[FamilyTracker] Test: ID=%d, Nick=%s — /stats yuborilmoqda...", targetId, nick), 0x33DDFF)
        if FamilyTracker and FamilyTracker.triggerStatsRequest then
            FamilyTracker.triggerStatsRequest(targetId, nick)
        end
        return false
    end

    -- /fam ID — IDni statsga yuborib semyasini ini'ga qo'shish (faqat /fw yoniqda)
    if command == "fam" then
        if not canUseTool() then return false end
        if not (FwPunishmentManager and FwPunishmentManager.enabled) then
            sampAddChatMessage("[FAM] Avval /fw yoqing!", 0xFF6666)
            return false
        end
        local targetId = tonumber(args[2])
        if not targetId then
            sampAddChatMessage("[FAM] Ishlatish: /fam <ID>  (masalan: /fam 42)", 0xFFAA00)
            return false
        end
        local nick = ""
        if type(sampIsPlayerConnected) == "function" then
            local okConn, conn = pcall(sampIsPlayerConnected, targetId)
            if okConn and conn and type(sampGetPlayerNickname) == "function" then
                local okN, n = pcall(sampGetPlayerNickname, targetId)
                if okN and type(n) == "string" and n ~= "" then nick = n end
            end
        end
        if nick == "" then nick = "Player_" .. targetId end
        sampAddChatMessage(string.format("[FAM] ID=%d (%s) — /stats so'ralmoqda...", targetId, nick), 0x33DDFF)
        if FamilyTracker and FamilyTracker.triggerStatsRequest then
            FamilyTracker.triggerStatsRequest(targetId, nick)
        end
        return false
    end

    -- /id Nick — har doim serverga o'tadi. Agar /fw yoniq bo'lsa, lokal qidiruv
    --           va FamilyTracker ham qo'shimcha ravishda ishlaydi (server javobini bekor qilmaydi).
    if command == "id" then
        -- /fw o'chiq bo'lsa — to'g'ridan-to'g'ri serverga
        if not (FwPunishmentManager and FwPunishmentManager.enabled) then
            return -- pass-through (nil = serverga ketadi)
        end
        if not canUseTool() then
            return -- huquq yo'q: lokal ish qilmaymiz, lekin serverga o'tkazib yuboramiz
        end

        local searchNick = tostring(args[2] or ""):lower()
        if searchNick == "" then
            -- argument yo'q: server o'zi xato qaytaradi
            return
        end
        -- Serverda barcha o'yinchilar orasida qidirish (lokal)
        local foundId, foundNick = nil, nil
        if type(sampGetMaxPlayerId) == "function" and type(sampIsPlayerConnected) == "function" then
            local okMax, maxId = pcall(sampGetMaxPlayerId, false)
            maxId = okMax and tonumber(maxId) or 300
            for i = 0, maxId do
                local okConn, conn = pcall(sampIsPlayerConnected, i)
                if okConn and conn and type(sampGetPlayerNickname) == "function" then
                    local okN, n = pcall(sampGetPlayerNickname, i)
                    if okN and type(n) == "string" then
                        if n:lower() == searchNick or n:lower():find(searchNick, 1, true) then
                            foundId   = i
                            foundNick = n
                            break
                        end
                    end
                end
            end
        end
        if foundId then
            sampAddChatMessage(string.format("[ID] %s = ID: %d | Semya aniqlanmoqda...", foundNick, foundId), 0x33FF66)
            if FamilyTracker and FamilyTracker.triggerStatsRequest then
                FamilyTracker.triggerStatsRequest(foundId, foundNick)
            end
        end
        -- Topilmasa ham, serverga o'tkazamiz — server o'z javobini beradi.
        return -- pass-through
    end

    if command == "netdiag" then
        local seconds = tonumber(args[2]) or 60
        if RemoteGuard and RemoteGuard.enableDiagnostics then
            RemoteGuard.enableDiagnostics(seconds)
            sampAddChatMessage(string.format("[GMEA] Network diagnostics enabled (%ds).", seconds), 0x33FF66)
        end
        return false
    end

    if command == "ans" then
        if not canUseTool() then
            return false
        end
        local answeredId = tonumber(args[2])
        if answeredId then
            if StatsManager.registerOutgoingAnswer(answeredId, cmd) then
                StatsManager.addAnswer(answeredId)
            end
            ReportCatchManager.markAnswered(answeredId)
            if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
               tonumber(ReportCatchManager.currentReport.id) == answeredId then
                ReportCatchManager.closePopup()
            end
        end
    end

    if command == "stats" then
        local statsTargetId = tonumber(args[2]) or 0
        if AdminCheckerManager and type(AdminCheckerManager.consumeOutgoingAutoStats) == "function" then
            local isAutoStats = AdminCheckerManager.consumeOutgoingAutoStats(statsTargetId)
            if not isAutoStats and type(AdminCheckerManager.deferManualStats) == "function" then
                AdminCheckerManager.deferManualStats(3.5)
            end
        end
    end

    if AdminRelayManager and AdminRelayManager.parseCommandParts and
       AdminRelayManager.extractTargetId and AdminRelayManager.updatePunishmentState then
        local outgoingInfo = AdminRelayManager.parseCommandParts(cmd)
        if outgoingInfo and AdminRelayManager.playerIdCommands and AdminRelayManager.playerIdCommands[outgoingInfo.name] then
            local outgoingTargetId = AdminRelayManager.extractTargetId(outgoingInfo)
            AdminRelayManager.updatePunishmentState(outgoingInfo.name, outgoingTargetId)
        end
    end

    if command == "sp" or command == "spec" then
        if not canUseTool() then
            return true
        end
    end

    SpectateQuickPanel.handleCommand(command, args)

    SecurityManager.logCommand(0, cmd)

    return true
end

local function safeEventDispatch(tag, owner, methodName, ...)
    -- crash fix: one failing subsystem should not stop the rest of the event chain.
    local fn = owner and owner[methodName]
    if type(fn) ~= "function" then
        return nil, false
    end
    local ok, result = RuntimeGuard.call(tag, fn, ...)
    if not ok then
        return nil, true
    end
    return result, true
end

-- ============================================
-- SAMPEV EVENTS
-- ============================================
function sampev.onSendCommand(cmd)
    -- fix: SAMP.Lua sampev qoidasi: `return false` = blok, `return {cmd}` = modifikatsiya,
    -- `return` (nil/hech narsa) = original passga ruxsat. Avval `return true` ishlatilgan edi,
    -- bu ba'zi muhitlarda komandalarni yutib yuborardi. Endi faqat aniq false bo'lganda blok qilamiz.
    local ok, result = RuntimeGuard.call("sampev.onSendCommand", processCommand, cmd)
    if not ok then
        return -- xato: original komandani o'tkazib yuboramiz
    end
    if result == false then
        return false -- script ataylab blok qilmoqchi
    end
    -- aks holda hech narsa qaytarmasdan original komanda serverga boradi
    return
end

function sampev.onServerMessage(color, text)
    local ok, result = RuntimeGuard.call("sampev.onServerMessage", function()
        local source = tostring(text or "")
        local rewrittenText = ChatLogManager and type(ChatLogManager.rewriteServerMessageWithIds) == "function" and
            ChatLogManager.rewriteServerMessageWithIds(source) or source
        local furaPriorityActive = FuraKillManager and
                                   type(FuraKillManager.isPriorityModeActive) == "function" and
                                   FuraKillManager.isPriorityModeActive() == true

        safeEventDispatch("ReportCatchManager.captureAdminFromServerMessage", ReportCatchManager, "captureAdminFromServerMessage", source)
        safeEventDispatch("TeleportClickManager.captureVehicleIdFromServerMessage", TeleportClickManager, "captureVehicleIdFromServerMessage", source)
        safeEventDispatch("ReportCatchManager.processGnewsAutoAccept", ReportCatchManager, "processGnewsAutoAccept", source)

        local answerMatch = source:match("Answer #(%d+)")
        if answerMatch then
            local id = tonumber(answerMatch)
            if not StatsManager.consumeOutgoingAnswer(id) then
                StatsManager.addAnswer(id)
            end
            LogManager.admin(string.format("Answer detected: #%d", id))
            ReportCatchManager.markAnswered(id)
            if ReportCatchManager.popupOpen and ReportCatchManager.currentReport and
               tonumber(ReportCatchManager.currentReport.id) == id then
                ReportCatchManager.closePopup()
            end
        end

        safeEventDispatch("FuraKillManager.processStatsMessage", FuraKillManager, "processStatsMessage", source)
        if not furaPriorityActive then
            safeEventDispatch("GossOpgMonitorManager.processStatsMessage", GossOpgMonitorManager, "processStatsMessage", source)
        end

        safeEventDispatch("AdminRelayManager.processIncomingMessage", AdminRelayManager, "processIncomingMessage", source)
        safeEventDispatch("AdminRelayManager.processCommandFeedbackMessage", AdminRelayManager, "processCommandFeedbackMessage", source)
        local consumedByAdminCheckerMessage = safeEventDispatch("AdminCheckerManager.processServerMessage", AdminCheckerManager, "processServerMessage", source)
        safeEventDispatch("TekshiruvManager.processServerMessage", TekshiruvManager, "processServerMessage", source)
        local consumedByAdminPoMessage = safeEventDispatch("AdminPoManager.processServerMessage", AdminPoManager, "processServerMessage", source)
        safeEventDispatch("PlayerLogManager.captureServerMessage", PlayerLogManager, "captureServerMessage", source)
        safeEventDispatch("ChatLogManager.captureServerMessage", ChatLogManager, "captureServerMessage", source)

        -- FW jazo xabarini aniqlash: faqat /fw yoniq bo'lganda
        -- Format: "AdminNik administratori VictimNik o'yinchisini X daqiqaga to'xtatib qo'ydi. Sababi: 1.14 fw"
        if FwPunishmentManager and FwPunishmentManager.enabled then
        do
            local cleanSrc = source:gsub("{%x%x%x%x%x%x}", "")

            -- Victimni aniqlaymiz
            local victimNick = cleanSrc:match("administratori%s+(%S+)%s+o'yinchisini")
                            or cleanSrc:match("administrator%s+(%S+)%s+o'yinchisini")

            -- Sababi qismini ajratib, oxiri "fw" bilan tugashini tekshiramiz
            local sababiPart = cleanSrc:lower():match("sababi:%s*(.-)%s*$")
            local isFw = false
            if sababiPart then
                -- Ohirgi so'z "fw" bo'lishi kerak
                local lastWord = sababiPart:match("(%S+)%s*$")
                isFw = (lastWord == "fw")
            end

            if victimNick and isFw then
                -- Dedup: agar bu nik allaqachon pending'da bo'lsa — qayta ishlamaymiz
                local alreadyPending = false
                if FamilyTracker and FamilyTracker.pending then
                    for _, entry in pairs(FamilyTracker.pending) do
                        if tostring(entry.nick or ""):lower() == victimNick:lower() then
                            alreadyPending = true
                            break
                        end
                    end
                end

                if not alreadyPending then
                    -- Serverda o'sha nikni topib ID aniqlaymiz
                    local foundId = nil
                    if type(sampGetMaxPlayerId) == "function" and type(sampIsPlayerConnected) == "function" then
                        local okMax, maxId = pcall(sampGetMaxPlayerId, false)
                        maxId = okMax and tonumber(maxId) or 300
                        for i = 0, maxId do
                            local okConn, conn = pcall(sampIsPlayerConnected, i)
                            if okConn and conn and type(sampGetPlayerNickname) == "function" then
                                local okN, n = pcall(sampGetPlayerNickname, i)
                                if okN and type(n) == "string" and n == victimNick then
                                    foundId = i
                                    break
                                end
                            end
                        end
                    end
                    if foundId and FamilyTracker and FamilyTracker.triggerStatsRequest then
                        pcall(FamilyTracker.triggerStatsRequest, foundId, victimNick)
                    end
                end
            end
        end
        end -- if FwPunishmentManager.enabled

        if consumedByAdminCheckerMessage == false then
            return false
        end

        if consumedByAdminPoMessage == false then
            return false
        end

        local consumedByPunishmentCheck = safeEventDispatch(
            "ReportCatchManager.processPunishmentInfoMessage",
            ReportCatchManager,
            "processPunishmentInfoMessage",
            source
        )
        if consumedByPunishmentCheck then
            return false
        end

        safeEventDispatch("ReportCatchManager.processReport", ReportCatchManager, "processReport", source)
        if tostring(rewrittenText or "") ~= tostring(source or "") then
            return { color, rewrittenText }
        end
        return true
    end)

    if not ok then
        return true
    end
    if result == nil then
        return true
    end
    return result
end

function sampev.onSetTimeEx(hour, minute)
