function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
    local eventResult = nil
    RuntimeGuard.call("sampev.onShowDialog", function()
        local furaPriorityActive = FuraKillManager and
                                   type(FuraKillManager.isPriorityModeActive) == "function" and
                                   FuraKillManager.isPriorityModeActive() == true
        safeEventDispatch("FuraKillManager.processStatsDialog", FuraKillManager, "processStatsDialog", dialogId, style, title, button1, button2, text)
        if not furaPriorityActive then
            safeEventDispatch("GossOpgMonitorManager.processStatsDialog", GossOpgMonitorManager, "processStatsDialog", dialogId, style, title, button1, button2, text)
        end
        safeEventDispatch("ReportCatchManager.processPunishmentInfoDialog", ReportCatchManager, "processPunishmentInfoDialog", dialogId, style, title, button1, button2, text)
        local consumedByGnewsAutoDialog = safeEventDispatch("ReportCatchManager.processGnewsAutoAcceptDialog", ReportCatchManager, "processGnewsAutoAcceptDialog", dialogId, style, title, button1, button2, text)
        safeEventDispatch("NavigatorManager.captureGpsDialog", NavigatorManager, "captureGpsDialog", dialogId, style, title, button1, button2, text)
        local consumedByAdminCheckerDialog = safeEventDispatch("AdminCheckerManager.processStatsDialog", AdminCheckerManager, "processStatsDialog", dialogId, style, title, button1, button2, text)
        -- FamilyTracker: /stats dialog'dan semya nomini parse qilish
        if FamilyTracker and FamilyTracker.processStatsDialog then
            pcall(FamilyTracker.processStatsDialog, dialogId, style, title, button1, button2, text)
        end
        local consumedByAdminPoDialog = safeEventDispatch("AdminPoManager.processDialog", AdminPoManager, "processDialog", dialogId, style, title, button1, button2, text)
        if consumedByGnewsAutoDialog == false then
            eventResult = false
        elseif consumedByAdminCheckerDialog == false then
            eventResult = false
        elseif consumedByAdminPoDialog ~= nil then
            eventResult = consumedByAdminPoDialog
        end
        safeEventDispatch("PlayerLogManager.captureDialog", PlayerLogManager, "captureDialog", text)
    end)
    if eventResult ~= nil then
        return eventResult
    end
end

