function sampev.onSendChat(msg)
    -- fix: bir xil muammo onSendChat'da ham bo'lgan. Faqat aniq false bo'lganda blok qilamiz.
    local ok, result = RuntimeGuard.call("sampev.onSendChat", function()
        local source = tostring(msg or "")
        if source:sub(1, 1) == "/" then
            return processCommand(source)
        end

        local filtered, word = false, nil
        if SecurityManager and type(SecurityManager.checkChatFilter) == "function" then
            local okFilter, resultFiltered, resultWord = RuntimeGuard.call("SecurityManager.checkChatFilter", SecurityManager.checkChatFilter, source)
            if okFilter then
                filtered, word = resultFiltered, resultWord
            end
        end
        if filtered then
            LogManager.security(string.format("Filtered word detected: %s", word))
        end

        if SettingsManager and SettingsManager.get and SettingsManager.get("autoNChatEnabled") == true then
            local plain = UtilityManager.trim(source)
            if plain ~= "" and type(sampSendChat) == "function" then
                -- safety fix: plain chat is redirected to /n, but slash commands keep their original behavior.
                local okSend = pcall(sampSendChat, "/n " .. plain)
                if okSend then
                    return false
                end
            end
        end

        -- normal chat: hech narsa qaytarmaslik (sampev qoidasi: pass-through)
        return
    end)

    if not ok then
        return -- xato: original chat/komandani serverga o'tkazamiz
    end
    if result == false then
        return false -- script ataylab blok qilmoqchi
    end
    if type(result) == "table" then
        return result -- modifikatsiya (kelajakda kerak bo'lsa)
    end
    -- aks holda pass-through
    return
end

local writeStartupTrace

local function noteTerminate(source, reason, context)
    if RuntimeGuard and RuntimeGuard.requestTerminate then
        RuntimeGuard.requestTerminate(source, reason, context)
    end
end

local function performRequestedReload()
    SCRIPT_RELOAD_REQUESTED = false

    local reloadErr = nil
    if type(thisScript) == "function" then
        local okScript, scriptObj = pcall(thisScript)
        if okScript and scriptObj and scriptObj.reload then
            local okReload, errReload = pcall(function()
                scriptObj:reload()
            end)
            if okReload then
                return true
            end
            reloadErr = errReload
        else
            reloadErr = okScript and "reload_method_unavailable" or scriptObj
        end
    else
        reloadErr = "thisScript_unavailable"
    end

    if LogManager and LogManager.system then
        LogManager.system("[RELOAD] direct reload failed, falling back to reconnect: " .. tostring(reloadErr or "unknown"))
    end

    if ReconnectManager and ReconnectManager.start then
        local okRec, reconnectMessage = ReconnectManager.start(2)
        if okRec then
            if type(sampAddChatMessage) == "function" then
                sampAddChatMessage("[GMEA] Reload fallback engaged: reconnecting to apply server command.", 0xFFB400)
            end
            return true
        end
        reloadErr = string.format("%s | reconnect_fallback_failed:%s", tostring(reloadErr or "reload_failed"), tostring(reconnectMessage or "unknown"))
    end

    if type(sampAddChatMessage) == "function" then
        sampAddChatMessage("[GMEA] Reload failed: " .. tostring(reloadErr or "unknown"), 0xFF6666)
    end
    return false
end

function onScriptTerminate(script, quitGame)
    RuntimeGuard.call("onScriptTerminate", function()
        if type(thisScript) == "function" and script and script ~= thisScript() then
            return
        end

        writeStartupTrace(string.format("Script terminating (quitGame=%s)", tostring(quitGame)))
        local terminateMeta = RuntimeGuard and RuntimeGuard.getTerminateMeta and RuntimeGuard.getTerminateMeta() or {}
        local terminateSource = tostring(terminateMeta.source or "")
        local terminateReason = tostring(terminateMeta.reason or "")
        local terminateContext = tostring(terminateMeta.context or "")
        if terminateSource == "" then
            terminateSource = "moonloader_external_or_unknown"
        end
        if terminateReason == "" then
            terminateReason = "not_recorded"
        end
        writeStartupTrace(string.format("TERMINATE_SOURCE=%s", terminateSource))
        writeStartupTrace(string.format("TERMINATE_REASON=%s", terminateReason))
        if terminateContext ~= "" then
            writeStartupTrace(string.format("TERMINATE_CONTEXT=%s", terminateContext))
        end

        if SpectateQuickPanel and SpectateQuickPanel.saveUiToDisk then
            SpectateQuickPanel.saveUiToDisk()
        end

        if AdminModesManager and AdminModesManager.restore then
            AdminModesManager.restore()
        end

        if StatsManager and StatsManager.save then
            StatsManager.save()
        end
        if RuntimeGuard and RuntimeGuard.clearTerminateMeta then
            RuntimeGuard.clearTerminateMeta()
        end
    end)
end

-- ============================================
-- GLOBAL VARIABLES FOR KEY HANDLING
-- ============================================
local M_KEY_LAST_STATE = false
local KERAKLI_MENU_KEY_LAST_STATE = false

writeStartupTrace = function(message, isError)
    local text = tostring(message or "")

    if BOOT_LOGGER and BOOT_LOGGER.write and not (LogManager and LogManager.fileReady) then
        BOOT_LOGGER.write(text)
    end

    if LogManager then
        if isError and LogManager.error then
            LogManager.error(text)
            return
        end
        if LogManager.system then
            LogManager.system(text)
            return
        end
    end

    if type(print) == "function" then
        print("[STARTUP] " .. text)
    end
end

-- ============================================
-- MAIN THREAD
-- ============================================
function main()
    -- Wait for SAMP to load
    while not isSampLoaded() do
        wait(100)
    end

    while not isSampAvailable() do
        wait(100)
    end

    writeStartupTrace("SAMP became available")

    -- FIX #6: sampAddChatMessage ni wrap qilib, client-side xabarlarni ham ChatLogManager ga yuborish
    -- /tools help, /tools status, [GMEA Tools] va barcha sampAddChatMessage chiqishlari shu orqali log qilinadi
    -- _G orqali o'rnatiladi — MoonLoader da global scope to'g'ri ishlashi uchun
    do
        local _origSampAddChatMessage = _G.sampAddChatMessage or sampAddChatMessage
        if type(_origSampAddChatMessage) == "function" then
            _G.sampAddChatMessage = function(text, color)
                local ok, result = pcall(_origSampAddChatMessage, text, color)
                if ChatLogManager and type(ChatLogManager.captureServerMessage) == "function" then
                    local cleanText = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
                    cleanText = UtilityManager and UtilityManager.trim and UtilityManager.trim(cleanText) or cleanText
                    if cleanText ~= "" then
                        pcall(ChatLogManager.captureServerMessage, cleanText)
                    end
                end
                return ok and result or nil
            end
        end
    end

    if RemoteGuard and RemoteGuard.start then
        writeStartupTrace("RemoteGuard.start begin")
        RemoteGuard.start()
        writeStartupTrace("RemoteGuard.start ok")
    end

    if RemoteGuard and (RemoteGuard.isStartupReady or RemoteGuard.canOperate) then
        local gateState = RemoteGuard.describeGateState and RemoteGuard.describeGateState() or "unavailable"
        writeStartupTrace("Waiting for remote access state")
        writeStartupTrace("Startup gate before wait: " .. tostring(gateState))
        while not ((RemoteGuard.isStartupReady and RemoteGuard.isStartupReady()) or (RemoteGuard.canOperate and RemoteGuard.canOperate())) do
            wait(0)
            if RemoteGuard and RemoteGuard.update then
                RuntimeGuard.call("RemoteGuard.update", RemoteGuard.update)
            end
            if ProtectionGuard and ProtectionGuard.update then
                RuntimeGuard.call("ProtectionGuard.update", ProtectionGuard.update)
            end
            if HiddenChecks and HiddenChecks.update then
                RuntimeGuard.call("HiddenChecks.update", HiddenChecks.update)
            end
            if SCRIPT_RELOAD_REQUESTED then
                if performRequestedReload() then
                    return
                end
            end
            if RemoteGuard and RemoteGuard.isBlocked and RemoteGuard.isBlocked() then
                local blockedState = RemoteGuard.describeGateState and RemoteGuard.describeGateState() or "unavailable"
                local blockedReason = RemoteGuard.getLastBlockReason and RemoteGuard.getLastBlockReason() or "unknown"
                writeStartupTrace("Startup gate state before decision: " .. tostring(blockedState), true)
                writeStartupTrace("Remote access blocked before startup completed: " .. tostring(blockedReason), true)
                noteTerminate("startup_gate", "remote_access_blocked", blockedReason)
                return
            end
        end
        local passedState = RemoteGuard.describeGateState and RemoteGuard.describeGateState() or "unavailable"
        writeStartupTrace("Remote access gate passed: " .. tostring(passedState))
    end

    -- Initialize all managers with guarded startup.
    local initSteps = {
        { name = "UtilityManager.initialize", fn = UtilityManager.initialize },
        { name = "LogManager.initialize", fn = LogManager.initialize },
        { name = "SettingsManager.initialize", fn = SettingsManager.initialize },
        { name = "TargetCircleOverlay.initialize", fn = TargetCircleOverlay.initialize },
        { name = "KillListManager.initialize", fn = KillListManager.initialize },
        { name = "ChatLogManager.initialize", fn = ChatLogManager.initialize },
        { name = "StatsManager.initialize", fn = StatsManager.initialize },
        { name = "AFKManager.initialize", fn = AFKManager.initialize },
        { name = "ReportManager.initialize", fn = ReportManager.initialize },
        { name = "ReportCatchManager.initialize", fn = ReportCatchManager.initialize },
        { name = "AdminRelayManager.initialize", fn = AdminRelayManager.initialize },
        { name = "PlayerManager.initialize", fn = PlayerManager.initialize },
        { name = "TeleportManager.initialize", fn = TeleportManager.initialize },
        { name = "ServerManager.initialize", fn = ServerManager.initialize },
        { name = "SecurityManager.initialize", fn = SecurityManager.initialize },
        { name = "TekshiruvManager.initialize", fn = TekshiruvManager.initialize },
        { name = "AdminCheckerManager.initialize", fn = AdminCheckerManager.initialize },
        { name = "AdminPoManager.initialize", fn = AdminPoManager.initialize },
        { name = "AnalyticsManager.initialize", fn = AnalyticsManager.initialize },
        { name = "FuraKillManager.initialize", fn = FuraKillManager.initialize },
        { name = "GossOpgMonitorManager.initialize", fn = GossOpgMonitorManager.initialize },
        { name = "GtaVPanel.initialize", fn = GtaVPanel.initialize },
        { name = "AutoPunishmentManager.initialize", fn = AutoPunishmentManager.initialize },
        { name = "FwPunishmentManager.initialize", fn = FwPunishmentManager.initialize },
        { name = "FuraPunishmentManager.initialize", fn = FuraPunishmentManager.initialize },
        { name = "BwPunishmentManager.initialize", fn = BwPunishmentManager.initialize },
        { name = "FamilyTracker.initialize", fn = FamilyTracker.initialize },
        { name = "FwReturnTracker.initialize", fn = FwReturnTracker.initialize },
        { name = "MpTeleportCloseTimer.initialize", fn = MpTeleportCloseTimer.initialize },
        { name = "TimeQuitTool.initialize", fn = TimeQuitTool.initialize },
        { name = "MainUI.initialize", fn = MainUI.initialize }
    }

    for _, step in ipairs(initSteps) do
        writeStartupTrace("Init begin: " .. step.name)
        local okInit = RuntimeGuard.call("init." .. step.name, step.fn)
        if not okInit then
            writeStartupTrace("Init failed: " .. step.name, true)
            if type(sampAddChatMessage) == "function" then
                sampAddChatMessage("[GMEA] Startup failed at " .. step.name, 0xFF6666)
            end
            noteTerminate("startup_init", "init_failed", step.name)
            return
        end
        writeStartupTrace("Init ok: " .. step.name)
    end

    if PermissionGuard and PermissionGuard.initialize then
        writeStartupTrace("Init begin: PermissionGuard.initialize")
        RuntimeGuard.call("PermissionGuard.initialize", PermissionGuard.initialize)
        writeStartupTrace("Init ok: PermissionGuard.initialize")
    end

    -- Initialize imgui process state
    imgui.Process = false
    imgui.ShowCursor = false

    -- Startup nick tekshiruvi (faqat bir marta)
    AccessControl.waitAndEnforce(10000)

    -- Print compact startup messages
    print("[GMEA] Tools ishga tushdi")
    print("[GMEA] Tools reload: /rld")
    sampAddChatMessage("[GMEA] Tools ishga tushdi", 0x00FF00)
    sampAddChatMessage("[GMEA] Tools reload: /rld", 0x00FF00)

    LogManager.system("System initialized successfully")
    writeStartupTrace("Main loop started")

    -- Main loop
    local lastSave = os.time()
    local lastAFKCheck = os.time()
    local frameCount = 0
    local deferredUpdateAtMs = {}
    local runtimeCall = RuntimeGuard.call
    local runtimeGetNowMs = RuntimeGuard and RuntimeGuard.getNowMs or nil
    local osTimeNow = os.time
    local osClockNow = os.clock
    local waitFrame = wait
    local pcallSafe = pcall
    local sampIsChatInputActiveFn = sampIsChatInputActive
    local sampIsDialogActiveFn = sampIsDialogActive
    local isKeyDownFn = isKeyDown
    local isKeyJustPressedFn = isKeyJustPressed
    local sampAddChatMessageFn = sampAddChatMessage

    local _loopGetNowMs = runtimeGetNowMs or function()
        return math.floor(osClockNow() * 1000)
    end
    local function loopNowMs()
        return _loopGetNowMs()
    end

    local function shouldRunDeferred(key, intervalMs)
        if not intervalMs or intervalMs <= 0 then
            return true
        end

        local now = loopNowMs()
        local last = deferredUpdateAtMs[key] or 0
        if last == 0 or (now - last) >= intervalMs then
            deferredUpdateAtMs[key] = now
            return true
        end
        return false
    end

    local function isFuraPriorityActive()
        return FuraKillManager and
               type(FuraKillManager.isPriorityModeActive) == "function" and
               FuraKillManager.isPriorityModeActive() == true
    end

    -- Interval variables hoisted outside loop to avoid per-frame allocation
    local reportCatchAuxIntervalMs = 0
    local adminModesIntervalMs     = 0
    local navigatorIntervalMs      = 0
    local gossIntervalMs           = 0
    local tekshiruvIntervalMs      = 0
    local adminCheckerIntervalMs   = 0
    local scannerIntervalMs        = 0
    local alertIntervalMs          = 0
    local permissionIntervalMs     = 0
    local approvalIntervalMs       = 0
    local toolCommandIntervalMs    = 0
    local chiefAdminIntervalMs     = 0

    while true do
        waitFrame(0)

        -- access_control: startup'da bir marta tekshirilgan (har 2s loop'dan chiqarildi)

        if RemoteGuard and RemoteGuard.update then
            runtimeCall("RemoteGuard.update", RemoteGuard.update)
        end
        if ProtectionGuard and ProtectionGuard.update then
            runtimeCall("ProtectionGuard.update", ProtectionGuard.update)
        end
        if HiddenChecks and HiddenChecks.update then
            runtimeCall("HiddenChecks.update", HiddenChecks.update)
        end

        if SCRIPT_RELOAD_REQUESTED then
            if performRequestedReload() then
                return
            end
        end

        if RemoteGuard and RemoteGuard.isBlocked and RemoteGuard.isBlocked() then
            local blockReason = RemoteGuard.getLastBlockReason and RemoteGuard.getLastBlockReason() or "unknown"
            noteTerminate("main_loop", "remote_blocked", blockReason)
            return
        end

        frameCount = frameCount + 1
        local chatActive = false
        local dialogActive = false
        local okChat, valueChat = pcallSafe(sampIsChatInputActiveFn)
        chatActive = okChat and valueChat == true
        local okDialog, valueDialog = pcallSafe(sampIsDialogActiveFn)
        dialogActive = okDialog and valueDialog == true

        local canRunTools = true
        local approvalGuard = ApprovalGuard
        if approvalGuard and approvalGuard.canExecute then
            canRunTools = approvalGuard.canExecute()
            if not canRunTools and approvalGuard.notifyIfPending then
                approvalGuard.notifyIfPending()
            end
        end

        local furaPriorityActive = false
        if canRunTools then
            furaPriorityActive = isFuraPriorityActive()
            if furaPriorityActive then
                reportCatchAuxIntervalMs = 350
                adminModesIntervalMs     = 120
                navigatorIntervalMs      = 120
                gossIntervalMs           = 1500
                tekshiruvIntervalMs      = 250
                adminCheckerIntervalMs   = 400
                scannerIntervalMs        = 250
                alertIntervalMs          = 250
                permissionIntervalMs     = 1500
                approvalIntervalMs       = 2500
                toolCommandIntervalMs    = 5000
                chiefAdminIntervalMs     = 5000
            else
                reportCatchAuxIntervalMs = 0
                adminModesIntervalMs     = 0
                navigatorIntervalMs      = 0
                gossIntervalMs           = 0
                tekshiruvIntervalMs      = 0
                adminCheckerIntervalMs   = 0
                scannerIntervalMs        = 0
                alertIntervalMs          = 0
                permissionIntervalMs     = 0
                approvalIntervalMs       = 0
                toolCommandIntervalMs    = 0
                chiefAdminIntervalMs     = 0
            end
            local nowTime = osTimeNow()

            -- AFK check (every second)
            if nowTime - lastAFKCheck >= 1 then
                runtimeCall("AFKManager.checkPosition", AFKManager.checkPosition)
                runtimeCall("StatsManager.updatePlaytime", StatsManager.updatePlaytime)
                lastAFKCheck = nowTime
            end

            runtimeCall("FuraKillManager.update", FuraKillManager.update)

            if shouldRunDeferred("report_pending", reportCatchAuxIntervalMs) then
                runtimeCall("ReportCatchManager.updatePendingPunishmentCheck", ReportCatchManager.updatePendingPunishmentCheck)
            end
            if shouldRunDeferred("report_keyword_tp", reportCatchAuxIntervalMs) then
                runtimeCall("ReportCatchManager.processKeywordTpQueue", ReportCatchManager.processKeywordTpQueue)
            end
            runtimeCall("ReconnectManager.update", ReconnectManager.update)
            if shouldRunDeferred("admin_modes", adminModesIntervalMs) then
                runtimeCall("AdminModesManager.update", AdminModesManager.update)
            end
            runtimeCall("CheatFunctions.updateAirbrake", CheatFunctions.updateAirbrake)
            if shouldRunDeferred("navigator", navigatorIntervalMs) then
                runtimeCall("NavigatorManager.update", NavigatorManager.update)
            end
            if shouldRunDeferred("goss_update", gossIntervalMs) then
                runtimeCall("GossOpgMonitorManager.update", GossOpgMonitorManager.update)
            end
            if shouldRunDeferred("tekshiruv_update", tekshiruvIntervalMs) then
                runtimeCall("TekshiruvManager.update", TekshiruvManager.update)
            end
            if shouldRunDeferred("admin_checker_update", adminCheckerIntervalMs) then
                runtimeCall("AdminCheckerManager.update", AdminCheckerManager.update)
            end
            if shouldRunDeferred("chat_logs_update", 900) then
                runtimeCall("ChatLogManager.update", ChatLogManager.update)
            end
            runtimeCall("AdminRelayManager.update", AdminRelayManager.update)
            if shouldRunDeferred("world_climate_lock", 1200) then
                runtimeCall("ServerManager.updateClimateLocks", ServerManager.updateClimateLocks)
            end
            if shouldRunDeferred("nearby_scanner", scannerIntervalMs) then
                runtimeCall("NearbyPlayerScanner.update", NearbyPlayerScanner.update)
            end
            runtimeCall("MpTeleportCloseTimer.update", MpTeleportCloseTimer.update)
            runtimeCall("TimeQuitTool.update", TimeQuitTool.update)
            runtimeCall("FwReturnTracker.update", FwReturnTracker.update)
            if shouldRunDeferred("auto_alert", alertIntervalMs) then
                runtimeCall("AutoAlertSystem.update", AutoAlertSystem.update)
            end
            if PermissionGuard and PermissionGuard.update and shouldRunDeferred("permission_guard", permissionIntervalMs) then
                runtimeCall("PermissionGuard.update", PermissionGuard.update)
            end
            if ApprovalManager and ApprovalManager.update and shouldRunDeferred("approval_manager", approvalIntervalMs) then
                runtimeCall("ApprovalManager.update", ApprovalManager.update)
            end
            if ToolCommandManager and ToolCommandManager.update and shouldRunDeferred("tool_commands", toolCommandIntervalMs) then
                runtimeCall("ToolCommandManager.update", ToolCommandManager.update)
            end
            if ChiefAdminManager and ChiefAdminManager.update and shouldRunDeferred("chief_admin", chiefAdminIntervalMs) then
                runtimeCall("ChiefAdminManager.update", ChiefAdminManager.update)
            end

            -- Keep reset checks without touching filesystem in this environment
            if nowTime - lastSave >= CONFIG.AUTO_SAVE_INTERVAL then
                runtimeCall("StatsManager.checkReset", StatsManager.checkReset)
                runtimeCall("StatsManager.save", StatsManager.save) -- Auto-save stats
                lastSave = nowTime
            end
        end

        -- Keep imgui active when any panel is visible
        local mainWindowOpen = MainUI.window.open == true
        local reportPopupOpen = ReportCatchManager.popupOpen == true
        local adminRelayPopupOpen = AdminRelayManager.popupOpen == true
        local spectatePanelActive = SpectateQuickPanel.active == true and SpectateQuickPanel.targetId ~= nil
        local clickTpActive = TeleportClickManager.enabled == true
        local farmWindowActive = FarmAnswerTool and FarmAnswerTool.open == true or false
        local timeQuitWindowActive = TimeQuitTool and TimeQuitTool.open == true or false
        local killOverlayPassiveOnly = KillListManager and KillListManager.isOverlayVisible and
            KillListManager.isOverlayVisible() and not (mainWindowOpen or reportPopupOpen or adminRelayPopupOpen or
                (spectatePanelActive and SpectateQuickPanel.cursorVisible) or clickTpActive or farmWindowActive)
        local adminCheckerPlacing = AdminCheckerManager and AdminCheckerManager.placementActive == true
        local uiProcessEnabled = mainWindowOpen or reportPopupOpen or adminRelayPopupOpen or
                                 (spectatePanelActive and SpectateQuickPanel.cursorVisible) or clickTpActive or farmWindowActive or
                                 timeQuitWindowActive or adminCheckerPlacing
        imgui.Process = uiProcessEnabled
        imgui.ShowCursor = uiProcessEnabled
        if killOverlayPassiveOnly then
            -- safety fix: passive Kill List overlay stays visible without leaving the cursor on.
            imgui.Process = false
            imgui.ShowCursor = false
        end

        local clickTpCanToggle = not chatActive and not dialogActive
        local clickTpCanTeleport = clickTpCanToggle and
                                  not mainWindowOpen and
                                  not reportPopupOpen and
                                  not adminRelayPopupOpen and
                                  not spectatePanelActive and
                                  not farmWindowActive and
                                  not timeQuitWindowActive
        if canRunTools then
            local clickTpIntervalMs = furaPriorityActive and 100 or 0
            if shouldRunDeferred("click_tp", clickTpIntervalMs) then
                runtimeCall("TeleportClickManager.update", TeleportClickManager.update, clickTpCanToggle, clickTpCanTeleport)
            end
        end

        local rightMouseClicked = false
        local spacePressed = false
        if canRunTools then
            if spectatePanelActive and not mainWindowOpen and not reportPopupOpen and
               not adminRelayPopupOpen and
               not chatActive and not dialogActive then
                rightMouseClicked = SpectateQuickPanel.isRightMouseClicked()
                spacePressed = SpectateQuickPanel.isSpacePressed()
            else
                SpectateQuickPanel.rightMouseLastState = false
                SpectateQuickPanel.spaceLastState = false
            end

            if spectatePanelActive and rightMouseClicked then
                SpectateQuickPanel.cursorVisible = not SpectateQuickPanel.cursorVisible
            end

            if spectatePanelActive and spacePressed then
                SpectateQuickPanel.cursorVisible = false
                SpectateQuickPanel.sendSpOff()
            end
        end

        -- KEY HANDLER - Main panel toggle with M key
        -- Use isKeyDown with manual toggle logic for reliability
        local mKeyDown = false
        local kerakliMenuCaptureActive = MainUI and MainUI.kerakliMenuKeyCapture and MainUI.kerakliMenuKeyCapture.active == true
        if type(isKeyDownFn) == "function" then
            local okKey, keyDown = pcallSafe(isKeyDownFn, vkeys.VK_M)
            mKeyDown = okKey and keyDown == true
        end

        -- Detect rising edge (key just pressed)
        if mKeyDown and not M_KEY_LAST_STATE then
            -- Check if chat is not open (don't toggle when typing)
            if not chatActive and not dialogActive and not kerakliMenuCaptureActive then
                runtimeCall("MainUI.toggle", MainUI.toggle)
            end
        end

        M_KEY_LAST_STATE = mKeyDown

        runtimeCall("MainUI.updateKerakliMenuKeyCapture", MainUI.updateKerakliMenuKeyCapture, isKeyDownFn, chatActive, dialogActive)
        kerakliMenuCaptureActive = MainUI and MainUI.kerakliMenuKeyCapture and MainUI.kerakliMenuKeyCapture.active == true

        local kerakliMenuKeyDown = false
        local kerakliMenuToggleKey = math.floor(tonumber(SettingsManager.get("kerakliMenuToggleKey")) or 0)
        if kerakliMenuToggleKey > 0 and type(isKeyDownFn) == "function" then
            local okKerakliKey, valueKerakliKey = pcallSafe(isKeyDownFn, kerakliMenuToggleKey)
            kerakliMenuKeyDown = okKerakliKey and valueKerakliKey == true
        end
        local kerakliMenuSuppress = MainUI and MainUI.kerakliMenuHotkeySuppress == true
        if kerakliMenuSuppress then
            if not kerakliMenuKeyDown and MainUI then
                MainUI.kerakliMenuHotkeySuppress = false
            end
        elseif not kerakliMenuCaptureActive and kerakliMenuKeyDown and not KERAKLI_MENU_KEY_LAST_STATE then
            if not chatActive and not dialogActive then
                runtimeCall("MainUI.toggleKerakliMenuDisabled", MainUI.toggleKerakliMenuDisabled, "hotkey")
            end
        end
        KERAKLI_MENU_KEY_LAST_STATE = kerakliMenuKeyDown

        -- Key handler - Report Catch enable/disable (N key)
        local hotkeyPressed = false
        if type(isKeyJustPressedFn) == "function" then
            local okHotkey, valueHotkey = pcallSafe(isKeyJustPressedFn, ReportCatchManager.settings.hotkey)
            hotkeyPressed = okHotkey and valueHotkey == true
        end

        if canRunTools then
            if hotkeyPressed then
                if not chatActive and not dialogActive and not kerakliMenuCaptureActive then
                    local state = ReportCatchManager.toggle()
                    sampAddChatMessageFn(string.format("[GMEA] Report Catch: %s (N)", state and "ON" or "OFF"), 0x00FF00)
                    if state then
                        runtimeCall("ReportCatchManager.tryShowNextQueuedReport", ReportCatchManager.tryShowNextQueuedReport)
                    end
                end
            end

            local quickHotkeyIntervalMs = furaPriorityActive and 120 or 0
            if not kerakliMenuCaptureActive and shouldRunDeferred("quick_hotkeys", quickHotkeyIntervalMs) then
                runtimeCall("QuickActionHotkeys.update", QuickActionHotkeys.update, chatActive, dialogActive)
                runtimeCall("ReportCatchManager.handleQuickHotkeys", ReportCatchManager.handleQuickHotkeys)
            end
            runtimeCall("TargetCircleOverlay.update", TargetCircleOverlay.update, chatActive, dialogActive)
        end
    end
end




















end

BOOT_LOGGER.write("Session bootstrap finished")
print("Nicks:", #AccessControl.authorizedNicks)
print("Proofs:", #AccessControl.nickProofs)